def transition_analysis_cached(path: str):
    """Return validated transition metadata without doing live decode work."""
    global _transition_analysis_cache_loaded, _transition_analysis_cache_loading
    if _transition_analysis_cache_loaded:
        # CPython dictionary reads are atomic. Do not take the persistence lock
        # on this playback/UI path: serializing a library-sized cache in the
        # analysis worker held it for 1–2 seconds during the 2026-08-27 show.
        return _transition_analysis_cache.get(str(path or ""))
    with _transition_analysis_cache_lock:
        if not _transition_analysis_cache_loaded:
            if not _transition_analysis_cache_loading:
                _transition_analysis_cache_loading = True

                def _load_transition_cache():
                    global _transition_analysis_cache_loaded, _transition_analysis_cache_loading
                    with _transition_analysis_cache_lock:
                        try:
                            _transition_analysis_cache.load()
                        except Exception as exc:
                            _diag(f"[TRANSITION] cache load failed; safe fallback active: {exc}")
                        finally:
                            _transition_analysis_cache_loaded = True
                            _transition_analysis_cache_loading = False

                threading.Thread(
                    target=_load_transition_cache, daemon=True,
                    name="transition-cache-load",
                ).start()
            # Never parse a library-sized JSON file on the playback/UI path.
            return None
        return _transition_analysis_cache.get(str(path or ""))


def _transition_analysis_cached_sync(path: str):
    """Worker-thread cache read used by enumeration/backfill, never the UI."""
    global _transition_analysis_cache_loaded, _transition_analysis_cache_loading
    with _transition_analysis_cache_lock:
        if not _transition_analysis_cache_loaded:
            _transition_analysis_cache.load()
            _transition_analysis_cache_loaded = True
            _transition_analysis_cache_loading = False
        return _transition_analysis_cache.get(str(path or ""))


def _transition_analysis_store(
    record, *, force: bool = False, persist: bool = True,
    checkpoint: bool = False,
) -> bool:
    """Incrementally persist one valid result without touching loudness.json."""
    global _transition_analysis_cache_loaded, _transition_analysis_cache_loading
    global _transition_analysis_last_save_ts
    try:
        with _transition_analysis_cache_lock:
            if not _transition_analysis_cache_loaded:
                _transition_analysis_cache.load()
                _transition_analysis_cache_loaded = True
                _transition_analysis_cache_loading = False
            _transition_analysis_cache.put(record)
            if checkpoint:
                _transition_analysis_cache.append_checkpoint(record)
            now = time.monotonic()
            if persist and (force or (now - _transition_analysis_last_save_ts) >= _TRANSITION_ANALYSIS_SAVE_INTERVAL_S):
                _transition_analysis_cache.save()
                _transition_analysis_last_save_ts = now
        return True
    except Exception as exc:
        _diag(f"[TRANSITION] cache write failed file={getattr(record, 'path', '')!r}: {exc}")
        return False


def _loudness_workers_allowed() -> bool:
    return not _loudness_cancel_event.is_set()


def set_loudness_workers_enabled(enabled: bool, reason: str = ""):
    if enabled:
        if _loudness_cancel_event.is_set():
            _diag(f"[LOUDNESS] workers enabled reason={reason or 'unknown'}")
        _loudness_cancel_event.clear()
    else:
        if not _loudness_cancel_event.is_set():
            _diag(f"[LOUDNESS] workers disabled reason={reason or 'unknown'}")
        _loudness_cancel_event.set()


def _loudness_lower_priority(pid: int):
    """Renice the analysis subprocess from the parent so the OS scheduler favors
    playback threads.  Done after spawn (not via preexec_fn) because preexec_fn
    is unsafe in a multithreaded program.  Best-effort; ignored if unsupported."""
    try:
        os.setpriority(os.PRIO_PROCESS, pid, 12)
    except Exception:
        pass


def _loudness_load_cache():
    global _loudness_cache_loaded
    if _loudness_cache_loaded:
        return
    with _loudness_lock:
        if _loudness_cache_loaded:
            return
        try:
            if LOUDNESS_CACHE_PATH.exists():
                data = json.loads(LOUDNESS_CACHE_PATH.read_text(encoding="utf-8") or "{}")
                if isinstance(data, dict):
                    _loudness_cache.update(data)
            # Batch scans append one compact record per completed item instead
            # of repeatedly encoding the growing library dictionary. A partial
            # final compaction is replayed too, making app/process crashes
            # resumable without a multi-megabyte rewrite every ten seconds.
            for checkpoint in (
                LOUDNESS_CHECKPOINT_PATH.with_suffix(".jsonl.flushing"),
                LOUDNESS_CHECKPOINT_PATH,
            ):
                if not checkpoint.exists():
                    continue
                for line in checkpoint.read_text(encoding="utf-8").splitlines():
                    try:
                        row = json.loads(line)
                        path = str(row["path"])
                        entry = row["entry"]
                        if path and isinstance(entry, dict):
                            _loudness_cache[path] = entry
                    except (KeyError, TypeError, ValueError):
                        continue
        except Exception:
            pass
        _loudness_cache_loaded = True


_LOUDNESS_SAVE_INTERVAL_S = 10.0
_loudness_last_save_ts = 0.0


def _loudness_append_checkpoint(path: str, entry: dict) -> None:
    """Durably stage one batch result in O(1) work."""
    try:
        line = json.dumps(
            {"path": str(path), "entry": dict(entry)}, separators=(",", ":")
        ) + "\n"
        with _loudness_lock:
            with LOUDNESS_CHECKPOINT_PATH.open("a", encoding="utf-8") as handle:
                handle.write(line)
                handle.flush()
    except Exception as exc:
        _diag(f"[LOUDNESS-LIB] checkpoint failed file={path!r}: {exc}")


def _loudness_save_cache(force: bool = True):
    """Persist the loudness cache to disk.

    The dict is snapshotted under _loudness_lock but serialized and written
    OUTSIDE it: the cache grows to library size, and json.dumps + the disk
    write while holding the lock stalled GUI-thread lock users for seconds
    during Analyze Library passes. With force=False the write is debounced to
    one per _LOUDNESS_SAVE_INTERVAL_S; bulk analysis must call once more with
    force=True when it finishes. Callers must NOT hold _loudness_lock.
    """
    global _loudness_last_save_ts
    flushing = LOUDNESS_CHECKPOINT_PATH.with_suffix(".jsonl.flushing")
    with _loudness_lock:
        if not force and (time.monotonic() - _loudness_last_save_ts) < _LOUDNESS_SAVE_INTERVAL_S:
            return
        snapshot = dict(_loudness_cache)
        _loudness_last_save_ts = time.monotonic()
        if force and LOUDNESS_CHECKPOINT_PATH.exists():
            try:
                os.replace(LOUDNESS_CHECKPOINT_PATH, flushing)
            except OSError:
                pass
    try:
        tmp = LOUDNESS_CACHE_PATH.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(snapshot), encoding="utf-8")
        os.replace(tmp, LOUDNESS_CACHE_PATH)
        if force:
            try:
                flushing.unlink()
            except OSError:
                pass
    except Exception:
        pass


def _loudness_file_sig(path: str):
    try:
        st = os.stat(path)
        return int(st.st_mtime), int(st.st_size)
    except Exception:
        return None


def _loudness_gain_from_lufs(integrated_lufs: float, peak_db: float | None = None) -> float:
    try:
        gain = LOUDNESS_TARGET_LUFS - float(integrated_lufs)
    except Exception:
        return 0.0
    gain = max(LOUDNESS_MIN_GAIN_DB, min(LOUDNESS_MAX_GAIN_DB, gain))
    if peak_db is not None:
        try:
            # Conservative peak guard: after applying gain, the measured sample
            # peak should stay below -1 dBFS.  This is static per-track gain,
            # not a compressor, so it avoids clipping without pumping.
            gain = min(gain, -LOUDNESS_TRUE_PEAK_HEADROOM_DB - float(peak_db))
        except Exception:
            pass
    return max(LOUDNESS_MIN_GAIN_DB, min(LOUDNESS_MAX_GAIN_DB, gain))


def _loudness_mark_failed(audio_path: str, reason: str = ""):
    """Remember that a file cannot be analysed, so passes stop retrying it.

    40 files in one library decode to nothing at all ("libmpv ebur128 produced
    no integrated loudness; PCM fallback failed"), and 11 SKK006 ZIPs have no
    readable MP3 inside. Only successes were ever cached, so every scan paid
    for them again -- on a job that already takes many hours. Keyed on the same
    mtime/size signature as a success, so repairing the file retries it.
    """
    sig = _loudness_file_sig(audio_path)
    if sig is None:
        return
    entry = {
            "failed": True,
            "failure_version": _LOUDNESS_FAILURE_CACHE_VERSION,
            "reason": str(reason or "")[:200],
            "mtime": sig[0],
            "size": sig[1],
            "at": int(time.time()),
        }
    with _loudness_lock:
        _loudness_cache[audio_path] = entry
    _loudness_append_checkpoint(audio_path, entry)


def loudness_failed_cached(audio_path: str) -> bool:
    """True when this exact file has already failed analysis."""
    _loudness_load_cache()
    if not audio_path:
        return False
    entry = _loudness_cache.get(audio_path)
    if not isinstance(entry, dict) or not entry.get("failed"):
        return False
    sig = _loudness_file_sig(audio_path)
    if sig is None:
        return False
    # A changed file is a different file: let it be retried.
    if int(entry.get("mtime", 0)) != sig[0] or int(entry.get("size", 0)) != sig[1]:
        return False
    # The 2026-08-29 resource-exhaustion run wrote ambiguous failures as the
    # generic "no measurable loudness" result or a Turbo helper timeout. Those
    # legacy records (including version 2 from the buffered-pipe bug) cannot be distinguished from
    # a real decode failure. Retry each once; a genuine failure is immediately
    # re-recorded at the current version, while a valid file overwrites it with
    # LUFS data. Specific structural failures remain cached below.
    if (
        int(entry.get("failure_version", 0)) < _LOUDNESS_FAILURE_CACHE_VERSION
        and (
            str(entry.get("reason") or "") == "no measurable loudness"
            or str(entry.get("reason") or "").startswith("Turbo helper failed:")
        )
    ):
        return False
    # A resource failure during the 2026-08-29 Turbo run was flattened into
    # the same message as a structurally invalid ZIP and poisoned almost the
    # whole library's failure cache. Revalidate only that cheap structural
    # claim. A currently readable, single-MP3 archive must be retried; a true
    # no/multiple-MP3 package remains skipped.
    if (
        str(audio_path).lower().endswith(".zip")
        and str(entry.get("reason") or "") == "ZIP does not contain exactly one readable MP3"
    ):
        try:
            with zipfile.ZipFile(audio_path, "r") as archive:
                members = [
                    info for info in archive.infolist()
                    if not info.is_dir() and info.filename.lower().endswith(".mp3")
                ]
            if len(members) == 1:
                return False
        except Exception:
            pass
    return True


def loudness_info_cached(audio_path: str):
    """Return cached loudness diagnostics for an audio file, or None."""
    _loudness_load_cache()
    if not audio_path:
        return None
    entry = _loudness_cache.get(audio_path)
    if not isinstance(entry, dict):
        return None
    sig = _loudness_file_sig(audio_path)
    if sig is not None and (int(entry.get("mtime", 0)) != sig[0] or int(entry.get("size", 0)) != sig[1]):
        return None
    try:
        lufs = float(entry["i"])
    except Exception:
        return None
    peak_db = None
    try:
        if entry.get("peak_db") is not None:
            peak_db = float(entry.get("peak_db"))
    except Exception:
        peak_db = None
    mode = "fast" if entry.get("mode") == "fast" else "full"
    gain_db = _loudness_gain_from_lufs(lufs, peak_db)
    if mode == "fast":
        gain_db = min(0.0, gain_db)
    return {
        "lufs": lufs,
        "peak_db": peak_db,
        "gain_db": gain_db,
        "gain_linear": 10.0 ** (float(gain_db) / 20.0),
        "mode": mode,
    }


def loudness_gain_db_cached(audio_path: str):
    """Return the cached normalization gain (dB) for an audio file, or None if
    not yet analyzed / the file changed."""
    _loudness_load_cache()
    if not audio_path:
        return None
    entry = _loudness_cache.get(audio_path)
    if not isinstance(entry, dict):
        return None
    sig = _loudness_file_sig(audio_path)
    if sig is not None and (int(entry.get("mtime", 0)) != sig[0] or int(entry.get("size", 0)) != sig[1]):
        return None
    try:
        peak_db = entry.get("peak_db")
        peak = float(peak_db) if peak_db is not None else None
        gain = _loudness_gain_from_lufs(float(entry["i"]), peak)
        # A representative sample cannot prove that a positive boost is safe
        # across the unmeasured parts of the song.
        return min(0.0, gain) if entry.get("mode") == "fast" else gain
    except Exception:
        return None


def _measure_loudness_lufs(audio_path: str, cancel_check=None, mode: str = "full",
                           session=None):
    """Measure integrated loudness (LUFS) and sample peak via bundled libmpv.

    Returns (integrated_lufs, max_peak_db) or (None, None).  The measured peak
    is cached and used only to cap static gain; no live compressor/limiter is added.

    Pass a LoudnessSession when measuring many files in a row: a fresh mpv core
    per track leaks ~1.5 MB that is never returned, which is what grew the app
    past 8 GB during a library scan.  A failing session falls back to the plain
    one-shot path so an older libmpv without ebur128 still works.
    """
    if cancel_check is not None:
        try:
            if cancel_check():
                return None, None
        except Exception:
            pass
    try:
        from libmpv_media_jobs import AnalysisHelperError, AnalysisTrackError, measure_loudness_fast_lufs, measure_loudness_lufs
        result = None
        if session is not None and getattr(session, "usable", False):
            try:
                result = (session.measure_fast(audio_path, timeout=120.0)
                          if mode == "fast" else
                          session.measure(audio_path, timeout=120.0))
            except AnalysisTrackError:
                raise
            except Exception as exc:
                if bool(getattr(session, "isolated", False)):
                    raise AnalysisHelperError(str(exc)) from exc
                result = None
        if result is None and bool(getattr(session, "isolated", False)):
            # Never fall back to constructing a one-shot libmpv core inside
            # the live show process. Those cores retain native allocations
            # after destroy; the isolated helper is the memory boundary.
            raise AnalysisHelperError("isolated analysis helper unavailable")
        if result is None:
            if mode == "fast":
                # Five sections avoid basing the estimate on one unusually quiet
                # intro/verse while still decoding only one minute in total.
                result = measure_loudness_fast_lufs(audio_path, timeout=120.0)
            else:
                result = measure_loudness_lufs(audio_path, timeout=120.0)
    except (AnalysisHelperError, AnalysisTrackError):
        raise
    except Exception as exc:
        _diag(
            f"[LOUDNESS] analysis failed file={os.path.basename(str(audio_path))!r} "
            f"reason={exc}"
        )
        return None, None
    if cancel_check is not None:
        try:
            if cancel_check():
                return None, None
        except Exception:
            pass
    if not result or result[0] is None:
        return None, None
    return float(result[0]), None if result[1] is None else float(result[1])


def analyze_loudness_async(audio_path: str):
    """Measure + cache loudness for a file in the background if not already done."""
    if not audio_path:
        return
    if str(audio_path).lower().startswith((
        "karafun_streaming:", "external_karafun:", "karafun_local:"
    )):
        _diag(f"[LOUDNESS] analysis skipped reason=external_provider file={audio_path!r}")
        return
    if str(audio_path).lower().endswith(".zip"):
        # libmpv cannot select the MP3 member inside an MP3+G archive. The
        # next-up prescan extracts it and queues the resolved MP3 instead.
        _diag(
            f"[LOUDNESS] analysis skipped reason=archive_requires_extraction "
            f"file={os.path.basename(str(audio_path))}"
        )
        return
    if not _loudness_workers_allowed():
        try:
            _diag(f"[LOUDNESS] analysis skipped reason=workers_disabled file={os.path.basename(audio_path)}")
        except Exception:
            pass
        return
    _loudness_load_cache()
    if loudness_gain_db_cached(audio_path) is not None:
        try:
            _diag(f"[LOUDNESS] analysis skipped reason=cache_hit file={os.path.basename(audio_path)}")
        except Exception:
            pass
        return
    with _loudness_lock:
        if audio_path in _loudness_inflight:
            try:
                _diag(f"[LOUDNESS] analysis skipped reason=inflight file={os.path.basename(audio_path)}")
            except Exception:
                pass
            return
        _loudness_inflight.add(audio_path)

    def _work():
        try:
            if not _loudness_workers_allowed():
                return
            sig = _loudness_file_sig(audio_path)
            with _loudness_sem:
                lufs, peak_db = _measure_loudness_lufs(audio_path, cancel_check=lambda: not _loudness_workers_allowed())
            if not _loudness_workers_allowed():
                try:
                    _diag(f"[LOUDNESS] analysis cancelled before cache write file={os.path.basename(audio_path)}")
                except Exception:
                    pass
                return
            if lufs is None and sig is not None and _loudness_workers_allowed():
                # Remember it so later passes skip this file instead of paying
                # for the same failed decode again.
                _loudness_mark_failed(audio_path, "no measurable loudness")
            if lufs is not None and sig is not None:
                with _loudness_lock:
                    _loudness_cache[audio_path] = {
                        "i": lufs, "peak_db": peak_db, "mtime": sig[0], "size": sig[1],
                    }
                _loudness_save_cache()
                try:
                    _diag(f"[LOUDNESS] {os.path.basename(audio_path)} I={lufs:.1f} LUFS "
                          f"peak={peak_db if peak_db is not None else 'n/a'}dB "
                          f"gain={_loudness_gain_from_lufs(lufs, peak_db):+.1f}dB")
                except Exception:
                    pass
        finally:
            with _loudness_lock:
                _loudness_inflight.discard(audio_path)

    threading.Thread(target=_work, daemon=True).start()


_LOG_SECRET_PATTERNS = [
    (re.compile(r"(?i)(api[_-]?key|x-api-key|token|password|passwd|secret|pin)(\s*[:=]\s*)([^\s,'\"&]+)"), r"\1\2***"),
    (re.compile(r"(?i)(token=)([^&\s]+)"), r"\1***"),
    (re.compile(r"(?i)(key=)([^&\s]+)"), r"\1***"),
    (re.compile(r"(?i)(Authorization:\s*Bearer\s+)([^\s]+)"), r"\1***"),
]


def _sanitize_log_text(text: str) -> str:
    """Redact credentials from diagnostic logs before packaging/emailing."""
    out = str(text or "")
    for pattern, repl in _LOG_SECRET_PATTERNS:
        try:
            out = pattern.sub(repl, out)
        except Exception:
            pass
    return out


def _recent_log_files(days: int = 3, *, now: float | None = None) -> list[Path]:
    try:
        days = max(1, min(30, int(days)))
    except Exception:
        days = 3
    cutoff = float(now if now is not None else time.time()) - (days * 86400)
    out = []
    try:
        for path in LOGS_DIR.glob("*"):
            if not path.is_file():
                continue
            if path.suffix.lower() not in {".log", ".txt"}:
                continue
            try:
                if path.stat().st_mtime >= cutoff:
                    out.append(path)
            except Exception:
                pass
    except Exception:
        pass
    return sorted(out, key=lambda p: p.name)


def prepare_log_email_package(days: int = 3, *, crash_log: str | Path | None = None) -> tuple[Path | None, list[Path], str]:
    """Create a sanitized ZIP of recent SingWS log/crash files only.

    Queue/history/settings JSON files are intentionally excluded so singer data
    and credentials are not sent as part of routine diagnostics.
    """
    import zipfile

    # Asynchronous log writes mean the most recent lines may still be queued;
    # a bundle that stops short of the problem is not worth sending.
    flush_log_queue()
    files = _recent_log_files(days)
    if crash_log:
        try:
            cp = Path(crash_log)
            if cp.exists() and cp.is_file() and cp not in files:
                files.append(cp)
        except Exception:
            pass
    files = sorted({Path(p) for p in files}, key=lambda p: p.name)
    if not files:
        return None, [], "No SingWS log files from the requested window."
    stamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
    package = LOGS_DIR / f"singws_logs_last_{int(days)}_days_{stamp}.zip"
    # Build under a temporary name and rename only on success.  Writing the ZIP
    # in place left a truncated, unopenable archive sitting next to the good
    # ones when packaging died partway on 2026-08-16 (a 712-byte file with no
    # end-of-central-directory record, indistinguishable from a real bundle
    # until you try to open it).
    building = package.with_suffix(".zip.partial")
    try:
        with zipfile.ZipFile(building, "w", compression=zipfile.ZIP_DEFLATED) as zf:
            for path in files:
                try:
                    raw = path.read_text(encoding="utf-8", errors="replace")
                    zf.writestr(path.name, _sanitize_log_text(raw))
                except Exception as exc:
                    zf.writestr(f"{path.name}.error.txt", f"Failed to read {path.name}: {exc}")
        os.replace(building, package)
        return package, files, ""
    except BaseException as exc:
        # BaseException so a MemoryError — the likely cause when this ran with
        # the app at 7.9 GB — also cleans up instead of orphaning the partial.
        try:
            building.unlink(missing_ok=True)
        except Exception:
            pass
        if isinstance(exc, Exception):
            return None, files, f"Failed to package logs: {exc}"
        raise


def _log_email_config_from_settings(settings: dict | None) -> dict:
    s = settings if isinstance(settings, dict) else {}
    try:
        port = int(s.get("log_smtp_port", 587) or 587)
    except Exception:
        port = 587
    return {
        "to": str(s.get("crash_log_email_to", "") or "").strip(),
        "host": str(s.get("log_smtp_host", "") or "").strip(),
        "port": port,
        "username": str(s.get("log_smtp_username", "") or "").strip(),
        "password": str(s.get("log_smtp_password", "") or ""),
        "from": str(s.get("log_smtp_from", "") or "").strip() or str(s.get("log_smtp_username", "") or "").strip(),
        "tls": bool(s.get("log_smtp_tls", True)),
    }


def _log_email_missing_config(config: dict) -> list[str]:
    required = ("to", "host", "username", "password", "from")
    return [key for key in required if not str(config.get(key, "") or "").strip()]


def send_log_package_via_smtp(settings: dict, package_path: Path, *, subject: str | None = None) -> tuple[bool, str]:
    import smtplib
    from email.message import EmailMessage

    config = _log_email_config_from_settings(settings)
    missing = _log_email_missing_config(config)
    if missing:
        return False, "Email is not configured. Fill in recipient, SMTP host, username, app password, and sender."
    if not package_path or not Path(package_path).exists():
        return False, "Log package was not created."
    try:
        msg = EmailMessage()
        msg["Subject"] = subject or f"SingWS logs {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        msg["From"] = config["from"]
        msg["To"] = config["to"]
        msg.set_content(
            "Attached is a sanitized SingWS diagnostic log bundle.\n\n"
            "The bundle contains recent app/crash logs only. API keys, tokens, passwords, and PIN-like values are redacted."
        )
        data = Path(package_path).read_bytes()
        msg.add_attachment(data, maintype="application", subtype="zip", filename=Path(package_path).name)
        with smtplib.SMTP(config["host"], int(config["port"]), timeout=20) as smtp:
            if config["tls"]:
                smtp.starttls()
            smtp.login(config["username"], config["password"])
            smtp.send_message(msg)
        logging.info(f"[LOG-EMAIL] sent package={Path(package_path).name} to={config['to']}")
        return True, f"Sent {Path(package_path).name} to {config['to']}."
    except Exception as exc:
        logging.error(f"[LOG-EMAIL] send failed package={Path(package_path).name}: {exc}")
        return False, f"Send failed: {exc}"


def send_recent_logs_email(settings: dict, days: int = 3, *, crash_log: str | Path | None = None) -> tuple[bool, str, Path | None]:
    package, files, package_error = prepare_log_email_package(days, crash_log=crash_log)
    if package_error:
        logging.warning(f"[LOG-EMAIL] package failed: {package_error}")
        return False, package_error, package
    logging.info(f"[LOG-EMAIL] packaged files={len(files)} package={package.name if package else ''}")
    ok, msg = send_log_package_via_smtp(settings, package, subject=f"SingWS last {int(days)} days of logs")
    return ok, msg, package


def maybe_auto_send_crash_logs(crash_log: str | Path | None):
    try:
        settings = {}
        if SETTINGS_PATH.exists():
            settings = json.loads(SETTINGS_PATH.read_text(encoding="utf-8") or "{}")
        if not isinstance(settings, dict) or not bool(settings.get("crash_auto_send_logs", False)):
            return
        def _work():
            # Without this guard a throw here (MemoryError, SMTP teardown, a
            # disk error) killed the daemon thread without a single log line,
            # which is why the 22:15:45 crash on 2026-08-16 has no [LOG-EMAIL]
            # record at all while the other three do.
            try:
                ok, msg, package = send_recent_logs_email(settings, 3, crash_log=crash_log)
                logging.info(f"[LOG-EMAIL] auto crash send ok={int(ok)} package={Path(package).name if package else ''} msg={msg}")
            except Exception as exc:
                logging.error(f"[LOG-EMAIL] auto crash send failed: {exc!r}")
        threading.Thread(target=_work, daemon=True, name="singws-crash-log-email").start()
    except Exception as exc:
        logging.error(f"[LOG-EMAIL] auto crash send setup failed: {exc}")

# --- Logging Setup ---
_LOG_QUEUE_LISTENER = None


def flush_log_queue(timeout_sec: float = 2.0) -> None:
    """Drain queued log records to disk.

    Log I/O runs on a listener thread so the GUI thread never blocks on a
    write.  Anything that may be the last code to run (crash handler, clean
    shutdown, log e-mail packaging) must drain first or the tail of the log —
    exactly the part worth reading — never reaches the file.
    """
    listener = _LOG_QUEUE_LISTENER
    if listener is None:
        return
    try:
        log_queue = listener.queue
        deadline = time.monotonic() + max(0.0, float(timeout_sec))
        while time.monotonic() < deadline:
            try:
                if log_queue.empty():
                    break
            except Exception:
                break
            time.sleep(0.01)
        for handler in getattr(listener, "handlers", ()) or ():
            try:
                handler.flush()
            except Exception:
                pass
    except Exception:
        pass


# The log queue used to be an unbounded queue.SimpleQueue. Logging is async so
# the GUI thread never blocks on a write, but unbounded means a burst -- a
# runaway retry loop, a scan logging per-track failures -- grows memory with no
# ceiling. ARCHITECTURE.md flagged it and the final audit kept it open as a
# release blocker. Bounded with an explicit drop policy instead: newest records
# are dropped when full, the count is kept, and the total is reported as soon as
# there is room, so a burst is visible in the log rather than silent.
_LOG_QUEUE_MAX = 10000


class _BoundedLogQueueHandler(logging.handlers.QueueHandler):
    def __init__(self, log_queue):
        super().__init__(log_queue)
        self.dropped = 0

    def enqueue(self, record):
        try:
            self.queue.put_nowait(record)
        except queue.Full:
            self.dropped += 1
            return
        if self.dropped:
            # There is room again: report the gap before anything else, so the
            # log says what it lost rather than quietly skipping it.
            dropped, self.dropped = self.dropped, 0
            try:
                self.queue.put_nowait(logging.LogRecord(
                    name="singws.logging", level=logging.WARNING, pathname=__file__,
                    lineno=0, msg="[LOG] dropped %d record(s): queue full (max %d)",
                    args=(dropped, _LOG_QUEUE_MAX), exc_info=None))
            except queue.Full:
                self.dropped += dropped


def setup_logging():
    """Setup comprehensive logging system"""
    # Create log filename with today's date
    log_filename = LOGS_DIR / f"singws_{datetime.now().strftime('%Y-%m-%d')}.log"

    # Create rotating file handler (keeps last 7 days)
    # Format: [HH:MM:SS] [LEVEL] message
    formatter = logging.Formatter(
        '[%(asctime)s] [%(levelname)s] %(message)s',
        datefmt='%H:%M:%S'
    )

    # Also log to console for development
    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)

    # Setup root logger
    logger = logging.getLogger()
    logger.setLevel(logging.INFO)

    # Sinks hang off a QueueListener thread rather than the root logger, so a
    # burst of diagnostics (relay reconcile logs one line per request row)
    # costs the GUI thread an enqueue instead of a file write plus a console
    # write per line.  The queue handler carries both marker attributes so the
    # idempotency guards below still see an installed file/console sink.
    global _LOG_QUEUE_LISTENER
    sinks = []
    if not any(bool(getattr(h, "_singws_file_handler", False)) for h in logger.handlers):
        try:
            file_handler = logging.handlers.TimedRotatingFileHandler(
                filename=str(log_filename),
                when='midnight',
                interval=1,
                backupCount=7,
                encoding='utf-8'
            )
            file_handler.setFormatter(formatter)
            file_handler._singws_file_handler = True
            sinks.append(file_handler)
        except Exception as e:
            print(f"SingWS log file unavailable ({log_filename}): {e}")
    if not any(bool(getattr(h, "_singws_console_handler", False)) for h in logger.handlers):
        console_handler._singws_console_handler = True
        sinks.append(console_handler)

    if sinks:
        try:
            log_queue = queue.Queue(maxsize=_LOG_QUEUE_MAX)
            queue_handler = _BoundedLogQueueHandler(log_queue)
            queue_handler._singws_queue_handler = True
            queue_handler._singws_file_handler = any(
                bool(getattr(h, "_singws_file_handler", False)) for h in sinks
            )
            queue_handler._singws_console_handler = any(
                bool(getattr(h, "_singws_console_handler", False)) for h in sinks
            )
            listener = logging.handlers.QueueListener(log_queue, *sinks, respect_handler_level=True)
            listener.start()
            _LOG_QUEUE_LISTENER = listener
            atexit.register(flush_log_queue)
            atexit.register(listener.stop)
            logger.addHandler(queue_handler)
        except Exception as e:
            # Never lose logging because the async path failed: fall back to
            # the original synchronous handlers.
            print(f"SingWS async logging unavailable, using direct handlers: {e}")
            _LOG_QUEUE_LISTENER = None
            for handler in sinks:
                if bool(getattr(handler, "_singws_file_handler", False)):
                    logger.addHandler(file_handler)
                else:
                    logger.addHandler(console_handler)

    return logger

# Initialize logging
logger = setup_logging()

_MAC_LOCATION_DELEGATE_CLASS = None
_DIAG_RATE_LIMIT_LAST = {}

def _diag(msg: str):
    """Write diagnostic messages to both terminal and SingWS log."""
    try:
        print(msg)
    except Exception:
        pass
    try:
        logging.info(msg)
    except Exception:
        pass

def _diag_rate_limited(key: str, msg: str, interval_sec: float = 60.0):
    """Log routine diagnostics at most once per key/interval."""
    try:
        now = time.monotonic()
        key = str(key or msg)
        last = float(_DIAG_RATE_LIMIT_LAST.get(key, 0.0) or 0.0)
        if now - last < max(0.0, float(interval_sec)):
            return False
        _DIAG_RATE_LIMIT_LAST[key] = now
        if len(_DIAG_RATE_LIMIT_LAST) > 4096:
            cutoff = now - 3600.0
            for stale_key, stale_at in list(_DIAG_RATE_LIMIT_LAST.items()):
                if float(stale_at or 0.0) < cutoff:
                    _DIAG_RATE_LIMIT_LAST.pop(stale_key, None)
        _diag(msg)
        return True
    except Exception:
        _diag(msg)
        return True

def _bounded_filesystem_call(call, *, default=None, timeout_sec: float = 0.45, label: str = "path probe"):
    """Run a potentially blocking File Provider lookup outside the GUI thread.

    macOS can leave ``stat``/``listdir`` waiting in LIFS for tens of seconds
    when an iCloud, third-party File Provider, or mounted location is offline.
    Python cannot cancel that kernel lookup, so the probe thread is a daemon;
    the caller gets a conservative result after a short bounded wait.
    """
    done = threading.Event()
    result = {"value": default}

    def worker():
        try:
            result["value"] = call()
        except Exception:
            result["value"] = default
        finally:
            done.set()

    threading.Thread(target=worker, daemon=True, name="singws-fs-probe").start()
    if not done.wait(max(0.01, float(timeout_sec))):
        _diag_rate_limited(
            f"fs_probe_timeout:{label}",
            f"[FILESYSTEM] timed out after {float(timeout_sec):.2f}s label={label}; treating path as unavailable",
            30.0,
        )
        return default
    return result.get("value", default)

def _bounded_path_exists(path, *, timeout_sec: float = 0.45, label: str = "exists") -> bool:
    value = str(path or "").strip()
    if not value:
        return False
    return bool(_bounded_filesystem_call(
        lambda: os.path.exists(value), default=False, timeout_sec=timeout_sec, label=label
    ))

def _network_log(msg: str):
    _diag(f"[NETWORK-SYNC] {msg}")

def _network_safe_body(resp, limit: int = 300) -> str:
    try:
        return str(getattr(resp, "text", "") or "")[:limit]
    except Exception:
        return ""

def _network_normalize_base_url(base_url: str) -> str:
    base = str(base_url or "").strip().rstrip("/")
    if base and "://" not in base:
        base = "https://" + base
    return base

def remote_request_song_key(singer: str = "", artist: str = "", title: str = "") -> str:
    """Stable loose key used only to prevent stale server requests resurrecting."""
    def norm(value: str) -> str:
        return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()
    parts = [norm(singer), norm(artist), norm(title)]
    return "|".join(parts)

def probe_network_sync_status(
    base_url: str,
    tenant: str,
    api_key: str = "",
    *,
    timeout_sec: float = 6.0,
    requests_module=None,
) -> dict:
    """Probe the request-server endpoints used by desktop sync/status.

    The live request intake endpoint is authoritative for "connected" because
    that is the path singers depend on. Other endpoints are reported as partial
    sync details so the UI can stop spinning and show the real failing piece.
    """
    req = requests_module or requests
    base = _network_normalize_base_url(base_url)
    user = str(tenant or "").strip()
    key = str(api_key or "").strip()
    timeout = max(1.0, float(timeout_sec or 6.0))
    headers = {
        "Accept": "application/json",
        "User-Agent": "SingWS/network-sync",
    }
    if key:
        headers["X-API-Key"] = key

    result = {
        "ok": False,
        "connected": False,
        "partial": False,
        "message": "",
        "base_url": base,
        "tenant": user,
        "accepting": None,
        "checks": {},
        "errors": [],
        "endpoints": {
            "request_intake": f"{base}/get_requests.php" if base else "",
            "accepting": f"{base}/tenants/{user}/accepting.txt" if base else "",
            "host_controls": f"{base}/api/v1/host_commands.php" if base else "",
            "singer_history": f"{base}/api/v1/singer_history_sync.php" if base else "",
            "rotation": f"{base}/post_rotation.php" if base else "",
            "queue_clear": f"{base}/api/v1/clear_remote_queue.php" if base else "",
            "queue_order": f"{base}/api/v1/set_remote_request_order.php" if base else "",
            "request_modifiers": f"{base}/api/v1/set_remote_request_modifiers.php" if base else "",
        },
    }

    def record(name: str, ok: bool, status=None, message: str = "", *, body: str = "", skipped: bool = False):
        check = {
            "ok": bool(ok),
            "status": status,
            "message": str(message or ""),
            "body": str(body or ""),
            "skipped": bool(skipped),
        }
        result["checks"][name] = check
        if skipped:
            _network_log(f"{name}: skipped {message}")
        elif ok:
            _network_log(f"{name}: ok status={status} {message}")
        else:
            detail = f"{name}: failed status={status} {message}".strip()
            if body:
                detail += f" body={body!r}"
            result["errors"].append(detail)
            _network_log(detail)
        return check

    if not base or not base.startswith(("http://", "https://")):
        record("config", False, message="Missing or invalid Base URL")
        result["message"] = "Missing or invalid Base URL"
        return result
    if not user:
        record("config", False, message="Missing User ID")
        result["message"] = "Missing User ID"
        return result

    host = ""
    try:
        from urllib.parse import urlparse
        host = (urlparse(base).hostname or "").lower()
    except Exception:
        host = ""
    if host == "wskar.com":
        _network_log("base_url host is wskar.com; beta deployments should use https://beta.wskar.com")
    _network_log(f"sync requested base_url={base} tenant={user} api_key={'set' if key else 'missing'} timeout={timeout:.1f}s")

    request_url = result["endpoints"]["request_intake"]
    try:
        _network_log(f"request sent name=request_intake method=GET url={request_url}")
        resp = req.get(
            request_url,
            params={"user": user, "sync": "1"},
            headers=headers,
            timeout=timeout,
        )
        body = _network_safe_body(resp)
        status = getattr(resp, "status_code", None)
        _network_log(f"response name=request_intake status={status}")
        if status == 200:
            try:
                resp.json()
                record("request_intake", True, status, "request intake reachable")
            except Exception as e:
                record("request_intake", False, status, f"invalid JSON: {e}", body=body)
        elif status in (401, 403):
            record("request_intake", False, status, "request intake rejected credentials", body=body)
        else:
            record("request_intake", False, status, "request intake failed", body=body)
    except requests.exceptions.Timeout as e:
        record("request_intake", False, message=f"timeout after {timeout:.1f}s: {e}")
    except requests.exceptions.ConnectionError as e:
        record("request_intake", False, message=f"connection error: {e}")
    except Exception as e:
        record("request_intake", False, message=f"{type(e).__name__}: {e}")

    accepting_url = result["endpoints"]["accepting"]
    try:
        _network_log(f"request sent name=accepting method=GET url={accepting_url}")
        resp = req.get(accepting_url, params={"_": int(time.time())}, timeout=min(timeout, 5.0))
        body = _network_safe_body(resp)
        status = getattr(resp, "status_code", None)
        _network_log(f"response name=accepting status={status}")
        if status == 200:
            txt = body.strip()
            if txt in ("0", "1"):
                result["accepting"] = (txt == "1")
                record("accepting", True, status, f"accepting={txt}")
            else:
                record("accepting", False, status, "unexpected accepting.txt body", body=body)
        else:
            record("accepting", False, status, "accepting state unavailable", body=body)
    except requests.exceptions.Timeout as e:
        record("accepting", False, message=f"timeout after {min(timeout, 5.0):.1f}s: {e}")
    except Exception as e:
        record("accepting", False, message=f"{type(e).__name__}: {e}")

    if key:
        host_url = result["endpoints"]["host_controls"]
        try:
            _network_log(f"request sent name=host_controls method=GET url={host_url}")
            resp = req.get(
                host_url,
                params={"user": user, "action": "poll"},
                headers=headers,
                timeout=min(timeout, 4.0),
            )
            status = getattr(resp, "status_code", None)
            body = _network_safe_body(resp)
            _network_log(f"response name=host_controls status={status}")
            record("host_controls", status == 200, status, "host controls poll", body="" if status == 200 else body)
        except requests.exceptions.Timeout as e:
            record("host_controls", False, message=f"timeout after {min(timeout, 4.0):.1f}s: {e}")
        except Exception as e:
            record("host_controls", False, message=f"{type(e).__name__}: {e}")
    else:
        record("host_controls", True, message="API key not configured", skipped=True)

    # Read-only reachability probes. 400/405 still prove the endpoint exists but
    # does not support GET, which is enough for a sync status check.
    for name, url in (
        ("singer_history", result["endpoints"]["singer_history"]),
        ("rotation", result["endpoints"]["rotation"]),
    ):
        try:
            _network_log(f"request sent name={name} method=GET url={url}")
            resp = req.get(url, params={"user": user, "_probe": "1"}, headers=headers, timeout=min(timeout, 4.0))
            status = getattr(resp, "status_code", None)
            body = _network_safe_body(resp)
            _network_log(f"response name={name} status={status}")
            ok = status in (200, 400, 405)
            record(name, ok, status, "endpoint reachable" if ok else "endpoint unavailable", body="" if ok else body)
        except requests.exceptions.Timeout as e:
            record(name, False, message=f"timeout after {min(timeout, 4.0):.1f}s: {e}")
        except Exception as e:
            record(name, False, message=f"{type(e).__name__}: {e}")

    request_ok = bool(result["checks"].get("request_intake", {}).get("ok"))
    result["connected"] = request_ok
    result["ok"] = request_ok
    supporting_failures = [
        name for name, check in result["checks"].items()
        if name != "request_intake" and not check.get("ok") and not check.get("skipped")
    ]
    result["partial"] = bool(request_ok and supporting_failures)
    if request_ok and supporting_failures:
        result["message"] = "Connected; partial sync issue: " + ", ".join(supporting_failures)
    elif request_ok:
        result["message"] = "Connected / Synced"
    else:
        first = result["errors"][0] if result["errors"] else "Sync failed"
        result["message"] = first
    _network_log(f"final UI state ok={result['ok']} partial={result['partial']} message={result['message']}")
    return result

def _load_json_file(path: Path, default, *, expected_type=None, label: str = "JSON"):
    try:
        if not path.exists():
            return default
        with open(path, "r", encoding="utf-8") as f:
            value = json.load(f)
        if expected_type is not None and not isinstance(value, expected_type):
            print(f"{label} ignored: expected {expected_type.__name__} in {path}")
            return default
        return value
    except Exception as e:
        print(f"{label} ignored: could not load {path}: {e}")
        return default

# Digest of the payload last written to each path, so an unchanged file is not
# rewritten. save_data() persists queue/history/preferences together on every
# call, but a queue edit leaves singer_history.json untouched -- and that file
# reaches 1.7MB, which is ~67ms of GUI-thread write for a byte-identical
# result. Serializing to compare costs ~14ms and is skipped entirely on a hit.
_JSON_WRITE_DIGESTS: dict[str, str] = {}


def _save_json_atomic(path: Path, value) -> None:
    _perf_t0 = time.perf_counter()
    path.parent.mkdir(parents=True, exist_ok=True)
    if path == TRACKS_PATH:
        # tracks.json grows to hundreds of thousands of rows when several
        # libraries are combined. Pretty-printing doubled its size and made
        # both UI-thread startup reads and post-scan writes needlessly
        # expensive.
        payload = json.dumps(value, separators=(",", ":")) + "\n"
    else:
        payload = json.dumps(value, indent=2) + "\n"
    key = str(path)
    digest = hashlib.sha1(payload.encode("utf-8")).hexdigest()
    if _JSON_WRITE_DIGESTS.get(key) == digest and path.exists():
        _perf_record(f"json_write_skipped:{path.name}", (time.perf_counter() - _perf_t0) * 1000.0)
        return
    fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(payload)
        os.replace(tmp_name, path)
        _JSON_WRITE_DIGESTS[key] = digest
        _perf_record(f"json_write:{path.name}", (time.perf_counter() - _perf_t0) * 1000.0)
    except Exception:
        _JSON_WRITE_DIGESTS.pop(key, None)
        try:
            os.unlink(tmp_name)
        except Exception:
            pass
        raise

class PerfStats:
    def __init__(self):
        self._lock = threading.Lock()
        self._stats = {}

    def record(self, name: str, ms: float):
        try:
            ms = float(ms)
        except Exception:
            return
        with self._lock:
            s = self._stats.setdefault(str(name), {"count": 0, "total": 0.0, "max": 0.0, "slow": 0})
            s["count"] += 1
            s["total"] += ms
            if ms > s["max"]:
                s["max"] = ms
            if ms >= _perf_threshold_ms(str(name)):
                s["slow"] += 1

    def snapshot(self):
        with self._lock:
            rows = []
            for name, s in self._stats.items():
                count = int(s.get("count", 0) or 0)
                if count <= 0:
                    continue
                total = float(s.get("total", 0.0) or 0.0)
                rows.append({
                    "name": name,
                    "count": count,
                    "avg": total / max(1, count),
                    "max": float(s.get("max", 0.0) or 0.0),
                    "slow": int(s.get("slow", 0) or 0),
                })
            return sorted(rows, key=lambda r: (r["max"], r["avg"]), reverse=True)

PERF_STATS = PerfStats()
_PERF_LAST_PRINT = {}

def _perf_threshold_ms(name: str) -> float:
    n = str(name or "").lower()
    if "audio" in n or "meter" in n:
        return 5.0
    if "ui_" in n or "frame" in n or "render" in n or "paint" in n or "tick" in n:
        return 16.0
    if "search" in n:
        return 50.0
    if "server" in n or "json" in n or "db" in n or "sync" in n or "save" in n:
        return 50.0
    return 50.0

def _perf_record(name: str, ms: float):
    try:
        PERF_STATS.record(name, ms)
    except Exception:
        pass

_IA_OBSERVER = transition_observer.TransitionObserver(transition_events.record)
_IA_SOUND = {"enabled": False, "monitor": None, "last_seq": 0}


def _ia_native_helper_path(name: str) -> Path:
    if getattr(sys, "frozen", False):
        for base in (getattr(sys, "_MEIPASS", None), Path(sys.executable).resolve().parent):
            if base and (Path(base) / name).is_file():
                return Path(base) / name
        return Path(getattr(sys, "_MEIPASS", Path(sys.executable).parent)) / name
    return Path(__file__).resolve().parent / "native" / "sound_helper" / name


def _ia_sound_helper_path() -> Path:
    return _ia_native_helper_path("SingWSSoundHelper")


def _ia_sound_monitor():
    """Lazily create the sound monitor; None when disabled. Never raises."""
    try:
        if not _IA_SOUND["enabled"]:
            return None
        if _IA_SOUND["monitor"] is None:
            import sound_monitor

            def _health(state, reason):
                transition_events.record("sound_health", state=str(state), reason=str(reason))
                if state == sound_monitor.STATE_BYPASSED:
                    _IA_OBSERVER.sound_unavailable(reason=str(reason))

            _IA_SOUND["monitor"] = sound_monitor.SoundMonitor(_ia_sound_helper_path(), on_health=_health)
        return _IA_SOUND["monitor"]
    except Exception:
        return None


_IA_MIC = {"monitor": None, "last_seq": 0, "last_reason": ""}


def _ia_mic_configure(settings: dict):
    """(Re)start the live-mic monitor from settings. Advisory evidence only. Never raises."""
    try:
        import mic_config
        import mic_monitor
        old = _IA_MIC["monitor"]
        _IA_MIC["monitor"], _IA_MIC["last_seq"], _IA_MIC["last_reason"] = None, 0, ""
        if old is not None:
            threading.Thread(target=old.shutdown, daemon=True, name="mic-monitor-stop").start()
        _IA_OBSERVER.set_mic_mode(str(settings.get("ia_mic_observer_mode", "singer_protection_host_ducking")))
        if not bool(settings.get("ia_mic_awareness_enabled", False)):
            _IA_OBSERVER.mic_unavailable(reason="disabled")
            return
        config = mic_config.MicInputConfig.from_settings(settings.get("ia_mic_config"))
        if config.problems():
            _IA_OBSERVER.mic_unavailable(reason="config:" + ",".join(config.problems()))
            return

        def _health(state, reason):
            transition_events.record("sound_health", source="mic", state=str(state), reason=str(reason))

        monitor = mic_monitor.MicMonitor(_ia_native_helper_path("SingWSMicMeter"), config, on_health=_health)
        _IA_MIC["monitor"] = monitor
        monitor.arm()   # launches on its own thread; levels only
    except Exception:
        pass


def _ia_mic_tick():
    """Feed the newest mic snapshot to the observer (once per report). O(1), never raises."""
    try:
        monitor = _IA_MIC["monitor"]
        if monitor is None:
            return
        snap = monitor.latest()
        if snap is None:
            reason = f"{monitor.state}:{monitor.reason}"
            if reason != _IA_MIC["last_reason"]:
                _IA_MIC["last_reason"] = reason
                _IA_OBSERVER.mic_unavailable(reason=reason)
            return
        _IA_MIC["last_reason"] = ""
        if int(snap.get("seq", 0)) > _IA_MIC["last_seq"]:
            _IA_MIC["last_seq"] = int(snap["seq"])
            _IA_OBSERVER.mic(roles=snap["roles"], t_mono=float(snap["t_mono"]))
    except Exception:
        pass


def _ia_sound_configure(enabled: bool):
    try:
        _IA_SOUND["enabled"] = bool(enabled)
        if not enabled and _IA_SOUND["monitor"] is not None:
            _IA_SOUND["monitor"].disarm()
            _IA_OBSERVER.sound_unavailable(reason="disabled")
    except Exception:
        pass


def _ia_observer_active() -> bool:
    return transition_events.recorder().enabled and _IA_OBSERVER.mode == transition_observer.MODE_OBSERVER


def _ia_observe(owner, what: str, **kwargs):
    """Feed the Phase 2 observer plain values. Never raises; never touches playback."""
    try:
        if not _ia_observer_active():
            return
        now = time.monotonic()
        generation = int(getattr(owner, "_ia_karaoke_generation", 0) or 0)
        if what == "start":
            record = None
            for candidate in (getattr(owner, "_current_karaoke_audio_path", ""), kwargs.get("video_path")):
                if candidate:
                    record = transition_analysis_cached(str(candidate))  # no decode; None while cache loads
                    if record is not None:
                        break
            _IA_OBSERVER.song_started(
                generation=generation,
                track=transition_events.track_id(getattr(owner, "_current_karaoke_audio_path", "")),
                cues=transition_cues.derive_cues(record), t_mono=now,
                playhead=float(kwargs.get("playhead", 0.0) or 0.0),
            )
        elif what == "position":
            playhead = float(kwargs["playhead"])
            monitor = _ia_sound_monitor()
            if monitor is not None:
                if _IA_OBSERVER.listening_window(generation=generation, playhead=playhead):
                    monitor.arm()   # launches the helper on its own thread
                    snap = monitor.latest()
                    if snap is not None and int(snap.get("seq", 0)) > _IA_SOUND["last_seq"]:
                        _IA_SOUND["last_seq"] = int(snap["seq"])   # each window counts once
                        _IA_OBSERVER.sound(generation=generation, result=snap["result"],
                                           confidence=snap["confidence"], t_mono=snap["t_mono"],
                                           model=snap.get("model", ""))
                else:
                    monitor.disarm()
            _IA_OBSERVER.position(generation=generation, playhead=playhead, t_mono=now)
        elif what == "seek":
            monitor = _ia_sound_monitor()
            if monitor is not None:
                monitor.disarm()
            _IA_OBSERVER.seeked(generation=generation, playhead=float(kwargs["playhead"]), t_mono=now)
        elif what == "bgm":
            _IA_OBSERVER.bgm_started(t_mono=now)
        elif what == "tick":
            _ia_mic_tick()
        elif what == "end":
            monitor = _ia_sound_monitor()
            if monitor is not None:
                monitor.disarm()
            _IA_OBSERVER.song_ended(generation=generation, trigger=str(kwargs.get("trigger", "eos")), t_mono=now)
    except Exception:
        pass


def _ia_record(owner, kind: str, playhead_s=None, **data):
    """Passive Phase 0 transition event. O(1), never raises, no-op when disabled.

    A module function rather than a KaraokeApp method so code paths exercised
    with lightweight test hosts (or any object) can never fail on a missing
    attribute because of instrumentation.
    """
    try:
        rec = transition_events.recorder()
        if not rec.enabled:
            return
        rec.record(
            kind,
            generation=int(getattr(owner, "_ia_karaoke_generation", 0) or 0),
            track=transition_events.track_id(getattr(owner, "_current_karaoke_audio_path", "")),
            media=getattr(owner, "_ia_media", None),
            playhead_s=playhead_s,
            **data,
        )
    except Exception:
        pass


def _perf_log_if_slow(name: str, ms: float):
    try:
        _perf_record(name, ms)
        if float(ms) >= _perf_threshold_ms(name):
            if name == "ui_update_time_left":
                transition_events.record("gui_stall", name=str(name), ms=float(ms))
            now = time.monotonic()
            key = str(name)
            last = float(_PERF_LAST_PRINT.get(key, 0.0) or 0.0)
            low_key = key.lower()
            repeat_sec = 15.0 if any(token in low_key for token in ("server", "sync", "json", "save", "db")) else 1.0
            if now - last < repeat_sec:
                return
            _PERF_LAST_PRINT[key] = now
            # _diag, not print: in the packaged .app stdout goes nowhere, so
            # these measurements never reached ~/SingWS/logs and the slow paths
            # they were added to catch stayed invisible.
            _diag(f"[PERF-DIAG] {name} took {float(ms):.0f}ms")
    except Exception:
        pass


def _fit_dialog_to_screen(dlg, *, preferred=(760, 640), minimum=(520, 360), margin=80):
    """Size a dialog to its preferred size, but never larger than the screen.

    The old code did `min(760, max(680, avail.width() - 120))` with a hard
    setMinimumWidth(680), so on a laptop screen the dialog could not shrink
    below 680x480 no matter how little room there was -- controls ended up
    clipped or pushed off the bottom. Preferred size is a ceiling here, not a
    floor: on a small display the dialog gets what actually fits, and its
    scroll areas take over.
    """
    try:
        from PyQt6.QtGui import QCursor

        screen = QApplication.screenAt(QCursor.pos()) or QApplication.primaryScreen()
        avail = screen.availableGeometry() if screen is not None else None
        if avail is None:
            dlg.resize(*preferred)
            return
        width = max(min(preferred[0], avail.width() - margin), min(minimum[0], avail.width()))
        height = max(min(preferred[1], avail.height() - margin), min(minimum[1], avail.height()))
        dlg.setMinimumSize(min(minimum[0], width), min(minimum[1], height))
        dlg.resize(int(width), int(height))
    except Exception:
        try:
            dlg.resize(*preferred)
        except Exception:
            pass


def _describe_window_topology() -> str:
    """Compact description of every top-level window and the screens they sit on.

    GUI THREAD ONLY -- QWidget/QScreen access is not thread safe.

    Exists because of a SIGSEGV inside QBackingStore::flush() on 2026-07-30:
    QPaintDevice::devicePixelRatio() dereferenced null while flushing a repaint,
    which means a widget was flushing to a window Qt no longer considered valid.
    The Qt-internal stack says nothing about WHICH window, so record the state
    the watchdog can print when it next detects a stall.
    """
    try:
        from PyQt6.QtGui import QGuiApplication

        parts = []
        try:
            screens = QGuiApplication.screens() or []
            parts.append("screens=" + ",".join(
                f"{s.name()}@{s.devicePixelRatio():.1f}"
                f"[{s.geometry().width()}x{s.geometry().height()}]"
                for s in screens
            ))
        except Exception:
            parts.append("screens=?")
        app = QApplication.instance()
        for w in list(app.topLevelWidgets() if app is not None else []):
            try:
                if not w.isVisible():
                    continue
                name = w.objectName() or w.__class__.__name__
                handle = w.windowHandle()
                scr = handle.screen().name() if (handle is not None and handle.screen() is not None) else "none"
                # A visible window with no handle, or a handle with no screen,
                # is precisely the state that makes flush() dereference null.
                parts.append(
                    f"{name}(handle={'y' if handle is not None else 'NONE'},"
                    f"screen={scr},dpr={w.devicePixelRatio():.1f})"
                )
            except Exception:
                continue
        return " ".join(parts)
    except Exception:
        return ""


class _StallAttributionDisabled(Exception):
    """Control-flow marker: skip installing the app-wide attribution filter."""


def _install_main_thread_watchdog(owner, threshold_ms: int = 120):
    """Log the GUI-thread stack when the event loop stalls.

    Observation only: a tiny GUI heartbeat timer plus a daemon watcher thread.
    It follows the existing runtime diagnostic setting and can be disabled with
    SINGWS_NO_WATCHDOG=1.
    """
    try:
        if os.environ.get("SINGWS_NO_WATCHDOG"):
            return
        if getattr(owner, "_mt_watch_thread", None) is not None:
            return
        try:
            if not bool(getattr(owner, "settings", {}).get("performance_debug_enabled", False)):
                return
        except Exception:
            return
        import traceback as _traceback

        main_ident = threading.main_thread().ident
        owner._mt_hb = time.monotonic()
        owner._mt_watch_stop = False

        def _heartbeat():
            owner._mt_hb = time.monotonic()
            # Snapshot the window/screen topology here, on the GUI thread. The
            # watchdog runs on a worker and must never touch Qt, but a crash in
            # QBackingStore::flush (a null window during a repaint, 2026-07-30)
            # is exactly the kind of fault where that state is the evidence.
            # Throttled: the heartbeat itself is 50ms.
            try:
                now = time.monotonic()
                if (now - float(getattr(owner, "_topology_ts", 0.0) or 0.0)) >= 2.0:
                    owner._topology_ts = now
                    owner._window_topology = _describe_window_topology()
            except Exception:
                pass

        hb_timer = QTimer(owner)
        hb_timer.timeout.connect(_heartbeat)
        hb_timer.start(50)
        owner._mt_hb_timer = hb_timer

        threshold = max(0.05, float(threshold_ms) / 1000.0)

        # Attribute stalls that land inside Qt's C++ (paint/layout/style), where
        # the Python stack is only app.exec() and names nothing. A filter for
        # this already lived on the tooltip gate, but across the whole
        # 2026-08-08 show not one [STALL] line carried a last_event= -- it never
        # recorded anything, and its install failure was swallowed by a bare
        # except. Own it here, keep a strong reference so PyQt cannot collect
        # the filter, and say out loud whether it is live.
        try:
            if not bool(getattr(owner, "settings", {}).get("stall_event_attribution", False)):
                # Default path: no application-wide filter, so ordinary events
                # never cross into Python. [STALL] still reports the GUI-thread
                # stack, which names the culprit whenever it is Python code.
                raise _StallAttributionDisabled

            from PyQt6.QtCore import QEvent as _StallEvent

            class _StallAttribution(QObject):
                _COSTLY = frozenset(int(t) for t in (
                    _StallEvent.Type.Paint,
                    _StallEvent.Type.UpdateRequest,
                    _StallEvent.Type.LayoutRequest,
                    _StallEvent.Type.Resize,
                    _StallEvent.Type.Show,
                    _StallEvent.Type.Polish,
                    _StallEvent.Type.StyleChange,
                    _StallEvent.Type.FontChange,
                    _StallEvent.Type.Timer,
                    _StallEvent.Type.DeferredDelete,
                ))

                def __init__(self, target):
                    super().__init__(target)
                    self._target = target
                    self._announced = False

                def eventFilter(self, obj, event):
                    try:
                        kind = event.type()
                        if int(kind) in self._COSTLY:
                            try:
                                name = obj.objectName() or ""
                            except Exception:
                                name = ""  # C++ side already gone
                            self._target._last_costly_event = (
                                kind.name, obj.__class__.__name__, name,
                                time.monotonic(),
                            )
                            if not self._announced:
                                self._announced = True
                                _diag("[STALL] event attribution live")
                    except Exception:
                        pass
                    return False

            _stall_app = QApplication.instance()
            if _stall_app is None:
                _diag("[STALL] event attribution unavailable: no QApplication")
            else:
                owner._stall_attribution = _StallAttribution(owner)
                _stall_app.installEventFilter(owner._stall_attribution)
                _diag(
                    "[STALL] event attribution ENABLED — this taxes every Qt event "
                    "and will itself slow the app; clear stall_event_attribution "
                    "once the stall is identified"
                )
        except _StallAttributionDisabled:
            _diag("[STALL] event attribution off (stall_event_attribution=0)")
        except Exception as _attr_exc:
            _diag(f"[STALL] event attribution install failed: {_attr_exc}")

        def _stack_capture_enabled() -> bool:
            try:
                return bool(getattr(owner, "settings", {}).get("stall_stack_capture", False))
            except Exception:
                return False

        def _watch():
            stall_logged = False
            peak = 0.0
            while not bool(getattr(owner, "_mt_watch_stop", False)):
                time.sleep(0.03)
                hb = getattr(owner, "_mt_hb", None)
                if hb is None:
                    continue
                gap = time.monotonic() - float(hb)
                if gap >= threshold:
                    peak = max(peak, gap)
                    if not stall_logged:
                        # Walking the main thread's frame chain from here is a
                        # use-after-free: sys._current_frames() hands back live
                        # frames, and format_stack() follows f_back while the
                        # main thread is still executing and freeing them. It
                        # segfaulted this app on 2026-08-09 23:15:41 --
                        # EXC_BAD_ACCESS at 0x0 on thread
                        # "singws-main-thread-watchdog", inside frame_back_get.
                        # Detecting the stall only reads a float and is safe, so
                        # timing stays on and the stack is opt-in.
                        stack = "(stack capture off; set stall_stack_capture to enable)"
                        if _stack_capture_enabled():
                            try:
                                frame = sys._current_frames().get(main_ident)
                                stack = (
                                    "".join(_traceback.format_stack(frame, limit=14))
                                    if frame is not None
                                    else "(main-thread frame unavailable)"
                                )
                            except Exception as exc:
                                stack = f"(stack capture failed: {exc})"
                        # When the block is inside Qt's C++ the Python stack is
                        # just app.exec() and names nothing, so fall back to the
                        # last expensive event the filter saw dispatched.
                        context = ""
                        try:
                            last = getattr(owner, "_last_costly_event", None)
                            if last:
                                kind, cls, name, when = last
                                age_ms = max(0.0, (time.monotonic() - float(when)) * 1000.0)
                                target = f"{cls}#{name}" if name else cls
                                context = f" last_event={kind} on {target} ({age_ms:.0f}ms before detection)"
                        except Exception:
                            context = ""
                        topology = ""
                        try:
                            snap = str(getattr(owner, "_window_topology", "") or "")
                            if snap:
                                topology = f"\n  windows: {snap}"
                        except Exception:
                            topology = ""
                        _diag(
                            f"[STALL] GUI thread blocked >{int(threshold * 1000)}ms;{context}"
                            f" main-thread stack at detection:\n{stack}{topology}"
                        )
                        stall_logged = True
                else:
                    if stall_logged:
                        _diag(f"[STALL] GUI thread recovered after ~{int(peak * 1000)}ms")
                    stall_logged = False
                    peak = 0.0

        watch_thread = threading.Thread(target=_watch, name="singws-main-thread-watchdog", daemon=True)
        owner._mt_watch_thread = watch_thread
        watch_thread.start()
        _diag(f"[STALL] main-thread watchdog armed threshold={threshold_ms}ms")
    except Exception as e:
        try:
            _diag(f"[STALL] watchdog install failed: {e}")
        except Exception:
            pass


# Settings defaults
TICKER_COLOR_DEFAULT = "#39FF88"  # lively green; operator can override in Ticker Settings
# 750, not 600: show testing established the +600 baseline needed another
# +150, and ffmpeg_cdg_750_baseline_migrated below already zeroes that saved
# +150 fine tuning on the assumption this constant carries it. The constant was
# never actually raised, so installs calibrated to +750 quietly dropped to +600.
FFMPEG_CDG_BASE_OFFSET_MS = 750
# The mpv baseline is a different number because it corrects a different thing.
# FFMPEG_CDG_BASE_OFFSET_MS compensates SingWS's own CDG decoder; the in-process
# (IINA) backend decodes the .cdg inside mpv off real timestamps and needs
# almost nothing. Applying the FFmpeg figure there put CDG ~750ms out and left
# the operator cancelling it by hand on the Display slider.
MPV_CDG_BASE_OFFSET_MS = -50
# Show calibration for MP4 tracks on the native mpv surface. Keep this out of
# the user-facing fine-tuning value so the normal control position is zero.
MPV_MP4_BASE_OFFSET_MS = 100

