DISC_ID_PRIORITY = [
    "SC",
    "CC",
    "KARAFUN",
    "KV",
    "SBI",
    "ME",
    "CB",
]

DISC_BRAND_ALIASES = {
    "KV": ["KV", "KARAOKE VERSION", "KARAOKEVERSION", "KARAOKE-VERSION", "KARAOKE_VERSION"],
    "ZM": ["ZM", "ZOOM", "ZDL", "ZOOM DL", "ZOOMDL", "ZOOM KARAOKE"],
    "SC": ["SC", "SOUNDCHOICE", "SOUND CHOICE", "SOUND-CHOICE", "SOUND_CHOICE"],
    "CC": ["CC"],  # Chris Call Karaoke — always labeled just "CC" (no name variants / code prefixes)
    "CB": ["CB", "CHARTBUSTER", "CHART BUSTER", "CHART-BUSTER", "CHART_BUSTER"],
    "PT": ["PT", "PARTY TYME", "PARTYTYME", "PARTY-TYME", "PARTY_TYME", "PARTY TIME", "PARTYTIME"],
    "SF": ["SF", "SUNFLY", "SUN FLY", "SUN-FLY", "SUN_FLY"],
    "SBI": ["SBI", "SBI KARAOKE"],
    "KARAFUN": ["KARAFUN", "KARA FUN", "KARA-FUN", "KARA_FUN"],
    "ME": ["ME", "MR ENTERTAINER", "MRENTERTAINER", "MR-ENTERTAINER"],
}

_DISC_BRAND_CANONICAL_BY_KEY = {}
_DISC_BRAND_ALIAS_KEYS_BY_CANONICAL = {}
for _canonical_brand, _aliases in DISC_BRAND_ALIASES.items():
    _keys = set()
    for _alias in [_canonical_brand] + list(_aliases):
        _key = re.sub(r"[^A-Z0-9]+", "", str(_alias or "").upper())
        if _key:
            _DISC_BRAND_CANONICAL_BY_KEY[_key] = _canonical_brand
            _keys.add(_key)
    _DISC_BRAND_ALIAS_KEYS_BY_CANONICAL[_canonical_brand] = _keys

def build_bg_index(roots, out_path=BG_MUSIC_INDEX_PATH, max_workers=8, fast_only=True):
    """
    Build/refresh a fast BG music index. Phase 1 is path/size/mtime only (instant at 60k+ files).
    If fast_only=False, will also probe tags/duration using mutagen in a thread pool.
    """
    import os, time, hashlib, json
    from pathlib import Path
    audio_exts = {'.mp3','.wav','.flac','.m4a','.aac','.ogg','.mp4'}

    roots = [str(Path(r)) for r in roots or [] if r and os.path.isdir(r)]
    if not roots:
        data = {"version": 1, "scanned_at": int(time.time()), "roots": [], "track_count": 0, "tracks": []}
        out_path.write_text(json.dumps(data, indent=2), encoding="utf-8")
        return data

    # Load existing for incremental checks
    existing = {}
    try:
        if out_path.exists():
            existing = json.loads(out_path.read_text(encoding="utf-8"))
    except Exception:
        existing = {}
    prev = {t.get("path"): (t.get("size",0), t.get("mtime",0)) for t in existing.get("tracks", [])}

    files = []
    for root in roots:
        for dirpath, _, filenames in os.walk(root):
            base = os.path.basename(dirpath)
            if base.startswith('.'):   # skip dot folders
                continue
            for fn in filenames:
                if fn.startswith('.'):  # skip dotfiles / ._*
                    continue
                ext = os.path.splitext(fn)[1].lower()
                if ext in audio_exts:
                    p = os.path.join(dirpath, fn)
                    try:
                        st = os.stat(p)
                    except Exception:
                        continue
                    files.append((p, st.st_size, int(st.st_mtime), ext))

    tracks, to_probe = [], []
    for p, size, mtime, ext in files:
        needs_probe = prev.get(p) != (size, mtime)
        entry = {
            "id": hashlib.blake2b(p.encode("utf-8"), digest_size=8).hexdigest(),
            "path": p,
            "file": os.path.basename(p),
            "ext": ext,
            "size": size,
            "mtime": mtime,
            "title": None, "artist": None, "album": None, "duration": None,
        }
        tracks.append(entry)
        if needs_probe and not fast_only:
            to_probe.append(entry)

    # Optional parallel tag probe (lazy by default)
    if to_probe:
        def _probe(e):
            try:
                if MutagenFile:
                    mf = MutagenFile(e["path"])
                    if mf:
                        if getattr(mf, "info", None) and getattr(mf.info, "length", None):
                            e["duration"] = int(mf.info.length + 0.5)
                        tags = getattr(mf, "tags", None)
                        def _first(*ks):
                            for k in ks:
                                v = tags.get(k) if tags and k in tags else None
                                if isinstance(v, list) and v: return str(v[0])
                                if v: return str(v)
                            return None
                        e["title"]  = _first("TIT2","title","TITLE")
                        e["artist"] = _first("TPE1","artist","ARTIST")
                        e["album"]  = _first("TALB","album","ALBUM")
            except Exception:
                pass
            return e

        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=max_workers) as ex:
            for _ in ex.map(_probe, to_probe):
                pass

    data = {"version": 1, "scanned_at": int(time.time()), "roots": roots, "track_count": len(tracks), "tracks": tracks}
    tmp = out_path.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, indent=2), encoding="utf-8")
    tmp.replace(out_path)
    print(f"BG index written: {out_path} ({len(tracks)} tracks)")
    return data

def _disc_brand_key(value) -> str:
    return re.sub(r"[^A-Z0-9]+", "", str(value or "").upper())

def _disc_brand_prefix_key(value) -> str:
    key = _disc_brand_key(value)
    m = re.match(r"([A-Z]+)", key)
    return m.group(1) if m else key[:8]

def _disc_brand_value_segments(value) -> list[str]:
    raw = str(value or "").strip()
    if not raw:
        return []
    values = [raw]
    try:
        stem = Path(raw).stem if any(ch in raw for ch in ("/", "\\")) else raw
    except Exception:
        stem = raw
    for part in re.split(r"\s+-\s+|[|/\\()\[\]{}]+", stem):
        part = str(part or "").strip()
        if part and part not in values:
            values.append(part)
    return values

def karaoke_brand_match_info(value) -> dict:
    """Return canonical karaoke brand match metadata for a raw disc/company value."""
    raw = str(value or "").strip()
    key = _disc_brand_key(raw)
    info = {
        "raw": raw,
        "normalized": key,
        "canonical": "",
        "confidence": 0,
        "matched_alias": "",
        "match_type": "unknown",
    }
    if not key:
        info["match_type"] = "empty"
        return info

    known = _DISC_BRAND_CANONICAL_BY_KEY.get(key)
    if known:
        info.update({
            "canonical": known,
            "confidence": 100,
            "matched_alias": key,
            "match_type": "alias_exact",
        })
        return info

    candidates = []
    for canonical, alias_keys in _DISC_BRAND_ALIAS_KEYS_BY_CANONICAL.items():
        for alias_key in alias_keys:
            if not alias_key or not key.startswith(alias_key):
                continue
            remainder = key[len(alias_key):]
            long_alias = len(alias_key) >= 4
            coded_suffix = bool(re.match(r"^[0-9]", remainder or ""))
            separator_free_text = long_alias and bool(remainder)
            if not remainder or coded_suffix or separator_free_text:
                confidence = 94 if coded_suffix else (90 if separator_free_text else 88)
                candidates.append((confidence, len(alias_key), canonical, alias_key))
    if candidates:
        confidence, _alias_len, canonical, alias_key = max(candidates)
        info.update({
            "canonical": canonical,
            "confidence": confidence,
            "matched_alias": alias_key,
            "match_type": "alias_prefix",
        })
    return info

def canonical_disc_brand(value, allow_unknown: bool = True) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    for segment in _disc_brand_value_segments(raw):
        info = karaoke_brand_match_info(segment)
        if info.get("canonical"):
            return str(info.get("canonical") or "")
    return raw.upper() if allow_unknown else ""

def library_brand_choices(tracks, should_cancel=None) -> list[str]:
    """Collapse library disc ids into the brand list the pickers offer.

    disc_id holds a per-disc code -- "KARAOKE VERSION 00", "KV 43403", "KV 00"
    -- not a brand, and the pickers listed those raw values. One library put
    121,650 entries in the combo and spread Karaoke Version across 20,901 of
    them, so the same brand appeared under many names. Canonicalise first, then
    keep only values that actually name a brand: a known alias, or a bare token
    carrying no disc number. Ordered by how much of the library each covers.
    """
    counts = {}
    known = set(DISC_BRAND_ALIASES)
    for index, track in enumerate(tracks or []):
        if should_cancel is not None and index % 1024 == 0 and should_cancel():
            return []
        try:
            disc = str((track or {}).get("disc_id", "") or "").strip().upper()
        except Exception:
            continue
        if not disc:
            continue
        canonical = canonical_disc_brand(disc, allow_unknown=True)
        if not canonical:
            continue
        if canonical not in known and (canonical != disc or any(c.isdigit() for c in disc)):
            continue
        counts[canonical] = counts.get(canonical, 0) + 1
    return [name for name, _count in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))]

def normalize_disc_priority(value, max_items: int = 10):
    """Normalize user priority input into canonical disc/brand prefixes (max 10)."""
    out = []
    seen = set()
    try:
        if isinstance(value, str):
            parts = value.split(",")
        elif isinstance(value, (list, tuple)):
            parts = list(value)
        else:
            parts = []
        for raw in parts:
            p = canonical_disc_brand(raw, allow_unknown=True)
            if not p or p in seen:
                continue
            seen.add(p)
            out.append(p)
            if len(out) >= int(max_items):
                break
    except Exception:
        return []
    return out

def normalize_singer_selected_disc_brand(value) -> str:
    """Return a known singer-selected brand alias, or blank for unknown/empty input."""
    return canonical_disc_brand(value, allow_unknown=False)

def disc_value_matches_brand(value, brand) -> bool:
    canonical = canonical_disc_brand(brand, allow_unknown=True)
    if not canonical:
        return False
    for segment in _disc_brand_value_segments(value):
        info = karaoke_brand_match_info(segment)
        if info.get("canonical") == canonical:
            return True
        if not info.get("canonical") and _disc_brand_key(segment).startswith(_disc_brand_key(canonical)):
            return True
    return False

def disc_id_matches_brand(disc_id, brand) -> bool:
    return disc_value_matches_brand(disc_id, brand)

def disc_brand_candidate_values(track) -> list[str]:
    if not isinstance(track, dict):
        return []
    values = []
    for key in ("disc_id", "discid", "DiscID", "Vendor", "vendor"):
        value = str(track.get(key) or "").strip()
        if value and value not in values:
            values.append(value)
    for key in ("display", "filename", "file", "path"):
        value = str(track.get(key) or "").strip()
        if not value:
            continue
        if key == "path":
            try:
                value = Path(value).name
            except Exception:
                value = os.path.basename(value)
        for segment in _disc_brand_value_segments(value):
            if segment and segment not in values:
                values.append(segment)
    return values

def _best_unknown_disc_brand_value(candidates: list[str]) -> str:
    for value in candidates or []:
        key = _disc_brand_key(value)
        if re.match(r"^[A-Z]{1,10}[0-9]", key):
            return value
    return candidates[0] if candidates else ""

def track_matches_disc_brand(track, brand) -> bool:
    return any(disc_value_matches_brand(value, brand) for value in disc_brand_candidate_values(track))

def effective_disc_priority(host_priority, singer_brand_raw="", singer_override=None, max_items: int = 10):
    host = normalize_disc_priority(host_priority, max_items=max_items)
    override = normalize_disc_priority(singer_override or [], max_items=max_items)
    selected_raw = str(singer_brand_raw or "").strip()
    selected = normalize_singer_selected_disc_brand(selected_raw)
    source = "request" if selected_raw else ""

    if not selected and not selected_raw and override:
        selected = override[0]
        selected_raw = selected
        source = "singer_history"

    if selected:
        effective = [selected] + [p for p in host if p != selected]
    else:
        effective = list(host)
    return {
        "host": host,
        "singer_raw": selected_raw,
        "singer_normalized": selected,
        "singer_source": source,
        "effective": effective,
        "unknown_ignored": bool(selected_raw and not selected),
    }

def disc_priority_available_versions(matches):
    versions = []
    for m in matches or []:
        if not isinstance(m, dict):
            continue
        disc = str(m.get("disc_id") or m.get("discid") or "").strip()
        if disc and disc not in versions:
            versions.append(disc)
    return versions

def build_disc_brand_scan_report(tracks, max_unknowns: int = 50) -> dict:
    report = {
        "track_count": 0,
        "raw_values": [],
        "canonical_counts": {},
        "unknown_prefixes": [],
    }
    raw_stats = {}
    unknown_stats = {}
    for track in tracks or []:
        if not isinstance(track, dict):
            continue
        report["track_count"] += 1
        candidates = disc_brand_candidate_values(track)
        chosen = ""
        chosen_info = None
        for value in candidates:
            info = karaoke_brand_match_info(value)
            if info.get("canonical"):
                chosen = value
                chosen_info = info
                break
        if chosen_info is None:
            chosen = _best_unknown_disc_brand_value(candidates)
            chosen_info = karaoke_brand_match_info(chosen)

        raw_key = chosen or "(blank)"
        stat = raw_stats.setdefault(raw_key, {
            "raw": raw_key,
            "normalized": chosen_info.get("normalized", ""),
            "canonical": chosen_info.get("canonical", ""),
            "confidence": int(chosen_info.get("confidence", 0) or 0),
            "count": 0,
            "matched_alias": chosen_info.get("matched_alias", ""),
            "match_type": chosen_info.get("match_type", "unknown"),
        })
        stat["count"] += 1

        canonical = str(chosen_info.get("canonical") or "")
        if canonical:
            report["canonical_counts"][canonical] = report["canonical_counts"].get(canonical, 0) + 1
        else:
            prefix = _disc_brand_prefix_key(chosen)
            if prefix:
                unk = unknown_stats.setdefault(prefix, {"prefix": prefix, "count": 0, "examples": []})
                unk["count"] += 1
                if chosen and chosen not in unk["examples"] and len(unk["examples"]) < 5:
                    unk["examples"].append(chosen)

    report["raw_values"] = sorted(raw_stats.values(), key=lambda item: (-item["count"], item["raw"]))[:200]
    report["unknown_prefixes"] = sorted(unknown_stats.values(), key=lambda item: (-item["count"], item["prefix"]))[:int(max_unknowns or 50)]
    return report

def request_preferred_disc_brand(req):
    if not isinstance(req, dict):
        return ""
    keys = (
        "preferred_brand",
        "preferred_version",
        "preferred_disc",
        "preferred_disc_id",
        "preferred_disc_priority",
        "brand",
        "version",
        "disc_id",
        "discid",
    )
    for key in keys:
        value = req.get(key)
        if isinstance(value, (list, tuple)):
            value = value[0] if value else ""
        value = str(value or "").strip()
        if key == "preferred_disc_priority" and "," in value:
            value = next((part.strip() for part in value.split(",") if part.strip()), "")
        if value:
            return value
    return ""

def pick_by_disc_priority(matches, priority_list=None):
    priorities = normalize_disc_priority(priority_list if priority_list is not None else DISC_ID_PRIORITY)
    if not priorities:
        return matches[0]
    for prefix in priorities:
        # Handle both 'disc_id' and 'discid' field names
        prefix_matches = [
            m for m in matches
            if track_matches_disc_brand(m, prefix)
        ]
        if prefix_matches:
            return prefix_matches[0]
    return matches[0]

# Lead-silence detection for better BG->karaoke transition timing.
def detect_lead_silence(path, noise_db=-50.0, min_silence=0.5) -> float:
    """Initial-silence length (content-start offset) for the first ~30s.

    Delegates to the FFmpeg/numpy scan in phrase_detect (no GStreamer);
    returns 0.0 on any error/no-match, matching the old level-element scan.
    """
    try:
        return float(phrase_detect.detect_lead_silence(
            path, noise_db=noise_db, min_silence=min_silence,
        ))
    except Exception:
        return 0.0


# Where the audio in a karaoke file actually stops, so the end-of-song detector
# can refuse to cut while notes are still playing. Keyed by resolved audio path.
_TRAILING_SILENCE_CACHE: dict[str, float] = {}
_TRAILING_SILENCE_LOCK = threading.Lock()


def detect_trailing_silence(path, noise_db=-55.0) -> float:
    """Trailing-silence length for `path`, cached per resolved audio file.

    The live meter cannot distinguish a quiet outro, a fade, or a reverb tail
    from the end of the song, which is what made some songs lose their last
    notes. Scanning the file itself gives the detector a hard floor: the song
    is not over until playback has passed the last audible sample.

    Returns 0.0 ("no trailing silence, play it all") on any error.
    """
    key = str(path or "")
    if not key:
        return 0.0
    with _TRAILING_SILENCE_LOCK:
        hit = _TRAILING_SILENCE_CACHE.get(key)
    if hit is not None:
        return float(hit)
    try:
        value = float(phrase_detect.detect_trailing_silence(key, noise_db=noise_db))
    except Exception:
        value = 0.0
    with _TRAILING_SILENCE_LOCK:
        _TRAILING_SILENCE_CACHE[key] = value
    return value


def trailing_silence_cached(path) -> float | None:
    """Cached trailing silence for `path`, or None when it has not been scanned."""
    with _TRAILING_SILENCE_LOCK:
        return _TRAILING_SILENCE_CACHE.get(str(path or ""))


# Trailing-silence (dead-air) detection tunables for background music.
BG_SILENCE_LEVEL = 0.02     # RMS meter (0..1) at/below this counts as silence
BG_SILENCE_MIN_S = 1.2      # sustained silence required before advancing
BG_SILENCE_TAIL_WINDOW = 45.0  # only act within this many seconds of the track end
BGM_UNKNOWN_ANALYSIS_PREGAIN = 1.0  # uncached BG tracks play raw; analysis is for future starts only
BGM_TRACK_CROSSFADE_MS = 5000  # overlap adjacent background tracks for a smooth mix


class BackgroundMusicPlayer(QObject):
    """Background music player that integrates with karaoke playback - OPTIMIZED VERSION"""
    
    def __init__(self, parent=None):
        super().__init__(parent)
        self.playlist = []
        self.current_index = 0
        self.is_playing = False
        self.is_shuffled = False
        self.volume = 0.8  # Default lower volume for background
        self.stop_after_current = False  # Session-only; not persisted.
        # Set when manager mutates playlist while idle; realign pipeline on next play.
        self._pipeline_realign_needed = False

        # Master enable/disable
        self.enabled = True
        
        # NEW: Artwork caching system for instant UI updates
        self.artwork_cache = {}  # file_path -> QPixmap
        self.artwork_cache_size = 50  # Cache up to 50 artworks
        self.precache_count = 5  # Pre-cache this many tracks ahead
        
        self.crossfade_active = False
        self.crossfade_duration_ms = BGM_TRACK_CROSSFADE_MS
        self._crossfade_target_index = None
        self.crossfade_progress = 0.0  # 0.0 = main only, 1.0 = crossfade only
        
        # Track position monitoring for auto-crossfade
        self.position_timer = QTimer(self)
        self.position_timer.timeout.connect(self._check_track_position)
        self.position_timer.start(500)  # Check every 500ms

        # Audio meter for idle overlay visualizer (0.0..1.0).
        self._meter_level = 0.0
        self._meter_last_ts = 0.0
        # Trailing-silence (dead-air) detection for background music. When the
        # tail of a track goes quiet for a sustained moment we advance early
        # instead of letting silence play out.
        self._bg_silence_accum_s = 0.0
        self._bg_silence_last_ts = 0.0
        # Probe fields used to detect stale 'is_playing=True' state.
        self._play_probe_pos = None
        self._play_probe_ts = None
        self._bass_engine = None
        self._bass_fade_generation = 0
        self._bass_crossfade_generation = 0
        self._bg_first_play_logged = False
        self._bg_volume_probe_generation = 0
        self._bg_last_volume_source = "default"
        self._startup_preload_generation = 0
        self._startup_preload_in_progress = False
        self._startup_preload_resume_request = None
        self._next_preload_in_progress = False
        self._next_preload_attempt = None
        self._init_bass_engine()

    def _platform_audio_label(self) -> str:
        try:
            machine = platform.machine() or ""
        except Exception:
            machine = ""
        if sys.platform == "darwin" and machine.lower() in {"x86_64", "amd64"}:
            return "macOS Intel"
        if sys.platform == "darwin" and machine.lower() in {"arm64", "aarch64"}:
            return "macOS Apple Silicon"
        return f"{sys.platform} {machine}".strip()

    def _simple_audio_enabled(self) -> bool:
        try:
            host = self.parent()
            return bool(host is None or not hasattr(host, "settings") or host.settings.get("simple_audio_mode", True))
        except Exception:
            return True

    def _bg_volume_diag(self, stage: str, path: str | None = None, extra: str = ""):
        try:
            engine = getattr(self, "_bass_engine", None)
            backend = getattr(engine, "backend_name", "BASS") if engine is not None else "none"
            master = ""
            if engine is not None:
                try:
                    master = f" engine_master={float(engine.master_volume):.3f}"
                except Exception:
                    master = ""
            track = Path(path).name if path else ""
            suffix = f" {extra}" if extra else ""
            _diag(
                f"[BG-VOLUME] stage={stage} platform={self._platform_audio_label()} "
                f"backend={backend} simple_audio={int(self._simple_audio_enabled())} "
                f"normalize={int(self._bg_normalize_active())} eq_bypassed={int(self._simple_audio_enabled())} "
                f"saved_or_ui={float(self.volume):.3f}{master} playing={int(bool(self.is_playing))} "
                f"track={track!r}{suffix}"
            )
        except Exception:
            pass

    def _sync_volume_from_ui_or_settings(self, reason: str) -> float:
        target = self._target_volume_from_ui()
        try:
            target = max(0.0, min(1.0, float(target)))
        except Exception:
            target = 0.8
        self.volume = target
        self._bg_last_volume_source = reason
        engine = getattr(self, "_bass_engine", None)
        if engine is not None:
            try:
                engine.set_master_volume(target)
            except Exception:
                pass
        self._bg_volume_diag(f"sync-target:{reason}", extra=f"target={target:.3f}")
        return target

    def _schedule_volume_state_probe(self, reason: str):
        self._bg_volume_probe_generation += 1
        generation = int(self._bg_volume_probe_generation)

        def _probe(label: str):
            if generation != int(getattr(self, "_bg_volume_probe_generation", 0) or 0):
                return
            path = self.get_active_track_path()
            extra = ""
            try:
                pos, dur = self.get_playback_times()
                extra = f"reason={reason} pos={pos:.2f}s dur={dur:.2f}s"
            except Exception:
                extra = f"reason={reason}"
            self._bg_volume_diag(label, path, extra)

        for ms, label in (
            (0, "play+0s"),
            (1000, "play+1s"),
            (2000, "play+2s"),
            (3000, "play+3s"),
            (4000, "play+4s"),
            (5000, "play+5s"),
        ):
            QTimer.singleShot(ms, lambda l=label: _probe(l))

    def initialize_startup_volume(self):
        target = self._sync_volume_from_ui_or_settings("app-launch")
        engine = getattr(self, "_bass_engine", None)
        if engine is not None:
            try:
                engine.set_master_volume(target)
            except Exception:
                pass
        self._bg_volume_diag("app-launch-init", extra=f"target={target:.3f}")

    def _init_bass_engine(self, output_name: str | None = None) -> bool:
        try:
            # Close old engine first to free BASS resources
            old_engine = getattr(self, "_bass_engine", None)
            if old_engine is not None:
                try:
                    old_engine.close()
                except Exception:
                    pass
                self._bass_engine = None

            try:
                self._bass_engine = BassBackgroundEngine(output_name=output_name)
            except BassBackgroundError as bass_err:
                # BASS failure recovery: fall back to the libmpv/Qt background
                # engine (same deck/crossfade API) before ever considering the
                # retired pipeline implementation.
                _diag(f"[BG-BASS] unavailable ({bass_err}); trying libmpv/Qt background engine")
                self._bass_engine = LibmpvBackgroundEngine(output_name=output_name)
            backend = getattr(self._bass_engine, "backend_name", "BASS")
            _diag(f"[BG-BASS] {backend} background engine ready platform={self._platform_audio_label()}")
            # Attach the BGM 10-band graphic EQ ONLY in advanced mode. Simple
            # Audio Mode (default) leaves the EQ out of the chain entirely.
            try:
                parent = self.parent()
                simple = bool(parent.settings.get("simple_audio_mode", True)) if (parent is not None and hasattr(parent, "settings")) else True
                if parent is not None and not simple and hasattr(parent, "_ensure_eq_engines"):
                    parent._ensure_eq_engines()
                bgm_eq = getattr(parent, "bgm_eq", None) if parent is not None else None
                if bgm_eq is not None and not simple:
                    self._bass_engine.set_eq(bgm_eq)
                elif hasattr(self._bass_engine, "set_eq"):
                    self._bass_engine.set_eq(None)
                _diag(f"[BG-BASS] init simple_audio={int(simple)} eq_attached={int(bool(bgm_eq is not None and not simple))}")
            except Exception:
                pass
            # Full master chain (gate/tilt EQ/exciter/compressor/limiter) so
            # BGM is processed in tandem with karaoke songs when enabled.
            try:
                if (parent is not None and hasattr(parent, "_bgm_master_active")
                        and hasattr(self._bass_engine, "set_master_processor")):
                    if parent._bgm_master_active():
                        self._bass_engine.set_master_processor(parent._ensure_bgm_master_processor())
                    else:
                        self._bass_engine.set_master_processor(None)
            except Exception:
                pass
            return True
        except Exception as e:
            self._bass_engine = None
            _diag(f"[BG-BASS] no BASS/libmpv background engine available ({e})")
            return False

    def _bass_ready(self) -> bool:
        return getattr(self, "_bass_engine", None) is not None

    def _bass_selected_output_name(self) -> str | None:
        try:
            parent = self.parent()
            return parent._safe_local_audio_output_name()
        except Exception:
            pass
        return None

    def _bass_update_meter(self):
        engine = getattr(self, "_bass_engine", None)
        if engine is None:
            return
        try:
            target = engine.meter_level()
            self._meter_level = (self._meter_level * 0.70) + (target * 0.30)
            self._meter_last_ts = time.monotonic()
        except Exception:
            pass

    def _bass_stop_after_fade(self, generation: int):
        if generation != int(getattr(self, "_bass_fade_generation", 0) or 0):
            return
        self.pause()
        try:
            self.volume = self._target_volume_from_ui()
        except Exception:
            pass
    
    def set_enabled(self, flag: bool):
        """Master enable/disable for BG playback."""
        self.enabled = bool(flag)
        if self.enabled:
            # Re-sync desired volume from UI/setting immediately
            try:
                self.volume = self._target_volume_from_ui()
                print(f"[BG] Enabled; desired volume set to {self.volume}")
            except Exception:
                pass
        else:
            # Smoothly fade out if currently playing
            if self.is_playing:
                self.fade_out(500)

    def load_folder(self, folder_path):
        """Load all audio files from a folder into the playlist"""
        from pathlib import Path
        
        audio_extensions = {'.mp3', '.wav', '.flac', '.m4a', '.aac', '.ogg', '.mp4'}
        
        try:
            folder = Path(folder_path)
            audio_files = []
            
            # Recursively find all audio files
            for file_path in folder.rglob('*'):
                # Skip hidden/system files (._* files on macOS)
                if file_path.name.startswith('.') or file_path.name.startswith('._'):
                    continue
                    
                if file_path.is_file() and file_path.suffix.lower() in audio_extensions:
                    audio_files.append(str(file_path))
            
            if not audio_files:
                print(f"No audio files found in {folder_path}")
                return
            
            # Sort alphabetically for consistent order
            audio_files.sort()
            
            # Stop current playback
            self.stop()
            
            # Clear old artwork cache when loading new folder
            self.clear_artwork_cache()
            
            # Load new playlist
            self.playlist = audio_files
            self.current_index = 0
            self.is_shuffled = False
            
            print(f"Loaded {len(audio_files)} background music tracks from {folder_path}")
            
            # IMMEDIATE UI update - don't wait for background tasks
            if hasattr(self.parent(), 'update_bg_track_display'):
                self.parent().update_bg_track_display()
            
            # Start background pre-caching after UI is updated
            QTimer.singleShot(200, self._start_artwork_precache)
                
        except Exception as e:
            print(f"Failed to load background music folder: {e}")

    def _start_artwork_precache(self):
        """Start background pre-caching of artwork for upcoming tracks"""
        if not self.playlist:
            return
        
        # Cache artwork for current track + next few tracks in background
        tracks_to_cache = []
        for i in range(min(self.precache_count, len(self.playlist))):
            idx = (self.current_index + i) % len(self.playlist)
            track_path = self.playlist[idx]
            if track_path not in self.artwork_cache:
                tracks_to_cache.append(track_path)
        
        if tracks_to_cache:
            print(f"🎨 Starting background pre-cache for {len(tracks_to_cache)} tracks")
            # Use a thread to pre-cache without blocking UI
            import threading
            threading.Thread(
                target=self._precache_artwork_worker,
                args=(tracks_to_cache,),
                daemon=True
            ).start()

    def _precache_artwork_worker(self, tracks_to_cache):
        """Background worker to pre-cache artwork"""
        for i, track_path in enumerate(tracks_to_cache):
            try:
                artwork = self._extract_artwork_sync(track_path)
                if artwork and not artwork.isNull():
                    # Store in cache (thread-safe since we're only writing to new keys)
                    self.artwork_cache[track_path] = artwork
                    
                    # If this is the current track, update UI immediately
                    if (self.playlist and 
                        self.current_index < len(self.playlist) and 
                        track_path == self.playlist[self.current_index]):
                        QTimer.singleShot(0, self._update_ui_with_cached_artwork)
                    
                    # Small delay between extractions to not hammer the disk
                    if i < len(tracks_to_cache) - 1:
                        import time
                        time.sleep(0.1)
                        
            except Exception as e:
                print(f"⚠️ Pre-cache failed for {Path(track_path).name}: {e}")

    def _update_ui_with_cached_artwork(self):
        """Update UI when pre-cached artwork becomes available"""
        if hasattr(self.parent(), 'update_bg_track_display'):
            self.parent().update_bg_track_display()

    def clear_artwork_cache(self):
        """Clear the artwork cache to free memory"""
        self.artwork_cache.clear()
        print("🗑️ Artwork cache cleared")

    def manage_artwork_cache(self):
        """Remove old entries if cache gets too large"""
        if len(self.artwork_cache) > self.artwork_cache_size:
            # Remove the oldest entries (simple approach - remove first half)
            keys_to_remove = list(self.artwork_cache.keys())[:len(self.artwork_cache)//2]
            for key in keys_to_remove:
                del self.artwork_cache[key]
            print(f"🗑️ Trimmed artwork cache to {len(self.artwork_cache)} entries")

    def shuffle_playlist(self):
        """Shuffle the current playlist"""
        if not self.playlist:
            return
            
        import random
        
        # Remember current track
        current_track = self.playlist[self.current_index] if self.current_index < len(self.playlist) else None
        
        # Shuffle the playlist
        shuffled = self.playlist.copy()
        random.shuffle(shuffled)
        
        # If we were playing a track, make it the first in the shuffled list
        if current_track and current_track in shuffled:
            shuffled.remove(current_track)
            shuffled.insert(0, current_track)
            self.current_index = 0
        
        self.playlist = shuffled
        self.is_shuffled = True
        
        print(f"Shuffled background music playlist ({len(self.playlist)} tracks)")
        
        # IMMEDIATE UI update
        if hasattr(self.parent(), 'update_bg_track_display'):
            self.parent().update_bg_track_display()

        # Restart pre-caching for new order
        QTimer.singleShot(200, self._start_artwork_precache)

    def get_current_track_name(self):
        """Get just the filename of the current track"""
        if not self.playlist or self.current_index >= len(self.playlist):
            return "No track"
        
        from pathlib import Path
        return Path(self.playlist[self.current_index]).stem

    def get_playlist_info(self):
        """Get playlist information string"""
        if not self.playlist:
            return "No folder loaded"
        
        track_name = self.get_current_track_name()
        crossfade_info = " (crossfading)" if self.crossfade_active else ""
        return f"{track_name} ({self.current_index + 1}/{len(self.playlist)}){crossfade_info}"
    
    def get_current_track_info(self):
        """Get info about currently loaded track"""
        return self.get_playlist_info()

    def get_active_track_path(self) -> str:
        """Best-effort path for the track currently sounding from the live engine."""
        if self._bass_ready():
            try:
                # A secondary deck can be preloaded and attached at zero gain
                # well before a crossfade starts.  It is not the audible track
                # until the crossfade is active; reporting it here makes
                # playlist edits/shuffles preserve the wrong row.
                deck = (
                    self._bass_engine.secondary
                    if self.crossfade_active and self._bass_engine.secondary is not None
                    else self._bass_engine.primary
                )
                if deck is not None:
                    return str(deck.path)
            except Exception:
                pass
        try:
            if self.playlist and 0 <= int(self.current_index) < len(self.playlist):
                return str(self.playlist[int(self.current_index)])
        except Exception:
            pass
        return ""
        
    def _karaoke_is_active(self) -> bool:
        """
        Returns True if karaoke is currently playing (as reported by the parent app).
        We check a few common flags/methods so it works with your current app.
        """
        try:
            p = self.parent()
            # Common patterns — keep all three for robustness
            if hasattr(p, "karaoke_playing"):
                return bool(p.karaoke_playing)
            if hasattr(p, "is_karaoke_playing") and callable(p.is_karaoke_playing):
                return bool(p.is_karaoke_playing())
            if hasattr(p, "is_karaoke_active"):
                return bool(p.is_karaoke_active)
        except Exception:
            pass
        return False
    
    def _bg_end_silence_enabled(self) -> bool:
        try:
            host = self.parent()
            if host is not None and hasattr(host, "settings"):
                return bool(host.settings.get("bg_end_silence_trim_enabled", False))
        except Exception:
            pass
        return True

    def _bg_loudness_info_for_path(self, path: str | None):
        """Return cached BGM loudness info and kick off background analysis.

        This is intentionally analysis/cache only. Playback applies the cached
        static gain once per BASS source deck, avoiding live loudness DSP,
        compressors, or duplicate volume filters.
        """
        if not path:
            return None
        if not self._bg_normalize_active():
            _diag(f"[BG-AUDIO] normalization bypassed reason=disabled track={Path(path).name}")
            return None
        info = loudness_info_cached(path)
        if info is None:
            _diag(f"[BG-AUDIO] normalization cache miss track={Path(path).name} action=analyze_async")
            analyze_loudness_async(path)
        else:
            try:
                gain_db = float(info.get("gain_db", 0.0) or 0.0)
                gain_linear = float(info.get("gain_linear", 1.0) or 1.0)
                _diag(f"[BG-AUDIO] normalization cache hit track={Path(path).name} gain_db={gain_db:+.1f} gain_linear={gain_linear:.3f}")
            except Exception:
                _diag(f"[BG-AUDIO] normalization cache hit track={Path(path).name}")
        return info

    def _bg_dsp_chain_label(self, path: str | None, info: dict | None) -> str:
        try:
            eq = None
            parent = self.parent()
            if parent is not None:
                eq = getattr(parent, "bgm_eq", None)
            eq_on = bool(eq is not None and eq.enabled() and not eq.is_flat())
        except Exception:
            eq_on = False
        eq_chain = "off"
        if eq_on:
            try:
                engine = getattr(self, "_bass_engine", None)
                if engine is not None and getattr(engine, "_eq_fx_handles", None):
                    eq_chain = "native-bass"
                elif engine is not None and getattr(engine, "_eq_dsp_handle", 0):
                    eq_chain = "python-dsp"
                else:
                    eq_chain = "requested-unavailable"
            except Exception:
                eq_chain = "on"
        norm = "on" if self._bg_normalize_active() else "off"
        lufs = "pending"
        gain = "+0.0"
        peak = "n/a"
        if info is not None:
            lufs = f"{float(info.get('lufs', 0.0)):.1f}"
            gain = f"{float(info.get('gain_db', 0.0)):+.1f}"
            pk = info.get("peak_db")
            peak = "n/a" if pk is None else f"{float(pk):.1f}"
        master = "off"
        try:
            parent = self.parent()
            if parent is not None and hasattr(parent, "_master_chain_label"):
                master = parent._master_chain_label("bgm")
        except Exception:
            master = "unknown"
        return (
            f"BASSmix -> deck_gain(norm={norm}, LUFS={lufs}, peak={peak}dB, gain={gain}dB) "
            f"-> deck_fade/crossfade -> mixer_master(slider/fade={float(self.volume):.3f}) "
            f"-> EQ({eq_chain}) -> master_audio({master}) -> output"
        )

    def _bg_normalize_active(self) -> bool:
        """BG loudness normalization is active only in advanced mode. Simple
        Audio Mode (default) bypasses it entirely so the BG slider is the only
        gain stage."""
        try:
            host = self.parent()
            if host is None or not hasattr(host, "settings"):
                return False
            if bool(host.settings.get("simple_audio_mode", True)):
                return False
            return bool(host.settings.get("bg_normalize_enabled", True))
        except Exception:
            return False

    def _bg_norm_factor_for_path(self, path: str | None) -> tuple[float, dict | None]:
        enabled = self._bg_normalize_active()
        if not enabled or not path:
            if path:
                _diag(f"[BG-AUDIO] normalization gain bypassed reason={'disabled' if not enabled else 'missing_path'} track={Path(path).name}")
            return 1.0, None
        info = self._bg_loudness_info_for_path(path)
        if info is None:
            _diag(
                f"[BG-AUDIO] normalization cache miss unity playback track={Path(path).name} "
                f"gain_linear={BGM_UNKNOWN_ANALYSIS_PREGAIN:.3f}"
            )
            return BGM_UNKNOWN_ANALYSIS_PREGAIN, None
        try:
            return max(0.05, min(4.0, float(info.get("gain_linear", 1.0) or 1.0))), info
        except Exception:
            return 1.0, info

    def _schedule_bg_normalize_retry(self, path: str, deck: str):
        """Retry normalization shortly, to catch the async loudness result for a
        track that started before its analysis finished (the classic 'first BGM
        track not normalized' case). Bounded and cancelled if the track changes."""
        try:
            counts = getattr(self, "_bg_norm_retry", None)
            if not isinstance(counts, dict):
                counts = {}
                self._bg_norm_retry = counts
            key = (deck, path)
            n = int(counts.get(key, 0))
            if n >= 12:  # ~18s of grace at 1.5s spacing, then give up
                return
            counts[key] = n + 1
            gen = getattr(self, "_bg_norm_gen", {})
            token = int(gen.get(deck, 0)) if isinstance(gen, dict) else 0

            def _retry():
                try:
                    cur_gen = getattr(self, "_bg_norm_gen", {})
                    if isinstance(cur_gen, dict) and int(cur_gen.get(deck, 0)) != token:
                        return  # a newer track/refresh superseded this retry
                    if not self._bg_normalize_active():
                        return
                    # For the primary deck, only re-apply if this is still the
                    # current track (secondary is short-lived; allow it).
                    if deck == "primary" and self.playlist and 0 <= int(self.current_index) < len(self.playlist):
                        if self.playlist[int(self.current_index)] != path:
                            return
                    # Re-run: applies the real gain if analysis landed, else
                    # re-arms another bounded retry.
                    self._refresh_bg_normalize(path, deck)
                except Exception:
                    pass

            QTimer.singleShot(1500, _retry)
        except Exception:
            pass

    def _refresh_bg_normalize(self, path: str | None = None, deck: str = "primary"):
        """Apply per-track loudness normalization to the BASS engine so each BG
        track plays at a consistent level. The gain is per source deck; the
        user's volume/fades remain the single mixer-master stage."""
        try:
            engine = getattr(self, "_bass_engine", None)
            if engine is None:
                return None
            # Bump this deck's generation token so any pending re-apply retry
            # scheduled for an earlier track/refresh cancels itself.
            gen = getattr(self, "_bg_norm_gen", None)
            if not isinstance(gen, dict):
                gen = {}
                self._bg_norm_gen = gen
            gen[deck] = int(gen.get(deck, 0)) + 1
            enabled = self._bg_normalize_active()
            if not enabled:
                if deck == "secondary" and hasattr(engine, "set_secondary_normalize_gain"):
                    engine.set_secondary_normalize_gain(1.0)
                elif hasattr(engine, "set_primary_normalize_gain"):
                    engine.set_primary_normalize_gain(1.0)
                _diag(f"[BG-AUDIO] normalization disabled chain={self._bg_dsp_chain_label(path, None)}")
                return None
            if not path:
                if self.playlist and 0 <= int(self.current_index) < len(self.playlist):
                    path = self.playlist[int(self.current_index)]
            if not path:
                if deck == "secondary" and hasattr(engine, "set_secondary_normalize_gain"):
                    engine.set_secondary_normalize_gain(1.0)
                elif hasattr(engine, "set_primary_normalize_gain"):
                    engine.set_primary_normalize_gain(1.0)
                return None
            info = self._bg_loudness_info_for_path(path)
            if info is None:
                factor = BGM_UNKNOWN_ANALYSIS_PREGAIN
                _diag(f"[BG-AUDIO] calculated gain unavailable deck={deck} track={Path(path).name}; unity playback while analysis runs gain={factor:.3f}")
                if deck == "secondary" and hasattr(engine, "set_secondary_normalize_gain"):
                    engine.set_secondary_normalize_gain(factor)
                elif hasattr(engine, "set_primary_normalize_gain"):
                    engine.set_primary_normalize_gain(factor)
            else:
                factor = float(info.get("gain_linear", 1.0) or 1.0)
                try:
                    _diag(f"[BG-AUDIO] calculated gain deck={deck} track={Path(path).name} gain_db={float(info.get('gain_db', 0.0)):+.1f} gain_linear={factor:.3f}")
                except Exception:
                    _diag(f"[BG-AUDIO] calculated gain deck={deck} track={Path(path).name} gain_linear={factor:.3f}")
                if deck == "secondary" and hasattr(engine, "set_secondary_normalize_gain"):
                    engine.set_secondary_normalize_gain(factor)
                elif hasattr(engine, "set_primary_normalize_gain"):
                    engine.set_primary_normalize_gain(factor)
            _diag(f"[BG-AUDIO] track={Path(path).name} deck={deck} chain={self._bg_dsp_chain_label(path, info)}")
            # Warm the next track so its gain is ready before the crossfade.
            try:
                if self.playlist:
                    nxt = self.playlist[(int(self.current_index) + 1) % len(self.playlist)]
                    if nxt:
                        nxt_info = self._bg_loudness_info_for_path(nxt)
                        if nxt_info is None:
                            _diag(f"[BG-AUDIO] next-track normalization warming queued_or_skipped track={Path(nxt).name}")
            except Exception:
                pass
            return info
        except Exception:
            return None

    def _check_bg_tail_silence(self, pos_sec: float, dur_sec: float, time_left: float) -> bool:
        """Detect sustained trailing silence near the end of a BG track.

        Returns True when we should advance/crossfade early to avoid dead air.
        Uses the live RMS meter (self._meter_level); only acts within the last
        BG_SILENCE_TAIL_WINDOW seconds so quiet intros/breaks aren't cut.
        """
        if not self._bg_end_silence_enabled() or dur_sec <= 0:
            self._bg_silence_accum_s = 0.0
            self._bg_silence_last_ts = 0.0
            return False
        now = time.monotonic()
        last = self._bg_silence_last_ts
        self._bg_silence_last_ts = now
        dt = (now - last) if last > 0 else 0.0
        if dt <= 0 or dt > 2.0:
            dt = 0.0  # first tick after (re)start or a stall — don't over-accumulate
        in_tail = time_left <= BG_SILENCE_TAIL_WINDOW
        if in_tail and self._meter_level <= BG_SILENCE_LEVEL:
            self._bg_silence_accum_s += dt
        else:
            self._bg_silence_accum_s = 0.0
        if self._bg_silence_accum_s >= BG_SILENCE_MIN_S:
            self._bg_silence_accum_s = 0.0
            return True
        return False

    def _check_track_position(self):
        """Check current track position and start crossfade near the end"""
        if self._bass_ready():
            self._bass_update_meter()
            engine = self._bass_engine
            if not self.is_playing or engine.primary is None:
                return
            if self.crossfade_active:
                finished = getattr(engine, "crossfade_finished", None)
                if callable(finished) and finished():
                    self._complete_crossfade(self._bass_crossfade_generation)
                return
            if not self.crossfade_active and engine.source_ended():
                if bool(getattr(self, "stop_after_current", False)):
                    self.stop_after_current = False
                    QTimer.singleShot(0, self.stop)
                else:
                    # An ended source has nothing left to fade out. Bring its
                    # replacement in promptly, not over another five seconds.
                    if not self._start_crossfade(duration_ms=100):
                        QTimer.singleShot(0, self.next_track)
                if hasattr(self.parent(), "update_bg_button_state"):
                    QTimer.singleShot(100, self.parent().update_bg_button_state)
                return
            if self.crossfade_active or bool(getattr(self, "stop_after_current", False)):
                return
            pos_sec, dur_sec = engine.get_times()
            self._prepare_next_background_track()
            _start, audio_end = self._bgm_content_window(self.playlist[self.current_index], dur_sec)
            lead = getattr(engine, "crossfade_lead_seconds", lambda: 0.0)()
            time_left = audio_end - pos_sec - lead
            adaptive_ms, adaptive_reason = self._adaptive_crossfade_duration_ms()
            crossfade_start_time = adaptive_ms / 1000.0
            if self._check_bg_tail_silence(pos_sec, dur_sec, dur_sec - pos_sec):
                print(f"[BG] trailing silence detected at {pos_sec:.1f}s — advancing early")
                self._start_crossfade(duration_ms=100)
                return
            if dur_sec > 0.0 and time_left <= crossfade_start_time:
                _diag(
                    f"[TRANSITION] BGM crossfade selected duration={adaptive_ms}ms "
                    f"reason={adaptive_reason} track={Path(self.playlist[self.current_index]).name!r}"
                )
                print(f"Starting BASSmix crossfade with {time_left:.1f}s left in track")
                # A late UI tick must not stretch the incoming fade beyond
                # the remaining outgoing audio, especially after a stall.
                self._start_crossfade(duration_ms=min(adaptive_ms, max(100, int(time_left * 1000))))
            return

    def _bgm_content_window(self, path, duration=None):
        host = self.parent()
        settings = getattr(host, "settings", {}) if host is not None else {}
        if not bool(settings.get("seamless_transitions_enabled", True)):
            return 0.0, float(duration or 0.0)
        record = transition_analysis_cached(path)
        return transition_analysis.bgm_audio_window(
            record, duration if duration is not None else getattr(record, "duration", 0.0),
        )

    def _prepare_next_background_track(self):
        """Prescan one next BASS source off the UI thread; attach only if still next."""
        engine = self._bass_engine
        host = self.parent()
        if (not self.playlist or self.crossfade_active
                or not hasattr(engine, "install_prepared_secondary")
                or host is None or not hasattr(host, "_run_on_ui_thread")
                or getattr(self, "_next_preload_in_progress", False)):
            return
        path = str(self.playlist[(self.current_index + 1) % len(self.playlist)])
        primary = engine.primary
        attempt = (id(engine), id(primary), path)
        if getattr(self, "_next_preload_attempt", None) == attempt:
            return
        self._next_preload_attempt = attempt
        self._next_preload_in_progress = True
        # Do not keep a stale next source attached after a playlist reorder.
        engine.invalidate_secondary_preload()
        norm_gain, _info = self._bg_norm_factor_for_path(path)

        def _worker():
            prepared = None
            error = ""
            try:
                prepared = engine.prepare_primary(path, norm_gain=norm_gain)
            except Exception as exc:
                error = str(exc)

            def _finish():
                self._next_preload_in_progress = False
                still_next = (
                    engine is self._bass_engine and primary is engine.primary
                    and not self.crossfade_active and bool(self.playlist)
                    and path == str(self.playlist[(self.current_index + 1) % len(self.playlist)])
                )
                if not still_next or prepared is None:
                    if prepared is not None:
                        engine.discard_prepared_primary(prepared)
                    if error:
                        _diag(f"[BG-BASS] next preload unavailable track={Path(path).name!r} error={error[:160]!r}")
                    return
                try:
                    engine.install_prepared_secondary(prepared)
                except Exception as exc:
                    _diag(f"[BG-BASS] next preload attach failed: {exc}")

            host._run_on_ui_thread(_finish)

        threading.Thread(target=_worker, daemon=True, name="bgm-next-preload").start()

    def _adaptive_crossfade_duration_ms(self):
        """Select from cached metadata only; missing data keeps configured timing."""
        configured = max(2000, min(8000, int(self.crossfade_duration_ms)))
        try:
            host = self.parent()
            settings = getattr(host, "settings", {}) if host is not None else {}
            if not bool(settings.get("seamless_transitions_enabled", True)):
                return configured, "seamless_disabled"
            if not self.playlist:
                return configured, "no_playlist"
            current_file = self.playlist[self.current_index]
            record = transition_analysis_cached(current_file)
            seconds, reason = transition_analysis.select_bgm_crossfade_seconds(
                record, default_seconds=configured / 1000.0,
            )
            return int(round(seconds * 1000.0)), reason
        except Exception:
            return configured, "safe_fallback"

    def get_playback_times(self) -> tuple[float, float]:
        """Return (position_seconds, duration_seconds) for current BG track."""
        if self._bass_ready():
            try:
                return self._bass_engine.get_times()
            except Exception:
                return 0.0, 0.0
        return 0.0, 0.0

    def is_effectively_playing(self) -> bool:
        """True only when BG is really running (not stale PLAYING/muted state)."""
        if self._bass_ready():
            try:
                engine = self._bass_engine
                return bool(
                    self.is_playing
                    and engine.primary is not None
                    and engine.is_playing()
                    and (float(engine.master_volume) > 0.0005 or self.crossfade_active)
                )
            except Exception:
                return False
        return False

    def seek_seconds(self, seconds: float) -> bool:
        """Seek current BG track to absolute seconds."""
        if self._bass_ready():
            try:
                return bool(self._bass_engine.seek(seconds))
            except Exception as e:
                _diag(f"[BG-BASS] seek failed: {e}")
                return False
        return False
    
    def _start_crossfade(self, target_index=None, duration_ms=None):
        """Start crossfade to next track"""
        # Reset trailing-silence detector for the upcoming track.
        self._bg_silence_accum_s = 0.0
        self._bg_silence_last_ts = 0.0
        if self._bass_ready():
            if self.crossfade_active or not self.playlist:
                return False
            self._sync_volume_from_ui_or_settings("crossfade-start")
            next_index = (
                int(target_index) % len(self.playlist)
                if target_index is not None
                else (self.current_index + 1) % len(self.playlist)
            )
            next_file = self.playlist[next_index]
            selected_duration_ms = max(100, min(8000, int(
                self.crossfade_duration_ms if duration_ms is None else duration_ms
            )))
            try:
                position, duration = self._bass_engine.get_times()
                if duration > 0.0:
                    _start, end = self._bgm_content_window(self.playlist[self.current_index], duration)
                    lead = getattr(self._bass_engine, "crossfade_lead_seconds", lambda: 0.0)()
                    selected_duration_ms = min(selected_duration_ms, max(100, int((end - position - lead) * 1000)))
                norm_gain, info = self._bg_norm_factor_for_path(next_file)
                content_start, content_end = self._bgm_content_window(next_file)
                if content_end > content_start:
                    selected_duration_ms = min(selected_duration_ms, max(100, int((content_end - content_start) * 1000)))
                if not self._bass_engine.start_crossfade(
                    next_file, selected_duration_ms, norm_gain=norm_gain, start_seconds=content_start,
                ):
                    return False
                _diag(f"[BG-AUDIO] track={Path(next_file).name} deck=secondary chain={self._bg_dsp_chain_label(next_file, info)}")
                print(f"Starting BASSmix crossfade to: {Path(next_file).name}")
                self.crossfade_active = True
                self.crossfade_progress = 0.0
                self._crossfade_target_index = next_index
                self._bass_crossfade_generation += 1
                generation = int(self._bass_crossfade_generation)
                if not callable(getattr(self._bass_engine, "crossfade_finished", None)):
                    QTimer.singleShot(
                        max(1, selected_duration_ms),
                        lambda g=generation: self._complete_crossfade(g),
                    )
                return True
            except Exception as e:
                print(f"Failed to start BASSmix crossfade: {e}")
                return False
        return False
    
    @staticmethod
    def _crossfade_mix_gains(progress):
        """Return equal-power outgoing/incoming gains for a 0..1 blend."""
        progress = max(0.0, min(1.0, float(progress)))
        return (
            math.cos(progress * math.pi * 0.5),
            math.sin(progress * math.pi * 0.5),
        )
    
    def _complete_crossfade(self, bass_generation=None):
        """Complete the crossfade and switch to the new track"""
        if self._bass_ready():
            if bass_generation is not None and bass_generation != int(getattr(self, "_bass_crossfade_generation", 0) or 0):
                return
            if not self.crossfade_active:
                return
            try:
                if not self._bass_engine.complete_crossfade():
                    return
            except Exception as e:
                _diag(f"[BG-BASS] crossfade completion failed: {e}")
                return
            target_index = getattr(self, "_crossfade_target_index", None)
            self.current_index = (
                int(target_index) % len(self.playlist)
                if target_index is not None
                else (self.current_index + 1) % len(self.playlist)
            )
            self._crossfade_target_index = None
            self.crossfade_active = False
            self.crossfade_progress = 0.0
            if hasattr(self.parent(), "update_bg_track_display"):
                self.parent().update_bg_track_display()
            QTimer.singleShot(200, self._start_artwork_precache)
            print(f"Switched to: {Path(self.playlist[self.current_index]).name}")
        return

    def preload_current_track_paused(self) -> bool:
        """Build current track pipeline and leave it PAUSED (silent preroll)."""
        if self._bass_ready():
            if not self.playlist:
                return False
            if self._bass_engine.primary is not None:
                self._sync_volume_from_ui_or_settings("preload-existing")
                return True
            try:
                current_file = self.playlist[self.current_index]
                self._bg_volume_diag("preload-before-media-load", current_file)
                target = self._sync_volume_from_ui_or_settings("preload")
                self._bass_engine.set_master_volume(0.0)
                self._bass_engine.load(current_file, paused=True, volume=self.volume)
                self._bass_engine.set_master_volume(target)
                self._refresh_bg_normalize(current_file, deck="primary")
                self.is_playing = False
                self._bg_volume_diag("preload-after-media-load", current_file, extra=f"target={target:.3f}")
                print(f"[BG-BASS] Preloaded track (paused): {Path(current_file).name}")
                return True
            except Exception as e:
                print(f"[BG-BASS] Preload exception: {e}")
                return False
        return False

    def preload_current_track_paused_async(self) -> bool:
        """Prescan the startup BGM source off the GUI thread, then attach it."""
        if not self._bass_ready() or not self.playlist:
            return False
        engine = self._bass_engine
        if engine.primary is not None:
            return True
        # Only the native BASS backend exposes a safe split between slow file
        # prescan and live mixer mutation. Other backends remain lazy and load
        # on first Play instead of moving QObject work to a Python thread.
        if not (
            hasattr(engine, "prepare_primary")
            and hasattr(engine, "install_prepared_primary")
            and hasattr(engine, "discard_prepared_primary")
        ):
            _diag("[BG-BASS] startup preload skipped; backend has no worker-safe prepare path")
            return False
        if bool(getattr(self, "_startup_preload_in_progress", False)):
            return True

        current_file = str(self.playlist[self.current_index])
        target = self._sync_volume_from_ui_or_settings("startup-preload-queue")
        norm_gain, info = self._bg_norm_factor_for_path(current_file)
        self._startup_preload_generation += 1
        generation = int(self._startup_preload_generation)
        self._startup_preload_in_progress = True
        _diag(f"[BG-BASS] startup preload queued track={Path(current_file).name!r}")

        def _worker():
            prepared = None
            error = ""
            started = time.monotonic()
            try:
                prepared = engine.prepare_primary(current_file, norm_gain=norm_gain)
            except Exception as exc:
                error = str(exc)

            def _finish():
                resume_request = getattr(self, "_startup_preload_resume_request", None)
                stale = (
                    generation != int(getattr(self, "_startup_preload_generation", 0) or 0)
                    or engine is not getattr(self, "_bass_engine", None)
                    or not self.playlist
                    or str(self.playlist[self.current_index]) != current_file
                )
                if stale or error or prepared is None:
                    if prepared is not None:
                        engine.discard_prepared_primary(prepared)
                    if generation == int(getattr(self, "_startup_preload_generation", 0) or 0):
                        self._startup_preload_in_progress = False
                        self._startup_preload_resume_request = None
                    _diag(
                        f"[BG-BASS] startup preload discarded stale={int(stale)} "
                        f"error={error[:160]!r}"
                    )
                    return
                try:
                    installed = bool(engine.install_prepared_primary(prepared, volume=target))
                except Exception as exc:
                    installed = False
                    error_text = str(exc)
                else:
                    error_text = ""
                self._startup_preload_in_progress = False
                self._startup_preload_resume_request = None
                if not installed:
                    _diag(f"[BG-BASS] startup preload attach failed error={error_text[:160]!r}")
                    if resume_request:
                        if resume_request[0] == "fade":
                            self.fade_in(*resume_request[1:])
                        else:
                            self.play()
                    return
                self.is_playing = False
                self._bg_volume_diag(
                    "startup-preload-ready", current_file,
                    extra=f"elapsed_ms={(time.monotonic() - started) * 1000.0:.0f} target={target:.3f}",
                )
                _diag(
                    f"[BG-BASS] startup preload ready track={Path(current_file).name!r} "
                    f"chain={self._bg_dsp_chain_label(current_file, info)}"
                )
                if resume_request:
                    _diag(f"[BG-BASS] honoring queued startup action={resume_request[0]}")
                    if resume_request[0] == "fade":
                        self.fade_in(*resume_request[1:])
                    else:
                        self.play()

            host = self.parent()
            if host is not None and hasattr(host, "_run_on_ui_thread"):
                host._run_on_ui_thread(_finish)
            elif prepared is not None:
                engine.discard_prepared_primary(prepared)

        threading.Thread(target=_worker, daemon=True, name="bgm-startup-preload").start()
        return True


    def play(self):
        """Start/resume background music"""
        if not self.playlist:
            print("No playlist loaded")
            return
        
        # Never play BG if karaoke is active
        if self._karaoke_is_active():
            print("Karaoke is active; suppressing BG play()")
            return
               
        if not self.enabled:
            print("BG disabled; play() ignored")
            return

        if bool(getattr(self, "_startup_preload_in_progress", False)):
            self._startup_preload_resume_request = ("play",)
            _diag("[BG-BASS] play queued behind startup preload")
            return

        if self._bass_ready():
            if self._pipeline_realign_needed and self._bass_engine.primary is not None and not self.is_playing:
                self._bass_engine.stop()
            self._pipeline_realign_needed = False
            target_volume = self._sync_volume_from_ui_or_settings("play")
            if self.volume <= 0.001:
                self.volume = target_volume
                print(f"[BG-BASS] Play sanity: using desired volume {self.volume}")
            try:
                current_file = self.playlist[self.current_index]
                if not self._bg_first_play_logged:
                    self._bg_first_play_logged = True
                    _diag(f"[BG-VOLUME] first BGM file selected={Path(current_file).name!r}")
                if self._bass_engine.primary is None and not self.preload_current_track_paused():
                    return
                self._refresh_bg_normalize()
                self._bg_volume_diag("play-before-BASS_ChannelPlay", current_file)
                self._bass_engine.set_master_volume(target_volume)
                if not self._bass_engine.play():
                    print("[BG-BASS] Failed to start background mixer")
                    return
                self._bass_engine.set_master_volume(target_volume)
                self.is_playing = True
                self._bg_volume_diag("play-after-BASS_ChannelPlay", current_file)
                self._schedule_volume_state_probe("bass-play")
                print(f"Playing BASSmix background music: {Path(self.playlist[self.current_index]).name}")
            except Exception as e:
                print(f"[BG-BASS] play failed: {e}")
            return
        print("[BG] no background audio engine available")
        
    def pause(self):
        """Pause background music"""
        if self._bass_ready():
            self._bass_fade_generation += 1
            self._bass_engine.pause()
            self.is_playing = False
            self._meter_level = 0.0
            self._play_probe_pos = None
            self._play_probe_ts = None
            print("BASSmix background music paused")
            return
        self.is_playing = False
        self._meter_level = 0.0
        self._play_probe_pos = None
        self._play_probe_ts = None
        
    def stop(self):
        """Stop background music"""
        self._startup_preload_generation = int(
            getattr(self, "_startup_preload_generation", 0) or 0
        ) + 1
        self._startup_preload_in_progress = False
        self._startup_preload_resume_request = None
        if self._bass_ready():
            self._bass_fade_generation += 1
            self._bass_crossfade_generation += 1
            self._bass_engine.stop()
            self.crossfade_active = False
            self.crossfade_progress = 0.0
            self._crossfade_target_index = None
            self.is_playing = False
            self._meter_level = 0.0
            self._play_probe_pos = None
            self._play_probe_ts = None
            print("BASSmix background music stopped")
            return
        self.crossfade_active = False
        self.crossfade_progress = 0.0
        self._crossfade_target_index = None
        self.is_playing = False
        self._meter_level = 0.0
        self._play_probe_pos = None
        self._play_probe_ts = None

    def set_stop_after_current(self, enabled: bool):
        """Session-only toggle: stop at EOS instead of advancing to next track."""
        self.stop_after_current = bool(enabled)

    def apply_audio_output_change(self):
        """Apply selected output device to BG immediately (karaoke applies next track)."""
        if self._bass_ready():
            had_deck = self._bass_engine.primary is not None
            was_playing = bool(self.is_playing and self._bass_engine.is_playing())
            pos_sec, _dur_sec = self.get_playback_times()
            try:
                self._bass_engine.close()
            except Exception:
                pass
            if not self._init_bass_engine(self._bass_selected_output_name()):
                return
            if had_deck and self.playlist:
                if self.preload_current_track_paused() and pos_sec > 0.0:
                    self.seek_seconds(pos_sec)
                if was_playing:
                    self.play()
            _diag(f"[AUDIO] BASSmix BG output switched at {pos_sec:.2f}s")
            return
        
    def next_track(self):
        """Advance to next track (manual or auto-advance) - OPTIMIZED FOR INSTANT UI"""
        if not self.playlist:
            return
            
        was_playing = self.is_playing

        # Keep both decks playing during manual skips and EOS recovery. The
        # old stop()/play() path made Next sound like a hard edit even though
        # natural track endings already used the crossfade mixer.
        if was_playing:
            if self.crossfade_active:
                return
            target_index = (self.current_index + 1) % len(self.playlist)
            if self._start_crossfade(target_index=target_index):
                return
        
        # IMMEDIATE UI UPDATE - Update index and display BEFORE audio processing
        self.current_index = (self.current_index + 1) % len(self.playlist)
        
        # Update UI instantly - don't wait for audio
        if hasattr(self.parent(), 'update_bg_track_display'):
            self.parent().update_bg_track_display()
        
        # Stop current playback (including any crossfade)
        self.stop()
        
        # Start pre-caching for upcoming tracks
        QTimer.singleShot(200, self._start_artwork_precache)
        
        if was_playing:  # Auto-continue if we were playing
            self.play()
            
    def previous_track(self):
        """Go to previous track - OPTIMIZED FOR INSTANT UI"""
        if not self.playlist:
            return
            
        was_playing = self.is_playing

        if was_playing:
            if self.crossfade_active:
                return
            target_index = (self.current_index - 1) % len(self.playlist)
            if self._start_crossfade(target_index=target_index):
                return
        
        # IMMEDIATE UI UPDATE - Update index and display BEFORE audio processing
        self.current_index = (self.current_index - 1) % len(self.playlist)
        
        # Update UI instantly - don't wait for audio
        if hasattr(self.parent(), 'update_bg_track_display'):
            self.parent().update_bg_track_display()
        
        # Stop current playback
        self.stop()
        
        # Start pre-caching for upcoming tracks  
        QTimer.singleShot(200, self._start_artwork_precache)
        
        if was_playing:  # Auto-continue if we were playing
            self.play()

    def _ensure_volume_set(self):
        """Ensure volume is properly set on the pipeline"""
        self._sync_volume_from_ui_or_settings("ensure-volume")
        if self._bass_ready():
            self._bass_engine.set_master_volume(self.volume)
            self._bg_volume_diag("ensure-volume-applied", self.get_active_track_path())
            return

    def _target_volume_from_ui(self):
        """Prefer the manager's visible slider; fall back to saved setting."""
        try:
            live_volume = getattr(self.parent(), "_host_bgm_live_volume", None)
            if live_volume is not None:
                return max(0.0, min(1.0, float(live_volume)))
        except Exception:
            pass
        try:
            # Try BackgroundMusicManager's slider if the window is open
            p = self.parent()
            mgr = getattr(p, "bg_manager", None)
            if mgr is not None and hasattr(mgr, "volume_slider"):
                return max(0.0, min(1.0, mgr.volume_slider.value() / 100.0))
        except Exception:
            pass
        # Fall back to persisted setting (default 0.8)
        try:
            p = self.parent()
            return float(getattr(p, "settings", {}).get("bg_volume", 0.8))
        except Exception:
            return 0.8
            
    def set_volume(self, volume):
        """Set background music volume (0.0 to 1.0)"""
        ui_value = volume
        self.volume = max(0.0, min(1.0, volume))
        if self._bass_ready():
            self._bass_engine.set_master_volume(self.volume)
            try:
                eff = float(self._bass_engine._effective_master())
            except Exception:
                eff = self.volume
            _diag(f"[BG-VOL] ui={float(ui_value):.3f} applied={self.volume:.3f} backend=BASS master_gain={eff:.3f}")
            return
        _diag(f"[BG-VOL] ui={float(ui_value):.3f} applied={self.volume:.3f} backend=none")

    def cancel_pending_fades(self, restore_to_target: bool = True):
        """Cancel any in-flight BG fade/crossfade so stale timers cannot mute playback later."""
        if self._bass_ready():
            self._bass_fade_generation += 1
            self._bass_crossfade_generation += 1
            self.crossfade_active = False
            self.crossfade_progress = 0.0
            self._crossfade_target_index = None
            self._bass_engine.cancel_crossfade()
            self._next_preload_attempt = None
            if not restore_to_target:
                return
            try:
                target = max(0.0, min(1.0, float(self._target_volume_from_ui())))
            except Exception:
                target = max(0.0, min(1.0, float(self.volume or 0.8)))
            self.volume = target
            self._bass_engine.set_master_volume(target)
            return
        self.crossfade_active = False
        self.crossfade_progress = 0.0
        self._crossfade_target_index = None
        if restore_to_target:
            self.volume = max(0.0, min(1.0, float(self._target_volume_from_ui())))
                
    def ensure_audible(self, reason: str = ""):
        """Recover the 'flag says playing but silent' state: a karaoke-start
        fade can leave the engine paused or at master volume 0 while
        self.is_playing stays True (a stale _bass_stop_after_fade generation
        skips the pause), so resume paths that trust the flag leave silence."""
        if not self._bass_ready() or not self.is_playing:
            return
        eng = self._bass_engine
        try:
            paused = bool(eng.is_paused())
            master = float(getattr(eng, "master_volume", 1.0) or 0.0)
            really_playing = bool(eng.is_playing())
        except Exception:
            return
        if really_playing and not paused and master > 0.05:
            return
        try:
            target = float(self._target_volume_from_ui())
        except Exception:
            target = float(getattr(self, "volume", 0.65) or 0.65)
        print(f"[BG-RECOVER] flag playing but paused={int(paused)} playing={int(really_playing)} master={master:.2f} reason={reason}; restoring vol={target:.2f}")
        try:
            self._bass_fade_generation += 1  # cancel any pending stop-after-fade
            if paused or not really_playing:
                eng.set_master_volume(0.0)
                eng.bass.BASS_ChannelPlay(eng.mixer, False)
            eng.slide_master_volume(target, 500)
        except Exception as e:
            print(f"[BG-RECOVER] failed: {e}")

    def fade_out(self, duration_ms=1000):
        """Fade out background music"""
        if self._bass_ready():
            if self._bass_engine.primary is None or not self.is_playing:
                return
            self._bass_fade_generation += 1
            self._bass_crossfade_generation += 1
            self.crossfade_active = False
            self.crossfade_progress = 0.0
            self._crossfade_target_index = None
            self._bass_engine.cancel_crossfade()
            self._next_preload_attempt = None
            generation = int(self._bass_fade_generation)
            self._bass_engine.slide_master_volume(0.0, duration_ms)
            try:
                settle_ms = max(0, int(self._bass_engine.fade_settle_delay_ms()))
            except Exception:
                settle_ms = 0
            QTimer.singleShot(
                max(1, int(duration_ms) + settle_ms),
                lambda g=generation: self._bass_stop_after_fade(g),
            )
            if settle_ms:
                _diag(
                    f"[BG-FADE] output drain added duration_ms={int(duration_ms)} "
                    f"settle_ms={settle_ms}"
                )
            return
        
    def fade_in(self, target_volume=None, duration_ms=1000, allow_during_karaoke=False):
        """Fade in background music - if no target_volume, use current slider value"""

        if self._karaoke_is_active() and not allow_during_karaoke:
            print("Karaoke is active; suppressing BG fade_in()")
            return
        
        if not self.enabled:
            print("BG disabled; fade_in ignored")
            return
        transition_events.record(
            "bgm_fade_in",
            fade_ms=int(duration_ms or 0),
            during_karaoke=bool(self._karaoke_is_active()),
        )
        _ia_observe(self, "bgm")
    
        # If no target volume specified, use manager slider if open; else saved setting
        if target_volume is None:
            target_volume = self._target_volume_from_ui()
            print(f"Using target volume from UI/setting: {target_volume}")

        if bool(getattr(self, "_startup_preload_in_progress", False)):
            self._startup_preload_resume_request = (
                "fade", target_volume, duration_ms, allow_during_karaoke,
            )
            _diag("[BG-BASS] fade-in queued behind startup preload")
            return

        if self._bass_ready():
            try:
                target_volume = max(0.0, min(1.0, float(target_volume)))
                self.volume = target_volume
                current_file = self.playlist[self.current_index] if self.playlist else ""
                if current_file and not self._bg_first_play_logged:
                    self._bg_first_play_logged = True
                    _diag(f"[BG-VOLUME] first BGM file selected={Path(current_file).name!r}")
                self._bg_volume_diag("fade-in-before-preload", current_file, extra=f"target={target_volume:.3f}")
                if self._bass_engine.primary is None and not self.preload_current_track_paused():
                    return
                self._bass_fade_generation += 1
                self._refresh_bg_normalize(deck="primary")
                self._bass_engine.set_master_volume(0.0)
                self._bg_volume_diag("fade-in-before-BASS_ChannelPlay", current_file, extra=f"target={target_volume:.3f}")
                if not self._bass_engine.play():
                    print("[BG-BASS] fade_in start failed")
                    return
                self.is_playing = True
                self._bass_engine.slide_master_volume(target_volume, duration_ms)
                self._bg_volume_diag("fade-in-after-BASS_ChannelPlay", current_file, extra=f"target={target_volume:.3f} duration_ms={int(duration_ms)}")
                self._schedule_volume_state_probe("bass-fade-in")
                print(f"Starting BASSmix fade in to volume {target_volume}")
            except Exception as e:
                print(f"[BG-BASS] fade in failed: {e}")
            return
        print("[BG] fade in unavailable: no background audio engine")

        

    def _extract_artwork_sync(self, file_path):
        """Synchronous artwork extraction (for background threads)"""
        if not MutagenFile:
            return None
            
        try:
            audio_file = MutagenFile(file_path)
            if not audio_file:
                return None
                
            artwork_data = None
            
            # MP3 files (ID3 tags)
            if hasattr(audio_file, 'tags') and audio_file.tags:
                apic_keys = [key for key in audio_file.tags.keys() if key.startswith('APIC')]
                if apic_keys:
                    for key in apic_keys:
                        try:
                            frame = audio_file.tags[key]
                            if hasattr(frame, 'data') and frame.data and len(frame.data) > 100:
                                artwork_data = frame.data
                                break
                        except Exception:
                            continue
            
            # FLAC files
            elif hasattr(audio_file, 'pictures') and audio_file.pictures:
                for pic in audio_file.pictures:
                    if pic.data and len(pic.data) > 100:
                        artwork_data = pic.data
                        break
                        
            # MP4/M4A files
            elif hasattr(audio_file, 'tags') and audio_file.tags and 'covr' in audio_file.tags:
                covers = audio_file.tags['covr']
                if covers and len(covers) > 0:
                    cover_data = covers[0]
                    if hasattr(cover_data, 'data'):
                        artwork_data = cover_data.data
                    else:
                        artwork_data = bytes(cover_data)
            
            # OGG Vorbis files
            elif hasattr(audio_file, 'tags') and audio_file.tags:
                if 'METADATA_BLOCK_PICTURE' in audio_file.tags:
                    try:
                        import base64
                        import struct
                        
                        picture_b64 = audio_file.tags['METADATA_BLOCK_PICTURE'][0]
                        picture_data = base64.b64decode(picture_b64)
                        
                        if len(picture_data) >= 32:
                            offset = 4
                            mime_length = struct.unpack('>I', picture_data[offset:offset+4])[0]
                            offset += 4 + mime_length
                            desc_length = struct.unpack('>I', picture_data[offset:offset+4])[0]
                            offset += 4 + desc_length
                            offset += 16
                            data_length = struct.unpack('>I', picture_data[offset:offset+4])[0]
                            offset += 4
                            
                            if offset + data_length <= len(picture_data):
                                artwork_data = picture_data[offset:offset+data_length]
                            
                    except Exception:
                        pass
            
            if artwork_data and len(artwork_data) > 0:
                from PyQt6.QtGui import QPixmap
                from PyQt6.QtCore import QByteArray
                
                pixmap = QPixmap()
                byte_array = QByteArray(artwork_data)
                
                if pixmap.loadFromData(byte_array):
                    return pixmap
                    
        except Exception:
            pass
            
        return None

    def get_album_artwork(self, file_path):
        """Enhanced album artwork extraction with caching - OPTIMIZED VERSION"""
        
        # INSTANT RETURN: Check cache first
        if file_path in self.artwork_cache:
            return self.artwork_cache[file_path]
        
        # If not in cache, try to extract it synchronously
        artwork = self._extract_artwork_sync(file_path)
        
        if artwork and not artwork.isNull():
            # Store in cache for future instant access
            self.artwork_cache[file_path] = artwork
            self.manage_artwork_cache()  # Keep cache size reasonable
            
        return artwork

    def get_current_artwork(self):
        """Get artwork for currently playing track - OPTIMIZED VERSION"""
        if not self.playlist or self.current_index >= len(self.playlist):
            return None
            
        current_file = self.playlist[self.current_index]
        
        # Check cache first for instant return
        if current_file in self.artwork_cache:
            return self.artwork_cache[current_file]
        
        # If not cached, try to extract (this will cache it automatically)
        return self.get_album_artwork(current_file)
    
_CLEAN_CDG_CACHE = {"key": None, "threshold": None, "transparent": None, "result": None}


def _clean_cdg_near_black(image: QImage, threshold: int = 10, transparent_black: bool = False) -> QImage:
    """Clamp only CDG near-black RGB pixels to true black.

    This is intentionally narrow: CDG source frames are small, and only pixels
    whose R/G/B channels are all near black are touched. Saturated lyric colors,
    outlines, and intentionally dark colored graphics survive. When
    transparent_black is true, those same near-black background pixels become
    transparent so a subtle host-selected background can show behind lyrics.

    The result is cached for the last (frame, threshold, transparent) combo:
    each karaoke frame is cleaned once even though BOTH the output and preview
    windows call this per frame — at full-resolution frames that redundant
    second scan cost ~10 ms/frame.
    """
    if image is None or image.isNull():
        return QImage()
    try:
        threshold = max(0, min(32, int(threshold)))
    except Exception:
        threshold = 10
    if threshold <= 0 and not transparent_black:
        return image
    try:
        cache_key = int(image.cacheKey())
    except Exception:
        cache_key = None
    _cc = _CLEAN_CDG_CACHE
    if (cache_key is not None and _cc["key"] == cache_key
            and _cc["threshold"] == threshold and _cc["transparent"] == transparent_black
            and _cc["result"] is not None):
        return _cc["result"]
    def _compute():
        try:
            if image.format() == QImage.Format.Format_Indexed8:
                table = list(image.colorTable())
                if not table:
                    return image
                changed = False
                for idx, value in enumerate(table):
                    try:
                        v = int(value)
                        a = (v >> 24) & 0xFF
                        r = (v >> 16) & 0xFF
                        g = (v >> 8) & 0xFF
                        b = v & 0xFF
                    except Exception:
                        continue
                    if a and r <= threshold and g <= threshold and b <= threshold and (r or g or b or transparent_black):
                        new_a = 0 if transparent_black else a
                        new_value = (new_a << 24)
                        if new_value != v:
                            table[idx] = new_value
                            changed = True
                if changed:
                    cleaned = QImage(image)
                    cleaned.setColorTable(table)
                    return cleaned
                return image

            cleaned = image.convertToFormat(QImage.Format.Format_ARGB32)
            ptr = cleaned.bits()
            ptr.setsize(cleaned.sizeInBytes())
            buf = memoryview(ptr)
            try:
                # Vectorized near-black clamp. The per-pixel Python fallback
                # below is fine for the tiny 300x216 CDG frames the GStreamer
                # path emits, but a full-resolution RGBA frame (e.g. an MP4
                # frame, up to 4K) has millions of pixels — looping in Python
                # blocks the GUI thread for hundreds of ms per frame and
                # freezes playback. Treat each ARGB32 pixel as
                # one uint32 so the scan/rewrite stays in numpy.
                import numpy as np
                v = np.asarray(buf).view(np.uint32)
                b = v & 0xFF
                g = (v >> 8) & 0xFF
                r = (v >> 16) & 0xFF
                a = (v >> 24) & 0xFF
                mask = (a > 0) & (r <= threshold) & (g <= threshold) & (b <= threshold)
                if not transparent_black:
                    mask &= (r > 0) | (g > 0) | (b > 0)
                if not mask.any():
                    return image
                if transparent_black:
                    v[mask] = 0
                else:
                    v[mask] = a[mask].astype(np.uint32) << 24  # zero RGB, keep alpha
                return cleaned
            except Exception:
                pass
            # Fallback: pure-Python per-pixel loop (numpy unavailable).
            changed = False
            for i in range(0, len(buf), 4):
                b = int(buf[i])
                g = int(buf[i + 1])
                r = int(buf[i + 2])
                a = int(buf[i + 3])
                if a and r <= threshold and g <= threshold and b <= threshold and (r or g or b or transparent_black):
                    buf[i] = 0
                    buf[i + 1] = 0
                    buf[i + 2] = 0
                    if transparent_black:
                        buf[i + 3] = 0
                    changed = True
            return cleaned if changed else image
        except Exception:
            return image

    result = _compute()
    if cache_key is not None:
        _cc.update(key=cache_key, threshold=threshold, transparent=transparent_black, result=result)
    return result


def _scaled_karaoke_image(
    image,
    size,
    aspect_mode,
    is_cdg,
    clean_near_black: bool = True,
    black_threshold: int = 10,
    transparent_black: bool = False,
):
    """Scale a karaoke frame for display.

    CDG frames are pixel art: SmoothTransformation softens lyric edges, so CDG
    always uses nearest-style scaling. Other video frames keep the same light
    scaling path.
    """
    if is_cdg and (clean_near_black or transparent_black):
        image = _clean_cdg_near_black(image, black_threshold, transparent_black=transparent_black)
    if is_cdg:
        return image.scaled(size, aspect_mode, Qt.TransformationMode.FastTransformation)
    return image.scaled(size, aspect_mode, Qt.TransformationMode.FastTransformation)


def _install_single_buffered_widget_surfaces() -> bool:
    """Remove the macOS backing-store swap chain that the flush crash lives in.

    The crash SingWS has been chasing since 0.4.3.4 -- EXC_BAD_ACCESS at 0x0 in
    QPaintDevice::devicePixelRatio(), under QWidgetRepaintManager::flush ->
    QBackingStore::flush -- was traced by disassembling the shipped
    libqcocoa.dylib and matching it against Qt 6.9's qcocoabackingstore.mm. The
    faulting frame is inside ``blitBuffer``:

        QPainter painter(destinationBuffer->asImage());
        painter.setCompositionMode(QPainter::CompositionMode_Source);
        ... painter.device()->devicePixelRatio()      <-- device() is null

    ``QPainter::device()`` is null only when the painter never began, i.e. the
    destination buffer's QImage was unusable (empty, or its IOSurface lock
    failed). Nothing above it checks. And blitBuffer is reached from exactly one
    place:

        void QCALayerBackingStore::finalizeBackBuffer() {
            if (!m_buffers.back()->isDirty()) return;
            if (m_buffers.back() != m_buffers.front()) {
                m_buffers.back()->lock(SWWriteAccess);
                blitBuffer(m_buffers.front().get(), ..., m_buffers.back().get());

    -- the branch that only exists because the CALayer backing store keeps a
    multi-buffer swap chain. With ``SwapBehavior::SingleBuffer``,
    ``ensureBackBuffer()`` returns immediately, the chain never grows past one
    buffer, front and back are the same buffer, and that branch is dead code:
    the crashing call site becomes unreachable rather than merely less likely.

    Scope and cost: this is the *raster widget* backing store only. Qt Quick
    (ticker, transitions, rotation rail) renders through its own scene graph and
    keeps its double buffering -- see _apply_double_buffered_quick_format -- and
    mpv draws into its own NSView, so neither animated surface is affected. What
    is left single-buffered is ordinary widget painting, where the window server
    may read the surface mid-paint; on static operator chrome that is not
    visible, but SINGWS_WIDGET_SWAP=double restores Qt's default without a
    rebuild if it ever is.
    """
    if sys.platform != "darwin":
        return False
    # NOW OPT-IN. The paragraph above predicted the cost -- "the window server
    # may read the surface mid-paint" -- and assumed it would not show on
    # "static operator chrome". The operator window is not static: the queue,
    # rotation rail, level meters and BGM progress all repaint continuously,
    # and on 2026-08-09 the result was visibly torn and stale widgets on every
    # build carrying this (0.4.3.9, 0.4.4.0) and on none without it (0.4.3.6).
    # A rare intermittent crash is a worse trade than corrupted chrome every
    # night, so Qt's default double buffering wins until the real fix (a Qt
    # upgrade, or not reaching blitBuffer at all) is in place.
    # SINGWS_WIDGET_SWAP=single restores the workaround without a rebuild.
    if os.environ.get("SINGWS_WIDGET_SWAP", "").strip().lower() != "single":
        _diag("[SURFACE] widget backing store double-buffered (Qt default; set SINGWS_WIDGET_SWAP=single for the blitBuffer workaround)")
        return False
    try:
        fmt = QSurfaceFormat.defaultFormat()
        fmt.setSwapBehavior(QSurfaceFormat.SwapBehavior.SingleBuffer)
        QSurfaceFormat.setDefaultFormat(fmt)
        _diag("[SURFACE] widget backing store single-buffered (QCALayerBackingStore blit path disabled)")
        return True
    except Exception as exc:
        _diag(f"[SURFACE] could not set single-buffered widget surfaces: {exc}")
        return False


def _apply_double_buffered_quick_format(view) -> None:
    """Keep Qt Quick views on Qt's normal double buffering.

    _install_single_buffered_widget_surfaces changes the *default* surface
    format, which every window created afterwards inherits -- including these.
    The scene graph animates continuously, so it is the one place where a
    single-buffered surface could actually be seen tearing, and it does not use
    the QWidget backing store the crash lives in. Must run before the view is
    shown: the format is read when the platform window is created.
    """
    try:
        fmt = view.format()
        fmt.setSwapBehavior(QSurfaceFormat.SwapBehavior.DoubleBuffer)
        view.setFormat(fmt)
    except Exception as exc:
        _diag(f"[SURFACE] Quick view kept default swap behaviour: {exc}")


def _rect_on_attached_screen(rect: QRect) -> QRect:
    """Keep a restored window rect on a screen that actually exists now.

    Saved show-window geometry outlives the monitor it was saved on. When the
    rect no longer touches any attached screen, move it onto the primary one at
    the same size instead of restoring it into empty space -- an unreachable
    window that macOS also never assigns a valid screen.
    """
    try:
        screens = QApplication.screens() or []
        for screen in screens:
            if screen.availableGeometry().intersects(rect):
                return rect
        target = QApplication.primaryScreen()
        if target is None:
            return rect
        avail = target.availableGeometry()
        width = min(rect.width(), avail.width())
        height = min(rect.height(), avail.height())
        moved = QRect(
            avail.x() + max(0, (avail.width() - width) // 2),
            avail.y() + max(0, (avail.height() - height) // 2),
            max(1, width),
            max(1, height),
        )
        _diag(
            f"[VIDWIN] saved geometry {rect.x()},{rect.y()} {rect.width()}x{rect.height()} "
            f"is off every attached screen; restoring at "
            f"{moved.x()},{moved.y()} {moved.width()}x{moved.height()}"
        )
        return moved
    except Exception:
        return rect


def _cdg_side_fill_color(image) -> QColor:
    """Choose the dominant CDG border color for widescreen side bars."""
    try:
        if image is None or image.isNull():
            return QColor("black")
        width = max(1, int(image.width()))
        height = max(1, int(image.height()))
        samples = []
        steps = 12
        for i in range(steps + 1):
            x = min(width - 1, int(round((width - 1) * i / steps)))
            y = min(height - 1, int(round((height - 1) * i / steps)))
            samples.extend(
                (
                    image.pixelColor(x, 0),
                    image.pixelColor(x, height - 1),
                    image.pixelColor(0, y),
                    image.pixelColor(width - 1, y),
                )
            )
        counts = {}
        for color in samples:
            if color.alpha() <= 0:
                continue
            key = (color.red(), color.green(), color.blue())
            counts[key] = counts.get(key, 0) + 1
        if counts:
            red, green, blue = max(counts, key=counts.get)
            return QColor(red, green, blue)
    except Exception:
        pass
    return QColor("black")


BG_VIDEO_EXTENSIONS = {".mp4", ".m4v", ".mov"}


def scan_background_video_folder(folder: str) -> list[str]:
    """MP4 files in the configured background-video folder, sorted for a
    stable baseline order. Missing/empty folder -> [] and the caller falls
    back to the normal CDG background."""
    if not folder:
        return []
    value = str(Path(folder).expanduser())

    def scan():
        if not os.path.isdir(value):
            return []
        matches = []
        with os.scandir(value) as entries:
            for entry in entries:
                if entry.is_file() and os.path.splitext(entry.name)[1].lower() in BG_VIDEO_EXTENSIONS:
                    matches.append(entry.path)
        return sorted(matches, key=lambda p: p.lower())

    return list(_bounded_filesystem_call(
        scan, default=[], timeout_sec=0.75, label="background video folder scan"
    ) or [])


class BackgroundVideoShuffleBag:
    """Play every decorative video once per cycle without edge repeats."""

    def __init__(self, files, shuffle: bool = True, rng=None):
        self._files = list(files)
        self._shuffle = bool(shuffle)
        self._rng = rng if rng is not None else random.Random()
        self._queue: list[str] = []
        self._last: str | None = None

    def next(self) -> str | None:
        if not self._files:
            return None
        if not self._queue:
            order = list(self._files)
            if self._shuffle:
                self._rng.shuffle(order)
                if len(order) > 1 and order[0] == self._last:
                    order[0], order[-1] = order[-1], order[0]
            self._queue = order
        pick = self._queue.pop(0)
        self._last = pick
        return pick


SHOW_TRANSITION_EFFECTS = (
    "curtain_reveal", "moving_spotlights", "neon_scan", "spinning_record",
    "confetti_drop", "audio_pulse", "camera_iris", "marquee_lightbulbs",
    "color_ribbon_wipe", "star_tunnel", "mosaic_tile_reveal",
    "waveform_sweep", "jukebox_flip", "laser_fan", "film_countdown",
    "polaroid_drop",
)


class ShowTransitionShuffleBag:
    """Use every enabled show transition once before reshuffling."""

    def __init__(self, effects, rng=None):
        allowed = set(SHOW_TRANSITION_EFFECTS)
        self._effects = [str(effect) for effect in effects if str(effect) in allowed]
        self._rng = rng if rng is not None else random.Random()
        self._queue: list[str] = []
        self._last: str | None = None

    def next(self) -> str:
        if not self._effects:
            return "moving_spotlights"
        if not self._queue:
            order = list(self._effects)
            self._rng.shuffle(order)
            if len(order) > 1 and order[0] == self._last:
                order[0], order[-1] = order[-1], order[0]
            self._queue = order
        pick = self._queue.pop(0)
        self._last = pick
        return pick


class NativeLyricsBackgroundVideoPlayer(QObject):
    """Muted decorative MP4 playlist decoded inside the native mpv bridge."""

    _FADE_STEPS = 12

    def __init__(self, plugin, parent=None, *, opacity: float = 1.0):
        super().__init__(parent)
        self.plugin = plugin
        self.opacity = max(0.0, min(1.0, float(opacity)))
        self._bag = None
        self._current = ""
        self._poll_count = 0
        self._transition = ""
        self._fade_step = 0
        self._timer = QTimer(self)
        # A cheap opacity-only GPU fade. End-state polling remains at roughly
        # 4 Hz; the faster tick is active Python work only during transitions.
        self._timer.setInterval(33)
        self._timer.timeout.connect(self._poll_end)

    def start(self, files: list[str], shuffle: bool = True) -> bool:
        if not files or not callable(getattr(self.plugin, "loadBackgroundVideo", None)):
            return False
        self._bag = BackgroundVideoShuffleBag(files, shuffle=shuffle)
        if not self._advance("start"):
            return False
        self._timer.start()
        return True

    def _advance(self, reason: str, *, opacity=None) -> bool:
        path = self._bag.next() if self._bag is not None else None
        if not path:
            return False
        load_opacity = self.opacity if opacity is None else max(0.0, min(1.0, float(opacity)))
        if not self.plugin.loadBackgroundVideo(path, load_opacity):
            _diag(f"[BG-VIDEO] native load failed file={os.path.basename(path)!r}")
            return False
        self._current = path
        _diag(f"[BG-VIDEO] native playing file={os.path.basename(path)!r} reason={reason}")
        return True

    def _poll_end(self):
        try:
            self._poll_count += 1
            if self._transition == "wait_frame":
                position = int(getattr(self.plugin, "backgroundVideoPositionMs", lambda: 0)())
                if position > 0:
                    self._transition = "fade_in"
                    self._fade_step = 0
                return
            if self._transition == "fade_in":
                self._fade_step += 1
                value = self.opacity * min(1.0, self._fade_step / self._FADE_STEPS)
                self.plugin.setBackgroundVideoOpacity(value)
                if self._fade_step >= self._FADE_STEPS:
                    self._transition = ""
                return

            if self._poll_count % 8 == 0:
                position = int(getattr(self.plugin, "backgroundVideoPositionMs", lambda: 0)())
                paused = bool(getattr(self.plugin, "backgroundVideoPaused", lambda: False)())
                # Keep the frequent EOS check, but sample the healthy clock.
                # Logging it every poll group produced tens of thousands of
                # lines per show and hid the faults this diagnostic exists for.
                if self._poll_count % 240 == 0:
                    _diag(f"[BG-VIDEO] clock position_ms={position} paused={int(paused)}")
                if self.plugin.backgroundVideoAtEnd():
                    # The bridge snapshots the outgoing final frame before this
                    # one decoder loads its replacement. Keep that frame fully
                    # visible while the incoming stream reaches its first real
                    # frame, then dissolve directly into it—no black/stale gap
                    # and no second decoder competing with karaoke on Intel.
                    if self._advance("eos_crossfade", opacity=0.0):
                        self._transition = "wait_frame"
        except Exception as exc:
            _diag(f"[BG-VIDEO] native end poll failed: {exc}")

    def stop(self, reason: str = "stop"):
        self._timer.stop()
        self._transition = ""
        try:
            self.plugin.stopBackgroundVideo()
        except Exception:
            pass
        _diag(f"[BG-VIDEO] native stopped reason={reason}")
        self._current = ""

    def diagnostics(self) -> dict:
        return {"running": bool(self._current), "current": os.path.basename(self._current),
                "decoder": "native-libmpv", "renderer": "shared-gpu-texture"}


