class RenderThreadShowScreenVfx(QFrame):
    """Transparent Qt Quick transition layer for the audience show screen."""

    def __init__(self, parent=None):
        super().__init__(parent)
        from PyQt6.QtQuick import QQuickView

        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.setStyleSheet("background: transparent;")
        self._view = QQuickView()
        _apply_double_buffered_quick_format(self._view)
        self._view.setColor(QColor(0, 0, 0, 0))
        self._view.setResizeMode(QQuickView.ResizeMode.SizeRootObjectToView)

        fd, qml_path = tempfile.mkstemp(prefix="singws_show_vfx_", suffix=".qml")
        self._qml_temp_path = qml_path
        with os.fdopen(fd, "w", encoding="utf-8") as qml_file:
            qml_file.write(QML_SHOW_SCREEN_VFX_SOURCE)
        self._view.setSource(QUrl.fromLocalFile(qml_path))
        if self._view.status() == QQuickView.Status.Error:
            errors = [err.toString() for err in self._view.errors()]
            raise RuntimeError("QML show-screen VFX load error: " + (" | ".join(errors) or "unknown"))

        self._root = self._view.rootObject()
        if self._root is None:
            raise RuntimeError("QML show-screen VFX has no root object")
        try:
            self._root.nextUpCountdownFinished.connect(self._on_next_up_countdown_finished)
        except Exception:
            pass
        try:
            self._root.activeChanged.connect(self._schedule_surface_plane_update)
        except Exception:
            pass
        self._container = QWidget.createWindowContainer(self._view, self)
        # A window container is native, and Qt promotes every ancestor of a
        # native widget unless this is set. Several of these in one top-level
        # is precisely the state described in _rotation_quick_surfaces_supported
        # -- Cocoa dereferencing a released paint device on hide -- which is
        # what got Qt Quick banned on Intel macOS rather than any fault of
        # Quick's. Keep the container native and leave the ancestors alone.
        self._container.setAttribute(
            Qt.WidgetAttribute.WA_DontCreateNativeAncestors, True)
        self._container.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._container.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        layout.addWidget(self._container)
        self._update_surface_plane()

    def _on_next_up_countdown_finished(self):
        area = self.parentWidget()
        if area is not None and hasattr(area, "finish_next_up_countdown"):
            area.finish_next_up_countdown()

    def _schedule_surface_plane_update(self):
        # active changes from a QML ScriptAction. Let the scene-graph callback
        # unwind before changing the native window-container sibling order.
        QTimer.singleShot(0, self._update_surface_plane)

    def _update_surface_plane(self):
        """Raise only while animating, then lower beneath the mpv view.

        The transparent QQuickView child can still occlude the native mpv view
        after its pixels become transparent. Resizing it to zero did not change
        its native plane. Lowering the existing objects avoids the Intel crash
        risk of destroying/recreating Quick surfaces and leaves the ticker on
        its independent top plane.
        """
        try:
            active = bool(self._root.property("active"))
            if active:
                self.raise_()
                self._container.raise_()
            else:
                self._container.lower()
                self.lower()
            self.update()
            _diag(f"[SHOW-VFX] surface plane={'effect' if active else 'video'}")
        except Exception as exc:
            _diag(f"[SHOW-VFX] surface plane update failed: {exc}")

    def show_next_up(self, payload: dict, duration_sec: float = 10.0):
        payload = payload if isinstance(payload, dict) else {}
        self._root.showNextUp(
            str(payload.get("singer", "") or ""),
            str(payload.get("title", "") or ""),
            str(payload.get("artist", "") or ""),
            str(payload.get("on_deck", "") or ""),
            float(duration_sec or 10.0),
        )
        self._update_surface_plane()

    def show_singer_start(self, singer: str, title: str = "", artist: str = "", style: str = "moving_spotlights"):
        self._root.showSingerStart(
            str(singer or ""), str(title or ""), str(artist or ""), str(style or "moving_spotlights")
        )
        self._update_surface_plane()

    def show_song_outro(self, singer: str, title: str = "", artist: str = "", style: str = "moving_spotlights"):
        self._root.showSongOutro(
            str(singer or ""), str(title or ""), str(artist or ""), str(style or "moving_spotlights")
        )
        self._update_surface_plane()

    def hide_transition(self, immediate: bool = False):
        self._root.hideTransition(bool(immediate))

    def set_enabled(self, enabled):
        enabled = bool(enabled)
        self._root.setProperty("effectsEnabled", enabled)


class VideoAreaWidget(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.background_pixmap = QPixmap()
        self.karaoke_frame = QImage()
        self.karaoke_stretch_fill = False
        self.karaoke_side_fill = False
        self.karaoke_blur_fill = False
        self._karaoke_side_fill_color = QColor("black")
        self._karaoke_blur_fill_pixmap = QPixmap()
        self._karaoke_blur_fill_key = None
        self.karaoke_frame_is_cdg = False
        self._karaoke_scaled_pixmap = QPixmap()
        self._karaoke_scaled_key = None
        self._karaoke_scaled_pos = QPoint(0, 0)
        self._karaoke_frame_count = 0
        self._karaoke_scale_time_ms = 0.0
        self._idle_bg_artwork_path = ""
        self._idle_bg_artwork = QPixmap()
        self._viz_phase = 0.0
        self._viz_levels = [0.08] * 14
        self._viz_peaks = [0.12] * 14
        self._viz_audio_level = 0.0
        self._idle_paint_log_ts = 0.0
        self.background_video_pixmap = QPixmap()
        self._background_video_upload_count = 0
        self._background_video_upload_time_ms = 0.0
        self._background_video_paint_count = 0
        self._background_video_paint_time_ms = 0.0
        self._background_image_path = ""
        self._background_previous_pixmap = QPixmap()
        self._background_fade_started = 0.0
        self._background_fade_ms = 700
        self._background_forced_fade_last = 0.0
        self._background_fade_timer = QTimer(self)
        self._background_fade_timer.timeout.connect(self._tick_background_fade)
        self._next_up_overlay_payload = {}
        self._next_up_overlay_phase = ""
        self._next_up_overlay_phase_started = 0.0
        self._next_up_overlay_fade_ms = 250
        self._next_up_overlay_duration_ms = 10000
        self._next_up_overlay_hide_started = False
        self._next_up_overlay_tick_timer = QTimer(self)
        self._next_up_overlay_tick_timer.timeout.connect(self._tick_next_up_overlay)
        self._next_up_overlay_hide_timer = QTimer(self)
        self._next_up_overlay_hide_timer.setSingleShot(True)
        self._next_up_overlay_hide_timer.timeout.connect(lambda: self.hide_next_up_overlay(reason="timer"))
        self._fallback_transition_payload = {}
        self._fallback_transition_timer = QTimer(self)
        self._fallback_transition_timer.setSingleShot(True)
        self._fallback_transition_timer.timeout.connect(self._clear_fallback_transition)
        self._fallback_transition_frame_timer = QTimer(self)
        self._fallback_transition_frame_timer.setInterval(33)
        self._fallback_transition_frame_timer.timeout.connect(self.update)
        self._show_vfx_overlay = None
        self._show_vfx_enabled = True
        # Request QR shown on the show screen, bottom-right, right-aligned with
        # the ticker countdown timer. Host pushes the pixmap; None hides it.
        self._request_qr_pixmap = QPixmap()
        self._request_qr_margin = 24

    def set_show_vfx_overlay(self, overlay):
        self._show_vfx_overlay = overlay
        if overlay is not None:
            overlay.setGeometry(self.rect())
            overlay.show()
            overlay.raise_()

    def set_show_vfx_enabled(self, enabled):
        self._show_vfx_enabled = bool(enabled)
        overlay = getattr(self, "_show_vfx_overlay", None)
        if overlay is not None:
            try:
                overlay.set_enabled(self._show_vfx_enabled)
            except Exception:
                pass
        self.update()

    def finish_next_up_countdown(self):
        """Clear Next Up state as soon as its visible countdown completes.

        The QML layer performs its short exit animation; clearing the backing
        payload here prevents a stale overlay timer or surface recreation from
        putting the panel back over the request QR.
        """
        self._next_up_overlay_hide_timer.stop()
        self._next_up_overlay_tick_timer.stop()
        self._next_up_overlay_hide_started = False
        self._next_up_overlay_payload = {}
        self._next_up_overlay_phase = ""
        self._next_up_overlay_log("hidden reason=countdown_complete; QR restored")
        self.update()

    def show_singer_start_vfx(self, singer: str, title: str = "", artist: str = "", style: str = "moving_spotlights"):
        overlay = getattr(self, "_show_vfx_overlay", None)
        if overlay is None:
            # Intel uses the painter-only sequence (no countdown/native Quick
            # surface). Give its burst, hero hold, and fade enough room to feel
            # like a proper stage entrance instead of a brief title card.
            self._show_fallback_transition(
                "NOW SINGING", singer, title, artist, duration_ms=3600
            )
            return True
        try:
            overlay.show_singer_start(singer, title, artist, style)
            return True
        except Exception as exc:
            _diag(f"[SHOW-VFX] singer-start failed: {exc}")
            return False

    def show_song_outro_vfx(self, singer: str, title: str = "", artist: str = "", style: str = "moving_spotlights"):
        if not bool(getattr(self, "_show_vfx_enabled", True)):
            return False
        overlay = getattr(self, "_show_vfx_overlay", None)
        if overlay is None:
            self._show_fallback_transition("APPLAUSE!", singer, title, artist)
            return True
        try:
            overlay.show_song_outro(singer, title, artist, style)
            return True
        except Exception as exc:
            _diag(f"[SHOW-VFX] song-outro failed: {exc}")
            return False

    def _show_fallback_transition(
        self,
        heading: str,
        singer: str,
        title: str = "",
        artist: str = "",
        duration_ms: int = 2400,
    ):
        self._fallback_transition_payload = {
            "heading": str(heading or ""),
            "singer": str(singer or ""),
            "title": str(title or ""),
            "artist": str(artist or ""),
            "started_at": time.monotonic(),
            "duration_ms": max(500, int(duration_ms)),
            "burst": bool(getattr(self, "_show_vfx_enabled", True)),
        }
        self._set_overlay_suppresses_mpv(True)
        self.update()
        self._fallback_transition_frame_timer.start()
        self._fallback_transition_timer.start(max(500, int(duration_ms)))

    def _set_overlay_suppresses_mpv(self, active: bool):
        """mpv's native surface would otherwise cover this painted overlay."""
        try:
            window = self.parent()
            owner = getattr(window, "_external_owner", None) if window is not None else None
            if owner is not None and hasattr(owner, "_suppress_mpv_hosts_for_overlay"):
                owner._suppress_mpv_hosts_for_overlay(
                    f"fallback_transition:{id(self)}", bool(active)
                )
        except Exception:
            pass  # never let presentation bookkeeping break the transition

    def _clear_fallback_transition(self):
        self._fallback_transition_frame_timer.stop()
        self._fallback_transition_payload = {}
        self._set_overlay_suppresses_mpv(False)
        self.update()

    def _draw_fallback_transition(self, painter: QPainter):
        payload = getattr(self, "_fallback_transition_payload", {}) or {}
        if not payload:
            return
        elapsed = max(0.0, time.monotonic() - float(payload.get("started_at", time.monotonic())))
        duration_sec = max(0.5, float(payload.get("duration_ms", 2400) or 2400) / 1000.0)
        painter.save()
        # Ease away over the final half-second instead of disappearing on the
        # timer edge. The countdown-free entrance gets a longer readable hold.
        exit_progress = max(0.0, min(1.0, (elapsed - (duration_sec - 0.55)) / 0.55))
        painter.setOpacity(1.0 - (exit_progress * exit_progress))
        backdrop_alpha = max(0, min(225, int(225 * min(1.0, elapsed / 0.16))))
        painter.fillRect(self.rect(), QColor(4, 6, 15, backdrop_alpha))
        # Intel-safe explosion: painter-only flash, shockwave, and radial
        # confetti. This replaces the native Qt Quick child surface that was
        # removed after real-show crashes on older Macs.
        cx = self.width() * 0.5
        cy = self.height() * 0.46
        burst_t = min(1.0, elapsed / 1.05)
        flash_alpha = max(0, int(170 * (1.0 - min(1.0, elapsed / 0.38))))
        if bool(payload.get("burst", True)) and flash_alpha:
            painter.fillRect(self.rect(), QColor(255, 245, 190, flash_alpha))
        wave_radius = min(self.width(), self.height()) * (0.05 + 0.58 * burst_t)
        if bool(payload.get("burst", True)):
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.setPen(QPen(QColor(246, 201, 69, max(0, int(230 * (1.0 - burst_t)))), max(2, int(self.height() * 0.009))))
            painter.drawEllipse(QPointF(cx, cy), wave_radius, wave_radius)
            colors = (QColor("#F6C945"), QColor("#FF5D8F"), QColor("#7FDBFF"), QColor("#B388FF"), QColor("#FFFFFF"))
            for i in range(30):
                angle = (i / 30.0) * math.tau + (i % 4) * 0.11
                distance = min(self.width(), self.height()) * (0.10 + 0.52 * burst_t) * (0.72 + (i % 5) * 0.07)
                px = cx + math.cos(angle) * distance
                py = cy + math.sin(angle) * distance + burst_t * burst_t * self.height() * 0.10
                size = max(4, int(self.height() * (0.010 + (i % 3) * 0.004)))
                color = QColor(colors[i % len(colors)])
                color.setAlpha(max(0, int(255 * (1.0 - max(0.0, burst_t - 0.62) / 0.38))))
                painter.setPen(Qt.PenStyle.NoPen)
                painter.setBrush(color)
                painter.drawEllipse(QPointF(px, py), size, size)
        width = max(120, int(self.width() * 0.88))
        left = (self.width() - width) // 2
        center_y = self.height() // 2
        heading_font = QFont()
        heading_font.setBold(True)
        heading_font.setPixelSize(max(11, int(self.height() * 0.065)))
        singer_font = QFont()
        singer_font.setBold(True)
        singer_font.setPixelSize(max(18, int(self.height() * 0.16)))
        detail_font = QFont()
        detail_font.setBold(True)
        detail_font.setPixelSize(max(10, int(self.height() * 0.055)))
        painter.setFont(heading_font)
        painter.setPen(QColor("#F6C945"))
        painter.drawText(
            QRect(left, center_y - int(self.height() * 0.25), width, int(self.height() * 0.10)),
            Qt.AlignmentFlag.AlignCenter,
            str(payload.get("heading", "") or ""),
        )
        painter.setFont(singer_font)
        painter.setPen(QColor("white"))
        painter.drawText(
            QRect(left, center_y - int(self.height() * 0.13), width, int(self.height() * 0.22)),
            Qt.AlignmentFlag.AlignCenter,
            str(payload.get("singer", "") or ""),
        )
        detail = str(payload.get("title", "") or "")
        artist = str(payload.get("artist", "") or "")
        if artist and detail:
            detail = f"{detail}  •  {artist}"
        elif artist:
            detail = artist
        painter.setFont(detail_font)
        painter.setPen(QColor("#D8D1ED"))
        painter.drawText(
            QRect(left, center_y + int(self.height() * 0.10), width, int(self.height() * 0.12)),
            Qt.AlignmentFlag.AlignCenter,
            detail,
        )
        painter.restore()

    def set_request_qr(self, pixmap):
        """Set (or clear with None) the request QR painted on the show screen.
        The host builds it from the network request link and pushes it here."""
        if pixmap is None or (hasattr(pixmap, "isNull") and pixmap.isNull()):
            had = not self._request_qr_pixmap.isNull()
            self._request_qr_pixmap = QPixmap()
            if had:
                self.update()
            return
        self._request_qr_pixmap = pixmap if isinstance(pixmap, QPixmap) else QPixmap(pixmap)
        self.update()

    def _ticker_timer_right_margin(self) -> int:
        """The ticker preset's right_margin (px): the QR's right edge aligns to
        where the countdown timer text ends, so the QR sits by the song
        duration. Falls back to the default margin if unavailable."""
        try:
            vw = self.parent()
            owner = getattr(vw, "_external_owner", None) if vw is not None else None
            if owner is None and vw is not None:
                owner = vw.parent()
            settings = getattr(owner, "settings", {}) if owner is not None else {}
            idx = int(settings.get("ticker_size_index", TICKER_SIZE_DEFAULT_INDEX))
            idx = max(0, min(len(TICKER_SIZE_PRESETS) - 1, idx))
            return int(TICKER_SIZE_PRESETS[idx][3])
        except Exception:
            return self._request_qr_margin

    def _draw_request_qr(self, painter: QPainter):
        pm = self._request_qr_pixmap
        if pm.isNull() or self.width() <= 120 or self.height() <= 120:
            return
        # Scale the QR responsively with the window (cap so it stays a tasteful
        # corner badge), then align its right edge to the timer and pin it to
        # the bottom of the video area (just above the ticker).
        target = max(72, min(180, int(self.height() * 0.20)))
        scaled = pm.scaled(
            target, target,
            Qt.AspectRatioMode.KeepAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
        right_margin = self._ticker_timer_right_margin()
        x = self.width() - right_margin - scaled.width()
        y = self.height() - self._request_qr_margin - scaled.height()
        x = max(self._request_qr_margin, x)
        painter.drawPixmap(int(x), int(y), scaled)

    def set_background_video_frame(self, image):
        """Live MP4 background frame (behind CDG lyrics). None clears it and
        the widget falls back to the normal background pixmap."""
        if image is None or (hasattr(image, "isNull") and image.isNull()):
            had = not self.background_video_pixmap.isNull()
            self.background_video_pixmap = QPixmap()
            if had:
                self.update()
            return
        t0 = time.perf_counter()
        self.background_video_pixmap = QPixmap.fromImage(image) if isinstance(image, QImage) else QPixmap(image)
        self._background_video_upload_count += 1
        self._background_video_upload_time_ms += (time.perf_counter() - t0) * 1000.0
        self.update()

    def _draw_background_video_pixmap(self, painter: QPainter, pixmap: QPixmap):
        """Stretch the decorative video edge-to-edge without an allocation.

        The background layer is decorative and already decoded to a small
        working size. Let QPainter stretch it during the draw instead of
        materializing a new Full HD pixmap every video frame.
        """
        if pixmap.isNull():
            return
        painter.drawPixmap(self.rect(), pixmap, pixmap.rect())

    def set_background_image(self, image_path):
        old_pixmap = QPixmap(self.background_pixmap) if not self.background_pixmap.isNull() else QPixmap()
        old_path = str(getattr(self, "_background_image_path", "") or "")
        if image_path and os.path.exists(image_path):
            new_pixmap = QPixmap(image_path)
        else:
            new_pixmap = QPixmap()
        new_path = str(image_path or "")
        path_changed = bool(new_path and new_path != old_path)
        pixmap_changed = True
        try:
            pixmap_changed = int(new_pixmap.cacheKey()) != int(self.background_pixmap.cacheKey())
        except Exception:
            pass
        self.background_pixmap = new_pixmap
        self._background_image_path = new_path
        if path_changed or pixmap_changed:
            self._background_previous_pixmap = old_pixmap
            self._background_fade_started = time.monotonic()
            if not self._background_fade_timer.isActive():
                self._background_fade_timer.start(33)
        elif self._background_fade_timer.isActive():
            self._background_fade_timer.stop()
            self._background_previous_pixmap = QPixmap()
        self.update()

    def fade_background_from_black(self, *, min_interval_sec: float = 0.35):
        if self.background_pixmap.isNull():
            return
        now = time.monotonic()
        try:
            if (now - float(getattr(self, "_background_forced_fade_last", 0.0) or 0.0)) < float(min_interval_sec):
                return
        except Exception:
            pass
        self._background_forced_fade_last = now
        self._background_previous_pixmap = QPixmap()
        self._background_fade_started = now
        if not self._background_fade_timer.isActive():
            self._background_fade_timer.start(33)
        self.update()

    def _tick_background_fade(self):
        if self._background_fade_alpha() >= 1.0:
            try:
                self._background_fade_timer.stop()
            except Exception:
                pass
            self._background_previous_pixmap = QPixmap()
        self.update()

    def _background_fade_alpha(self) -> float:
        started = float(getattr(self, "_background_fade_started", 0.0) or 0.0)
        if started <= 0:
            return 1.0
        fade_ms = max(1.0, float(getattr(self, "_background_fade_ms", 700) or 700))
        return min(1.0, max(0.0, ((time.monotonic() - started) * 1000.0) / fade_ms))

    def _is_live_karaoke_active(self) -> bool:
        try:
            vw = self.parent()
            owner = getattr(vw, "_external_owner", None) if vw is not None else None
            if owner is not None and bool(getattr(owner, "karaoke_playing", False)):
                return True
            # The show window flips idle=False as soon as playback starts.
            # Treat that as active even before the first frame arrives so a
            # transient empty frame/surface rebuild cannot flash the idle BG.
            if vw is not None and not bool(getattr(vw, "idle", True)):
                return True
        except Exception:
            pass
        return False

    def set_karaoke_frame(
        self,
        image,
        stretch_fill: bool = False,
        is_cdg: bool = False,
        side_fill: bool = False,
        blur_fill: bool = False,
    ):
        # QImage is implicitly shared; avoid copying here. Scaling is cached per
        # frame/size/display mode so fullscreen paints only blit an already-scaled
        # pixmap instead of redoing CDG image processing every repaint.
        self.karaoke_frame = image if image is not None and not image.isNull() else QImage()
        self.karaoke_stretch_fill = bool(stretch_fill)
        self.karaoke_frame_is_cdg = bool(is_cdg)
        self.karaoke_side_fill = bool(side_fill and is_cdg and not stretch_fill)
        self.karaoke_blur_fill = bool(blur_fill and is_cdg and not stretch_fill)
        self._karaoke_side_fill_color = (
            _cdg_side_fill_color(self.karaoke_frame)
            if self.karaoke_side_fill else QColor("black")
        )
        self._ensure_karaoke_scaled_pixmap()
        self.update()

    def clear_karaoke_frame(self):
        self.karaoke_frame = QImage()
        self._karaoke_scaled_pixmap = QPixmap()
        self._karaoke_scaled_key = None
        self.update()

    def _next_up_overlay_log(self, message: str):
        try:
            _diag(f"[NEXT-UP-OVERLAY] {message}")
        except Exception:
            try:
                print(f"[NEXT-UP-OVERLAY] {message}")
            except Exception:
                pass

    def _start_next_up_overlay_hide_timer(self, reason: str = "visible"):
        if not self._next_up_overlay_payload or self._next_up_overlay_hide_started:
            return
        self._next_up_overlay_hide_started = True
        duration_ms = max(1000, int(getattr(self, "_next_up_overlay_duration_ms", 10000) or 10000))
        self._next_up_overlay_hide_timer.stop()
        self._next_up_overlay_hide_timer.start(duration_ms)
        self._next_up_overlay_log(
            f"hide timer started reason={reason} duration_ms={duration_ms} payload={self._next_up_overlay_payload!r}"
        )

    def next_up_overlay_remaining_sec(self) -> float:
        try:
            if self._next_up_overlay_hide_timer.isActive():
                return max(1.0, float(self._next_up_overlay_hide_timer.remainingTime()) / 1000.0)
            return max(1.0, float(getattr(self, "_next_up_overlay_duration_ms", 10000) or 10000) / 1000.0)
        except Exception:
            return 10.0

    def show_next_up_overlay(self, payload: dict, duration_sec: float = 10.0, *, reason: str = "show"):
        if not isinstance(payload, dict) or not str(payload.get("singer", "") or "").strip():
            self.hide_next_up_overlay(immediate=True, reason="invalid_payload")
            return
        self._next_up_overlay_payload = dict(payload)
        self._next_up_overlay_phase = "fade_in"
        self._next_up_overlay_phase_started = time.monotonic()
        try:
            duration_ms = int(max(1.0, min(60.0, float(duration_sec or 10.0))) * 1000)
        except Exception:
            duration_ms = 10000
        self._next_up_overlay_duration_ms = duration_ms
        # Arm a widget-side deadline immediately.  The QML completion signal is
        # still the preferred finish path, but it can be delayed when the render
        # thread is saturated (notably during show startup on slower Macs).
        # Keeping this independent watchdog also prevents stale/stacked overlays.
        self._next_up_overlay_hide_started = True
        self._next_up_overlay_hide_timer.stop()
        self._next_up_overlay_hide_timer.start(
            duration_ms + max(1, int(getattr(self, "_next_up_overlay_fade_ms", 250) or 250))
        )
        if not self._next_up_overlay_tick_timer.isActive():
            self._next_up_overlay_tick_timer.start(33)
        overlay = getattr(self, "_show_vfx_overlay", None)
        if overlay is not None and bool(getattr(self, "_show_vfx_enabled", True)):
            try:
                overlay.show_next_up(self._next_up_overlay_payload, duration_sec)
            except Exception as exc:
                _diag(f"[SHOW-VFX] next-up failed; using painter fallback: {exc}")
                self._show_vfx_overlay = None
        self._next_up_overlay_log(f"show requested reason={reason} duration_ms={duration_ms} payload={self._next_up_overlay_payload!r}")
        self.update()

    def hide_next_up_overlay(self, immediate: bool = False, reason: str = "unknown"):
        try:
            self._next_up_overlay_hide_timer.stop()
        except Exception:
            pass
        self._next_up_overlay_hide_started = False
        self._next_up_overlay_log(f"hide requested reason={reason} immediate={int(bool(immediate))}")
        overlay = getattr(self, "_show_vfx_overlay", None)
        if overlay is not None:
            try:
                overlay.hide_transition(immediate=bool(immediate))
            except Exception:
                pass
        if immediate or not self._next_up_overlay_payload:
            self._next_up_overlay_payload = {}
            self._next_up_overlay_phase = ""
            try:
                self._next_up_overlay_tick_timer.stop()
            except Exception:
                pass
            self.update()
            return
        self._next_up_overlay_phase = "fade_out"
        self._next_up_overlay_phase_started = time.monotonic()
        if not self._next_up_overlay_tick_timer.isActive():
            self._next_up_overlay_tick_timer.start(33)
        self.update()

    def _tick_next_up_overlay(self):
        if not self._next_up_overlay_payload:
            self._next_up_overlay_tick_timer.stop()
            return
        self.update()

    def _next_up_overlay_alpha(self) -> float:
        if not self._next_up_overlay_payload:
            return 0.0
        phase = str(self._next_up_overlay_phase or "")
        elapsed_ms = (time.monotonic() - float(self._next_up_overlay_phase_started or 0.0)) * 1000.0
        fade_ms = max(1.0, float(self._next_up_overlay_fade_ms or 250))
        if phase == "fade_in":
            alpha = min(1.0, max(0.0, elapsed_ms / fade_ms))
            if alpha >= 1.0:
                self._next_up_overlay_phase = "hold"
                self._next_up_overlay_log(f"actually visible/rendered duration_ms={int(getattr(self, '_next_up_overlay_duration_ms', 10000) or 10000)}")
                self._start_next_up_overlay_hide_timer("fade_in_complete")
            return alpha
        if phase == "fade_out":
            alpha = 1.0 - min(1.0, max(0.0, elapsed_ms / fade_ms))
            if alpha <= 0.0:
                self._next_up_overlay_log("hidden reason=fade_out_complete")
                self._next_up_overlay_payload = {}
                self._next_up_overlay_phase = ""
                try:
                    self._next_up_overlay_tick_timer.stop()
                except Exception:
                    pass
                return 0.0
            return alpha
        self._start_next_up_overlay_hide_timer("hold_paint")
        return 1.0

    def _draw_background_pixmap(self, painter: QPainter, pixmap: QPixmap):
        """Stretch the show image over the whole video area.

        The video area is already the window minus the ticker (they are
        siblings in the show window's vertical layout), so filling this
        widget's rect is exactly "window minus ticker space". Aspect ratio is
        deliberately ignored: letterboxing show art left black bars that read
        as a broken background on stage, and the operator wants the artwork
        edge to edge. The slides are authored for this, so the small vertical
        compression from the ticker's height is accepted.
        """
        if pixmap.isNull():
            return
        pm = pixmap.scaled(
            self.size(),
            Qt.AspectRatioMode.IgnoreAspectRatio,
            Qt.TransformationMode.SmoothTransformation
        )
        painter.drawPixmap(0, 0, pm)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._karaoke_scaled_key = None
        if not self.karaoke_frame.isNull():
            self._ensure_karaoke_scaled_pixmap()
        overlay = getattr(self, "_show_vfx_overlay", None)
        if overlay is not None:
            overlay.setGeometry(self.rect())
            overlay.raise_()

    def _cdg_near_black_settings(self) -> tuple[bool, int]:
        try:
            vw = self.parent()
            owner = getattr(vw, "_external_owner", None) if vw is not None else None
            if owner is None and vw is not None:
                owner = vw.parent()
            settings = getattr(owner, "settings", {}) if owner is not None else {}
            enabled = bool(settings.get("cdg_near_black_cleanup", True))
            threshold = int(settings.get("cdg_near_black_threshold", 10) or 10)
            return enabled, threshold
        except Exception:
            return True, 10

    def _lyrics_background_opacity(self) -> float:
        try:
            vw = self.parent()
            owner = getattr(vw, "_external_owner", None) if vw is not None else None
            if owner is None and vw is not None:
                owner = vw.parent()
            settings = getattr(owner, "settings", {}) if owner is not None else {}
            value = float(settings.get("lyrics_background_video_opacity", 0) or 0)
            return max(0.0, min(1.0, value / 100.0))
        except Exception:
            return 0.0

    def _ensure_karaoke_scaled_pixmap(self):
        if self.karaoke_frame.isNull() or self.width() <= 0 or self.height() <= 0:
            self._karaoke_scaled_pixmap = QPixmap()
            self._karaoke_scaled_key = None
            return
        try:
            image_key = int(self.karaoke_frame.cacheKey())
        except Exception:
            image_key = id(self.karaoke_frame)
        key = (
            image_key,
            int(self.width()),
            int(self.height()),
            bool(self.karaoke_stretch_fill),
            bool(self.karaoke_frame_is_cdg),
            self._cdg_near_black_settings() if bool(self.karaoke_frame_is_cdg) else (False, 0),
            round(self._lyrics_background_opacity(), 3) if bool(self.karaoke_frame_is_cdg) else 0.0,
        )
        if key == self._karaoke_scaled_key and not self._karaoke_scaled_pixmap.isNull():
            return
        mode = (
            Qt.AspectRatioMode.IgnoreAspectRatio
            if bool(self.karaoke_stretch_fill)
            else Qt.AspectRatioMode.KeepAspectRatio
        )
        t0 = time.perf_counter()
        scaled = _scaled_karaoke_image(
            self.karaoke_frame,
            self.size(),
            mode,
            bool(self.karaoke_frame_is_cdg),
            *self._cdg_near_black_settings(),
            transparent_black=bool(self.karaoke_frame_is_cdg and self._lyrics_background_opacity() > 0.0),
        )
        self._karaoke_scaled_pixmap = QPixmap.fromImage(scaled)
        self._karaoke_scaled_pos = QPoint(
            (self.width() - self._karaoke_scaled_pixmap.width()) // 2,
            (self.height() - self._karaoke_scaled_pixmap.height()) // 2,
        )
        self._karaoke_scaled_key = key
        self._karaoke_frame_count += 1
        self._karaoke_scale_time_ms += (time.perf_counter() - t0) * 1000.0
        if self._karaoke_frame_count % 300 == 0:
            try:
                avg = self._karaoke_scale_time_ms / max(1, self._karaoke_frame_count)
                _diag(f"[CDG-RENDER] frames={self._karaoke_frame_count} avg_scale_ms={avg:.3f}")
                _perf_log_if_slow("cdg_frame_render", avg)
            except Exception:
                pass

    def _ensure_karaoke_blur_fill_pixmap(self):
        """Widescreen bars filled with an ambient blur of the CDG picture.

        The colour side fill draws the disc's own background, which is black on
        most discs and therefore invisible. This mode is the visible-everywhere
        alternative: downscale the frame to a handful of pixels and let the
        smooth upscale be the blur, which costs one small scale per frame
        instead of a real convolution.
        """
        if self.karaoke_frame.isNull() or self.width() <= 0 or self.height() <= 0:
            self._karaoke_blur_fill_pixmap = QPixmap()
            self._karaoke_blur_fill_key = None
            return
        try:
            image_key = int(self.karaoke_frame.cacheKey())
        except Exception:
            image_key = id(self.karaoke_frame)
        key = (image_key, int(self.width()), int(self.height()))
        if key == self._karaoke_blur_fill_key and not self._karaoke_blur_fill_pixmap.isNull():
            return
        tiny = self.karaoke_frame.scaled(
            24, 18,
            Qt.AspectRatioMode.IgnoreAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
        blurred = tiny.scaled(
            self.size(),
            Qt.AspectRatioMode.IgnoreAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
        pixmap = QPixmap(self.size())
        pixmap.fill(QColor("black"))
        p = QPainter(pixmap)
        # Dimmed so the bars read as ambience beside the lyrics, matching the
        # mpv shader's fill.
        p.setOpacity(0.88)
        p.drawPixmap(0, 0, QPixmap.fromImage(blurred))
        p.end()
        self._karaoke_blur_fill_pixmap = pixmap
        self._karaoke_blur_fill_key = key

    def set_audio_level(self, level: float):
        try:
            self._viz_audio_level = max(0.0, min(1.0, float(level)))
        except Exception:
            self._viz_audio_level = 0.0

    def advance_visualizer(self, active: bool):
        """Beat-reactive but lightweight bar animation for idle BG now-playing card."""
        if active:
            amp = max(0.0, min(1.0, float(self._viz_audio_level)))
            # Decay between meter packets to keep motion smooth.
            self._viz_audio_level = max(0.0, self._viz_audio_level * 0.88)

            # Faster phase movement at higher energy.
            self._viz_phase = (self._viz_phase + (0.12 + amp * 0.55)) % 10000.0

            for i, old in enumerate(self._viz_levels):
                wave1 = 0.5 + 0.5 * math.sin(self._viz_phase + (i * 0.60))
                wave2 = 0.5 + 0.5 * math.sin((self._viz_phase * 0.72) + (i * 1.05))
                shape = (0.62 * wave1) + (0.38 * wave2)
                target = 0.05 + (0.08 + 0.87 * shape) * max(0.08, amp)
                lvl = (old * 0.70) + (target * 0.30)
                self._viz_levels[i] = lvl

                # Peak hold cap: rises instantly, falls slowly.
                pk = self._viz_peaks[i] if i < len(self._viz_peaks) else lvl
                if lvl >= pk:
                    pk = min(1.0, lvl)
                else:
                    pk = max(0.04, pk - 0.018)
                self._viz_peaks[i] = pk
        else:
            self._viz_audio_level = 0.0
            for i, old in enumerate(self._viz_levels):
                lvl = max(0.02, old * 0.84)
                self._viz_levels[i] = lvl
                pk = self._viz_peaks[i] if i < len(self._viz_peaks) else lvl
                self._viz_peaks[i] = max(lvl, pk * 0.92)

    def _get_idle_bg_overlay_info(self):
        """Return overlay payload when karaoke is idle and BG music is actively playing."""
        try:
            vw = self.parent()
            if vw is None or not bool(getattr(vw, "idle", False)):
                return None

            owner = getattr(vw, "_external_owner", None)
            if owner is None:
                owner = vw.parent()

            bg = getattr(owner, "bg_music", None)
            if bg is None or not bool(getattr(bg, "is_playing", False)):
                return None

            playlist = getattr(bg, "playlist", None) or []
            idx = int(getattr(bg, "current_index", -1))
            if not playlist or idx < 0 or idx >= len(playlist):
                return None

            path = str(playlist[idx])
            stem = Path(path).stem
            artist = ""
            title = stem
            if " - " in stem:
                artist, title = stem.split(" - ", 1)
                artist = artist.strip()
                title = title.strip()
            else:
                title = stem.strip()

            if path != self._idle_bg_artwork_path:
                self._idle_bg_artwork_path = path
                self._idle_bg_artwork = QPixmap()
                try:
                    art = bg.get_album_artwork(path)
                    if art is not None and not art.isNull():
                        self._idle_bg_artwork = art
                except Exception:
                    pass

            return {
                "title": title or "",
                "artist": artist or "",
                "artwork": self._idle_bg_artwork,
            }
        except Exception:
            return None

    def _draw_idle_bg_overlay(self, painter: QPainter, info: dict):
        w = self.width()
        h = self.height()
        if w <= 120 or h <= 120:
            return

        card_w = min(int(w * 0.46), 680)
        card_h = min(int(h * 0.22), 210)
        margin = 18
        card_x = margin
        card_y = max(4, h - card_h - 6)

        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)

        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(0, 0, 0, 170))
        painter.drawRoundedRect(card_x, card_y, card_w, card_h, 16, 16)

        pad = 12
        art_size = max(0, card_h - pad * 2)
        art = info.get("artwork")
        has_art = art is not None and not art.isNull()

        text_x = card_x + pad
        if has_art:
            art_pm = art.scaled(
                art_size,
                art_size,
                Qt.AspectRatioMode.KeepAspectRatioByExpanding,
                Qt.TransformationMode.SmoothTransformation,
            )
            painter.setBrush(QColor(20, 20, 20, 220))
            painter.drawRoundedRect(card_x + pad, card_y + pad, art_size, art_size, 10, 10)
            painter.drawPixmap(card_x + pad, card_y + pad, art_pm)
            text_x = card_x + pad + art_size + 12

        text_w = (card_x + card_w - pad) - text_x
        if text_w <= 40:
            painter.restore()
            return

        title = str(info.get("title", "") or "")
        artist = str(info.get("artist", "") or "")

        title_font = painter.font()
        title_font.setBold(True)
        title_font.setPointSize(max(11, int(card_h * 0.20)))

        artist_font = painter.font()
        artist_font.setBold(False)
        artist_font.setPointSize(max(9, int(card_h * 0.14)))

        title_metrics = QFontMetrics(title_font)
        artist_metrics = QFontMetrics(artist_font)

        title_text = title_metrics.elidedText(title, Qt.TextElideMode.ElideRight, text_w)
        artist_text = artist_metrics.elidedText(artist, Qt.TextElideMode.ElideRight, text_w)

        # Keep text in upper half so visualizer has its own lane below.
        top_y = card_y + pad + 2
        title_y = top_y + title_metrics.ascent()
        artist_y = title_y + max(2, int(card_h * 0.02)) + artist_metrics.ascent()

        painter.setPen(QColor("#F4F4F4"))
        painter.setFont(title_font)
        painter.drawText(text_x, title_y, title_text)

        if artist_text:
            painter.setPen(QColor("#C8C8C8"))
            painter.setFont(artist_font)
            painter.drawText(text_x, artist_y, artist_text)

        # Lightweight visualizer inside the same card (separate lower lane).
        bar_area_h = max(24, int(card_h * 0.33))
        bar_area_y = card_y + card_h - pad - bar_area_h
        bar_area_x = text_x
        bar_area_w = text_w
        if bar_area_w > 60:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QColor(255, 255, 255, 22))
            painter.drawRoundedRect(bar_area_x, bar_area_y, bar_area_w, bar_area_h, 6, 6)

            levels = self._viz_levels or [0.08] * 14
            bar_count = len(levels)
            gap = 3
            usable_w = max(1, bar_area_w - (gap * (bar_count - 1)) - 4)
            bar_w = max(2, usable_w // bar_count)
            max_h = max(6, bar_area_h - 6)
            x = bar_area_x + 2

            peaks = self._viz_peaks if hasattr(self, "_viz_peaks") else levels
            for i, lv in enumerate(levels):
                v = max(0.03, min(1.0, float(lv)))
                h_px = max(3, int(max_h * v))
                y = bar_area_y + bar_area_h - h_px - 2
                painter.setBrush(QColor(245, 245, 245, 215))
                painter.drawRoundedRect(int(x), int(y), int(bar_w), int(h_px), 2, 2)

                # Peak-hold cap
                try:
                    pv = max(v, min(1.0, float(peaks[i])))
                except Exception:
                    pv = v
                py = bar_area_y + bar_area_h - max(2, int(max_h * pv)) - 2
                painter.setBrush(QColor(255, 255, 255, 245))
                painter.drawRoundedRect(int(x), int(py), int(bar_w), 2, 1, 1)

                x += bar_w + gap

        painter.restore()

    def _draw_next_up_overlay(self, painter: QPainter):
        if (getattr(self, "_show_vfx_overlay", None) is not None
                and bool(getattr(self, "_show_vfx_enabled", True))):
            return
        payload = self._next_up_overlay_payload if isinstance(self._next_up_overlay_payload, dict) else {}
        if not payload:
            return
        alpha = self._next_up_overlay_alpha()
        if alpha <= 0.0:
            return

        w = self.width()
        h = self.height()
        if w <= 180 or h <= 160:
            return

        singer = str(payload.get("singer", "") or "").strip()
        title = str(payload.get("title", "") or "").strip()
        artist = str(payload.get("artist", "") or "").strip()
        on_deck = str(payload.get("on_deck", "") or "").strip()
        if on_deck.lower() in {"none", "null", "nil", "n/a", "na", "-", "—"}:
            on_deck = ""
        if not singer:
            return

        panel_w = min(int(w * 0.84), 1100)
        panel_h_ratio = 0.58 if on_deck else 0.50
        panel_h_max = 500 if on_deck else 420
        panel_h_min = 300 if on_deck else 260
        panel_h = min(int(h * panel_h_ratio), panel_h_max)
        panel_h = max(panel_h_min, panel_h)
        x = int((w - panel_w) / 2)
        y = int((h - panel_h) / 2)
        pad = max(24, int(panel_w * 0.055))
        text_w = max(80, panel_w - pad * 2)

        def a(value: int) -> int:
            return max(0, min(255, int(value * alpha)))

        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)

        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(0, 0, 0, a(96)))
        painter.drawRoundedRect(QRectF(x + 10, y + 14, panel_w, panel_h), 22, 22)
        painter.setBrush(QColor(1, 2, 6, a(188)))
        painter.drawRoundedRect(QRectF(x, y, panel_w, panel_h), 20, 20)

        try:
            accent = QColor(_v("accent_bright"))
        except Exception:
            accent = QColor("#8B5CF6")
        accent.setAlpha(a(255))

        label_font = painter.font()
        label_font.setBold(True)
        label_font.setPointSize(max(18, int(panel_h * 0.074)))

        singer_font = painter.font()
        singer_font.setBold(True)
        singer_font.setPointSize(max(42, int(panel_h * 0.168)))

        title_font = painter.font()
        title_font.setBold(True)
        title_font.setPointSize(max(26, int(panel_h * 0.105)))

        artist_font = painter.font()
        artist_font.setBold(False)
        artist_font.setPointSize(max(22, int(panel_h * 0.082)))

        deck_font = painter.font()
        deck_font.setBold(True)
        deck_font.setPointSize(max(18, int(panel_h * 0.062)))

        y_cursor = y + pad

        painter.setFont(label_font)
        label_fm = QFontMetrics(label_font)
        painter.setPen(QColor(255, 255, 255, a(210)))
        painter.drawText(QRect(x + pad, y_cursor, text_w, label_fm.height() + 6),
                         Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter, "NEXT UP")
        y_cursor += label_fm.height() + 12

        painter.setFont(singer_font)
        singer_fm = QFontMetrics(singer_font)
        singer_text = singer_fm.elidedText(singer, Qt.TextElideMode.ElideRight, text_w)
        painter.setPen(accent)
        painter.drawText(QRect(x + pad, y_cursor, text_w, singer_fm.height() + 14),
                         Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter, singer_text)
        y_cursor += singer_fm.height() + 22

        painter.setFont(title_font)
        title_fm = QFontMetrics(title_font)
        title_text = title_fm.elidedText(title or "Unknown Song", Qt.TextElideMode.ElideRight, text_w)
        painter.setPen(QColor(255, 255, 255, a(242)))
        painter.drawText(QRect(x + pad, y_cursor, text_w, title_fm.height() + 8),
                         Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter, title_text)
        y_cursor += title_fm.height() + 8

        if artist:
            painter.setFont(artist_font)
            artist_fm = QFontMetrics(artist_font)
            artist_text = artist_fm.elidedText(artist, Qt.TextElideMode.ElideRight, text_w)
            painter.setPen(QColor(221, 226, 238, a(228)))
            painter.drawText(QRect(x + pad, y_cursor, text_w, artist_fm.height() + 8),
                             Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter, artist_text)
            y_cursor += artist_fm.height() + 18

        if on_deck:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QColor(255, 255, 255, a(30)))
            line_y = min(y + panel_h - pad - 70, y_cursor)
            painter.drawRoundedRect(QRectF(x + pad, line_y, text_w, 1), 1, 1)
            y_cursor = line_y + 18

            painter.setFont(deck_font)
            deck_fm = QFontMetrics(deck_font)
            deck_text = deck_fm.elidedText(f"On deck: {on_deck}", Qt.TextElideMode.ElideRight, text_w)
            painter.setPen(QColor(255, 255, 255, a(220)))
            painter.drawText(QRect(x + pad, y_cursor, text_w, deck_fm.height() + 8),
                             Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter, deck_text)

        painter.restore()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.fillRect(self.rect(), QColor("black"))

        if not self.karaoke_frame.isNull():
            if bool(self.karaoke_side_fill and self.karaoke_frame_is_cdg):
                painter.fillRect(self.rect(), self._karaoke_side_fill_color)
            elif bool(self.karaoke_blur_fill and self.karaoke_frame_is_cdg):
                self._ensure_karaoke_blur_fill_pixmap()
                if not self._karaoke_blur_fill_pixmap.isNull():
                    painter.drawPixmap(0, 0, self._karaoke_blur_fill_pixmap)
            bg_opacity = self._lyrics_background_opacity() if bool(self.karaoke_frame_is_cdg) else 0.0
            if bg_opacity > 0.0:
                # Live MP4 background video wins; otherwise the normal
                # idle/slideshow background shows through (graceful fallback
                # when the video folder is empty/missing/disabled).
                if not self.background_video_pixmap.isNull():
                    painter.save()
                    painter.setOpacity(bg_opacity)
                    t0 = time.perf_counter()
                    self._draw_background_video_pixmap(painter, self.background_video_pixmap)
                    self._background_video_paint_count += 1
                    self._background_video_paint_time_ms += (time.perf_counter() - t0) * 1000.0
                    if self._background_video_paint_count % 300 == 0:
                        try:
                            avg_paint = self._background_video_paint_time_ms / max(1, self._background_video_paint_count)
                            avg_upload = self._background_video_upload_time_ms / max(1, self._background_video_upload_count)
                            _diag(
                                f"[BG-VIDEO] compose stats frames={self._background_video_paint_count} "
                                f"avg_upload_ms={avg_upload:.3f} avg_compose_ms={avg_paint:.3f} "
                                f"pixmap={self.background_video_pixmap.width()}x{self.background_video_pixmap.height()} "
                                f"target={self.width()}x{self.height()}"
                            )
                        except Exception:
                            pass
                    painter.restore()
                elif not self.background_pixmap.isNull():
                    painter.save()
                    painter.setOpacity(bg_opacity)
                    self._draw_background_pixmap(painter, self.background_pixmap)
                    painter.restore()
            self._ensure_karaoke_scaled_pixmap()
            if not self._karaoke_scaled_pixmap.isNull():
                painter.drawPixmap(self._karaoke_scaled_pos, self._karaoke_scaled_pixmap)
        elif not self.background_pixmap.isNull() and not self._is_live_karaoke_active():
            fade_alpha = self._background_fade_alpha()
            if fade_alpha < 1.0:
                previous = getattr(self, "_background_previous_pixmap", QPixmap())
                if not previous.isNull():
                    self._draw_background_pixmap(painter, previous)
                painter.save()
                painter.setOpacity(fade_alpha)
                self._draw_background_pixmap(painter, self.background_pixmap)
                painter.restore()
            else:
                self._draw_background_pixmap(painter, self.background_pixmap)

        info = self._get_idle_bg_overlay_info()
        if info:
            self._draw_idle_bg_overlay(painter, info)

        self._draw_next_up_overlay(painter)
        self._draw_fallback_transition(painter)

        # Request QR sits on top of everything, bottom-right by the timer.
        self._draw_request_qr(painter)

        painter.end()

        # Throttled diagnostic marker: prove Qt idle frame paints are occurring.
        try:
            vw = self.parent()
            if vw is not None and bool(getattr(vw, "idle", False)):
                now = time.monotonic()
                if (now - float(getattr(self, "_idle_paint_log_ts", 0.0))) >= 2.0:
                    self._idle_paint_log_ts = now
                    pix_ok = not bool(self.background_pixmap.isNull())
        except Exception:
            pass

class MusicDatabaseWidget(QListWidget):
    """Left panel - shows all music in database"""
    
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setDragEnabled(True)
        self.setDefaultDropAction(Qt.DropAction.CopyAction)
        self.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        
    def startDrag(self, supportedActions):
        """Custom drag with file paths as mime data"""
        items = self.selectedItems()
        if not items:
            return
            
        mime_data = QMimeData()
        paths = []
        
        for item in items:
            file_path = item.data(Qt.ItemDataRole.UserRole)
            if file_path:
                paths.append(file_path)
        
        # Store paths as JSON in mime data
        mime_data.setText(json.dumps(paths))
        
        drag = QDrag(self)
        drag.setMimeData(mime_data)
        drag.exec(Qt.DropAction.CopyAction)


# ============================================================================
# Circular avatar + bar-level meter widgets for the redesigned Now Singing /
# On Deck / Rotation Waiting card.
# ============================================================================

class CircularAvatar(QWidget):
    """A round badge displaying the current singer's first name.

    Draws a glowing purple-ring circle with a dark interior; the name auto-
    fits down to ~12pt before being clipped.  Provides ``set_mode`` and
    ``set_media_badge`` shims so it's a drop-in replacement for the old
    ``HeroVisualizerWidget`` API.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self._name = ""
        self._mode = "idle"
        self.setMinimumSize(80, 80)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)

    # ---- legacy API shims (kept so existing code doesn't have to change) ----
    def set_mode(self, mode: str):
        self._mode = str(mode or "idle").lower()
        self.update()

    def set_media_badge(self, _text: str):
        # No longer rendered — badge moved into the text column.
        pass

    def set_name(self, name: str):
        # First word only (mirrors mockup); strip a "duet" suffix if present.
        clean = str(name or "").strip()
        # Try to keep a useful glyph for blank/idle states.
        first = clean.split()[0] if clean else ""
        # Strip emoji + decorative chars that look weird in a tight circle.
        import re as _re
        first = _re.sub(r"[^0-9A-Za-z'._-]", "", first).strip("'._-")
        self._name = first[:10]  # cap; the auto-fit shrinks the rest
        self.update()

    # ---- paint ----
    def paintEvent(self, event):
        from PyQt6.QtGui import QPainter, QPen, QBrush, QColor, QFont, QLinearGradient
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        side = min(self.width(), self.height())
        pad = 6
        cx = self.width() / 2
        cy = self.height() / 2
        r_outer = side / 2 - 2
        # Outer soft glow (three concentric rings of decreasing alpha)
        for i, alpha in enumerate((40, 70, 110)):
            grad = QLinearGradient(cx - r_outer, cy - r_outer, cx + r_outer, cy + r_outer)
            grad.setColorAt(0.0, QColor(120, 80, 255, alpha))
            grad.setColorAt(1.0, QColor(200, 100, 230, alpha))
            p.setPen(QPen(QBrush(grad), 6 - i * 2))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(int(cx - r_outer + i * 2), int(cy - r_outer + i * 2),
                          int((r_outer - i * 2) * 2), int((r_outer - i * 2) * 2))
        # Solid ring + dark fill
        grad = QLinearGradient(cx - r_outer, cy - r_outer, cx + r_outer, cy + r_outer)
        grad.setColorAt(0.0, QColor(140, 80, 255))
        grad.setColorAt(1.0, QColor(210, 110, 230))
        p.setPen(QPen(QBrush(grad), 2.4))
        p.setBrush(QColor(15, 18, 30))
        inner = int(r_outer - pad)
        p.drawEllipse(int(cx - inner), int(cy - inner), int(inner * 2), int(inner * 2))
        # Name — auto-fit the largest size that fits with comfortable margin
        if self._name:
            from PyQt6.QtGui import QFontMetrics as _Fm
            font = QFont(self.font())
            font.setBold(True)
            avail = inner * 2 - 16
            for size in (34, 30, 26, 22, 18, 15, 12):
                font.setPointSize(size)
                if _Fm(font).horizontalAdvance(self._name) <= avail:
                    break
            p.setFont(font)
            p.setPen(QColor("#FFFFFF"))
            from PyQt6.QtCore import QRect as _QRect
            p.drawText(_QRect(int(cx - inner), int(cy - inner), int(inner * 2), int(inner * 2)),
                       Qt.AlignmentFlag.AlignCenter, self._name)


class BarLevelMeter(QWidget):
    """Vertical purple-pink bars whose heights respond to the current
    karaoke audio level, or indicate playback when metering is unavailable."""

    def __init__(self, level_provider=None, n_bars: int = 12, parent=None,
                 playback_provider=None):
        super().__init__(parent)
        self._level_provider = level_provider
        self._playback_provider = playback_provider
        self._n_bars = max(4, int(n_bars))
        self._heights = [0.10] * self._n_bars
        self._phase = 0.0
        self._active = False
        self.setMinimumSize(86, 60)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self._timer = QTimer(self)
        self._timer.setInterval(45)  # ~22 fps
        self._timer.timeout.connect(self._tick)

    def set_active(self, active: bool):
        active = bool(active)
        if active == self._active:
            return
        self._active = active
        if active:
            self._timer.start()
            return

        # This meter sits inside a card with a drop-shadow effect. Repainting
        # it while idle makes Qt re-render the whole effected card every 45 ms,
        # consuming a substantial fraction of a CPU core for a static screen.
        # Stop the animation completely and draw the silent baseline once.
        self._timer.stop()
        self._heights = [0.0] * self._n_bars
        self.update()

    def _sample_level(self) -> float:
        # mpv and external playback have no level tap. Animate decoratively
        # only while the host reports playback; never invent transport dB data.
        fallback = 0.0
        if self._playback_provider is not None:
            try:
                if not self._playback_provider():
                    return 0.0
                fallback = 0.55
            except Exception:
                return 0.0
        if not self._level_provider:
            return fallback
        try:
            db, ts = self._level_provider()
        except Exception:
            return 0.0
        if db is None or ts is None:
            return fallback
        if (time.monotonic() - float(ts)) > 0.5:
            return 0.0
        # Map -60dB→0 .. 0dB→1 with a tiny boost so quiet content still moves.
        x = max(0.0, min(1.0, (float(db) + 60.0) / 60.0))
        return x ** 0.85

    def _tick(self):
        import math
        self._phase += 0.20
        base = self._sample_level() if self._active else 0.0
        for i in range(self._n_bars):
            # Tall in centre, taper toward the edges.
            center_dist = abs(i + 0.5 - self._n_bars / 2.0) / (self._n_bars / 2.0)
            shape = 1.0 - center_dist * 0.55
            wobble = (math.sin(self._phase + i * 0.9) + 1.0) * 0.5
            target = base * shape * (0.45 + 0.55 * wobble)
            # Smooth attack/release
            cur = self._heights[i]
            self._heights[i] = cur * 0.6 + target * 0.4
        self.update()

    def paintEvent(self, event):
        from PyQt6.QtGui import QPainter, QColor, QLinearGradient, QBrush, QPen
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w = self.width()
        h = self.height()
        margin = 4

        # If the meter is essentially silent, render a single faint baseline
        # instead of a row of identical floor-height bars (which look like
        # punctuation/dashes to a casual observer).
        max_level = max(self._heights) if self._heights else 0.0
        if max_level < 0.04:
            base_y = h - margin - 2
            grad = QLinearGradient(margin, 0, w - margin, 0)
            grad.setColorAt(0.0, QColor(120, 90, 200, 90))
            grad.setColorAt(1.0, QColor(220, 110, 200, 90))
            p.setPen(QPen(QBrush(grad), 2))
            p.drawLine(margin + 2, base_y, w - margin - 2, base_y)
            return

        usable_w = w - margin * 2
        gap = 2
        bar_w = max(2, (usable_w - (self._n_bars - 1) * gap) // self._n_bars)
        x = margin
        floor = 2  # tiny baseline so quiet bars are still visible
        for lvl in self._heights:
            bar_h = max(floor, int((h - margin * 2) * lvl))
            top = h - margin - bar_h
            grad = QLinearGradient(0, h - margin, 0, top)
            grad.setColorAt(0.0, QColor(110, 60, 240))
            grad.setColorAt(1.0, QColor(240, 90, 200))
            p.fillRect(x, top, bar_w, bar_h, QBrush(grad))
            x += bar_w + gap


class HeroVisualizerWidget(QWidget):
    def __init__(self, level_provider=None, parent=None):
        super().__init__(parent)
        self._level_provider = level_provider
        self._mode = "idle"
        self._badge_text = "KJ"
        self._phase = 0.0
        self._bars = [0.10] * 16
        self._peaks = [0.12] * 16
        self._tick = QTimer(self)
        self._tick.setInterval(45)
        self._tick.timeout.connect(self._advance)
        self._tick.start()
        self.setMinimumSize(156, 90)

    def set_media_badge(self, text: str):
        self._badge_text = str(text or "KJ").upper()
        self.update()

    def set_mode(self, mode: str):
        self._mode = str(mode or "idle").lower()
        self.update()

    def _sample_level(self) -> float:
        try:
            if not callable(self._level_provider):
                return 0.0
            db, ts = self._level_provider()
            if db is None:
                return 0.0
            if ts is not None and (time.monotonic() - float(ts)) > 0.9:
                return 0.0
            return max(0.0, min(1.0, (float(db) + 60.0) / 60.0))
        except Exception:
            return 0.0

    def _advance(self):
        level = self._sample_level() if self._mode == "live" else 0.0
        self._phase = (self._phase + (0.16 + (level * 0.55 if level > 0 else 0.06))) % 10000.0
        for i, old in enumerate(self._bars):
            if level > 0.0:
                wave1 = 0.5 + 0.5 * math.sin(self._phase + (i * 0.52))
                wave2 = 0.5 + 0.5 * math.sin((self._phase * 0.68) + (i * 1.04))
                target = 0.10 + ((0.62 * wave1) + (0.38 * wave2)) * (0.16 + level * 0.76)
            elif self._mode == "next":
                wave = 0.5 + 0.5 * math.sin((self._phase * 0.45) + (i * 0.7))
                target = 0.08 + wave * 0.10
            else:
                target = 0.05
            self._bars[i] = (old * 0.70) + (target * 0.30)
            pk = self._peaks[i]
            if self._bars[i] >= pk:
                pk = min(1.0, self._bars[i])
            else:
                pk = max(0.04, pk - 0.020)
            self._peaks[i] = pk
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        rect = self.rect().adjusted(0, 0, -1, -1)

        painter.setPen(QColor(255, 255, 255, 12))
        painter.setBrush(QColor(18, 24, 32, 245))
        painter.drawRoundedRect(rect, 10, 10)

        inner = rect.adjusted(8, 8, -8, -8)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(10, 34, 24, 78 if self._mode == "live" else 44))
        painter.drawRoundedRect(inner, 8, 8)

        bar_area = inner.adjusted(10, 14, -10, -14)
        count = max(1, len(self._bars))
        gap = 4
        bar_w = max(3, int((bar_area.width() - (gap * (count - 1))) / count))
        x = bar_area.left()
        base = bar_area.bottom()
        for i, lvl in enumerate(self._bars):
            h = max(6, int(bar_area.height() * max(0.05, min(1.0, lvl))))
            bar_rect = QRect(int(x), int(base - h), int(bar_w), int(h))
            alpha = 110 + int(min(1.0, lvl) * 55)
            color = QColor(36, 133, 255, alpha) if self._mode == "live" else QColor(72, 96, 128, 62)
            painter.setBrush(color)
            painter.drawRoundedRect(bar_rect, 2, 2)

            peak_y = max(bar_area.top() + 2, base - int(bar_area.height() * max(0.05, min(1.0, self._peaks[i]))))
            painter.setBrush(QColor(255, 255, 255, 55 if self._mode == "live" else 24))
            painter.drawRoundedRect(QRect(int(x), int(peak_y), int(bar_w), 2), 1, 1)
            x += bar_w + gap

        badge_font = painter.font()
        badge_font.setPointSize(18)
        badge_font.setBold(True)
        badge_font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 2.0)
        painter.setFont(badge_font)
        painter.setPen(QColor(255, 255, 255, 12))
        painter.drawText(inner.adjusted(0, 1, 0, 1), int(Qt.AlignmentFlag.AlignCenter), self._badge_text)
        painter.setPen(QColor(255, 255, 255, 26))
        painter.drawText(inner, int(Qt.AlignmentFlag.AlignCenter), self._badge_text)

class PlaylistWidget(QListWidget):
    """Right panel - current playlist with drag/drop support"""

    # Carries (paths, insert_row) — insert_row=-1 means append to end.
    tracks_added = pyqtSignal(list, int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setDragDropMode(QListWidget.DragDropMode.InternalMove)
        self.setDefaultDropAction(Qt.DropAction.MoveAction)
        self.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)

    def dragEnterEvent(self, event: QDragEnterEvent):
        """Accept drags from database or external files"""
        if event.mimeData().hasText() or event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragEnterEvent(event)

    def dragMoveEvent(self, event):
        """Show drop-indicator so the user can see where the track will land."""
        if event.mimeData().hasText() or event.mimeData().hasUrls():
            self.setDropIndicatorShown(True)
            event.acceptProposedAction()
        else:
            super().dragMoveEvent(event)

    def _drop_row_at(self, pos) -> int:
        """Return the row index where a drop at *pos* should be inserted.

        Returns -1 when the drop lands below all existing items (append).
        """
        item = self.itemAt(pos)
        if item is None:
            return -1  # Below all items -> append
        row = self.row(item)
        # If cursor is in the lower half of the item, insert after it.
        rect = self.visualItemRect(item)
        if pos.y() > rect.top() + rect.height() // 2:
            row += 1
        if row >= self.count():
            return -1  # Would be at the very end anyway
        return row

    def dropEvent(self, event: QDropEvent):
        """Handle drops from file tree, external sources, or internal reorders."""
        new_tracks = []

        # Prefer URL payloads (QFileSystemModel drag) so folders/files from browser work reliably.
        if event.mimeData().hasUrls():
            import os
            audio_exts = {'.mp3', '.wav', '.flac', '.m4a', '.aac', '.ogg'}

            def gather_audio(path: str):
                if os.path.isdir(path):
                    for root, _, files in os.walk(path):
                        for f in files:
                            if f.startswith('.'):
                                continue
                            if os.path.splitext(f)[1].lower() in audio_exts:
                                yield os.path.join(root, f)
                else:
                    if os.path.splitext(path)[1].lower() in audio_exts:
                        yield path

            for url in event.mimeData().urls():
                p = url.toLocalFile()
                if p and os.path.exists(p):
                    for ap in gather_audio(p):
                        new_tracks.append(ap)
        # From JSON (legacy internal drag)
        elif event.mimeData().hasText():
            try:
                paths = json.loads(event.mimeData().text())
                audio_exts = {'.mp3', '.wav', '.flac', '.m4a', '.aac', '.ogg'}
                new_tracks = [
                    p for p in paths
                    if isinstance(p, str) and os.path.splitext(p)[1].lower() in audio_exts
                ]
            except json.JSONDecodeError:
                # Not JSON: internal move
                super().dropEvent(event)
                return

        if new_tracks:
            # Deduplicate while preserving order
            seen = set()
            flat = []
            for p in new_tracks:
                if p not in seen:
                    seen.add(p)
                    flat.append(p)
            insert_row = self._drop_row_at(event.position().toPoint())
            self.tracks_added.emit(flat, insert_row)
            event.acceptProposedAction()
        else:
            # Internal reordering
            super().dropEvent(event)


class SeekSlider(QSlider):
    """Horizontal slider that jumps to click position for media scrubbing."""
    def mousePressEvent(self, event):
        try:
            if event.button() == Qt.MouseButton.LeftButton and self.orientation() == Qt.Orientation.Horizontal:
                x = int(event.position().x())
                w = max(1, self.width())
                ratio = max(0.0, min(1.0, x / w))
                val = int(self.minimum() + ratio * (self.maximum() - self.minimum()))
                self.setValue(val)
                self.sliderMoved.emit(val)
        except Exception:
            pass
        super().mousePressEvent(event)


class ClickableImageLabel(QLabel):
    clicked = pyqtSignal()

    def __init__(self, text: str = "", parent=None):
        super().__init__(text, parent)

    def mousePressEvent(self, event):
        try:
            if event.button() == Qt.MouseButton.LeftButton:
                self.clicked.emit()
        except Exception:
            pass
        super().mousePressEvent(event)

class BackgroundMusicManager(QMainWindow):
    """Main window for background music management - OpenKJ style"""
    
    def __init__(self, bg_music_player, parent=None):
        super().__init__(parent)
        self.bg_music = bg_music_player
        self.host_app = parent if parent is not None and hasattr(parent, "settings") else None
        self.setWindowTitle("Background Music Manager")
        self.setGeometry(100, 100, 1000, 600)

        # Safety: make sure bg_music looks like the player, not the app
        if not hasattr(self.bg_music, "playlist") or not hasattr(self.bg_music, "play"):
            raise TypeError("BackgroundMusicManager expects a BackgroundMusicPlayer as first argument")
        
        # Playlist storage only (no database)
        self.playlist_path = APP_USER_DIR / "bg_playlist.json"
        self.current_playlist = []  # Current playlist
        self._last_highlight_row = None
        self._last_highlight_count = 0
        self._bg_ui_op_in_progress = False
        self._bg_ui_cooldown_until = 0.0
        self._bg_pulse_started_at = time.monotonic()
        self._bg_player_frame_css_cache = ""
        self._bg_now_playing_kicker_css_cache = ""
        
        self.setup_ui()
        self._apply_main_window_look()
        self._match_main_window_geometry()
        self._browser_filter_timer = QTimer(self)
        self._browser_filter_timer.setSingleShot(True)
        self._browser_filter_timer.setInterval(220)
        self._browser_filter_timer.timeout.connect(self._apply_browser_filter_now)
        self._bg_pulse_timer = QTimer(self)
        self._bg_pulse_timer.setInterval(100)
        self._bg_pulse_timer.timeout.connect(self._tick_bg_pulse)
        self.load_data()
        self.setup_connections()
        self._init_file_browser()

    def _host(self):
        host = getattr(self, "host_app", None)
        if host is not None:
            return host
        p = self.parent()
        if p is not None and hasattr(p, "settings"):
            return p
        return None

    def _add_selected_from_library(self):
        items = self.library_list.selectedItems()
        paths = []
        for it in items:
            p = it.data(Qt.ItemDataRole.UserRole)
            if p:
                paths.append(p)
        if paths:
            self.add_tracks_to_playlist(paths)

    def _sync_to_player(self, reset_index: bool = True, defer_pipeline_realign: bool = False):
        """
        Mirror the manager's Current Playlist into the BackgroundMusicPlayer.
        Tries self.bg_music first; falls back to parent().bg_music.
        """
        player = getattr(self, "bg_music", None)
        host = self._host()
        if player is None and host is not None and hasattr(host, "bg_music"):
            player = host.bg_music
        if player is None:
            return  # no player wired yet

        # Push just the file paths to the player
        player.playlist = [t["path"] for t in self.current_playlist]
        if reset_index:
            player.current_index = 0

        # If BG is not actively playing, align any preloaded paused pipeline.
        # For idle shuffles, this can be deferred to the next play to avoid stop/start thrash.
        try:
            is_playing = bool(getattr(player, "is_playing", False))
            if not is_playing:
                expected = ""
                if player.playlist and 0 <= int(player.current_index) < len(player.playlist):
                    expected = str(player.playlist[int(player.current_index)])
                active = ""
                if hasattr(player, "get_active_track_path"):
                    active = str(player.get_active_track_path() or "")
                if active and expected and active != expected:
                    if defer_pipeline_realign:
                        player._pipeline_realign_needed = True
                    else:
                        player.stop()
                        if player.playlist:
                            player.preload_current_track_paused()
        except Exception:
            pass

        # Nudge the mini panel in the main window if present
        parent = self._host()
        if parent and hasattr(parent, "update_bg_track_display"):
            try: parent.update_bg_track_display()
            except Exception: pass
        if parent and hasattr(parent, "update_bg_button_state"):
            try: parent.update_bg_button_state()
            except Exception: pass

    def _begin_bg_ui_action(self, action: str) -> bool:
        now = time.monotonic()
        if self._bg_ui_op_in_progress or now < self._bg_ui_cooldown_until:
            _diag(f"[BG-ACT] ignored action={action} busy_or_cooldown=True")
            return False
        self._bg_ui_op_in_progress = True
        # Small cooldown to absorb double-click bursts.
        self._bg_ui_cooldown_until = now + 0.25
        return True

    def _end_bg_ui_action(self):
        self._bg_ui_op_in_progress = False

    def _init_file_browser(self):
        """Initialize live filesystem browser (no bgmusic.json index)."""
        self.fs_model = QFileSystemModel(self)
        try:
            self.fs_model.setFilter(QDir.Filter.AllDirs | QDir.Filter.Files | QDir.Filter.NoDotAndDotDot | QDir.Filter.Drives)
            self.fs_model.setNameFilterDisables(False)
            self.fs_model.setNameFilters(self._audio_name_filters(""))
        except Exception:
            pass
        self.fs_model.setRootPath("")

        self.fs_tree.setModel(self.fs_model)
        self.fs_tree.setSortingEnabled(True)
        self.fs_tree.sortByColumn(0, Qt.SortOrder.AscendingOrder)
        self.fs_tree.setHeaderHidden(True)
        # Keep browser compact like a DJ crate list.
        for c in (1, 2, 3):
            try:
                self.fs_tree.hideColumn(c)
            except Exception:
                pass

        self._browser_roots = []
        try:
            self._browser_roots.append(("Home", str(Path.home())))
            if sys.platform == "darwin":
                self._browser_roots.append(("Macintosh HD", "/"))
                if Path("/Volumes").exists():
                    self._browser_roots.append(("Volumes", "/Volumes"))
            elif sys.platform == "win32":
                for d in QDir.drives():
                    p = d.absolutePath()
                    self._browser_roots.append((p.rstrip("\\/"), p))
            else:
                self._browser_roots.append(("Root (/)", "/"))
        except Exception:
            self._browser_roots = [("Home", str(Path.home()))]

        self.browser_root_combo.blockSignals(True)
        self.browser_root_combo.clear()
        for label, _path in self._browser_roots:
            self.browser_root_combo.addItem(label)
        self.browser_root_combo.blockSignals(False)
        self._set_browser_root(self._browser_roots[0][1] if self._browser_roots else str(Path.home()))

    def _set_browser_root(self, root_path: str):
        idx = self.fs_model.index(root_path)
        if idx.isValid():
            self.fs_tree.setRootIndex(idx)

    def _on_browser_root_changed(self, index: int):
        if 0 <= index < len(self._browser_roots):
            self._set_browser_root(self._browser_roots[index][1])

    def _open_browser_folder(self):
        folder = QFileDialog.getExistingDirectory(self, "Select Folder")
        if not folder:
            return
        # Add the folder as a quick root for fast return.
        if all(folder != p for _l, p in self._browser_roots):
            self._browser_roots.append((Path(folder).name or folder, folder))
            self.browser_root_combo.addItem(self._browser_roots[-1][0])
        self._set_browser_root(folder)

    def _audio_extensions(self) -> tuple[str, ...]:
        return ('.mp3', '.wav', '.flac', '.m4a', '.aac', '.ogg')

    def _audio_name_filters(self, term: str) -> list[str]:
        term = (term or "").strip()
        if not term:
            return [f"*{ext}" for ext in self._audio_extensions()]
        return [f"*{term}*{ext}" for ext in self._audio_extensions()]

    def _is_audio_file(self, path: str) -> bool:
        ext = os.path.splitext(path)[1].lower()
        return ext in set(self._audio_extensions())

    def _collect_audio_from_path(self, path: str) -> list[str]:
        out = []
        term = (self.library_search.text() or "").strip().lower()
        try:
            if os.path.isdir(path):
                for root, _, files in os.walk(path):
                    for f in files:
                        if f.startswith('.'):
                            continue
                        full = os.path.join(root, f)
                        if self._is_audio_file(full):
                            if term and term not in f.lower():
                                continue
                            out.append(full)
            else:
                if self._is_audio_file(path):
                    if not term or term in os.path.basename(path).lower():
                        out.append(path)
        except Exception:
            pass
        return out

    def _selected_browser_paths(self) -> list[str]:
        paths = []
        seen = set()
        try:
            for idx in self.fs_tree.selectionModel().selectedRows():
                p = self.fs_model.filePath(idx)
                if p and p not in seen:
                    seen.add(p)
                    paths.append(p)
        except Exception:
            pass
        return paths

    def _add_selected_from_browser(self):
        picked = []
        seen = set()
        for p in self._selected_browser_paths():
            for ap in self._collect_audio_from_path(p):
                if ap not in seen:
                    seen.add(ap)
                    picked.append(ap)
        if picked:
            self.add_tracks_to_playlist(picked)

    def _on_browser_double_click(self, index):
        p = self.fs_model.filePath(index)
        if not p:
            return
        # Double-click folder: normal tree navigation (expand/collapse), no root jump.
        if os.path.isdir(p):
            self.fs_tree.setExpanded(index, not self.fs_tree.isExpanded(index))
            return
        # Double-click audio file: add just that file.
        tracks = self._collect_audio_from_path(p)
        if tracks:
            self.add_tracks_to_playlist(tracks)

    def _on_browser_filter_changed(self, _text: str):
        # Debounce filesystem model filtering; setNameFilters can trigger a
        # visible tree refresh, so avoid repainting the browser on every key.
        try:
            self._browser_filter_timer.start()
        except Exception:
            self._apply_browser_filter_now()

    def _apply_browser_filter_now(self):
        try:
            self.fs_model.setNameFilters(self._audio_name_filters(self.library_search.text()))
        except Exception:
            pass

    def _bg_pulse_value(self) -> float:
        """Slow eased pulse for active BGM indicators.

        A single 10 fps timer drives only the small now-playing card while BGM
        is active, keeping repaint cost low and avoiding the old blink effect.
        """
        period = 1.8
        t = (time.monotonic() - float(getattr(self, "_bg_pulse_started_at", time.monotonic()))) % period
        return 0.5 - (0.5 * math.cos((t / period) * math.tau))

    def _bg_player_frame_css(self, active: bool, pulse: float = 0.0) -> str:
        if active:
            glow = 0.14 + (0.11 * max(0.0, min(1.0, float(pulse))))
            border = 0.26 + (0.16 * max(0.0, min(1.0, float(pulse))))
            return f"""
            QFrame#bgPlayerFrame {{
                background: qlineargradient(x1:0,y1:0,x2:1,y2:1,
                    stop:0 rgba(54,214,138,{glow:.3f}),
                    stop:0.42 {_v('surface_alt')},
                    stop:1 {_v('surface')});
                border: 1px solid rgba(141,255,177,{border:.3f});
                border-radius: 8px;
            }}
            """
        return content_card_css("bgPlayerFrame", radius=12)

    def _apply_bg_pulse_style(self):
        try:
            active = bool(getattr(self.bg_music, "is_playing", False))
            if getattr(self, "bg_player_frame", None) is not None:
                # setStyleSheet forces Qt to repolish the widget. Quantize and
                # cache the animated state so the 10 fps pulse does not do a
                # full style pass when the visual output is effectively same.
                pulse = round(self._bg_pulse_value(), 1) if active else 0.0
                css = self._bg_player_frame_css(active, pulse)
                if css != getattr(self, "_bg_player_frame_css_cache", ""):
                    self.bg_player_frame.setStyleSheet(css)
                    self._bg_player_frame_css_cache = css
            if getattr(self, "bg_now_playing_kicker", None) is not None:
                color = _v("now_singing") if active else _v("text_soft")
                css = f"color:{color}; font-size:11px; font-weight:750; letter-spacing:0px;"
                if css != getattr(self, "_bg_now_playing_kicker_css_cache", ""):
                    self.bg_now_playing_kicker.setStyleSheet(css)
                    self._bg_now_playing_kicker_css_cache = css
        except Exception:
            pass

    def _tick_bg_pulse(self):
        self._apply_bg_pulse_style()

    def _sync_bg_pulse_timer(self):
        try:
            active = bool(getattr(self.bg_music, "is_playing", False))
            timer = getattr(self, "_bg_pulse_timer", None)
            if timer is None:
                return
            if active:
                if not timer.isActive():
                    self._bg_pulse_started_at = time.monotonic()
                    timer.start()
            else:
                if timer.isActive():
                    timer.stop()
            self._apply_bg_pulse_style()
        except Exception:
            pass

    def _play_next_insert_row(self) -> int:
        """Return the playlist row immediately after the currently playing track.

        If nothing is playing, returns -1 (append to end).
        """
        try:
            player = getattr(self, "bg_music", None)
            if player is None:
                return -1
            if not getattr(player, "is_playing", False):
                return -1
            idx = int(getattr(player, "current_index", -1))
            if idx < 0:
                return -1
            # Insert right after the current track.
            return idx + 1
        except Exception:
            return -1

    def _add_as_play_next_from_browser(self):
        """Collect selected browser paths and insert them right after the current track."""
        picked = []
        seen = set()
        for p in self._selected_browser_paths():
            for ap in self._collect_audio_from_path(p):
                if ap not in seen:
                    seen.add(ap)
                    picked.append(ap)
        if picked:
            row = self._play_next_insert_row()
            self.add_tracks_to_playlist(picked, insert_row=row)

    def _show_browser_context_menu(self, pos):
        menu = QMenu(self.fs_tree)
        style_app_menu(menu)

        add_selected = menu.addAction("Add Selected to Playlist")
        # "Play Next" — insert right after the currently playing track.
        play_next_action = menu.addAction("Play Next")

        chosen = menu.exec(self.fs_tree.viewport().mapToGlobal(pos))
        if chosen is None:
            return
        if chosen == add_selected:
            self._add_selected_from_browser()
            return
        if chosen == play_next_action:
            self._add_as_play_next_from_browser()
            return
        
