    def setup_connections(self):
        """Connect signals and slots (file browser + playlist only; no database)."""
        # Player controls
        self.play_button.clicked.connect(self.toggle_playback)
        self.next_button.clicked.connect(self.play_next)
        self.prev_button.clicked.connect(self.play_previous)
        self.stop_button.clicked.connect(self.stop_playback)
        self.seek_slider.sliderPressed.connect(self._on_seek_pressed)
        self.seek_slider.sliderReleased.connect(self._on_seek_released)
        self.seek_slider.valueChanged.connect(self._on_seek_value_changed)
        self.volume_slider.valueChanged.connect(self.on_volume_changed)
        self.volume_slider.valueChanged.connect(lambda v: self.volume_label.setText(str(v)))

        # One-time sync at window open (paranoia guard)
        self.volume_label.setText(str(self.volume_slider.value()))


        self.volume_slider.valueChanged.connect(
            lambda v: self.volume_label.setText(str(v))
        )

        # Toggles
        self.enable_bg_cb.toggled.connect(self._toggle_bg_enabled)
        self.autoplay_cb.toggled.connect(self._toggle_bg_autoplay)
        self.stop_after_current_cb.toggled.connect(self._toggle_stop_after_current)

        # File browser events
        self.browser_root_combo.currentIndexChanged.connect(self._on_browser_root_changed)
        self.library_search.textChanged.connect(self._on_browser_filter_changed)
        self.fs_tree.doubleClicked.connect(self._on_browser_double_click)
        self.fs_tree.customContextMenuRequested.connect(self._show_browser_context_menu)
        self.add_selected_button.clicked.connect(self._add_selected_from_browser)

        # PLAYLIST controls
        self.playlist_list.tracks_added.connect(self.add_tracks_to_playlist)
        self.playlist_list.itemDoubleClicked.connect(self.play_from_playlist)
        self.playlist_up_button.clicked.connect(self.move_selected_up)
        self.playlist_down_button.clicked.connect(self.move_selected_down)
        self.remove_selected_button.clicked.connect(self.remove_selected_from_playlist)
        self.shuffle_button.clicked.connect(self.shuffle_playlist)
        self.clear_playlist_button.clicked.connect(self.clear_playlist)
        self.save_playlist_button.clicked.connect(self.save_playlist_as)
