    def _iter_audio_files(self, path: str):
        """Yield absolute audio file paths from a file or folder (recursive)."""
        audio_exts = {'.mp3', '.wav', '.flac', '.m4a', '.aac', '.ogg', '.mp4'}
        if os.path.isdir(path):
            for root, _, files in os.walk(path):
                for f in files:
                    if f.startswith('.'):
                        continue
                    if os.path.splitext(f)[1].lower() in audio_exts:
                        yield os.path.join(root, f)
        else:
            if os.path.splitext(path)[1].lower() in audio_exts:
                yield path
        
    def add_folder(self):
        """Add a folder to the music database"""
        folder = QFileDialog.getExistingDirectory(self, "Select Music Folder")
        if not folder:
            return
            
        # Store the folder path for rescanning
        if not hasattr(self, 'scanned_folders'):
            self.scanned_folders = []
        if folder not in self.scanned_folders:
            self.scanned_folders.append(folder)
            
        # Scan for music files
        self.scan_folder(folder)
        self.save_database()
        
    def scan_folder(self, folder):
        """Scan a folder for music files"""
        audio_extensions = {'.mp3', '.wav', '.flac', '.m4a', '.aac', '.ogg', '.mp4'}
        
        for root, _, files in os.walk(folder):
            for file in files:
                if file.startswith('.'):
                    continue
                    
                ext = os.path.splitext(file)[1].lower()
                if ext in audio_extensions:
                    full_path = os.path.join(root, file)
                    
                    # Check if already in database
                    if not any(track['path'] == full_path for track in self.music_database):
                        track_info = {
                            'path': full_path,
                            'filename': file,
                            'title': os.path.splitext(file)[0]
                        }
                        self.music_database.append(track_info)
        
        self.refresh_database_display()
        self.status_label.setText(f"Database: {len(self.music_database)} tracks")
        
    def refresh_database_display(self):
        """Update the database list widget"""
        self.database_list.clear()
        
        filter_text = self.db_search.text().lower()
        
        for track in self.music_database:
            if filter_text and filter_text not in track['filename'].lower():
                continue
                
            item = QListWidgetItem(track['filename'])
            item.setData(Qt.ItemDataRole.UserRole, track['path'])
            self.database_list.addItem(item)
            
    def _make_playlist_item(self, filename: str, path: str):
        item = QListWidgetItem(filename)
        item.setData(Qt.ItemDataRole.UserRole, path)
        try:
            item_font = QApplication.font()
            item_font.setPointSize(11)
            item_font.setWeight(QFont.Weight.Medium)
            item.setFont(item_font)
            item.setSizeHint(QSize(0, 32))
        except Exception:
            pass
        return item

    def add_tracks_to_playlist(self, paths, insert_row: int = -1):
        """Add tracks to the current playlist.

        insert_row  the 0-based row to insert at (-1 or out-of-range = append).
        Called from:
          - drag-and-drop (carries the exact drop position)
          - right-click "Play Next" (passes current_index + 1)
          - Add Selected button / double-click (passes -1 to append)
        """
        if not paths:
            return

        # Build track_info dicts for every path first.
        new_infos = []
        for path in paths:
            new_infos.append({
                'path': path,
                'filename': os.path.basename(path),
                'title': os.path.splitext(os.path.basename(path))[0],
            })

        # Determine the actual insertion index in current_playlist.
        n = len(self.current_playlist)
        if insert_row < 0 or insert_row >= n:
            # Append to end.
            insert_at = n
        else:
            insert_at = insert_row

        self.playlist_list.setUpdatesEnabled(False)
        try:
            if insert_at >= n:
                # Append path: fast — just extend list and addItem.
                for info in new_infos:
                    self.current_playlist.append(info)
                    item = self._make_playlist_item(info['filename'], info['path'])
                    self.playlist_list.addItem(item)
            else:
                # Insert at specific position in both current_playlist and the widget.
                for offset, info in enumerate(new_infos):
                    self.current_playlist.insert(insert_at + offset, info)
                    item = self._make_playlist_item(info['filename'], info['path'])
                    self.playlist_list.insertItem(insert_at + offset, item)
                # Scroll to make the first inserted item visible.
                self.playlist_list.scrollToItem(
                    self.playlist_list.item(insert_at),
                    QAbstractItemView.ScrollHint.EnsureVisible,
                )
        finally:
            self.playlist_list.setUpdatesEnabled(True)

        self._invalidate_highlight_cache()
        self.update_playlist_count()
        self.save_current_playlist()

        # Keep the live player in lockstep.
        self._sync_to_player(reset_index=False if len(paths) == 1 else True)
        self.highlight_current_track()
        
    def update_playlist_count(self):
        """Update the playlist counter"""
        self.playlist_count.setText(f"{len(self.current_playlist)} tracks")
        self._refresh_workspace_meta()
        
    # ── Session undo -------------------------------------------------------
    # Commands intentionally hold complete model records.  Queue entries carry
    # request IDs and server-order metadata which cannot safely be reconstructed
    # from the visible list rows.
    def _setup_undo_system(self):
        self._undo_stack = []
        self._undo_limit = 20
        self._undo_restoring = False
        self._undo_action = None
        try:
            menu_bar = QMenuBar(self)
            menu_bar.setNativeMenuBar(True)
            edit_menu = menu_bar.addMenu("Edit")
            action = QAction("Undo", self)
            action.setShortcut(QKeySequence.StandardKey.Undo)
            action.setShortcutContext(Qt.ShortcutContext.ApplicationShortcut)
            action.setEnabled(False)
            action.triggered.connect(self._dispatch_undo)
            edit_menu.addAction(action)
            self._app_menu_bar = menu_bar
            self._edit_menu = edit_menu
            self._undo_action = action
        except Exception as e:
            _diag(f"[UNDO] menu setup failed: {e}")
        KaraokeApp._update_undo_action(self)

    def _undo_snapshot(self) -> dict:
        """Capture durable host state affected by queue/waitlist commands."""
        state = object.__getattribute__(self, "__dict__")
        return copy.deepcopy({
            "queue": state.get("queue", []),
            "waiting_for_add_requests": state.get("_waiting_for_add_requests", {}),
            "waiting_for_add_handled_ids": state.get("_waiting_for_add_handled_ids", set()),
            "waiting_for_add_removed_tonight": state.get("_waiting_for_add_removed_tonight", {}),
            "remote_attention_requests": state.get("_remote_attention_requests", {}),
            "remote_request_tombstones": state.get("_remote_request_tombstones", {"requests": {}}),
            "remote_removed_request_ids": state.get("_remote_removed_request_ids", set()),
            "pending_remote_order_syncs": state.get("_pending_remote_order_syncs", {}),
            "queue_revision": state.get("_queue_revision", 0),
        })

    def _begin_undoable_action(self, name: str) -> dict | None:
        state = object.__getattribute__(self, "__dict__")
        if bool(state.get("_undo_restoring", False)):
            return None
        return {"name": str(name or "Change"), "before": KaraokeApp._undo_snapshot(self)}

    def _commit_undoable_action(self, command: dict | None, message: str = "") -> bool:
        state = object.__getattribute__(self, "__dict__")
        if not command or bool(state.get("_undo_restoring", False)):
            return False
        try:
            if command.get("before") == KaraokeApp._undo_snapshot(self):
                return False
        except Exception:
            pass
        stack = state.get("_undo_stack")
        if not isinstance(stack, list):
            stack = []
            self._undo_stack = stack
        stack.append(command)
        del stack[:-max(1, int(state.get("_undo_limit", 20) or 20))]
        KaraokeApp._update_undo_action(self)
        # Routine queue actions stay quiet. The Edit menu exposes Undo without
        # turning the search-area status line into an activity feed.
        return True

    def _update_undo_action(self):
        state = object.__getattribute__(self, "__dict__")
        action = state.get("_undo_action")
        if action is None:
            return
        stack = state.get("_undo_stack", [])
        command = stack[-1] if stack else None
        action.setText(f"Undo {command.get('name', 'Change')}" if command else "Undo")
        action.setEnabled(bool(command))

    def _dispatch_undo(self):
        """Keep normal editor undo when Command+Z is used while typing."""
        try:
            focus = QApplication.focusWidget()
            if isinstance(focus, (QLineEdit, QTextEdit, QPlainTextEdit)) and hasattr(focus, "undo"):
                focus.undo()
                return
        except Exception:
            pass
        self.undo_last_action()

    def undo_last_action(self) -> bool:
        state = object.__getattribute__(self, "__dict__")
        stack = state.get("_undo_stack")
        if not isinstance(stack, list) or not stack:
            KaraokeApp._update_undo_action(self)
            return False
        command = stack.pop()
        before_restore = copy.deepcopy(state.get("queue", []))
        snapshot = copy.deepcopy(command.get("before") or {})
        self._undo_restoring = True
        try:
            self.queue = snapshot.get("queue", [])
            self._waiting_for_add_requests = snapshot.get("waiting_for_add_requests", {})
            self._waiting_for_add_handled_ids = set(snapshot.get("waiting_for_add_handled_ids", set()))
            self._waiting_for_add_removed_tonight = snapshot.get("waiting_for_add_removed_tonight", {})
            self._remote_attention_requests = snapshot.get("remote_attention_requests", {})
            self._remote_request_tombstones = snapshot.get("remote_request_tombstones", {"requests": {}})
            self._remote_removed_request_ids = set(snapshot.get("remote_removed_request_ids", set()))
            self._pending_remote_order_syncs = snapshot.get("pending_remote_order_syncs", {})
            # A new host revision supersedes any deletion/reorder already in flight.
            self._queue_revision = max(
                int(getattr(self, "_queue_revision", 0) or 0),
                int(snapshot.get("queue_revision", 0) or 0),
            ) + 1
            self.save_data()
            self._save_remote_request_tombstones(self._remote_request_tombstones)
            self._save_waitlist_removed_tonight()
            self.update_queue_display()
            try:
                self._schedule_waiting_for_add_view_refresh(reason="undo")
            except Exception:
                pass
            try:
                self.update_rotation_summary_card()
            except Exception:
                pass
            KaraokeApp._sync_undo_server_state(self, before_restore)
            try:
                self._show_processing_notification(
                    f"{command.get('name', 'Change')} restored", level="success"
                )
            except Exception:
                pass
            return True
        except Exception as e:
            stack.append(command)
            _diag(f"[UNDO] restore failed action={command.get('name')!r}: {e}")
            return False
        finally:
            self._undo_restoring = False
            KaraokeApp._update_undo_action(self)

    def _sync_undo_server_state(self, previous_queue=None):
        """Publish restored host state and supersede stale remote mutations."""
        try:
            self.post_rotation()
        except Exception:
            pass
        for singer_idx, singer in enumerate(self.queue or []):
            try:
                self._sync_remote_singer_order(singer_idx, reason="host_undo")
            except Exception:
                pass
            for entry in list((singer or {}).get("songs", []) or []):
                try:
                    if self._queue_entry_remote_request_id(entry) is not None:
                        self._push_remote_request_replacement(
                            entry,
                            singer_name=str((singer or {}).get("name", "") or ""),
                            source="host_undo",
                        )
                except Exception:
                    pass

    def load_data(self):
        """Load saved current playlist (no database)"""
        # Load playlist
        if self.playlist_path.exists():
            try:
                with open(self.playlist_path, 'r') as f:
                    self.current_playlist = json.load(f)

                # Populate playlist widget
                self.playlist_list.setUpdatesEnabled(False)
                try:
                    self.playlist_list.clear()
                    for track in self.current_playlist:
                        item = self._make_playlist_item(track['filename'], track['path'])
                        self.playlist_list.addItem(item)
                finally:
                    self.playlist_list.setUpdatesEnabled(True)

                self._invalidate_highlight_cache()
                self.update_playlist_count()
                self.highlight_current_track()
            except Exception as e:
                print(f"Failed to load playlist: {e}")
                
    def save_database(self):
        """Save the music database"""
        try:
            data = {
                'tracks': self.music_database,
                'folders': getattr(self, 'scanned_folders', [])
            }
            with open(self.db_path, 'w') as f:
                json.dump(data, f, indent=2)
        except Exception as e:
            print(f"Failed to save database: {e}")
            
    def save_current_playlist(self):
        """Save the current playlist"""
        try:
            with open(self.playlist_path, 'w') as f:
                json.dump(self.current_playlist, f, indent=2)
        except Exception as e:
            print(f"Failed to save playlist: {e}")

    def _on_playlist_rows_moved(self, parent, start, end, dest, row):
        """
        Keep self.current_playlist in the same order as the QListWidget after a drag/drop move,
        then push that order to the live BackgroundMusicPlayer without resetting the index.
        """
        try:
            # Rebuild model list from the widget's current visual order
            new_list = []
            for i in range(self.playlist_list.count()):
                it = self.playlist_list.item(i)
                p = it.data(Qt.ItemDataRole.UserRole)
                # Reuse existing track dict when possible
                t = next((t for t in self.current_playlist if t["path"] == p), None)
                if t is None:
                    fname = it.text()
                    t = {"path": p, "filename": fname, "title": os.path.splitext(fname)[0]}
                new_list.append(t)

            self.current_playlist = new_list
            self.save_current_playlist()  # persist to bg_playlist.json (optional but nice)

            # IMPORTANT: Don’t jump playback to the top just because order changed
            self._sync_to_player(reset_index=False)

            # If the mini label exists, refresh it
            parent = self._host()
            if parent and hasattr(parent, "update_bg_track_display"):
                parent.update_bg_track_display()
        except Exception as e:
            print("playlist rowsMoved sync error:", e)
            
    def toggle_playback(self):
        """Toggle play/pause"""
        if not self._begin_bg_ui_action("toggle"):
            return
        try:
            if self.bg_music.is_playing:
                self.bg_music.pause()
                self.play_button.setText("▶")
            else:
                # If no playlist loaded to bg_music, load it
                if not self.bg_music.playlist and self.current_playlist:
                    paths = [t['path'] for t in self.current_playlist]
                    self.bg_music.playlist = paths
                    self.bg_music.current_index = 0

                self.bg_music.play()
                self.play_button.setText("⏸")
        finally:
            self._end_bg_ui_action()
            
    def update_display(self):
        """Update now playing info"""
        # Guard if bg_music not wired yet or wired incorrectly
        if not getattr(self, "bg_music", None) or not hasattr(self.bg_music, "playlist"):
            return

        # Keep UI checkbox synced when EOS consumes the one-shot option.
        try:
            desired = bool(getattr(self.bg_music, "stop_after_current", False))
            if self.stop_after_current_cb.isChecked() != desired:
                self.stop_after_current_cb.blockSignals(True)
                self.stop_after_current_cb.setChecked(desired)
                self.stop_after_current_cb.blockSignals(False)
        except Exception:
            pass

        if self.bg_music.playlist:
            info = self.bg_music.get_current_track_info()
            self.now_playing_label.setText(f"Now Playing: {info}")

            # Update play button
            self.play_button.setText("⏸" if self.bg_music.is_playing else "▶")
            self.highlight_current_track()
            try:
                pos_sec, dur_sec = self.bg_music.get_playback_times()
                self._update_seek_ui(pos_sec, dur_sec)
            except Exception:
                pass
        else:
            self._update_seek_ui(0.0, 0.0)
        self._sync_bg_pulse_timer()

    def _fmt_mmss(self, sec: float) -> str:
        try:
            s = max(0, int(round(float(sec))))
        except Exception:
            s = 0
        m, s = divmod(s, 60)
        return f"{m:02d}:{s:02d}"

    def _update_seek_ui(self, pos_sec: float, dur_sec: float):
        try:
            if dur_sec <= 0:
                # After seek, GStreamer can briefly report 0/0; hold last known display.
                if time.monotonic() < float(getattr(self, "_seek_hold_until", 0.0)) and self._seek_last_dur > 0:
                    pos_sec = self._seek_last_pos
                    dur_sec = self._seek_last_dur
                else:
                    self.seek_elapsed_label.setText("00:00")
                    self.seek_remaining_label.setText("-00:00")
                    if not self._seek_dragging:
                        self.seek_slider.setValue(0)
                    return

            pos_sec = max(0.0, min(float(dur_sec), float(pos_sec)))
            self._seek_last_pos = pos_sec
            self._seek_last_dur = float(dur_sec)
            self.seek_elapsed_label.setText(self._fmt_mmss(pos_sec))
            self.seek_remaining_label.setText(f"-{self._fmt_mmss(max(0.0, dur_sec - pos_sec))}")
            if not self._seek_dragging:
                pct = int((pos_sec / dur_sec) * 1000.0)
                self.seek_slider.blockSignals(True)
                self.seek_slider.setValue(max(0, min(1000, pct)))
                self.seek_slider.blockSignals(False)
        except Exception:
            pass

    def _on_seek_pressed(self):
        self._seek_dragging = True

    def _on_seek_released(self):
        try:
            pos_sec, dur_sec = self.bg_music.get_playback_times()
            if dur_sec > 0:
                target = (self.seek_slider.value() / 1000.0) * dur_sec
                self.bg_music.seek_seconds(target)
                self._seek_last_pos = float(target)
                self._seek_last_dur = float(dur_sec)
                self._seek_hold_until = time.monotonic() + 0.8
        except Exception:
            pass
        self._seek_dragging = False
        self.update_display()

    def _on_seek_value_changed(self, value: int):
        if not self._seek_dragging:
            return
        try:
            _pos, dur_sec = self.bg_music.get_playback_times()
            if dur_sec > 0:
                preview = (int(value) / 1000.0) * dur_sec
                self.seek_elapsed_label.setText(self._fmt_mmss(preview))
                self.seek_remaining_label.setText(f"-{self._fmt_mmss(max(0.0, dur_sec - preview))}")
        except Exception:
            pass

    def _set_playlist_item_style(self, item, is_current):
        # Keep list styling neutral; now-playing is shown only in the label above.
        item.setForeground(QColor(_v("text_bright")))
        item_font = QApplication.font()
        item_font.setPointSize(11)
        item_font.setWeight(QFont.Weight.Medium)
        item.setFont(item_font)
        item.setSizeHint(QSize(0, 32))

    def _set_hidden_cutoff_range(self, start, end, hidden):
        if start > end:
            return
        count = self.playlist_list.count()
        s = max(0, start)
        e = min(count - 1, end)
        if s > e:
            return
        for i in range(s, e + 1):
            self.playlist_list.item(i).setHidden(hidden)

    def _invalidate_highlight_cache(self):
        self._last_highlight_row = None
        self._last_highlight_count = self.playlist_list.count()

    def highlight_current_track(self):
        """Highlight the current track in green and hide anything above it."""
        if not self.bg_music.playlist:
            return

        count = self.playlist_list.count()
        if count <= 0:
            self._last_highlight_row = None
            self._last_highlight_count = 0
            return

        current_idx = max(0, min(self.bg_music.current_index, count - 1))
        prev_idx = self._last_highlight_row
        prev_count = self._last_highlight_count

        # Fast-path: nothing changed.
        if prev_idx == current_idx and prev_count == count:
            return

        # Keep hide-above-current behavior, but avoid a full-row pass on normal +/-1 movement.
        if prev_idx is None or prev_count != count:
            for i in range(count):
                self.playlist_list.item(i).setHidden(i <= current_idx)
                if i != current_idx:
                    self._set_playlist_item_style(self.playlist_list.item(i), False)
        elif current_idx > prev_idx:
            self._set_hidden_cutoff_range(prev_idx + 1, current_idx, True)
        elif current_idx < prev_idx:
            self._set_hidden_cutoff_range(current_idx + 1, prev_idx, False)

        if prev_idx is not None and 0 <= prev_idx < count and prev_idx != current_idx:
            self._set_playlist_item_style(self.playlist_list.item(prev_idx), False)

        self._set_playlist_item_style(self.playlist_list.item(current_idx), True)

        self._last_highlight_row = current_idx
        self._last_highlight_count = count
                
    # Additional methods...
    def play_next(self):
        if not self._begin_bg_ui_action("next"):
            return
        try:
            self.bg_music.next_track()
            self.highlight_current_track()
        finally:
            self._end_bg_ui_action()
        
    def play_previous(self):
        if not self._begin_bg_ui_action("previous"):
            return
        try:
            self.bg_music.previous_track()
            self.highlight_current_track()
        finally:
            self._end_bg_ui_action()
        
    def stop_playback(self):
        if not self._begin_bg_ui_action("stop"):
            return
        try:
            self.bg_music.stop()
            self.play_button.setText("▶")
        finally:
            self._end_bg_ui_action()
        
    def on_volume_changed(self, value):
        # Live-apply to the player
        vol = max(0.0, min(1.0, value / 100.0))
        if self.bg_music:
            self.bg_music.set_volume(vol)

        # Persist to settings so BG player can use it when the window isn't open
        p = self._host()
        if p and hasattr(p, "settings"):
            p.settings["bg_volume"] = vol
            try:
                p.save_settings()
            except Exception:
                pass

    def _toggle_bg_enabled(self, checked: bool):
        p = self._host()
        if p and hasattr(p, "settings"):
            p.settings["bg_enabled"] = bool(checked)
            try: p.save_settings()
            except Exception: pass
        # Drive player immediately
        player = getattr(self, "bg_music", None) or (p.bg_music if p and hasattr(p, "bg_music") else None)
        if player:
            try: player.set_enabled(bool(checked))
            except Exception: pass

    def _toggle_bg_autoplay(self, checked: bool):
        p = self._host()
        if p and hasattr(p, "settings"):
            p.settings["bg_autoplay_on_idle"] = bool(checked)
            try: p.save_settings()
            except Exception: pass

    def _toggle_stop_after_current(self, checked: bool):
        try:
            self.bg_music.set_stop_after_current(bool(checked))
        except Exception:
            pass

    def _choose_bg_folders(self):
        # Multi-select folder picker (non-native dialog allows multi)
        dlg = QFileDialog(self, "Select background music folder(s)")
        dlg.setFileMode(QFileDialog.FileMode.Directory)
        dlg.setOption(QFileDialog.Option.ShowDirsOnly, True)
        dlg.setOption(QFileDialog.Option.DontUseNativeDialog, True)

        # Start where external drives live on macOS; otherwise Home
        try:
            if sys.platform == "darwin" and Path("/Volumes").exists():
                start_dir = "/Volumes"
            else:
                start_dir = str(Path.home())
            dlg.setDirectory(start_dir)
        except Exception:
            pass

        # Helpful sidebar shortcuts (Home, root, Volumes)
        try:
            urls = [
                QUrl.fromLocalFile(str(Path.home())),
                QUrl.fromLocalFile("/"),
            ]
            if sys.platform == "darwin":
                urls.append(QUrl.fromLocalFile("/Volumes"))
            dlg.setSidebarUrls(urls)
        except Exception:
            pass

        # enable multi-select in the non-native dialog’s views
        for w in dlg.findChildren(QTreeView) + dlg.findChildren(QListWidget):
            try:
                w.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
            except Exception:
                pass

        if dlg.exec():
            folders = [str(Path(p)) for p in dlg.selectedFiles()]
            p = self._host()
            if p and hasattr(p, "settings"):
                roots = list(p.settings.get("bg_import_folders", []))
                # append only new ones
                for f in folders:
                    if f not in roots:
                        roots.append(f)
                p.settings["bg_import_folders"] = roots
                try:
                    p.save_settings()
                except Exception:
                    pass
            self._rescan_bg_library()

    def _rescan_bg_library(self):
        """Deprecated (old bgmusic.json flow)."""
        return

    def _open_manage_folders(self):
        """Deprecated button target; now mapped to filesystem folder picker."""
        self._open_browser_folder()
        
    def filter_database(self, text):
        self.refresh_database_display()
        
    def add_from_database(self, item):
        """Double-click in database to add to playlist"""
        path = item.data(Qt.ItemDataRole.UserRole)
        if path:
            self.add_tracks_to_playlist([path])
            
    def play_from_playlist(self, item):
        """Double-click in playlist to play"""
        row = self.playlist_list.row(item)
        
        # Update bg_music playlist
        paths = [t['path'] for t in self.current_playlist]
        self.bg_music.playlist = paths
        self.bg_music.current_index = row
        
        # Stop current and play new
        self.bg_music.stop()
        self.bg_music.play()
        self.highlight_current_track()

    def move_selected_up(self):
        rows = sorted({self.playlist_list.row(i) for i in self.playlist_list.selectedItems()})
        if not rows:
            return

        moved_rows = []
        self.playlist_list.setUpdatesEnabled(False)
        try:
            for r in rows:
                if r <= 0:
                    continue
                item = self.playlist_list.takeItem(r)
                self.playlist_list.insertItem(r - 1, item)

                track = self.current_playlist.pop(r)
                self.current_playlist.insert(r - 1, track)
                moved_rows.append(r - 1)

            self.playlist_list.clearSelection()
            for r in moved_rows:
                it = self.playlist_list.item(r)
                if it is not None:
                    it.setSelected(True)
        finally:
            self.playlist_list.setUpdatesEnabled(True)

        self._invalidate_highlight_cache()
        self.update_playlist_count()
        self.save_current_playlist()
        self._sync_to_player(reset_index=False)
        self.highlight_current_track()

    def move_selected_down(self):
        rows = sorted({self.playlist_list.row(i) for i in self.playlist_list.selectedItems()}, reverse=True)
        if not rows:
            return

        last = len(self.current_playlist) - 1
        moved_rows = []
        self.playlist_list.setUpdatesEnabled(False)
        try:
            for r in rows:
                if r >= last:
                    continue
                item = self.playlist_list.takeItem(r)
                self.playlist_list.insertItem(r + 1, item)

                track = self.current_playlist.pop(r)
                self.current_playlist.insert(r + 1, track)
                moved_rows.append(r + 1)

            self.playlist_list.clearSelection()
            for r in sorted(moved_rows):
                it = self.playlist_list.item(r)
                if it is not None:
                    it.setSelected(True)
        finally:
            self.playlist_list.setUpdatesEnabled(True)

        self._invalidate_highlight_cache()
        self.update_playlist_count()
        self.save_current_playlist()
        self._sync_to_player(reset_index=False)
        self.highlight_current_track()

    def _rebuild_playlist_widget(self, selected_rows=None):
        self.playlist_list.clear()
        for t in self.current_playlist:
            it = self._make_playlist_item(t["filename"], t["path"])
            self.playlist_list.addItem(it)
        if selected_rows:
            for r in selected_rows:
                if 0 <= r < self.playlist_list.count():
                    self.playlist_list.item(r).setSelected(True)
        self.update_playlist_count()
        
    def remove_selected_from_playlist(self):
        """Remove selected rows from the Current Playlist"""
        rows = sorted({self.playlist_list.row(i) for i in self.playlist_list.selectedItems()}, reverse=True)
        if not rows:
            return

        self.playlist_list.setUpdatesEnabled(False)
        try:
            for r in rows:
                if 0 <= r < self.playlist_list.count() and 0 <= r < len(self.current_playlist):
                    self.playlist_list.takeItem(r)
                    self.current_playlist.pop(r)
        finally:
            self.playlist_list.setUpdatesEnabled(True)

        self._invalidate_highlight_cache()
        self.update_playlist_count()
        self.save_current_playlist()
        self._sync_to_player(reset_index=False)
        self.highlight_current_track()
        
    def shuffle_playlist(self):
        """Shuffle the Current Playlist"""
        if not self.current_playlist:
            return
        if not self._begin_bg_ui_action("shuffle"):
            return
        import random

        try:
            player = getattr(self, "bg_music", None)
            host = self._host()
            if player is None and host is not None and hasattr(host, "bg_music"):
                player = host.bg_music

            is_playing = bool(getattr(player, "is_playing", False)) if player is not None else False

            current_path = ""
            current_idx = 0
            if player is not None:
                try:
                    current_path = str(player.get_active_track_path() or "")
                except Exception:
                    current_path = ""
                try:
                    current_idx = max(0, min(int(player.current_index), max(0, len(self.current_playlist) - 1)))
                except Exception:
                    current_idx = 0

            if is_playing and player is not None and self.current_playlist:
                # While playing: keep the currently playing track fixed in the list,
                # shuffle only the remaining tracks.
                fixed_track = None
                rest = []
                for t in self.current_playlist:
                    if fixed_track is None and t.get("path") == current_path:
                        fixed_track = t
                    else:
                        rest.append(t)

                # If we can't identify current track path reliably, fall back to full shuffle.
                if fixed_track is None:
                    random.shuffle(self.current_playlist)
                    reset_index = False
                else:
                    random.shuffle(rest)
                    insert_at = max(0, min(current_idx, len(rest)))
                    self.current_playlist = rest[:insert_at] + [fixed_track] + rest[insert_at:]
                    reset_index = False
            else:
                # Not playing: shuffle everything.
                random.shuffle(self.current_playlist)
                reset_index = True

            self.playlist_list.setUpdatesEnabled(False)
            try:
                self.playlist_list.clear()
                for t in self.current_playlist:
                    it = self._make_playlist_item(t["filename"], t["path"])
                    self.playlist_list.addItem(it)
            finally:
                self.playlist_list.setUpdatesEnabled(True)

            self._invalidate_highlight_cache()
            self.update_playlist_count()
            self.save_current_playlist()
            self._sync_to_player(
                reset_index=reset_index,
                defer_pipeline_realign=(not is_playing),
            )
            if (not is_playing) and player is not None:
                try:
                    player._pipeline_realign_needed = True
                except Exception:
                    pass
            if is_playing and player is not None and current_path:
                try:
                    idx = next((i for i, p in enumerate(player.playlist) if p == current_path), None)
                    if idx is not None:
                        player.current_index = int(idx)
                except Exception:
                    pass
            self.highlight_current_track()
        finally:
            self._end_bg_ui_action()
        
    def clear_playlist(self):
        """Clear the Current Playlist"""
        if not self.current_playlist and self.playlist_list.count() == 0:
            return

        self.current_playlist.clear()
        self.playlist_list.setUpdatesEnabled(False)
        try:
            self.playlist_list.clear()
        finally:
            self.playlist_list.setUpdatesEnabled(True)

        self._invalidate_highlight_cache()
        self.update_playlist_count()
        self.save_current_playlist()
        self._sync_to_player(reset_index=True)
        
    def save_playlist_as(self):
        """Save playlist to a custom file"""
        filename, _ = QFileDialog.getSaveFileName(
            self, "Save Playlist", "", "Playlist Files (*.json)"
        )
        if filename:
            with open(filename, 'w') as f:
                json.dump(self.current_playlist, f, indent=2)
            print(f"Playlist saved to {filename}")
                
    def load_playlist_from_file(self):
        """Load a saved playlist file (.json exported by Save Playlist)"""
        path, _ = QFileDialog.getOpenFileName(
            self, "Load Playlist", "", "Playlist Files (*.json);;All Files (*.*)"
        )
        if not path:
            return

        try:
            with open(path, "r", encoding="utf-8") as f:
                loaded = json.load(f)
            # Expect a list of {path, filename, title}
            if not isinstance(loaded, list):
                print("Playlist file format not recognized (expected list).")
                return

            self.current_playlist = loaded

            # Rebuild the widget
            self.playlist_list.clear()
            for t in self.current_playlist:
                it = self._make_playlist_item(t["filename"], t["path"])
                self.playlist_list.addItem(it)

            self.update_playlist_count()
            self.save_current_playlist()
            # Push to live player but don't force index to 0 unless you want to:
            self._sync_to_player(reset_index=True)
            self.highlight_current_track()
            print(f"Loaded playlist from {path}")
        except Exception as e:
            print(f"Failed to load playlist: {e}")
                
    def rescan_folders(self):
        """Rescan all previously added folders"""
        if hasattr(self, 'scanned_folders'):
            self.music_database.clear()
            for folder in self.scanned_folders:
                if os.path.exists(folder):
                    self.scan_folder(folder)
            self.save_database()
            self.status_label.setText(f"Rescanned {len(self.scanned_folders)} folders")
        

