class SingerHistoryDirectoryBuildWorker(QObject):
    """Build Singer History directory rows away from the GUI thread."""

    finished = pyqtSignal(int, dict)

    def __init__(self, job_id: int, singers_snapshot: list, search: str, render_limit: int, song_scan_limit: int):
        super().__init__()
        self.job_id = int(job_id)
        self.singers_snapshot = list(singers_snapshot or [])
        self.search = str(search or "").strip().lower()
        self.render_limit = max(1, int(render_limit or 1))
        self.song_scan_limit = max(1, int(song_scan_limit or 1))
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        started = time.perf_counter()
        timings = {}
        model_rows = []
        total_matches = 0
        shown = 0
        cancelled = False
        try:
            sort_t0 = time.perf_counter()
            singers = list(self.singers_snapshot or [])
            singers.sort(key=lambda kv: str((kv[1] or {}).get("name", "") or "").strip().lower())
            timings["sort_ms"] = (time.perf_counter() - sort_t0) * 1000.0

            scan_t0 = time.perf_counter()
            matched_rows = []
            for row_num, (singer_key, record) in enumerate(singers):
                if self._cancelled:
                    cancelled = True
                    break
                if not isinstance(record, dict):
                    continue
                name = str(record.get("name", "") or singer_key).strip()
                if self.search:
                    haystack = f"{name} {record.get('preferred_disc_priority', '')}".lower()
                    if self.search not in haystack:
                        song_match = False
                        try:
                            song_values = list((record.get("songs", {}) or {}).values())
                        except Exception:
                            song_values = []
                        for idx, song in enumerate(song_values):
                            if idx >= self.song_scan_limit:
                                break
                            if not isinstance(song, dict):
                                continue
                            text = (
                                f"{song.get('artist', '')} {song.get('title', '')} "
                                f"{song.get('disc_id', '')} {song.get('duet_display', '')}"
                            ).lower()
                            if self.search in text:
                                song_match = True
                                break
                        if not song_match:
                            continue
                total_matches += 1
                if len(matched_rows) < self.render_limit:
                    matched_rows.append((singer_key, record, name))
                if row_num and row_num % 256 == 0:
                    time.sleep(0)
            timings["scan_ms"] = (time.perf_counter() - scan_t0) * 1000.0

            rows_t0 = time.perf_counter()
            for singer_key, record, name in matched_rows:
                if self._cancelled:
                    cancelled = True
                    break
                try:
                    perf = int(record.get("total_performances") or 0)
                except Exception:
                    perf = 0
                try:
                    uniq = int(record.get("unique_song_count") or len(record.get("songs", {}) or {}))
                except Exception:
                    uniq = 0
                pref = str(record.get("preferred_disc_priority", "") or "").strip()
                lines = [name, f"{perf} plays  ·  {uniq} songs"]
                if pref:
                    lines.append(f"Prefers: {pref}")
                text = "\n".join(lines)
                model_rows.append({
                    "text": text,
                    "singer_key": singer_key,
                    "selectable": True,
                    "tooltip": text,
                    "height": 52,
                })
            shown = min(total_matches, len(matched_rows))
            if total_matches > len(matched_rows) and not cancelled:
                model_rows.append({
                    "text": f"Showing {len(matched_rows)} of {total_matches} singers. Refine search to narrow results.",
                    "singer_key": "",
                    "selectable": False,
                    "foreground_hex": "#94a3b8",
                    "height": 52,
                })
            timings["rows_ms"] = (time.perf_counter() - rows_t0) * 1000.0
        except Exception as e:
            model_rows = [{
                "text": f"Could not load singer history: {e}",
                "singer_key": "",
                "selectable": False,
                "foreground_hex": "#f59e0b",
                "height": 52,
            }]
            cancelled = False
        finally:
            timings["total_ms"] = (time.perf_counter() - started) * 1000.0
            self.finished.emit(self.job_id, {
                "rows": model_rows,
                "total_matches": total_matches,
                "shown": shown,
                "search": self.search,
                "timings": timings,
                "cancelled": cancelled,
            })


def _history_song_last_sang_text(timestamp, *, now=None) -> str:
    """Return a compact local-time label that makes same-night repeats obvious."""
    try:
        performed = datetime.fromtimestamp(int(timestamp or 0))
        current = now if isinstance(now, datetime) else datetime.now()
        time_text = performed.strftime("%I:%M %p").lstrip("0")
        if performed.date() == current.date():
            return f"Last sang tonight at {time_text}"
        date_format = "%b %d" if performed.year == current.year else "%b %d, %Y"
        return f"Last sang {performed.strftime(date_format)} at {time_text}"
    except Exception:
        return "Last sang date unavailable"


class SingerHistorySongsBuildWorker(QObject):
    """Build one singer's song-history rows away from the GUI thread."""

    finished = pyqtSignal(int, str, dict)

    def __init__(self, job_id: int, singer_key: str, songs_snapshot: list, render_limit: int):
        super().__init__()
        self.job_id = int(job_id)
        self.singer_key = str(singer_key or "")
        self.songs_snapshot = list(songs_snapshot or [])
        self.render_limit = max(1, int(render_limit or 1))
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    @staticmethod
    def _song_display(song: dict) -> str:
        artist = str(song.get("artist", "") or "").strip() or "Unknown Artist"
        title = str(song.get("title", "") or "").strip() or "Unknown Song"
        disc = str(song.get("disc_id", "") or "").strip()
        song_type = str(song.get("song_type", "") or "").strip().upper()
        duet_display = str(song.get("duet_display", "") or "").strip()
        key = int(song.get("last_key") or 0)
        tempo = int(song.get("last_tempo_percent") or 100)
        meta = []
        if duet_display:
            meta.append(f"Duet: {duet_display}")
        if disc:
            meta.append(disc)
        if song_type:
            meta.append(song_type)
        meta.append(f"Key {key:+d}")
        meta.append(f"Tempo {tempo}%")
        meta.append(_history_song_last_sang_text(song.get("last_performed_at")))
        return f"{artist} • {title}\n" + "  ·  ".join(meta)

    def run(self):
        started = time.perf_counter()
        timings = {}
        model_rows = []
        cancelled = False
        total = 0
        try:
            sort_t0 = time.perf_counter()
            songs = list(self.songs_snapshot or [])
            total = len(songs)
            songs.sort(key=lambda kv: (
                -(int((kv[1] or {}).get("last_performed_at") or 0)),
                str((kv[1] or {}).get("artist", "") or "").lower(),
                str((kv[1] or {}).get("title", "") or "").lower(),
            ))
            timings["sort_ms"] = (time.perf_counter() - sort_t0) * 1000.0

            rows_t0 = time.perf_counter()
            for idx, (song_key, song) in enumerate(songs[:self.render_limit]):
                if self._cancelled:
                    cancelled = True
                    break
                if not isinstance(song, dict):
                    continue
                text = self._song_display(song)
                model_rows.append({
                    "text": text,
                    "song_key": song_key,
                    "selectable": True,
                    "tooltip": text,
                    "height": 44,
                })
                if idx and idx % 128 == 0:
                    time.sleep(0)
            if total > self.render_limit and not cancelled:
                model_rows.append({
                    "text": f"Showing {self.render_limit} of {total} songs. Use search or edit history to narrow this list.",
                    "song_key": "",
                    "selectable": False,
                    "foreground_hex": "#94a3b8",
                    "height": 44,
                })
            timings["rows_ms"] = (time.perf_counter() - rows_t0) * 1000.0
        except Exception as e:
            model_rows = [{
                "text": f"Could not load song history: {e}",
                "song_key": "",
                "selectable": False,
                "foreground_hex": "#f59e0b",
                "height": 44,
            }]
            cancelled = False
        finally:
            timings["total_ms"] = (time.perf_counter() - started) * 1000.0
            self.finished.emit(self.job_id, self.singer_key, {
                "rows": model_rows,
                "total": total,
                "shown": min(total, self.render_limit),
                "timings": timings,
                "cancelled": cancelled,
            })


_BRAND_CHOICE_THREADS = None


def _register_brand_choice_thread(thread) -> None:
    """Track brand-choices QThreads and join them at interpreter exit.

    Destroying a running QThread (test teardown, abrupt quit) aborts the
    whole process with 'QThread: Destroyed while thread is still running';
    an atexit join runs before Qt/C++ teardown and prevents it."""
    global _BRAND_CHOICE_THREADS
    if _BRAND_CHOICE_THREADS is None:
        import atexit

        _BRAND_CHOICE_THREADS = set()

        def _join_brand_choice_threads():
            for th in list(_BRAND_CHOICE_THREADS):
                try:
                    th.quit()
                    th.wait(3000)
                except Exception:
                    pass

        atexit.register(_join_brand_choice_threads)
    _BRAND_CHOICE_THREADS.add(thread)
    try:
        thread.finished.connect(lambda t=thread: _BRAND_CHOICE_THREADS.discard(t))
    except Exception:
        pass


class SingerHistoryBrandChoicesWorker(QObject):
    """Build Singer History preferred-brand choices away from the GUI thread."""

    finished = pyqtSignal(int, object, list, float)

    def __init__(self, job_id: int, cache_key, tracks_ref):
        super().__init__()
        self.job_id = int(job_id)
        self.cache_key = cache_key
        self.tracks_ref = tracks_ref
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        started = time.perf_counter()
        try:
            choices = library_brand_choices(self.tracks_ref, should_cancel=lambda: self._cancelled)
        except Exception:
            choices = []
        self.finished.emit(
            self.job_id,
            self.cache_key,
            [] if self._cancelled else choices,
            (time.perf_counter() - started) * 1000.0,
        )


class QueueListModel(QAbstractListModel):
    """Model-backed rows for the live rotation queue."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._rows = []

    def rowCount(self, parent=QModelIndex()):
        if parent.isValid():
            return 0
        return len(self._rows)

    def data(self, index, role=Qt.ItemDataRole.DisplayRole):
        if not index.isValid():
            return None
        row_num = int(index.row())
        if row_num < 0 or row_num >= len(self._rows):
            return None
        row = self._rows[row_num]
        if role == Qt.ItemDataRole.DisplayRole:
            return str(row.get("text") or "")
        if role == Qt.ItemDataRole.UserRole:
            return str(row.get("kind") or "")
        if role == int(Qt.ItemDataRole.UserRole) + 1:
            return row.get("entry")
        if role == Qt.ItemDataRole.ToolTipRole:
            return str(row.get("tooltip") or row.get("text") or "")
        if role == Qt.ItemDataRole.ForegroundRole:
            color = row.get("foreground")
            if isinstance(color, QColor):
                return QBrush(color)
        if role == Qt.ItemDataRole.BackgroundRole:
            color = row.get("background")
            if isinstance(color, QColor):
                return QBrush(color)
        if role == Qt.ItemDataRole.FontRole:
            font = row.get("font")
            if isinstance(font, QFont):
                return font
        if role == Qt.ItemDataRole.SizeHintRole:
            try:
                return QSize(0, int(row.get("height") or 32))
            except Exception:
                return QSize(0, 32)
        custom = row.get("roles") or {}
        try:
            if role in custom:
                return custom.get(role)
        except Exception:
            pass
        return None

    def flags(self, index):
        if not index.isValid():
            return Qt.ItemFlag.NoItemFlags
        return Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable

    def setRows(self, rows):
        self.beginResetModel()
        try:
            self._rows = list(rows or [])
        finally:
            self.endResetModel()

    def _identity_for_row(self, row: dict):
        try:
            return (
                str(row.get("kind") or ""),
                int(row.get("singer_idx", -1)),
                int(row.get("song_idx", -1)),
            )
        except Exception:
            return ("", -1, -1)

    def _changed_roles(self):
        user = int(Qt.ItemDataRole.UserRole)
        return [
            int(Qt.ItemDataRole.DisplayRole),
            int(Qt.ItemDataRole.ToolTipRole),
            int(Qt.ItemDataRole.ForegroundRole),
            int(Qt.ItemDataRole.BackgroundRole),
            int(Qt.ItemDataRole.FontRole),
            int(Qt.ItemDataRole.SizeHintRole),
            user,
            user + 1,
            user + 20,
            user + 21,
            user + 23,
            user + 30,
            user + 31,
            user + 32,
            user + 33,
        ]

    def _row_payload_equal(self, a: dict, b: dict) -> bool:
        try:
            user = int(Qt.ItemDataRole.UserRole)
            scalar_keys = (
                "text",
                "tooltip",
                "kind",
                "singer_idx",
                "song_idx",
                "height",
                "foreground",
                "background",
                "font",
            )
            for key in scalar_keys:
                if a.get(key) != b.get(key):
                    return False
            a_roles = dict(a.get("roles") or {})
            b_roles = dict(b.get("roles") or {})
            a_roles.pop(user + 1, None)
            b_roles.pop(user + 1, None)
            return a_roles == b_roles
        except Exception:
            return False

    def _replace_row_if_changed(self, row_num: int, row: dict):
        try:
            if row_num < 0 or row_num >= len(self._rows):
                return False
            if self._row_payload_equal(self._rows[row_num], row):
                return False
            self._rows[row_num] = row
            idx = self.index(row_num, 0)
            self.dataChanged.emit(idx, idx, self._changed_roles())
            return True
        except Exception:
            return False

    def syncRows(self, rows):
        """Synchronize queue rows without resetting the whole model when possible."""
        rows = list(rows or [])
        old_len = len(self._rows)
        new_len = len(rows)

        if old_len <= 0:
            if new_len > 0:
                self.beginInsertRows(QModelIndex(), 0, new_len - 1)
                try:
                    self._rows = rows
                finally:
                    self.endInsertRows()
            return
        if new_len <= 0:
            self.beginRemoveRows(QModelIndex(), 0, old_len - 1)
            try:
                self._rows = []
            finally:
                self.endRemoveRows()
            return

        old_ids = [self._identity_for_row(row) for row in self._rows]
        new_ids = [self._identity_for_row(row) for row in rows]

        if old_len == new_len and old_ids == new_ids:
            for i, row in enumerate(rows):
                self._replace_row_if_changed(i, row)
            return

        prefix = 0
        max_prefix = min(old_len, new_len)
        while prefix < max_prefix and old_ids[prefix] == new_ids[prefix]:
            self._replace_row_if_changed(prefix, rows[prefix])
            prefix += 1

        suffix = 0
        while (
            suffix < (old_len - prefix)
            and suffix < (new_len - prefix)
            and old_ids[old_len - 1 - suffix] == new_ids[new_len - 1 - suffix]
        ):
            suffix += 1

        remove_start = prefix
        remove_end = old_len - suffix - 1
        if remove_start <= remove_end:
            self.beginRemoveRows(QModelIndex(), remove_start, remove_end)
            try:
                del self._rows[remove_start:remove_end + 1]
            finally:
                self.endRemoveRows()

        insert_rows = rows[prefix:new_len - suffix]
        if insert_rows:
            self.beginInsertRows(QModelIndex(), prefix, prefix + len(insert_rows) - 1)
            try:
                self._rows[prefix:prefix] = insert_rows
            finally:
                self.endInsertRows()

        if suffix > 0:
            suffix_start = new_len - suffix
            for i in range(suffix_start, new_len):
                self._replace_row_if_changed(i, rows[i])

    def rowDict(self, row_num: int):
        try:
            row_num = int(row_num)
            if 0 <= row_num < len(self._rows):
                return self._rows[row_num]
        except Exception:
            pass
        return {}

    def setRowTextMeta(self, row_num: int, *, text=None, tooltip=None, left=None, right=None):
        try:
            row_num = int(row_num)
            if row_num < 0 or row_num >= len(self._rows):
                return False
            row = self._rows[row_num]
            if text is not None:
                row["text"] = str(text)
            if tooltip is not None:
                row["tooltip"] = str(tooltip)
            roles = row.setdefault("roles", {})
            if left is not None:
                roles[int(Qt.ItemDataRole.UserRole) + 20] = str(left or "")
            if right is not None:
                roles[int(Qt.ItemDataRole.UserRole) + 21] = str(right or "")
            idx = self.index(row_num, 0)
            self.dataChanged.emit(idx, idx, [
                Qt.ItemDataRole.DisplayRole,
                Qt.ItemDataRole.ToolTipRole,
                int(Qt.ItemDataRole.UserRole) + 20,
                int(Qt.ItemDataRole.UserRole) + 21,
            ])
            return True
        except Exception:
            return False

    def indexForSinger(self, singer_idx: int):
        try:
            singer_idx = int(singer_idx)
        except Exception:
            return QModelIndex()
        for i, row in enumerate(self._rows):
            if row.get("kind") == "singer" and int(row.get("singer_idx", -1)) == singer_idx:
                return self.index(i, 0)
        return QModelIndex()


class QueueListView(QListView):
    """QListView with tiny QListWidget-compatible helpers for queue migration."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.itemClicked = self.clicked

    def count(self) -> int:
        try:
            return int(self.model().rowCount())
        except Exception:
            return 0

    def currentRow(self) -> int:
        try:
            idx = self.currentIndex()
            return int(idx.row()) if idx.isValid() else -1
        except Exception:
            return -1

    def setCurrentRow(self, row: int):
        try:
            row = int(row)
            if row < 0 or row >= self.count():
                self.setCurrentIndex(QModelIndex())
                return
            self.setCurrentIndex(self.model().index(row, 0))
        except Exception:
            pass

    def currentItem(self):
        try:
            idx = self.currentIndex()
            return idx if idx.isValid() else None
        except Exception:
            return None

    def selectedItems(self):
        try:
            return list(self.selectedIndexes() or [])
        except Exception:
            return []

    def item(self, row: int):
        try:
            row = int(row)
            if row < 0 or row >= self.count():
                return None
            return self.model().index(row, 0)
        except Exception:
            return None

    def itemAt(self, position):
        try:
            idx = self.indexAt(position)
            return idx if idx.isValid() else None
        except Exception:
            return None

    def row(self, item) -> int:
        try:
            return int(item.row()) if item is not None and item.isValid() else -1
        except Exception:
            return -1

    def scrollToItem(self, item, hint=QAbstractItemView.ScrollHint.EnsureVisible):
        try:
            if item is not None and item.isValid():
                self.scrollTo(item, hint)
        except Exception:
            pass

    def clear(self):
        try:
            model = self.model()
            if hasattr(model, "setRows"):
                model.setRows([])
        except Exception:
            pass


from PyQt6.QtWidgets import QMainWindow

# --- Smart vertical scrollbar (macOS-friendly) ---
# Goal: behave like the old .75 build:
# - When no scrolling is needed: NO extra gutter (width=0)
# - When scrolling is needed: show a dark, small handle and reserve space (so text "shrinks" cleanly)
# - Keep native macOS fonts/controls elsewhere (we only style the scrollbar itself)
def attach_smart_vscroll(view, width_px=10):
    from PyQt6.QtCore import Qt
    sb = view.verticalScrollBar()

    # Force the scrollbar object to exist so we can control width precisely.
    # We then collapse it to 0px when not needed to avoid the "always reserved" blank strip.
    view.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOn)
    view.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)

    def _apply():
        if sb.maximum() <= 0:
            # No scrolling needed -> collapse to 0px (no reserved space)
            sb.setStyleSheet(f"""
                QScrollBar:vertical {{
                    width: 0px;
                    background: transparent;
                    margin: 0px;
                }}
                QScrollBar::handle:vertical {{
                    background: rgba(0,0,0,0.0);
                    border: none;
                    border-radius: 0px;
                    min-height: 0px;
                }}
                QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{ height: 0px; }}
                QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {{ background: transparent; }}
            """)
        else:
            # Scrolling needed -> reserve width and use a dark "block" handle (old look)
            w = int(width_px)
            sb.setStyleSheet(f"""
                QScrollBar:vertical {{
                    width: {w}px;
                    background: transparent;
                    margin: 0px;
                }}
                QScrollBar::handle:vertical {{
                    background: rgba(0,0,0,0.70);
                    border: 1px solid rgba(255,255,255,0.10);
                    border-radius: 2px;   /* squarer like old build */
                    min-height: 26px;
                }}
                QScrollBar::handle:vertical:hover {{
                    background: rgba(0,0,0,0.85);
                }}
                QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{ height: 0px; }}
                QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {{ background: transparent; }}
            """)

    # Update whenever content size changes
    try:
        sb.rangeChanged.connect(lambda *_: _apply())
    except Exception:
        pass

    _apply()
    return sb

