    def _schedule_reformat_lists(self):
        """Debounce reformatting on resize so dragging the window stays smooth."""
        try:
            self._list_reformat_timer.start(120)
        except Exception:
            try:
                self._reformat_lists_now()
            except Exception:
                pass

    def _reformat_lists_now(self):
        """Rebuild ONLY the visible text for existing items based on current widget widths."""
        # Search results
        try:
            for i in range(self.results_list.count()):
                it = self.results_list.item(i)
                t = it.data(Qt.ItemDataRole.UserRole)
                if isinstance(t, dict):
                    visible, tooltip, left, right = self._build_search_row_text(t)
                    it.setText(visible)
                    self._set_aligned_row_meta(it, left, right)
                    try:
                        it.setToolTip(tooltip)
                    except Exception:
                        pass
        except Exception:
            pass

        # Queue songs (leave singer rows alone)
        try:
            model = getattr(self, "queue_display_model", None)
            if isinstance(model, QueueListModel):
                for i in range(model.rowCount()):
                    row = model.rowDict(i)
                    if row.get("kind") != "song":
                        continue
                    entry = row.get("entry")
                    if isinstance(entry, dict):
                        visible, tooltip, left, right = self._build_queue_song_row_text(entry)
                        model.setRowTextMeta(i, text=visible, tooltip=tooltip, left=left, right=right)
        except Exception:
            pass
    def showEvent(self, event):
        super().showEvent(event)
        # Restore/return-from-tab must re-read authoritative playback IDs. This
        # updates presentation only and never selects a row or steals focus.
        QTimer.singleShot(0, lambda: self._reapply_rotation_presentation(scroll_current=False))
        # Run startup auto-placement only once; do not re-place on restore/maximize.
        if not getattr(self, "_initial_video_window_placement_done", False):
            self._initial_video_window_placement_done = True
            QTimer.singleShot(0, self._place_video_window_bottom_right)
        # Defer first paint of BG mini-card until after final startup geometry sync.
        QTimer.singleShot(0, self._finalize_bg_main_card_layout)
        QTimer.singleShot(80, self._finalize_bg_main_card_layout)

    def changeEvent(self, event):
        super().changeEvent(event)
        try:
            if event.type() in (QEvent.Type.ActivationChange, QEvent.Type.WindowStateChange):
                if self.isActiveWindow() or not self.isMinimized():
                    QTimer.singleShot(0, lambda: self._reapply_rotation_presentation(scroll_current=False))
        except Exception:
            pass

    def _place_video_window_bottom_right(self):
        try:
            if not hasattr(self, "video_window") or self.video_window is None:
                return

            # Respect user-saved window geometry when available.
            saved_pos = (self.settings or {}).get("karaoke_window_pos", {}) if hasattr(self, "settings") else {}
            if isinstance(saved_pos, dict) and int(saved_pos.get("width", 0) or 0) > 0 and int(saved_pos.get("height", 0) or 0) > 0:
                try:
                    # Guarded like the other two restore paths: saved geometry
                    # outlives the monitor it was saved on, and restoring onto a
                    # detached screen leaves a window macOS never gives a valid
                    # backing store -- the 2026-08-09 23:15 segfault.
                    self.video_window.setGeometry(_rect_on_attached_screen(QRect(
                        int(saved_pos.get("x", 100) or 100),
                        int(saved_pos.get("y", 100) or 100),
                        int(saved_pos.get("width", 640) or 640),
                        int(saved_pos.get("height", 520) or 520),
                    )))
                except Exception:
                    pass

                if not self.video_window.isVisible():
                    self.video_window.show()
                    self.video_window.raise_()

                QTimer.singleShot(50, self._activate_host_if_foreground)
                return

            # Never override an explicit fullscreen/maximized output state.
            if self.video_window.isFullScreen() or self.video_window.isMaximized():
                return

            from PyQt6.QtWidgets import QApplication
            from PyQt6.QtGui import QCursor

            # Square-ish size (first-run default only)
            vw, vh = 480, 360
            self.video_window.resize(vw, vh)

            # Pick screen under cursor (fallback to primary)
            screen = QApplication.screenAt(QCursor.pos())
            if screen is None:
                screen = QApplication.primaryScreen()
            if not screen:
                return

            avail = screen.availableGeometry()
            sx, sy, sw, sh = avail.x(), avail.y(), avail.width(), avail.height()

            pad_x = 24
            pad_y = 24

            x = sx + sw - vw - pad_x
            y = sy + sh - vh - pad_y

            # Clamp
            x = max(sx + 10, min(x, sx + sw - vw - 10))
            y = max(sy + 10, min(y, sy + sh - vh - 10))

            self.video_window.move(x, y)

            # First-run behavior: ensure visible without changing state later.
            if not self.video_window.isVisible():
                self.video_window.show()
                self.video_window.raise_()

            # Give focus back to the main window so keyboard shortcuts keep working.
            QTimer.singleShot(50, self._activate_host_if_foreground)

        except Exception as e:
            print("Video window placement failed:", e)
    
    def _display_for_track(self, t: dict) -> str:
        # delegate to the module-level helper
        return _display_for_track(t)

    def apply_default_window_positions(self):
        """
        Startup-only positioning (no saving):
        - Main window centered horizontally AND vertically
        - Slightly narrower than full width
        """
        from PyQt6.QtWidgets import QApplication
        from PyQt6.QtGui import QCursor

        # Pick the screen under the cursor (best for multi-monitor)
        screen = None
        try:
            screen = QApplication.screenAt(QCursor.pos())
        except Exception:
            screen = None

        if screen is None:
            screen = QApplication.primaryScreen()
        if screen is None:
            self.setGeometry(100, 100, 1200, 800)
            return

        avail = screen.availableGeometry()
        sx, sy = avail.x(), avail.y()
        sw, sh = avail.width(), avail.height()

        # Leave deliberate breathing room around the window so the resize handle
        # is always reachable above the dock / screen edge.
        edge_pad_x = 32
        edge_pad_top = 28
        edge_pad_bottom = 72

        # Adjust these to taste
        main_w = min(int(sw * 0.69), max(980, sw - (edge_pad_x * 2)))
        main_h = min(int(sh * 0.82), max(720, sh - edge_pad_top - edge_pad_bottom))

        # Center within the padded available area.
        main_x = sx + (sw - main_w) // 2
        main_y = sy + (sh - main_h) // 2
        main_x = max(sx + edge_pad_x, min(main_x, sx + sw - main_w - edge_pad_x))
        main_y = max(sy + edge_pad_top, min(main_y, sy + sh - main_h - edge_pad_bottom))

        self.setGeometry(main_x, main_y, main_w, main_h)
        
    # ---------- GStreamer helpers ----------


    def restore_main_window_geometry(self) -> bool:
        """Restore main window geometry from settings.json.

        Returns True if a saved geometry was applied; otherwise False (and defaults are applied).
        """
        try:
            from PyQt6.QtCore import QRect
            from PyQt6.QtWidgets import QApplication
        except Exception:
            try:
                self.apply_default_window_positions()
            except Exception:
                pass
            return False

        try:
            geo = (self.settings or {}).get("main_window_geometry")
        except Exception:
            geo = None

        if isinstance(geo, dict):
            try:
                x = int(geo.get("x", 0))
                y = int(geo.get("y", 0))
                w = int(geo.get("w", 0))
                h = int(geo.get("h", 0))
            except Exception:
                x = y = w = h = 0

            if w > 200 and h > 200:
                rect = QRect(x, y, w, h)
                # Ensure visible on at least one screen. The reachability test
                # uses a padded rect, but clamping uses the full available area
                # so a near-fullscreen window restores at its saved size
                # instead of shrinking by the padding on every launch.
                try:
                    screens = QApplication.screens() or []
                    for s in screens:
                        avail = s.availableGeometry()
                        padded = avail.adjusted(24, 24, -24, -72)
                        if padded.intersects(rect):
                            clamped_w = min(rect.width(), avail.width())
                            clamped_h = min(rect.height(), avail.height())
                            clamped_x = max(avail.x(), min(rect.x(), avail.right() - clamped_w + 1))
                            clamped_y = max(avail.y(), min(rect.y(), avail.bottom() - clamped_h + 1))
                            self.setGeometry(clamped_x, clamped_y, clamped_w, clamped_h)
                            return True
                except Exception:
                    try:
                        self.setGeometry(rect)
                        return True
                    except Exception:
                        pass

        try:
            self.apply_default_window_positions()
        except Exception:
            pass
        return False
    def _stop_karaoke_transport(self):
        transport = getattr(self, "karaoke_transport", None)
        self.karaoke_transport = None
        if transport is not None:
            try:
                transport.stop()
            except Exception as e:
                _diag(f"[PY-KARAOKE] stop failed: {e}")
        self._set_mpv_hosts_visible(False)
        self._stop_lyrics_background_video("karaoke_stopped")

    # -------------------- MP4 background videos behind CDG lyrics ----------
    def _start_lyrics_background_video(self):
        """Start the shuffled MP4 background loop for a CDG song, when the
        host enabled it. Falls back silently (normal CDG background) when the
        feature is off, the opacity is 0, or the folder is empty/missing."""
        self._stop_lyrics_background_video("restart")
        try:
            enabled = bool(self.settings.get("bg_video_enabled", False))
            folder = str(self.settings.get("bg_video_folder", "") or "")
            shuffle = bool(self.settings.get("bg_video_shuffle", True))
            opacity = int(float(self.settings.get("lyrics_background_video_opacity", 0) or 0))
        except Exception:
            return
        if not enabled:
            return
        if opacity <= 0:
            _diag("[BG-VIDEO] not started reason=opacity_zero (set Background Video Opacity > 0)")
            return
        plugin = getattr(self, "_mpv_playback", None)
        if plugin is None or not callable(getattr(plugin, "loadBackgroundVideo", None)):
            _diag("[BG-VIDEO] not started reason=native_background_unavailable")
            return
        files = scan_background_video_folder(folder)
        if not files:
            _diag(f"[BG-VIDEO] fallback to normal CDG background reason=no_videos folder={folder!r}")
            return
        try:
            player = NativeLyricsBackgroundVideoPlayer(
                plugin, self, opacity=opacity / 100.0)
            if player.start(files, shuffle=shuffle):
                self._lyrics_bg_video_player = player
                _diag(
                    f"[BG-VIDEO] started files={len(files)} shuffle={int(shuffle)} "
                    f"opacity={opacity}% decoder=native-libmpv renderer=shared-gpu-texture "
                    f"folder={folder!r}"
                )
            else:
                player.stop("start_failed")
        except Exception as e:
            _diag(f"[BG-VIDEO] start failed: {e}")

    def _stop_lyrics_background_video(self, reason: str = "stop"):
        player = getattr(self, "_lyrics_bg_video_player", None)
        self._lyrics_bg_video_player = None
        if player is not None:
            try:
                player.stop(reason)
            except Exception:
                pass
        try:
            self.video_window.video_area.set_background_video_frame(None)
        except Exception:
            pass

    def _on_karaoke_ended(self):
        if getattr(self, "karaoke_transport", None) is None:
            return
        _ia_record(self, "karaoke_eos")
        _diag("[PY-KARAOKE] decoder reached end of stream")
        QTimer.singleShot(0, self._handle_media_end_safe)

    @staticmethod
    def _load_mpv_playback_backend():
        """Return the one supported bundled native mpv backend."""
        import mpv_playback_iina
        bridge = mpv_playback_iina._runtime_root() / "libsingws_mpv_bridge.dylib"
        if not bridge.is_file():
            raise RuntimeError(f"bundled native mpv bridge missing: {bridge}")
        return mpv_playback_iina.MpvPlaybackPlugin, "native"

    def _ensure_mpv_karaoke_core(self):
        """Lazily attach mpv's two Metal windows to the existing video areas."""
        plugin = getattr(self, "_mpv_playback", None)
        if plugin is not None:
            return plugin
        MpvPlaybackPlugin, _mpv_backend_name = self._load_mpv_playback_backend()
        _diag(f"[MPV] backend={_mpv_backend_name}")
        from mpv_karaoke_transport import MpvVideoHost

        plugin = MpvPlaybackPlugin(log=_diag)
        output_parent = self.video_window.video_area
        preview_parent = self.preview_window.video_area
        output_host = MpvVideoHost(output_parent)
        preview_host = MpvVideoHost(preview_parent)
        output_host.setObjectName("mpv_karaoke_output")
        preview_host.setObjectName("mpv_karaoke_preview")
        for parent, host in ((output_parent, output_host), (preview_parent, preview_host)):
            layout = parent.layout()
            if layout is None:
                layout = QVBoxLayout(parent)
                layout.setContentsMargins(0, 0, 0, 0)
                layout.setSpacing(0)
            layout.addWidget(host)
            host.show()
        QApplication.processEvents()
        if not plugin.attach(preview_host, output_host):
            try:
                plugin.shutdown()
            except Exception:
                pass
            output_host.deleteLater()
            preview_host.deleteLater()
            raise RuntimeError(plugin.errorString() or "mpv surface attach failed")
        app = QApplication.instance()
        if app is not None:
            app.aboutToQuit.connect(plugin.shutdown)
        self._mpv_playback = plugin
        self._mpv_output_host = output_host
        self._mpv_preview_host = preview_host
        self._apply_mpv_display_mode()
        _diag(f"[MPV] initialized plugin={plugin.version()} audio={plugin.audioDescription()}")
        return plugin

    def _mpv_selected_audio_output_name(self) -> str:
        """Return the safe local SingWS output label for libmpv.

        SingWS persists a stable, UI-owned device id while libmpv requires its
        own backend-specific id.  The native bridge resolves this display label
        through mpv's audio-device-list immediately before applying it.
        """
        return self._safe_local_audio_output_name() or "__singws_no_safe_output__"

    def _set_mpv_hosts_visible(self, visible: bool):
        for name in ("_mpv_output_host", "_mpv_preview_host"):
            host = getattr(self, name, None)
            if host is not None:
                host.setVisible(bool(visible))
                if visible:
                    host.raise_()
        if visible:
            # The mpv hosts and the Qt Quick ticker are native child surfaces
            # on macOS. Raising the newly revealed output host can cover a
            # ticker which is still running normally. Reopening the Rotation
            # window used to repair this accidentally by raising the ticker.
            # Do the same after every native-video reveal, including bounded
            # retries while AppKit finishes reconnecting the retained view.
            self._schedule_show_ticker_reassert("mpv_host_reveal")

    def _schedule_show_ticker_reassert(self, reason: str, delays=(0, 80, 250)):
        """Re-raise the ticker after anything that re-orders native surfaces.

        The ticker and the mpv hosts are native child views on macOS: they
        stack by creation order, not by the Qt widget tree, and raising the
        show window can bury a ticker that is still updating normally. Bounded
        retries because AppKit finishes reconnecting the retained views a few
        frames later.
        """
        for delay in delays:
            try:
                QTimer.singleShot(
                    delay,
                    lambda phase=f"{delay}ms": self._reassert_show_ticker_surface(reason, phase),
                )
            except Exception as exc:
                _diag(f"[TICKER] surface reassert scheduling failed reason={reason}: {exc}")

    def _reassert_show_ticker_surface(self, reason: str, phase: str = ""):
        try:
            if not bool(self.settings.get("ticker_enabled", True)):
                return
            video_window = getattr(self, "video_window", None)
            ticker = getattr(video_window, "ticker", None) if video_window is not None else None
            if ticker is None:
                return
            video_window.set_ticker_enabled(True)
            native_reordered = video_window._raise_ticker_surface()
            suffix = f" phase={phase}" if phase else ""
            _diag(
                f"[TICKER] show-screen surface reasserted reason={reason}{suffix} "
                f"native={int(bool(native_reordered))}"
            )
        except Exception as exc:
            _diag(f"[TICKER] surface reassert failed reason={reason}: {exc}")

    def _reassert_show_window_surface(self, reason: str):
        """Order the macOS audience parent forward without taking focus."""
        if sys.platform != "darwin":
            return
        if isinstance(getattr(self, "_active_external_karafun", None), dict):
            return
        video_window = getattr(self, "video_window", None)
        if video_window is None or not video_window.isVisible():
            return
        try:
            import objc
            native_view = objc.objc_object(c_void_p=int(QWidget.winId(video_window)))
            native_window = native_view.window()
            if native_window is None:
                return
            native_window.orderFrontRegardless()
            _diag(f"[SHOW-SURFACE] audience window reasserted reason={reason}")
        except Exception as exc:
            _diag(f"[SHOW-SURFACE] audience window reassert failed reason={reason}: {exc}")

    def _refresh_mpv_video_views(self, reason: str = ""):
        """Re-present libmpv's retained texture after the show window returns."""
        plugin = getattr(self, "_mpv_playback", None)
        refresh = getattr(plugin, "refreshVideoViews", None) if plugin is not None else None
        if not callable(refresh):
            return

        def apply():
            try:
                refresh()
                _diag(f"[MPV] video views refreshed reason={reason}")
            except Exception as exc:
                _diag(f"[MPV] video views refresh failed reason={reason}: {exc}")

        # AppKit may reconnect native children just after Qt emits showEvent.
        # One immediate pass handles ordinary restores; one bounded retry
        # handles that macOS ordering without reloading playback.
        QTimer.singleShot(0, apply)
        QTimer.singleShot(80, apply)
        QTimer.singleShot(250, apply)

    def _reveal_mpv_hosts_if_allowed(self, attempt: int = 0):
        """Readiness-gated reveal that yields to a running painted overlay."""
        if getattr(self, "_mpv_host_overlay_suppressions", None):
            return  # the overlay restores the surface when it clears
        plugin = getattr(self, "_mpv_playback", None)
        try:
            ready = bool(plugin is not None and plugin.visualsReady())
        except Exception:
            ready = False
        if not ready:
            # The transport's audible-start fail-safe may commit queue state
            # before a delayed AppKit/libmpv drawable is ready. Never reveal a
            # black native child over the painted show surface; keep checking
            # for a bounded five seconds instead.
            if attempt < 25 and getattr(self, "karaoke_transport", None) is not None:
                QTimer.singleShot(200, lambda: self._reveal_mpv_hosts_if_allowed(attempt + 1))
            else:
                _diag("[MPV] video reveal timed out waiting for native frame")
            return
        self._set_mpv_hosts_visible(True)

    def _handle_mpv_visual_stall(self, path: str, position_ms: int):
        """Fail visibly and safely when CDG audio runs without a decoded frame."""
        self._set_mpv_hosts_visible(False)
        name = os.path.basename(str(path or "")) or "unknown CDG"
        _diag(
            f"[CDG-WATCHDOG] no visual frame after {int(position_ms)}ms "
            f"file={name!r}; native hosts remain hidden, audio left uninterrupted"
        )
        try:
            self._show_processing_notification(
                f"CDG lyrics did not load for {name}. Audio is still playing; "
                "the black video surface was hidden.",
                level="warning",
                persistent=True,
            )
        except Exception:
            pass

    def _mpv_hosts_should_show(self) -> bool:
        """Whether the mpv surfaces belong on screen right now.

        Mirrors the reveal condition in _start_mpv_karaoke_transport: the mpv
        engine is the live one and it is rendering a picture (audio-only mode
        has nothing to show).
        """
        if str(getattr(self, "_last_karaoke_engine", "") or "").lower() != "mpv":
            return False
        if getattr(self, "karaoke_transport", None) is None:
            return False
        return str(getattr(self, "_current_karaoke_mode", "") or "").lower() in {"cdg", "mp4"}

    def _collect_pre_show_diagnostics(self) -> list[tuple[bool, str, str]]:
        """Read-only checks for the failure points that matter during a show."""
        checks = []

        local_name = self._safe_local_audio_output_name()
        checks.append((
            bool(local_name),
            "Local audio output",
            str(local_name or "No safe local output is selected"),
        ))

        try:
            screen_count = len(QApplication.screens())
        except Exception:
            screen_count = 0
        airplay_video_only = bool(local_name) and screen_count >= 2
        checks.append((
            airplay_video_only,
            "AirPlay video-only routing",
            f"{screen_count} displays; audio pinned to {local_name}"
            if local_name else f"{screen_count} displays; local audio pin missing",
        ))

        karafun_enabled = bool(self.settings.get("karafun_provider_enabled", True))
        try:
            karafun_path = self._karafun_application_path() if karafun_enabled else None
        except Exception:
            karafun_path = None
        checks.append((
            bool(karafun_enabled and karafun_path),
            "KaraFun",
            str(karafun_path) if karafun_path else (
                "Disabled in settings" if not karafun_enabled else "Application not found"
            ),
        ))

        output_host = getattr(self, "_mpv_output_host", None)
        preview_host = getattr(self, "_mpv_preview_host", None)
        checks.append((
            output_host is not None and preview_host is not None,
            "Native video surfaces",
            "show + host preview ready" if output_host is not None and preview_host is not None
            else "show or host preview surface is missing",
        ))

        ticker_enabled = bool(self.settings.get("ticker_enabled", True))
        show_ticker = getattr(getattr(self, "video_window", None), "ticker", None)
        checks.append((
            ticker_enabled and show_ticker is not None,
            "Show ticker",
            "enabled and constructed" if ticker_enabled and show_ticker is not None
            else "disabled or not constructed",
        ))

        qr_url = self._header_qr_url()
        checks.append((
            bool(qr_url),
            "Signup QR URL",
            str(qr_url or "No request URL is configured/detectable"),
        ))

        bg_folder = str(self.settings.get("bg_video_folder", "") or "").strip()
        bg_files = scan_background_video_folder(bg_folder)
        bg_enabled = bool(self.settings.get("bg_video_enabled", False))
        checks.append((
            (not bg_enabled) or bool(bg_files),
            "Background videos",
            (f"{len(bg_files)} playable files in {bg_folder}" if bg_files else
             ("disabled" if not bg_enabled else f"No playable files in {bg_folder or '(unset)'}")),
        ))
        return checks

    def run_pre_show_diagnostics(self):
        checks = self._collect_pre_show_diagnostics()
        passed = sum(1 for ok, _label, _detail in checks if ok)
        lines = [
            f"{'PASS' if ok else 'CHECK'}  {label}: {detail}"
            for ok, label, detail in checks
        ]
        _diag(f"[PRE-SHOW] result={passed}/{len(checks)} " + " | ".join(lines))
        box = QMessageBox(self)
        box.setWindowTitle("Pre-Show Diagnostics")
        box.setIcon(
            QMessageBox.Icon.Information
            if passed == len(checks) else QMessageBox.Icon.Warning
        )
        box.setText(f"{passed} of {len(checks)} checks passed")
        box.setDetailedText("\n".join(lines))
        box.setInformativeText("Open Details to review every show-critical check.")
        box.exec()

    def _suppress_mpv_hosts_for_overlay(self, reason: str, active: bool):
        """Hide the mpv surfaces while a painter-drawn show overlay is running.

        Qt composites a WA_NativeWindow child above everything its parent
        widget paints, so the singer-start / outro transitions -- which
        VideoAreaWidget draws in paintEvent -- were invisible from the moment
        playback started and the host was revealed. Hiding the host for the
        overlay's lifetime is the same mechanism the idle background already
        depends on. Reason-counted so two windows (or a transition overlapping
        another overlay) cannot restore the surface out from under each other.
        """
        reasons = getattr(self, "_mpv_host_overlay_suppressions", None)
        if reasons is None:
            reasons = set()
            self._mpv_host_overlay_suppressions = reasons
        if active:
            reasons.add(str(reason))
        else:
            reasons.discard(str(reason))
        if getattr(self, "_mpv_playback", None) is None:
            return  # no native surfaces to get in the way
        self._set_mpv_hosts_visible(not reasons and self._mpv_hosts_should_show())

    def _video_stretch_supported(self) -> bool:
        """Whether the permanent native backend supports stretch-to-fill."""
        try:
            plugin = getattr(self, "_mpv_playback", None)
            if plugin is None:
                plugin, _name = self._load_mpv_playback_backend()
            return bool(getattr(plugin, "supportsVideoStretch", lambda: True)())
        except Exception:
            return True

    def _apply_mpv_display_mode(self):
        plugin = getattr(self, "_mpv_playback", None)
        if plugin is None:
            return
        mode = self._effective_cdg_display_mode()
        if mode == "stretch" and not bool(
            getattr(plugin, "supportsVideoStretch", lambda: True)()
        ):
            # Do not fail silently: the saved mode renders as "fit" here.
            _diag(
                "[MPV] CDG display mode 'stretch' is not supported by this backend; "
                "rendering as 'fit'"
            )
        plugin.setVideoStretch(mode == "stretch")
        # 0 off, 1 the disc's background colour, 2 an ambient blur of the
        # picture. The colour fill is a deliberate no-op on the many discs whose
        # background is black; the blur fill is the visible-everywhere option.
        plugin.setCdgOutputSidefill(
            2 if mode == "blur" else (1 if mode == "sidefill" else 0)
        )
        # Whether the mode reached the backend at all was previously invisible
        # in the log, which made "side fill does nothing" impossible to triage
        # from a show log.
        _diag(
            f"[MPV] display mode applied mode={mode} "
            f"fill={2 if mode == 'blur' else (1 if mode == 'sidefill' else 0)}"
        )

    def _start_mpv_karaoke_transport(
        self, *, audio_path, video_path, mode, semitones,
        start_seconds=0.0, loop_seconds=None, duration_seconds=None,
    ):
        from mpv_karaoke_transport import MpvKaraokeTransport

        plugin = self._ensure_mpv_karaoke_core()
        output_name = self._mpv_selected_audio_output_name()
        plugin.setAudioDevice(output_name)
        _diag(f"[AUDIO] karaoke output requested={output_name!r} engine=mpv")
        self._stop_karaoke_transport()
        transport = MpvKaraokeTransport(
            plugin,
            audio_path=audio_path,
            video_path=video_path,
            mode=mode,
            parent=self,
        )
        transport.duration_seconds = float(duration_seconds or 0.0)
        transport.started.connect(lambda: _diag("[MPV] audible playback started"))
        transport.visual_stalled.connect(self._handle_mpv_visual_stall)
        if str(mode).lower() != "audio":
            # Not _set_mpv_hosts_visible directly: a singer-start transition is
            # normally already on screen by the time this fires, and revealing
            # the native surface would paint over it.
            transport.started.connect(self._reveal_mpv_hosts_if_allowed)
        transport.ended.connect(self._on_karaoke_ended)
        transport.set_modifiers(
            float(self._clamp_karaoke_tempo(self._karaoke_tempo_percent)) / 100.0,
            float(self._clamp_karaoke_key(semitones)),
        )
        transport.set_volume(float(getattr(self, "_host_karaoke_live_volume", 1.0) or 0.0))
        transport.set_visual_timer_interval_ms(self._effective_visual_timer_interval_ms())
        self._apply_mpv_display_mode()
        # Persistent Metal surfaces can retain the preceding texture. Reveal
        # only from the readiness-gated started signal above.
        self._set_mpv_hosts_visible(False)
        self._current_karaoke_audio_path = str(audio_path or "")
        self.karaoke_transport = transport
        self.karaoke_volume = None
        try:
            transport.start(start_seconds)
            if loop_seconds and len(loop_seconds) == 2:
                transport.set_loop(float(loop_seconds[0]), float(loop_seconds[1]))
        except Exception:
            self.karaoke_transport = None
            self._set_mpv_hosts_visible(False)
            try:
                transport.stop()
            except Exception:
                pass
            raise
        self._last_karaoke_engine = "mpv"
        # Phase 0 instrumentation: outside the start try-block so nothing here can
        # ever tear down a transport that started successfully.
        try:
            self._ia_karaoke_generation = int(getattr(self, "_ia_karaoke_generation", 0) or 0) + 1
            self._ia_media = str(mode or "") or None
            _ia_record(self, 
                "karaoke_start",
                playhead_s=float(start_seconds or 0.0),
                mode=str(mode or ""),
                duration_s=float(duration_seconds) if duration_seconds else None,
                looped=bool(loop_seconds),
                has_video=bool(video_path),
            )
            _ia_observe(self, "start", playhead=float(start_seconds or 0.0), video_path=video_path)
        except Exception:
            pass
        # mpv owns the audio here, so the SingWS chain runs as mpv `af` filters
        # rather than in the Python sample path. Pushed after start() so the
        # engine has a stream to attach the filters to.
        self._push_mpv_audio_processing("song_start", audio_path=audio_path)
        # CDG visual-timing calibration. This path never applied it at all, so
        # even a backend that CAN honour the offset would have started every
        # song uncalibrated and only picked it up if the operator happened to
        # nudge the Display slider mid-song.
        try:
            mode_l = str(mode or "").lower()
            # MP4 was omitted here, so mp4_timing_offset_ms was read only by the
            # painter path and the mpv engine had no video trim at all: an MP4
            # running late could not be corrected from anywhere in the UI.
            if mode_l == "cdg":
                off = self._effective_cdg_timing_offset_ms()
            elif mode_l == "mp4":
                off = self._effective_mp4_timing_offset_ms()
            else:
                off = 0
            if hasattr(transport, "set_video_offset_ms"):
                transport.set_video_offset_ms(off)
                _diag(f"[VIDEO-OFFSET] applying {off:+d}ms visual offset mode={mode} engine=mpv")
        except Exception as exc:
            _diag(f"[VIDEO-OFFSET] mpv offset apply failed: {exc}")
        self._setup_end_silence_state(mode, None)
        # The queue already resolved the original ZIP's duration before this
        # extracted MP3 was handed to playback. Reuse that authoritative hint:
        # probing the randomized temporary filename is less reliable in frozen
        # builds and previously disabled verified tail trimming for every MP3+G.
        self._arm_audio_end_floor(audio_path, duration_seconds)
        self._arm_visual_end_floor(video_path, mode)
        self._update_karaoke_key_ui()
        _diag(
            f"[KARAOKE-ENGINE] engine=mpv mode={mode} "
            f"file={os.path.basename(audio_path)} key={int(semitones):+d} "
            f"tempo={float(self._karaoke_tempo_percent):.0f}%"
        )
        return True

    def _start_karaoke_transport(
        self,
        *,
        audio_path: str,
        video_path: str | None,
        mode: str,
        semitones: int,
        start_seconds: float = 0.0,
        loop_seconds=None,
        duration_seconds: float | None = None,
    ):
        # One authoritative playback path. A native-core failure is surfaced
        # by _start_mpv_karaoke_transport; silently changing clocks/renderers
        # in the middle of a live show is no longer permitted.
        return self._start_mpv_karaoke_transport(
            audio_path=audio_path,
            video_path=video_path,
            mode=mode,
            semitones=semitones,
            start_seconds=start_seconds,
            loop_seconds=loop_seconds,
            duration_seconds=duration_seconds,
        )

    def _prepare_karaoke_start(self, media_path: str):
        self.karaoke_playing = True
        try:
            self._mark_daw_preview_playback_started(media_path)
        except Exception:
            pass
        try:
            self.update_bg_button_state()
        except Exception:
            pass
        self._prepare_bg_for_karaoke_start(media_path)
        self.video_window.idle = False
        self.video_window.force_black = False
        self.video_window.update()
        self.preview_window.force_black = False
        self.preview_window.update()

    def _play_mp4(self, song_path, semitones=0, start_seconds=0.0, loop_seconds=None):
        self._reset_end_silence_state()
        self._prepare_karaoke_start(song_path)
        self._current_karaoke_mode = "mp4"
        self._current_karaoke_semitones = int(semitones or 0)
        try:
            machine = platform.machine() or ""
        except Exception:
            machine = ""
        try:
            _diag(
                "[MP4-PERF] start "
                f"media_type=MP4 file={Path(song_path).name!r} "
                f"platform={sys.platform}/{machine} "
                f"visual_timer_ms={self._effective_visual_timer_interval_ms()} "
                f"workers={self._active_worker_snapshot()}"
            )
        except Exception:
            pass
        return self._start_karaoke_transport(
            audio_path=song_path,
            video_path=song_path,
            mode="mp4",
            semitones=self._current_karaoke_semitones,
            start_seconds=start_seconds,
            loop_seconds=loop_seconds,
        )

    def _play_cdg(self, cdg_path, mp3_path, semitones=0, start_seconds=0.0, loop_seconds=None, duration_seconds=None):
        self._prepare_karaoke_start(mp3_path)
        self._current_karaoke_mode = "cdg"
        self._current_karaoke_cdg_path = str(cdg_path or "")
        self._current_karaoke_mp3_path = str(mp3_path or "")
        self._current_karaoke_semitones = int(semitones or 0)
        try:
            pending = getattr(self, "_pending_playback_countdown_payload", None)
            current_singer = str(pending.get("singer") or "") if isinstance(pending, dict) else self._get_current_singer()
            duration = float(duration_seconds or self._get_duration_secs(mp3_path) or 0.0)
            SingWSLogger.log_playback_start("CDG", cdg_path, semitones, current_singer, duration)
        except Exception:
            pass
        started = self._start_karaoke_transport(
            audio_path=mp3_path,
            video_path=cdg_path,
            mode="cdg",
            semitones=self._current_karaoke_semitones,
            start_seconds=start_seconds,
            loop_seconds=loop_seconds,
            duration_seconds=duration_seconds,
        )
        # Optional shuffled MP4 background behind the CDG lyrics. Runs on its
        # own muted video-only pipeline so audio timing/key/tempo are
        # untouched; falls back to the normal background when disabled/empty.
        if started:
            try:
                # Decorative video startup is deliberately delayed until the
                # real karaoke transport has accepted its start. This keeps it
                # out of the Play-button critical section on slower Macs.
                QTimer.singleShot(self._playback_safe_ui_delay_ms(180), self._start_lyrics_background_video)
            except Exception as e:
                _diag(f"[BG-VIDEO] start hook failed: {e}")
        return bool(started)

    def _play_mp3(self, song_path, semitones=0, start_seconds=0.0, loop_seconds=None):
        self._reset_end_silence_state()
        self._prepare_karaoke_start(song_path)
        self._current_karaoke_mode = "mp3"
        self._current_karaoke_semitones = int(semitones or 0)
        return self._start_karaoke_transport(
            audio_path=song_path,
            video_path=None,
            mode="audio",
            semitones=self._current_karaoke_semitones,
            start_seconds=start_seconds,
        )

    def _gst_teardown(self):
        """Stop the karaoke transport and reset per-song modifiers.

        The legacy GStreamer pipeline objects this used to tear down were
        removed long ago (gst_pipeline & co. were always None), so the
        transport stop is the whole job now."""
        self._stop_karaoke_transport()
        self._karaoke_transport_tempo_ratio = 1.0

    def _gst_teardown_async(self):
        """Stop playback without blocking the UI.

        Kept as a separate entry point for call sites that used to need a
        worker-thread teardown of legacy pipelines; the transport stops
        in-place and there is nothing left to defer."""
        self._stop_karaoke_transport()
        self._karaoke_transport_tempo_ratio = 1.0

    def _recover_idle_output(self, reason: str, ensure_bg: bool = True):
        """Single-path idle visual/audio recovery used by teardown success and fallback paths."""
        has_pipe = False  # legacy pipelines removed; transport owns playback
        karaoke_active = bool(getattr(self, "karaoke_playing", False))
        if karaoke_active or has_pipe:
            _diag(
                f"[IDLE-RECOVER] skipped reason={reason} ensure_bg={bool(ensure_bg)} "
                f"karaoke_playing={karaoke_active} has_pipeline={has_pipe}"
            )
            return
        try:
            self.karaoke_playing = False
            self._reset_end_silence_state()
            self._reset_karaoke_tempo_for_track_end()
            self.video_window.force_black = False
            self.video_window.idle = True
            self.preview_window.force_black = True
        except Exception:
            pass

        # GStreamer video sinks were removed.  Do not create or touch native
        # parking windows here: a hidden Cocoa child can still participate in
        # QBackingStore flushes while screens are changing at song handoff.
        self._teardown_detach_sinks = []

        try:
            self._recreate_video_surfaces(f"idle_recover:{reason}")
        except Exception:
            pass

        try:
            self._apply_idle_background(force=True, advance_slideshow=True)
            self.video_window.update()
            self.preview_window.update()
        except Exception:
            pass

        # Reassert preview idle-black shortly after handoff; this clears occasional
        # stale preview sink frames that can persist after teardown.
        self._schedule_preview_idle_reassert(reason)

        if ensure_bg:
            try:
                should_have_bg = bool(self.settings.get("bg_enabled", True)) and bool(self.settings.get("bg_autoplay_on_idle", True))
                bg = getattr(self, "bg_music", None)
                if should_have_bg and bg and bool(getattr(bg, "playlist", None)) and not bool(getattr(bg, "is_playing", False)):
                    self._bg_resume_reason = "idle_recover"
                    self._start_bg_with_fade_safe("idle_recover")
            except Exception:
                pass

        try:
            bg = getattr(self, "bg_music", None)
            bg_playing = bool(getattr(bg, "is_playing", False)) if bg is not None else False
            pix_ok = not bool(getattr(self.video_window.video_area, "background_pixmap", QPixmap()).isNull())
            has_pipe = False  # legacy pipelines removed; transport owns playback
            _diag(
                f"[IDLE-RECOVER] reason={reason} ensure_bg={bool(ensure_bg)} idle={bool(getattr(self.video_window, 'idle', False))} "
                f"bg_playing={bg_playing} has_pipeline={has_pipe} pix_ok={pix_ok}"
            )
        except Exception:
            pass

    def _schedule_preview_idle_reassert(self, reason: str):
        try:
            QTimer.singleShot(140, lambda: self._reassert_preview_idle(reason, "140ms"))
            QTimer.singleShot(520, lambda: self._reassert_preview_idle(reason, "520ms"))
        except Exception:
            pass

    def _reassert_preview_idle(self, reason: str, phase: str):
        try:
            has_pipe = False  # legacy pipelines removed; transport owns playback
            if bool(getattr(self, "karaoke_playing", False)) or has_pipe:
                return
            pw = getattr(self, "preview_window", None)
            if pw is None:
                return
            pw.force_black = True
            try:
                area = getattr(pw, "video_area", None)
                if area is not None and hasattr(area, "clear_karaoke_frame"):
                    area.clear_karaoke_frame()
            except Exception:
                pass
            pw.update()
        except Exception:
            pass

    def _detach_video_sinks_now(self, reason: str):
        """Compatibility no-op now that karaoke uses the Python renderer."""
        self._teardown_detach_sinks = []

    def _get_sink_parking_winid(self):
        """Legacy API retained for callers; no native parking surface exists."""
        return 0

    def _recreate_video_surfaces(self, reason: str):
        """Clear stale frames without replacing live native macOS widgets.

        Native surface replacement was required by the removed GStreamer video
        overlay. The Python renderer paints into persistent Qt widgets, and
        deleting those widgets during pending Cocoa backing-store flushes can
        leave Qt with a window whose screen paint device has already gone away.
        """
        try:
            _diag(f"[VIDSURFACE-DIAG] stable refresh reason={reason} | {_describe_window_topology()}")
        except Exception:
            pass
        for window_name in ("video_window", "preview_window"):
            try:
                window = getattr(self, window_name, None)
                area = getattr(window, "video_area", None) if window is not None else None
                if area is not None and hasattr(area, "clear_karaoke_frame"):
                    area.clear_karaoke_frame()
            except Exception:
                pass
        try:
            self._refresh_show_screen_qr(f"surface_refresh:{reason}", force=True)
        except Exception:
            pass

    @pyqtSlot()
    def _on_gst_teardown_complete(self):
        """Main-thread teardown completion hook for UI recovery and deferred actions."""
        self._stop_in_progress = False
        self._teardown_active = False
        if bool(getattr(self, "_app_closing", False)):
            return
        pending_next = bool(getattr(self, "_playnext_pending", False))
        if hasattr(self, "_manual_stop_t0"):
            self._log_manual_stop_timeline("teardown_complete")
        try:
            _diag(
                f"[TEARDOWN] complete karaoke_playing={bool(getattr(self, 'karaoke_playing', False))} "
                f"has_pipeline=False"
            )
        except Exception:
            pass

        # Recover only when karaoke is truly idle. If a new track already started,
        # this completion belongs to an older teardown and must not force BG/idle.
        if pending_next:
            _diag("[TEARDOWN] idle recovery skipped: play-next pending")
        else:
            self._recover_idle_output("teardown_complete", ensure_bg=True)

        # If user hit Play Next while teardown was running, run it now.
        if pending_next:
            self._playnext_pending = False
            QTimer.singleShot(0, self.play_next_file)

    def start_freeze_detector(self):
        """DIAGNOSTIC: Detect UI thread freezes"""
        import time as time_module
        self._last_heartbeat = time_module.time()
        self._freeze_detector = QTimer(self)
        self._freeze_detector.timeout.connect(self._heartbeat)
        self._freeze_detector.start(1000)  # Every 1 second
        print("[FREEZE-DETECT] Freeze detector started")
    
    def _heartbeat(self):
        """DIAGNOSTIC: Called every second - if this stops, UI is frozen"""
        import time as time_module
        now = time_module.time()
        delta = now - self._last_heartbeat
        _perf_record("ui_heartbeat_jitter", max(0.0, (delta - 1.0) * 1000.0))
        
        if delta > 5.0:  # More than 5 seconds since last heartbeat
            print(f"⚠️⚠️⚠️ UI FREEZE DETECTED! {delta:.1f} seconds since last update ⚠️⚠️⚠️")
            
            # Collect state info
            state_info = {}
            try:
                state_info['karaoke_playing'] = getattr(self, 'karaoke_playing', False)
                state_info['pipeline_exists'] = False  # legacy pipelines removed
                state_info['polling_running'] = getattr(self, 'poll_thread', None) and self.poll_thread.isRunning()
                
                print(f"  - Karaoke playing: {state_info['karaoke_playing']}")
                print(f"  - Pipeline exists: {state_info['pipeline_exists']}")
                print(f"  - Polling thread running: {state_info['polling_running']}")
            except Exception as e:
                print(f"  - Error logging state: {e}")
            
            # Log to file with full details
            SingWSLogger.log_freeze_detected(delta, state_info)
        
        self._last_heartbeat = now

    def _start_perf_summary_timer(self):
        try:
            if not bool(self.settings.get("performance_debug_enabled", False)):
                return
            timer = getattr(self, "_perf_summary_timer", None)
            if timer is None:
                timer = QTimer(self)
                timer.timeout.connect(self._log_perf_summary)
                self._perf_summary_timer = timer
            try:
                interval = max(5, int(float(self.settings.get("performance_log_interval_sec", 15))))
            except Exception:
                interval = 15
            timer.start(interval * 1000)
        except Exception:
            pass

    def _active_worker_snapshot(self) -> str:
        pairs = []
        for name in ("poll_thread", "_search_thread", "_dur_thread", "_index_thread", "_songbook_upload_thread"):
            try:
                obj = getattr(self, name, None)
                running = bool(obj is not None and hasattr(obj, "isRunning") and obj.isRunning())
            except Exception:
                running = False
            pairs.append(f"{name}={int(running)}")
        return " ".join(pairs)

    def _log_perf_summary(self):
        if not bool(self.settings.get("performance_debug_enabled", False)):
            return
        try:
            cpu = "n/a"
            mem = "n/a"
            if PSUTIL_AVAILABLE:
                proc = psutil.Process(os.getpid())
                cpu = f"{proc.cpu_percent(interval=None):.1f}%"
                mem = f"{proc.memory_info().rss / (1024 * 1024):.1f}MB"
            rows = PERF_STATS.snapshot()[:10]
            top = "; ".join(
                f"{r['name']} max={r['max']:.0f}ms avg={r['avg']:.1f}ms n={r['count']} slow={r['slow']}"
                for r in rows
            ) or "no samples yet"
            try:
                q_count = len(getattr(self, "queue", []) or [])
            except Exception:
                q_count = 0
            try:
                result_count = self.results_list.count() if hasattr(self, "results_list") else 0
            except Exception:
                result_count = 0
            try:
                track_count = len(getattr(self, "tracks", []) or [])
            except Exception:
                track_count = 0
            print(
                "[PERF-SUMMARY] "
                f"cpu={cpu} mem={mem} threads={threading.active_count()} "
                f"tracks={track_count} queue={q_count} results={result_count} "
                f"{self._active_worker_snapshot()} top=[{top}]"
            )
        except Exception as e:
            print(f"[PERF-SUMMARY] failed: {e}")

    def _start_memory_telemetry(self):
        """Sample bounded cache/process growth without adding UI work."""
        if not PSUTIL_AVAILABLE:
            return
        try:
            timer = getattr(self, "_memory_telemetry_timer", None)
            if timer is None:
                timer = QTimer(self)
                timer.timeout.connect(self._log_memory_telemetry)
                self._memory_telemetry_timer = timer
            timer.start(5 * 60 * 1000)
            QTimer.singleShot(60 * 1000, self._log_memory_telemetry)
        except Exception:
            pass

    def _log_memory_telemetry(self, *, force: bool = False):
        """Log first sample, material RSS growth, and a 30-minute heartbeat."""
        if not PSUTIL_AVAILABLE:
            return
        try:
            now = time.monotonic()
            rss_mb = psutil.Process(os.getpid()).memory_info().rss / (1024 * 1024)
            last_rss = float(getattr(self, "_memory_telemetry_logged_rss_mb", 0.0) or 0.0)
            last_log = float(getattr(self, "_memory_telemetry_last_log_ts", 0.0) or 0.0)
            growth_mb = rss_mb - last_rss if last_rss > 0 else 0.0
            should_log = bool(
                force
                or last_rss <= 0
                or growth_mb >= 128.0
                or now - last_log >= 30 * 60
            )
            if not should_log:
                return
            self._memory_telemetry_logged_rss_mb = rss_mb
            self._memory_telemetry_last_log_ts = now
            display_cache = len(getattr(self, "_display_name_cache", {}) or {})
            search_cache = len(getattr(song_index, "_SEARCH_CACHE", {}) or {})
            lookup_cache = len(getattr(song_index, "_LOOKUP_CACHE", {}) or {})
            queue_rows = sum(
                len((singer or {}).get("songs", []) or [])
                for singer in (getattr(self, "queue", []) or [])
                if isinstance(singer, dict)
            )
            # Live decoder readers and the RGB they hold. The 07-25 show grew
            # 790MB -> 2148MB while every instrumented cache stayed tiny (215
            # entries total), so the frame pipeline is the remaining suspect:
            # each reader can retain MAX_BUFFERED_FRAMES of full-size RGB. A
            # readers count that climbs across a show means they outlive songs.
            readers = "readers=0 running=0 frames=0 frames_mb=0.0"
            _diag(
                "[MEMORY] "
                f"rss_mb={rss_mb:.0f} growth_mb={growth_mb:+.0f} "
                f"tracks={len(getattr(self, 'tracks', []) or [])} queue_songs={queue_rows} "
                f"display_cache={display_cache} search_cache={search_cache} "
                f"lookup_cache={lookup_cache} threads={threading.active_count()} "
                f"{readers}"
            )
        except Exception as exc:
            _diag_rate_limited(
                "memory_telemetry_failure",
                f"[MEMORY] telemetry unavailable error={exc}",
                1800.0,
            )

    def _perf_process_snapshot(self) -> tuple[str, str]:
        cpu = "n/a"
        mem = "n/a"
        if PSUTIL_AVAILABLE:
            try:
                proc = psutil.Process(os.getpid())
                cpu = f"{proc.cpu_percent(interval=None):.1f}%"
                mem = f"{proc.memory_info().rss / (1024 * 1024):.0f}MB"
            except Exception:
                pass
        return cpu, mem

    def _tick_perf_debug_overlay(self):
        """Periodically log playback diagnostics ([MP4-PERF]) to the log file.
        There is no on-screen overlay; this is invisible during normal use."""
        try:
            enabled = bool(self.settings.get("performance_debug_enabled", False))
            transport = getattr(self, "karaoke_transport", None)
            active = bool(enabled and transport is not None and getattr(self, "karaoke_playing", False))
            if not active or not hasattr(transport, "diagnostics"):
                return
            diag = transport.diagnostics()
            now = time.monotonic()
            if now - float(getattr(self, "_perf_debug_overlay_last_log_ts", 0.0) or 0.0) >= 5.0:
                self._perf_debug_overlay_last_log_ts = now
                video = diag.get("video") if isinstance(diag.get("video"), dict) else {}
                _diag(
                    "[MP4-PERF] "
                    f"media={diag.get('media_type')} decoder={video.get('decoder', 'n/a')} codec={video.get('codec', 'n/a')} "
                    f"renderer={video.get('renderer', 'n/a')} "
                    f"hw={video.get('hardware_acceleration', 'n/a')} hw_checked={int(bool(video.get('hardware_acceleration_checked')))} "
                    f"src={video.get('source_size', '')} out={video.get('output_size', '')} "
                    f"fps={float(video.get('delivered_fps', 0.0) or 0.0):.1f}/{float(video.get('fps', 0.0) or 0.0):.1f} "
                    f"queue={int(video.get('queue_size', 0) or 0)}/{int(video.get('max_buffered_frames', 0) or 0)} "
                    f"drops={int(video.get('dropped_frames', 0) or 0)} "
                    f"video_eof={int(bool(video.get('eof_received')))} drained={int(bool(video.get('eof_drained')))} "
                    f"holding_last={int(bool(video.get('holding_last_frame')))} last_frame_pts_ns={video.get('last_frame_pts_ns')} "
                    f"render_ms={float(diag.get('last_visual_render_ms', 0.0) or 0.0):.1f} "
                    f"render_max_ms={float(diag.get('visual_render_max_ms', 0.0) or 0.0):.1f} "
                    # Visual tick health. The tick is a 15ms QTimer, so an
                    # emit_fps well under ~66 means the main thread is not
                    # getting scheduled on time -- which is what jittery,
                    # slightly-late lyrics actually are. Without this the app
                    # measured its own smoothness and discarded it.
                    f"visual_ticks={int(diag.get('visual_ticks', 0) or 0)} "
                    f"visual_emits={int(diag.get('visual_emits', 0) or 0)} "
                    f"visual_emit_fps={float(diag.get('visual_emit_fps', 0.0) or 0.0):.1f} "
                    f"visual_timer_ms={int(diag.get('visual_timer_ms', 0) or 0)} "
                    f"audible_time_s={float(diag.get('audible_position_seconds', diag.get('position_seconds', 0.0)) or 0.0):.3f} "
                    f"display_time_s={float(diag.get('display_position_seconds', diag.get('position_seconds', 0.0)) or 0.0):.3f} "
                    f"clock_source_s={float(diag.get('audio_clock_source_seconds', 0.0) or 0.0):.3f} "
                    f"clock_delta_s={float(diag.get('audio_clock_delta_seconds', 0.0) or 0.0):.3f} "
                    f"audio_buffer_bytes={int(diag.get('audio_buffer_bytes', 0) or 0)} "
                    f"audio_buffer_ms={float(diag.get('audio_buffer_ms', diag.get('audio_latency_ms', 0.0)) or 0.0):.0f} "
                    f"video_offset_ms={float(diag.get('video_offset_ms', 0.0) or 0.0):+.0f} "
                    f"underruns={int(diag.get('audio_underruns', 0) or 0)}"
                )
        except Exception as e:
            print(f"[MP4-PERF] diagnostics log failed: {e}")

    def configure_crossfade(self):
        """Configure crossfade settings"""
