    # ------------------------------------------------------------------
    # WebSocket request relay (wss://wskar.com/relay + get_requests_v2.php)
    # ------------------------------------------------------------------

    RELAY_MIN_APP_VERSION = (0, 3, 0, 0)
    # v2 DAW host-control over WebSocket is for app versions strictly newer than
    # 3.0.0.0 (the server spec's notation); in this app's 0.3.0.x scheme that is
    # > (0,3,0,0), i.e. >= (0,3,0,1).
    DAW_RELAY_MIN_APP_VERSION = (0, 3, 0, 1)
    RELAY_HOSTS = {"wskar.com", "www.wskar.com"}
    NETWORK_RECOVERY_TICK_MS = 2000
    RELAY_RECOVERY_FETCH_SEC = 10.0
    TERMINAL_RETRY_DELAYS_SEC = (5.0, 15.0, 30.0, 60.0, 120.0, 300.0)
    RELAY_HEALTHY_RECOVERY_FETCH_SEC = 60.0

    @staticmethod
    def _version_tuple(version: str) -> tuple:
        parts = []
        for chunk in str(version or "").split("."):
            digits = "".join(ch for ch in chunk if ch.isdigit())
            parts.append(int(digits) if digits else 0)
        return tuple(parts) if parts else (0,)

    def _request_transport_setting(self) -> str:
        """Transport preference: auto (default) | websocket/relay | polling."""
        env_value = str(os.environ.get("SINGWS_REQUEST_TRANSPORT", "") or "").strip().lower()
        value = env_value or str(self.settings.get("request_transport", "auto") or "auto").strip().lower()
        if value in ("websocket", "relay"):
            return "websocket"
        if value == "polling":
            return "polling"
        return "auto"

    def _supports_request_relay(self) -> bool:
        if not QTWEBSOCKETS_AVAILABLE or QWebSocket is None:
            return False
        return self._version_tuple(APP_VERSION) >= self.RELAY_MIN_APP_VERSION

    def _should_use_request_relay(self, base_url: str, tenant: str, api_key: str) -> bool:
        if self._request_transport_setting() == "polling":
            return False
        if not self._supports_request_relay():
            return False
        if not (tenant or "").strip() or not (api_key or "").strip():
            return False
        host = QUrl(_network_normalize_base_url(base_url)).host().strip().lower()
        return host in self.RELAY_HOSTS

    def _start_request_relay(self, base_url: str, tenant: str, api_key: str):
        try:
            app = QApplication.instance()
            if app is not None and QThread.currentThread() != app.thread():
                self._run_on_ui_thread(lambda: self._start_request_relay(base_url, tenant, api_key))
                return
        except Exception:
            pass
        self._stop_request_relay()
        self._relay_fetch_in_flight = False
        self._relay_fetch_queued = False
        self._relay_last_successful_fetch_at = 0.0
        self._relay_recovery_last_attempt_at = 0.0
        self._relay_last_snapshot_signature = ""
        self._relay_last_snapshot_queue_revision = -1
        worker = RelayRequestWorker(base_url, tenant, api_key, APP_VERSION, parent=self)
        worker.requests_available.connect(self.fetch_remote_requests_once)
        worker.history_available.connect(lambda reason: self._sync_singer_history_async(f"relay_{reason}"))
        worker.connection_status_changed.connect(self._set_server_connection_status)
        self.relay_worker = worker
        worker.start()

    def _stop_request_relay(self):
        try:
            app = QApplication.instance()
            if app is not None and QThread.currentThread() != app.thread():
                self._run_on_ui_thread(self._stop_request_relay)
                return
        except Exception:
            pass
        worker = getattr(self, "relay_worker", None)
        self.relay_worker = None
        if worker is not None:
            try:
                app_closing = bool(getattr(self, "_app_closing", False))
                worker.stop(delete_later=not app_closing)
                if not app_closing:
                    worker.deleteLater()
                else:
                    worker.setParent(None)
                    orphans = getattr(self, "_shutdown_relay_workers", None)
                    if not isinstance(orphans, list):
                        orphans = []
                        self._shutdown_relay_workers = orphans
                    orphans.append(worker)
            except Exception:
                pass

    # ── v2 DAW host-control over WebSocket ───────────────────────────────────
    def _supports_host_control_relay(self) -> bool:
        if not QTWEBSOCKETS_AVAILABLE or QWebSocket is None:
            return False
        return self._version_tuple(APP_VERSION) >= self.DAW_RELAY_MIN_APP_VERSION

    def _should_use_host_control_relay(self, base_url: str, tenant: str, api_key: str) -> bool:
        if self._request_transport_setting() == "polling":
            return False
        if not self._supports_host_control_relay():
            return False
        if not (tenant or "").strip() or not (api_key or "").strip():
            return False
        host = QUrl(_network_normalize_base_url(base_url)).host().strip().lower()
        return host in self.RELAY_HOSTS

    def _start_host_control_relay(self, base_url: str, tenant: str, api_key: str):
        try:
            app = QApplication.instance()
            if app is not None and QThread.currentThread() != app.thread():
                self._run_on_ui_thread(lambda: self._start_host_control_relay(base_url, tenant, api_key))
                return
        except Exception:
            pass
        self._stop_host_control_relay()
        worker = HostControlRelayWorker(base_url, tenant, api_key, APP_VERSION, parent=self)
        worker.command_received.connect(self._on_host_relay_command)
        worker.connection_status_changed.connect(self._set_server_connection_status)
        self.host_relay_worker = worker
        worker.start()
        # Publisher: push playback_tick frequently + full state on change, so the
        # v2 DAW page tracks position smoothly. GUI-thread QTimer; cheap, never
        # touches the audio thread.
        timer = getattr(self, "_host_relay_pub_timer", None)
        if timer is None:
            timer = QTimer(self)
            timer.timeout.connect(self._publish_host_state_ws)
            self._host_relay_pub_timer = timer
        self._host_relay_last_full_sig = ""
        self._host_relay_last_full_at = 0.0
        timer.start(150)

    def _stop_host_control_relay(self):
        try:
            app = QApplication.instance()
            if app is not None and QThread.currentThread() != app.thread():
                self._run_on_ui_thread(self._stop_host_control_relay)
                return
        except Exception:
            pass
        timer = getattr(self, "_host_relay_pub_timer", None)
        if timer is not None:
            try:
                timer.stop()
            except Exception:
                pass
        worker = getattr(self, "host_relay_worker", None)
        self.host_relay_worker = None
        if worker is not None:
            try:
                app_closing = bool(getattr(self, "_app_closing", False))
                worker.stop(delete_later=not app_closing)
                if not app_closing:
                    worker.deleteLater()
                else:
                    worker.setParent(None)
                    orphans = getattr(self, "_shutdown_relay_workers", None)
                    if not isinstance(orphans, list):
                        orphans = []
                        self._shutdown_relay_workers = orphans
                    orphans.append(worker)
            except Exception:
                pass

    def _on_host_relay_command(self, data: dict):
        worker = getattr(self, "host_relay_worker", None)
        if worker is None or not isinstance(data, dict):
            return
        request_id = data.get("request_id")
        action = str(data.get("command") or data.get("action") or "").strip().lower()
        args = data.get("args")
        if not isinstance(args, dict):
            args = {}
        ok = False
        message = ""
        try:
            _diag(f"[HOST-RELAY] command received id={request_id} action={action}")
            ok, message = self._execute_host_control_command(action, args)
        except Exception as e:
            ok, message = False, str(e)
            _diag(f"[HOST-RELAY] command failed id={request_id} action={action} reason={message}")
        worker.send_json({"type": "ack", "request_id": request_id, "ok": bool(ok), "message": str(message or "")})
        # Push a fresh full state right after a command so the UI snaps to truth.
        self._publish_host_state_ws(force=True)

    def _publish_host_state_ws(self, force: bool = False):
        worker = getattr(self, "host_relay_worker", None)
        if worker is None or not worker.is_connected():
            return
        try:
            state = self._host_control_state()
        except Exception:
            return
        playback = state.get("playback", {}) if isinstance(state, dict) else {}
        # Frequent lightweight tick for smooth position.
        worker.send_json({
            "type": "playback_tick",
            "position_seconds": playback.get("position_seconds", 0.0),
            "duration_seconds": playback.get("duration_seconds", 0.0),
            "remaining_seconds": playback.get("remaining_seconds", 0.0),
            "is_playing": playback.get("is_playing", False),
            "updated_at": int(time.time()),
        })
        # Full state on change (rotation/song/key/tempo/bgm) or at least every ~3s.
        full = {
            "type": "state",
            "user": self.settings.get("user", self.settings.get("tenant", "")),
            "app_version": APP_VERSION,
            "connected": True,
            "updated_at": int(time.time()),
            "rotation": state.get("rotation", {}),
            "playback": playback,
        }
        sig = json.dumps([full["rotation"], playback.get("key"), playback.get("tempo"),
                          playback.get("bgm_volume"), playback.get("karaoke_volume"),
                          playback.get("title")], sort_keys=True)
        now = time.monotonic()
        if force or sig != getattr(self, "_host_relay_last_full_sig", "") or \
           (now - getattr(self, "_host_relay_last_full_at", 0.0)) > 3.0:
            self._host_relay_last_full_sig = sig
            self._host_relay_last_full_at = now
            worker.send_json(full)

    def fetch_remote_requests_once(self, reason: str = "relay"):
        """Fetch active remote requests from get_requests_v2.php in a background thread.

        Never overlaps fetches: a notification that lands mid-fetch queues
        exactly one follow-up fetch.
        """
        if bool(getattr(self, "_relay_fetch_in_flight", False)):
            self._relay_fetch_queued = True
            return
        self._relay_fetch_in_flight = True

        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        print(f"[REQUESTS] Fetching due to {reason}")

        def worker():
            rows = None
            try:
                resp = requests.get(
                    f"{base_url}/get_requests_v2.php",
                    params={"user": tenant, "sync": "1"},
                    headers={"X-API-Key": api_key, "User-Agent": f"SingWS/{APP_VERSION}"},
                    timeout=10,
                )
                if resp.status_code == 200:
                    data = resp.json()
                    if isinstance(data, list):
                        rows = data
                    else:
                        print(f"[REQUESTS] v2 fetch: unexpected payload (not a list): {str(data)[:160]!r}")
                else:
                    print(f"[REQUESTS] v2 fetch failed: HTTP {resp.status_code} - {(resp.text or '')[:160]!r}")
            except Exception as e:
                print(f"[REQUESTS] v2 fetch failed: {e}")
            finally:
                fetched = rows
                self._run_on_ui_thread(lambda: self._relay_fetch_finished(fetched))

        threading.Thread(target=worker, daemon=True, name="relay-request-fetch").start()

    def _relay_fetch_finished(self, rows):
        self._relay_fetch_in_flight = False
        try:
            if rows is not None:
                self._relay_last_successful_fetch_at = time.monotonic()
                _diag_rate_limited(
                    "network_recovery_success",
                    "[NETWORK-RECOVERY] request refresh succeeded "
                    f"rows={len(rows or [])}",
                    60.0,
                )
                self._handle_relay_requests(rows)
            else:
                _diag("[NETWORK-RECOVERY] request refresh failed; pending requests preserved")
        finally:
            if bool(getattr(self, "_relay_fetch_queued", False)):
                self._relay_fetch_queued = False
                self.fetch_remote_requests_once("queued notification")

    def _start_network_recovery_timer(self) -> bool:
        """Run request recovery and durable-add retries without any screen open."""
        try:
            timer = getattr(self, "_network_recovery_timer", None)
            if timer is None:
                timer = QTimer(self)
                timer.timeout.connect(self._network_recovery_tick)
                self._network_recovery_timer = timer
            timer.start(int(self.NETWORK_RECOVERY_TICK_MS))
            _diag(
                "[NETWORK-RECOVERY] watchdog started "
                f"tick_ms={int(self.NETWORK_RECOVERY_TICK_MS)} "
                f"relay_fetch_sec={float(self.RELAY_RECOVERY_FETCH_SEC):.1f}"
            )
            return True
        except Exception as exc:
            # Unit tests construct a Python-only KaraokeApp without initializing
            # QObject; production instances always take the successful path.
            _diag(f"[NETWORK-RECOVERY] watchdog unavailable error={exc}")
            return False

    def _stop_network_recovery_timer(self) -> None:
        try:
            timer = getattr(self, "_network_recovery_timer", None)
            if timer is not None:
                timer.stop()
        except Exception:
            pass

    def _network_recovery_tick(self) -> None:
        """Retry pending sends and periodically recover missed relay notices."""
        state = object.__getattribute__(self, "__dict__")
        if bool(state.get("_app_closing", False)) or not self.is_network_configured():
            return

        try:
            pending_count = len(list(state.get("_host_request_sync_ops", []) or []))
        except Exception:
            pending_count = 0
        if pending_count:
            scheduled = self._flush_host_request_sync_ops()
            if scheduled:
                _diag(
                    "[NETWORK-RECOVERY] durable host retry scheduled "
                    f"pending={pending_count} sends={scheduled}"
                )

        try:
            tombstones = state.get("_remote_request_tombstones", {})
            terminal_pending = sum(
                1 for item in ((tombstones or {}).get("requests", {}) or {}).values()
                if isinstance(item, dict) and item.get("request_id") and not item.get("server_synced_at")
            )
        except Exception:
            terminal_pending = 0
        now_wall = time.time()
        terminal_due = sum(
            1 for item in ((tombstones or {}).get("requests", {}) or {}).values()
            if isinstance(item, dict)
            and item.get("request_id")
            and not item.get("server_synced_at")
            and self._remote_tombstone_retry_due(item, now=now_wall)
        ) if terminal_pending else 0
        if terminal_due:
            _diag_rate_limited(
                "terminal_retry_watchdog",
                "[REQUEST-LIFECYCLE] terminal retry watchdog "
                f"pending={terminal_pending} due={terminal_due} reason=network_watchdog",
                30.0,
            )
            self._sync_remote_removal_tombstones_async("network_watchdog")

        # WebSocket notifications remain the immediate path.  This bounded
        # recovery fetch covers a missed notification or a relay that appears
        # connected but stopped delivering events.  Request IDs plus the
        # intake/in-flight sets keep repeated snapshots idempotent.
        if state.get("relay_worker") is None:
            return
        now = time.monotonic()
        last_success = float(state.get("_relay_last_successful_fetch_at", 0.0) or 0.0)
        last_attempt = float(state.get("_relay_recovery_last_attempt_at", 0.0) or 0.0)
        worker = state.get("relay_worker")
        try:
            relay_healthy = bool(worker.is_connected())
        except Exception:
            relay_healthy = False
        recovery_interval = (
            float(self.RELAY_HEALTHY_RECOVERY_FETCH_SEC)
            if relay_healthy
            else float(self.RELAY_RECOVERY_FETCH_SEC)
        )
        if now - max(last_success, last_attempt) < recovery_interval:
            return
        self._relay_recovery_last_attempt_at = now
        _diag_rate_limited(
            "network_recovery_scheduled",
            "[NETWORK-RECOVERY] scheduled request refresh "
            f"reason=relay_watchdog healthy={int(relay_healthy)} "
            f"interval_sec={recovery_interval:.1f} "
            f"age_sec={(now - last_success) if last_success else -1:.1f}",
            60.0,
        )
        self.fetch_remote_requests_once("relay watchdog")

    @staticmethod
    def _relay_request_snapshot_signature(rows) -> str:
        try:
            payload = json.dumps(
                rows or [],
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
                default=str,
            )
        except Exception:
            payload = repr(rows or [])
        return hashlib.sha256(payload.encode("utf-8", errors="replace")).hexdigest()

    def _handle_relay_requests(self, rows):
        """Reconcile v2 rotation rows on the UI thread, then ack queued successes.

        The v2 feed is backed by ``okjweb.db`` and is not authoritative for
        waitlisted phone requests, which live in ``incoming_requests.db``.
        Legacy sync polling remains the wait-list snapshot source.
        """
        processed = getattr(self, "_relay_processed_request_ids", None)
        if not isinstance(processed, set):
            processed = set()
            self._relay_processed_request_ids = processed

        for req in rows or []:
            if isinstance(req, dict):
                try:
                    rid = int(req.get("id") or req.get("request_id") or 0)
                except Exception:
                    rid = 0
                if rid > 0 and not req.get("request_id"):
                    req["request_id"] = rid

        try:
            app_state = object.__getattribute__(self, "__dict__")
        except Exception:
            app_state = {}
        snapshot_signature = self._relay_request_snapshot_signature(rows)
        queue_revision = int(app_state.get("_queue_revision", 0) or 0)
        unchanged_snapshot = bool(
            snapshot_signature
            and snapshot_signature == str(app_state.get("_relay_last_snapshot_signature", "") or "")
            and queue_revision == int(app_state.get("_relay_last_snapshot_queue_revision", -1) or 0)
        )
        if unchanged_snapshot:
            _diag_rate_limited(
                "relay_snapshot_unchanged",
                f"[REMOTE-SYNC] unchanged relay snapshot skipped rows={len(rows or [])}",
                300.0,
            )
        else:
            try:
                self._reconcile_remote_requests(rows or [], update_waitlist=False)
            except Exception as e:
                logging.error(f"Relay request reconciliation failed: {e}")
                print(f"❌ Error reconciling relay requests: {e}")
                return
            app_state["_relay_last_snapshot_signature"] = snapshot_signature
            app_state["_relay_last_snapshot_queue_revision"] = int(
                app_state.get("_queue_revision", queue_revision) or 0
            )

        try:
            queue_ids = set(int(v) for v in self._host_owned_remote_request_ids())
        except Exception:
            queue_ids = set()
        try:
            queue_ids |= self._deferred_remote_request_ids()
        except Exception:
            pass

        ack_ids = []
        for req in rows or []:
            if not isinstance(req, dict):
                continue
            try:
                rid = int(req.get("request_id") or req.get("id") or 0)
            except Exception:
                rid = 0
            if rid <= 0:
                continue
            state = str(req.get("state") or "").strip().lower()
            already_delivered = bool(req.get("sent") or req.get("delivered") or state == "delivered")
            if already_delivered:
                continue
            if rid in processed or rid in queue_ids:
                processed.add(rid)
                ack_ids.append(rid)
        if ack_ids:
            self.ack_remote_requests(ack_ids)

    def ack_remote_requests(self, ack_ids):
        ids = sorted({int(i) for i in (ack_ids or []) if int(i) > 0})
        if not ids:
            return
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()

        def worker():
            try:
                resp = requests.post(
                    f"{base_url}/get_requests_v2.php",
                    json={"user": tenant, "tenant": tenant, "ack_ids": ids},
                    headers={
                        "X-API-Key": api_key,
                        "Content-Type": "application/json",
                        "User-Agent": f"SingWS/{APP_VERSION}",
                    },
                    timeout=10,
                )
                if resp.status_code == 200:
                    print(f"[REQUESTS] Acked {len(ids)} request(s): {ids}")
                else:
                    print(f"[REQUESTS] Ack failed: HTTP {resp.status_code} - {(resp.text or '')[:160]!r}")
            except Exception as e:
                print(f"[REQUESTS] Ack failed: {e}")

        threading.Thread(target=worker, daemon=True, name="relay-request-ack").start()

    def _connect_poll_worker_requests_received(self, use_relay: bool):
        # Keep incoming_requests.db polling connected even with the relay. The
        # relay's v2 recovery feed reads okjweb.db, which intentionally omits
        # phone requests that are still on the wait-list. Request IDs plus the
        # intake/in-flight sets make duplicate active snapshots idempotent.
        self.poll_worker.requests_received.connect(self.handle_requests_from_thread)

    def start_request_polling(self, *, stop_existing=True):
        base_url = _network_normalize_base_url(self.settings.get("base_url", "https://beta.wskar.com"))
        tenant   = self.settings.get("user", self.settings.get("tenant", ""))

        # Safety: ensure any previous thread is gone
        if stop_existing:
            self.stop_request_polling()

        api_key = self.settings.get("api_key", "")

        # WebSocket relay replaces get_requests.php polling when supported
        # (wskar.com, tenant + API key configured, QtWebSockets importable).
        use_relay = self._should_use_request_relay(base_url, tenant, api_key)
        if use_relay:
            self._start_request_relay(base_url, tenant, api_key)
            print(f"✅ Request relay started (WebSocket) tenant={tenant}; waitlist recovery polling retained")

        # v2 DAW host-control over WebSocket (app > 3.0.0.0). Runs alongside the
        # v1 host_commands.php polling below, which stays active for older browsers
        # and as a fallback. A given browser uses exactly one channel, so commands
        # are never executed twice.
        if self._should_use_host_control_relay(base_url, tenant, api_key):
            self._start_host_control_relay(base_url, tenant, api_key)
            print(f"✅ Host-control relay started (WebSocket) tenant={tenant}")

        self.poll_thread = QThread(self)
        try:
            _poll_iv = self._effective_request_poll_interval_sec()
        except Exception:
            _poll_iv = 2
        self.poll_worker = SimplePollWorker(
            base_url,
            tenant,
            api_key,
            interval_sec=_poll_iv,
            host_interval_sec=self._effective_host_poll_interval_sec(),
            # The legacy sync feed remains required for wait-listed requests;
            # the relay/v2 feed supplies immediate active-rotation updates.
            poll_requests=True,
        )
        self.poll_worker.moveToThread(self.poll_thread)

        self._connect_poll_worker_requests_received(use_relay)
        self.poll_worker.host_commands_received.connect(self.handle_host_commands_from_thread)
        self.poll_worker.host_state_sync_requested.connect(self._schedule_host_control_state_sync)
        self.poll_worker.connection_status_changed.connect(self._set_server_connection_status)
        self.poll_thread.started.connect(self.poll_worker.run)

        self.poll_thread.start()
        if use_relay:
            print(f"✅ Request relay + waitlist recovery polling started ({_poll_iv}s, tenant={tenant})")
        else:
            print(f"✅ Polling started ({_poll_iv}s) URL: {base_url}/get_requests.php (tenant={tenant})")

        try:
            QTimer.singleShot(250, lambda: self._sync_remote_removal_tombstones_async("poll_start"))
        except Exception:
            pass
        self._start_network_recovery_timer()

    def stop_request_polling(self):
        # Relay and polling are managed together: stopping the request
        # transport always tears down both, so they can never run at once.
        self._stop_network_recovery_timer()
        self._stop_request_relay()
        self._stop_host_control_relay()

        t = getattr(self, "poll_thread", None)
        w = getattr(self, "poll_worker", None)

        if w is not None:
            try:
                w.stop()  # instant break out of the wait loop
            except Exception:
                pass

        if t is not None:
            try:
                t.requestInterruption()
                t.quit()
                if not t.wait(2000):
                    print("⚠️ Thread didn't stop gracefully, terminating...")
                    t.terminate()
                    t.wait(1000)
            except Exception:
                pass

        self.poll_worker = None
        self.poll_thread = None

    def _stop_request_polling_async(self, on_stopped=None):
        """Retire the polling thread without waiting on the GUI/audio thread."""
        self._stop_network_recovery_timer()
        self._stop_request_relay()
        self._stop_host_control_relay()

        t = getattr(self, "poll_thread", None)
        w = getattr(self, "poll_worker", None)
        self.poll_worker = None
        self.poll_thread = None

        if t is None or not t.isRunning():
            if callable(on_stopped):
                QTimer.singleShot(0, on_stopped)
            return

        retired = getattr(self, "_retiring_poll_threads", None)
        if not isinstance(retired, list):
            retired = []
            self._retiring_poll_threads = retired
        pair = (t, w)
        retired.append(pair)

        def finished():
            def finish_on_ui():
                try:
                    retired.remove(pair)
                except ValueError:
                    pass
                if callable(on_stopped):
                    on_stopped()

            self._run_on_ui_thread(finish_on_ui)

        t.finished.connect(finished)
        if w is not None:
            t.finished.connect(w.deleteLater)
            try:
                w.stop()
            except Exception:
                pass
        t.finished.connect(t.deleteLater)
        t.requestInterruption()
        t.quit()
        _diag("[NETWORK] polling retirement scheduled off the GUI thread")

    def _shutdown_network_transports(self):
        """Idempotently stop network timers, relays, and poll threads during app quit."""
        if bool(getattr(self, "_network_transports_shutdown", False)):
            return
        self._network_transports_shutdown = True
        begin_shutdown = getattr(requests, "begin_shutdown", None)
        if callable(begin_shutdown):
            begin_shutdown()
        if bool(getattr(self, "_app_closing", False)):
            try:
                global _QT_APP_SHUTTING_DOWN
                _QT_APP_SHUTTING_DOWN = True
            except Exception:
                pass
        try:
            self._stop_network_recovery_timer()
        except Exception:
            pass
        try:
            timer = getattr(self, "_host_control_state_timer", None)
            if timer is not None:
                timer.stop()
        except Exception:
            pass
        try:
            timer = getattr(self, "_host_relay_pub_timer", None)
            if timer is not None:
                timer.stop()
        except Exception:
            pass
        try:
            self._stop_request_relay()
        except Exception as e:
            print("Request relay stop failed:", e)
        try:
            self._stop_host_control_relay()
        except Exception as e:
            print("Host relay stop failed:", e)
        try:
            QApplication.processEvents()
            QApplication.sendPostedEvents(None, QEvent.Type.DeferredDelete)
            QApplication.processEvents()
        except Exception:
            pass
        t = getattr(self, "poll_thread", None)
        w = getattr(self, "poll_worker", None)
        if w is not None:
            try:
                w.stop()
            except Exception as e:
                print("Poll worker stop failed:", e)
        # Daemon HTTP workers can still be loading certificates while AppKit
        # calls exit/OPENSSL_cleanup. Drain TLS users before Qt tears down.
        wait_for_idle = getattr(requests, "wait_for_idle", None)
        if callable(wait_for_idle):
            wait_for_idle()
        if t is not None:
            try:
                if t.isRunning():
                    t.requestInterruption()
                    t.quit()
                    t.wait()
                try:
                    t.deleteLater()
                except Exception:
                    pass
            except Exception as e:
                print("Poll thread stop failed:", e)
        self.poll_worker = None
        self.poll_thread = None

    def _capture_window_geometry_settings(self) -> None:
        """Snapshot main / show-screen / rotation window geometry into settings.

        Called from both closeEvent and aboutToQuit: quitting with Cmd+Q on
        macOS skips the main window's closeEvent, which used to silently lose
        window positions."""
        try:
            if not hasattr(self, "settings") or self.settings is None:
                self.settings = {}
            g = self.geometry()
            self.settings["main_window_geometry"] = {"x": int(g.x()), "y": int(g.y()), "w": int(g.width()), "h": int(g.height())}
        except Exception:
            pass
        try:
            vw = getattr(self, "video_window", None)
            if vw is not None:
                vg = vw.geometry()
                if vg.width() > 0 and vg.height() > 0:
                    self.settings["karaoke_window_pos"] = {
                        "x": int(vg.x()), "y": int(vg.y()),
                        "width": int(vg.width()), "height": int(vg.height()),
                    }
        except Exception:
            pass
        try:
            rv = getattr(self, "rotation_view", None)
            if rv is not None:
                rg = rv.geometry()
                self.settings["rotation_window_geometry"] = {
                    "x": int(rg.x()), "y": int(rg.y()),
                    "width": int(rg.width()), "height": int(rg.height()),
                }
        except Exception:
            pass

    def _open_mic_diagnostics(self):
        try:
            import mic_diagnostics_dialog

            def _save(values: dict):
                self.settings.update(values)
                self._schedule_save_settings()
                _ia_mic_configure(self.settings)

            dialog = mic_diagnostics_dialog.MicDiagnosticsDialog(
                self, settings=self.settings,
                helper_path=_ia_native_helper_path("SingWSMicMeter"), on_save=_save,
            )
            dialog.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
            dialog.show()
        except Exception as exc:
            _diag(f"[MIC] diagnostics dialog failed: {exc}")

    def _on_app_about_to_quit(self):
        self._app_closing = True
        try:
            if _IA_SOUND["monitor"] is not None:
                _IA_SOUND["monitor"].shutdown()
            if _IA_MIC["monitor"] is not None:
                _IA_MIC["monitor"].shutdown()
            transition_events.recorder().close()
        except Exception:
            pass
        try:
            global _QT_APP_SHUTTING_DOWN
            _QT_APP_SHUTTING_DOWN = True
        except Exception:
            pass
        try:
            self._capture_window_geometry_settings()
            self._save_operator_splitter_sizes()
            self.save_settings()
        except Exception:
            pass
        try:
            keep_awake = getattr(self, "_mac_keep_awake", None)
            if keep_awake is not None:
                keep_awake.end()
        except Exception:
            pass
        self._shutdown_network_transports()
        try:
            flush_log_queue()
        except Exception:
            pass

    def restart_request_polling(self):
        """Stop and restart request polling when network settings are present.

        The core show-night path is /get_requests.php.  Do not gate polling on
        optional sync probes such as host controls or singer history; those can
        be partial or temporarily unavailable while request intake still works.
        """
        generation = int(getattr(self, "_request_poll_restart_generation", 0) or 0) + 1
        self._request_poll_restart_generation = generation

        def start_after_retirement():
            if generation != int(getattr(self, "_request_poll_restart_generation", 0) or 0):
                return
            if bool(getattr(self, "_app_closing", False)):
                return
            if self.is_network_configured():
                base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
                user_id = self.settings.get("user", "") or self.settings.get("tenant", "")
                self.start_request_polling(stop_existing=False)
                print(f"✅ Polling restarted for request intake: {base_url}/get_requests.php (tenant={user_id})")
            else:
                print("ℹ️ Network not fully configured - polling disabled")

        self._stop_request_polling_async(start_after_retirement)

    def configure_ticker(self):
        """Enable/disable the ticker and pick its color; persist both."""
        from PyQt6.QtWidgets import (
            QDialog, QVBoxLayout, QHBoxLayout, QLabel, QPushButton, QCheckBox, QLineEdit, QColorDialog, QDialogButtonBox, QSlider
        )
        from PyQt6.QtGui import QColor, QPalette

        dlg = QDialog(self)
        dlg.setWindowTitle("Ticker Settings")
        vbox = QVBoxLayout(dlg)


        # --- Dialog styling (match Add to Queue dialog / main UI) ---
        try:
            # Pull colors from main UI so it always matches your theme
            if hasattr(self, "queue_display"):
                base = self.queue_display.palette().color(QPalette.ColorRole.Base)
                win  = self.palette().color(QPalette.ColorRole.Window)
                txtc = self.palette().color(QPalette.ColorRole.Text)
            else:
                base = dlg.palette().color(QPalette.ColorRole.Base)
                win  = dlg.palette().color(QPalette.ColorRole.Window)
                txtc = dlg.palette().color(QPalette.ColorRole.Text)

            border  = base.lighter(115)
            hover   = base.lighter(110)
            pressed = base.darker(110)
            field_bg = base.darker(105)
            focus_border = border.lighter(120)

            dlg.setStyleSheet(dialog_stylesheet(win, base, txtc))

            # More “designed” spacing like your Add to Queue window
            vbox.setContentsMargins(14, 14, 14, 14)
            vbox.setSpacing(10)
            dlg.setMinimumWidth(560)
        except Exception:
            pass

        # --- Show/Hide toggle ---
        enabled_cb = QCheckBox("Show ticker (names + timer)")
        current_enabled = bool(self.settings.get("ticker_enabled", True))
        enabled_cb.setChecked(current_enabled)
        vbox.addWidget(enabled_cb)

        # --- Color row ---
        color_row = QHBoxLayout()
        color_row.addWidget(QLabel("Color:"))
        pick_btn = QPushButton("Choose…")
        color_row.addWidget(pick_btn)
        vbox.addLayout(color_row)

        # --- Size row ---
        size_row = QHBoxLayout()
        size_row.addWidget(QLabel("Text Size:"))
        size_slider = QSlider(Qt.Orientation.Horizontal)
        size_slider.setRange(0, len(TICKER_SIZE_PRESETS) - 1)
        size_slider.setSingleStep(1)
        size_slider.setPageStep(1)
        size_slider.setTickPosition(QSlider.TickPosition.TicksBelow)
        size_slider.setTickInterval(1)
        current_ticker_idx = int(self.settings.get("ticker_size_index", TICKER_SIZE_DEFAULT_INDEX))
        current_ticker_idx = max(0, min(len(TICKER_SIZE_PRESETS) - 1, current_ticker_idx))
        size_slider.setValue(current_ticker_idx)
        size_row.addWidget(size_slider, 1)
        vbox.addLayout(size_row)

        # --- Scroll speed row ---
        speed_row = QHBoxLayout()
        speed_label = QLabel("Scroll Speed:")
        speed_row.addWidget(speed_label)
        speed_slider = QSlider(Qt.Orientation.Horizontal)
        speed_slider.setRange(int(TICKER_SPEED_MIN), int(TICKER_SPEED_MAX))
        speed_slider.setSingleStep(5)
        speed_slider.setPageStep(20)
        speed_slider.setTickPosition(QSlider.TickPosition.TicksBelow)
        speed_slider.setTickInterval(50)
        current_speed = self.settings.get("ticker_speed_px_per_sec", TICKER_SPEED_DEFAULT)
        try:
            current_speed = float(current_speed)
        except Exception:
            current_speed = TICKER_SPEED_DEFAULT
        current_speed = max(TICKER_SPEED_MIN, min(TICKER_SPEED_MAX, current_speed))
        speed_slider.setValue(int(round(current_speed)))
        speed_value_lbl = QLabel(f"{int(round(current_speed))} px/s")
        speed_row.addWidget(speed_slider, 1)
        speed_row.addWidget(speed_value_lbl)
        vbox.addLayout(speed_row)

        def on_speed_changed(val: int):
            val = max(int(TICKER_SPEED_MIN), min(int(TICKER_SPEED_MAX), int(val)))
            speed_value_lbl.setText(f"{val} px/s")
            self.settings["ticker_speed_px_per_sec"] = float(val)
            try:
                self.video_window.ticker.set_scroll_speed(float(val))
            except Exception:
                pass
            self._schedule_save_settings(700)

        speed_slider.valueChanged.connect(on_speed_changed)

        # --- Weight row ---
        ticker_bold_cb = QCheckBox("Bold ticker text")
        ticker_bold_cb.setChecked(bool(self.settings.get("ticker_bold", False)))
        vbox.addWidget(ticker_bold_cb)

        ticker_vfx_cb = QCheckBox("Animated ticker lighting and accents (more GPU)")
        _ticker_fx_ok = self._ticker_effects_supported()
        _ticker_fx_pending = self._ticker_effects_pending_relaunch()
        ticker_vfx_cb.setToolTip(
            "Turn off for the plain render-thread ticker; scrolling remains equally smooth."
            + (self._TICKER_FX_PENDING_NOTE if _ticker_fx_pending
               else ("" if _ticker_fx_ok else self._TICKER_FX_UNAVAILABLE_NOTE))
        )
        ticker_vfx_cb.setChecked(bool(self.settings.get("ticker_vfx_enabled", True)))
        # Do not offer a control that cannot do anything here: the setting was
        # saved and then silently dropped, which reads as the animated ticker
        # being broken rather than absent.
        ticker_vfx_cb.setEnabled(_ticker_fx_ok)
        vbox.addWidget(ticker_vfx_cb)

        # --- Custom message (optional) ---
        msg_cb = QCheckBox("Include custom message in ticker")
        msg_cb.setChecked(bool(self.settings.get("ticker_custom_enabled", False)))
        vbox.addWidget(msg_cb)

        msg_row = QHBoxLayout()
        msg_row.addWidget(QLabel("Message:"))
        msg_edit = QLineEdit(dlg)
        msg_edit.setPlaceholderText("Type a custom ticker message…")
        msg_edit.setText(str(self.settings.get("ticker_custom_message", "") or ""))
        msg_row.addWidget(msg_edit)
        vbox.addLayout(msg_row)

        rotation_msg_cb = QCheckBox("Show announcement ticker on Singer Rotation screen")
        rotation_msg_cb.setChecked(bool(self.settings.get("rotation_announcement_enabled", False)))
        vbox.addWidget(rotation_msg_cb)

        rotation_msg_row = QHBoxLayout()
        rotation_msg_row.addWidget(QLabel("Rotation message:"))
        rotation_msg_edit = QLineEdit(dlg)
        rotation_msg_edit.setPlaceholderText("Tonight's drink specials, venue announcements, etc.")
        rotation_msg_edit.setText(str(self.settings.get("rotation_announcement_message", "") or ""))
        rotation_msg_row.addWidget(rotation_msg_edit)
        vbox.addLayout(rotation_msg_row)

        vars_label = QLabel("Codes: %m_curSinger  %curSong  %m_curArtist  %m_curTitle  %nextSinger")
        vars_label.setWordWrap(True)
        try:
            vars_label.setStyleSheet(section_meta_css())
        except Exception:
            pass
        vbox.addWidget(vars_label)

        # Remember current color
        current_hex = self.settings.get("ticker_color", TICKER_COLOR_DEFAULT)
        current_qcolor = QColor(current_hex)

        def pick_color():
            nonlocal current_qcolor
            c = QColorDialog.getColor(current_qcolor, self, "Choose Ticker Color")
            if c.isValid():
                current_qcolor = c

        pick_btn.clicked.connect(pick_color)

        def on_size_changed(idx: int):
            idx = max(0, min(len(TICKER_SIZE_PRESETS) - 1, int(idx)))
            self.settings["ticker_size_index"] = idx
            try:
                self.video_window.ticker.set_size_preset(idx)
            except Exception:
                pass
            self._schedule_save_settings(700)

        size_slider.valueChanged.connect(on_size_changed)

        # --- OK/Cancel ---
        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        vbox.addWidget(btns)

        def accept():
            # Save enabled flag
            new_enabled = enabled_cb.isChecked()
            self.settings["ticker_enabled"] = new_enabled

            # Save color
            new_hex = current_qcolor.name()
            self.settings["ticker_color"] = new_hex

            # Save custom message
            try:
                self.settings["ticker_custom_enabled"] = msg_cb.isChecked()
                self.settings["ticker_custom_message"] = msg_edit.text()
            except Exception:
                pass
            self.settings["ticker_size_index"] = int(size_slider.value())
            self.settings["ticker_bold"] = bool(ticker_bold_cb.isChecked())
            self.settings["ticker_speed_px_per_sec"] = float(speed_slider.value())
            self.settings["ticker_vfx_enabled"] = bool(ticker_vfx_cb.isChecked())
            self.settings["rotation_announcement_enabled"] = bool(rotation_msg_cb.isChecked())
            self.settings["rotation_announcement_message"] = rotation_msg_edit.text().strip()

            # Persist and apply immediately
            self.save_settings()

            # Ticker data is cached for speed; invalidate so custom message updates now.
            try:
                if hasattr(self, '_cached_ticker_data'):
                    delattr(self, '_cached_ticker_data')
            except Exception:
                pass

            try:
                # Apply color if ticker exists (safe even if hidden)
                self.video_window.ticker.set_color(new_hex)
            except Exception:
                pass
            try:
                self.video_window.ticker.set_bold(bool(ticker_bold_cb.isChecked()))
            except Exception:
                pass
            try:
                self.video_window.ticker.set_scroll_speed(float(speed_slider.value()))
            except Exception:
                pass
            try:
                if hasattr(self.video_window.ticker, "set_effects_enabled"):
                    self.video_window.ticker.set_effects_enabled(bool(ticker_vfx_cb.isChecked()))
            except Exception:
                pass

            try:
                # Apply visibility/space
                self.video_window.set_ticker_enabled(new_enabled)
            except Exception:
                pass

            try:
                if self.rotation_view is not None:
                    self.rotation_view.set_announcement_ticker(
                        bool(rotation_msg_cb.isChecked()),
                        rotation_msg_edit.text().strip(),
                    )
            except Exception:
                pass

            try:
                # Force immediate queue text refresh (custom message / enabled state changes)
                if hasattr(self.video_window.ticker, 'force_refresh_now'):
                    self.video_window.ticker.force_refresh_now()
                else:
                    if hasattr(self.video_window.ticker, '_last_queue_text'):
                        self.video_window.ticker._last_queue_text = ''
                    self.video_window.ticker.update_queue_text()
            except Exception:
                pass

            dlg.accept()

        btns.accepted.connect(accept)
        btns.rejected.connect(dlg.reject)

        dlg.exec()

    def _get_time_left_text(self):
        try:
            txt = self.time_left_label.text()
            if not bool(getattr(self, "karaoke_playing", False)):
                return ""
            txt = str(txt or "").strip()
            if not txt or txt in ("-00:00", "--:--", "00:00"):
                return ""
            return txt
        except Exception:
            return ""

    def _gst_query_times(self):
        transport = getattr(self, "karaoke_transport", None)
        if transport is not None:
            try:
                return transport.query_times_ns()
            except Exception:
                return None, None
        return None, None

    def _karaoke_seek_seconds(self, seconds: float) -> bool:
        """Seek karaoke playback to absolute seconds."""
        transport = getattr(self, "karaoke_transport", None)
        if transport is None:
            return False
        try:
            transport.seek(seconds)
            _ia_record(self, "manual_seek", playhead_s=float(seconds))
            _ia_observe(self, "seek", playhead=float(seconds))
            return True
        except Exception as e:
            _diag(f"[PY-KARAOKE] seek failed: {e}")
            return False

    def _is_karaoke_paused(self) -> bool:
        transport = getattr(self, "karaoke_transport", None)
        if transport is not None and hasattr(transport, "is_paused"):
            try:
                return bool(transport.is_paused())
            except Exception:
                pass
        return False

    def toggle_karaoke_pause(self):
        """Pause or resume the active karaoke track.

        Routes to the Python karaoke transport when one is active (CDG
        playback path) and falls back to GStreamer state changes for any
        other media path.
        """
        if not bool(getattr(self, "karaoke_playing", False)):
            return
        paused = self._is_karaoke_paused()
        # Warn only when about to PAUSE (halt audio); resuming never prompts.
        if not paused:
            if not self._confirm_audio_interrupt(
                title="Pause Playback?",
                message=("A track is currently playing.\n"
                         "Pause the current singer?"),
            ):
                return
        transport = getattr(self, "karaoke_transport", None)
        if transport is not None:
            try:
                if paused:
                    transport.resume()
                else:
                    transport.pause()
            except Exception as e:
                _diag(f"[PY-KARAOKE] pause/resume failed: {e}")
        # Refresh the button label to mirror the new state.
        try:
            self._update_karaoke_pause_button()
        except Exception:
            pass

    def _update_karaoke_pause_button(self):
        btn = getattr(self, "karaoke_pause_button", None)
        if btn is None:
            return
        try:
            paused = self._is_karaoke_paused()
            # Show ▶ while paused (click resumes), ▮▮ while playing (click
            # pauses).  ▮ from Geometric Shapes renders at matching weight
            # to ▶ in every system font.
            btn.setText("▶" if paused else "▮▮")
            # Always enabled so the button doesn't go dark when there's no
            # active song; toggle_karaoke_pause() is itself a no-op when
            # karaoke_playing is False.
            btn.setEnabled(True)
        except Exception:
            pass

    def _gst_watch_bus(self, pipeline, which="main"):
        """Attach a bus watch to a pipeline so we can react to EOS/ERROR."""
        try:
            bus = pipeline.get_bus()
            bus.add_signal_watch()
            # Pass which ("main" | "preview") so we know who fired the message
            bus.connect("message", self._on_gst_message, which)
        except Exception as e:
            print("Bus watch add failed:", e)

    def _gst_unwatch_bus(self, pipeline):
        """Remove signal watch from a pipeline's bus (safe to call even if not added)."""
        if not pipeline:
            return
        try:
            bus = pipeline.get_bus()
            bus.remove_signal_watch()
        except Exception:
            pass

    def _on_gst_message(self, bus, msg, which):
        if bool(getattr(self, "_app_closing", False)):
            return
        mtype = msg.type
        if mtype == Gst.MessageType.ELEMENT:
            # Level meter messages from CDG/ZIP audio path (for optional end-silence trim).
            try:
                if which == "main" and getattr(self, "_end_silence_mode", "") == "cdg":
                    st = msg.get_structure()
                    if st is not None and st.get_name() == "level":
                        db_vals = []
                        for field in ("peak", "rms", "decay"):
                            try:
                                v = st.get_value(field)
                            except Exception:
                                v = None
                            db_vals.extend(self._extract_db_values(v))
                        if db_vals:
                            self._karaoke_last_level_db = max(db_vals)
                            self._karaoke_last_level_ts = time.monotonic()
            except Exception:
                pass
            return
        elif mtype == Gst.MessageType.EOS:
            # Only react to EOS from the MAIN pipeline; preview will end too.
            if which == "main":
                QTimer.singleShot(0, lambda: self._handle_media_end_safe("eos"))
        elif mtype == Gst.MessageType.ERROR:
            err, debug = msg.parse_error()
            print(f"GStreamer ERROR from {which}: {err} ({debug})")
            if which == "main":
                QTimer.singleShot(0, lambda: self._handle_media_end_safe("error"))

    def _prepare_overlay(self, sink, win):
        # Attach sink to a QWidget via VideoOverlay
        if sink:
            try:
                GstVideo.VideoOverlay.prepare_window_handle(sink)
                sink.set_window_handle(int(win))
            except Exception as e:
                print("VideoOverlay bind failed:", e)
                
    def _handle_media_end_safe(self, trigger: str = "eos"):
        """Called when the current track finishes or on pipeline ERROR."""
        if getattr(self, "_stop_in_progress", False):
            return
        if bool(getattr(self, "_media_end_handoff_active", False)):
            _diag("[END] duplicate media-end ignored: handoff already active")
            return
        trigger = str(trigger or "eos").strip().lower()
        self._media_end_overlay_eligible = (trigger != "error")
        self._media_end_handoff_active = True
        try:
            self._media_end_handoff_timer.start(6000)
        except Exception:
            pass

        # Track end is a safe moment to flush deferred garbage.  We raised
        # gc thresholds at startup to avoid pauses mid-song; the trade-off
        # is that we should run a manual collection at points where a
        # brief pause is inaudible — between songs is ideal.
        try:
            import gc as _gc
            _gc.collect()
        except Exception:
            pass

        end_silence_triggered = bool(getattr(self, "_end_silence_triggered", False))
        early_end_reason = str(getattr(self, "_end_silence_last_reason", "") or "")
        early_auto_advance = bool(getattr(self, "_end_silence_auto_advance_next", False))
        self._reset_end_silence_state()

        # Intro Loop: instead of BGM, auto-advance to the next queued song held at
        # a looping intro. Reuse the proven early-auto-advance path (skips BG
        # overlap, tears down, then triggers play_next_file) and flag the loop.
        if (not early_auto_advance) and self._should_start_intro_loop():
            early_auto_advance = True
            self._pending_intro_loop = True
            _diag("[INTRO-LOOP] media-end → auto-advance into next song's intro loop")
        if early_end_reason:
            _diag(f"[END] early-end handoff reason={early_end_reason} auto_advance={early_auto_advance}")
        _ia_record(self, 
            "media_end",
            trigger=trigger,
            early_end_reason=early_end_reason or None,
            end_silence_triggered=end_silence_triggered,
            auto_advance=bool(early_auto_advance),
            crossfade_enabled=bool(self._karaoke_bgm_crossfade_enabled()),
        )
        _ia_observe(self, "end", trigger=trigger)

        # True end-overlap path: start BG fade immediately, then teardown karaoke shortly after.
        can_overlap = (
            self._karaoke_bgm_crossfade_enabled()
            and (not early_auto_advance)
            and (not end_silence_triggered)
            and (not early_end_reason)
            and hasattr(self, "bg_music")
            and bool(getattr(self.bg_music, "playlist", None))
            and not bool(getattr(self.bg_music, "is_playing", False))
            and bool(self.settings.get("bg_enabled", True))
            and bool(self.settings.get("bg_autoplay_on_idle", True))
        )
        if can_overlap:
            try:
                self._bg_resume_reason = "karaoke_end_overlap"
                _diag("Karaoke track ended, starting BG overlap fade...")
                can_overlap = bool(self._start_bg_with_fade_safe("media_end_overlap"))
            except Exception as e:
                print("Failed starting BG overlap fade:", e)
                can_overlap = False
            if can_overlap:
                overlap_ms = max(0, int(getattr(self, "_karaoke_end_overlap_ms", 220)))
                _diag(f"Finishing karaoke teardown after {overlap_ms}ms overlap")
                self._schedule_media_end_cleanup(
                    overlap_ms,
                    end_silence_triggered=end_silence_triggered,
                    schedule_bg_resume=False,
                )
                return

        self._finish_media_end_cleanup(end_silence_triggered, schedule_bg_resume=(not early_auto_advance))
        if early_auto_advance:
            _diag(f"[END] scheduling next queued karaoke after early end ({early_end_reason})")
            ended_generation = int(getattr(self, "_confirmed_singer_start_generation", 0) or 0)
            QTimer.singleShot(
                450,
                lambda generation=ended_generation, reason=early_end_reason: self._auto_play_next_if_generation(
                    generation,
                    reason=reason or "early_media_end",
                ),
            )

    def _auto_play_next_if_generation(self, ended_generation: int, *, reason: str) -> bool:
        """Run an end timer only if no newer manual playback command won."""
        current_generation = int(getattr(self, "_confirmed_singer_start_generation", 0) or 0)
        if current_generation != int(ended_generation):
            _diag(
                f"[PLAY-COMMAND] stale auto-advance ignored reason={reason} "
                f"ended_generation={int(ended_generation)} current_generation={current_generation}"
            )
            return False
        if (
            getattr(self, "_pending_play_start_token", None) is not None
            or bool(getattr(self, "_next_in_progress", False))
        ):
            _diag(f"[PLAY-COMMAND] auto-advance yielded to active command reason={reason}")
            return False
        self.play_next_file(skip_confirmation=True, command_source=f"automatic:{reason}")
        return True

    def _karaoke_bgm_crossfade_enabled(self) -> bool:
        """True when the host explicitly allows duration-based end overlap."""
        try:
            return (
                bool(self.settings.get("seamless_transitions_enabled", True))
                and bool(self.settings.get("karaoke_bgm_crossfade_enabled", False))
            )
        except Exception:
            return False

    def _karaoke_early_silence_trim_enabled(self) -> bool:
        """Verified file-tail trimming, or the conservative legacy end gate."""
        try:
            if bool(self.settings.get("karaoke_trim_verified_tail", True)):
                return True
            return (
                bool(self.settings.get("seamless_transitions_enabled", True))
                and
                bool(self.settings.get("karaoke_allow_early_silence_trim", False))
                and bool(self.settings.get("end_silence_trim_enabled", False))
            )
        except Exception:
            return False

    def _commit_pending_performance(self, reason: str = "song_completed") -> bool:
        """Record the song that just finished as actually performed.

        Deferred from song start so that a song changed or removed part-way
        through is never counted as sung, and so a singer's slot only frees up
        once their song has genuinely ended.
        """
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return False
        pending = state.pop("_pending_performance", None)
        if not isinstance(pending, dict):
            return False
        request_id = pending.get("remote_request_id")
        if request_id is not None:
            try:
                self._complete_remote_request(
                    request_id,
                    entry=pending.get("entry"),
                    singer_name=str(pending.get("singer_name") or ""),
                    reason=reason,
                )
            except Exception:
                pass
        try:
            self._record_singer_history_play(
                str(pending.get("singer_name") or ""),
                pending.get("entry"),
                str(pending.get("song_path") or ""),
                key=pending.get("key") or 0,
                tempo_percent=pending.get("tempo_percent"),
            )
            self._schedule_save_data(1000)
            self._sync_singer_history_async(reason)
        except Exception:
            pass
        _diag(
            f"[PERFORMANCE] recorded reason={reason} "
            f"singer={str(pending.get('singer_name') or '')!r} request_id={request_id}"
        )
        return True

    def _discard_pending_performance(self, reason: str = "stopped_early") -> bool:
        """Drop an in-flight song without recording it as performed."""
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return False
        pending = state.pop("_pending_performance", None)
        if not isinstance(pending, dict):
            return False
        singer_name = str(pending.get("singer_name") or "")
        request_id = pending.get("remote_request_id")
        _diag(
            f"[PERFORMANCE] not recorded reason={reason} "
            f"singer={singer_name!r} request_id={request_id}"
        )
        # Dropping it locally was not enough. The request stayed active on the
        # server, so the next poll saw a live phone request with no local row
        # and re-created it -- a song stopped at 01:45 reappeared at 01:51,
        # after the host had already removed the singer. Tombstone it here so
        # a host stop actually sticks. This does NOT mark it sung, so the
        # singer is still free to request it again from their phone.
        try:
            if request_id is not None:
                self._delete_remote_request(
                    request_id,
                    entry=pending.get("entry"),
                    singer_name=singer_name,
                    reason=f"host_stopped:{reason}",
                )
        except Exception as e:
            _diag(f"[PERFORMANCE] could not retire request {request_id}: {e}")
        return True

    def _finish_media_end_cleanup(self, end_silence_triggered: bool, schedule_bg_resume: bool):
        """Finalize karaoke end: teardown/UI reset and optional delayed BG resume."""
        try:
            # Before stop_playback(), which discards anything still pending.
            self._commit_pending_performance(reason="song_completed")
        except Exception:
            pass
        try:
            song_outro_payload = self._song_outro_payload_from_current()
            try:
                # Stop/tear down players (doesn't prompt the user)
                self.stop_playback(skip_confirmation=True)
            except Exception as e:
                print("stop_playback failed:", e)
            try:
                self._flush_deferred_remote_adds("media_end")
            except Exception as e:
                _diag(f"[REMOTE-DEFER] media-end flush failed: {e}")
            try:
                if bool(getattr(self, "_media_end_overlay_eligible", False)):
                    self._pending_song_outro_payload = song_outro_payload
                    self._mark_next_up_overlay_pending_after_completion(reason="media_end")
                else:
                    self._clear_next_up_overlay_pending("media_end_not_eligible")
            except Exception:
                pass

            # Clear the Now Singing line
            try:
                self.clear_now_singing()
            except Exception:
                pass

            # Detach sinks immediately so glimagesink stops being fed frames.
            try:
                self._detach_video_sinks_now("media_end_cleanup")
            except Exception:
                pass

            # Critical: use the same strong surface refresh used by manual-stop so
            # end-of-track cannot leave a stale CDG frame composited on top.
            try:
                self._recreate_video_surfaces("media_end_cleanup")
            except Exception:
                pass

            # Restore idle background mode on the main video window
            try:
                self._show_idle_background_after_karaoke(reason="media_end_cleanup", advance_slideshow=True)
            except Exception as e:
                print("restore background failed:", e)

            if not schedule_bg_resume:
                return

            _diag("Karaoke track ended, attempting to start background music...")
            bg = getattr(self, 'bg_music', None)
            has_bg = bg is not None
            has_playlist = bool(getattr(bg, 'playlist', None)) if bg is not None else False

            effective_playing = False
            raw_playing = False
            if bg is not None:
                raw_playing = bool(getattr(bg, 'is_playing', False))
                try:
                    effective_playing = bool(bg.is_effectively_playing())
                except Exception:
                    effective_playing = raw_playing

            if has_bg and has_playlist and not effective_playing:
                # Heal stale BG state before resume when flags claim 'playing' but pipeline is not active.
                if raw_playing:
                    _diag("[BG] stale is_playing detected at karaoke end; forcing BG reset")
                    try:
                        bg.stop()
                    except Exception:
                        pass
                    try:
                        bg.preload_current_track_paused()
                    except Exception:
                        pass

                delay_ms = 60 if end_silence_triggered else 120
                _diag(f"Starting background music with {delay_ms}ms delay (end_silence={end_silence_triggered})...")
                self._schedule_bg_resume(delay_ms, reason="karaoke_end")
            else:
                _diag(
                    f"Cannot start background music: has_bg_music={has_bg}, has_playlist={has_playlist}, "
                    f"is_playing={raw_playing}, effective_playing={effective_playing}"
                )
        finally:
            try:
                self._media_end_cleanup_timer.stop()
            except Exception:
                pass
            try:
                self._media_end_handoff_timer.stop()
            except Exception:
                pass
            self._media_end_handoff_active = False

    def _render_ticker_custom_message(self, template: str, singer_list: list[str]) -> str:
        """Apply OpenKJ-style variable substitutions for ticker custom text."""
        msg = str(template or "")
        if not msg:
            return ""

        cur_singer = ""
        cur_artist = ""
        cur_title = ""
        try:
            parts = getattr(self, "_now_singing_parts", None)
            if isinstance(parts, (tuple, list)) and len(parts) >= 3:
                cur_singer = str(parts[0] or "").strip()
                cur_artist = str(parts[1] or "").strip()
                cur_title = str(parts[2] or "").strip()
        except Exception:
            pass

        cur_song = ""
        if cur_artist and cur_title:
            cur_song = f"{cur_artist} • {cur_title}"
        else:
            cur_song = cur_title or cur_artist

        next_singer = ""
        try:
            if singer_list:
                next_singer = str(singer_list[0] or "").strip()
        except Exception:
            next_singer = ""

        replacements = {
            "%m_curSinger": (f"Current: {cur_singer}" if cur_singer else ""),
            "%curSinger": cur_singer,
            "%curSong": cur_song,
            "%m_curArtist": cur_artist,
            "%curArtist": cur_artist,
            "%m_curTitle": cur_title,
            "%curTitle": cur_title,
            "%nextSinger": (f"Next: {next_singer}" if next_singer else ""),
        }

        for token, value in replacements.items():
            msg = msg.replace(token, value)

        # Clean up empty fragments so separators do not remain when fields are blank.
        parts = [p.strip() for p in msg.split("|")]
        cleaned = []
        for part in parts:
            # Normalize spaces and trim dangling punctuation from empty substitutions.
            ptxt = re.sub(r"\s+", " ", part).strip()
            ptxt = ptxt.strip(" -•")
            ptxt = re.sub(r"\s*-\s*-+", " - ", ptxt)
            ptxt = re.sub(r"\s*•\s*•+", " • ", ptxt)
            ptxt = re.sub(r"\s+", " ", ptxt).strip(" -•")
            if ptxt:
                cleaned.append(ptxt)

        return " | ".join(cleaned)

    def get_singer_names_for_ticker(self):
        """
        Provide data for the scrolling ticker.
        Only includes active (non-skipped) singers with non-skipped songs.

        Backward-compatible return:
          - Can return just a list[str] of singers
          - OR a tuple: (singer_list, custom_message)

        Duet behavior:
          - If the *next* song for a singer is a duet, show "Primary & Partner" on the ticker
            (no literal word 'Duet' anywhere).
            
        OPTIMIZED: Uses cached value, only recalculates when queue changes
        """
        # Cache keyed by a cheap signature of the authoritative playback/queue
        # state. When anything that affects the ticker changes (queue order,
        # active songs, skips, or the currently-playing singer), the signature
        # changes and the list is rebuilt — so the ticker can never hold a stale
        # singer after a song ends or the rotation advances.
        sig = self._ticker_state_signature()
        cached = getattr(self, "_cached_ticker_data", None)
        if cached is not None and getattr(self, "_cached_ticker_sig", None) == sig:
            return cached

        # Calculate and cache
        singer_list = []
        for s in self.queue:
            # Skip if singer is skipped or has no active songs
            if not self.is_singer_active(s):
                continue
            
            # Find first non-skipped song
            first_active_song = None
            for song in s.get("songs", []):
                if isinstance(song, dict):
                    if not song.get("skipped", False):
                        first_active_song = song
                        break
                else:
                    # Old format
                    first_active_song = song
                    break
            
            if not first_active_song:
                continue
            
            duet_display = None
            if isinstance(first_active_song, dict):
                duet_display = first_active_song.get("duet_display")
            elif isinstance(first_active_song, (tuple, list)) and len(first_active_song) >= 3:
                duet_display = first_active_song[2]
            
            singer_list.append(duet_display if duet_display else s.get("name", ""))

        # Optional custom message (configured from the Ticker Settings dialog)
        try:
            custom_enabled = bool(self.settings.get("ticker_custom_enabled", False))
            custom_msg = (self.settings.get("ticker_custom_message", "") or "").strip()
        except Exception:
            custom_enabled = False
            custom_msg = ""

        if custom_enabled and custom_msg:
            rendered_msg = self._render_ticker_custom_message(custom_msg, singer_list)
            result = (singer_list, rendered_msg)
        else:
            result = singer_list

        # Log ticker singer transitions for diagnostics.
        try:
            new_first = (singer_list[0] if singer_list else "(none)")
            prev_first = getattr(self, "_ticker_last_first", None)
            if prev_first != new_first:
                cur = str(getattr(self, "_current_karaoke_singer_display", "") or "").strip() or "(none)"
                _diag(f"[TICKER] singer '{prev_first}' -> '{new_first}' "
                      f"(now_singing={cur!r}, active={len(singer_list)})")
                self._ticker_last_first = new_first
        except Exception:
            pass

        # Cache the result with its state signature.
        self._cached_ticker_data = result
        self._cached_ticker_sig = sig
        return result

    def _ticker_state_signature(self):
        """Cheap signature of everything that should drive the ticker: active
        singers (name + their first active song path) in order, plus the
        currently-playing singer. Changes whenever a song ends/advances/skips."""
        try:
            parts = []
            for s in (self.queue or []):
                if not self.is_singer_active(s):
                    continue
                name = str(s.get("name", "") or "")
                first_path = ""
                for song in s.get("songs", []) or []:
                    if isinstance(song, dict):
                        if song.get("skipped", False):
                            continue
                        si = song.get("song_info")
                        first_path = str(self._song_info_primary_path(si) or "")
                        break
                    else:
                        first_path = str(self._song_info_primary_path(song) or "")
                        break
                parts.append(name + "\x1f" + first_path)
            cur = str(getattr(self, "_current_karaoke_singer_display", "") or "")
            playing = "1" if bool(getattr(self, "karaoke_playing", False)) else "0"
            return "\x1e".join(parts) + "||" + cur + "||" + playing
        except Exception:
            return None

    def schedule_ticker_update(self):
        """Debounce ticker - only updates 150ms after last change"""
        try:
            app = QApplication.instance()
            if app is not None and QThread.currentThread() != app.thread():
                self._run_on_ui_thread(self.schedule_ticker_update)
                return
        except Exception:
            pass
        self._ticker_update_timer.stop()
        self._ticker_update_timer.start(150)
        self._schedule_next_up_prescan()
    
    def _do_ticker_update(self):
        """Actually update ticker after debounce"""
        # Invalidate cache so ticker recalculates
        if hasattr(self, '_cached_ticker_data'):
            delattr(self, '_cached_ticker_data')

        # A change of current singer has to reach the screen now. Routine queue
        # edits are deliberately deferred to the end of the scroll pass so the
        # marquee never visibly restarts, but that same deferral is what left
        # the ticker naming the singer whose song had already finished for the
        # whole gap between songs -- a full pass can easily outlast the gap.
        current_singer = str(getattr(self, "_current_karaoke_singer_display", "") or "")
        singer_changed = current_singer != getattr(self, "_ticker_last_rendered_singer", None)
        self._ticker_last_rendered_singer = current_singer

        try:
            if hasattr(self, 'video_window') and hasattr(self.video_window, 'ticker'):
                # Reset ticker's auto-timer to prevent double-updates
                self.video_window.ticker.queue_update_timer.stop()
                self.video_window.ticker.update_queue_text(force=singer_changed)
                self.video_window.ticker.queue_update_timer.start(5000)
        except Exception:
            pass

    def _get_list_font_scale(self) -> float:
        try:
            v = float(self.settings.get("list_font_scale", 1.0))
        except Exception:
            v = 1.0
        # Snap to nearest preset so behavior is predictable and each step is visible.
        try:
            return min(LIST_FONT_SCALE_PRESETS, key=lambda p: abs(float(p) - float(v)))
        except Exception:
            return 1.0

    def _apply_list_font_scale(self):
        """Apply native-font size scaling to the user-facing song/queue lists."""
        try:
            scale = self._get_list_font_scale()
        except Exception:
            scale = 1.0

        def apply_to_list(widget, base_size: int, row_mult: float = 2.15):
            if widget is None:
                return
            try:
                point_size = max(8, int(round(int(base_size) * scale)))
                row_height = max(28, int(round(point_size * row_mult)))
                f = widget.font()
                f.setPointSize(point_size)
                widget.setFont(f)

                # Existing QListWidgetItems may carry explicit fonts for status
                # styling. Keep that styling, but update their point size too.
                try:
                    widget.setUniformItemSizes(False)
                    for i in range(widget.count()):
                        item = widget.item(i)
                        item_font = item.font()
                        item_font.setFamily(f.family())
                        item_font.setPointSize(point_size)
                        item.setFont(item_font)
                        item.setSizeHint(QSize(0, row_height))
                except Exception:
                    pass

                try:
                    widget.doItemsLayout()
                    widget.updateGeometries()
                    widget.viewport().update()
                except Exception:
                    pass
            except Exception:
                pass

        try:
            results_base = int(getattr(self, "_results_base_point_size", 14 if sys.platform == "darwin" else 10))
            queue_base = int(getattr(self, "_queue_base_point_size", 14 if sys.platform == "darwin" else 10))
        except Exception:
            results_base = 14 if sys.platform == "darwin" else 10
            queue_base = results_base

        apply_to_list(getattr(self, "results_list", None), results_base, 2.38)
        apply_to_list(getattr(self, "queue_display", None), queue_base)

        # Secondary workspaces are built lazily; include them when present so
        # the Settings slider feels consistent across app screens.
        for name in ("singer_history_singer_list", "singer_history_songs_list", "waiting_for_add_list"):
            apply_to_list(getattr(self, name, None), queue_base)

        try:
            self._schedule_reformat_lists()
        except Exception:
            pass
        apply_to_list(getattr(self, "queue_display", None), queue_base)

    def _iter_audio_sink_devices(self):
        """Enumerate GStreamer audio sink devices."""
        devices = []
        try:
            mon = Gst.DeviceMonitor.new()
            mon.add_filter("Audio/Sink", None)
            mon.start()
            devices = list(mon.get_devices() or [])
            mon.stop()
        except Exception:
            return []
        return devices

    def _qt_audio_device_for_selected_output(self):
        """Resolve the existing SingWS/GStreamer selection to QAudioDevice.

        This adapter lets the FFmpeg/Signalsmith transport honor the same host
        choice without changing persisted device IDs or the production engine.
        """
        try:
            from PyQt6.QtMultimedia import QMediaDevices

            default_device = QMediaDevices.defaultAudioOutput()
            selected = self._get_selected_audio_output_id()
            if selected == "default":
                name = str(default_device.description() or "")
                return default_device, name

            outputs = list(getattr(self, "_audio_output_cache", []) or [])
            if not outputs:
                outputs = self._refresh_audio_output_cache()
            selected_item = next((item for item in outputs if str(item.get("id") or "") == selected), None)
            selected_name = (
                str((selected_item or {}).get("name") or "").strip()
                or str(self.settings.get("audio_output_name", "") or "").strip()
            )
            qt_outputs = list(QMediaDevices.audioOutputs() or [])
            device = match_qt_audio_device(qt_outputs, selected_name) if match_qt_audio_device else None
            if device is not None:
                _diag(f"[PY-KARAOKE] Qt audio output matched selected={selected!r} name={selected_name!r}")
                return device, selected_name

            default_name = str(default_device.description() or "")
            _diag(
                f"[PY-KARAOKE] Qt audio output match unavailable selected={selected!r} "
                f"gst_name={selected_name!r}; using default={default_name!r}"
            )
            return default_device, default_name
        except Exception as exc:
            _diag(f"[PY-KARAOKE] Qt audio output resolution failed; using implicit default ({exc})")
            return None, ""

    def _audio_output_id_for_device(self, dev) -> str:
        try:
            import hashlib
            name = str(dev.get_display_name() or "")
            caps = dev.get_caps()
            caps_s = caps.to_string() if caps else ""
            props = dev.get_properties()
            props_s = props.to_string() if props else ""
            raw = f"{name}|{caps_s}|{props_s}"
            return "dev_" + hashlib.sha1(raw.encode("utf-8", "ignore")).hexdigest()[:16]
        except Exception:
            return ""

    def _classify_audio_output_name(self, name: str) -> str:
        n = (name or "").lower()
        if any(k in n for k in ("airplay", "bluetooth", "tv", "hdmi", "display")):
            return "display"
        if any(k in n for k in ("headphone", "headset", "earbud", "airpods")):
            return "headphones"
        return "speaker"

    @staticmethod
    def _local_audio_output_priority(item) -> tuple:
        """Prefer the Mac's live headphone jack, then its built-in speakers."""
        name = str((item or {}).get("name") or "").casefold()
        kind = str((item or {}).get("kind") or "").casefold()
        if kind == "display" or any(
            token in name for token in ("airplay", "apple tv", "bravia", "television", "hdmi")
        ):
            return (99, name)
        if any(token in name for token in ("external headphones", "headphone", "headset")):
            return (0, name)
        if any(token in name for token in ("macbook", "built-in", "built in", "internal speakers")):
            return (1, name)
        return (2, name)

    def _safe_local_audio_output_name(self) -> str | None:
        """Resolve playback output without ever following an AirPlay display.

        macOS changes its system default when a TV is added through AirPlay.
        SingWS treats Default as the current local Mac output instead: the
        headphone jack when present, then built-in speakers. A valid explicit
        non-display pin still wins (USB interfaces included).
        """
        selected = self._get_selected_audio_output_id()
        outputs = list(getattr(self, "_audio_output_cache", []) or [])
        if not outputs:
            outputs = self._refresh_audio_output_cache()

        if selected != "default":
            item = next(
                (entry for entry in outputs if str(entry.get("id") or "") == selected),
                None,
            )
            if item is not None and self._local_audio_output_priority(item)[0] < 99:
                return str(item.get("name") or "").strip() or None

        try:
            from PyQt6.QtMultimedia import QMediaDevices
            default_name = str(QMediaDevices.defaultAudioOutput().description() or "").strip()
            default_item = {
                "name": default_name,
                "kind": self._classify_audio_output_name(default_name),
            }
            if default_name and self._local_audio_output_priority(default_item)[0] < 99:
                return default_name
        except Exception:
            pass

        candidates = [
            item for item in outputs
            if str(item.get("id") or "") != "default"
            and self._local_audio_output_priority(item)[0] < 99
        ]
        if candidates:
            chosen = min(candidates, key=self._local_audio_output_priority)
            name = str(chosen.get("name") or "").strip()
            _diag(
                f"[AUDIO] AirPlay-safe local fallback selected={name!r} "
                f"saved={str(self.settings.get('audio_output_name', '') or 'Default')!r}"
            )
            return name or None

        _diag("[AUDIO] no safe local output available; refusing AirPlay/display audio")
        return None

    def _audio_icon_for_kind(self, kind: str) -> str:
        k = str(kind or "").lower()
        if k == "display":
            return "🖥"
        if k == "headphones":
            return "🎧"
        return "🔊"

    @staticmethod
    def _normalized_audio_output_name(name: str) -> str:
        return "".join(ch for ch in str(name or "").casefold() if ch.isalnum())

    def _refresh_audio_output_cache(self):
        outputs = [{
            "id": "default",
            "name": "Default (System)",
            "kind": "speaker",
        }]
        seen_names = set()
        # Primary: Qt enumeration. Engine-agnostic (works for the libmpv/Qt
        # karaoke transport and, by name, for the BASS BGM engine) and its ids
        # are keyed on the display name ALONE, so a selection survives
        # reboots, driver churn, and AirPlay devices coming and going —
        # the old GStreamer ids hashed caps/props and silently un-pinned the
        # host's device whenever those changed (2026-07-20 AirPlay outage).
        try:
            from PyQt6.QtMultimedia import QMediaDevices

            import hashlib
            for dev in QMediaDevices.audioOutputs() or []:
                name = str(dev.description() or "").strip()
                key = self._normalized_audio_output_name(name)
                if not key or key in seen_names:
                    continue
                seen_names.add(key)
                did = "qt_" + hashlib.sha1(key.encode("utf-8", "ignore")).hexdigest()[:16]
                outputs.append({"id": did, "name": name, "kind": self._classify_audio_output_name(name)})
        except Exception:
            pass
        # Legacy: GStreamer device monitor. Only fills in devices Qt did not
        # report (and keeps their historic ids resolvable for old settings).
        try:
            for dev in self._iter_audio_sink_devices():
                did = self._audio_output_id_for_device(dev)
                if not did:
                    continue
                name = str(dev.get_display_name() or "Audio Output").strip() or "Audio Output"
                key = self._normalized_audio_output_name(name)
                if key in seen_names:
                    continue
                seen_names.add(key)
                kind = self._classify_audio_output_name(name)
                outputs.append({"id": did, "name": name, "kind": kind})
        except Exception:
            pass
        self._audio_output_cache = outputs
        return outputs

    def _audio_output_exists(self, output_id: str) -> bool:
        if (output_id or "default") == "default":
            return True
        for x in self._refresh_audio_output_cache():
            if x.get("id") == output_id:
                return True
        return False

    def _get_selected_audio_output_id(self) -> str:
        out_id = str(self.settings.get("audio_output_id", "default") or "default")
        if out_id != "default" and not self._audio_output_exists(out_id):
            recovered = self._recover_audio_output_selection(out_id)
            if recovered:
                return recovered
            _diag(
                f"[AUDIO] selected output id={out_id!r} "
                f"name={str(self.settings.get('audio_output_name', '') or '')!r} not found; "
                "temporarily using system default without changing the saved preference"
            )
        return out_id

    def _recover_audio_output_selection(self, stale_id: str) -> str:
        """Re-pin a stale device id by name instead of silently unpinning.

        Old GStreamer-era ids hashed device caps/props and churned between
        sessions; losing the pin dropped the host onto the system default,
        which AirPlay then hijacked. Recovery order: the persisted device
        name, then the legacy GStreamer id resolved to its display name.
        """
        outputs = list(getattr(self, "_audio_output_cache", []) or []) or self._refresh_audio_output_cache()

        def _adopt(name: str) -> str:
            key = self._normalized_audio_output_name(name)
            if not key:
                return ""
            for item in outputs:
                if str(item.get("id") or "") == "default":
                    continue
                if self._normalized_audio_output_name(item.get("name")) == key:
                    new_id = str(item.get("id") or "")
                    self.settings["audio_output_id"] = new_id
                    self.settings["audio_output_name"] = str(item.get("name") or "")
                    try:
                        self.save_settings()
                    except Exception:
                        pass
                    _diag(
                        f"[AUDIO] re-pinned output by name {item.get('name')!r} "
                        f"(stale id {stale_id!r} -> {new_id!r})"
                    )
                    return new_id
            return ""

        recovered = _adopt(str(self.settings.get("audio_output_name", "") or ""))
        if recovered:
            return recovered
        try:
            for dev in self._iter_audio_sink_devices():
                if self._audio_output_id_for_device(dev) == stale_id:
                    return _adopt(str(dev.get_display_name() or ""))
        except Exception:
            pass
        return ""

    def _create_audio_sink_for_selected_output(self, sink_name: str, default_factory: str = "autoaudiosink"):
        selected = self._get_selected_audio_output_id()
        if selected == "default":
            return Gst.ElementFactory.make(default_factory, sink_name)

        # Pinned output: build sink directly from matching Gst.Device.
        try:
            for dev in self._iter_audio_sink_devices():
                if self._audio_output_id_for_device(dev) != selected:
                    continue
                sink = dev.create_element(sink_name)
                if sink is not None:
                    self._audio_device_missing_notice_shown = False
                    return sink
        except Exception:
            pass

        # Selected device disappeared: use default for this sink only. Never
        # overwrite the durable preference; hot-plug recovery should return to
        # the saved device automatically when it is available again.
        if not self._audio_device_missing_notice_shown:
            _diag("[AUDIO] Selected output unavailable; reverting to Default (System)")
            self._audio_device_missing_notice_shown = True
        return Gst.ElementFactory.make(default_factory, sink_name)

    def _set_audio_output_id(self, output_id: str):
        output_id = str(output_id or "default")
        current = self._get_selected_audio_output_id()
        if output_id == current:
            return
        self.settings["audio_output_id"] = output_id
        # Persist the display name as well: it is the durable identity used to
        # re-pin the device if the id ever goes stale, and it is what the BASS
        # and Qt engines actually match on.
        try:
            outputs = list(getattr(self, "_audio_output_cache", []) or []) or self._refresh_audio_output_cache()
            item = next((x for x in outputs if str(x.get("id") or "") == output_id), None)
            self.settings["audio_output_name"] = str((item or {}).get("name") or "") if output_id != "default" else ""
        except Exception:
            pass
        try:
            self.save_settings()
        except Exception:
            pass
        _diag(
            f"[AUDIO] output pinned id={output_id!r} "
            f"name={str(self.settings.get('audio_output_name', '') or 'Default (System)')!r}"
        )
        self._update_audio_output_button()

        # Soundboard streams share BASS's output device. Release their handles
        # before the background engine tears down that device, then restore
        # active pads on the newly initialized output.
        strip = getattr(self, "soundboard_strip", None)
        try:
            if strip is not None and hasattr(strip, "prepare_audio_output_change"):
                strip.prepare_audio_output_change()
        except Exception as e:
            _diag(f"[AUDIO] Soundboard output preparation failed: {e}")

        # Apply immediately to BG; karaoke applies on next track.
        try:
            if hasattr(self, "bg_music") and self.bg_music is not None:
                self.bg_music.apply_audio_output_change()
        except Exception as e:
            _diag(f"[AUDIO] BG output switch failed: {e}")
        try:
            if strip is not None and hasattr(strip, "apply_audio_output_change"):
                strip.apply_audio_output_change()
        except Exception as e:
            _diag(f"[AUDIO] Soundboard output switch failed: {e}")

    def _ensure_screen_change_watcher(self):
        """Log screen topology changes and reconnect native video surfaces.

        A display appearing, vanishing, or being re-laid-out invalidates the
        native windows Qt is painting into, and flushing a repaint to one of
        those is what SIGSEGV'd inside QBackingStore::flush on 2026-07-30. The
        crash stack is entirely Qt-internal, so if a screen event precedes the
        next one, this is the line that will say so.
        """
        if getattr(self, "_screen_watcher_installed", False):
            return
        try:
            from PyQt6.QtGui import QGuiApplication

            app = QGuiApplication.instance()
            if app is None:
                return

            surface_refresh_timer = QTimer(self)
            surface_refresh_timer.setSingleShot(True)
            surface_refresh_timer.setInterval(600)
            surface_refresh_timer.timeout.connect(
                lambda: self._refresh_mpv_video_views("screen_topology_change")
            )
            self._screen_surface_refresh_timer = surface_refresh_timer

            def _log(event: str, screen=None, refresh_video: bool = False):
                try:
                    who = ""
                    if screen is not None:
                        geo = screen.geometry()
                        who = (f" screen={screen.name()!r} "
                               f"{geo.width()}x{geo.height()} dpr={screen.devicePixelRatio():.1f}")
                    _diag(f"[SCREEN] {event}{who} | {_describe_window_topology()}")
                except Exception:
                    pass

                # AirPlay display changes can replace the NSWindow backing the
                # embedded host preview while playback and the audience view
                # continue normally. Wait for the topology burst to settle,
                # then rebind both native drawables to their current Qt hosts.
                if refresh_video:
                    surface_refresh_timer.start()

            app.screenAdded.connect(lambda s: _log("screen added", s, True))
            app.screenRemoved.connect(lambda s: _log("screen removed", s, True))
            app.primaryScreenChanged.connect(lambda s: _log("primary screen changed", s, True))
            self._screen_watcher_installed = True
            _log("initial topology")
        except Exception as e:
            _diag(f"[SCREEN] watcher unavailable: {e}")

    def _ensure_audio_output_watcher(self):
        """Watch for CoreAudio device-list changes (AirPlay/Bluetooth)."""
        if getattr(self, "_qt_media_devices_watcher", None) is not None:
            return
        try:
            from PyQt6.QtMultimedia import QMediaDevices

            watcher = QMediaDevices(self)
            watcher.audioOutputsChanged.connect(self._on_qt_audio_outputs_changed)
            self._qt_media_devices_watcher = watcher
        except Exception:
            self._qt_media_devices_watcher = None

    def _on_qt_audio_outputs_changed(self):
        # An AirPlay display or Bluetooth device appeared/vanished. macOS flips
        # the SYSTEM default output to a new AirPlay device; a pinned SingWS
        # device shields karaoke (QAudioSink on an explicit QAudioDevice) and
        # BGM (BASS opened on an explicit device index) from that hijack, so
        # the job here is to refresh the picker and keep the pin intact.
        try:
            outputs = self._refresh_audio_output_cache()
            names = [str(o.get("name") or "") for o in outputs[1:]]
            selected = str(self.settings.get("audio_output_id", "default") or "default")
            pinned_name = str(self.settings.get("audio_output_name", "") or "")
            _diag(f"[AUDIO] output devices changed: {names!r} pinned={(pinned_name or 'default')!r}")
            if selected != "default" and pinned_name:
                pinned_key = self._normalized_audio_output_name(pinned_name)
                present = any(
                    self._normalized_audio_output_name(o.get("name")) == pinned_key
                    for o in outputs[1:]
                )
                if not present:
                    _diag(
                        f"[AUDIO] WARNING: pinned output {pinned_name!r} went offline; "
                        "audio may follow the system default until it returns"
                    )
            self._update_audio_output_button()
        except Exception:
            pass

    def _update_audio_output_button(self):
        self._ensure_audio_output_watcher()
        self._ensure_screen_change_watcher()
        selected = self._get_selected_audio_output_id()
        outputs = self._refresh_audio_output_cache()
        item = next((x for x in outputs if x.get("id") == selected), outputs[0] if outputs else None)
        if selected != "default" and not any(str(x.get("id") or "") == selected for x in outputs):
            saved_name = str(self.settings.get("audio_output_name", "") or "Saved audio output")
            item = {"id": selected, "name": saved_name, "kind": self._classify_audio_output_name(saved_name)}
            unavailable = True
        else:
            unavailable = False
        if item is None:
            icon = "🔊"
            tip = "Audio Output: Default (System)"
        else:
            icon = self._audio_icon_for_kind(item.get("kind", "speaker"))
            tip = f"Audio Output: {item.get('name', 'Default (System)')}"
            if unavailable:
                tip += " (unavailable; temporarily using system default)"
        self._audio_output_button_label = icon
        try:
            # Use native monochrome icon so it blends with transport controls.
            self.audio_output_button.setText("")
            self.audio_output_button.setFixedSize(44, 32)
            self.audio_output_button.setMinimumWidth(0)
            self.audio_output_button.setMaximumWidth(44)
            self.audio_output_button.setIcon(self._default_audio_output_icon())
            self.audio_output_button.setIconSize(QSize(30, 30))
            self.audio_output_button.setToolTip(tip)
        except Exception:
            self.audio_output_button.setFixedSize(44, 32)
            self.audio_output_button.setMinimumWidth(0)
            self.audio_output_button.setMaximumWidth(44)
            self.audio_output_button.setText(icon)
            self.audio_output_button.setToolTip(tip)

    def _open_audio_output_menu(self):
        """Refresh outputs on click, then open selection menu."""
        try:
            self._update_audio_output_button()
        except Exception:
            pass
        self._show_audio_output_menu()

    def _default_audio_output_icon(self) -> QIcon:
        """Draw a full-size speaker icon for the compact transport control."""
        try:
            dst = QPixmap(30, 30)
            dst.fill(Qt.GlobalColor.transparent)
            p = QPainter(dst)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            color = QColor("#F2F2F2")
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(color))
            p.drawPolygon(
                QPoint(4, 12),
                QPoint(10, 12),
                QPoint(17, 6),
                QPoint(17, 24),
                QPoint(10, 18),
                QPoint(4, 18),
            )
            pen = QPen(color, 2.2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawArc(QRect(16, 10, 7, 10), -45 * 16, 90 * 16)
            p.drawArc(QRect(15, 6, 13, 18), -45 * 16, 90 * 16)
            p.end()
            return QIcon(dst)
        except Exception:
            return self.style().standardIcon(QStyle.StandardPixmap.SP_MediaVolume)

    def _show_audio_output_menu(self):
        menu = QMenu(self)
        style_app_menu(menu)
        selected = self._get_selected_audio_output_id()
        outputs = self._refresh_audio_output_cache()

        if selected != "default" and not any(str(out.get("id") or "") == selected for out in outputs):
            saved_name = str(self.settings.get("audio_output_name", "") or "Saved audio output")
            missing = QAction(f"{saved_name} (Unavailable — saved)", menu)
            missing.setCheckable(True)
            missing.setChecked(True)
            missing.setEnabled(False)
            menu.addAction(missing)
            menu.addSeparator()

        for out in outputs:
            oid = str(out.get("id", "default"))
            label = f"{out.get('name', 'Audio Output')}"
            act = QAction(label, menu)
            act.setCheckable(True)
            act.setChecked(oid == selected)
            act.triggered.connect(lambda _=False, x=oid: self._set_audio_output_id(x))
            menu.addAction(act)

        menu.exec(self.audio_output_button.mapToGlobal(self.audio_output_button.rect().bottomLeft()))

    def _update_download_dir(self) -> str:
        custom = str(self.settings.get("auto_update_download_dir", "") or "").strip()
        if custom:
            return os.path.expanduser(custom)
        return str(Path.home() / "Downloads" / "SingWS Pro Updates")

    def _set_update_status_text(self, text: str):
        self._last_update_status_text = str(text or "")
        for label in list(getattr(self, "_update_status_labels", []) or []):
            try:
                label.setText(self._last_update_status_text)
            except Exception:
                pass

    def _start_update_check(self, *, manual: bool = False, download: bool = False):
        try:
            worker = getattr(self, "_github_update_worker", None)
            if worker is not None and worker.isRunning():
                if manual:
                    self._set_update_status_text("Update check already running...")
                return
        except Exception:
            pass
        repo = _effective_update_repo(self.settings.get("auto_update_repo", ""))
        self._github_update_manual = bool(manual)
        self._github_update_download_requested = bool(download)
        self._set_update_status_text("Checking GitHub for updates...")
        self._github_update_worker = GitHubUpdateWorker(
            repo=repo,
            current_version=APP_VERSION,
            manifest_url=_effective_update_manifest_url(self.settings.get("auto_update_manifest_url", "")),
            download_dir=self._update_download_dir(),
            download=bool(download),
        )
        self._github_update_worker.checked.connect(self._on_update_check_finished)
        self._github_update_worker.progress.connect(self._on_update_download_progress)
        self._github_update_worker.downloaded.connect(self._on_update_downloaded)
        self._github_update_worker.failed.connect(self._on_update_failed)
        self._github_update_worker.start()

    def _maybe_auto_check_for_updates(self):
        try:
            if not bool(self.settings.get("auto_update_enabled", True)):
                return
            now = int(time.time())
            last = int(self.settings.get("auto_update_last_check", 0) or 0)
            hours = max(1, int(float(self.settings.get("auto_update_check_interval_hours", 12) or 12)))
            if last and (now - last) < hours * 3600:
                return
            self.settings["auto_update_last_check"] = now
            self.save_settings()
            self._start_update_check(manual=False, download=bool(self.settings.get("auto_update_download", True)))
        except Exception as e:
            print(f"[UPDATE] auto-check skipped: {e}")

    def _on_update_check_finished(self, info: dict):
        try:
            version = str((info or {}).get("version") or "").strip()
            if not version:
                self._set_update_status_text("Could not read latest GitHub release.")
                return
            if info.get("available"):
                asset_name = str(((info or {}).get("asset") or {}).get("name") or "installer")
                self._set_update_status_text(f"SingWS {version} is available: {asset_name}")
                if bool(getattr(self, "_github_update_manual", False)) and not bool(getattr(self, "_github_update_download_requested", False)):
                    QMessageBox.information(
                        self,
                        "Update Available",
                        f"SingWS {version} is available on GitHub.\n\nUse Download Latest Update to fetch the installer.",
                    )
            else:
                self._set_update_status_text(f"SingWS is up to date ({APP_VERSION}).")
                if bool(getattr(self, "_github_update_manual", False)):
                    QMessageBox.information(self, "No Update Available", f"SingWS {APP_VERSION} is the latest release.")
        except Exception as e:
            self._set_update_status_text(f"Update check failed: {e}")

    def _on_update_download_progress(self, pct: int, text: str):
        self._set_update_status_text(str(text or f"Downloading update ({int(pct)}%)"))

    def _on_update_downloaded(self, info: dict):
        path = str((info or {}).get("download_path") or "")
        version = str((info or {}).get("version") or "").strip()
        if not path:
            self._set_update_status_text("Update download finished, but no file path was returned.")
            return
        self.settings["auto_update_last_download_path"] = path
        self.settings["auto_update_last_download_version"] = version
        try:
            self.save_settings()
        except Exception:
            pass
        self._set_update_status_text(f"Downloaded SingWS {version}: {path}")
        try:
            msg = QMessageBox(self)
            msg.setWindowTitle("Update Downloaded")
            msg.setText(f"SingWS {version} has been downloaded.")
            msg.setInformativeText("Open the downloaded DMG, then drag SingWS Pro.app to Applications to install it.")
            open_btn = msg.addButton("Show in Finder", QMessageBox.ButtonRole.AcceptRole)
            msg.addButton("Later", QMessageBox.ButtonRole.RejectRole)
            msg.exec()
            if msg.clickedButton() == open_btn:
                QDesktopServices.openUrl(QUrl.fromLocalFile(str(Path(path).parent)))
        except Exception:
            pass

    def _on_update_failed(self, message: str):
        text = f"Update failed: {message}"
        self._set_update_status_text(text)
        if bool(getattr(self, "_github_update_manual", False)):
            try:
                QMessageBox.warning(self, "Update Failed", text)
            except Exception:
                pass

    def _open_github_releases_page(self):
        repo = _effective_update_repo(self.settings.get("auto_update_repo", ""))
        QDesktopServices.openUrl(QUrl(f"https://github.com/{repo}/releases"))

    def configure_settings(self):
        """App settings dialog (list text size + CDG display mode)."""
        from PyQt6.QtWidgets import (
            QDialog, QVBoxLayout, QHBoxLayout, QLabel, QPushButton,
            QSlider, QCheckBox, QLineEdit, QSpinBox, QDoubleSpinBox, QScrollArea, QTabWidget
        )
        from PyQt6.QtGui import QCursor
        import copy as _copy

        dlg = QDialog(self)
        dlg.setWindowTitle("Settings")
        original_settings = _copy.deepcopy(self.settings)
        _fit_dialog_to_screen(dlg, preferred=(760, 640), minimum=(560, 380))

        root = QVBoxLayout(dlg)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        # Organize settings into tabs so the dialog stays small and readable and
        # fits cleanly on smaller / Intel laptop screens. Each tab scrolls only
        # if its own content overflows; the Save/Close bar stays fixed below.
        tabs = QTabWidget(dlg)
        tabs.tabBar().setElideMode(Qt.TextElideMode.ElideNone)
        tabs.setUsesScrollButtons(True)
        root.addWidget(tabs, 1)

        _setting_tabs = []
        def _make_settings_tab(title):
            page = QWidget()
            page_outer = QVBoxLayout(page)
            page_outer.setContentsMargins(0, 0, 0, 0)
            tab_scroll = QScrollArea(page)
            tab_scroll.setWidgetResizable(True)
            tab_scroll.setFrameShape(QFrame.Shape.NoFrame)
            tab_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
            inner = QWidget()
            tab_scroll.setWidget(inner)
            page_outer.addWidget(tab_scroll)
            lay = QVBoxLayout(inner)
            lay.setContentsMargins(14, 14, 14, 14)
            lay.setSpacing(12)
            tabs.addTab(page, title)
            _setting_tabs.append(lay)
            return lay

        # Short, single-word tab titles so all six fit on one row without being
        # clipped or pushed behind scroll arrows, even on narrow Intel screens.
        tab_general = _make_settings_tab("General")
        tab_display = _make_settings_tab("Display")
        tab_audio = _make_settings_tab("Audio")
        tab_search = _make_settings_tab("Search")
        tab_server = _make_settings_tab("Server")
        tab_advanced = _make_settings_tab("Advanced")

        # Group related controls into titled "cards" so each tab reads as a set of
        # clean sections — reuses the same card styling as the library/rotation
        # panels for a consistent, polished look.
        def _section_card(tab_layout, title=None, hint=None):
            card = QFrame()
            card.setObjectName("settingsCard")
            try:
                card.setStyleSheet(content_card_css("settingsCard", radius=12))
            except Exception:
                pass
            cl = QVBoxLayout(card)
            cl.setContentsMargins(16, 13, 16, 14)
            cl.setSpacing(9)
            if title:
                _t = QLabel(title)
                try:
                    _t.setStyleSheet(section_title_css())
                except Exception:
                    pass
                cl.addWidget(_t)
            if hint:
                _h = QLabel(hint)
                try:
                    _h.setStyleSheet(section_meta_css())
                except Exception:
                    pass
                _h.setWordWrap(True)
                cl.addWidget(_h)
            tab_layout.addWidget(card)
            return cl

        # Polished tab bar + primary Save button, themed to match the rest of the app.
        def _settings_dialog_extra_css():
            return f"""
                QTabWidget::pane {{
                    border: 1px solid {_v('border')};
                    border-radius: 12px;
                    top: -1px;
                    background: {_v('surface')};
                }}
                QTabBar {{ qproperty-drawBase: 0; }}
                QTabBar::tab {{
                    background: transparent;
                    color: {_v('text_soft')};
                    border: 1px solid transparent;
                    border-radius: 9px;
                    padding: 8px 14px;
                    margin: 4px 2px;
                    font-size: 12px;
                    font-weight: 750;
                    min-height: 32px;
                }}
                QTabBar::tab:hover {{
                    background: rgba(124,61,255,0.12);
                    color: {_v('text_bright')};
                }}
                QTabBar::tab:selected {{
                    background: {_v('accent')};
                    color: {_v('accent_text')};
                    border: 1px solid {_v('accent_bright')};
                }}
                QPushButton#settingsPrimaryBtn {{
                    background: {_v('accent')};
                    color: {_v('accent_text')};
                    border: 1px solid {_v('accent_bright')};
                    font-weight: 800;
                }}
                QPushButton#settingsPrimaryBtn:hover {{
                    background: {_v('accent_bright')};
                    border-color: {_v('accent_bright')};
                }}
            """

        # `v` is the "current section" layout; reassigned per section below so the
        # existing control-building code routes each group into the right card.
        v = _section_card(tab_display, "Display")

        try:
            if hasattr(self, "queue_display"):
                base = self.queue_display.palette().color(QPalette.ColorRole.Base)
                win = self.palette().color(QPalette.ColorRole.Window)
                txtc = self.palette().color(QPalette.ColorRole.Text)
            else:
                base = self.palette().color(QPalette.ColorRole.Base)
                win = self.palette().color(QPalette.ColorRole.Window)
                txtc = self.palette().color(QPalette.ColorRole.Text)

            border = base.darker(120)
            hover = base.lighter(115)
            pressed = base.darker(110)
            field_bg = base.darker(105)
            focus_border = border.lighter(120)

            dlg.setStyleSheet(dialog_stylesheet(win, base, txtc) + _settings_dialog_extra_css())
        except Exception:
            pass

        row = QHBoxLayout()
        row.addWidget(QLabel("Text Size:"))

        slider = QSlider(Qt.Orientation.Horizontal)
        slider.setRange(0, len(LIST_FONT_SCALE_PRESETS) - 1)
        slider.setSingleStep(1)
        slider.setPageStep(1)
        slider.setTickPosition(QSlider.TickPosition.TicksBelow)
        slider.setTickInterval(1)

        current_scale = self._get_list_font_scale()
        try:
            current_idx = min(range(len(LIST_FONT_SCALE_PRESETS)), key=lambda i: abs(LIST_FONT_SCALE_PRESETS[i] - current_scale))
        except Exception:
            current_idx = LIST_FONT_SCALE_DEFAULT_INDEX
        slider.setValue(current_idx)
        row.addWidget(slider, 1)

        v.addLayout(row)

        cdg_display_row = QHBoxLayout()
        cdg_display_row.addWidget(QLabel("CDG Display:"))
        cdg_display_combo = QComboBox(dlg)
        cdg_display_combo.addItem("Fit original lyrics", "fit")
        cdg_display_combo.addItem("Widescreen side fill (background color)", "sidefill")
        cdg_display_combo.addItem("Widescreen side fill (blurred image)", "blur")
        # Offered only where it actually renders. The in-process mpv backend
        # always preserves aspect, so listing it there was a control that
        # silently did nothing.
        _stretch_ok = self._video_stretch_supported()
        if _stretch_ok:
            cdg_display_combo.addItem("Stretch to fill", "stretch")
        cdg_display_combo.setToolTip(
            "Side fill keeps lyrics unstretched and fills widescreen side bars.\n"
            "Background color uses the disc's own background/border color, so on "
            "the many discs with a black background the bars stay black.\n"
            "Blurred image fills the bars with a soft blur of the lyrics picture "
            "itself, which is visible on every disc."
            + ("" if _stretch_ok else
               "\n\nStretch to fill is unavailable on the current mpv backend, "
               "which always preserves aspect.")
        )
        cur_cdg_display = self._effective_cdg_display_mode()
        cdg_display_idx = cdg_display_combo.findData(cur_cdg_display)
        cdg_display_combo.setCurrentIndex(cdg_display_idx if cdg_display_idx >= 0 else 0)
        cdg_display_row.addWidget(cdg_display_combo)
        cdg_display_row.addStretch(1)
        v.addLayout(cdg_display_row)

        cdg_black_cleanup_cb = QCheckBox("Clean near-black CDG backgrounds")
        cdg_black_cleanup_cb.setToolTip("Clamps only very dark CDG background pixels to true black. Lyrics and colored graphics are left alone.")
        cdg_black_cleanup_cb.setChecked(bool(self.settings.get("cdg_near_black_cleanup", True)))
        v.addWidget(cdg_black_cleanup_cb)

        cdg_black_row = QHBoxLayout()
        cdg_black_row.addWidget(QLabel("Black cleanup threshold:"))
        cdg_black_threshold_spin = QSpinBox(dlg)
        cdg_black_threshold_spin.setRange(0, 32)
        cdg_black_threshold_spin.setSingleStep(1)
        try:
            cdg_black_threshold_spin.setValue(max(0, min(32, int(self.settings.get("cdg_near_black_threshold", 10) or 10))))
        except Exception:
            cdg_black_threshold_spin.setValue(10)
        cdg_black_row.addWidget(cdg_black_threshold_spin)
        cdg_black_row.addStretch(1)
        v.addLayout(cdg_black_row)

        lyric_bg_opacity_row = QHBoxLayout()
        lyric_bg_opacity_row.addWidget(QLabel("Background video opacity/transparency:"))
        lyric_bg_opacity_spin = QSpinBox(dlg)
        lyric_bg_opacity_spin.setRange(0, 100)
        lyric_bg_opacity_spin.setSingleStep(5)
        lyric_bg_opacity_spin.setSuffix("%")
        lyric_bg_opacity_spin.setToolTip("Shows the background (video/idle/slideshow) subtly through near-black CDG background pixels only. Lyrics stay opaque.")
        try:
            lyric_bg_opacity_spin.setValue(max(0, min(100, int(float(self.settings.get("lyrics_background_video_opacity", 0) or 0)))))
        except Exception:
            lyric_bg_opacity_spin.setValue(0)
        lyric_bg_opacity_row.addWidget(lyric_bg_opacity_spin)
        lyric_bg_opacity_row.addStretch(1)
        v.addLayout(lyric_bg_opacity_row)

        # ---- Background videos behind CDG lyrics ----
        v = _section_card(tab_display, "Background Videos Behind Lyrics",
                          "Plays muted MP4s from a folder behind CDG lyrics at the "
                          "opacity above. Needs opacity > 0. Falls back to the normal "
                          "background when the folder is empty or missing.")
        bg_video_enable_cb = QCheckBox("Enable Background Videos Behind Lyrics")
        bg_video_enable_cb.setChecked(bool(self.settings.get("bg_video_enabled", False)))
        v.addWidget(bg_video_enable_cb)

        bg_video_shuffle_cb = QCheckBox("Shuffle Background Videos")
        bg_video_shuffle_cb.setToolTip("Every video plays once before any repeats. Off = alphabetical loop.")
        bg_video_shuffle_cb.setChecked(bool(self.settings.get("bg_video_shuffle", True)))
        v.addWidget(bg_video_shuffle_cb)

        bg_video_folder_row = QHBoxLayout()
        bg_video_folder_btn = QPushButton("Choose Background Video Folder…")
        bg_video_folder_row.addWidget(bg_video_folder_btn)
        bg_video_folder_label = QLabel()
        bg_video_folder_label.setWordWrap(True)

        def _refresh_bg_video_folder_label():
            folder = str(self.settings.get("bg_video_folder", "") or "")
            if not folder:
                bg_video_folder_label.setText("No folder selected")
                return
            # Do not enumerate a File Provider/mounted folder from this button
            # callback. Playback scans it on its worker path when needed.
            bg_video_folder_label.setText(folder)

        _refresh_bg_video_folder_label()
        bg_video_folder_row.addWidget(bg_video_folder_label, 1)
        v.addLayout(bg_video_folder_row)

        def on_choose_bg_video_folder():
            start_dir = str(self.settings.get("bg_video_folder", "") or "") or str(Path.home())
            folder = QFileDialog.getExistingDirectory(dlg, "Choose Background Video Folder", start_dir)
            if folder:
                self.settings["bg_video_folder"] = folder
                try:
                    self.save_settings()
                except Exception:
                    pass
                _refresh_bg_video_folder_label()
                _diag(f"[BG-VIDEO] folder selected folder={folder!r}")

        bg_video_folder_btn.clicked.connect(on_choose_bg_video_folder)

        v = _section_card(
            tab_display, "Animated Effects",
            "Each of these uses the GPU. Turn them off if the show screen stutters.",
        )
        show_screen_vfx_cb = QCheckBox("Show Screen transitions")
        show_screen_vfx_cb.setToolTip(
            "Full-screen 3-2-1 after Play, spotlights, shockwaves, and singer-start confetti. "
            "Turn off to skip the animated countdown on slower laptops."
        )
        show_screen_vfx_cb.setChecked(bool(self.settings.get("show_screen_vfx_enabled", True)))
        v.addWidget(show_screen_vfx_cb)

        rotation_vfx_cb = QCheckBox("Singer Rotation")
        rotation_vfx_cb.setToolTip(
            "Particles, glow loops, parallax, flashes, and singer-change explosions. "
            "The smooth vertical rotation scroll stays enabled when this is off."
        )
        rotation_vfx_cb.setChecked(bool(self.settings.get("rotation_vfx_enabled", True)))
        v.addWidget(rotation_vfx_cb)

        _quick_row = QHBoxLayout()
        _quick_row.addWidget(QLabel("Animated GPU ticker / transitions:"))
        quick_combo = QComboBox(dlg)
        quick_combo.addItem("Automatic (on, Intel Macs included)", "auto")
        quick_combo.addItem("On — animated ticker and transitions", "on")
        quick_combo.addItem("Off — plain painter ticker", "off")
        quick_combo.setToolTip(
            "The animated ticker lighting and the between-singer transitions run on "
            "Qt Quick. They were disabled on Intel Macs on 2026-08-01 to stop a "
            "crash, but Qt Quick has never appeared in a crash on this machine and "
            "the crash kept happening without it — including one on 2026-08-09 in a "
            "session with no Quick surfaces running at all. Automatic now means on "
            "everywhere; choose Off if you prefer the plain painter ticker."
            "\n\nTakes effect at the next launch."
        )
        _quick_cur = str(self.settings.get("quick_gpu_surfaces", "auto") or "auto")
        _qi = quick_combo.findData(_quick_cur)
        quick_combo.setCurrentIndex(_qi if _qi >= 0 else 0)
        _quick_row.addWidget(quick_combo)
        _quick_row.addStretch(1)
