    def _waiting_for_add_request_id(self, req: dict | None) -> int:
        try:
            return int((req or {}).get("request_id") or (req or {}).get("id") or 0)
        except Exception:
            return 0

    def _accepted_request_identity_text(self, value) -> str:
        try:
            return song_index.normalize_text(str(value or "").strip())
        except Exception:
            return re.sub(r"\s+", " ", str(value or "").strip().lower())

    def _accepted_request_identity_parts(self, req: dict | None) -> tuple:
        req = req if isinstance(req, dict) else {}
        replacement = req.get("replacement_track") if isinstance(req.get("replacement_track"), dict) else {}
        track = replacement if replacement else req
        singer_raw = str(req.get("singer") or req.get("name") or "").strip()
        primary, _duet = self._parse_duet_singer(singer_raw)
        singer_key = self._queue_limit_name_key(primary or singer_raw)
        artist = self._accepted_request_identity_text(track.get("artist") or req.get("artist") or "")
        title = self._accepted_request_identity_text(track.get("title") or req.get("title") or req.get("display_name") or "")
        version_values = []
        for key in (
            "song_key",
            "stable_request_key",
            "selected_version",
            "selected_brand",
            "selected_disc_id",
            "selected_source",
            "disc_id",
            "discid",
            "songid",
            "song_id",
            "brand",
            "version",
            "source",
            "request_source",
        ):
            value = self._accepted_request_identity_text(track.get(key) or req.get(key) or "")
            if value and value not in version_values:
                version_values.append(value)
        return singer_key, artist, title, "|".join(version_values[:4])

    def _accepted_request_identity_for_entry(self, singer: dict | None, entry: dict | None) -> tuple:
        singer_name = str((singer or {}).get("name") or "").strip()
        entry = entry if isinstance(entry, dict) else {}
        artist = str(entry.get("artist") or "").strip()
        title = str(entry.get("title") or "").strip()
        if not (artist and title):
            try:
                display = str(entry.get("display_name") or entry.get("display") or "").strip()
                a2, t2, _d2 = self._split_display_artist_title_disc(display)
                artist = artist or a2
                title = title or t2
            except Exception:
                pass
        req = {
            "singer": singer_name,
            "artist": artist,
            "title": title,
            "selected_version": entry.get("selected_version"),
            "selected_brand": entry.get("selected_brand"),
            "selected_disc_id": entry.get("selected_disc_id") or entry.get("disc_id") or entry.get("discid"),
            "song_key": entry.get("song_key") or entry.get("stable_request_key"),
            "songid": entry.get("songid") or entry.get("song_id"),
            "source": entry.get("source") or entry.get("type"),
            "request_source": entry.get("request_source"),
        }
        return self._accepted_request_identity_parts(req)

    def _accepted_request_identity_sets(self) -> tuple[set[int], set[tuple], set[tuple]]:
        ids: set[int] = set()
        exact_sigs: set[tuple] = set()
        loose_sigs: set[tuple] = set()
        try:
            for rid in self._queue_remote_request_ids() or []:
                rid = int(rid)
                if rid > 0:
                    ids.add(rid)
        except Exception:
            pass
        try:
            ids |= {int(v) for v in self._deferred_remote_request_ids()}
        except Exception:
            pass
        try:
            ids |= {int(v) for v in self._remote_request_inflight_ids()}
        except Exception:
            pass
        try:
            handled = getattr(self, "_waiting_for_add_handled_ids", set())
            if isinstance(handled, set):
                ids |= {int(v) for v in handled if int(v) > 0}
        except Exception:
            pass
        try:
            for singer in getattr(self, "queue", []) or []:
                if not isinstance(singer, dict):
                    continue
                for entry in singer.get("songs", []) or []:
                    if not isinstance(entry, dict):
                        continue
                    rid = self._queue_entry_remote_request_id(entry)
                    if rid is not None:
                        try:
                            ids.add(int(rid))
                        except Exception:
                            pass
                    sig = self._accepted_request_identity_for_entry(singer, entry)
                    if sig[0] and sig[1] and sig[2]:
                        exact_sigs.add(sig)
                        loose_sigs.add(sig[:3])
        except Exception:
            pass
        return ids, exact_sigs, loose_sigs

    def _request_matches_accepted_queue_item(self, req: dict | None, *, identity_sets=None) -> bool:
        if not isinstance(req, dict):
            return False
        if identity_sets is None:
            identity_sets = self._accepted_request_identity_sets()
        accepted_ids, exact_sigs, loose_sigs = identity_sets
        rid = self._waiting_for_add_request_id(req)
        if rid > 0:
            return rid in accepted_ids
        sig = self._accepted_request_identity_parts(req)
        if sig[0] and sig[1] and sig[2]:
            if sig in exact_sigs:
                return True
            if sig[:3] in loose_sigs:
                return True
        return False

    def _cleanup_accepted_waiting_for_add_requests(self, *, reason: str = "accepted_cleanup") -> int:
        pending = getattr(self, "_waiting_for_add_requests", None)
        if not isinstance(pending, dict) or not pending:
            return 0
        identity_sets = self._accepted_request_identity_sets()
        removed = 0
        handled = getattr(self, "_waiting_for_add_handled_ids", None)
        if not isinstance(handled, set):
            handled = set()
            self._waiting_for_add_handled_ids = handled
        for rid, req in list(pending.items()):
            if self._request_matches_accepted_queue_item(req, identity_sets=identity_sets):
                pending.pop(rid, None)
                rid_int = 0
                try:
                    rid_int = int(rid)
                    if rid_int > 0:
                        handled.add(rid_int)
                except Exception:
                    pass
                removed += 1
                try:
                    attention = getattr(self, "_remote_attention_requests", None)
                    if isinstance(attention, dict):
                        attention.pop(rid, None)
                        attention.pop(rid_int, None)
                except Exception:
                    pass
        if removed:
            _diag(f"[WAITING-FOR-ADD] removed accepted duplicate pending count={removed} reason={reason}")
        return removed

    def _mark_waiting_for_add_duplicate_accepted(self, req: dict | None, *, reason: str = "accepted_duplicate") -> None:
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            state = {}
        try:
            handled = state.get("_waiting_for_add_handled_ids")
            if not isinstance(handled, set):
                handled = set()
                self._waiting_for_add_handled_ids = handled
            handled.add(rid)
            state["_waiting_for_add_handled_ids"] = handled
        except Exception:
            pass
        try:
            pending = state.get("_waiting_for_add_requests")
            if isinstance(pending, dict):
                pending.pop(rid, None)
        except Exception:
            pass
        try:
            attention = state.get("_remote_attention_requests")
            if isinstance(attention, dict):
                attention.pop(rid, None)
        except Exception:
            pass
        try:
            self._mark_waiting_for_add_delivered_async(rid, req)
        except Exception:
            pass
        _diag(f"[WAITING-FOR-ADD] suppressed accepted duplicate request_id={rid} reason={reason}")

    def _waiting_for_add_reason_text(self, req: dict | None) -> str:
        req = req or {}
        reason = str(req.get("pending_reason") or req.get("attention_reason") or "").strip()
        status = str(req.get("pending_status") or "").strip()
        if status:
            return status
        labels = {
            "failed_needs_review": "Needs Review",
            "host_not_accepting": "Waiting because requests are closed",
            "rotation_full": "Waiting because rotation is full",
            "sync_failed": "Waiting because song failed to sync",
            "auto_accept_failed": "Waiting because song failed to sync",
            "queue_insert_failed": "Waiting because add confirmation was not received",
            "no_local_library_match": "Waiting because song is not in the local library",
            "previous_auto_match_failure": "Waiting because song failed to match earlier",
            "cdg_missing_mp3": "Waiting because CDG audio is missing",
            "invalid_zip_format": "Waiting because the ZIP format is invalid",
        }
        if reason.startswith("unsupported_format"):
            return "Waiting because song format is unsupported"
        state = str(req.get("state") or "").strip().lower()
        if state == "failed_needs_review":
            return "Needs Review"
        if state == "failed":
            return "Waiting because song failed to sync"
        if state == "waiting":
            return "Waiting for host to add"
        return labels.get(reason, "Waiting for host to add")

    def _waitlist_evening_key(self) -> str:
        """Group after-midnight removals with the show that started the prior evening."""
        return (datetime.now() - timedelta(hours=6)).strftime("%Y-%m-%d")

    def _load_waitlist_removed_tonight(self) -> dict:
        data = _load_json_file(
            WAITLIST_REMOVED_TONIGHT_PATH, {}, expected_type=dict,
            label="Waitlist removed tonight",
        )
        tenant = str(getattr(self, "settings", {}).get("user") or getattr(self, "settings", {}).get("tenant") or "")
        if data.get("evening") != self._waitlist_evening_key() or str(data.get("tenant") or "") != tenant:
            return {}
        rows = data.get("requests")
        if not isinstance(rows, dict):
            return {}
        restored = {}
        for key, req in rows.items():
            try:
                rid = int(key)
            except Exception:
                continue
            if rid > 0 and isinstance(req, dict):
                restored[rid] = dict(req)
        return restored

    def _save_waitlist_removed_tonight(self) -> None:
        tenant = str(self.settings.get("user") or self.settings.get("tenant") or "")
        rows = getattr(self, "_waiting_for_add_removed_tonight", {})
        try:
            _save_json_atomic(WAITLIST_REMOVED_TONIGHT_PATH, {
                "version": 1,
                "evening": self._waitlist_evening_key(),
                "tenant": tenant,
                "requests": rows if isinstance(rows, dict) else {},
            })
        except Exception as exc:
            _diag(f"[WAITING-FOR-ADD] removed-tonight save failed: {exc}")

    def _archive_waitlist_removed_tonight(self, req: dict, *, reason: str) -> None:
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return
        rows = getattr(self, "_waiting_for_add_removed_tonight", None)
        if not isinstance(rows, dict):
            rows = {}
            self._waiting_for_add_removed_tonight = rows
        item = copy.deepcopy(req)
        item.update({
            "request_id": rid,
            "state": "removed",
            "removed_at": time.time(),
            "removal_reason": str(reason or "host_remove"),
            "_removed_tonight": True,
        })
        rows[rid] = item
        self._save_waitlist_removed_tonight()

    def _toggle_waiting_for_add_removed_view(self, checked: bool) -> None:
        self._waiting_for_add_show_removed = bool(checked)
        self._schedule_waiting_for_add_view_refresh(reason="removed_tonight_toggle")

    def _restore_selected_waiting_for_add(self) -> None:
        req = self._selected_waiting_for_add_request()
        if not isinstance(req, dict) or not req.get("_removed_tonight"):
            return
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return
        restored = copy.deepcopy(req)
        for key in ("_removed_tonight", "removed_at", "removed_by", "removal_reason", "completed_at"):
            restored.pop(key, None)
        restored["state"] = "waiting"
        restored["pending_status"] = "Restored by host"
        restored["pending_reason"] = str(restored.get("pending_reason") or "host_restored")
        self._queue_revision = int(getattr(self, "_queue_revision", 0) or 0) + 1
        revision = int(self._queue_revision)
        restored["local_revision"] = revision
        self._waiting_for_add_requests[rid] = restored
        self._waiting_for_add_removed_tonight.pop(rid, None)
        self._waiting_for_add_handled_ids.discard(rid)
        removed_ids = getattr(self, "_remote_removed_request_ids", None)
        if isinstance(removed_ids, set):
            removed_ids.discard(rid)
        self._drop_remote_request_tombstone(rid, reason="waitlist_restore")
        self._save_waitlist_removed_tonight()
        self._restore_waitlist_request_on_server_async(restored, revision)
        self._schedule_waiting_for_add_view_refresh(reason="restore_removed")
        self._show_processing_notification("Restored song to tonight's waitlist.", level="success")

    def _restore_waitlist_request_on_server_async(self, req: dict, revision: int) -> None:
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        rid = self._waiting_for_add_request_id(req)
        if not base_url or not tenant or not api_key or rid <= 0:
            _diag(f"[WAITING-FOR-ADD] restore pending server sync request_id={rid}")
            return

        def worker():
            try:
                response = requests.post(
                    f"{base_url}/api/v1/restore_remote_request.php",
                    data={"user": tenant, "request_id": rid, "local_revision": int(revision)},
                    headers={"X-API-Key": api_key, "Accept": "application/json"},
                    timeout=5,
                )
                _diag(
                    f"[WAITING-FOR-ADD] restore server request_id={rid} "
                    f"ok={int(200 <= response.status_code < 300)} status={response.status_code}"
                )
            except Exception as exc:
                _diag(f"[WAITING-FOR-ADD] restore server failed request_id={rid}: {exc}")

        threading.Thread(target=worker, daemon=True, name="waitlist-restore").start()

    def _is_waiting_for_add_request(self, req: dict | None) -> bool:
        if not isinstance(req, dict):
            return False
        state = str(req.get("state") or "").strip().lower()
        if self._remote_request_is_non_actionable(req):
            return False
        if state in {"waiting", "failed", "failed_needs_review"}:
            return True
        return bool(str(req.get("pending_reason") or req.get("last_error") or req.get("attention_reason") or "").strip())

    def _remote_request_is_non_actionable(self, req: dict | None) -> bool:
        """Return whether a server row has left host-actionable intake.

        ``sent``/``delivered`` are transport acknowledgement fields on older
        servers.  An explicit lifecycle state is authoritative: a waiting or
        failed row remains actionable even if one of those transport flags is
        stale.
        """
        if not isinstance(req, dict):
            return False
        state = str(req.get("state") or req.get("status") or "").strip().lower()
        if state in {"waiting", "failed", "failed_needs_review"}:
            return False
        if state == "accepted":
            # The server's submit-time validation marks fresh requests
            # "accepted" before the desktop has ever seen them (server change
            # of 2026-07-19; this filed every new request as historical and
            # killed the whole show's intake). Accepted alone is not proof of
            # delivery — require a transport ack or a desktop-side record.
            if bool(req.get("sent") or req.get("delivered")):
                return True
            sync_status = str(req.get("desktop_sync_status") or "").strip().lower()
            return sync_status not in {"", "pending", "pending_desktop_sync"}
        if state in {"active", "delivered", "completed", "sung", "removed", "skipped"}:
            return True
        try:
            if bool(req.get("sent") or req.get("delivered")):
                return True
        except Exception:
            pass
        # "accepted_at" is deliberately NOT delivery evidence: the new server
        # stamps it at submit-time validation, before the desktop is involved.
        for key in ("added_at", "queued_at", "completed_at", "removed_at"):
            try:
                if float(req.get(key) or 0) > 0:
                    return True
            except Exception:
                continue
        return False

    def _waiting_for_add_status_kind(self, req: dict | None) -> str:
        req = req or {}
        state = str(req.get("state") or "").strip().lower()
        try:
            completed_at = int(float(req.get("completed_at") or 0))
            removed_at = int(float(req.get("removed_at") or 0))
        except Exception:
            completed_at = 0
            removed_at = 0
        if state in {"removed", "skipped"} or removed_at > 0:
            return "removed"
        if state in {"completed", "sung"} or completed_at > 0:
            return "sung"
        if state in {"failed", "failed_needs_review"} or str(req.get("last_error") or req.get("attention_reason") or "").strip():
            return "waitlist"
        if state == "waiting" or str(req.get("pending_reason") or "").strip():
            return "waitlist"
        return "active"

    def _waiting_for_add_status_label(self, kind: str) -> str:
        return {
            "active": "Active",
            "pending_acceptance": "Pending Acceptance",
            "waitlist": "Waitlisted",
            "needs_review": "Needs Review",
            "sung": "Sung",
            "removed": "Removed",
        }.get(str(kind or "").strip().lower(), "Active")

    def _waiting_for_add_request_time_text(self, req: dict | None) -> str:
        req = req or {}
        for key in (
            "request_time",
            "requested_at_client",
            "requested_at",
            "created_at",
            "submitted_at",
            "received_at",
            "ts",
            "time",
        ):
            value = req.get(key)
            if value in (None, ""):
                continue
            try:
                if isinstance(value, (int, float)) or str(value).strip().isdigit():
                    stamp = int(float(value))
                    if stamp > 100000:
                        return datetime.fromtimestamp(stamp).strftime("%I:%M %p").lstrip("0")
                    continue
            except Exception:
                pass
            text = str(value).strip()
            if not text:
                continue
            try:
                parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
                return parsed.strftime("%I:%M %p").lstrip("0")
            except Exception:
                return text
        return "Unknown time"

    def _waiting_for_add_server_time_text(self, req: dict | None) -> str:
        req = req or {}
        for key in ("received_at_server", "server_received_at", "received_at", "ts"):
            value = req.get(key)
            if value in (None, ""):
                continue
            text = str(value).strip()
            if not text:
                continue
            try:
                parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
                return parsed.strftime("%I:%M %p").lstrip("0")
            except Exception:
                try:
                    stamp = int(float(text))
                    if stamp > 100000:
                        return datetime.fromtimestamp(stamp).strftime("%I:%M %p").lstrip("0")
                except Exception:
                    pass
                return text
        return "Unknown time"

    def _remote_request_timestamp(self, req: dict | None) -> float:
        req = req or {}
        for key in (
            "received_at_server",
            "server_received_at",
            "waitlisted_at",
            "attention_at",
            "requested_at_client",
            "requested_at",
            "created_at",
            "submitted_at",
            "received_at",
            "request_time",
            "ts",
            "time",
        ):
            value = req.get(key)
            if value in (None, ""):
                continue
            try:
                stamp = float(value)
                if stamp > 1000000000:
                    return stamp
                continue
            except Exception:
                pass
            text = str(value).strip()
            if not text:
                continue
            try:
                return datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
            except Exception:
                continue
        return 0.0

    def _waiting_for_add_stale_cutoff_seconds(self) -> float:
        try:
            hours = float(self.settings.get("waitlist_stale_hours", 24) or 24)
        except Exception:
            hours = 24.0
        return max(1.0, min(168.0, hours)) * 3600.0

    def _is_stale_waiting_for_add_request(self, req: dict | None) -> bool:
        if not isinstance(req, dict) or not self._is_waiting_for_add_request(req):
            return False
        state = str(req.get("state") or "").strip().lower()
        if state in {"accepted", "active", "delivered", "completed", "sung", "removed", "skipped"}:
            return False
        stamp = self._remote_request_timestamp(req)
        if stamp <= 0:
            return False
        return (time.time() - stamp) > self._waiting_for_add_stale_cutoff_seconds()

    def _stale_waiting_for_add_tombstone(self, req: dict) -> dict:
        item = dict(req or {})
        item["state"] = "removed"
        item["removed_at"] = int(time.time())
        item["removed_by"] = "desktop_stale_waitlist_cleanup"
        item["removal_reason"] = "stale_waitlist_startup_cleanup"
        return item

    def _pending_acceptance_enabled(self) -> bool:
        try:
            return bool(self.settings.get("defer_remote_adds_until_between_singers", False))
        except Exception:
            return False

    def _pending_acceptance_rows(self, *, local_ids: set[int] | None = None, identity_sets=None) -> list[dict]:
        if not self._pending_acceptance_enabled():
            return []
        try:
            pending = list(object.__getattribute__(self, "__dict__").get("_deferred_remote_adds", []) or [])
        except Exception:
            pending = []
        if not pending:
            return []
        local_ids = local_ids or set()
        if identity_sets is None:
            accepted_ids, exact_sigs, loose_sigs = self._accepted_request_identity_sets()
            try:
                accepted_ids = set(accepted_ids) - self._deferred_remote_request_ids()
            except Exception:
                accepted_ids = set(accepted_ids)
            identity_sets = (accepted_ids, exact_sigs, loose_sigs)
        rows = []
        for position, item in enumerate(pending, start=1):
            if not isinstance(item, dict):
                continue
            try:
                rid = int(item.get("request_id") or 0)
            except Exception:
                rid = 0
            if rid <= 0 or rid in local_ids:
                continue
            req = dict(item.get("remote_meta") or {})
            req.setdefault("request_id", rid)
            if not req.get("singer"):
                req["singer"] = item.get("singer")
            if not req.get("artist"):
                req["artist"] = item.get("artist")
            if not req.get("title"):
                req["title"] = item.get("title")
            req.setdefault("request_time", item.get("request_time") or item.get("deferred_at"))
            req["queue_position"] = position
            track = item.get("track")
            if isinstance(track, dict):
                if not req.get("artist"):
                    req["artist"] = track.get("artist")
                if not req.get("title"):
                    req["title"] = track.get("title")
                for key in (
                    "selected_version",
                    "selected_brand",
                    "selected_disc_id",
                    "selected_source",
                    "disc_id",
                    "discid",
                    "songid",
                    "song_id",
                    "brand",
                    "source",
                    "version",
                    "duration_secs",
                    "duration",
                    "path",
                ):
                    if not req.get(key) and track.get(key):
                        req[key] = track.get(key)
            if self._request_matches_accepted_queue_item(req, identity_sets=identity_sets):
                continue
            rows.append(self._waiting_for_add_row(req, "pending_acceptance", selectable=False))
        rows.sort(key=self._waiting_for_add_order_key)
        return rows

    def _waiting_for_add_row(self, req: dict, kind: str, *, selectable: bool) -> dict:
        req = dict(req or {})
        replacement = req.get("replacement_track") if isinstance(req.get("replacement_track"), dict) else None
        track = replacement or {}
        artist = str((track.get("artist") if track else "") or req.get("artist") or "").strip() or "Unknown artist"
        title = str((track.get("title") if track else "") or req.get("title") or "").strip() or "Unknown song"
        return {
            "request_id": self._waiting_for_add_request_id(req),
            "singer": str(req.get("singer") or "").strip() or "Unknown singer",
            "artist": artist,
            "title": title,
            "version": self._waiting_for_add_version_text(req),
            "duration": self._waiting_for_add_duration_text(req),
            "first_time_singer": self._is_first_time_waitlist_singer(str(req.get("singer") or "")),
            "request_time": self._waiting_for_add_request_time_text(req),
            "server_received_time": self._waiting_for_add_server_time_text(req),
            "queue_position": req.get("queue_position"),
            "status_kind": "needs_review" if str(req.get("state") or "").strip().lower() == "failed_needs_review" else str(kind or "active"),
            "status_label": self._waiting_for_add_status_label(
                "needs_review" if str(req.get("state") or "").strip().lower() == "failed_needs_review" else kind
            ),
            "selectable": bool(selectable),
            "request": req,
        }

    def _format_waiting_duration(self, value) -> str:
        try:
            if value in (None, ""):
                return ""
            seconds = int(float(value))
            if seconds <= 0:
                return ""
            return f"{seconds // 60}:{seconds % 60:02d}"
        except Exception:
            text = str(value or "").strip()
            return text

    def _waiting_for_add_version_text(self, req: dict | None) -> str:
        req = req or {}
        replacement = req.get("replacement_track") if isinstance(req.get("replacement_track"), dict) else None
        source = "Replacement" if replacement else "Requested"
        track = replacement or req
        pieces = []
        for key in (
            "selected_version",
            "selected_brand",
            "selected_disc_id",
            "selected_source",
            "disc_id",
            "discid",
            "songid",
            "song_id",
            "brand",
            "source",
            "version",
        ):
            value = str(track.get(key) or "").strip()
            if value and value.lower() not in {"unknown", "none"} and value not in pieces:
                pieces.append(value)
        path = str(track.get("path") or "").strip()
        if path:
            ext = os.path.splitext(path)[1].strip(".").upper()
            if ext and ext not in pieces:
                pieces.append(ext)
        if pieces:
            return f"{source}: {' / '.join(pieces[:3])}"
        return source

    def _waiting_for_add_duration_text(self, req: dict | None) -> str:
        req = req or {}
        replacement = req.get("replacement_track") if isinstance(req.get("replacement_track"), dict) else None
        for source in (replacement, req):
            if not isinstance(source, dict):
                continue
            for key in ("duration_secs", "duration", "length_secs", "len_secs"):
                text = self._format_waiting_duration(source.get(key))
                if text:
                    return text
        return "Length unknown"

    def _has_singer_sung_current_show(self, singer_name: str) -> bool:
        key = self._queue_limit_name_key(singer_name)
        if not key:
            return False
        try:
            queue = object.__getattribute__(self, "__dict__").get("queue", [])
        except Exception:
            queue = []
        for singer in queue or []:
            if not isinstance(singer, dict):
                continue
            if self._queue_limit_name_key(singer.get("name", "")) == key and bool(singer.get("has_sung", False)):
                return True
        return False

    def _is_first_time_waitlist_singer(self, singer_name: str) -> bool:
        primary, _duet_display = self._parse_duet_singer(str(singer_name or ""))
        name = primary or singer_name
        return bool(str(name or "").strip()) and not self._has_singer_sung_current_show(name)

    def _waiting_for_add_order_key(self, row: dict) -> tuple:
        req = row.get("request") if isinstance(row, dict) else None
        if not isinstance(req, dict):
            req = {}
        raw_value = None
        for key in ("received_at_server", "request_time", "requested_at_client", "requested_at", "created_at", "submitted_at", "received_at", "ts", "time"):
            value = req.get(key)
            if value not in (None, ""):
                raw_value = value
                break
        order_value = float("inf")
        if raw_value not in (None, ""):
            try:
                order_value = float(raw_value)
            except Exception:
                text = str(raw_value).strip()
                try:
                    order_value = datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
                except Exception:
                    order_value = float("inf")
        return (order_value, row.get("request_id") or 0)

    def _waiting_for_add_sections(self) -> list[dict]:
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            state = {}
        try:
            local_ids = set(int(v) for v in (self._queue_remote_request_ids() or []))
        except Exception:
            local_ids = set()
        identity_sets = self._accepted_request_identity_sets()
        try:
            deferred_ids = self._deferred_remote_request_ids()
        except Exception:
            deferred_ids = set()
        pending_identity_sets = (set(identity_sets[0]) - set(deferred_ids), identity_sets[1], identity_sets[2])

        sections = []
        pending_acceptance_rows = self._pending_acceptance_rows(local_ids=local_ids, identity_sets=pending_identity_sets)
        if pending_acceptance_rows:
            sections.append({
                "key": "pending_acceptance",
                "title": "Pending Acceptance",
                "rows": pending_acceptance_rows,
                "helper": "These requests will automatically be added when the current song finishes.",
            })

        pending = state.get("_waiting_for_add_requests", {})
        if not isinstance(pending, dict):
            pending = {}
        wait_rows = []
        for rid, req in pending.items():
            try:
                rid_int = int(rid)
            except Exception:
                continue
            if rid_int <= 0 or rid_int in local_ids or self._request_matches_accepted_queue_item(req, identity_sets=identity_sets):
                continue
            wait_rows.append(self._waiting_for_add_row(req, "waitlist", selectable=True))
        wait_rows.sort(key=self._waiting_for_add_order_key)
        if wait_rows:
            sections.append({"key": "waitlist", "title": "Waitlist", "rows": wait_rows})
        if bool(state.get("_waiting_for_add_show_removed", False)):
            removed_rows = []
            removed = state.get("_waiting_for_add_removed_tonight", {})
            if isinstance(removed, dict):
                for req in removed.values():
                    if isinstance(req, dict):
                        removed_rows.append(self._waiting_for_add_row(req, "removed", selectable=True))
            removed_rows.sort(
                key=lambda row: float((row.get("request") or {}).get("removed_at") or 0),
                reverse=True,
            )
            if removed_rows:
                sections.append({"key": "removed", "title": "Removed Tonight", "rows": removed_rows})
        return sections

    def _waiting_for_add_row_text(self, row: dict) -> str:
        singer = row.get("singer") or "Unknown singer"
        title = row.get("title") or "Unknown song"
        artist = row.get("artist") or "Unknown artist"
        request_time = row.get("request_time") or "Unknown time"
        server_received_time = row.get("server_received_time") or "Unknown time"
        version = row.get("version") or "Requested"
        duration = row.get("duration") or "Length unknown"
        status = row.get("status_label") or "Pending"
        if row.get("first_time_singer"):
            status = f"{status} - First turn"
        queue_position = row.get("queue_position")
        queue_text = ""
        try:
            if queue_position not in (None, "") and int(queue_position) > 0:
                queue_text = f"    Queue: #{int(queue_position)}"
        except Exception:
            queue_text = ""
        return (
            f"Singer: {singer}    Status: {status}{queue_text}\n"
            f"Song: {title}    Artist: {artist}\n"
            f"Version: {version}    Length: {duration}    Requested: {request_time}    Server: {server_received_time}"
        )

    def _upsert_waiting_for_add_request(self, req: dict | None, reason: str = "", *, force_visible: bool = False) -> None:
        if not isinstance(req, dict):
            return
        if not self._is_waitlist_enabled_cached() and not force_visible:
            _diag(f"[WAITING-FOR-ADD] ignored upsert because waitlist disabled reason={reason!r}")
            return
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return
        if self._remote_request_is_non_actionable(req):
            _diag(
                "[WAITING-FOR-ADD] ignored non-actionable upsert "
                f"request_id={rid} singer={str(req.get('singer') or '')!r} title={str(req.get('title') or '')!r} "
                f"state={str(req.get('state') or req.get('status') or '')!r} sent={int(bool(req.get('sent') or req.get('delivered')))} "
                f"reason={reason!r}"
            )
            return
        handled = state.get("_waiting_for_add_handled_ids", set())
        if not isinstance(handled, set):
            handled = set()
            self._waiting_for_add_handled_ids = handled
        elif "_waiting_for_add_handled_ids" not in state:
            self._waiting_for_add_handled_ids = handled
        if isinstance(handled, set) and rid in handled:
            return
        if self._request_matches_accepted_queue_item(req):
            self._mark_waiting_for_add_duplicate_accepted(req, reason=f"upsert:{reason or 'waitlist'}")
            return
        if self._is_stale_waiting_for_add_request(req):
            handled.add(rid)
            try:
                self._cleanup_terminal_removed_requests({rid: self._stale_waiting_for_add_tombstone(req)})
            except Exception:
                pass
            _diag(f"[WAITING-FOR-ADD] stale past-show request ignored request_id={rid} reason={reason!r}")
            return
        item = dict(req)
        if reason and not item.get("pending_reason") and not item.get("attention_reason"):
            item["attention_reason"] = str(reason)
        pending = state.get("_waiting_for_add_requests")
        if not isinstance(pending, dict):
            pending = {}
            self._waiting_for_add_requests = pending
        existed = rid in pending
        pending[rid] = item
        _diag(
            "[WAITING-FOR-ADD] upsert "
            f"request_id={rid} singer={str(item.get('singer') or '')!r} title={str(item.get('title') or '')!r} "
            f"source={str(item.get('request_source') or item.get('source') or '')!r} state={str(item.get('state') or '')!r} "
            f"action={'updated' if existed else 'created'} reason={reason!r} pending_count={len(pending)}"
        )
        self._schedule_waiting_for_add_view_refresh(reason="upsert")

    def _set_waiting_for_add_requests(self, reqs, *, local_remote_ids=None) -> None:
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return
        handled = state.get("_waiting_for_add_handled_ids", set())
        if not isinstance(handled, set):
            handled = set()
            self._waiting_for_add_handled_ids = handled
        elif "_waiting_for_add_handled_ids" not in state:
            self._waiting_for_add_handled_ids = handled
        if not self._is_waitlist_enabled_cached():
            # Auto-accept mode: server-driven waitlist entries go away, but
            # locally recorded failures (attention_reason set) must survive —
            # they are the host's only trace of requests that could not be
            # auto-added.
            existing = state.get("_waiting_for_add_requests") or {}
            kept = {
                rid: item for rid, item in existing.items()
                if isinstance(item, dict) and str(item.get("attention_reason") or "").strip()
            }
            if len(kept) != len(existing):
                _diag(
                    "[WAITING-FOR-ADD] cleared server waitlist entries because waitlist disabled "
                    f"(kept {len(kept)} failed-auto-accept entr{'y' if len(kept) == 1 else 'ies'})"
                )
            self._waiting_for_add_requests = kept
            self._waiting_for_add_recent_terminal_requests = {}
            self._schedule_waiting_for_add_view_refresh(reason="waitlist_disabled")
            return
        try:
            local_ids = set(int(v) for v in (local_remote_ids or self._queue_remote_request_ids() or []))
        except Exception:
            local_ids = set()
        identity_sets = self._accepted_request_identity_sets()
        candidates = {}
        terminal_items = {}
        for req in reqs or []:
            if not isinstance(req, dict):
                continue
            # A rename-merge may have retired this request's singer name this
            # session; map it so the sync can't resurrect the duplicate.
            req = self._alias_mapped_request(req)
            rid = self._waiting_for_add_request_id(req)
            if rid <= 0:
                continue
            try:
                completed_at = int(float(req.get("completed_at") or 0))
                removed_at = int(float(req.get("removed_at") or 0))
            except Exception:
                completed_at = 0
                removed_at = 0
            state_name = str(req.get("state") or "").strip().lower()
            if state_name in {"removed", "skipped", "completed", "sung"} or completed_at > 0 or removed_at > 0:
                if rid not in local_ids:
                    terminal_items[rid] = dict(req)
                continue
            if self._remote_request_is_non_actionable(req):
                handled.add(rid)
                # Every reconcile re-walks the same non-actionable rows, so
                # logging one line each pass produced 1435 identical lines in a
                # single show. Say it once per request/state, matching the
                # [REMOTE-SYNC] historical handling.
                # __dict__ access: getattr on a half-built QWidget raises.
                _wfa_state = object.__getattribute__(self, "__dict__")
                logged_non_actionable = _wfa_state.get("_wfa_logged_non_actionable")
                if not isinstance(logged_non_actionable, set):
                    logged_non_actionable = set()
                    _wfa_state["_wfa_logged_non_actionable"] = logged_non_actionable
                if (rid, state_name) not in logged_non_actionable:
                    logged_non_actionable.add((rid, state_name))
                    _diag(
                        "[WAITING-FOR-ADD] ignored accepted/delivered server row "
                        f"request_id={rid} singer={str(req.get('singer') or '')!r} title={str(req.get('title') or '')!r} "
                        f"state={state_name!r} sent={int(bool(req.get('sent') or req.get('delivered')))}"
                    )
                continue
            if state_name in {"waiting", "failed", "failed_needs_review"} and bool(req.get("sent") or req.get("delivered")):
                _diag(
                    "[WAITING-FOR-ADD] lifecycle/transport conflict retained "
                    f"request_id={rid} state={state_name!r} sent={int(bool(req.get('sent')))} "
                    f"delivered={int(bool(req.get('delivered')))} action=keep_waitlisted"
                )
            if not self._is_waiting_for_add_request(req):
                continue
            if rid in local_ids:
                handled.add(rid)
                continue
            if rid in handled:
                continue
            if self._request_matches_accepted_queue_item(req, identity_sets=identity_sets):
                self._mark_waiting_for_add_duplicate_accepted(req, reason="set_requests")
                continue
            if self._is_stale_waiting_for_add_request(req):
                handled.add(rid)
                terminal_items[rid] = self._stale_waiting_for_add_tombstone(req)
                _diag(f"[WAITING-FOR-ADD] stale past-show request queued for purge request_id={rid}")
                continue
            candidates[rid] = dict(req)
        try:
            for rid, req in state.get("_remote_attention_requests", {}).items():
                rid = int(rid)
                if rid <= 0 or rid in handled or rid in local_ids or self._request_matches_accepted_queue_item(req, identity_sets=identity_sets):
                    continue
                if self._is_stale_waiting_for_add_request(req):
                    handled.add(rid)
                    terminal_items[rid] = self._stale_waiting_for_add_tombstone(req)
                    _diag(f"[WAITING-FOR-ADD] stale local attention request queued for purge request_id={rid}")
                    continue
                if rid > 0:
                    candidates.setdefault(rid, dict(req))
        except Exception:
            pass
        try:
            self._cleanup_duplicate_singer_songs(reason="waitlist_rebuild_precheck")
        except Exception:
            pass
        items = {}

        def candidate_order(pair):
            rid, req = pair
            row = {"request_id": rid, "request": req}
            return self._waiting_for_add_order_key(row)

        for rid, req in sorted(candidates.items(), key=candidate_order):
            items[rid] = dict(req)
            if str(req.get("pending_reason") or "").strip().lower() == "singer_limit_waitlist":
                _diag(
                    "[WAITING-FOR-ADD] retained singer-limit waitlist entry "
                    f"request_id={rid} singer={str(req.get('singer') or '')!r} action=await_host"
                )
        self._waiting_for_add_requests = items
        self._waiting_for_add_recent_terminal_requests = terminal_items
        _diag(
            "[WAITING-FOR-ADD] rebuilt "
            f"pending_count={len(items)} terminal_count={len(terminal_items)} candidate_count={len(candidates)}"
        )
        try:
            self._cleanup_terminal_removed_requests(terminal_items)
        except Exception:
            pass
        self._cleanup_accepted_waiting_for_add_requests(reason="set_requests_final")
        self._schedule_waiting_for_add_view_refresh(reason="set_requests")

    def _refresh_waiting_for_add_view(self):
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return
        _perf_t0 = time.perf_counter()
        sections = self._waiting_for_add_sections()

        current_id = 0
        try:
            model = getattr(self, "waiting_for_add_model", None)
            view = getattr(self, "waiting_for_add_list", None)
            if model is not None and view is not None:
                current_id = int(model.requestIdForIndex(view.currentIndex()) or 0)
        except Exception:
            current_id = 0

        waiting_list = state.get("waiting_for_add_list")
        waiting_model = state.get("waiting_for_add_model")
        if waiting_list is not None and waiting_model is not None:
            colors = {
                "pending_acceptance": QColor("#bae6fd"),
                "waitlist": QColor("#e2e8f0"),
                "needs_review": QColor("#86efac"),
                "sung": QColor("#c4b5fd"),
                "removed": QColor("#fca5a5"),
            }
            header_colors = {
                "pending_acceptance": (QColor("#7dd3fc"), QColor(14, 165, 233, 42)),
                "waitlist": (QColor("#e2e8f0"), QColor(71, 85, 105, 36)),
                "completed": (QColor("#c4b5fd"), QColor(124, 58, 237, 30)),
                "removed": (QColor("#fca5a5"), QColor(220, 38, 38, 28)),
            }
            render_limit = 120 if bool(getattr(self, "karaoke_playing", False)) else 300
            rendered = 0
            total_rows = 0
            model_rows = []
            for section in sections:
                rows = section.get("rows") or []
                if not rows:
                    continue
                total_rows += len(rows)
                header_fg, header_bg = header_colors.get(section.get("key"), (QColor("#e2e8f0"), QColor(51, 65, 85, 32)))
                model_rows.append({
                    "text": f"{section.get('title') or 'Requests'} ({len(rows)})",
                    "request_id": 0,
                    "selectable": False,
                    "foreground": header_fg,
                    "background": header_bg,
                    "height": 38,
                })
                for row in rows:
                    if rendered >= render_limit:
                        continue
                    rid = int(row.get("request_id") or 0)
                    tooltip = (
                        f"Singer: {row.get('singer')}\n"
                        f"Song: {row.get('title')}\n"
                        f"Artist: {row.get('artist')}\n"
                        f"Version: {row.get('version')}\n"
                        f"Length: {row.get('duration')}\n"
                        f"Request Time: {row.get('request_time')}\n"
                        f"Server Received: {row.get('server_received_time')}\n"
                        f"Status: {row.get('status_label')}"
                        + (f"\nQueue Position: #{int(row.get('queue_position'))}" if str(row.get("queue_position") or "").isdigit() else "")
                        + ("\nFirst turn this show" if row.get("first_time_singer") else "")
                    )
                    status_kind = str(row.get("status_kind") or "")
                    row_bg = QColor(22, 101, 52, 42) if row.get("first_time_singer") else None
                    if status_kind == "needs_review":
                        pulse = self._waiting_for_add_pulse_value()
                        row_bg = QColor(22, 163, 74, int(42 + 54 * pulse))
                    model_rows.append({
                        "text": self._waiting_for_add_row_text(row),
                        "request_id": rid,
                        "selectable": bool(row.get("selectable")),
                        "foreground": colors.get(status_kind, QColor("#e2e8f0")),
                        "background": row_bg,
                        "tooltip": tooltip,
                        "height": 76,
                    })
                    rendered += 1
            if not model_rows:
                model_rows.append({
                    "text": "No pending or waitlisted requests.",
                    "request_id": 0,
                    "selectable": False,
                    "foreground": QColor("#64748b"),
                    "height": 44,
                })
            if total_rows > rendered:
                model_rows.append({
                    "text": f"Showing {rendered} of {total_rows} requests.",
                    "request_id": 0,
                    "selectable": False,
                    "foreground": QColor("#94a3b8"),
                    "height": 44,
                })
            try:
                waiting_model.setRows(model_rows)
                target = waiting_model.indexForRequestId(current_id)
                if not target.isValid():
                    target = waiting_model.firstSelectableIndex()
                if target.isValid():
                    waiting_list.setCurrentIndex(target)
                else:
                    waiting_list.clearSelection()
            except Exception:
                pass

        pending_section = next((s for s in sections if s.get("key") == "pending_acceptance"), {"rows": []})
        pending_count = len(pending_section.get("rows") or [])
        pending_enabled = self._pending_acceptance_enabled()
        pending_panel = state.get("pending_acceptance_panel")
        if pending_panel is not None:
            pending_panel.setVisible(bool(pending_enabled and pending_count > 0))
        pending_badge = state.get("pending_acceptance_badge_label")
        if pending_badge is not None:
            pending_badge.setText(str(pending_count))
        pending_helper = state.get("pending_acceptance_helper_label")
        if pending_helper is not None:
            pending_helper.setVisible(bool(pending_enabled and pending_count > 0))
        pending_button = state.get("deferred_remote_add_now_button")
        if pending_button is not None:
            pending_button.setVisible(bool(pending_enabled and pending_count > 0))
            pending_button.setEnabled(bool(pending_count > 0))
            pending_button.setToolTip("Accept all pending requests now")

        wait_section = next((s for s in sections if s.get("key") == "waitlist"), {"rows": []})
        count = len(wait_section.get("rows") or [])
        removed_count = len(state.get("_waiting_for_add_removed_tonight", {}) or {})
        removed_toggle = state.get("waiting_for_add_removed_toggle")
        if removed_toggle is not None:
            removed_toggle.setText(f"Removed Tonight ({removed_count})")
            removed_toggle.setEnabled(removed_count > 0)
        meta_label = state.get("waiting_for_add_meta_label")
        if meta_label is not None:
            if pending_count and count:
                meta_label.setText(f"{pending_count} pending • {count} waiting")
            elif pending_count:
                meta_label.setText(f"{pending_count} pending")
            else:
                meta_label.setText("Clear" if count == 0 else f"{count} waiting")
        clear_all_button = state.get("waiting_for_add_clear_all_button")
        if clear_all_button is not None:
            clear_all_button.setEnabled(count > 0)
            clear_all_button.setToolTip("Remove all waitlisted songs" if count > 0 else "No waitlisted songs to clear")
        detail_label = state.get("waiting_for_add_detail_label")
        if count == 0 and detail_label is not None:
            detail_label.setText("No waitlisted songs.")
        self._update_waiting_for_add_nav_state()
        self._on_waiting_for_add_selection_changed()
        try:
            elapsed_ms = (time.perf_counter() - _perf_t0) * 1000.0
            if bool(getattr(self, "karaoke_playing", False)) and elapsed_ms >= 20.0:
                _diag(f"[PERF] waitlist_refresh_during_playback ms={elapsed_ms:.1f}")
            else:
                _perf_log_if_slow("waitlist_refresh", elapsed_ms)
        except Exception:
            pass

    def _waiting_for_add_clearable_requests(self) -> list[dict]:
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            state = {}
        pending = state.get("_waiting_for_add_requests", {})
        if not isinstance(pending, dict):
            return []
        try:
            local_ids = set(int(v) for v in (self._queue_remote_request_ids() or []))
        except Exception:
            local_ids = set()
        identity_sets = self._accepted_request_identity_sets()
        clearable = []
        for rid, req in pending.items():
            try:
                rid_int = int(rid)
            except Exception:
                continue
            if rid_int <= 0 or rid_int in local_ids:
                continue
            if self._request_matches_accepted_queue_item(req, identity_sets=identity_sets):
                continue
            item = dict(req or {})
            item["request_id"] = rid_int
            clearable.append(item)
        clearable.sort(key=lambda req: self._waiting_for_add_order_key({
            "request": req,
            "request_id": self._waiting_for_add_request_id(req),
        }))
        return clearable

    def _selected_waiting_for_add_request(self) -> dict | None:
        try:
            state = object.__getattribute__(self, "__dict__")
            waiting_list = state.get("waiting_for_add_list")
            waiting_model = state.get("waiting_for_add_model")
            if waiting_list is None:
                return None
            index = waiting_list.currentIndex()
            if waiting_model is None or not index.isValid():
                return None
            rid = int(waiting_model.requestIdForIndex(index) or 0)
            req = getattr(self, "_waiting_for_add_requests", {}).get(rid)
            if req is None:
                req = getattr(self, "_waiting_for_add_removed_tonight", {}).get(rid)
            return req
        except Exception:
            return None

    def _on_waiting_for_add_selection_changed(self, *_args):
        req = self._selected_waiting_for_add_request()
        enabled = req is not None
        is_removed = bool(req and req.get("_removed_tonight"))
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            state = {}
        try:
            add_button = state.get("waiting_for_add_add_button")
            find_button = state.get("waiting_for_add_find_button")
            clear_button = state.get("waiting_for_add_clear_button")
            clear_all_button = state.get("waiting_for_add_clear_all_button")
            if add_button is not None:
                add_button.setEnabled(enabled and not is_removed)
            if find_button is not None:
                find_button.setEnabled(enabled and not is_removed)
            if clear_button is not None:
                clear_button.setEnabled(enabled)
                clear_button.setText("Restore" if is_removed else "Remove")
            if clear_all_button is not None:
                clear_all_button.setEnabled(self._waiting_for_add_count() > 0)
        except Exception:
            pass
        detail_label = state.get("waiting_for_add_detail_label")
        if detail_label is None:
            return
        if not req:
            detail_label.setText("No waitlisted songs.")
            return
        singer = str(req.get("singer") or "").strip() or "Unknown singer"
        artist = str(req.get("artist") or "").strip()
        title = str(req.get("title") or "").strip()
        song = " - ".join([v for v in (artist, title) if v]) or "Unknown song"
        version = self._waiting_for_add_version_text(req)
        duration = self._waiting_for_add_duration_text(req)
        server_received = self._waiting_for_add_server_time_text(req)
        detail = (
            "Removed tonight — select Restore to return it to the waitlist"
            if is_removed else self._waiting_for_add_reason_text(req)
        )
        err = str(req.get("last_error") or req.get("attention_error") or "").strip()
        if err and err != detail:
            detail = f"{detail}. {err}"
        detail_label.setText(f"{singer}: {song}\n{version} • {duration} • Server {server_received}\n{detail}")

    def _show_waiting_for_add_context_menu(self, position):
        waiting_list = getattr(self, "waiting_for_add_list", None)
        waiting_model = getattr(self, "waiting_for_add_model", None)
        if waiting_list is None:
            return
        index = waiting_list.indexAt(position)
        if waiting_model is None or not index.isValid():
            return
        try:
            rid = int(waiting_model.requestIdForIndex(index) or 0)
        except Exception:
            rid = 0
        if rid <= 0:
            return
        waiting_list.setCurrentIndex(index)
        req = self._selected_waiting_for_add_request()
        if not req:
            return
        menu = QMenu(self)
        style_app_menu(menu)
        if req.get("_removed_tonight"):
            restore_action = menu.addAction("Restore to waitlist")
            restore_action.triggered.connect(self._restore_selected_waiting_for_add)
            menu.exec(waiting_list.viewport().mapToGlobal(position))
            return
        version_action = menu.addAction("Replace with another karaoke version")
        version_action.triggered.connect(lambda: self._find_song_for_selected_waiting_for_add(mode="replace_version"))
        song_action = menu.addAction("Replace with a different song")
        song_action.triggered.connect(lambda: self._find_song_for_selected_waiting_for_add(mode="replace_song"))
        menu.addSeparator()
        edit_action = menu.addAction("Edit singer/name/song metadata...")
        edit_action.triggered.connect(self._edit_selected_waiting_for_add_metadata)
        menu.addSeparator()
        remove_action = menu.addAction("Remove from waitlist")
        remove_action.triggered.connect(self._clear_selected_waiting_for_add)
        menu.exec(waiting_list.viewport().mapToGlobal(position))

    def _add_selected_waiting_for_add(self):
        req = self._selected_waiting_for_add_request()
        if not req:
            return
        if req.get("_removed_tonight"):
            self._restore_selected_waiting_for_add()
            return
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return
        replacement = req.get("replacement_track") if isinstance(req.get("replacement_track"), dict) else None
        if replacement:
            try:
                if self._add_waiting_for_add_track(req, replacement):
                    return
            except Exception as e:
                try:
                    QMessageBox.warning(self, "Waiting for Add", str(e))
                except Exception:
                    pass
                return
        ok = False
        try:
            ok = bool(self.process_external_request(dict(req)))
        except Exception as e:
            ok = False
            _diag(f"[WAITING-FOR-ADD] add failed request_id={rid}: {e}")
        if not ok:
            try:
                QMessageBox.warning(self, "Waiting for Add", "That song could not be added from the local library.")
            except Exception:
                pass
            return
        try:
            self._waiting_for_add_handled_ids.add(rid)
        except Exception:
            self._waiting_for_add_handled_ids = {rid}
        try:
            self._mark_waiting_for_add_delivered_async(rid, req)
        except Exception:
            pass
        try:
            getattr(self, "_waiting_for_add_requests", {}).pop(rid, None)
        except Exception:
            pass
        self._schedule_waiting_for_add_view_refresh(reason="add_now")
        self._show_processing_notification("Added waiting request to rotation.", level="success")

    def _update_waiting_for_add_request(self, rid: int, updates: dict) -> dict | None:
        try:
            rid = int(rid or 0)
        except Exception:
            rid = 0
        if rid <= 0:
            return None
        pending = getattr(self, "_waiting_for_add_requests", None)
        if not isinstance(pending, dict) or rid not in pending:
            return None
        req = dict(pending.get(rid) or {})
        req.update(updates or {})
        req["request_id"] = rid
        pending[rid] = req
        try:
            attention = getattr(self, "_remote_attention_requests", None)
            if isinstance(attention, dict) and rid in attention:
                attention[rid] = dict(req)
        except Exception:
            pass
        self._schedule_waiting_for_add_view_refresh(reason="update_request")
        return req

    def _replace_waiting_for_add_track(self, req: dict, track: dict, *, source: str = "waiting_replace") -> bool:
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0 or not isinstance(track, dict):
            return False
        old_artist = str(req.get("artist") or "").strip()
        old_title = str(req.get("title") or "").strip()
        undo = KaraokeApp._begin_undoable_action(self, "Replace Song")
        artist = str(track.get("artist") or old_artist).strip()
        title = str(track.get("title") or old_title).strip()
        replacement = dict(track)
        replacement.setdefault("artist", artist)
        replacement.setdefault("title", title)
        updated = self._update_waiting_for_add_request(rid, {
            "artist": artist,
            "title": title,
            "replacement_track": replacement,
            "attention_reason": "host_replaced_waitlist_track",
            "pending_status": "Replacement selected",
        })
        if updated is None:
            return False
        try:
            entry = self._build_queue_entry_from_track_choice({
                "remote_request_id": rid,
                "key": int(updated.get("key") or 0),
                "tempo_percent": 100 + int(updated.get("tempo") or 0),
            }, replacement)
            entry["remote_request_id"] = rid
            self._push_remote_request_replacement(
                entry,
                singer_name=str(updated.get("singer") or ""),
                old_artist=old_artist,
                old_title=old_title,
                source=source,
            )
        except Exception:
            pass
        self._show_processing_notification("Waitlist replacement selected.", level="success")
        KaraokeApp._commit_undoable_action(self, undo, "Waitlist song replaced")
        return True

    def _waiting_for_add_song_data_from_track(self, req: dict, track: dict):
        path = str((track or {}).get("path") or "").strip()
        if not path:
            raise ValueError("Selected track has no valid path.")
        try:
            key = int((req or {}).get("key") or (req or {}).get("key_change") or 0)
        except Exception:
            key = 0
        try:
            tempo_offset = int((req or {}).get("tempo") or 0)
        except Exception:
            tempo_offset = 0
        tempo_percent = max(70, min(130, 100 + tempo_offset))
        low = path.lower()
        if low.endswith(".cdg"):
            mp3_path = self._find_mp3_pair_for_cdg(path)
            if not mp3_path:
                raise FileNotFoundError(f"Matching MP3 not found for CDG:\n{path}")
            return ((path, mp3_path), key, tempo_percent)
        if low.endswith(".zip") and not self.is_mp3g_zip(path):
            raise ValueError(f"ZIP must contain exactly one CDG and one MP3:\n{path}")
        return (path, key, tempo_percent)

    def _add_waiting_for_add_track(self, req: dict, track: dict) -> bool:
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return False
        singer = str((req or {}).get("singer") or "").strip()
        if not singer:
            raise ValueError("Waiting request has no singer name.")
        check_req = dict(req or {})
        if isinstance(track, dict):
            check_req["replacement_track"] = dict(track)
            check_req.setdefault("artist", track.get("artist"))
            check_req.setdefault("title", track.get("title"))
            for key in (
                "song_key",
                "stable_request_key",
                "selected_version",
                "selected_brand",
                "selected_disc_id",
                "selected_source",
                "disc_id",
                "discid",
                "songid",
                "song_id",
                "brand",
                "version",
                "source",
            ):
                if not check_req.get(key) and track.get(key):
                    check_req[key] = track.get(key)
        if self._request_matches_accepted_queue_item(check_req):
            self._mark_waiting_for_add_duplicate_accepted(req, reason="add_track")
            self._schedule_waiting_for_add_view_refresh(reason="add_track_duplicate")
            self._show_processing_notification("That request is already in the singer's queue.", level="info")
            return True
        song_data = self._waiting_for_add_song_data_from_track(req, track)
        ok = bool(self._add_song_to_queue(singer, song_data, track=track, remote_meta=req))
        if not ok:
            return False
        try:
            primary, _duet = self._parse_duet_singer(singer)
            target_key = self._queue_limit_name_key(primary or singer)
            for idx, queue_singer in enumerate(self.queue or []):
                if self._queue_limit_name_key((queue_singer or {}).get("name", "")) == target_key:
                    self._sync_remote_singer_order(idx, reason="host_add_waitlist_song")
                    break
        except Exception:
            pass
        try:
            self._waiting_for_add_handled_ids.add(rid)
        except Exception:
            self._waiting_for_add_handled_ids = {rid}
        try:
            self._mark_waiting_for_add_delivered_async(rid, req)
        except Exception:
            pass
        try:
            getattr(self, "_waiting_for_add_requests", {}).pop(rid, None)
        except Exception:
            pass
        try:
            self._cleanup_accepted_waiting_for_add_requests(reason="add_track")
        except Exception:
            pass
        self._schedule_waiting_for_add_view_refresh(reason="add_track")
        self._show_processing_notification("Added selected song to rotation.", level="success")
        return True

    def _edit_selected_waiting_for_add_metadata(self):
        req = self._selected_waiting_for_add_request()
        if not req:
            return
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return

        dlg = QDialog(self)
        dlg.setWindowTitle("Edit Waitlist Request")
        dlg.setMinimumWidth(420)
        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            dlg.setStyleSheet(dialog_stylesheet(win, base, txtc))
        except Exception:
            pass

        layout = QVBoxLayout(dlg)
        summary = QLabel("Edit the pending request without changing its waitlist position.")
        summary.setWordWrap(True)
        summary.setStyleSheet(f"color:{_v('text_soft')}; font-weight:700;")
        layout.addWidget(summary)

        form = QGridLayout()
        form.setHorizontalSpacing(10)
        form.setVerticalSpacing(8)

        singer_edit = QLineEdit(str(req.get("singer") or ""), dlg)
        artist_edit = QLineEdit(str(req.get("artist") or ""), dlg)
        title_edit = QLineEdit(str(req.get("title") or ""), dlg)
        key_spin = QSpinBox(dlg)
        key_spin.setRange(-12, 12)
        try:
            key_spin.setValue(int(req.get("key") or req.get("key_change") or 0))
        except Exception:
            key_spin.setValue(0)
        tempo_spin = QSpinBox(dlg)
        tempo_spin.setRange(-30, 30)
        try:
            tempo_spin.setValue(int(req.get("tempo") or 0))
        except Exception:
            tempo_spin.setValue(0)

        rows = [
            ("Singer", singer_edit),
            ("Song title", title_edit),
            ("Artist", artist_edit),
            ("Key", key_spin),
            ("Tempo", tempo_spin),
        ]
        for row, (label_text, widget) in enumerate(rows):
            label = QLabel(label_text, dlg)
            label.setStyleSheet(f"color:{_v('text_soft')}; font-weight:700;")
            form.addWidget(label, row, 0)
            form.addWidget(widget, row, 1)
        layout.addLayout(form)

        buttons = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel,
            parent=dlg,
        )
        try:
            buttons.button(QDialogButtonBox.StandardButton.Ok).setText("Save")
        except Exception:
            pass
        layout.addWidget(buttons)

        def save_changes():
            singer = str(singer_edit.text() or "").strip()
            title = str(title_edit.text() or "").strip()
            artist = str(artist_edit.text() or "").strip()
            if not singer or not title:
                QMessageBox.warning(dlg, "Waitlist Request", "Singer and song title are required.")
                return
            updated = self._update_waiting_for_add_request(rid, {
                "singer": singer,
                "artist": artist,
                "title": title,
                "key": int(key_spin.value()),
                "tempo": int(tempo_spin.value()),
                "attention_reason": "host_edited_waitlist_metadata",
                "pending_status": "Metadata edited",
            })
            if updated is None:
                return
            try:
                replacement = updated.get("replacement_track") if isinstance(updated.get("replacement_track"), dict) else None
                if replacement:
                    entry = self._build_queue_entry_from_track_choice({
                        "remote_request_id": rid,
                        "key": int(updated.get("key") or 0),
                        "tempo_percent": 100 + int(updated.get("tempo") or 0),
                    }, replacement)
                else:
                    entry = {
                        "remote_request_id": rid,
                        "artist": artist,
                        "title": title,
                        "key": int(updated.get("key") or 0),
                        "tempo_percent": 100 + int(updated.get("tempo") or 0),
                    }
                entry["remote_request_id"] = rid
                self._push_remote_request_replacement(
                    entry,
                    singer_name=singer,
                    old_artist=str(req.get("artist") or ""),
                    old_title=str(req.get("title") or ""),
                    source="waiting_metadata_edit",
                )
            except Exception:
                pass
            self._show_processing_notification("Waitlist request updated.", level="success")
            dlg.accept()

        buttons.accepted.connect(save_changes)
        buttons.rejected.connect(dlg.reject)
        dlg.exec()

    def _find_song_for_selected_waiting_for_add(self, mode: str = "add"):
        req = self._selected_waiting_for_add_request()
        if not req:
            return
        mode = str(mode or "add")
        singer = str(req.get("singer") or "").strip() or "Unknown singer"
        old_artist = str(req.get("artist") or "").strip()
        old_title = str(req.get("title") or "").strip()
        old_label = f"{old_artist} - {old_title}".strip(" -") or "waiting request"
        replacing = mode in {"replace_version", "replace_song"}
        same_song = mode == "replace_version"

        dlg = QDialog(self)
        if same_song:
            dlg.setWindowTitle("Replace Waitlist Version")
        elif replacing:
            dlg.setWindowTitle("Replace Waitlist Song")
        else:
            dlg.setWindowTitle("Find Song for Waiting Request")
        dlg.setMinimumSize(560, 340)
        try:
            sz = (self.settings or {}).get("waiting_find_song_dialog_size") or {}
            dlg.resize(max(560, int(sz.get("w", 900))), max(340, int(sz.get("h", 540))))
        except Exception:
            dlg.resize(900, 540)
        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            border = base.darker(120)
            field_bg = base.darker(105)
            dlg.setStyleSheet(
                dialog_stylesheet(win, base, txtc)
                + f"""
                QListWidget {{
                    background-color: {field_bg.name()};
                    color: {txtc.name()};
                    border: 1px solid {border.name()};
                    border-radius: 8px;
                    outline: none;
                }}
                QListWidget::item {{ padding: 2px 6px; }}
                QListWidget::item:selected {{
                    background-color: palette(highlight);
                    color: palette(highlighted-text);
                }}
                """
            )
        except Exception:
            pass

        layout = QVBoxLayout(dlg)
        summary = QLabel(f"{singer}: {old_label}")
        summary.setWordWrap(True)
        summary.setStyleSheet(f"color:{_v('text_soft')}; font-weight:700;")
        layout.addWidget(summary)

        search = QLineEdit(dlg)
        search.setPlaceholderText("Search your karaoke library...")
        search.setClearButtonEnabled(True)
        layout.addWidget(search)

        results = QListWidget(dlg)
        results.setAlternatingRowColors(True)
        results.setUniformItemSizes(True)
        results.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        results.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        results.setItemDelegate(
            RightAlignedMetaDelegate(
                self._row_left_role,
                self._row_right_role,
                results,
                compact_shift_ratio=0.0,
                edge_pad_px=2,
                gap_px=12,
                force_scrollbar_reserve_px=0,
            )
        )
        layout.addWidget(results, 1)

        if same_song:
            confirm_text = "Select a karaoke version for this pending request."
        elif replacing:
            confirm_text = "Select a different song for this pending request."
        else:
            confirm_text = "Select a track to add this waiting request."
        confirm = QLabel(confirm_text)
        confirm.setWordWrap(True)
        confirm.setStyleSheet(f"color:{_v('warning')}; font-weight:700;")
        layout.addWidget(confirm)

        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Cancel, parent=dlg)
        button_text = "Use Version" if same_song else ("Use Song" if replacing else "Add Selected")
        add_btn = btns.addButton(button_text, QDialogButtonBox.ButtonRole.AcceptRole)
        add_btn.setEnabled(False)
        layout.addWidget(btns)

        search_state = {"job_id": 0, "thread": None}
        search_timer = QTimer(dlg)
        search_timer.setSingleShot(True)
        search_timer.setInterval(max(120, int(self._effective_search_debounce_ms() * 0.7)))

        def current_track():
            item = results.currentItem()
            if item is None:
                return None
            track = item.data(Qt.ItemDataRole.UserRole)
            return track if isinstance(track, dict) else None

        def refresh_confirm():
            track = current_track()
            add_btn.setEnabled(track is not None)
            if not track:
                confirm.setText(confirm_text)
                return
            artist = str(track.get("artist") or "").strip()
            title = str(track.get("title") or "").strip()
            label = f"{artist} - {title}".strip(" -") or str(track.get("display") or "selected track")
            if replacing:
                confirm.setText(f"Use '{label}' for {singer}'s pending request?")
            else:
                confirm.setText(f"Add '{label}' for {singer}?")

        def add_rows(rows):
            results.setUpdatesEnabled(False)
            try:
                results.clear()
                for r in rows or []:
                    try:
                        track = self._track_from_search_row(r)
                        if not str(track.get("path") or "").strip():
                            continue
                        _label, tooltip, left, right = self._build_search_row_text(track)
                        item = QListWidgetItem(left)
                        item.setData(Qt.ItemDataRole.UserRole, track)
                        self._set_aligned_row_meta(item, left, right)
                        item.setData(self._row_disc_role, str(track.get("disc_id") or "").strip())
                        try:
                            item.setToolTip(tooltip)
                        except Exception:
                            pass
                        results.addItem(item)
                    except Exception:
                        continue
            finally:
                results.setUpdatesEnabled(True)
            if results.count() > 0:
                results.setCurrentRow(0)
            refresh_confirm()

        def on_results(job_id, rows):
            if int(job_id) != int(search_state.get("job_id") or 0):
                return
            if not str(search.text() or "").strip():
                results.clear()
                refresh_confirm()
                return
            add_rows(rows)

        def start_search():
            query = str(search.text() or "").strip()
            search_state["job_id"] = int(search_state.get("job_id") or 0) + 1
            job_id = int(search_state["job_id"])
            # Retire before the empty-query check, not after. Backspacing the
            # box to nothing has to stand the in-flight search down too --
            # otherwise it keeps scanning the library for a result that is
            # already discarded, and it is still running when the next
            # keystroke or the dialog close comes to replace it.
            _retire_search_thread(search_state)
            if not query:
                results.clear()
                refresh_confirm()
                return
            thread = SongSearchThread(
                job_id,
                query,
                limit=250,
                fuzzy=True,
                karafun_search_url=(
                    _network_normalize_base_url(self.settings.get("base_url", "")) + "/karafun_search.php"
                    if bool(self.settings.get("karafun_provider_enabled", True))
                    and bool(self.settings.get("karafun_include_online_search", False))
                    else ""
                ),
                karafun_tenant=str(self.settings.get("user", self.settings.get("tenant", "")) or ""),
            )
            thread.results_ready.connect(on_results)
            search_state["thread"] = thread
            thread.start()

        def apply_choice():
            track = current_track()
            if not isinstance(track, dict):
                return
            try:
                if replacing:
                    ok = self._replace_waiting_for_add_track(req, track, source=mode)
                else:
                    ok = self._add_waiting_for_add_track(req, track)
                if ok:
                    dlg.accept()
            except Exception as e:
                QMessageBox.warning(dlg, "Waiting for Add", str(e))

        search.textChanged.connect(lambda *_: search_timer.start())
        search.returnPressed.connect(apply_choice)
        search_timer.timeout.connect(start_search)
        results.itemSelectionChanged.connect(refresh_confirm)
        results.itemDoubleClicked.connect(lambda *_: apply_choice())
        btns.accepted.connect(apply_choice)
        btns.rejected.connect(dlg.reject)

        def cleanup():
            try:
                s = dlg.size()
                self.settings["waiting_find_song_dialog_size"] = {"w": int(s.width()), "h": int(s.height())}
                self.save_settings()
            except Exception:
                pass
            _retire_search_thread(search_state)

        dlg.finished.connect(lambda _r: cleanup())
        seed = " ".join([p for p in (old_artist, old_title) if p]).strip()
        if seed:
            search.setText(seed)
            search.selectAll()
            search_timer.start(10)
        search.setFocus(Qt.FocusReason.PopupFocusReason)
        dlg.exec()

    def _mark_waiting_for_add_delivered_async(self, request_id: int, req: dict | None = None):
        try:
            request_id = int(request_id or 0)
        except Exception:
            return
        if request_id <= 0:
            return
        try:
            if hasattr(self, "ack_remote_requests"):
                self.ack_remote_requests([request_id])
        except Exception:
            pass
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        if not base_url or not tenant or not api_key:
            return

        def worker():
            try:
                resp = requests.post(
                    f"{base_url}/api/v1/mark_remote_request_delivered.php",
                    data={
                        "user": tenant,
                        "request_id": request_id,
                        "singer": str((req or {}).get("singer") or ""),
                        "artist": str((req or {}).get("artist") or ""),
                        "title": str((req or {}).get("title") or ""),
                    },
                    headers={"X-API-Key": api_key, "Accept": "application/json"},
                    timeout=5,
                )
                _diag(
                    "[WAITING-FOR-ADD] delivered mark "
                    f"request_id={request_id} ok={int(200 <= resp.status_code < 300)} status={resp.status_code}"
                )
            except Exception as e:
                _diag(f"[WAITING-FOR-ADD] delivered mark failed request_id={request_id}: {e}")

        try:
            threading.Thread(target=worker, daemon=True, name="waiting-for-add-delivered").start()
        except Exception:
            pass

    def _clear_selected_waiting_for_add(self):
        req = self._selected_waiting_for_add_request()
        if not req:
            return
        if req.get("_removed_tonight"):
            self._restore_selected_waiting_for_add()
            return
        rid = self._waiting_for_add_request_id(req)
        if rid <= 0:
            return
        undo = KaraokeApp._begin_undoable_action(self, "Remove Pending Request")
        self._archive_waitlist_removed_tonight(req, reason="waiting_for_add_cleared")
        try:
            self._waiting_for_add_handled_ids.add(rid)
        except Exception:
            self._waiting_for_add_handled_ids = {rid}
        try:
            self._delete_remote_request(
                rid,
                entry={"artist": req.get("artist", ""), "title": req.get("title", "")},
                singer_name=str(req.get("singer") or ""),
                reason="waiting_for_add_cleared",
            )
        except Exception:
            pass
        try:
            if self._waiting_for_add_failed_add(req):
                self._notify_singer_waitlist_add_failed(req)
        except Exception:
            pass
        try:
            getattr(self, "_waiting_for_add_requests", {}).pop(rid, None)
        except Exception:
            pass
        self._schedule_waiting_for_add_view_refresh(reason="clear")
        KaraokeApp._commit_undoable_action(self, undo, "Pending request removed")

    def _clear_all_waiting_for_add(self):
        reqs = self._waiting_for_add_clearable_requests()
        if not reqs:
            return
        count = len(reqs)
        try:
            answer = QMessageBox.question(
                self,
                "Clear Waitlist",
                f"Remove all {count} waitlisted song{'s' if count != 1 else ''}?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if answer != QMessageBox.StandardButton.Yes:
                return
        except Exception:
            pass
        undo = KaraokeApp._begin_undoable_action(self, "Clear Waitlist")
        handled = getattr(self, "_waiting_for_add_handled_ids", None)
        if not isinstance(handled, set):
            handled = set()
            self._waiting_for_add_handled_ids = handled
        pending = getattr(self, "_waiting_for_add_requests", None)
        removed = 0
        for req in reqs:
            rid = self._waiting_for_add_request_id(req)
            if rid <= 0:
                continue
            self._archive_waitlist_removed_tonight(req, reason="waiting_for_add_clear_all")
            handled.add(rid)
            try:
                self._delete_remote_request(
                    rid,
                    entry={"artist": req.get("artist", ""), "title": req.get("title", "")},
                    singer_name=str(req.get("singer") or ""),
                    reason="waiting_for_add_clear_all",
                )
            except Exception:
                pass
            try:
                if self._waiting_for_add_failed_add(req):
                    self._notify_singer_waitlist_add_failed(req)
            except Exception:
                pass
            try:
                if isinstance(pending, dict):
                    pending.pop(rid, None)
            except Exception:
                pass
            removed += 1
        if removed:
            self._schedule_waiting_for_add_view_refresh(reason="clear_all")
            self._show_processing_notification(
                f"Cleared {removed} waitlisted song{'s' if removed != 1 else ''}.",
                level="success",
            )
            KaraokeApp._commit_undoable_action(self, undo, "Waitlist cleared")

    def _waiting_for_add_failed_add(self, req: dict | None) -> bool:
        """True when this waitlist entry is here because the desktop add failed
        (as opposed to plain waiting for the host)."""
        req = req or {}
        state = str(req.get("state") or "").strip().lower()
        if state in {"failed", "failed_needs_review"}:
            return True
        reason = str(req.get("pending_reason") or req.get("last_error") or req.get("attention_reason") or "").strip().lower()
        if reason.startswith("unsupported_format"):
            return True
        return reason in {
            "sync_failed",
            "auto_accept_failed",
            "queue_insert_failed",
            "no_local_library_match",
            "previous_auto_match_failure",
            "cdg_missing_mp3",
            "invalid_zip_format",
        }

    def _notify_singer_waitlist_add_failed(self, req: dict | None) -> None:
        req = req or {}
        singer = str(req.get("singer") or "").strip()
        if not singer:
            return
        title = str(req.get("title") or "").strip() or "your song"
        message = (
            f'Sorry — we couldn\'t add "{title}" tonight, so it was removed from the waitlist. '
            "Feel free to request a different song!"
        )

        def worker():
            ok, err = self._net_send_direct_message(singer, message, system_notice=True)
            if not ok:
                _diag(f"[WAITING-FOR-ADD] add-failed notice to {singer!r} failed: {err}")

        try:
            threading.Thread(target=worker, daemon=True, name="waitlist-add-failed-notice").start()
        except Exception:
            pass

    def _cleanup_terminal_removed_requests(self, terminal_items: dict) -> None:
        """Hard-delete server rows for requests that ended up removed/skipped.

        The Removed/Skipped section is no longer rendered, so without this the
        rows would ride along in every sync response forever."""
        if not isinstance(terminal_items, dict) or not terminal_items:
            return
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return
        cleaned = state.get("_terminal_removed_cleaned_ids")
        if not isinstance(cleaned, set):
            cleaned = set()
            self._terminal_removed_cleaned_ids = cleaned
        targets = []
        for rid, req in terminal_items.items():
            try:
                rid_int = int(rid)
            except Exception:
                continue
            if rid_int <= 0 or rid_int in cleaned or not isinstance(req, dict):
                continue
            if self._waiting_for_add_status_kind(req) != "removed":
                continue
            cleaned.add(rid_int)
            targets.append(rid_int)
        if not targets:
            return
        try:
            base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
            tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
            api_key = str(self.settings.get("api_key", "") or "").strip()
        except Exception:
            return
        if not base_url or not tenant or not api_key:
            return

        def worker():
            headers = {"X-API-Key": api_key, "Accept": "application/json", "User-Agent": "SingWS/waitlist-cleanup"}
            for rid in targets:
                try:
                    requests.post(
                        f"{base_url}/api/v1/delete_remote_request.php",
                        data={"user": tenant, "request_id": rid, "hard_delete": 1},
                        headers=headers,
                        timeout=5,
                    )
                except Exception as e:
                    _diag(f"[WAITING-FOR-ADD] terminal removed purge failed request_id={rid}: {e}")

        try:
            threading.Thread(target=worker, daemon=True, name="waitlist-removed-purge").start()
        except Exception:
            pass

    def _tick_waiting_for_add_pulse(self):
        self._update_waiting_for_add_nav_state()
        try:
            if self._needs_review_count() > 0:
                self._schedule_waiting_for_add_view_refresh(delay_ms=0, reason="needs_review_pulse")
        except Exception:
            pass

    def _waiting_for_add_pulse_value(self) -> float:
        try:
            period = 1.8
            t = (time.monotonic() - float(getattr(self, "_waiting_for_add_pulse_started_at", time.monotonic()))) % period
            return 0.5 - 0.5 * math.cos((t / period) * math.tau)
        except Exception:
            return 0.0

    def _pending_acceptance_count(self) -> int:
        if not self._pending_acceptance_enabled():
            return 0
        try:
            return len(self._pending_acceptance_rows())
        except Exception:
            return 0

    def _needs_review_count(self) -> int:
        try:
            pending = object.__getattribute__(self, "__dict__").get("_waiting_for_add_requests", {})
        except Exception:
            return 0
        if not isinstance(pending, dict):
            return 0
        count = 0
        for req in pending.values():
            if isinstance(req, dict) and str(req.get("state") or "").strip().lower() == "failed_needs_review":
                count += 1
        return count

    def _waiting_for_add_count(self) -> int:
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return 0
        pending = state.get("_waiting_for_add_requests", {})
        if not isinstance(pending, dict):
            return 0
        try:
            local_ids = set(int(v) for v in (self._queue_remote_request_ids() or []))
        except Exception:
            local_ids = set()
        identity_sets = self._accepted_request_identity_sets()
        count = 0
        for rid, req in pending.items():
            try:
                rid_int = int(rid)
            except Exception:
                continue
            if rid_int not in local_ids and not self._request_matches_accepted_queue_item(req, identity_sets=identity_sets):
                count += 1
        return count

    def _update_waiting_for_add_nav_state(self, active: bool | None = None):
        try:
            state = object.__getattribute__(self, "__dict__")
        except Exception:
            return
        btn = state.get("bottom_waiting_for_add_button")
        if btn is None:
            return
        try:
            if active is None:
                stack = state.get("left_workspace_stack")
                active = stack is not None and stack.currentWidget() is state.get("waiting_for_add_page")
        except Exception:
            active = False
        # Any actionable host decision should pulse the nav button green.
        count = self._pending_acceptance_count() + self._waiting_for_add_count()
        timer = state.get("_waiting_for_add_pulse_timer")
        if count > 0:
            if timer is not None and not timer.isActive():
                self._waiting_for_add_pulse_started_at = time.monotonic()
                timer.start()
        else:
            if timer is not None:
                timer.stop()
            self._waiting_for_add_nav_css_cache_key = None
        try:
            label = state.get("_nav_text_labels", {}).get(btn)
            if label is not None:
                text = "Waitlist" if count == 0 else f"Waitlist ({count})"
                if label.text() != text:
                    label.setText(text)
            tooltip = (
                f"Waitlist: {count} request{'s' if count != 1 else ''} need host action"
                if count > 0
                else "Waitlist: no pending host action"
            )
            if btn.toolTip() != tooltip:
                btn.setToolTip(tooltip)
        except Exception:
            pass
        if count > 0:
            pulse = round(self._waiting_for_add_pulse_value(), 1)
            bg_alpha = 0.22 + (0.18 * pulse)
            border_alpha = 0.46 + (0.24 * pulse)
            cache_key = ("pending", count, pulse)
            if getattr(self, "_waiting_for_add_nav_css_cache_key", None) == cache_key:
                return
            self._waiting_for_add_nav_css_cache_key = cache_key
            css = (
                f"""
                QPushButton {{
                    background-color: rgba(22, 163, 74, {bg_alpha:.2f});
                    color: {_v('accent_text')};
                    border: 1px solid rgba(134, 239, 172, {border_alpha:.2f});
                    border-radius: 8px;
                    padding: 4px 6px;
                    font-size: 12px;
                    font-weight: 800;
                }}
                QPushButton:hover {{
                    background-color: rgba(22, 163, 74, 0.44);
                    border-color: rgba(187, 247, 208, 0.86);
                }}
                """
            )
            btn.setStyleSheet(css)
        else:
            css = (
                SINGWS_THEME.nav_item_css(active=bool(active))
                if SINGWS_THEME is not None and hasattr(SINGWS_THEME, "nav_item_css")
                else (button_css(padding="9px 12px", radius=8) if active else subtle_button_css(padding="9px 12px", radius=8))
            )
            cache_key = ("normal", bool(active), id(SINGWS_THEME) if SINGWS_THEME is not None else 0)
            if getattr(self, "_waiting_for_add_nav_css_cache_key", None) != cache_key:
                self._waiting_for_add_nav_css_cache_key = cache_key
                btn.setStyleSheet(css)

    def _build_singer_history_page(self):
        page = QWidget()
        root = QVBoxLayout(page)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(6)

        shell = QFrame()
        shell.setObjectName("singerHistoryShell")
        shell.setStyleSheet(panel_frame_css("singerHistoryShell", radius=14, border_alpha=0.05))
        shell_layout = QVBoxLayout(shell)
        shell_layout.setContentsMargins(12, 10, 12, 12)
        shell_layout.setSpacing(8)

        header = QHBoxLayout()
        title = QLabel("SINGER HISTORY")
        title.setStyleSheet(section_title_css())
        header.addWidget(title)
        header.addStretch(1)
