    def _history_sort_key(self, record: dict):
        # Alphabetical by singer name (case-insensitive) so the directory is
        # easy to scan during a show.
        return str(record.get("name", "") or "").strip().lower()

    def _history_song_display(self, song: dict) -> str:
        artist = str(song.get("artist", "") or "").strip() or "Unknown Artist"
        title = str(song.get("title", "") or "").strip() or "Unknown Song"
        disc = str(song.get("disc_id", "") or "").strip()
        song_type = str(song.get("song_type", "") or "").strip().upper()
        duet_display = str(song.get("duet_display", "") or "").strip()
        key = int(song.get("last_key") or 0)
        tempo = int(song.get("last_tempo_percent") or 100)
        meta = []
        if duet_display:
            meta.append(f"Duet: {duet_display}")
        if disc:
            meta.append(disc)
        if song_type:
            meta.append(song_type)
        meta.append(f"Key {key:+d}")
        meta.append(f"Tempo {tempo}%")
        meta.append(_history_song_last_sang_text(song.get("last_performed_at")))
        return f"{artist} • {title}\n" + "  ·  ".join(meta)

    def _format_history_timestamp(self, ts: int) -> str:
        try:
            ts = int(ts or 0)
            if ts <= 0:
                return "Never"
            return datetime.fromtimestamp(ts).strftime("%b %d, %Y")
        except Exception:
            return "Never"

    def _selected_singer_history_key(self) -> str:
        model = getattr(self, "singer_history_singer_model", None)
        view = getattr(self, "singer_history_singer_list", None)
        if model is not None and view is not None and hasattr(model, "singerKeyForIndex"):
            return str(model.singerKeyForIndex(view.currentIndex()) or "")
        try:
            item = view.currentItem()
            if not item:
                return ""
            return str(item.data(Qt.ItemDataRole.UserRole) or "")
        except Exception:
            return ""

    def _selected_singer_history_song_key(self) -> str:
        model = getattr(self, "singer_history_songs_model", None)
        view = getattr(self, "singer_history_songs_list", None)
        if model is not None and view is not None and hasattr(model, "songKeyForIndex"):
            return str(model.songKeyForIndex(view.currentIndex()) or "")
        try:
            item = view.currentItem()
            if not item:
                return ""
            return str(item.data(Qt.ItemDataRole.UserRole) or "")
        except Exception:
            return ""

    def _selected_singer_history_song_record(self) -> dict | None:
        singer_key = self._selected_singer_history_key()
        song_key = self._selected_singer_history_song_key()
        if not singer_key or not song_key:
            return None
        singer = self.singer_history.get("singers", {}).get(singer_key)
        if not isinstance(singer, dict):
            return None
        song = (singer.get("songs", {}) or {}).get(song_key)
        return song if isinstance(song, dict) else None

    def _refresh_singer_history_view(self):
        if not hasattr(self, "singer_history_singer_list"):
            return
        editing_allowed = not bool(getattr(self, "karaoke_playing", False))
        for button_name in (
            "history_clear_all_button",
            "history_clear_small_button",
            "history_clear_inactive_button",
            "singer_history_sync_button",
        ):
            button = getattr(self, button_name, None)
            if button is not None:
                button.setEnabled(editing_allowed)
        try:
            if self.left_workspace_stack.currentWidget() is not self.singer_history_page:
                self._singer_history_refresh_hidden_deferred = True
                return
        except Exception:
            return
        self._singer_history_refresh_deferred = False
        open_t0 = time.perf_counter()
        current_key = self._selected_singer_history_key()
        search = ""
        try:
            search = str(self.singer_history_search.text() or "").strip().lower()
        except Exception:
            pass
        playing = bool(getattr(self, "karaoke_playing", False))
        render_limit = 220 if playing else 700
        song_scan_limit = 120 if playing else 500

        try:
            self._singer_history_refresh_job_id = int(getattr(self, "_singer_history_refresh_job_id", 0) or 0) + 1
            job_id = int(self._singer_history_refresh_job_id)
        except Exception:
            job_id = int(time.time() * 1000)
            self._singer_history_refresh_job_id = job_id

        old_worker = getattr(self, "_singer_history_directory_worker", None)
        try:
            if old_worker is not None and hasattr(old_worker, "cancel"):
                old_worker.cancel()
        except Exception:
            pass

        snapshot_t0 = time.perf_counter()
        try:
            singers_snapshot = list((self.singer_history.get("singers", {}) or {}).items())
        except Exception:
            singers_snapshot = []
        self._history_perf_log(
            "snapshot",
            (time.perf_counter() - snapshot_t0) * 1000.0,
            count=len(singers_snapshot),
            playing=int(playing),
            search=int(bool(search)),
        )

        if not singers_snapshot:
            self._apply_singer_history_directory_rows(job_id, {
                "rows": [],
                "total_matches": 0,
                "shown": 0,
                "search": search,
                "timings": {"total_ms": 0.0},
                "cancelled": False,
            }, current_key)
            self._history_perf_log("open_request", (time.perf_counter() - open_t0) * 1000.0, count=0)
            return

        try:
            self.singer_history_meta_label.setText("Loading singers...")
            if hasattr(self, "singer_history_left_meta_label"):
                self.singer_history_left_meta_label.setText("Loading")
        except Exception:
            pass

        try:
            thread = QThread()
            worker = SingerHistoryDirectoryBuildWorker(job_id, singers_snapshot, search, render_limit, song_scan_limit)
            worker.moveToThread(thread)
            thread.started.connect(worker.run)
            targets = getattr(self, "_singer_history_directory_targets", None)
            if not isinstance(targets, dict):
                targets = {}
                self._singer_history_directory_targets = targets
            targets[job_id] = current_key
            worker.finished.connect(self._on_singer_history_directory_built)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            self._singer_history_directory_thread = thread
            self._singer_history_directory_worker = worker
            jobs = getattr(self, "_singer_history_directory_jobs", None)
            if not isinstance(jobs, list):
                jobs = []
                self._singer_history_directory_jobs = jobs
            job_ref = (thread, worker)
            jobs.append(job_ref)
            thread.finished.connect(lambda ref=job_ref: jobs.remove(ref) if ref in jobs else None)
            _register_brand_choice_thread(thread)
            thread.start()
            self._history_perf_log(
                "open_request",
                (time.perf_counter() - open_t0) * 1000.0,
                count=len(singers_snapshot),
                playing=int(playing),
                search=int(bool(search)),
            )
        except Exception as e:
            _diag(f"[PERF] singer_history_worker_start_failed error={e}")
            rows = []
            for singer_key, record in singers_snapshot[:render_limit]:
                if not isinstance(record, dict):
                    continue
                name = str(record.get("name", "") or singer_key).strip()
                text = f"{name}\n{int(record.get('total_performances') or 0)} plays  ·  {int(record.get('unique_song_count') or len(record.get('songs', {}) or {}))} songs"
                rows.append({"text": text, "singer_key": singer_key, "selectable": True, "tooltip": text, "height": 52})
            self._apply_singer_history_directory_rows(job_id, {
                "rows": rows,
                "total_matches": len(singers_snapshot),
                "shown": len(rows),
                "search": search,
                "timings": {"total_ms": (time.perf_counter() - open_t0) * 1000.0},
                "cancelled": False,
            }, current_key)

    def _on_singer_history_directory_built(self, job_id: int, result: dict):
        try:
            targets = getattr(self, "_singer_history_directory_targets", {})
            current_key = str((targets or {}).pop(int(job_id), "") or "")
            if int(job_id) != int(getattr(self, "_singer_history_refresh_job_id", 0) or 0):
                return
            if isinstance(result, dict) and result.get("cancelled"):
                return
            self._apply_singer_history_directory_rows(job_id, result, current_key)
        except Exception as e:
            _diag(f"[PERF] singer_history_directory_apply_failed error={e}")

    def _apply_singer_history_directory_rows(self, job_id: int, result: dict, current_key: str):
        apply_t0 = time.perf_counter()
        rows = list((result or {}).get("rows") or [])
        for row in rows:
            color_hex = row.pop("foreground_hex", None)
            if color_hex:
                try:
                    row["foreground"] = QColor(str(color_hex))
                except Exception:
                    pass
        total_matches = int((result or {}).get("total_matches") or 0)
        shown = int((result or {}).get("shown") or 0)
        search = str((result or {}).get("search") or "")
        selection_model = self.singer_history_singer_list.selectionModel()
        self.singer_history_singer_list.setUpdatesEnabled(False)
        if selection_model is not None:
            selection_model.blockSignals(True)
        try:
            self.singer_history_singer_model.setRows(rows)
            target_index = self.singer_history_singer_model.indexForSingerKey(current_key)
            if not target_index.isValid():
                target_index = self.singer_history_singer_model.firstSelectableIndex()
            if target_index.isValid():
                self.singer_history_singer_list.setCurrentIndex(target_index)
            else:
                self.singer_history_singer_list.setCurrentIndex(QModelIndex())
        finally:
            if selection_model is not None:
                selection_model.blockSignals(False)
            self.singer_history_singer_list.setUpdatesEnabled(True)
        try:
            suffix = "" if total_matches == shown else f" ({shown} shown)"
            self.singer_history_meta_label.setText(f"{total_matches} singers{suffix}")
            try:
                self.singer_history_left_meta_label.setText("Directory" if total_matches else "Empty")
            except Exception:
                pass
        except Exception:
            pass
        self._update_singer_history_details(self._selected_singer_history_key())
        self._history_perf_log(
            "model_apply",
            (time.perf_counter() - apply_t0) * 1000.0,
            rows=len(rows),
            total=total_matches,
            playing=int(bool(getattr(self, "karaoke_playing", False))),
            search=int(bool(search)),
        )
        try:
            timings = dict((result or {}).get("timings") or {})
            for key, value in timings.items():
                self._history_perf_log(f"directory_worker_{key.replace('_ms', '')}", float(value), job=job_id)
        except Exception:
            pass

    def _on_singer_history_selection_changed(self, *_args):
        self._update_singer_history_details(self._selected_singer_history_key())

    def _singer_history_song_query(self) -> str:
        try:
            return str(self.singer_history_song_search.text() or "").strip().casefold()
        except Exception:
            return ""

    def _filter_singer_history_songs(self, songs):
        """Filter (song_key, song) items by the song-search box.

        Every whitespace-separated token must appear somewhere in the song's
        artist/title/disc/duet text (case-insensitive), matching how the main
        library search feels.
        """
        query = self._singer_history_song_query()
        if not query:
            return songs
        tokens = query.split()
        filtered = []
        for item in songs or []:
            try:
                song_key, song = item
            except Exception:
                continue
            parts = [str(song_key or "")]
            if isinstance(song, dict):
                for field in ("artist", "title", "disc_id", "song_type", "duet_display"):
                    value = song.get(field)
                    if value:
                        parts.append(str(value))
            blob = " ".join(parts).casefold()
            if all(token in blob for token in tokens):
                filtered.append(item)
        return filtered

    def _singer_history_song_meta_text(self, shown_total: int, shown: int | None = None) -> str:
        total_unfiltered = int(getattr(self, "_singer_history_song_total_unfiltered", shown_total) or 0)
        filtered = bool(getattr(self, "_singer_history_song_filter_active", False))
        suffix = "" if shown is None or shown == shown_total else f" ({shown} shown)"
        if filtered:
            return f"{shown_total} of {total_unfiltered} entries{suffix}"
        return f"{shown_total} entries{suffix}"

    def _update_singer_history_details(self, singer_key: str):
        if not hasattr(self, "singer_history_name_label"):
            return
        editing_allowed = not bool(getattr(self, "karaoke_playing", False))
        old_worker = getattr(self, "_singer_history_songs_worker", None)
        try:
            if old_worker is not None and hasattr(old_worker, "cancel"):
                old_worker.cancel()
        except Exception:
            pass
        record = self.singer_history.get("singers", {}).get(singer_key, {}) if singer_key else {}
        if not isinstance(record, dict) or not singer_key:
            self.singer_history_name_label.setText("Select a singer")
            if hasattr(self, "singer_history_summary_label"):
                self.singer_history_summary_label.setText("No singer selected.")
            self.singer_history_rename_button.setEnabled(False)
            self.singer_history_brand_button.setEnabled(False)
            try:
                self.singer_history_brand_combo.blockSignals(True)
                self.singer_history_brand_combo.clear()
                self.singer_history_brand_combo.addItem("No preferred brand", "")
                self.singer_history_brand_combo.setEnabled(False)
                self.singer_history_brand_combo.blockSignals(False)
            except Exception:
                pass
            self.singer_history_delete_singer_button.setEnabled(False)
            self.singer_history_add_song_button.setEnabled(False)
            self.singer_history_edit_song_button.setEnabled(False)
            self.singer_history_delete_song_button.setEnabled(False)
            try:
                self.singer_history_songs_model.setRows([])
            except Exception:
                try:
                    self.singer_history_songs_list.clear()
                except Exception:
                    pass
            try:
                self.singer_history_song_meta_label.setText("0 entries")
            except Exception:
                pass
            return
        name = str(record.get("name", "") or singer_key)
        total = int(record.get("total_performances") or 0)
        unique = int(record.get("unique_song_count") or len(record.get("songs", {}) or {}))
        last_seen = self._format_history_timestamp(record.get("last_seen_at") or 0)
        pref = str(record.get("preferred_disc_priority", "") or "").strip()
        self.singer_history_name_label.setText(name)
        summary = f"{total} total performances  ·  {unique} songs  ·  Last seen {last_seen}"
        if pref:
            summary += f"  ·  Preferred brand {pref}"
        if hasattr(self, "singer_history_summary_label"):
            self.singer_history_summary_label.setText(summary)
        self.singer_history_rename_button.setEnabled(editing_allowed)
        self.singer_history_brand_button.setEnabled(editing_allowed)
        self._refresh_singer_history_brand_combo(pref)
        self.singer_history_brand_combo.setEnabled(editing_allowed)
        self.singer_history_delete_singer_button.setEnabled(editing_allowed)
        self.singer_history_add_song_button.setEnabled(editing_allowed)
        for button_name in (
            "history_clear_all_button",
            "history_clear_small_button",
            "history_clear_inactive_button",
            "singer_history_sync_button",
        ):
            button = getattr(self, button_name, None)
            if button is not None:
                button.setEnabled(editing_allowed)
        current_song_key = self._selected_singer_history_song_key()
        render_limit = 180 if bool(getattr(self, "karaoke_playing", False)) else 500
        try:
            songs = list((record.get("songs", {}) or {}).items())
        except Exception:
            songs = []
        # Song search: filter at the source (before the render worker and its
        # row cap) so every history entry is searchable, not just the first
        # render_limit rows.
        total_unfiltered = len(songs)
        songs = self._filter_singer_history_songs(songs)
        self._singer_history_song_total_unfiltered = total_unfiltered
        self._singer_history_song_filter_active = len(songs) != total_unfiltered or bool(
            self._singer_history_song_query()
        )
        try:
            self._singer_history_songs_job_id = int(getattr(self, "_singer_history_songs_job_id", 0) or 0) + 1
            job_id = int(self._singer_history_songs_job_id)
        except Exception:
            job_id = int(time.time() * 1000)
            self._singer_history_songs_job_id = job_id
        self.singer_history_edit_song_button.setEnabled(False)
        self.singer_history_delete_song_button.setEnabled(False)
        try:
            self.singer_history_song_meta_label.setText(
                f"{self._singer_history_song_meta_text(len(songs))} (loading)"
            )
        except Exception:
            pass
        if not songs:
            try:
                self.singer_history_songs_model.setRows([])
                self.singer_history_song_meta_label.setText(self._singer_history_song_meta_text(0))
            except Exception:
                pass
            return
        try:
            thread = QThread()
            worker = SingerHistorySongsBuildWorker(job_id, singer_key, songs, render_limit)
            worker.moveToThread(thread)
            thread.started.connect(worker.run)
            selected_by_job = getattr(self, "_singer_history_songs_selected_by_job", None)
            if not isinstance(selected_by_job, dict):
                selected_by_job = {}
                self._singer_history_songs_selected_by_job = selected_by_job
            selected_by_job[job_id] = current_song_key
            worker.finished.connect(self._on_singer_history_songs_built)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            self._singer_history_songs_thread = thread
            self._singer_history_songs_worker = worker
            jobs = getattr(self, "_singer_history_songs_jobs", None)
            if not isinstance(jobs, list):
                jobs = []
                self._singer_history_songs_jobs = jobs
            job_ref = (thread, worker)
            jobs.append(job_ref)
            thread.finished.connect(lambda ref=job_ref: jobs.remove(ref) if ref in jobs else None)
            _register_brand_choice_thread(thread)
            thread.start()
        except Exception as e:
            _diag(f"[PERF] singer_history_songs_worker_start_failed singer={singer_key} error={e}")
            rows = []
            for song_key, song in songs[:render_limit]:
                if not isinstance(song, dict):
                    continue
                text = self._history_song_display(song)
                rows.append({"text": text, "song_key": song_key, "selectable": True, "tooltip": text, "height": 44})
            self._apply_singer_history_song_rows(job_id, singer_key, {
                "rows": rows,
                "total": len(songs),
                "shown": len(rows),
                "timings": {},
                "cancelled": False,
            }, current_song_key)

    def _on_singer_history_songs_built(self, job_id: int, singer_key: str, result: dict):
        try:
            selected_by_job = getattr(self, "_singer_history_songs_selected_by_job", {})
            current_song_key = str((selected_by_job or {}).pop(int(job_id), "") or "")
            if int(job_id) != int(getattr(self, "_singer_history_songs_job_id", 0) or 0):
                return
            if str(singer_key or "") != self._selected_singer_history_key():
                return
            if isinstance(result, dict) and result.get("cancelled"):
                return
            self._apply_singer_history_song_rows(job_id, singer_key, result, current_song_key)
        except Exception as e:
            _diag(f"[PERF] singer_history_songs_apply_failed singer={singer_key} error={e}")

    def _apply_singer_history_song_rows(self, job_id: int, singer_key: str, result: dict, current_song_key: str):
        apply_t0 = time.perf_counter()
        rows = list((result or {}).get("rows") or [])
        for row in rows:
            color_hex = row.pop("foreground_hex", None)
            if color_hex:
                try:
                    row["foreground"] = QColor(str(color_hex))
                except Exception:
                    pass
        self.singer_history_songs_list.setUpdatesEnabled(False)
        try:
            self.singer_history_songs_model.setRows(rows)
        finally:
            self.singer_history_songs_list.setUpdatesEnabled(True)
        total = int((result or {}).get("total") or 0)
        shown = int((result or {}).get("shown") or 0)
        try:
            self.singer_history_song_meta_label.setText(
                self._singer_history_song_meta_text(total, shown)
            )
        except Exception:
            pass
        has_rows = any((row or {}).get("selectable") for row in rows)
        editing_allowed = not bool(getattr(self, "karaoke_playing", False))
        self.singer_history_edit_song_button.setEnabled(bool(has_rows) and editing_allowed)
        self.singer_history_delete_song_button.setEnabled(bool(has_rows) and editing_allowed)
        if has_rows:
            target_index = self.singer_history_songs_model.indexForSongKey(current_song_key)
            if not target_index.isValid():
                target_index = self.singer_history_songs_model.firstSelectableIndex()
            if target_index.isValid():
                self.singer_history_songs_list.setCurrentIndex(target_index)
        self._history_perf_log(
            "songs_model_apply",
            (time.perf_counter() - apply_t0) * 1000.0,
            singer=singer_key,
            rows=len(rows),
            total=total,
            playing=int(bool(getattr(self, "karaoke_playing", False))),
        )
        try:
            timings = dict((result or {}).get("timings") or {})
            for key, value in timings.items():
                self._history_perf_log(f"songs_worker_{key.replace('_ms', '')}", float(value), singer=singer_key, job=job_id)
        except Exception:
            pass

    def _history_brand_choices_cache_key(self):
        try:
            tracks = getattr(self, "tracks", []) or []
            count = len(tracks)
            first = ""
            last = ""
            if count:
                try:
                    first = str((tracks[0] or {}).get("path", "") or (tracks[0] or {}).get("file", "") or "")
                except Exception:
                    first = ""
                try:
                    last = str((tracks[-1] or {}).get("path", "") or (tracks[-1] or {}).get("file", "") or "")
                except Exception:
                    last = ""
            return (id(tracks), count, first, last)
        except Exception:
            return (0, 0, "", "")

    def _ensure_history_brand_choices_async(self):
        cache_key = self._history_brand_choices_cache_key()
        if getattr(self, "_history_brand_choices_cached_key", None) == cache_key:
            return
        worker = getattr(self, "_history_brand_choices_worker", None)
        try:
            if worker is not None and hasattr(worker, "cancel"):
                worker.cancel()
        except Exception:
            pass
        # Join the previous thread before replacing it: destroying a QThread
        # object (e.g. via parent teardown at shutdown) while it is still
        # running aborts the whole process.
        old_thread = getattr(self, "_history_brand_choices_thread", None)
        if old_thread is not None:
            try:
                old_thread.quit()
                old_thread.wait(2000)
            except Exception:
                pass
        try:
            self._history_brand_choices_job_id = int(getattr(self, "_history_brand_choices_job_id", 0) or 0) + 1
            job_id = int(self._history_brand_choices_job_id)
        except Exception:
            job_id = int(time.time() * 1000)
            self._history_brand_choices_job_id = job_id
        try:
            thread = QThread()
            worker = SingerHistoryBrandChoicesWorker(job_id, cache_key, getattr(self, "tracks", []))
            worker.moveToThread(thread)
            thread.started.connect(worker.run)
            worker.finished.connect(self._on_history_brand_choices_built)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            self._history_brand_choices_thread = thread
            self._history_brand_choices_worker = worker
            _register_brand_choice_thread(thread)
            thread.start()
        except Exception as e:
            _diag(f"[PERF] singer_history_brand_choices_worker_start_failed error={e}")

    def _on_history_brand_choices_built(self, job_id: int, cache_key, choices: list, elapsed_ms: float):
        matched_current = False
        try:
            if int(job_id) != int(getattr(self, "_history_brand_choices_job_id", 0) or 0):
                return
            matched_current = True
            self._history_brand_choices_cached_key = cache_key
            self._history_brand_choices_cache = list(choices or [])
            self._history_perf_log("brand_choices_worker", float(elapsed_ms), tracks=len(getattr(self, "tracks", []) or []))
            try:
                self._refresh_singer_history_brand_combo(
                    (self.singer_history.get("singers", {}).get(self._selected_singer_history_key(), {}) or {}).get("preferred_disc_priority", "")
                )
            except Exception:
                pass
        finally:
            if matched_current:
                self._history_brand_choices_worker = None

    def _history_brand_choices(self, *, allow_sync_build: bool = False) -> list[str]:
        cache_key = self._history_brand_choices_cache_key()
        try:
            cached_key = getattr(self, "_history_brand_choices_cached_key", None)
            cached = getattr(self, "_history_brand_choices_cache", None)
            if cached_key == cache_key and isinstance(cached, list):
                return list(cached)
        except Exception:
            tracks = getattr(self, "tracks", []) or []
        self._ensure_history_brand_choices_async()
        if not allow_sync_build:
            return []
        tracks = getattr(self, "tracks", []) or []
        _perf_t0 = time.perf_counter()
        try:
            choices = library_brand_choices(tracks)
        except Exception:
            choices = []
        try:
            self._history_brand_choices_cached_key = cache_key
            self._history_brand_choices_cache = list(choices)
        except Exception:
            pass
        try:
            self._history_perf_log("brand_choices_build", (time.perf_counter() - _perf_t0) * 1000.0, tracks=len(tracks))
        except Exception:
            pass
        return choices

    def _refresh_singer_history_brand_combo(self, current_pref: str = ""):
        combo = getattr(self, "singer_history_brand_combo", None)
        if combo is None:
            return
        current_pref = ", ".join(normalize_disc_priority(current_pref, max_items=10))
        choices = self._history_brand_choices(allow_sync_build=False)
        try:
            combo.blockSignals(True)
            combo.clear()
            combo.addItem("No preferred brand", "")
            for brand in choices:
                combo.addItem(brand, brand)
            if current_pref and current_pref not in choices:
                combo.addItem(current_pref, current_pref)
            idx = combo.findData(current_pref)
            combo.setCurrentIndex(idx if idx >= 0 else 0)
            combo.setEnabled(True)
        finally:
            combo.blockSignals(False)

    def _on_singer_history_brand_combo_changed(self, _index: int):
        combo = getattr(self, "singer_history_brand_combo", None)
        singer_key = self._selected_singer_history_key()
        record = self.singer_history.get("singers", {}).get(singer_key)
        if combo is None or not isinstance(record, dict):
            return
        singer_name = str(record.get("name", "") or singer_key)
        value = ", ".join(normalize_disc_priority(combo.currentData() or "", max_items=10))
        current = ", ".join(normalize_disc_priority(record.get("preferred_disc_priority", ""), max_items=10))
        if value == current:
            return
        if value:
            self._set_singer_preference(singer_name, "preferred_disc_priority", value)
            self._commit_singer_history_change("history_brand_quick_select")
        else:
            self._clear_singer_preference(singer_name, "preferred_disc_priority")
            self._commit_singer_history_change("history_brand_quick_clear")

    def _apply_singer_history_preferences_to_queue(self):
        try:
            for singer in self.queue:
                singer_name_key = self._normalize_singer_pref_key(singer.get("name", ""))
                if not singer_name_key:
                    continue
                pref = self.singer_preferences.get(singer_name_key, {})
                pref_disc = ", ".join(normalize_disc_priority(pref.get("preferred_disc_priority", ""), max_items=10))
                if pref_disc:
                    singer["preferred_disc_priority"] = pref_disc
                else:
                    singer.pop("preferred_disc_priority", None)
        except Exception:
            pass

    def _commit_singer_history_change(self, reason: str = "history_edit"):
        self._apply_singer_history_preferences_to_queue()
        try:
            self._schedule_save_data(250 if bool(getattr(self, "karaoke_playing", False)) else 0)
        except Exception:
            pass
        self._schedule_singer_history_refresh(reason=reason)
        try:
            self.update_queue_display()
            self.update_rotation_summary_card()
            self._update_last_sung_card()
        except Exception:
            pass
        self._sync_singer_history_async(reason)

    def _rename_selected_singer_history(self):
        if bool(getattr(self, "karaoke_playing", False)):
            return
        singer_key = self._selected_singer_history_key()
        record = self.singer_history.get("singers", {}).get(singer_key)
        if not isinstance(record, dict):
            return
        old_name = str(record.get("name", "") or singer_key).strip()
        new_name, ok = QInputDialog.getText(
            self,
            "Rename Singer History",
            "Singer name:",
            QLineEdit.EchoMode.Normal,
            old_name,
        )
        if not ok:
            return
        new_name = str(new_name or "").strip()
        if not new_name or new_name == old_name:
            return
        old_key = self._normalize_singer_pref_key(old_name)
        new_key = self._normalize_singer_pref_key(new_name)
        singers = self.singer_history.setdefault("singers", {})
        source = singers.pop(old_key, None)
        if not isinstance(source, dict):
            return
        target = singers.get(new_key)
        merged = self._empty_singer_history_record(new_name)
        if isinstance(target, dict):
            merged.update(target)
        merged.update(source)
        merged["name"] = new_name
        merged["songs"] = dict(merged.get("songs", {}) or {})
        merged["unique_song_count"] = len(merged["songs"])
        merged["updated_at"] = int(time.time())
        singers[new_key] = merged
        old_pref = self.singer_preferences.pop(old_key, None)
        if isinstance(old_pref, dict):
            old_pref["name"] = new_name
            self.singer_preferences[new_key] = old_pref
        if old_key != new_key:
            # The old name no longer exists; tombstone it so the rename syncs.
            self._record_singer_tombstone(old_name)
        self._commit_singer_history_change("history_singer_rename")
        # If that singer is in the current rotation, apply the same rename
        # there — merging into an existing singer instead of duplicating
        # (prefs/history were already merged above).
        try:
            rotation_idx = self._queue_singer_match_index(old_name)
            if rotation_idx >= 0:
                self._rename_rotation_singer(
                    rotation_idx, new_name, source="history", merge_prefs_history=False
                )
        except Exception:
            pass
        try:
            index = self.singer_history_singer_model.indexForSingerKey(new_key)
            if index.isValid():
                self.singer_history_singer_list.setCurrentIndex(index)
        except Exception:
            pass

    def _edit_history_song_dialog(self, singer_key: str, song_key: str | None = None):
        record = self.singer_history.get("singers", {}).get(singer_key)
        if not isinstance(record, dict):
            return
        songs = record.setdefault("songs", {})
        existing = dict(songs.get(song_key, {})) if song_key else {}

        dlg = QDialog(self)
        dlg.setWindowTitle("Add Song History" if not song_key else "Edit Song History")
        dlg.setModal(True)
        dlg.setMinimumWidth(520)
        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            dlg.setStyleSheet(dialog_stylesheet(win, base, txtc))
        except Exception:
            pass
        layout = QVBoxLayout(dlg)

        artist_edit = QLineEdit(dlg)
        artist_edit.setPlaceholderText("Artist")
        artist_edit.setText(str(existing.get("artist", "") or ""))
        title_edit = QLineEdit(dlg)
        title_edit.setPlaceholderText("Title")
        title_edit.setText(str(existing.get("title", "") or ""))
        disc_edit = QLineEdit(dlg)
        disc_edit.setPlaceholderText("Disc ID")
        disc_edit.setText(str(existing.get("disc_id", "") or ""))
        type_edit = QLineEdit(dlg)
        type_edit.setPlaceholderText("Type (CDG, ZIP, MP4)")
        type_edit.setText(str(existing.get("song_type", "") or ""))
        key_spin = QSpinBox(dlg)
        key_spin.setRange(-24, 24)
        key_spin.setValue(int(existing.get("last_key") or 0))
        tempo_spin = QSpinBox(dlg)
        tempo_spin.setRange(50, 200)
        tempo_spin.setValue(int(existing.get("last_tempo_percent") or 100))

        for label_text, widget in (
            ("Artist", artist_edit),
            ("Title", title_edit),
            ("Disc ID", disc_edit),
            ("Song Type", type_edit),
            ("Key", key_spin),
            ("Tempo %", tempo_spin),
        ):
            label = QLabel(label_text)
            label.setStyleSheet(section_meta_css())
            layout.addWidget(label)
            layout.addWidget(widget)

        buttons = QDialogButtonBox(dlg)
        save_btn = buttons.addButton("Save", QDialogButtonBox.ButtonRole.AcceptRole)
        buttons.addButton("Cancel", QDialogButtonBox.ButtonRole.RejectRole)
        layout.addWidget(buttons)

        def handle_save():
            if song_key:
                songs.pop(song_key, None)
            new_song = dict(existing)
            new_song["artist"] = str(artist_edit.text() or "").strip()
            new_song["title"] = str(title_edit.text() or "").strip()
            new_song["disc_id"] = str(disc_edit.text() or "").strip()
            new_song["song_type"] = str(type_edit.text() or "").strip().upper()
            new_song["last_key"] = int(key_spin.value())
            new_song["last_tempo_percent"] = int(tempo_spin.value())
            new_song["updated_at"] = int(time.time())
            new_song.setdefault("songid", str(new_song.get("disc_id", "") or ""))
            new_song.setdefault("path", str(existing.get("path", "") or ""))
            new_song.setdefault("play_count", int(existing.get("play_count") or 0))
            new_song.setdefault("first_performed_at", int(existing.get("first_performed_at") or 0))
            new_song.setdefault("last_performed_at", int(existing.get("last_performed_at") or 0))
            new_key = self._normalize_history_song_key(
                new_song.get("artist", ""),
                new_song.get("title", ""),
                new_song.get("songid", ""),
                new_song.get("path", ""),
                new_song.get("provider", ""),
                new_song.get("provider_track_id", ""),
            )
            if not new_key:
                new_key = song_key or f"manual|{time.time()}"
            songs[new_key] = new_song
            record["unique_song_count"] = len(songs)
            record["updated_at"] = int(time.time())
            dlg.accept()
            self._commit_singer_history_change("history_song_edit" if song_key else "history_song_add")
            try:
                index = self.singer_history_songs_model.indexForSongKey(new_key)
                if index.isValid():
                    self.singer_history_songs_list.setCurrentIndex(index)
            except Exception:
                pass

        save_btn.clicked.connect(handle_save)
        buttons.rejected.connect(dlg.reject)
        dlg.exec()

    def _add_song_to_selected_singer_history(self):
        if bool(getattr(self, "karaoke_playing", False)):
            return
        singer_key = self._selected_singer_history_key()
        if singer_key:
            self._edit_history_song_dialog(singer_key, None)

    def _history_target_singer_names(self, default_name: str = "") -> list[str]:
        names = []
        seen = set()

        def add_name(raw):
            name = str(raw or "").strip()
            if not name:
                return
            key = name.lower()
            if key in seen:
                return
            seen.add(key)
            names.append(name)

        add_name(default_name)
        try:
            for singer in self.queue:
                add_name(singer.get("name", ""))
        except Exception:
            pass
        try:
            for record in (self.singer_history.get("singers", {}) or {}).values():
                if isinstance(record, dict):
                    add_name(record.get("name", ""))
        except Exception:
            pass
        return names

    def _find_matching_mp3_for_cdg(self, cdg_path: str) -> str:
        base = os.path.splitext(str(cdg_path or "").strip())[0]
        if not base:
            return ""
        for ext in (".mp3", ".MP3"):
            mp3_path = base + ext
            if os.path.exists(mp3_path):
                return mp3_path
        return ""

    def _karafun_track_from_history_song(self, song: dict) -> dict | None:
        """Rebuild a KaraFun streaming track from a history record.

        These songs have no local library row: their path is the synthetic
        "karafun_streaming:<id>" reference, which is never indexed. Playback
        drives KaraFun.app by artist/title search, so the stored catalog id is
        a display reference only and a catalog that has renumbered since does
        not prevent the add.
        """
        if not isinstance(song, dict):
            return None
        path = str(song.get("path", "") or "").strip()
        provider = str(song.get("provider", "") or "").strip().lower()
        song_type = str(song.get("song_type", "") or "").strip().lower()
        if not (
            path.lower().startswith("karafun_streaming:")
            or provider == "karafun_streaming"
            or song_type == "karafun_streaming"
        ):
            return None

        artist = str(song.get("artist", "") or "").strip()
        title = str(song.get("title", "") or "").strip()
        if not (artist or title):
            return None

        provider_track_id = str(song.get("provider_track_id", "") or "").strip()
        if not provider_track_id:
            # Older history rows kept the reference in songid or the path only.
            songid = str(song.get("songid", "") or "").strip()
            if songid.lower().startswith("kf_"):
                provider_track_id = songid
            elif path.lower().startswith("karafun_streaming:"):
                provider_track_id = path.split(":", 1)[1].strip()

        return self._build_karafun_streaming_track(
            artist=artist,
            title=title,
            provider_track_id=provider_track_id,
            provider_url=str(song.get("provider_url", "") or "").strip(),
        )

    def _resolve_history_song_track(self, song: dict, singer_name: str):
        if not isinstance(song, dict):
            return None

        karafun_track = self._karafun_track_from_history_song(song)
        if karafun_track is not None:
            return karafun_track

        path = str(song.get("path", "") or "").strip()
        if path:
            track = self._find_track_by_path_ci(path)
            if track:
                return track
            try:
                track = song_index.find_by_path(path)
                if isinstance(track, dict):
                    return track
            except Exception:
                pass

        disc_id = str(song.get("disc_id", "") or "").strip()
        artist = str(song.get("artist", "") or "").strip()
        title = str(song.get("title", "") or "").strip()

        matches = []
        if artist and title:
            try:
                matches = song_index.find_by_artist_title(artist, title) or []
            except Exception:
                matches = [
                    t for t in self.tracks
                    if str(t.get("artist", "") or "").strip().lower() == artist.lower()
                    and str(t.get("title", "") or "").strip().lower() == title.lower()
                ]

        if not matches and disc_id:
            disc_u = disc_id.upper()
            try:
                matches = [
                    t for t in self.tracks
                    if str(t.get("discid") or t.get("disc_id") or "").strip().upper() == disc_u
                ]
            except Exception:
                matches = []

        if not matches:
            return None

        if disc_id:
            disc_u = disc_id.upper()
            exact_disc = [
                t for t in matches
                if str(t.get("discid") or t.get("disc_id") or "").strip().upper() == disc_u
            ]
            if exact_disc:
                matches = exact_disc

        host_priority = normalize_disc_priority(self.settings.get("disc_id_priority", ""), max_items=10)
        runtime_info = effective_disc_priority(
            host_priority,
            singer_override=self._singer_disc_priority_override(singer_name),
            max_items=10,
        )
        runtime_priority = runtime_info.get("effective", [])
        try:
            return pick_by_disc_priority(matches, runtime_priority)
        except Exception:
            return matches[0] if matches else None

    def _queue_song_from_history_record(self, target_singer: str, song: dict) -> bool:
        target_singer = str(target_singer or "").strip()
        if not target_singer or not isinstance(song, dict):
            return False

        track = self._resolve_history_song_track(song, target_singer)
        if not isinstance(track, dict):
            return False

        try:
            key = int(song.get("last_key") or 0)
        except Exception:
            key = 0
        try:
            tempo_percent = int(song.get("last_tempo_percent") or 100)
        except Exception:
            tempo_percent = 100

        path = str(track.get("path", "") or "").strip()
        ext = os.path.splitext(path)[1].lower()

        if ext == ".mp4":
            song_data = (path, key, tempo_percent)
        elif ext == ".cdg":
            mp3_path = self._find_matching_mp3_for_cdg(path)
            if not mp3_path:
                QMessageBox.warning(self, "Add To Tonight", f"Matching MP3 not found for:\n{path}")
                return False
            song_data = ((path, mp3_path), key, tempo_percent)
        elif ext == ".zip":
            if not self.is_mp3g_zip(path):
                QMessageBox.warning(self, "Add To Tonight", f"Invalid karaoke ZIP:\n{path}")
                return False
            song_data = (path, key, tempo_percent)
        else:
            song_data = (path, key, tempo_percent)

        self._add_song_to_queue(target_singer, song_data, track=track)
        return True

    def _queue_selected_singer_history_song(self):
        singer_key = self._selected_singer_history_key()
        song = self._selected_singer_history_song_record()
        if not singer_key or not isinstance(song, dict):
            return
        singer_record = self.singer_history.get("singers", {}).get(singer_key, {})
        default_singer = str(singer_record.get("name", "") or singer_key).strip()

        dlg = QDialog(self)
        dlg.setWindowTitle("Add To Tonight")
        dlg.setModal(True)
        dlg.setMinimumWidth(520)
        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            dlg.setStyleSheet(dialog_stylesheet(win, base, txtc))
        except Exception:
            pass

        layout = QVBoxLayout(dlg)
        title = QLabel("Add song to tonight's queue")
        title.setStyleSheet(f"color:{_v('text_bright')}; font-size:18px; font-weight:700;")
        layout.addWidget(title)

        summary = QLabel(self._history_song_display(song))
        summary.setStyleSheet(section_meta_css())
        summary.setWordWrap(True)
        layout.addWidget(summary)

        target_label = QLabel("Singer")
        target_label.setStyleSheet(section_meta_css())
        layout.addWidget(target_label)

        singer_combo = QComboBox(dlg)
        singer_combo.setEditable(True)
        singer_combo.setInsertPolicy(QComboBox.InsertPolicy.NoInsert)
        singer_combo.setStyleSheet(line_edit_css())
        singer_names = self._history_target_singer_names(default_singer)
        singer_combo.addItems(singer_names)
        if default_singer:
            idx = singer_combo.findText(default_singer, Qt.MatchFlag.MatchFixedString)
            if idx >= 0:
                singer_combo.setCurrentIndex(idx)
            singer_combo.setEditText(default_singer)
        layout.addWidget(singer_combo)

        note = QLabel("Defaults to this singer, but you can choose another singer or type a new one.")
        note.setStyleSheet(section_meta_css())
        note.setWordWrap(True)
        layout.addWidget(note)

        buttons = QDialogButtonBox(dlg)
        add_btn = buttons.addButton("Add To Tonight", QDialogButtonBox.ButtonRole.AcceptRole)
        edit_btn = buttons.addButton("Edit Song Instead", QDialogButtonBox.ButtonRole.ActionRole)
        buttons.addButton("Cancel", QDialogButtonBox.ButtonRole.RejectRole)
        layout.addWidget(buttons)

        def handle_add():
            target_singer = str(singer_combo.currentText() or "").strip()
            if not target_singer:
                QMessageBox.warning(dlg, "Add To Tonight", "Choose or enter a singer name.")
                return
            if not self._queue_song_from_history_record(target_singer, song):
                artist = str(song.get("artist", "") or "").strip()
                title_text = str(song.get("title", "") or "").strip()
                QMessageBox.warning(
                    dlg,
                    "Add To Tonight",
                    f"Could not match this history song to a local track:\n\n{artist} - {title_text}"
                )
                return
            dlg.accept()

        def handle_edit():
            dlg.accept()
            song_key = self._selected_singer_history_song_key()
            if singer_key and song_key:
                self._edit_history_song_dialog(singer_key, song_key)

        add_btn.clicked.connect(handle_add)
        edit_btn.clicked.connect(handle_edit)
        buttons.rejected.connect(dlg.reject)
        dlg.exec()

    def _edit_selected_singer_history_brand(self):
        if bool(getattr(self, "karaoke_playing", False)):
            return
        singer_key = self._selected_singer_history_key()
        record = self.singer_history.get("singers", {}).get(singer_key)
        if not isinstance(record, dict):
            return
        singer_name = str(record.get("name", "") or singer_key)
        dlg = QDialog(self)
        dlg.setWindowTitle(f"Preferred Brand: {singer_name}")
        dlg.setModal(True)
        dlg.setMinimumWidth(460)
        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            dlg.setStyleSheet(dialog_stylesheet(win, base, txtc))
        except Exception:
            pass
        layout = QVBoxLayout(dlg)
        label = QLabel(f"Preferred brand override for {singer_name}")
        layout.addWidget(label)
        edit = QLineEdit(dlg)
        edit.setText(str(record.get("preferred_disc_priority", "") or "").strip())
        edit.setPlaceholderText("KV, SC, SBI")
        layout.addWidget(edit)
        buttons = QDialogButtonBox(dlg)
        save_btn = buttons.addButton("Save", QDialogButtonBox.ButtonRole.AcceptRole)
        clear_btn = buttons.addButton("Clear", QDialogButtonBox.ButtonRole.ResetRole)
        buttons.addButton("Cancel", QDialogButtonBox.ButtonRole.RejectRole)
        layout.addWidget(buttons)

        def handle_save():
            value = ", ".join(normalize_disc_priority(edit.text(), max_items=10))
            self._set_singer_preference(singer_name, "preferred_disc_priority", value)
            dlg.accept()
