    def _active_queue_singer_names(self) -> list[str]:
        names: list[str] = []
        try:
            for singer in self.queue:
                if not isinstance(singer, dict):
                    continue
                if singer.get("skipped", False):
                    continue
                songs = singer.get("songs") or []
                has_playable = False
                for song in songs:
                    if isinstance(song, dict):
                        if not song.get("skipped", False):
                            has_playable = True
                            break
                    else:
                        has_playable = True
                        break
                if not has_playable:
                    continue
                name = str(singer.get("name", "") or "").strip()
                if name:
                    names.append(name)
        except Exception:
            return []
        return names

    def _send_stage_notifications_for_transition(self, current_singer_name: str):
        current_name = str(current_singer_name or "").strip()
        if not current_name:
            return
        try:
            enabled = bool(self.settings.get("enable_stage_notifications", True))
        except Exception:
            enabled = True
        if not enabled:
            return
        if not self.is_network_configured():
            return

        queue_names = self._active_queue_singer_names()
        next_name = queue_names[0] if len(queue_names) >= 1 else ""
        up_soon_name = queue_names[1] if len(queue_names) >= 2 else ""
        jobs = [
            (current_name, "up_now", "You're up now!"),
        ]
        if next_name:
            jobs.append((next_name, "on_deck", "You're on deck. Please be ready."))
        if up_soon_name:
            jobs.append((up_soon_name, "up_soon", "You're up soon."))

        def send():
            for singer_name, stage, message in jobs:
                ok, err = self._net_send_stage_notification(singer_name, stage, message)
                if not ok:
                    try:
                        print(f"[stage-notify] {stage} -> {singer_name}: {err}")
                    except Exception:
                        pass

        threading.Thread(target=send, daemon=True).start()

    def mark_top_of_rotation(self, singer_idx):
        """Set selected singer as the start of next rotation (yellow marker)."""
        if not self._is_rotation_mode():
            return
        if singer_idx < 0 or singer_idx >= len(self.queue):
            return
        self._rotation_set_marker_index(singer_idx)
        self.update_queue_display()
        try:
            self.save_data()
        except Exception:
            pass

    def _cancel_pending_singer_start_for_queue_change(self, reason: str) -> bool:
        """Invalidate an unconfirmed singer presentation after a queue edit."""
        cancelled = False
        pending_rollback = getattr(self, "_pending_play_start_rollback", None)
        if callable(pending_rollback):
            try:
                cancelled = bool(pending_rollback(str(reason or "queue_changed")))
            except Exception as exc:
                _diag(f"[PLAYNEXT] pending presentation rollback failed reason={reason}: {exc}")
        self._pending_playback_countdown_payload = None
        self._singer_start_generation = int(getattr(self, "_singer_start_generation", 0) or 0) + 1
        if cancelled:
            transport = getattr(self, "karaoke_transport", None)
            try:
                if transport is not None:
                    transport.stop()
            except Exception:
                pass
            if getattr(self, "karaoke_transport", None) is transport:
                self.karaoke_transport = None
            _diag(f"[PLAYNEXT] pending singer start cancelled reason={reason}")
        return cancelled

    def toggle_singer_skip(self, singer_idx):
        """Toggle skip status for a singer"""
        if 0 <= singer_idx < len(self.queue):
            target_singer = self.queue[singer_idx]
            self._cancel_pending_singer_start_for_queue_change("singer_skip_changed")
            try:
                singer_idx = next(i for i, queued in enumerate(self.queue) if queued is target_singer)
            except StopIteration:
                return
            undo = KaraokeApp._begin_undoable_action(self, "Skip Singer")
            self.queue[singer_idx]["skipped"] = not self.queue[singer_idx].get("skipped", False)
            self.update_queue_display()
            self.save_data()
            KaraokeApp._commit_undoable_action(self, undo, "Singer status changed")

    def toggle_song_skip(self, singer_idx, song_idx):
        """Toggle skip status for a song"""
        if 0 <= singer_idx < len(self.queue):
            target_singer = self.queue[singer_idx]
            songs = target_singer.get("songs", [])
            if 0 <= song_idx < len(songs):
                target_song = songs[song_idx]
                self._cancel_pending_singer_start_for_queue_change("song_skip_changed")
                try:
                    singer_idx = next(i for i, queued in enumerate(self.queue) if queued is target_singer)
                    songs = self.queue[singer_idx].get("songs", [])
                    song_idx = next(i for i, queued_song in enumerate(songs) if queued_song is target_song)
                except StopIteration:
                    return
                # Convert to dict format if needed
                if not isinstance(songs[song_idx], dict):
                    entry = songs[song_idx]
                    new_entry = {
                        "song_info": entry[0] if isinstance(entry, (tuple, list)) else entry,
                        "key": entry[1] if isinstance(entry, (tuple, list)) and len(entry) > 1 else 0,
                        "skipped": False
                    }
                    if isinstance(entry, (tuple, list)) and len(entry) >= 3:
                        new_entry["duet_display"] = entry[2]
                    songs[song_idx] = new_entry
                songs[song_idx]["skipped"] = not songs[song_idx].get("skipped", False)
                self.update_queue_display()
                self.save_data()

    def _queue_entry_song_info(self, entry):
        if isinstance(entry, dict):
            return entry.get("song_info")
        if isinstance(entry, (tuple, list)) and len(entry) >= 1:
            return entry[0]
        return entry

    def _queue_entry_key(self, entry) -> int:
        try:
            if isinstance(entry, dict):
                return int(entry.get("key", 0) or 0)
            if isinstance(entry, (tuple, list)) and len(entry) >= 2:
                return int(entry[1] or 0)
        except Exception:
            pass
        return 0

    def _queue_entry_duet_display(self, entry):
        if isinstance(entry, dict):
            return entry.get("duet_display")
        if isinstance(entry, (tuple, list)) and len(entry) >= 3:
            return entry[2]
        return None

    def _queue_singer_display_for_entry(self, singer: dict, entry=None) -> str:
        """Return display singer text while preserving duet partners.

        Queue ownership stays under the primary singer for rotation logic; this
        helper is only for display/export surfaces that should announce duet
        songs as "Singer 1 & Singer 2".
        """
        duet_display = str(self._queue_entry_duet_display(entry) or "").strip()
        if duet_display:
            return duet_display
        try:
            return str(singer.get("name", "") or "").strip()
        except Exception:
            return ""

    def _queue_entry_primary_path(self, entry) -> str:
        try:
            song_info = self._queue_entry_song_info(entry)
            if isinstance(song_info, (tuple, list)) and len(song_info) >= 1:
                return str(song_info[0] or "")
            return str(song_info or "")
        except Exception:
            return ""

    def _find_mp3_pair_for_cdg(self, cdg_path: str) -> str:
        base, _ = os.path.splitext(str(cdg_path or ""))
        for cand in (base + ".mp3", base + ".MP3"):
            if os.path.exists(cand):
                return cand
        try:
            p = Path(cdg_path)
            stem_l = p.stem.lower()
            for f in p.parent.iterdir():
                if f.is_file() and f.stem.lower() == stem_l and f.suffix.lower() == ".mp3":
                    return str(f)
        except Exception:
            pass
        return ""

    def _queue_entry_artist_title(self, entry) -> tuple[str, str]:
        artist = ""
        title = ""
        if isinstance(entry, dict):
            artist = str(entry.get("artist", "") or "").strip()
            title = str(entry.get("title", "") or "").strip()
            if artist and title:
                return artist, title
        try:
            p = self._queue_entry_primary_path(entry)
            if p:
                disp = self.lookup_display_name(p, artist_title_only=False)
                a2, t2, _d2 = self._split_display_artist_title_disc(str(disp or ""))
                artist = artist or a2
                title = title or t2
        except Exception:
            pass
        return artist.strip(), title.strip()

    def _find_discid_candidates(self, artist: str, title: str) -> list:
        artist_n = str(artist or "").strip().lower()
        title_n = str(title or "").strip().lower()
        # Strict mode for Change Disc ID: exact artist + exact title only.
        if not title_n or not artist_n:
            return []

        matched = []
        seen = set()
        for t in (self.tracks or []):
            path = str(t.get("path", "") or "")
            if not path:
                continue
            path_l = path.lower()
            if path_l in seen:
                continue

            ta = str(t.get("artist", "") or "").strip().lower()
            tt = str(t.get("title", "") or "").strip().lower()
            if not tt and not ta:
                continue

            if ta != artist_n or tt != title_n:
                continue

            track = {
                "artist": t.get("artist") or "",
                "title": t.get("title") or "",
                "discid": t.get("discid") or t.get("disc_id") or "",
                "disc_id": t.get("disc_id") or t.get("discid") or "",
                "duration": t.get("duration_secs") or t.get("duration") or "",
                "path": path,
                "type": t.get("type") or "",
                "display": t.get("display") or "",
            }
            seen.add(path_l)
            matched.append((str(track.get("disc_id", "") or "").upper(), track))

        matched.sort(key=lambda x: x[0])
        return [x[1] for x in matched]

    def _track_from_search_row(self, row: dict) -> dict:
        if not isinstance(row, dict):
            row = {}
        disc = row.get("discid") or row.get("disc_id") or row.get("disc") or ""
        return {
            "artist": row.get("artist") or "",
            "title": row.get("title") or "",
            "discid": disc,
            "disc_id": disc,
            "duration": row.get("duration_secs") or row.get("duration") or "",
            "duration_estimated": bool(row.get("duration_estimated", False)),
            "duration_source": row.get("duration_source") or "",
            "path": row.get("path") or "",
            "type": row.get("song_type") or row.get("type") or "",
            "display": row.get("display") or "",
            "songid": row.get("songid") or row.get("song_id") or row.get("id") or "",
            "provider": row.get("provider") or "local",
            "provider_track_id": row.get("provider_track_id") or "",
            "provider_url": row.get("provider_url") or "",
            "local_reference_path": row.get("local_reference_path") or "",
            "authorization_requirement": row.get("authorization_requirement") or "",
            "availability_status": row.get("availability_status") or "",
            "karafun_catalog_only": bool(row.get("karafun_catalog_only", False)),
        }

    def _build_queue_entry_from_track_choice(self, old_entry, track: dict):
        path = str(track.get("path", "") or "").strip()
        if not path:
            raise ValueError("Selected track has no valid path.")

        key = self._queue_entry_key(old_entry)
        duet_display = self._queue_entry_duet_display(old_entry)
        new_entry = dict(old_entry) if isinstance(old_entry, dict) else {}

        low = path.lower()
        if low.endswith(".cdg"):
            mp3_path = self._find_mp3_pair_for_cdg(path)
            if not mp3_path:
                raise FileNotFoundError(f"Matching MP3 not found for CDG:\n{path}")
            song_info = (path, mp3_path)
            song_type = "cdg"
        elif low.endswith(".zip"):
            song_info = path
            song_type = "mp3g"
        elif low.endswith(".mp4"):
            song_info = path
            song_type = "mp4"
        elif low.endswith(".mp3"):
            song_info = path
            song_type = "mp3"
        else:
            song_info = path
            song_type = str(track.get("type") or "")

        artist = str(track.get("artist") or "").strip()
        title = str(track.get("title") or "").strip()
        disc_id = str(track.get("disc_id") or track.get("discid") or "").strip()
        display = str(track.get("display") or "").strip()
        if not display:
            display = " - ".join([p for p in (artist, title, disc_id) if p])

        new_entry.update({
            "song_info": song_info,
            "key": key,
            "duet_display": duet_display,
            "artist": artist,
            "title": title,
            "duration": track.get("duration") or track.get("duration_secs"),
            "disc_id": disc_id,
            "display": display,
            "display_name": display,
            "path": path,
            "type": song_type,
        })
        for _provider_key in (
            "provider",
            "provider_track_id",
            "provider_url",
            "local_reference_path",
            "authorization_requirement",
            "availability_status",
        ):
            if track.get(_provider_key) not in (None, ""):
                new_entry[_provider_key] = track.get(_provider_key)
        if "songid" in track or "song_id" in track:
            new_entry["songid"] = str(track.get("songid") or track.get("song_id") or "").strip()
        if "tempo_percent" not in new_entry and isinstance(old_entry, (tuple, list)) and len(old_entry) >= 3:
            try:
                if isinstance(old_entry[2], (int, float)):
                    new_entry["tempo_percent"] = int(old_entry[2])
            except Exception:
                pass
        return new_entry

    def _replace_queue_song_with_track(self, singer_idx: int, song_idx: int, track: dict, source: str = "replace_track"):
        if singer_idx < 0 or singer_idx >= len(self.queue):
            return False
        songs = self.queue[singer_idx].get("songs", [])
        if song_idx < 0 or song_idx >= len(songs):
            return False
        undo = KaraokeApp._begin_undoable_action(self, "Replace Song")

        singer_name = str(self.queue[singer_idx].get("name", "") or "").strip()
        old_entry = songs[song_idx]
        old_artist, old_title = self._queue_entry_artist_title(old_entry)
        new_entry = self._build_queue_entry_from_track_choice(old_entry, track)
        new_artist, new_title = self._queue_entry_artist_title(new_entry)
        songs[song_idx] = new_entry
        try:
            self._queue_revision = int(getattr(self, "_queue_revision", 0)) + 1
        except Exception:
            self._queue_revision = 1
        request_id = self._queue_entry_remote_request_id(new_entry)
        try:
            tempo_percent = int(new_entry.get("tempo_percent") or 100)
        except Exception:
            tempo_percent = 100
        _diag(
            "[REPLACE-TRACK] "
            f"source={source} singer={singer_name!r} request_id={request_id or ''} "
            f"old={old_artist!r}/{old_title!r} new={new_artist!r}/{new_title!r} "
            f"key={self._queue_entry_key(new_entry):+d} tempo={tempo_percent}% "
            f"revision={int(getattr(self, '_queue_revision', 0) or 0)}"
        )
        self.update_queue_display()
        self.save_data()
        try:
            self._schedule_next_up_prescan()
        except Exception:
            pass
        try:
            self.post_rotation()
        except Exception:
            pass
        self._push_remote_request_replacement(
            new_entry,
            singer_name=singer_name,
            old_artist=old_artist,
            old_title=old_title,
            source=source,
        )
        KaraokeApp._commit_undoable_action(self, undo, "Song replaced")
        return True

    def _push_remote_request_replacement(self, entry, *, singer_name: str = "", old_artist: str = "", old_title: str = "", source: str = "replace_track"):
        request_id = self._queue_entry_remote_request_id(entry)
        if request_id is None:
            _diag(f"[REPLACE-TRACK] local-only replacement synced through rotation mirror source={source}")
            return
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        if not base_url or not tenant or not api_key:
            _diag(f"[REPLACE-TRACK] queued unsynced request_id={request_id} reason=network_not_configured")
            return

        artist, title = self._queue_entry_artist_title(entry)
        try:
            song_key = int(entry.get("key") or 0)
        except Exception:
            song_key = 0
        try:
            tempo_offset = int(entry.get("tempo_percent") or 100) - 100
        except Exception:
            tempo_offset = 0
        payload = {
            "user": tenant,
            "request_id": int(request_id),
            "singer_name": singer_name,
            "old_artist": old_artist,
            "old_title": old_title,
            "artist": artist,
            "title": title,
            "songid": entry.get("songid", ""),
            "disc_id": entry.get("disc_id", ""),
            "path": self._queue_entry_primary_path(entry) or str(entry.get("path") or ""),
            "duration": entry.get("duration", ""),
            "song_key": song_key,
            "tempo": tempo_offset,
            "source": source,
        }

        import threading

        def send():
            headers = {"X-API-Key": api_key, "Accept": "application/json", "User-Agent": "SingWS/replace-track"}
            try:
                resp = requests.post(
                    f"{base_url}/api/v1/replace_remote_request.php",
                    data=payload,
                    headers=headers,
                    timeout=6,
                )
                if 200 <= resp.status_code < 300:
                    _diag(f"[REPLACE-TRACK] server accepted request_id={request_id} status={resp.status_code}")
                else:
                    print(f"[REPLACE-TRACK] HTTP {resp.status_code}: {resp.text[:180]}")
            except Exception as e:
                print(f"[REPLACE-TRACK] Failed to sync request {request_id}: {e}")

        threading.Thread(target=send, daemon=True).start()


    def open_replace_track_dialog(self, singer_idx: int, song_idx: int):
        if singer_idx < 0 or singer_idx >= len(self.queue):
            return
        songs = self.queue[singer_idx].get("songs", [])
        if song_idx < 0 or song_idx >= len(songs):
            return

        old_entry = songs[song_idx]
        old_artist, old_title = self._queue_entry_artist_title(old_entry)
        old_label = f"{old_artist} - {old_title}".strip(" -") or "selected track"

        class _ReplaceTrackDialog(QDialog):
            def __init__(self, parent=None):
                super().__init__(parent)
                self._on_resize_cb = None
            def resizeEvent(self, event):
                super().resizeEvent(event)
                cb = getattr(self, "_on_resize_cb", None)
                if cb is not None:
                    try:
                        cb()
                    except Exception:
                        pass

        dlg = _ReplaceTrackDialog(self)
        dlg.setWindowTitle("Replace Track")
        dlg.setMinimumSize(560, 340)
        try:
            geo_hex = str((self.settings or {}).get("replace_track_dialog_geometry", "") or "").strip()
            if not (geo_hex and dlg.restoreGeometry(QByteArray.fromHex(geo_hex.encode("ascii")))):
                sz = (self.settings or {}).get("replace_track_dialog_size") or {}
                dlg.resize(max(560, int(sz.get("w", 900))), max(340, int(sz.get("h", 540))))
        except Exception:
            dlg.resize(900, 540)

        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            border = base.darker(120)
            field_bg = base.darker(105)
            dlg.setStyleSheet(
                dialog_stylesheet(win, base, txtc)
                + f"""
                QListWidget {{
                    background-color: {field_bg.name()};
                    color: {txtc.name()};
                    border: 1px solid {border.name()};
                    border-radius: 8px;
                    outline: none;
                }}
                QListWidget::item {{ padding: 2px 6px; }}
                QListWidget::item:selected {{
                    background-color: palette(highlight);
                    color: palette(highlighted-text);
                }}
                """
            )
        except Exception:
            pass

        v = QVBoxLayout(dlg)
        search = QLineEdit(dlg)
        search.setPlaceholderText("Search replacement song...")
        search.setClearButtonEnabled(True)
        v.addWidget(search)

        results = QListWidget(dlg)
        results.setAlternatingRowColors(True)
        results.setUniformItemSizes(True)
        results.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        results.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        results.setItemDelegate(
            RightAlignedMetaDelegate(
                self._row_left_role,
                self._row_right_role,
                results,
                compact_shift_ratio=0.0,
                edge_pad_px=2,
                gap_px=12,
                force_scrollbar_reserve_px=0,
            )
        )
        v.addWidget(results, 1)

        confirm = QLabel(f"Replace '{old_label}' with a selected track?")
        confirm.setWordWrap(True)
        confirm.setStyleSheet(f"color: {_v('warning')}; font-weight: 700;")
        v.addWidget(confirm)

        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Cancel, parent=dlg)
        replace_btn = btns.addButton("Replace", QDialogButtonBox.ButtonRole.AcceptRole)
        replace_btn.setEnabled(False)
        v.addWidget(btns)

        search_state = {"job_id": 0, "thread": None}
        search_timer = QTimer(dlg)
        search_timer.setSingleShot(True)
        search_timer.setInterval(max(120, int(self._effective_search_debounce_ms() * 0.7)))

        def current_track():
            item = results.currentItem()
            if item is None:
                return None
            track = item.data(Qt.ItemDataRole.UserRole)
            return track if isinstance(track, dict) else None

        def refresh_confirm():
            track = current_track()
            replace_btn.setEnabled(track is not None)
            if not track:
                confirm.setText(f"Replace '{old_label}' with a selected track?")
                return
            new_artist = str(track.get("artist") or "").strip()
            new_title = str(track.get("title") or "").strip()
            new_label = f"{new_artist} - {new_title}".strip(" -") or str(track.get("display") or "replacement track")
            confirm.setText(f"Replace '{old_label}' with '{new_label}'?")

        def add_rows(rows):
            results.setUpdatesEnabled(False)
            try:
                results.clear()
                for r in rows or []:
                    try:
                        track = self._track_from_search_row(r)
                        if not str(track.get("path") or "").strip():
                            continue
                        _label, tooltip, left, right = self._build_search_row_text(track)
                        item = QListWidgetItem(left)
                        item.setData(Qt.ItemDataRole.UserRole, track)
                        self._set_aligned_row_meta(item, left, right)
                        item.setData(self._row_disc_role, str(track.get("disc_id") or "").strip())
                        try:
                            item.setToolTip(tooltip)
                        except Exception:
                            pass
                        results.addItem(item)
                    except Exception:
                        continue
            finally:
                results.setUpdatesEnabled(True)
            if results.count() > 0:
                results.setCurrentRow(0)
            refresh_confirm()

        def on_results(job_id, rows):
            if int(job_id) != int(search_state.get("job_id") or 0):
                return
            if not str(search.text() or "").strip():
                results.clear()
                refresh_confirm()
                return
            add_rows(rows)

        def start_search():
            query = str(search.text() or "").strip()
            search_state["job_id"] = int(search_state.get("job_id") or 0) + 1
            job_id = int(search_state["job_id"])
            # Retire before the empty-query check, not after. Backspacing the
            # box to nothing has to stand the in-flight search down too --
            # otherwise it keeps scanning the library for a result that is
            # already discarded, and it is still running when the next
            # keystroke or the dialog close comes to replace it.
            _retire_search_thread(search_state)
            if not query:
                results.clear()
                refresh_confirm()
                return
            thread = SongSearchThread(
                job_id,
                query,
                limit=250,
                fuzzy=True,
                karafun_search_url=(
                    _network_normalize_base_url(self.settings.get("base_url", "")) + "/karafun_search.php"
                    if bool(self.settings.get("karafun_provider_enabled", True))
                    and bool(self.settings.get("karafun_include_online_search", False))
                    else ""
                ),
                karafun_tenant=str(self.settings.get("user", self.settings.get("tenant", "")) or ""),
            )
            thread.results_ready.connect(on_results)
            search_state["thread"] = thread
            thread.start()

        def apply_choice():
            track = current_track()
            if not isinstance(track, dict):
                return
            try:
                provider = str(track.get("provider") or "local").strip().lower()
                if "karafun" in provider:
                    track_id = str(track.get("provider_track_id") or track.get("songid") or "").strip()
                    availability = str(track.get("availability_status") or "").strip().lower()
                    if not track_id or availability in {"unavailable", "invalid", "removed"}:
                        raise ValueError("This KaraFun result is unavailable or no longer has a valid track ID.")
                if self._replace_queue_song_with_track(singer_idx, song_idx, track, source="replace_track_dialog"):
                    dlg.accept()
            except Exception as e:
                QMessageBox.warning(dlg, "Replace Track", str(e))

        def refresh_rows_for_width():
            try:
                current = results.currentRow()
                for i in range(results.count()):
                    it = results.item(i)
                    track = it.data(Qt.ItemDataRole.UserRole)
                    if not isinstance(track, dict):
                        continue
                    _label, tooltip, left, right = self._build_search_row_text(track)
                    it.setText(left)
                    self._set_aligned_row_meta(it, left, right)
                    try:
                        it.setToolTip(tooltip)
                    except Exception:
                        pass
                if 0 <= current < results.count():
                    results.setCurrentRow(current)
            except Exception:
                pass

        resize_refresh_timer = QTimer(dlg)
        resize_refresh_timer.setSingleShot(True)
        resize_refresh_timer.timeout.connect(refresh_rows_for_width)
        dlg._on_resize_cb = lambda: resize_refresh_timer.start(20)
        search.textChanged.connect(lambda *_: search_timer.start())
        search.returnPressed.connect(apply_choice)
        search_timer.timeout.connect(start_search)
        results.itemSelectionChanged.connect(refresh_confirm)
        results.itemDoubleClicked.connect(lambda *_: apply_choice())
        btns.accepted.connect(apply_choice)
        btns.rejected.connect(dlg.reject)

        def persist_size():
            try:
                s = dlg.size()
                self.settings["replace_track_dialog_size"] = {"w": int(s.width()), "h": int(s.height())}
                try:
                    self.settings["replace_track_dialog_geometry"] = bytes(dlg.saveGeometry().toHex()).decode("ascii")
                except Exception:
                    pass
                self.save_settings()
            except Exception:
                pass
            _retire_search_thread(search_state)

        dlg.finished.connect(lambda _r: persist_size())
        try:
            seed = " ".join([p for p in (old_artist, old_title) if p]).strip()
            if seed:
                search.setText(seed)
                search.selectAll()
                search_timer.start(10)
        except Exception:
            pass
        search.setFocus(Qt.FocusReason.PopupFocusReason)
        dlg.exec()


