    def closeEvent(self, event):
        """Close main window -> quit whole app.

        - If karaoke is playing, confirm before quitting.
        - Save main-window geometry to settings.json.
        - Stop playback + background music + polling threads.
        """
        # Join the brand-choices worker thread first: destroying a running
        # QThread during teardown aborts the process.
        try:
            worker = getattr(self, "_history_brand_choices_worker", None)
            if worker is not None and hasattr(worker, "cancel"):
                worker.cancel()
            thread = getattr(self, "_history_brand_choices_thread", None)
            if thread is not None:
                thread.quit()
                thread.wait(2000)
        except Exception:
            pass
        # If a karaoke track is playing, ask before quitting.
        try:
            is_playing = bool(getattr(self, "karaoke_playing", False))
        except Exception:
            is_playing = False

        if is_playing:
            try:
                from PyQt6.QtWidgets import QMessageBox
                btn = QMessageBox.question(
                    self,
                    "Quit SingWS?",
                    "A karaoke track is currently playing. Quit SingWS and stop playback?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No
                )
                if btn != QMessageBox.StandardButton.Yes:
                    event.ignore()
                    return
            except Exception:
                event.ignore()
                return

        self._app_closing = True
        try:
            global _QT_APP_SHUTTING_DOWN
            _QT_APP_SHUTTING_DOWN = True
        except Exception:
            pass
        self._mt_watch_stop = True

        # Save window geometry (position/size) for next launch
        try:
            self._capture_window_geometry_settings()
            try:
                self._save_operator_splitter_sizes()
            except Exception:
                pass
            try:
                self.save_settings()
            except Exception:
                pass
        except Exception:
            pass

        # Flush the queue/history synchronously on the way out. Saves are
        # debounced and now always run on a worker, so quitting could otherwise
        # land between the last edit and its write and lose it. This is the one
        # place that must not be deferred.
        try:
            timer = getattr(self, "_save_data_timer", None)
            if timer is not None:
                timer.stop()
        except Exception:
            pass
        try:
            self.save_data()
        except Exception as e:
            _diag(f"[SHUTDOWN] final queue save failed: {e}")

        # Stop karaoke playback cleanly
        try:
            if is_playing and hasattr(self, "stop_playback"):
                self.stop_playback(skip_confirmation=True)
        except Exception:
            pass

        # Stop background music
        try:
            if hasattr(self, "bg_music") and self.bg_music:
                self.bg_music.stop()
        except Exception as e:
            print("Background music stop failed:", e)

        try:
            strip = getattr(self, "soundboard_strip", None)
            if strip is not None and hasattr(strip, "stop_all"):
                strip.stop_all()
        except Exception as e:
            print("Soundboard stop failed:", e)

        # Mark the live session location inactive on normal app exit.
        try:
            self.sync_session_location(active=False)
        except Exception as e:
            print("Session location shutdown sync failed:", e)

        try:
            timer = getattr(self, "_daw_snapshot_timer", None)
            if timer is not None:
                timer.stop()
            self._daw_snapshot_inflight = False
        except Exception:
            pass

        # --- Stop network relays/polling cleanly ---
        self._shutdown_network_transports()

        # Close secondary windows (karaoke output, preview, etc.)
        try:
            if hasattr(self, "video_window") and self.video_window:
                try:
                    self.video_window.close()
                except Exception:
                    pass
        except Exception:
            pass
        try:
            if hasattr(self, "preview_window") and self.preview_window:
                try:
                    self.preview_window.close()
                except Exception:
                    pass
        except Exception:
            pass

        # PROCESSED_DIR cleanup removed - no longer needed

        # Ask a filesystem scan to stop before tearing down its QThread. The
        # worker checks this flag between directories and file batches, so the
        # app can close without leaving a scan running against an external
        # volume.
        try:
            self._cancel_library_scan()
        except Exception:
            pass

        # Cancel any background ZIP extraction before temp cleanup.
        try:
            worker = getattr(self, "_zip_extract_worker", None)
            if worker is not None and hasattr(worker, "cancel"):
                worker.cancel()
        except Exception:
            pass
        try:
            thread = getattr(self, "_zip_extract_thread", None)
            if thread is not None and thread.isRunning():
                thread.requestInterruption()
                thread.quit()
                thread.wait(500)
        except Exception:
            pass

        # Clean up zip cache
        try:
            if hasattr(self, "zip_cache") and self.zip_cache:
                self.zip_cache.cleanup()
        except Exception as e:
            print("Zip cache cleanup failed:", e)

        # Persist state
        try:
            self._save_deferred_remote_adds()
        except Exception:
            pass
        try:
            self.save_data()
        except Exception:
            pass

        # Proceed with normal close, then quit application (even if other windows exist).
        try:
            super().closeEvent(event)
        finally:
            try:
                from PyQt6.QtWidgets import QApplication
                QApplication.instance().quit()
            except Exception:
                pass

    def _tracks_state(self) -> dict:
        """Backing store for the ``tracks`` property.

        Created on demand so it does not depend on __init__ ordering: the
        property is used before the point where instance attributes are
        normally set up.
        """
        # Key must not be "_tracks_state": an entry in the instance __dict__
        # shadows the method of the same name, so the second call would try to
        # invoke the dict.
        state = self.__dict__.get("_tracks_state_data")
        if state is None:
            state = {"lock": threading.Lock(), "value": [], "ready": False, "thread": None}
            self.__dict__["_tracks_state_data"] = state
        return state

    def _start_tracks_prefetch(self) -> None:
        """Parse tracks.json on a worker instead of blocking startup.

        This library is ~134k rows, which is ~800ms of JSON parse on the GUI
        thread, and it ran inside __init__ -- before the window could paint.
        Nothing during startup needs it: song search goes through the SQLite
        index, and the remaining consumers (songbook export/upload, rescan,
        duration scan, display-name lookup) are all operator-initiated. The
        ``tracks`` property joins this worker if anything asks early, so the
        deferral cannot produce a half-loaded library.
        """
        state = self._tracks_state()
        started = time.perf_counter()

        def _work():
            data = _load_json_file(TRACKS_PATH, [], expected_type=list, label="Tracks")
            elapsed_ms = (time.perf_counter() - started) * 1000.0
            with state["lock"]:
                # An explicit assignment (rescan, library removal) that landed
                # while this was in flight wins; do not clobber it.
                if not state["ready"]:
                    state["value"] = data
                    state["ready"] = True
                    loaded = len(data)
                else:
                    loaded = -1
            if loaded >= 0:
                _perf_log_if_slow("library_startup_load", elapsed_ms)
                _diag(f"[LIBRARY-LOAD] tracks={loaded:,} elapsed_ms={elapsed_ms:.1f} thread=worker")
            else:
                _diag("[LIBRARY-LOAD] worker result discarded; tracks were reassigned during load")

        with state["lock"]:
            state["ready"] = False
            state["value"] = []
        thread = threading.Thread(target=_work, daemon=True, name="singws-tracks-load")
        state["thread"] = thread
        thread.start()

    @property
    def tracks(self):
        state = self._tracks_state()
        thread = state.get("thread")
        if thread is not None and thread.is_alive():
            blocked_at = time.perf_counter()
            thread.join()
            waited_ms = (time.perf_counter() - blocked_at) * 1000.0
            if waited_ms >= 1.0:
                _diag(f"[LIBRARY-LOAD] caller waited {waited_ms:.0f}ms for tracks.json")
        with state["lock"]:
            return state["value"]

    @tracks.setter
    def tracks(self, value):
        state = self._tracks_state()
        with state["lock"]:
            state["value"] = value if isinstance(value, list) else list(value or [])
            state["ready"] = True

    def load_data(self):
        self._start_tracks_prefetch()
        # Old in-memory index removed - now using DB lookups
        self.singer_history = {"singers": {}}
        try:
            if SINGER_HISTORY_PATH.exists():
                raw_history = _load_json_file(SINGER_HISTORY_PATH, {"singers": {}}, expected_type=dict, label="Singer history")
                normalized_history = self._normalize_singer_history_store(raw_history)
            elif SINGER_PREFS_PATH.exists():
                raw_prefs = _load_json_file(SINGER_PREFS_PATH, {}, expected_type=dict, label="Singer preferences")
                normalized_history = self._normalize_singer_history_store({"singers": raw_prefs})
            else:
                normalized_history = {"singers": {}}
            self.singer_history = normalized_history
            self.singer_preferences = {
                key: {
                    "name": value.get("name", ""),
                    "preferred_disc_priority": value.get("preferred_disc_priority", ""),
                }
                for key, value in self.singer_history.get("singers", {}).items()
            }
        except Exception:
            self.singer_preferences = {}
            self.singer_history = {"singers": {}}
        self.queue = _load_json_file(QUEUE_PATH, [], expected_type=list, label="Queue")
        # DATA MIGRATION: Add skip flags and has_sung tracking
        valid_queue = []
        for singer in self.queue:
            if not isinstance(singer, dict):
                continue
            self._ensure_singer_id(singer)
            if "skipped" not in singer:
                singer["skipped"] = False
            # NEW: Add has_sung field - default to True for existing singers
            # (assumes if they're already in the queue from a previous session, they may have sung)
            if "has_sung" not in singer:
                singer["has_sung"] = True  # Existing singers default to "already sang"
            # Round marker for rotation mode (defaults to unsung each launch).
            if "round_sung" not in singer:
                singer["round_sung"] = False
            if "rotation_marker" not in singer:
                singer["rotation_marker"] = False
            new_songs = []
            for song_idx, entry in enumerate(singer.get("songs", [])):
                if isinstance(entry, dict) and "song_info" in entry:
                    if "skipped" not in entry:
                        entry["skipped"] = False
                    if self._is_external_karafun_entry(entry):
                        self._ensure_karafun_duration_estimate(entry)
                    new_songs.append(entry)
                    self._ensure_queue_entry_id(entry)
                else:
                    if isinstance(entry, (tuple, list)):
                        song_dict = {
                            "song_info": entry[0] if len(entry) > 0 else None,
                            "key": entry[1] if len(entry) > 1 else 0,
                            "skipped": False
                        }
                        if len(entry) >= 3:
                            song_dict["duet_display"] = entry[2]
                        new_songs.append(song_dict)
                    else:
                        new_songs.append({"song_info": entry, "key": 0, "skipped": False})
            singer["songs"] = new_songs
            singer_name_key = self._normalize_singer_pref_key(singer.get("name", ""))
            if singer_name_key:
                pref = self.singer_preferences.get(singer_name_key, {})
                pref_disc = ", ".join(normalize_disc_priority(
                    singer.get("preferred_disc_priority", "") or pref.get("preferred_disc_priority", ""),
                    max_items=10,
                ))
                if pref_disc:
                    singer["preferred_disc_priority"] = pref_disc
                else:
                    singer.pop("preferred_disc_priority", None)
            valid_queue.append(singer)
        self.queue = valid_queue
        # Safety net: a queue saved by an older build (or a racing client)
        # may contain duplicate singer names — collapse them on load so
        # duplicates never survive a restart.
        try:
            self._merge_duplicate_rotation_singers(reason="load_data")
        except Exception:
            pass

    def _bootstrap_bg_playlist_on_startup(self):
        """Load persisted BG playlist into player so main BG card is populated on launch."""
        try:
            if getattr(self.bg_music, "playlist", None):
                return
            p = APP_USER_DIR / "bg_playlist.json"
            if not p.exists():
                return
            with open(p, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, list):
                return
            paths = []
            for item in data:
                if isinstance(item, dict):
                    track_path = item.get("path")
                elif isinstance(item, str):
                    track_path = item
                else:
                    track_path = None
                if track_path:
                    track_path = str(track_path)
                    if os.path.exists(track_path):
                        paths.append(track_path)
            if not paths:
                return
            self.bg_music.playlist = paths
            self.bg_music.current_index = 0
            print(f"[BG] Startup loaded playlist with {len(paths)} track(s)")
            # Prescan the first source on a worker. BASS_STREAM_PRESCAN can
            # take multiple seconds on network/large files and must never run
            # from a zero-delay GUI timer during launch.
            try:
                QTimer.singleShot(0, self.bg_music.preload_current_track_paused_async)
            except Exception:
                pass
        except Exception as e:
            print(f"[BG] Startup playlist load failed: {e}")

    def save_data(self):
        _perf_t0 = time.perf_counter()
        # Only save the queue every minute
        _save_json_atomic(QUEUE_PATH, self.queue)
        try:
            _save_json_atomic(SINGER_HISTORY_PATH, self.singer_history)
        except Exception:
            pass
        try:
            _save_json_atomic(SINGER_PREFS_PATH, self.singer_preferences)
        except Exception:
            pass
        _perf_log_if_slow("json_save_data", (time.perf_counter() - _perf_t0) * 1000.0)
            
    def export_songbook_csv(self):
        import csv
        from PyQt6.QtWidgets import QFileDialog, QMessageBox

        filename, _ = QFileDialog.getSaveFileName(self, "Export Songbook CSV", "songbook.csv", "CSV Files (*.csv)")
        if not filename:
            return

        # Try database first (faster), fall back to tracks list
        rows = []
        try:
            dbf = song_index.db_path()
            if dbf.exists():
                # Export from database (much faster for large libraries)
                con = song_index._connect(dbf)
                db_rows = con.execute(
                    "SELECT DISTINCT artist, title FROM songs WHERE artist IS NOT NULL AND title IS NOT NULL ORDER BY artist, title"
                ).fetchall()
                con.close()
                rows = [(r["artist"].strip(), r["title"].strip()) for r in db_rows if r["artist"] and r["title"]]
            else:
                raise FileNotFoundError("DB not found, using tracks list")
        except Exception:
            # Fallback to in-memory tracks list
            seen = set()
            for track in self.tracks:
                artist = track.get("artist", "").strip()
                title = track.get("title", "").strip()
                key = (artist.lower(), title.lower())
                if not artist or not title or key in seen:
                    continue
                seen.add(key)
                rows.append((artist, title))
            rows.sort(key=lambda x: (x[0].lower(), x[1].lower()))

        try:
            with open(filename, "w", newline='', encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(["Artist", "Title"])
                writer.writerows(rows)
            QMessageBox.information(self, "Export Complete", f"Exported {len(rows)} songs to:\n{filename}")
        except Exception as e:
            QMessageBox.critical(self, "Export Failed", f"Could not write CSV:\n{e}")

    def _library_locations(self) -> list[dict]:
        locations, changed = _migrate_library_locations(self.settings)
        if changed:
            self.save_settings()
        return locations

    def _add_library_location(self, path: str, start_scan: bool = True) -> tuple[bool, str]:
        normalized = _normalize_library_location_path(path)
        if not normalized:
            return False, "Choose a library folder."
        locations = self._library_locations()
        if any(_library_location_key(item.get("path", "")) == _library_location_key(normalized) for item in locations):
            return False, "That library location is already configured."
        location = {
            "id": _library_location_id(normalized),
            "path": normalized,
            "added_at": time.time(),
            "last_scan_at": 0,
            "last_scan_status": "not scanned",
            "last_track_count": 0,
        }
        locations.append(location)
        self.settings["karaoke_library_locations"] = locations
        self.settings["karaoke_scan_roots"] = [item["path"] for item in locations]
        self.save_settings()
        if start_scan and os.path.isdir(normalized):
            self._scan_library_locations([location["id"]], full=True)
        return True, ""

    def _remove_library_location(self, location_id: str) -> bool:
        locations = self._library_locations()
        removed = next((item for item in locations if item.get("id") == location_id), None)
        if removed is None:
            return False
        remaining = [item for item in locations if item.get("id") != location_id]
        self.tracks = _tracks_after_library_location_removed(
            list(getattr(self, "tracks", []) or []), removed.get("path", ""), remaining
        )
        self.settings["karaoke_library_locations"] = remaining
        self.settings["karaoke_scan_roots"] = [item["path"] for item in remaining]
        signatures = self.settings.get("karaoke_scan_dir_sigs", {}) or {}
        self.settings["karaoke_scan_dir_sigs"] = {
            path: sig for path, sig in signatures.items()
            if not _path_is_within_library(path, removed.get("path", ""))
            or any(_path_is_within_library(path, item.get("path", "")) for item in remaining)
        }
        self.save_settings()
        _save_json_atomic(TRACKS_PATH, self.tracks)
        try:
            self._display_name_cache = {}
            self._rebind_queue_entries_to_tracks()
            self.search_tracks()
            self.update_queue_display()
            self.ensure_song_index_async(force=True)
        except Exception as e:
            print(f"Post-removal library refresh failed: {e}")
        return True

    def _scan_library_locations(self, location_ids=None, full: bool = False) -> bool:
        try:
            thread = getattr(self, "_library_scan_thread", None)
            if thread is not None and thread.isRunning():
                self._show_processing_notification("Library scan already running.", level="info")
                return False
        except Exception:
            pass
        locations = self._library_locations()
        selected_ids = set(location_ids or [item.get("id") for item in locations])
        selected = [item for item in locations if item.get("id") in selected_ids]
        if not selected:
            return False
        self.settings["karaoke_library_locations"] = locations
        for item in selected:
            item["last_scan_status"] = "scanning"
        self.save_settings()
        self._pending_library_scan_ids = [item.get("id") for item in selected]
        return self._start_library_scan_worker(
            [item.get("path") for item in selected],
            quick_mode=not bool(full),
            preserve_outside=True,
        )

    def open_library_locations_dialog(self):
        dialog = QDialog(self)
        dialog.setWindowTitle("Karaoke Library Locations")
        dialog.setMinimumSize(720, 390)
        layout = QVBoxLayout(dialog)
        intro = QLabel(
            "Songs from every available location are searched as one library. "
            "Offline drives stay configured and reconnect automatically when mounted again."
        )
        intro.setWordWrap(True)
        layout.addWidget(intro)
        location_list = QListWidget(dialog)
        layout.addWidget(location_list, 1)

        def refresh():
            current_id = None
            if location_list.currentItem() is not None:
                current_id = location_list.currentItem().data(Qt.ItemDataRole.UserRole)
            location_list.clear()
            tracks = list(getattr(self, "tracks", []) or [])
            track_path_keys = [
                _scanned_library_path_key(track.get("path", ""))
                for track in tracks if isinstance(track, dict) and track.get("path")
            ]
            for location in self._library_locations():
                path = location.get("path", "")
                scan_status = str(location.get("last_scan_status") or "not scanned")
                online = scan_status != "offline"
                root_key = _scanned_library_path_key(path)
                count = sum(
                    1 for path_key in track_path_keys
                    if path_key == root_key or path_key.startswith(root_key + os.sep)
                )
                status = "Configured" if online else "Offline"
                row = QListWidgetItem(f"{status}  •  {count:,} songs  •  {scan_status}\n{path}")
                row.setData(Qt.ItemDataRole.UserRole, location.get("id"))
                if not online:
                    row.setToolTip("The location is unavailable. Its settings and song records are preserved.")
                location_list.addItem(row)
                if location.get("id") == current_id:
                    location_list.setCurrentItem(row)
            try:
                thread = getattr(self, "_library_scan_thread", None)
                scanning = bool(thread is not None and thread.isRunning())
            except Exception:
                scanning = False
            rescan_button.setEnabled(not scanning)
            rescan_all_button.setEnabled(not scanning)
            full_rescan_button.setEnabled(not scanning)
            remove_button.setEnabled(not scanning)
            cancel_scan_button.setEnabled(scanning)

        buttons = QHBoxLayout()
        add_button = QPushButton("Add Library Location…")
        rescan_button = QPushButton("Update Selected")
        rescan_all_button = QPushButton("Update All Available")
        full_rescan_button = QPushButton("Full Rescan Selected…")
        remove_button = QPushButton("Remove Selected")
        cancel_scan_button = QPushButton("Cancel Scan")
        close_button = QPushButton("Close")
        for button in (add_button, rescan_button, rescan_all_button, full_rescan_button, remove_button):
            buttons.addWidget(button)
        buttons.addWidget(cancel_scan_button)
        buttons.addStretch(1)
        buttons.addWidget(close_button)
        layout.addLayout(buttons)

        def selected_id():
            item = location_list.currentItem()
            return item.data(Qt.ItemDataRole.UserRole) if item is not None else None

        def add_location():
            folder = QFileDialog.getExistingDirectory(self, "Add Library Location")
            if not folder:
                return
            added, message = self._add_library_location(folder, start_scan=True)
            if not added:
                QMessageBox.information(dialog, "Library Location", message)
            refresh()

        def rescan_selected():
            location_id = selected_id()
            if not location_id:
                return
            self._scan_library_locations([location_id], full=False)
            refresh()

        def full_rescan_selected():
            location_id = selected_id()
            if not location_id:
                return
            answer = QMessageBox.question(
                dialog,
                "Full Library Rescan",
                "Re-read every file in the selected library?\n\n"
                "Use this only to repair metadata. A normal Update is much faster "
                "and already detects added, changed, moved, and removed files.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.Cancel,
                QMessageBox.StandardButton.Cancel,
            )
            if answer != QMessageBox.StandardButton.Yes:
                return
            self._scan_library_locations([location_id], full=True)
            refresh()

        def remove_selected():
            location_id = selected_id()
            location = next((x for x in self._library_locations() if x.get("id") == location_id), None)
            if not location:
                return
            answer = QMessageBox.question(
                dialog, "Remove Library Location",
                f"Remove this location from the combined library?\n\n{location.get('path', '')}\n\n"
                "Files on disk will not be deleted.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.Cancel,
                QMessageBox.StandardButton.Cancel,
            )
            if answer == QMessageBox.StandardButton.Yes:
                self._remove_library_location(location_id)
                refresh()

        add_button.clicked.connect(add_location)
        rescan_button.clicked.connect(rescan_selected)
        rescan_all_button.clicked.connect(lambda: (self._scan_library_locations(full=False), refresh()))
        full_rescan_button.clicked.connect(full_rescan_selected)
        remove_button.clicked.connect(remove_selected)
        cancel_scan_button.clicked.connect(lambda: (self._cancel_library_scan(), refresh()))
        close_button.clicked.connect(dialog.accept)
        self._library_locations_refresh = refresh
        refresh()
        dialog.exec()
        self._library_locations_refresh = None

    def _cancel_library_scan(self) -> bool:
        worker = getattr(self, "_library_scan_worker", None)
        thread = getattr(self, "_library_scan_thread", None)
        try:
            if worker is None or thread is None or not thread.isRunning():
                return False
            worker.cancel()
            self._set_processing_text("Cancelling library scan…", auto_dismiss_ms=None)
            return True
        except Exception as e:
            print(f"⚠️ Could not cancel library scan: {e}")
            return False

    def _start_library_scan_worker(self, roots, quick_mode: bool, preserve_outside: bool = False) -> bool:
        try:
            thr = getattr(self, "_library_scan_thread", None)
            if thr is not None and thr.isRunning():
                self._show_processing_notification("Library scan already running.", level="info")
                return True
        except Exception:
            pass
        try:
            self._last_scan_summary_text = ""
            phase = "Quick Update" if quick_mode else "Full Scan"
            self._set_processing_text(f"Scanning... ({phase})", auto_dismiss_ms=None)
            if hasattr(self, "scan_progress"):
                self.scan_progress.setRange(0, 0)
                self.scan_progress.show()

            self._library_scan_thread = QThread(self)
            scan_settings = dict(getattr(self, "settings", {}) or {})
            scan_settings["_scan_preserve_outside_roots"] = bool(preserve_outside)
            self._library_scan_worker = LibraryScanWorker(
                roots,
                quick_mode,
                list(getattr(self, "tracks", []) or []),
                scan_settings,
            )
            self._library_scan_worker.moveToThread(self._library_scan_thread)
            self._library_scan_thread.started.connect(self._library_scan_worker.run)
            self._library_scan_worker.progress.connect(self._on_library_scan_progress)
            self._library_scan_worker.finished.connect(self._on_library_scan_finished)
            self._library_scan_worker.finished.connect(self._library_scan_thread.quit)
            self._library_scan_worker.finished.connect(self._library_scan_worker.deleteLater)
            self._library_scan_thread.finished.connect(self._library_scan_thread.deleteLater)
            self._library_scan_thread.start()
            return True
        except Exception as e:
            print(f"⚠️ Background scan startup failed, falling back to inline scan: {e}")
            try:
                if hasattr(self, "scan_progress"):
                    self.scan_progress.hide()
                    self.scan_progress.setRange(0, 1)
            except Exception:
                pass
            return False

    def _on_library_scan_progress(self, text: str):
        try:
            self._set_processing_text(str(text or ""), auto_dismiss_ms=None)
        except Exception:
            pass

    def _on_library_scan_finished(self, result: dict):
        result = result if isinstance(result, dict) else {}
        try:
            if hasattr(self, "scan_progress"):
                self.scan_progress.hide()
                self.scan_progress.setRange(0, 1)
        except Exception:
            pass
        if bool(result.get("cancelled", False)):
            pending_ids = set(getattr(self, "_pending_library_scan_ids", []) or [])
            for location in self._library_locations():
                if location.get("id") in pending_ids:
                    location["last_scan_status"] = "scan cancelled"
            self._pending_library_scan_ids = []
            self.save_settings()
            self._show_processing_notification("Library scan cancelled; existing library preserved.", level="info")
            return
        if not result.get("ok", False):
            msg = str(result.get("error") or "Library scan failed")
            pending_ids = set(getattr(self, "_pending_library_scan_ids", []) or [])
            if pending_ids:
                for location in self._library_locations():
                    if location.get("id") in pending_ids:
                        location["last_scan_status"] = f"scan failed: {msg[:80]}"
                self.save_settings()
            self._pending_library_scan_ids = []
            print(f"⚠️ Library scan failed: {msg}")
            self._show_processing_notification(f"Scan failed: {msg[:120]}", level="error")
            return

        new_tracks = list(result.get("tracks") or [])
        self.tracks = new_tracks
        try:
            self.settings["karaoke_scan_dir_sigs"] = result.get("dir_sigs", {}) or {}
            self.settings["karaoke_scan_last_update"] = time.time()
            pending_ids = set(getattr(self, "_pending_library_scan_ids", []) or [])
            unavailable_keys = {
                _scanned_library_path_key(path) for path in (result.get("unavailable_roots") or [])
            }
            suspect_keys = {
                _scanned_library_path_key(path) for path in (result.get("suspect_empty_roots") or [])
            }
            if pending_ids:
                now = time.time()
                track_path_keys = [
                    _scanned_library_path_key(track.get("path", ""))
                    for track in self.tracks if isinstance(track, dict) and track.get("path")
                ]
                for location in self._library_locations():
                    if location.get("id") not in pending_ids:
                        continue
                    if _scanned_library_path_key(location.get("path", "")) in unavailable_keys:
                        location["last_scan_status"] = "offline"
                        continue
                    if _scanned_library_path_key(location.get("path", "")) in suspect_keys:
                        location["last_scan_status"] = "looked empty — songs preserved (check drive)"
                        continue
                    location["last_scan_at"] = now
                    location["last_scan_status"] = "scan complete"
                    root_key = _scanned_library_path_key(location.get("path", ""))
                    location["last_track_count"] = sum(
                        1 for path_key in track_path_keys
                        if path_key == root_key or path_key.startswith(root_key + os.sep)
                    )
            self._pending_library_scan_ids = []
            self.save_settings()
        except Exception:
            pass
        try:
            suspect_roots = list(result.get("suspect_empty_roots") or [])
            if suspect_roots:
                names = ", ".join(os.path.basename(r.rstrip(os.sep)) or r for r in suspect_roots)
                _diag(
                    "[LIBRARY-SCAN] WARNING: configured location(s) scanned empty while songs "
                    f"were previously indexed there; records preserved. roots={suspect_roots!r}"
                )
                self._show_processing_notification(
                    f"⚠ Library location(s) looked EMPTY: {names}. Songs preserved — "
                    "check that the drive is mounted at the same path.",
                    level="warning",
                )
        except Exception:
            pass
        try:
            self._display_name_cache = {}
        except Exception:
            pass
        try:
            self._rebind_queue_entries_to_tracks()
        except Exception:
            pass

        quick_mode = bool(result.get("quick_mode", False))
        reindex_needed = bool(result.get("reindex_needed", not quick_mode))
        self._pending_scan_reindex_needed = bool(reindex_needed)
        self._pending_scan_index_incremental = bool(quick_mode)
        self._pending_scan_index_changed_paths = list(result.get("index_changed_paths") or [])
        self._pending_scan_index_removed_paths = list(result.get("index_removed_paths") or [])
        self._last_scan_summary_text = str(result.get("summary_text") or "")

        scan_time = float(result.get("scan_time") or 0.0)
        tracks_added = int(result.get("tracks_added") or 0)
        zip_count = int(result.get("zip_count") or 0)
        mp4_count = int(result.get("mp4_count") or 0)
        cdg_count = int(result.get("cdg_count") or 0)
        tracks_reused = int(result.get("tracks_reused") or 0)
        tracks_changed = int(result.get("tracks_changed") or 0)
        unavailable_count = len(result.get("unavailable_roots") or [])
        overlap_count = int(result.get("overlapping_roots_skipped") or 0)
        print(f"✅ Phase 1 completed in {scan_time:.2f} seconds")
        print(f"📁 Found {tracks_added} tracks ({zip_count} zip files, {mp4_count} mp4, ~{cdg_count} cdg entries)")
        _diag(
            f"[LIBRARY-SCAN] mode={'quick' if quick_mode else 'full'} "
            f"requested={len(result.get('requested_roots') or [])} scanned={len(result.get('roots') or [])} "
            f"offline={unavailable_count} overlapping_skipped={overlap_count} "
            f"files_seen={int(result.get('files_seen') or 0):,} reused={tracks_reused:,} "
            f"changed={tracks_changed:,} elapsed_ms={scan_time * 1000.0:.1f}"
        )
        if quick_mode:
            print(f"⚡ Quick Update reused {tracks_reused:,} unchanged track(s); changed existing: {tracks_changed:,}")
        try:
            SingWSLogger.log_scan_complete(
                tracks_added,
                scan_time,
                {"ZIP": zip_count, "MP4": mp4_count, "CDG": cdg_count},
            )
        except Exception:
            pass

        try:
            if hasattr(self, "processing_label"):
                self.processing_label.setText("")
            if hasattr(self, "search_input"):
                self.search_input.setText("")
            self.search_tracks()
            self.update_queue_display()
            self.update_rotation_view()
        except Exception as e:
            print("Post-scan refresh failed:", e)

        if not bool(result.get("tracks_persisted", False)):
            try:
                _save_json_atomic(TRACKS_PATH, self.tracks)
            except Exception as e:
                print(f"⚠️ Failed to save tracks: {e}")

        try:
            refresh = getattr(self, "_library_locations_refresh", None)
            if callable(refresh):
                refresh()
        except Exception:
            pass

        missing = sum(1 for t in self.tracks if self._track_needs_duration(t))
        if missing > 0:
            print(f"🔍 Phase 2: Starting background duration scanning ({missing} missing).")
            print("   (DB will be built after durations are obtained)")
            QTimer.singleShot(250, self._start_duration_probe)
        else:
            print("✅ All durations present — checking search index...")
            try:
                self.ensure_song_index_async(
                    force=bool(reindex_needed),
                    changed_paths=(result.get("index_changed_paths") or []) if quick_mode else None,
                    removed_paths=(result.get("index_removed_paths") or []) if quick_mode else None,
                )
                self._pending_scan_index_changed_paths = []
                self._pending_scan_index_removed_paths = []
                self._pending_scan_index_incremental = False
            except Exception as e:
                print(f"⚠️ Failed to rebuild search index: {e}")

    def scan_folder(self):
        self.open_library_locations_dialog()

    def _legacy_scan_folder(self):
        """Scan chooser: Quick Update (incremental) or Full Scan."""
        import time, os
        self._last_scan_summary_text = ""

        # Styled mode chooser (matches Settings/Network visual language).
        mode_dlg = QDialog(self)
        mode_dlg.setWindowTitle("Scan Library")
        mode_dlg.setMinimumWidth(380)
        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            mode_dlg.setStyleSheet(dialog_stylesheet(win, base, txtc))
        except Exception:
            pass

        mode_box = QVBoxLayout(mode_dlg)
        row = QHBoxLayout()
        row.addStretch(1)
        btn_update = QPushButton("Update")
        btn_full = QPushButton("Full Scan")
        btn_cancel = QPushButton("Cancel")
        row.addWidget(btn_update)
        row.addWidget(btn_full)
        row.addWidget(btn_cancel)
        row.addStretch(1)
        mode_box.addLayout(row)

        scan_hint = QLabel(
            "Update checks saved folders for added, changed, or removed files.\n"
            "Full Scan rereads the entire selected library and rebuilds all metadata and durations."
        )
        scan_hint.setWordWrap(True)
        scan_hint.setStyleSheet(section_meta_css())
        mode_box.addWidget(scan_hint)
        btn_update.setToolTip("Incremental: process only filesystem changes in saved library folders.")
        btn_full.setToolTip("Complete rebuild: reread every supported file and duration in the selected folder.")

        mode_choice = {"value": None}
        btn_update.clicked.connect(lambda: (mode_choice.__setitem__("value", "update"), mode_dlg.accept()))
        btn_full.clicked.connect(lambda: (mode_choice.__setitem__("value", "full"), mode_dlg.accept()))
        btn_cancel.clicked.connect(mode_dlg.reject)

        if mode_dlg.exec() != QDialog.DialogCode.Accepted or mode_choice["value"] is None:
            return

        quick_mode = (mode_choice["value"] == "update")
        roots = [str(p) for p in (self.settings.get("karaoke_scan_roots", []) or []) if p and os.path.isdir(str(p))]

        if quick_mode:
            if not roots:
                QMessageBox.information(
                    self,
                    "No Saved Scan Paths",
                    "Update uses saved scan paths only.\nRun Full Scan once to select and save a folder.",
                )
                return
        else:
            folder = QFileDialog.getExistingDirectory(self, "Select Karaoke Folder (full scan)")
            if not folder:
                return
            roots = [folder]
            self.settings["karaoke_scan_roots"] = roots
            try:
                self.save_settings()
            except Exception:
                pass

        if self._start_library_scan_worker(roots, quick_mode):
            return

        _diag(f"[SCAN] mode={'quick_update' if quick_mode else 'full_scan'} roots={len(roots)}")
        print("🚀 Phase 1: Instant filename scan...")
        start_time = time.time()

        old_tracks = list(getattr(self, "tracks", []) or [])
        old_by_path = {str(t.get("path") or ""): t for t in old_tracks if isinstance(t, dict) and t.get("path")}
        old_duration_by_path = {
            t.get("path"): t.get("duration")
            for t in old_tracks
            if isinstance(t, dict) and t.get("path") and t.get("duration")
        }

        def _scan_file_sig(path: str):
            try:
                st = os.stat(path)
                return int(st.st_mtime), int(st.st_size)
            except Exception:
                return None, None

        def _scan_dir_sig(path: str):
            try:
                st = os.stat(path)
                return [int(getattr(st, "st_mtime_ns", int(st.st_mtime * 1_000_000_000))), int(st.st_size)]
            except Exception:
                return None

        def _old_track_unchanged(old_track: dict, mtime, size) -> bool:
            if not isinstance(old_track, dict):
                return False
            old_mtime = old_track.get("scan_mtime")
            old_size = old_track.get("scan_size")
            if old_mtime is None or old_size is None:
                # Older libraries did not persist scan signatures. Reuse once so
                # Quick Update regains its fast path, then write signatures below.
                return True
            try:
                return int(old_mtime) == int(mtime) and int(old_size) == int(size)
            except Exception:
                return False

        def _song_type_for_name(filename: str):
            lower = str(filename or "").lower()
            if lower.endswith(".mp4"):
                return "mp4"
            if lower.endswith(".cdg"):
                return "cdg"
            if lower.endswith(".zip"):
                return "mp3g"
            return None

        def _make_scanned_track(full_path: str, song_type: str, old_track: dict | None = None):
            name = os.path.basename(full_path)
            scan_mtime, scan_size = _scan_file_sig(full_path)
            if quick_mode and _old_track_unchanged(old_track, scan_mtime, scan_size):
                track = dict(old_track)
                track["path"] = full_path
                track["type"] = song_type
                if scan_mtime is not None:
                    track["scan_mtime"] = scan_mtime
                if scan_size is not None:
                    track["scan_size"] = scan_size
                if not track.get("artist") or not track.get("title") or not track.get("display"):
                    base = os.path.splitext(name)[0]
                    fmt = str(self.settings.get("filename_format", DEFAULT_FILENAME_FORMAT) or DEFAULT_FILENAME_FORMAT)
                    artist, title, disc_id = parse_filename_stem(base, fmt)
                    if not track.get("artist"):
                        track["artist"] = artist
                    if not track.get("title"):
                        track["title"] = title
                    if not track.get("disc_id"):
                        track["disc_id"] = disc_id
                    track["display"] = self._display_for_track(track)
                return track, True, False

            base = os.path.splitext(name)[0]
            fmt = str(self.settings.get("filename_format", DEFAULT_FILENAME_FORMAT) or DEFAULT_FILENAME_FORMAT)
            artist, title, disc_id = parse_filename_stem(base, fmt)
            track = {
                "path": full_path,
                "type": song_type,
                "artist": artist,
                "title": title,
                "disc_id": disc_id,
                "duration": old_duration_by_path.get(full_path) if quick_mode else None,
            }
            if scan_mtime is not None:
                track["scan_mtime"] = scan_mtime
            if scan_size is not None:
                track["scan_size"] = scan_size
            track["display"] = self._display_for_track(track)
            changed_existing = bool(quick_mode and old_track is not None)
            return track, False, changed_existing

        # Keep untouched tracks outside selected roots in quick mode.
        keep_outside_roots = []
        if quick_mode and roots:
            root_norms = [os.path.normcase(os.path.abspath(r)) for r in roots]

            def _is_under_any_root(path: str) -> bool:
                try:
                    p = os.path.normcase(os.path.abspath(path))
                    for rn in root_norms:
                        if p == rn or p.startswith(rn + os.sep):
                            return True
                except Exception:
                    pass
                return False

            keep_outside_roots = [
                t for t in old_tracks
                if str(t.get("path") or "") and (not _is_under_any_root(str(t.get("path") or "")))
            ]

        new_tracks = [] if not quick_mode else list(keep_outside_roots)
        seen = set(str(t.get("path") or "") for t in new_tracks if t.get("path"))

        try:
            if hasattr(self, "processing_label"):
                phase = "Quick Update" if quick_mode else "Full Scan"
                self.processing_label.setText(f"Scanning… ({phase})")
            if hasattr(self, "scan_progress"):
                self.scan_progress.setRange(0, 0)
                self.scan_progress.show()
            QApplication.processEvents()
        except Exception:
            pass

        files_seen = 0
        tracks_added, zip_count, mp4_count, cdg_count = 0, 0, 0, 0
        tracks_reused, tracks_changed = 0, 0
        last_ui = time.time()
        dir_sigs = {}

        if quick_mode:
            root_norms = [os.path.normcase(os.path.abspath(r)) for r in roots]

            def _is_under_any_root(path: str) -> bool:
                try:
                    p = os.path.normcase(os.path.abspath(path))
                    for rn in root_norms:
                        if p == rn or p.startswith(rn + os.sep):
                            return True
                except Exception:
                    pass
                return False

            stored_dir_sigs = self.settings.get("karaoke_scan_dir_sigs", {}) or {}
            if not isinstance(stored_dir_sigs, dict):
                stored_dir_sigs = {}
            no_dir_cache = not bool(stored_dir_sigs)
            try:
                baseline_ns = int(TRACKS_PATH.stat().st_mtime_ns)
            except Exception:
                baseline_ns = 0

            tracks_by_path = {str(t.get("path") or ""): dict(t) for t in old_tracks if isinstance(t, dict) and t.get("path")}
            for path in list(tracks_by_path):
                if os.path.basename(path).startswith("."):
                    tracks_by_path.pop(path, None)
            under_root_paths = {p for p in tracks_by_path if _is_under_any_root(p)}
            known_dirs = set(os.path.abspath(r) for r in roots)
            for path in under_root_paths:
                try:
                    known_dirs.add(os.path.abspath(os.path.dirname(path)))
                except Exception:
                    pass
            for path in stored_dir_sigs.keys():
                if _is_under_any_root(path):
                    known_dirs.add(os.path.abspath(path))

            changed_dirs = set()
            removed_dirs = set()
            for directory in sorted(known_dirs):
                sig = _scan_dir_sig(directory)
                if sig is None:
                    removed_dirs.add(directory)
                    continue
                dir_sigs[directory] = sig
                old_sig = stored_dir_sigs.get(directory)
                if old_sig is None:
                    if no_dir_cache and baseline_ns and int(sig[0]) <= baseline_ns:
                        continue
                    changed_dirs.add(directory)
                    continue
                try:
                    if [int(old_sig[0]), int(old_sig[1])] != [int(sig[0]), int(sig[1])]:
                        changed_dirs.add(directory)
                except Exception:
                    changed_dirs.add(directory)

            def _remove_tracks_under(directory: str):
                dn = os.path.normcase(os.path.abspath(directory))
                for path in list(tracks_by_path.keys()):
                    try:
                        pn = os.path.normcase(os.path.abspath(path))
                        if pn.startswith(dn + os.sep):
                            tracks_by_path.pop(path, None)
                    except Exception:
                        pass

            for directory in sorted(removed_dirs, key=len, reverse=True):
                _remove_tracks_under(directory)

            scanned_dirs = set()

            def _scan_directory_files(directory: str, recursive: bool = False):
                nonlocal files_seen, tracks_added, zip_count, mp4_count, cdg_count, tracks_reused, tracks_changed, last_ui
                directory = os.path.abspath(directory)
                if directory in scanned_dirs:
                    return
                scanned_dirs.add(directory)
                try:
                    entries = list(os.scandir(directory))
                except Exception:
                    return
                sig = _scan_dir_sig(directory)
                if sig is not None:
                    dir_sigs[directory] = sig
                current_files = set()
                for entry in entries:
                    try:
                        name = entry.name
                        lower = name.lower()
                    except Exception:
                        continue
                    if name.startswith("."):
                        continue
                    try:
                        if entry.is_dir(follow_symlinks=False):
                            child_dir = os.path.abspath(entry.path)
                            child_sig = _scan_dir_sig(child_dir)
                            if child_sig is not None:
                                dir_sigs[child_dir] = child_sig
                            if recursive or child_dir not in known_dirs:
                                _scan_directory_files(child_dir, recursive=True)
                            continue
                    except Exception:
                        pass

                    song_type = _song_type_for_name(name)
                    if song_type is None:
                        continue
                    full_path = entry.path
                    current_files.add(full_path)
                    files_seen += 1
                    if song_type == "mp4":
                        mp4_count += 1
                    elif song_type == "cdg":
                        cdg_count += 1
                    elif song_type == "mp3g":
                        zip_count += 1
                    old_track = old_by_path.get(str(full_path))
                    track, reused, changed_existing = _make_scanned_track(full_path, song_type, old_track)
                    tracks_by_path[full_path] = track
                    tracks_added += 1
                    if reused:
                        tracks_reused += 1
                    if changed_existing:
                        tracks_changed += 1
                    now = time.time()
                    if (now - last_ui) >= 0.05:
                        try:
                            self.processing_label.setText(f"Scanning changed folders… {files_seen:,}")
                            QApplication.processEvents()
                        except Exception:
                            pass
                        last_ui = now

                # A changed known directory also tells us which files were
                # deleted from that directory, without rewalking unchanged dirs.
                for path in list(under_root_paths):
                    try:
                        if os.path.abspath(os.path.dirname(path)) == directory and path not in current_files:
                            tracks_by_path.pop(path, None)
                    except Exception:
                        pass

            for directory in sorted(changed_dirs):
                _scan_directory_files(directory, recursive=False)

            new_tracks = []
            emitted = set()
            for old in old_tracks:
                path = str(old.get("path") or "") if isinstance(old, dict) else ""
                if path and path in tracks_by_path and path not in emitted:
                    new_tracks.append(tracks_by_path[path])
                    emitted.add(path)
            for path in sorted(tracks_by_path.keys(), key=lambda p: song_index.normalize_text(os.path.basename(p))):
                if path not in emitted:
                    new_tracks.append(tracks_by_path[path])
                    emitted.add(path)
            tracks_added = len([t for t in new_tracks if _is_under_any_root(str(t.get("path") or ""))])
        else:
            for scan_root in roots:
                for root, _, files in os.walk(scan_root):
                    root_abs = os.path.abspath(root)
                    sig = _scan_dir_sig(root_abs)
                    if sig is not None:
                        dir_sigs[root_abs] = sig
                    now = time.time()
                    if (now - last_ui) >= 0.05:
                        try:
                            self.processing_label.setText(f"Scanning… {files_seen:,}")
                            QApplication.processEvents()
                        except Exception:
                            pass
                        last_ui = now

                    for name in files:
                        files_seen += 1
                        lower = name.lower()
                        full_path = os.path.join(root, name)
                        if name.startswith("."):
                            continue
                        if full_path in seen:
                            continue

                        if (files_seen % 50) == 0:
                            try:
                                self.processing_label.setText(f"Scanning… {files_seen:,}")
                                QApplication.processEvents()
                            except Exception:
                                pass

                        song_type = _song_type_for_name(name)
                        if song_type is None:
                            continue
                        if song_type == "mp4":
                            mp4_count += 1
                        elif song_type == "cdg":
                            cdg_count += 1
                        elif song_type == "mp3g":
                            zip_count += 1

                        seen.add(full_path)
                        old_track = old_by_path.get(str(full_path))
                        track, reused, changed_existing = _make_scanned_track(full_path, song_type, old_track)
                        new_tracks.append(track)
                        tracks_added += 1
                        if reused:
                            tracks_reused += 1
                        if changed_existing:
                            tracks_changed += 1

        self.tracks = new_tracks
        try:
            self.settings["karaoke_scan_dir_sigs"] = dir_sigs
            self.settings["karaoke_scan_last_update"] = time.time()
            self.save_settings()
        except Exception:
            pass
        try:
            self._display_name_cache = {}
        except Exception:
            pass
        try:
            self._rebind_queue_entries_to_tracks()
        except Exception:
            pass
        # Build scan delta summary for the post-index "Import Complete" status line.
        new_by_path = {str(t.get("path") or ""): t for t in new_tracks if t.get("path")}
        old_paths = set(old_by_path.keys())
        new_paths = set(new_by_path.keys())
        added_count = len(new_paths - old_paths)
        removed_count = len(old_paths - new_paths)
        reindex_needed = (not quick_mode) or added_count > 0 or removed_count > 0 or tracks_changed > 0
        self._pending_scan_reindex_needed = bool(reindex_needed)
        self._last_scan_summary_text = (
            f"Added: {added_count:,} • Removed: {removed_count:,} • "
            f"Total: {len(new_tracks):,}"
        )

        scan_time = time.time() - start_time
        print(f"✅ Phase 1 completed in {scan_time:.2f} seconds")
        print(f"📁 Found {tracks_added} tracks ({zip_count} zip files, {mp4_count} mp4, ~{cdg_count} cdg entries)")
        if quick_mode:
            print(f"⚡ Quick Update reused {tracks_reused:,} unchanged track(s); changed existing: {tracks_changed:,}")
        file_counts = {"ZIP": zip_count, "MP4": mp4_count, "CDG": cdg_count}
        SingWSLogger.log_scan_complete(tracks_added, scan_time, file_counts)

        try:
            if hasattr(self, "scan_progress"):
                self.scan_progress.hide()
                self.scan_progress.setRange(0, 1)
            if hasattr(self, "processing_label"):
                self.processing_label.setText("")
            QApplication.processEvents()
        except Exception:
            pass

        try:
            if hasattr(self, "search_input"):
                self.search_input.setText("")
            self.search_tracks()
            self.update_queue_display()
            self.update_rotation_view()
        except Exception as e:
            print("Post-scan refresh failed:", e)

        try:
            _save_json_atomic(TRACKS_PATH, self.tracks)
        except Exception as e:
            print(f"⚠️ Failed to save tracks: {e}")

        missing = sum(1 for t in self.tracks if self._track_needs_duration(t))
        if missing > 0:
            print(f"🔍 Phase 2: Starting background duration scanning ({missing} missing).")
            print("   (DB will be built after durations are obtained)")
            QTimer.singleShot(250, self._start_duration_probe)
        else:
            print("✅ All durations present — checking search index...")
            try:
                self.ensure_song_index_async(force=bool(reindex_needed))
            except Exception as e:
                print(f"⚠️ Failed to rebuild search index: {e}")
        
    def _fmt_mmss(self, secs: int | None) -> str:
        if not secs or secs <= 0:
            return "--:--"
        m, s = divmod(int(secs), 60)
        return f"{m:02d}:{s:02d}"

    def _fmt_hhmm(self, secs: int) -> str:
        h, r = divmod(int(secs), 3600)
        m, _ = divmod(r, 60)
        return f"{h:02d}:{m:02d}"
        
    def _fmt_m_ss(self, secs: int | None) -> str:
        if not secs or secs <= 0:
            return "0:00"
        m, s = divmod(int(secs), 60)
        return f"{m}:{s:02d}"

    def _duration_cache_key(self, p: str) -> tuple[int, float] | None:
        """
        Stable key so we can skip re-probing unchanged files.
        Returns (size, mtime) or None if the file is missing/inaccessible.
        """
        try:
            st = os.stat(p)
            return (st.st_size, st.st_mtime)
        except Exception:
            return None
        
    def _duration_cache_key_for_path(self, file_path: str):
        """
        For normal files: (mtime,size). For ZIPs: coarse (zip mtime,size) only.
        Strong ZIP member identity (crc/usize/member) is stored per-track in 'dur_member_key'.
        """
        try:
            if str(file_path).lower().endswith(".zip"):
                return {
                    "zip_mtime": int(os.path.getmtime(file_path)),
                    "zip_size":  os.path.getsize(file_path),
                }
            st = os.stat(file_path)
            return {"mtime": int(st.st_mtime), "size": st.st_size}
        except Exception:
            return None

    def _priority_paths(self) -> set[str]:
        """
        Prioritize durations that affect the UI right now:
          1) Each singer's NEXT song (top of their list)
          2) Currently visible search results
        Everything else is probed afterwards in the background.
        """
        pri = set()

        # 1) next song for each active singer
        try:
            for s in self.queue:
                if s.get("songs"):
                    song_info, _key = s["songs"][0]
                    p = song_info[0] if isinstance(song_info, (tuple, list)) else song_info
                    if p:
                        pri.add(str(p))
        except Exception:
            pass

        # 2) visible search results (list)
        try:
            if hasattr(self, "results_list"):
                for r in range(self.results_list.count()):
                    it = self.results_list.item(r)
                    t = it.data(Qt.ItemDataRole.UserRole)
                    if isinstance(t, dict) and t.get("path"):
                        pri.add(str(t["path"]))
        except Exception:
            pass

        return pri

    def _get_track_obj(self, song_path: str):
        return self._find_track_by_path_ci(song_path)

    def set_video_timing_offset_ms(self, ms: int):
        """Save the visual-only CDG/MP4 timing offset and apply it live to any
        currently-playing karaoke transport. Audio is untouched."""
        try:
            ms = max(-3000, min(3000, int(ms)))
        except Exception:
            ms = 0
        self.settings["video_timing_offset_ms"] = ms
        try:
            self.save_settings()
        except Exception:
            pass
        try:
            if str(getattr(self, "_current_karaoke_mode", "") or "").lower() != "cdg":
                t = getattr(self, "karaoke_transport", None)
                if t is not None and hasattr(t, "set_video_offset_ms"):
                    t.set_video_offset_ms(ms)
                    _diag(f"[VIDEO-OFFSET] live offset set to {ms:+d}ms")
        except Exception:
            pass

    def set_cdg_timing_offset_ms(self, ms: int):
        """Save CDG fine tuning on top of the active engine's timing baseline.

        Written to the key for the engine currently selected, so calibrating on
        mpv cannot move FFmpeg's timing (or the reverse).
        """
        try:
            ms = max(-3000, min(3000, int(ms)))
        except Exception:
            ms = 0
        engine = self._cdg_timing_engine()
        self.settings[self._cdg_timing_offset_key()] = ms
        try:
            self.save_settings()
        except Exception:
            pass
        try:
            if str(getattr(self, "_current_karaoke_mode", "") or "").lower() == "cdg":
                t = getattr(self, "karaoke_transport", None)
                if t is not None and hasattr(t, "set_video_offset_ms"):
                    effective_ms = self._effective_cdg_timing_offset_ms()
                    t.set_video_offset_ms(effective_ms)
                    _diag(
                        f"[VIDEO-OFFSET] live CDG offset engine={engine} "
                        f"base={self._cdg_timing_base_offset_ms():+d}ms "
                        f"fine={ms:+d}ms total={effective_ms:+d}ms"
                    )
        except Exception:
            pass

    def set_mp4_timing_offset_ms(self, ms: int):
        """Save MP4 video trim for the active engine and apply it live."""
        try:
            ms = max(-3000, min(3000, int(ms)))
        except Exception:
            ms = 0
        engine = self._cdg_timing_engine()
        self.settings[self._mp4_timing_offset_key()] = ms
        try:
            self.save_settings()
        except Exception:
            pass
        try:
            if str(getattr(self, "_current_karaoke_mode", "") or "").lower() == "mp4":
                t = getattr(self, "karaoke_transport", None)
                if t is not None and hasattr(t, "set_video_offset_ms"):
                    effective_ms = self._effective_mp4_timing_offset_ms()
                    t.set_video_offset_ms(effective_ms)
                    _diag(
                        f"[VIDEO-OFFSET] live MP4 offset engine={engine} "
                        f"base={self._mp4_timing_base_offset_ms():+d}ms "
                        f"fine={ms:+d}ms total={effective_ms:+d}ms"
                    )
        except Exception:
            pass

    def _ticker_effects_supported(self) -> bool:
        """Whether the animated ticker lighting can be used at all here.

        Only RenderThreadTicker implements effects. The live ticker is the
        authority when it already has them, but "the ticker running right now
        cannot" is not the same as "this Mac cannot": switching GPU surfaces
        back on applies at the next launch, and greying the checkbox out until
        then hides the very control the operator just enabled. So a pending
        on-at-next-launch state counts as supported -- see
        _ticker_effects_pending_relaunch for the wording that says so.
        """
        try:
            ticker = getattr(getattr(self, "video_window", None), "ticker", None)
            if ticker is not None and hasattr(ticker, "set_effects_enabled"):
                return True
        except Exception:
            pass
        return _native_quick_child_surfaces_supported()

    def _ticker_effects_pending_relaunch(self) -> bool:
        """Effects are configured on, but this session's ticker cannot do them."""
        try:
            ticker = getattr(getattr(self, "video_window", None), "ticker", None)
            if ticker is not None and hasattr(ticker, "set_effects_enabled"):
                return False
        except Exception:
            return False
        return _native_quick_child_surfaces_supported()

    _TICKER_FX_UNAVAILABLE_NOTE = (
        "\n\nUnavailable while 'Animated GPU ticker / transitions' is set to Off: "
        "the animated ticker runs on Qt Quick, so this session uses the legacy "
        "painter ticker, which has no lighting effects. The ticker still scrolls."
    )

    _TICKER_FX_PENDING_NOTE = (
        "\n\nThis session started with the plain painter ticker, so the lighting "
        "appears after the next launch. The setting is saved now."
    )

    def _simple_audio_mode(self) -> bool:
        """Simple Audio Mode (default ON): no normalization and no graphic EQ.

        Master Audio Processing is a separate explicit opt-in.
        """
        try:
            return bool(self.settings.get("simple_audio_mode", True))
        except Exception:
            return True

    def _apply_simple_audio_mode_live(self, simple: bool) -> None:
        """Apply a Simple Audio Mode change to BOTH running audio paths.

        Historically only the BGM engine was updated live and karaoke waited
        for the next song start, so toggling advanced audio mid-song made the
        EQ appear to work on one path and not the other. The karaoke transport
        reads .eq each visual tick (_mirror_eq), so swapping it mid-song is
        safe and takes effect immediately.
        """
        simple = bool(simple)
        if not simple:
            try:
                self._ensure_eq_engines()
            except Exception:
                pass
        # Background music engine (BASS): attach/detach the BGM EQ.
        try:
            bg = getattr(self, "bg_music", None)
            eng = getattr(bg, "_bass_engine", None) if bg is not None else None
            if eng is not None and hasattr(eng, "set_eq"):
                eng.set_eq(None if simple else getattr(self, "bgm_eq", None))
                self._log_bgm_eq_route("simple_audio_toggle")
            if bg is not None:
                bg._refresh_bg_normalize()
        except Exception:
            pass
        # Karaoke transport: swap the EQ live instead of waiting for the next
        # song (normalization gain still re-evaluates on the next song start).
        try:
            transport = getattr(self, "karaoke_transport", None)
            if transport is not None and hasattr(transport, "eq"):
                transport.eq = None if simple else getattr(self, "karaoke_eq", None)
                eq_obj = getattr(transport, "eq", None)
                _diag(
                    f"[EQ-ROUTE] path=karaoke mode={getattr(self, '_current_karaoke_mode', '?')} "
                    f"routed={int(eq_obj is not None)} reason=simple_audio_toggle live=1"
                )
        except Exception:
            pass
        # mpv's audio engine has no Python sample path to swap, so its whole
        # `af` chain is rebuilt instead. No-op on the other engines.
        self._push_mpv_audio_processing("simple_audio_toggle")

    def _log_bgm_eq_route(self, reason: str) -> None:
        try:
            bg = getattr(self, "bg_music", None)
            eng = getattr(bg, "_bass_engine", None) if bg is not None else None
            if eng is None:
                _diag(f"[EQ-ROUTE] path=bgm routed=0 chain=gstreamer_fallback reason={reason}")
                return
            if getattr(eng, "_eq_fx_handles", None):
                chain = "native-bass"
            elif getattr(eng, "_eq_dsp_handle", 0):
                chain = "python-dsp"
            else:
                chain = "off"
            eq_obj = getattr(self, "bgm_eq", None)
            _diag(
                f"[EQ-ROUTE] path=bgm routed={int(chain != 'off')} chain={chain} reason={reason} "
                f"enabled={int(bool(eq_obj is not None and eq_obj.enabled()))} "
                f"flat={int(bool(eq_obj is None or eq_obj.is_flat()))} "
                f"simple_audio={int(self._simple_audio_mode())}"
            )
        except Exception:
            pass

    def _karaoke_normalize_active(self, master_active: bool | None = None) -> bool:
        """True only when karaoke loudness work is allowed to read/cache/analyze.

        This is the hard gate for the "Normalize karaoke volume" checkbox. When
        the checkbox is off, no cache read, cache write, LUFS calculation, or
        background loudness worker should start from karaoke paths.
        """
        try:
            if not bool(self.settings.get("karaoke_normalize_enabled", True)):
                return False
            if not self._simple_audio_mode():
                return True
            if master_active is None:
                master_active = self._master_processing_active()
            return bool(master_active)
        except Exception:
            return False

    def _karaoke_normalize_bypass_reason(self, master_active: bool | None = None) -> str:
        try:
            if not bool(self.settings.get("karaoke_normalize_enabled", True)):
                return "setting_off"
            if self._simple_audio_mode():
                if master_active is None:
                    master_active = self._master_processing_active()
                if not master_active:
                    return "simple_audio_mode"
            return "unknown"
        except Exception:
            return "error"

    def _bg_normalize_setting_active(self) -> bool:
        """App-level mirror of BackgroundMusicPlayer._bg_normalize_active().

        Used before batch analysis so disabled BGM normalization does not scan
        folders, read loudness cache, or wake any analysis workers.
        """
        try:
            if bool(self.settings.get("simple_audio_mode", True)):
                return False
            return bool(self.settings.get("bg_normalize_enabled", True))
        except Exception:
            return False

    def _any_loudness_normalization_active(self) -> bool:
        return bool(self._karaoke_normalize_active() or self._bg_normalize_setting_active())

    def _sync_loudness_worker_gate(self, reason: str = "settings"):
        enabled = self._any_loudness_normalization_active()
        set_loudness_workers_enabled(enabled, reason=reason)
        if not enabled:
            self._cancel_loudness_analysis(reason)

    def _cancel_loudness_analysis(self, reason: str = "settings"):
        try:
            job = getattr(self, "_analyze_lib_job", None)
            if isinstance(job, tuple) and len(job) >= 2:
                worker = job[1]
                if worker is not None and hasattr(worker, "cancel"):
                    worker.cancel()
                    _diag(f"[LOUDNESS-LIB] cancel requested reason={reason}")
        except Exception:
            pass

    def _active_background_worker_snapshot(self) -> dict:
        qthreads = []
        for name in (
            "_dur_thread",
            "_library_scan_thread",
            "_zip_extract_thread",
            "_analyze_lib_job",
            "poll_thread",
        ):
            try:
                obj = getattr(self, name, None)
                if name == "_analyze_lib_job" and isinstance(obj, tuple):
                    obj = obj[0] if obj else None
                if obj is not None and hasattr(obj, "isRunning") and obj.isRunning():
                    qthreads.append(name)
            except Exception:
                pass
        timers = []
        for name in (
            "_queue_display_refresh_timer",
            "_save_data_timer",
            "rotation_post_timer",
            "_bg_transition_fade_timer",
            "_bg_transition_advance_timer",
            "_media_end_cleanup_timer",
        ):
            try:
                timer = getattr(self, name, None)
                if timer is not None and hasattr(timer, "isActive") and timer.isActive():
                    timers.append(name)
            except Exception:
                pass
        thread_names = []
        try:
            for th in threading.enumerate():
                nm = str(getattr(th, "name", "") or "")
                if nm and (
                    nm.startswith("remote-")
                    or nm.startswith("singws-")
                    or nm.startswith("waitlist-")
                    or nm.startswith("request-")
                    or nm.startswith("relay-")
                ):
                    thread_names.append(nm)
        except Exception:
            pass
        try:
            with _loudness_lock:
                loudness_inflight = len(_loudness_inflight)
        except Exception:
            loudness_inflight = 0
        try:
            prescan_inflight = len(getattr(self, "_next_prescan_inflight", set()) or set())
        except Exception:
            prescan_inflight = 0
        return {
            "qthreads": qthreads,
            "timers": timers,
            "threads": sorted(thread_names),
            "loudness_inflight": loudness_inflight,
            "lead_silence_prescan": prescan_inflight,
        }

    def _log_active_background_workers(self, reason: str = "status", *, force: bool = False):
        try:
            if not bool(getattr(self, "karaoke_playing", False)) and not force:
                return
            now = time.monotonic()
            last = float(getattr(self, "_active_worker_log_last_ts", 0.0) or 0.0)
            if not force and now - last < 60.0:
                return
            self._active_worker_log_last_ts = now
            snap = self._active_background_worker_snapshot()
            signature = repr(snap)
            if not force and signature == str(getattr(self, "_active_worker_log_last_signature", "") or ""):
                return
            self._active_worker_log_last_signature = signature
            _diag(
                "[PLAYBACK-WORKERS] "
                f"reason={reason} karaoke_active={int(bool(getattr(self, 'karaoke_playing', False)))} "
                f"qthreads={snap['qthreads']} timers={snap['timers']} threads={snap['threads']} "
                f"loudness_inflight={snap['loudness_inflight']} "
                f"lead_silence_prescan={snap['lead_silence_prescan']}"
            )
        except Exception:
            pass

    def _effective_search_debounce_ms(self) -> int:
        return 300

    def _effective_request_poll_interval_sec(self) -> int:
        try:
            base = max(1, int(float(self.settings.get("request_poll_interval_sec", 2))))
        except Exception:
            base = 2
        return base

    def _effective_host_poll_interval_sec(self) -> int:
        return 2

    def _effective_cdg_display_mode(self) -> str:
        mode = str(self.settings.get("cdg_display_mode", "") or "").strip().lower()
        if mode in {"fit", "sidefill", "blur", "stretch"}:
            return mode
        # Migration fallback for older settings files.
        try:
            if bool(self.settings.get("cdg_stretch_fill", False)):
                return "stretch"
        except Exception:
            pass
        return "fit"

    def _cdg_timing_engine(self) -> str:
        """The permanent native mpv timing baseline."""
        return "mpv"

    def _cdg_timing_offset_key(self) -> str:
        return (
            "cdg_timing_offset_mpv_ms"
            if self._cdg_timing_engine() == "mpv"
            else "cdg_timing_offset_ms"
        )

    def _cdg_timing_base_offset_ms(self) -> int:
        return (
            MPV_CDG_BASE_OFFSET_MS
            if self._cdg_timing_engine() == "mpv"
            else FFMPEG_CDG_BASE_OFFSET_MS
        )

    def _effective_cdg_timing_offset_ms(self) -> int:
        """Return the active engine's CDG baseline plus its saved fine tuning."""
        try:
            fine_ms = int(self.settings.get(self._cdg_timing_offset_key(), 0) or 0)
        except Exception:
            fine_ms = 0
        return max(-3000, min(3000, self._cdg_timing_base_offset_ms() + fine_ms))

    def _mp4_timing_offset_key(self) -> str:
        """Per engine, for the same reason CDG is: mpv composites the picture
        through its own GL surface and the painter path blits into a widget, so
        the display latency each carries is different and one shared value would
        de-calibrate whichever engine was not used to dial it in."""
        return (
            "mp4_timing_offset_mpv_ms"
            if self._cdg_timing_engine() == "mpv"
            else "mp4_timing_offset_ms"
        )

    def _effective_mp4_timing_offset_ms(self) -> int:
        """Return the active engine's MP4 baseline plus saved fine tuning."""
        try:
            fine_ms = int(self.settings.get(self._mp4_timing_offset_key(), 0) or 0)
        except Exception:
            fine_ms = 0
        return max(-3000, min(3000, self._mp4_timing_base_offset_ms() + fine_ms))

    def _mp4_timing_base_offset_ms(self) -> int:
        return MPV_MP4_BASE_OFFSET_MS if self._cdg_timing_engine() == "mpv" else 0

    def _effective_visual_timer_interval_ms(self) -> int:
        """Throttle visual polling only. Audio timing remains authoritative."""
        return 15

    def _effective_ticker_speed_px_per_sec(self, saved_speed=None) -> float:
        try:
            speed = float(saved_speed if saved_speed is not None else self.settings.get("ticker_speed_px_per_sec", TICKER_SPEED_DEFAULT))
        except Exception:
            speed = TICKER_SPEED_DEFAULT
        speed = max(TICKER_SPEED_MIN, min(TICKER_SPEED_MAX, speed))
        return speed

    def _apply_runtime_media_settings(self):
        """Apply runtime media settings without overwriting user choices."""
        try:
            ticker = getattr(getattr(self, "video_window", None), "ticker", None)
            if ticker is not None and hasattr(ticker, "set_scroll_speed"):
                ticker.set_scroll_speed(self._effective_ticker_speed_px_per_sec())
        except Exception:
            pass
        try:
            transport = getattr(self, "karaoke_transport", None)
            if transport is not None and hasattr(transport, "set_visual_timer_interval_ms"):
                transport.set_visual_timer_interval_ms(self._effective_visual_timer_interval_ms())
        except Exception:
            pass
        # Re-evaluate the attachment for the current song when settings change.
        try:
            transport = getattr(self, "karaoke_transport", None)
            if transport is not None and hasattr(transport, "master"):
                transport.master = self._ensure_master_processor()
        except Exception:
            pass
        try:
            self._apply_bgm_master_processing()
        except Exception:
            pass
    def _track_trim_db(self, path: str) -> float:
        """Host-set per-track playback trim in dB (plain gain, no DSP). 0 if unset."""
        try:
            trims = self.settings.get("karaoke_track_trims", {}) or {}
            v = trims.get(str(path or ""))
            if v is None:
                return 0.0
            return max(-24.0, min(24.0, float(v)))
        except Exception:
            return 0.0

    def _get_duration_secs(self, song_path: str) -> int | None:
        p = str(song_path)
        if p.lower().endswith(".cdg"):
            base, _ = os.path.splitext(p)
            audio = base + ".mp3"
            t = self._get_track_obj(p) or self._get_track_obj(audio)
        elif p.lower().endswith(".zip"):
            # For MP3G zips, look up by the zip path directly
            t = self._get_track_obj(p)
        else:
            t = self._get_track_obj(p)
        
        if t is None:
            return None
        dur = t.get("duration")
        return int(dur) if isinstance(dur, (int, float)) and dur > 0 else None
    
    def _get_current_singer(self):
        """Helper to get current singer name for logging"""
        try:
            # Check if we have a queue and get the first singer with songs
            if self.queue:
                for singer_entry in self.queue:
                    if singer_entry.get("songs") and not singer_entry.get("skipped"):
                        return singer_entry.get("name", "Unknown")
            return "Unknown"
        except:
            return "Unknown"
        
    @staticmethod
    def _track_needs_duration(t) -> bool:
        """A track still needs a duration probe only if it has no duration AND
        has not already been flagged as unresolvable on this build. The flag is
        cleared by a rescan (tracks are rebuilt from scratch), so unresolved
        files still get one fresh attempt after each scan."""
        return (
            isinstance(t, dict)
            and not t.get("duration")
            and not t.get("dur_unavailable")
            and t.get("type") in ("cdg", "mp3g", "mp4")
        )

    def _start_duration_probe(self):
        try:
            thr = getattr(self, "_dur_thread", None)
            if thr is not None and thr.isRunning():
                _diag("[DURATION] probe already running; duplicate start ignored")
                return
        except Exception:
            pass

        # Count items that actually need probing (zip mp3g and mp4 without duration)
        total = sum(1 for t in self.tracks if self._track_needs_duration(t))
        self._duration_scan_state = "running" if total > 0 else "finished"
        self._duration_scan_error = ""
        try:
            self._set_processing_text(
                f"Getting Durations… 0/{total:,}" if total > 0 else "",
                auto_dismiss_ms=None,
            )
        except Exception:
            pass
        
            # mark probe as in-progress so we don't hide items yet
        self._probe_completed = False
        
        if total == 0:
            self._probe_completed = True
            try:
                self._clear_duration_processing_text()
            except Exception:
                pass
            return

        # Thread & worker
        self._dur_thread = QThread()
        self._dur_worker = DurationProbeWorker(self)
        self._dur_worker.moveToThread(self._dur_thread)

        self._dur_thread.started.connect(self._dur_worker.run)
        self._dur_worker.progress.connect(self._on_duration_progress_counts)
        self._dur_worker.finished.connect(self._final_duration_refresh)
        self._dur_worker.finished.connect(self._dur_thread.quit)
        self._dur_worker.finished.connect(self._dur_worker.deleteLater)
        self._dur_thread.finished.connect(self._dur_thread.deleteLater)
        self._dur_thread.finished.connect(self._on_duration_thread_finished)

        # Persist durations to tracks.json when probing completes, and rebuild
        # the index only if something new was actually resolved.
        self._dur_worker.finished.connect(self._on_duration_probe_finished)

        self._dur_thread.start()

    def _on_duration_thread_finished(self):
        try:
            self._duration_probe_started = False
        except Exception:
            pass
        try:
            self._clear_duration_processing_text()
        except Exception:
            pass
        if str(getattr(self, "_duration_scan_state", "") or "") == "running":
            self._duration_scan_state = "finished"

    def _start_missing_duration_probe_if_needed(self):
        """Backfill durations for existing libraries without blocking first paint."""
        try:
            if getattr(self, "_duration_probe_started", False):
                return
            missing = sum(
                1
                for t in getattr(self, "tracks", []) or []
                if self._track_needs_duration(t)
            )
            if missing <= 0:
                return
            self._duration_probe_started = True
            _diag(f"[DURATION] starting missing-duration probe for {missing:,} track(s)")
            self._start_duration_probe()
        except Exception as e:
            try:
                self._duration_scan_state = "error"
                self._duration_scan_error = str(e)
                self._clear_duration_processing_text()
                self._set_processing_text(f"Duration scan error: {str(e)[:120]}")
            except Exception:
                pass
            _diag(f"[DURATION] missing-duration probe startup failed: {e}")

    def _on_duration_probe_finished(self):
        """Called when the background duration probe completes. Only rebuild the
        search index if the probe actually resolved at least one new duration —
        otherwise (unreadable files, or a build that can't probe mp4 durations)
        there is nothing new to index and we must not reindex on every launch."""
        resolved = 0
        try:
            resolved = int(getattr(getattr(self, "_dur_worker", None), "resolved_count", 0) or 0)
        except Exception:
            resolved = 0
        _diag(f"[DURATION] probe finished; resolved={resolved} new duration(s)")
        try:
            self._duration_scan_state = "finished"
            self._duration_scan_error = ""
            self._clear_duration_processing_text()
        except Exception:
            pass
        try:
            pending_scan_reindex = bool(getattr(self, "_pending_scan_reindex_needed", False))
            self._pending_scan_reindex_needed = False
            incremental = bool(getattr(self, "_pending_scan_index_incremental", False))
            changed_paths = set(getattr(self, "_pending_scan_index_changed_paths", []) or [])
            removed_paths = set(getattr(self, "_pending_scan_index_removed_paths", []) or [])
            try:
                changed_paths.update(getattr(getattr(self, "_dur_worker", None), "resolved_paths", []) or [])
            except Exception:
                pass
            self._pending_scan_index_changed_paths = []
            self._pending_scan_index_removed_paths = []
            self._pending_scan_index_incremental = False
            self._persist_tracks_json(
                trigger_reindex=(resolved > 0 or pending_scan_reindex),
                changed_paths=sorted(changed_paths) if incremental or not pending_scan_reindex else None,
                removed_paths=sorted(removed_paths) if incremental else None,
            )
        except Exception as e:
            self._duration_scan_state = "error"
            self._duration_scan_error = str(e)
            try:
                self._set_processing_text(f"Duration scan error: {str(e)[:120]}")
            except Exception:
                pass

    def _persist_tracks_json(
        self,
        trigger_reindex: bool = True,
        *,
        changed_paths=None,
        removed_paths=None,
    ):
        """Persist the large library snapshot without blocking the GUI thread."""
        try:
            snapshot = list(getattr(self, "tracks", []) or [])
        except Exception:
            snapshot = []
        reindex_args = (
            bool(trigger_reindex),
            list(changed_paths) if changed_paths is not None else None,
            list(removed_paths) if removed_paths is not None else None,
        )
        if bool(getattr(self, "_tracks_save_inflight", False)):
            self._tracks_save_pending = (snapshot, reindex_args)
            return
        self._start_tracks_save_worker(snapshot, reindex_args)

    def _start_tracks_save_worker(self, snapshot: list, reindex_args: tuple):
        self._tracks_save_inflight = True
        self._tracks_save_pending = None

        def worker():
            error = ""
            started = time.perf_counter()
            try:
                _save_json_atomic(TRACKS_PATH, snapshot)
            except Exception as exc:
                error = str(exc)
            finally:
                _perf_log_if_slow(
                    "json_save_tracks_worker",
                    (time.perf_counter() - started) * 1000.0,
                )
                self._run_on_ui_thread(
                    lambda: self._finish_tracks_save_worker(error, reindex_args)
                )

        threading.Thread(
            target=worker,
            daemon=True,
            name="singws-save-tracks",
        ).start()

    def _finish_tracks_save_worker(self, error: str, reindex_args: tuple):
        self._tracks_save_inflight = False
        if error:
            print("⚠️ Failed to persist durations:", error)
        else:
            print("✅ Saved durations to tracks.json")
            trigger_reindex, changed_paths, removed_paths = reindex_args
            if trigger_reindex:
                try:
                    print("🔍 Rebuilding search index with durations...")
                    self.ensure_song_index_async(
                        force=True,
                        changed_paths=changed_paths,
                        removed_paths=removed_paths,
                    )
                except Exception as exc:
                    print(f"⚠️ Failed to rebuild search index: {exc}")
        pending = getattr(self, "_tracks_save_pending", None)
        self._tracks_save_pending = None
        if pending is not None:
            snapshot, pending_reindex_args = pending
            self._start_tracks_save_worker(snapshot, pending_reindex_args)

    def _on_duration_progress_counts(self, done: int, total: int):
        # Update processing label with duration progress
        try:
            self._set_processing_text(f"Getting Durations… {done:,}/{total:,}", auto_dismiss_ms=None)
        except Exception:
            pass

    def _final_duration_refresh(self):
        # Mark probe complete so tracks without duration can be hidden
        self._probe_completed = True

        # One-and-done repaint after the whole scan finishes
        try:
            self.search_tracks()           # show [mm:ss] in search now
        except Exception:
            pass
        try:
            self.update_queue_display()    # queue + ETA
        except Exception:
            pass
        try:
            self.update_rotation_view()    # rotation window
        except Exception:
            pass
        try:
            if hasattr(self, "duration_status"):
                self.duration_status.setText("")  # clear progress
        except Exception:
            pass
        try:
            self._clear_duration_processing_text()
        except Exception:
            pass
        
    def search_tracks(self):
        # DB-backed search (runs in background so the ticker/UI never freezes)
        query = (self.search_input.text() or "").strip()
        try:
            self.results_list.clear()
        except Exception:
            pass
        self.track_map = {}

        if not query:
            return

        # If DB doesn't exist yet, kick off an index build (async) and show a hint.
        try:
            dbf = song_index.db_path()
            if not dbf.exists():
                try:
                    self._set_processing_text("Building search index…", auto_dismiss_ms=None)
                except Exception:
                    pass
                try:
                    self.ensure_song_index_async(force=False)
                except Exception:
                    pass
                # Don't fall back to python list scanning (that was the freeze).
                item = QListWidgetItem("No DB Found - Please use Scan Folder")
                try:
                    item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsSelectable)
                except Exception:
                    pass
                try:
                    self.results_list.addItem(item)
                except Exception:
                    pass
                return
        except Exception:
            pass

        # Start a new async search job.  Keep at most one database worker
        # active; stale LIKE/fuzzy scans still consume CPU even though their
        # results are ignored, which can steal time from audio/video playback
        # while an operator types quickly.
        self._search_job_id = getattr(self, "_search_job_id", 0) + 1
        job_id = self._search_job_id

        try:
            if getattr(self, "_search_thread", None) is not None and self._search_thread.isRunning():
                try:
                    self._search_thread.requestInterruption()
                except Exception:
                    pass
                self._pending_search_query = query
                self._pending_search_job_id = job_id
                return
        except Exception:
            pass

        self._pending_search_query = None
        self._pending_search_job_id = None
        self._search_thread = SongSearchThread(
            job_id,
            query,
            limit=500,
            fuzzy=True,
            karafun_search_url=(
                _network_normalize_base_url(self.settings.get("base_url", "")) + "/karafun_search.php"
                if bool(self.settings.get("karafun_include_online_search", False)) else ""
            ),
            karafun_tenant=str(self.settings.get("user", self.settings.get("tenant", "")) or ""),
        )
        self._search_thread.results_ready.connect(self._apply_db_search_results)
        # The coalesced query must also drain when the worker simply exits.
        # results_ready is not a reliable drain trigger: search_tracks() calls
        # requestInterruption() on the running worker, and run() checks that
        # flag right after its first emit and returns without emitting again.
        # So a keystroke landing between a worker's strict emit and its exit
        # left _pending_search_query set with nothing left to deliver it --
        # and search_tracks() had already cleared the results list, so the
        # search stayed empty until something else triggered a new one.
        self._search_thread.finished.connect(
            lambda jid=job_id: self._start_pending_search_if_needed(jid)
        )
        self._search_thread.start()

    def on_search_text_changed(self, text):
        """Handle real-time search text changes (search-as-you-type)."""
        t = (text or "").strip()

        # If the field is empty (including via the native clear button), clear the visible results quickly
        # and avoid triggering a full-library search.
        if not t:
            # Invalidate any in-flight search job so a slow background result
            # from a previous query can't repopulate the list after the box is
            # cleared (the "stale result randomly pops up" bug).
            self._search_job_id = getattr(self, "_search_job_id", 0) + 1
            self._pending_search_query = None
            self._pending_search_job_id = None
            try:
                self._search_debounce.stop()
            except Exception:
                pass
            try:
                self.results_list.clear()
                self.track_map = {}
            except Exception:
                pass
            return

        # Debounce so big libraries stay snappy while typing.
        try:
            self._search_debounce.start(self._effective_search_debounce_ms())
        except Exception:
            self.search_tracks()

    def _set_processing_text(self, msg: str, *, auto_dismiss_ms: int | None = PROCESSING_NOTIFICATION_TIMEOUT_MS):
        # Reuse whatever label you already show scan/probe status in.
        # We try a few common ones used in your builds.
        text = str(msg or "")
        if auto_dismiss_ms is None:
            try:
                timer = getattr(self, "_processing_notification_timer", None)
                if timer is not None:
                    timer.stop()
            except Exception:
                pass
            try:
                self._processing_notification_text = ""
            except Exception:
                pass
        elif not text:
            try:
                timer = getattr(self, "_processing_notification_timer", None)
                if timer is not None:
                    timer.stop()
            except Exception:
                pass
            try:
                self._processing_notification_text = ""
            except Exception:
                pass
        for name in ("processing_label", "scan_status", "duration_status", "status_label"):
            try:
                w = getattr(self, name, None)
                if w is not None:
                    w.setText(text)
                    if text and auto_dismiss_ms is not None and auto_dismiss_ms > 0:
                        self._processing_notification_text = text
                        timer = getattr(self, "_processing_notification_timer", None)
                        if timer is not None:
                            timer.stop()
                            timer.start(int(auto_dismiss_ms))
                    return
            except Exception:
                pass

    def _clear_routine_processing_text_for_playback(self):
        """Clear routine action text at playback start, preserving actual work/errors."""
        try:
            label = getattr(self, "processing_label", None)
            if label is None:
                return
            text = str(label.text() or "").strip()
            protected = (
                "scanning", "building search", "getting durations", "extracting zip",
                "analyzing", "packaging", "failed", "error",
            )
            if text and not any(part in text.lower() for part in protected):
                label.setText("")
                self._processing_notification_text = ""
        except Exception:
            pass

    def _show_processing_notification(self, msg: str, *, level: str = "info", persistent: bool = False):
        """Show a short-lived app notification below search.

        Long-running scan/index progress still uses _set_processing_text()
        directly. This helper is for user-visible info/success/error messages:
        each new message resets the dismiss timer, and only explicitly
        persistent messages are allowed to linger.
        """
        try:
            color = _v("warning")
            if level == "success":
                color = _v("success")
            elif level == "error":
                color = _v("warning")
            self.processing_label.setStyleSheet(f"color: {color}; font-size:11px; font-weight:750;")
        except Exception:
            pass
        timeout = None if persistent else PROCESSING_NOTIFICATION_TIMEOUT_MS
        self._set_processing_text(str(msg or ""), auto_dismiss_ms=timeout)

    def _clear_processing_notification(self):
        try:
            expected = str(getattr(self, "_processing_notification_text", "") or "")
            if not expected:
                return
            for name in ("processing_label", "scan_status", "duration_status", "status_label"):
                try:
                    w = getattr(self, name, None)
                    if w is not None and w.text() == expected:
                        w.setText("")
                except Exception:
                    pass
            self._processing_notification_text = ""
            if hasattr(self, "processing_label"):
                self.processing_label.setStyleSheet(f"color: {_v('warning')}; font-size:11px; font-weight:750;")
        except Exception:
            pass

    def _clear_duration_processing_text(self):
        """Clear stale duration-scan text from every known status label."""
        for name in ("processing_label", "scan_status", "duration_status", "status_label"):
            try:
                w = getattr(self, name, None)
                if w is None:
                    continue
                txt = str(w.text() or "")
                if "Getting Durations" in txt or "Getting durations" in txt:
                    w.setText("")
            except Exception:
                pass

    def ensure_song_index_async(self, force: bool = False, *, changed_paths=None, removed_paths=None):
        # Start index build in a QThread, report completion in the same status area as scan text.
        try:
            thr = getattr(self, "_index_thread", None)
            if thr is not None and thr.isRunning():
                return
        except Exception:
            pass

        self._index_thread = IndexBuildThread(
            force=force,
            changed_paths=changed_paths,
            removed_paths=removed_paths,
        )
        self._index_thread.done.connect(self._on_index_done)
        self._index_thread.progress.connect(self._on_index_progress)  # NEW: connect progress
        self._index_thread.start()

    def _on_index_progress(self, msg: str, current: int, total: int):
        """Update status label with indexing progress."""
        try:
            self._set_processing_text(msg, auto_dismiss_ms=None)
        except Exception:
            pass

    def _on_index_done(self, ok: bool, msg: str):
        try:
            if ok:
                # The library changed, so previously-unmatched remote requests
                # deserve a fresh lookup attempt against the new index.
                try:
                    self._unmatched_remote_request_ids = set()
                    self._unmatched_request_sigs = set()
                    self._empty_library_request_warned = False
                    self._relay_last_snapshot_signature = ""
                except Exception:
                    pass
                # Show success in green
                scan_summary = str(getattr(self, "_last_scan_summary_text", "") or "").strip()
                complete_text = "Import Complete"
                if scan_summary:
                    complete_text = f"{complete_text} • {scan_summary}"
                self._show_processing_notification(complete_text, level="success")
            else:
                self._show_processing_notification(msg, level="error")
        except Exception:
            pass
    
    def _clear_processing_text_if_matches(self, expected_text: str):
        """Clear processing label if it still shows the expected text."""
        try:
            if hasattr(self, "processing_label") and self.processing_label.text() == expected_text:
                try:
                    timer = getattr(self, "_processing_notification_timer", None)
                    if timer is not None:
                        timer.stop()
                except Exception:
                    pass
                self.processing_label.setText("")
                # Reset to yellow for future messages
                self.processing_label.setStyleSheet(f"color: {_v('warning')}; font-size:11px; font-weight:750;")
        except Exception:
            pass

    def _apply_db_search_results(self, job_id: int, rows: list):
        _apply_started = time.perf_counter()
        # Thread safety guard: same reasoning as update_queue_display.
        try:
            from PyQt6.QtCore import QThread as _QThread
            _qapp = QApplication.instance()
            if _qapp is not None and _QThread.currentThread() != _qapp.thread():
                self._run_on_ui_thread(lambda: self._apply_db_search_results(job_id, rows))
                return
        except Exception:
            pass

        # Ignore stale results (typing fast creates multiple jobs)
        if job_id != getattr(self, "_search_job_id", 0):
            self._start_pending_search_if_needed(job_id)
            return

        # If the search box was cleared while this job was running, don't
        # repopulate the list with results for a query that no longer applies.
        try:
            if not (self.search_input.text() or "").strip():
                self.results_list.clear()
                self.track_map = {}
                return
        except Exception:
            pass

        try:
            self.results_list.clear()
        except Exception:
            pass
        self.track_map = {}

        # Add items in SMALLER batches with proper yielding to avoid freezing the ticker
        BATCH_SIZE = 25
        batch_idx = [0]  # Use list to avoid nonlocal issues
        dropped = [0]
        
        def add_next_batch():
            _batch_started = time.perf_counter()
            start = batch_idx[0] * BATCH_SIZE
            end = min(start + BATCH_SIZE, len(rows))
            
            # Disable updates during batch add
            self.results_list.setUpdatesEnabled(False)
            try:
                for i in range(start, end):
                    r = rows[i]
                    try:
                        track = self._track_from_search_row(r)
                        label, tooltip, left, right = self._build_search_row_text(track)
                        item = QListWidgetItem(label)
                        item.setData(Qt.ItemDataRole.UserRole, track)
                        self._set_aligned_row_meta(item, left, right)
                        item.setData(self._row_disc_role, str(track.get("disc_id") or "").strip())
                        try:
                            item.setToolTip(tooltip)
                        except Exception:
                            pass
                        self.results_list.addItem(item)
                    except Exception as row_exc:
                        # Silently swallowing this made "my search returns
                        # nothing" undiagnosable: a row that fails to render
                        # simply vanished with no trace anywhere.
                        dropped[0] += 1
                        if dropped[0] == 1:
                            _diag(f"[SEARCH] row render failed: {type(row_exc).__name__}: {row_exc}")
                        continue
            finally:
                # Re-enable updates
                self.results_list.setUpdatesEnabled(True)
                _perf_log_if_slow("ui_search_render_batch", (time.perf_counter() - _batch_started) * 1000.0)
            if start == 0 and self.results_list.count() and self.results_list.currentRow() < 0:
                try:
                    self.results_list.setCurrentRow(0)
                except Exception:
                    pass
            
            batch_idx[0] += 1
            
            # Schedule next batch if there are more items (increased delay for ticker smoothness)
            if end < len(rows):
                QTimer.singleShot(20, add_next_batch)  # 20ms delay ensures ticker gets its 16ms frame
            else:
                if dropped[0]:
                    _diag(f"[SEARCH] rendered {self.results_list.count()} of {len(rows)} rows; {dropped[0]} dropped")
                _perf_log_if_slow("ui_apply_search_results", (time.perf_counter() - _apply_started) * 1000.0)
        
        # Start processing batches
        if rows:
            add_next_batch()
        else:
            _perf_log_if_slow("ui_apply_search_results", (time.perf_counter() - _apply_started) * 1000.0)
        self._start_pending_search_if_needed(job_id)

    def _start_pending_search_if_needed(self, completed_job_id: int):
        pending_query = str(getattr(self, "_pending_search_query", "") or "").strip()
        pending_job_id = getattr(self, "_pending_search_job_id", None)
        if not pending_query or pending_job_id is None:
            return
        # Only the latest completed worker is allowed to drain the coalesced
        # search request.  This keeps background searching serial and prevents
        # old worker completions from launching extra stale jobs.
        if int(completed_job_id) >= int(pending_job_id):
            return
        if pending_job_id != getattr(self, "_search_job_id", 0):
            return
        # A worker may still be winding down when this fires from its own
        # finished signal; the pending job is the newest one either way.
        try:
            running = getattr(self, "_search_thread", None)
            if running is not None and running.isRunning() and int(completed_job_id) != int(
                getattr(running, "job_id", -1)
            ):
                return
        except Exception:
            pass
        self._pending_search_query = None
        self._pending_search_job_id = None
        try:
            self._search_thread = SongSearchThread(
                int(pending_job_id), pending_query, limit=500,
                karafun_search_url=(
                    _network_normalize_base_url(self.settings.get("base_url", "")) + "/karafun_search.php"
                    if bool(self.settings.get("karafun_include_online_search", False)) else ""
                ),
                karafun_tenant=str(self.settings.get("user", self.settings.get("tenant", "")) or ""),
            )
            self._search_thread.results_ready.connect(self._apply_db_search_results)
            self._search_thread.finished.connect(
                lambda jid=int(pending_job_id): self._start_pending_search_if_needed(jid)
            )
            self._search_thread.start()
        except Exception:
            pass

    def clear_search(self):
        """Clear the search box and results (kept for compatibility)."""
        try:
            self.search_input.blockSignals(True)
            self.search_input.clear()
        finally:
            self.search_input.blockSignals(False)

        # Clear the visible list + map and return focus.
        try:
            self.results_list.clear()
            self.track_map = {}
        except Exception:
            pass

        self.search_input.setFocus()

    def add_song_to_singer(self):
        singer_name = self.singer_input.text().strip()
        if not singer_name:
            return

        try:
            sel_items = self.results_list.selectedItems()
        except Exception:
            sel_items = []
        if not sel_items:
            return

        item = sel_items[0]
        t = item.data(Qt.ItemDataRole.UserRole)
        if not isinstance(t, dict):
            return
        track_path = t.get("path", "") or ""
        if not track_path:
            return
        key_text = self.key_selector.currentText().replace("Key:", "").replace("+", "").strip()
        try:
            key_offset = int(key_text)
        except Exception:
            key_offset = 0

        base, ext = os.path.splitext(track_path)
        ext = ext.lower()

        if ext == ".mp4":
            song_data = (track_path, key_offset)
            self._add_song_to_queue(singer_name, song_data)
            return

        elif ext == ".cdg":
            mp3_path = base + ".mp3"
            self._enqueue_cdg_pair_async(
                track_path,
                mp3_path,
                singer_name,
                key_offset,
            )
            return

        elif ext == ".mp3":
            song_data = (track_path, key_offset)
            self._add_song_to_queue(singer_name, song_data)
            return

        elif ext == ".zip":
            # NEW: Handle MP3G zip files
            if self.is_mp3g_zip(track_path):
                song_data = (track_path, key_offset)  # Store zip path directly
                self._add_song_to_queue(singer_name, song_data)
                return
            else:
                QMessageBox.warning(self, "Invalid Zip", "Zip file must contain exactly one CDG and one MP3 file!")
                return
            
        elif ext == ".zip":
            # NEW: Handle MP3G zip files
            if self.is_mp3g_zip(track_path):
                song_data = (track_path, key_offset)
            else:
                QMessageBox.warning(self, "Invalid Zip", f"Zip file must contain exactly one CDG and one MP3 file:\n{track_path}")
                return
            
    def _enqueue_track_path_for_singer(self, track_path: str, singer_name: str, key_offset: int = 0):
        """Compatibility helper: enqueue a track path for a given singer/key (no dialog).

        Some UI paths (legacy handlers) call this. Internally we convert into the song_data
        format used by _add_song_to_queue, including CDG+MP3 pairing."""
        track_path = (track_path or "").strip()
        singer_name = (singer_name or "").strip()
        try:
            key_offset = int(key_offset)
        except Exception:
            key_offset = 0
        if not track_path or not singer_name:
            return

        # If it's a .cdg, pair it with a matching .mp3 like the rest of the app expects.
        if track_path.lower().endswith(".cdg"):
            mp3_path = track_path[:-4] + ".mp3"
            self._enqueue_cdg_pair_async(
                track_path,
                mp3_path,
                singer_name,
                key_offset,
            )
            return
        else:
            song_data = (track_path, key_offset)               # (file, key)

        self._add_song_to_queue(singer_name, song_data)

    def _enqueue_cdg_pair_async(
        self,
        cdg_path: str,
        mp3_path: str,
        singer_name: str,
        key_offset: int,
    ):
        """Validate a CDG pair and warm graphics without blocking the GUI."""
        try:
            self._set_processing_text(
                f"Checking media... {os.path.basename(cdg_path)}",
                auto_dismiss_ms=None,
            )
        except Exception:
            pass

        def worker():
            exists = os.path.exists(mp3_path)
            def finish():
                try:
                    self._clear_processing_text_if_matches(
                        f"Checking media... {os.path.basename(cdg_path)}"
                    )
                except Exception:
                    pass
                if not exists:
                    QMessageBox.warning(
                        self,
                        "Missing MP3",
                        f"Matching .mp3 not found:\n{mp3_path}",
                    )
                    return
                self._add_song_to_queue(
                    singer_name,
                    ((cdg_path, mp3_path), key_offset),
                )

            self._run_on_ui_thread(finish)

        threading.Thread(
            target=worker,
            name="singws-cdg-pair-check",
            daemon=True,
        ).start()


    def _add_track_path_to_queue_with_dialog(self, track_path: str):
        """Shared: add a track path into the singer queue using the existing Singer+Key dialog."""
        track_path = (track_path or "").strip()
        if not track_path:
            return

        default_singer = self.singer_input.text().strip() if hasattr(self, "singer_input") else ""
        try:
            key_text = self.key_selector.currentText().replace("Key:", "").replace("+", "").strip()
            default_key = int(key_text)
        except Exception:
            default_key = 0

        dlg = AddToQueueDialog(self, default_singer=default_singer, default_key=default_key)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        singer_name, key_offset = dlg.values()
        if not singer_name:
            return

        self._enqueue_track_path_for_singer(track_path, singer_name, key_offset)

    def add_karafun_reference_to_queue(self):
        """Add a KaraFun song reference for assisted external playback."""
        if not bool(self.settings.get("karafun_provider_enabled", True)):
            QMessageBox.information(self, "KaraFun Disabled", "Enable the KaraFun provider before adding KaraFun references.")
            return

        dlg = QDialog(self)
        dlg.setWindowTitle("Add KaraFun Song")
        dlg.setModal(True)
        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(18, 16, 18, 14)
        layout.setSpacing(10)

        note = QLabel("KaraFun will play externally. SingWS will hold the singer active until you confirm completion.")
        note.setWordWrap(True)
        note.setStyleSheet(section_meta_css())
        layout.addWidget(note)

        grid = QGridLayout()
        grid.setHorizontalSpacing(10)
        grid.setVerticalSpacing(8)

        singer_edit = QLineEdit()
        singer_edit.setPlaceholderText("Singer")
        try:
            singer_edit.setText(str(self.singer_input.text() or "").strip())
        except Exception:
            pass
        artist_edit = QLineEdit()
        artist_edit.setPlaceholderText("Artist")
        title_edit = QLineEdit()
        title_edit.setPlaceholderText("Song title")
        for row, (label_text, widget) in enumerate((
            ("Singer", singer_edit),
            ("Artist", artist_edit),
            ("Title", title_edit),
        )):
            label = QLabel(label_text)
            label.setStyleSheet(section_meta_css())
            grid.addWidget(label, row, 0)
            grid.addWidget(widget, row, 1)
        layout.addLayout(grid)

        buttons = QDialogButtonBox(dlg)
        add_btn = buttons.addButton("Add to Rotation", QDialogButtonBox.ButtonRole.AcceptRole)
        buttons.addButton("Cancel", QDialogButtonBox.ButtonRole.RejectRole)
        layout.addWidget(buttons)
        buttons.rejected.connect(dlg.reject)

        def accept_if_valid():
            singer = str(singer_edit.text() or "").strip()
            title = str(title_edit.text() or "").strip()
            if not singer or not title:
                QMessageBox.warning(dlg, "Missing Info", "Enter at least a singer and song title.")
                return
            dlg.accept()

        add_btn.clicked.connect(accept_if_valid)

        if dlg.exec() != QDialog.DialogCode.Accepted:
            return

        singer = str(singer_edit.text() or "").strip()
        artist = str(artist_edit.text() or "").strip()
        title = str(title_edit.text() or "").strip()
        track = self._build_karafun_streaming_track(
            artist=artist,
            title=title,
        )
        song_path = track["path"]
        song_data = (song_path, 0, None)
        if self._add_song_to_queue(singer, song_data, track=track):
            try:
                self._show_processing_notification(f"Added KaraFun: {title}", level="success")
            except Exception:
                pass

    @staticmethod
    def _apply_verified_duration(entry: dict, value, *, source: str) -> bool:
        """Replace only a missing/estimated duration with verified metadata."""
        if not isinstance(entry, dict):
            return False
        seconds = normalize_karafun_duration_seconds(value)
        if seconds is None:
            return False
        scraped = str(source or "").strip() == "karafun_result"
        current = normalize_karafun_duration_seconds(entry.get("duration"))
        if current is not None and not bool(entry.get("duration_estimated", False)):
            # A scraped result is read off KaraFun's own window for the exact
            # song about to play, so it outranks machine metadata already on the
            # entry: our catalog estimate can come back from the server without
            # its "estimated" flag and then look verified, and refusing to
            # correct it there is what let the watchdog complete a 4:57 song at
            # the estimate and start background music over KaraFun mid-song.
            # A duration the host set by hand is a deliberate override and still
            # wins over everything.
            host_set = "manual" in str(entry.get("duration_source", "") or "").strip().lower()
            if host_set or not scraped:
                return False
        if scraped and current is not None and int(current) != int(seconds):
            try:
                _diag(
                    f"[KARAFUN] duration corrected from {int(current)}s to {int(seconds)}s "
                    f"(was_estimated={int(bool(entry.get('duration_estimated', False)))}) "
                    f"title={str(entry.get('title', '') or '')!r}"
                )
            except Exception:
                pass
        entry["duration"] = seconds
        entry["duration_estimated"] = False
        entry["duration_source"] = str(source or "verified_metadata")
        return True

    @staticmethod
    def _ensure_karafun_duration_estimate(entry: dict) -> bool:
        """Persist one stable estimate for an external KaraFun queue entry."""
        if not isinstance(entry, dict):
            return False
        current = normalize_karafun_duration_seconds(entry.get("duration"))
        if current is not None and not bool(entry.get("duration_estimated", False)):
            return False
        changed = current != KARAFUN_ESTIMATED_DURATION_SECONDS or not bool(entry.get("duration_estimated", False))
        entry["duration"] = KARAFUN_ESTIMATED_DURATION_SECONDS
        entry["duration_estimated"] = True
        entry["duration_source"] = "karafun_default_estimate"
        return changed

    @staticmethod
    def _build_karafun_streaming_track(*, artist: str, title: str,
                                       provider_track_id: str = "", provider_url: str = "",
                                       duration=None, duration_estimated=None,
                                       duration_source: str = "") -> dict:
        """Build the single external-track shape used by manual and server adds."""
        artist = str(artist or "").strip()
        title = str(title or "").strip()
        provider_track_id = str(provider_track_id or "").strip()
        provider_url = str(provider_url or "").strip()
        reference_id = provider_track_id or provider_url or f"manual:{uuid.uuid4().hex}"
        normalized_duration = normalize_karafun_duration_seconds(duration)
        is_estimate = bool(duration_estimated) or normalized_duration is None
        return {
            "artist": artist,
            "title": title,
            "display": " - ".join([p for p in (artist, title, "KaraFun") if p]),
            "path": f"karafun_streaming:{reference_id}",
            "type": "external",
            "provider": "karafun_streaming",
            "provider_track_id": provider_track_id,
            "provider_url": provider_url,
            "authorization_requirement": "official_karafun_app",
            "availability_status": "externally_controlled",
            "duration": normalized_duration or KARAFUN_ESTIMATED_DURATION_SECONDS,
            "duration_estimated": is_estimate,
            "duration_source": (
                "karafun_default_estimate"
                if is_estimate else str(duration_source or "karafun_metadata")
            ),
        }

