    def _sanitize_filename_component(self, value: str) -> str:
        s = str(value or "").strip()
        s = re.sub(r'[<>:"/\\\\|?*]+', " ", s)
        s = re.sub(r"[\x00-\x1F]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip(" .")
        return s

    def _build_track_basename(self, artist: str, title: str, disc_id: str, fallback_stem: str) -> str:
        disc = self._sanitize_filename_component(disc_id)
        art = self._sanitize_filename_component(artist)
        ttl = self._sanitize_filename_component(title)
        parts = [p for p in (disc, art, ttl) if p]
        if parts:
            return " - ".join(parts)
        fb = self._sanitize_filename_component(fallback_stem)
        return fb or "Renamed Track"

    def _rename_track_files(self, original_path: str, artist: str, title: str, disc_id: str):
        """Rename selected karaoke file (and CDG pair) on disk."""
        old_main = str(original_path or "").strip()
        if not old_main or not os.path.exists(old_main):
            raise FileNotFoundError("Selected file no longer exists.")

        old_dir = os.path.dirname(old_main)
        new_stem = self._build_track_basename(artist, title, disc_id, Path(old_main).stem)
        ext = Path(old_main).suffix

        mappings = []
        if old_main.lower().endswith(".cdg"):
            old_cdg = old_main
            old_mp3 = os.path.splitext(old_main)[0] + ".mp3"
            if not os.path.exists(old_mp3):
                raise FileNotFoundError("Matching MP3 not found for this CDG file.")
            new_cdg = os.path.join(old_dir, new_stem + ".cdg")
            new_mp3 = os.path.join(old_dir, new_stem + ".mp3")
            mappings = [(old_cdg, new_cdg), (old_mp3, new_mp3)]
            new_main = new_cdg
        else:
            new_main = os.path.join(old_dir, new_stem + ext)
            mappings = [(old_main, new_main)]

        for old_p, new_p in mappings:
            if os.path.normcase(old_p) == os.path.normcase(new_p):
                continue
            if os.path.exists(new_p):
                raise FileExistsError(f"Target already exists:\n{new_p}")

        completed = []
        try:
            for old_p, new_p in mappings:
                if old_p == new_p:
                    continue
                # case-only rename safety on case-insensitive filesystems
                if os.path.normcase(old_p) == os.path.normcase(new_p):
                    tmp_p = os.path.join(old_dir, f".__singws_rename_tmp_{uuid.uuid4().hex}{Path(old_p).suffix}")
                    os.rename(old_p, tmp_p)
                    completed.append((old_p, tmp_p))
                    os.rename(tmp_p, new_p)
                    completed.append((tmp_p, new_p))
                else:
                    os.rename(old_p, new_p)
                    completed.append((old_p, new_p))
        except Exception:
            for src, dst in reversed(completed):
                try:
                    if os.path.exists(dst) and not os.path.exists(src):
                        os.rename(dst, src)
                except Exception:
                    pass
            raise

        rename_map = {}
        for old_p, new_p in mappings:
            if old_p != new_p:
                rename_map[old_p] = new_p
        return rename_map, new_main

    def _apply_track_rename_map(self, rename_map: dict, artist: str, title: str, disc_id: str):
        if not rename_map:
            return
        low_map = {str(k).lower(): str(v) for k, v in rename_map.items()}

        # Update loaded track metadata/path
        for t in self.tracks:
            old_p = str(t.get("path", "") or "")
            new_p = low_map.get(old_p.lower())
            if new_p:
                t["path"] = new_p
                t["artist"] = artist
                t["title"] = title
                t["disc_id"] = disc_id
                t["display"] = _display_for_track(t)

        # Update queue song references so playback still works immediately.
        for singer in self.queue:
            songs = singer.get("songs", [])
            for i, entry in enumerate(songs):
                if isinstance(entry, dict):
                    si = entry.get("song_info")
                    if isinstance(si, (tuple, list)):
                        rebuilt = []
                        changed = False
                        for part in si:
                            part_s = str(part)
                            new_part = low_map.get(part_s.lower(), part_s)
                            rebuilt.append(new_part)
                            changed = changed or (new_part != part_s)
                        if changed:
                            entry["song_info"] = tuple(rebuilt)
                    else:
                        p = str(si or "")
                        new_p = low_map.get(p.lower())
                        if new_p:
                            entry["song_info"] = new_p
                else:
                    try:
                        if isinstance(entry, (tuple, list)) and len(entry) >= 1:
                            si = entry[0]
                            rest = list(entry[1:])
                            if isinstance(si, (tuple, list)):
                                rebuilt = []
                                changed = False
                                for part in si:
                                    part_s = str(part)
                                    new_part = low_map.get(part_s.lower(), part_s)
                                    rebuilt.append(new_part)
                                    changed = changed or (new_part != part_s)
                                if changed:
                                    songs[i] = (tuple(rebuilt), *rest)
                            else:
                                p = str(si or "")
                                new_p = low_map.get(p.lower())
                                if new_p:
                                    songs[i] = (new_p, *rest)
                    except Exception:
                        pass

        # Drop stale caches
        try:
            for old_p, new_p in rename_map.items():
                self._display_name_cache.pop((str(old_p).lower(), True), None)
                self._display_name_cache.pop((str(old_p).lower(), False), None)
                self._display_name_cache.pop((str(new_p).lower(), True), None)
                self._display_name_cache.pop((str(new_p).lower(), False), None)
                self._silence_cache.pop(str(old_p), None)
                self._silence_cache.pop(str(new_p), None)
        except Exception:
            pass

    def _update_song_index_for_rename(self, rename_map: dict, artist: str, title: str, disc_id: str):
        """Update DB rows for renamed files so search updates immediately."""
        if not rename_map:
            return
        try:
            dbf = song_index.db_path()
            con = song_index._connect(dbf)
            cur = con.cursor()
            for old_p, new_p in rename_map.items():
                display = _display_for_track({"artist": artist or "", "title": title or "", "disc_id": disc_id or ""})
                cur.execute(
                    "UPDATE songs SET path=?, artist=?, title=?, discid=?, display=? WHERE lower(path)=lower(?)",
                    (str(new_p), artist or "", title or "", disc_id or "", display, str(old_p)),
                )
            con.commit()
            con.close()
        except Exception:
            pass

    def open_search_track_editor(self, track: dict):
        """Edit song metadata from search and rename the file on disk."""
        path = str(track.get("path", "") or "").strip()
        if not path:
            return

        if bool(getattr(self, "karaoke_playing", False)):
            QMessageBox.warning(self, "Playback Active", "Stop karaoke playback before renaming songs.")
            return

        artist = str(track.get("artist", "") or "").strip()
        title = str(track.get("title", "") or "").strip()
        disc_id = str(track.get("disc_id") or track.get("discid") or "").strip()
        if not (artist and title):
            a2, t2, d2 = self._split_display_artist_title_disc(str(track.get("display", "") or ""), disc_id)
            artist = artist or a2
            title = title or t2
            disc_id = disc_id or d2

        dlg = QDialog(self)
        dlg.setWindowTitle("Edit Song Metadata")
        dlg.resize(660, 300)

        # Match Network/Settings look
        try:
            base = self.palette().color(QPalette.ColorRole.Base)
            win = self.palette().color(QPalette.ColorRole.Window)
            txtc = self.palette().color(QPalette.ColorRole.Text)
            dlg.setStyleSheet(dialog_stylesheet(win, base, txtc))
        except Exception:
            pass

        v = QVBoxLayout(dlg)

        row_file = QHBoxLayout()
        row_file.addWidget(QLabel("Current File:"))
        file_edit = QLineEdit(path)
        file_edit.setReadOnly(True)
        row_file.addWidget(file_edit, 1)
        v.addLayout(row_file)

        row_artist = QHBoxLayout()
        row_artist.addWidget(QLabel("Artist:"))
        artist_edit = QLineEdit(artist)
        row_artist.addWidget(artist_edit, 1)
        v.addLayout(row_artist)

        row_title = QHBoxLayout()
        row_title.addWidget(QLabel("Title:"))
        title_edit = QLineEdit(title)
        row_title.addWidget(title_edit, 1)
        v.addLayout(row_title)

        row_disc = QHBoxLayout()
        row_disc.addWidget(QLabel("Disc ID:"))
        disc_edit = QLineEdit(disc_id)
        row_disc.addWidget(disc_edit, 1)
        v.addLayout(row_disc)

        row_preview = QHBoxLayout()
        row_preview.addWidget(QLabel("New Name:"))
        preview_edit = QLineEdit("")
        preview_edit.setReadOnly(True)
        row_preview.addWidget(preview_edit, 1)
        v.addLayout(row_preview)

        def refresh_preview():
            stem = self._build_track_basename(
                artist_edit.text().strip(),
                title_edit.text().strip(),
                disc_edit.text().strip(),
                Path(path).stem,
            )
            preview_edit.setText(stem + Path(path).suffix)

        artist_edit.textChanged.connect(refresh_preview)
        title_edit.textChanged.connect(refresh_preview)
        disc_edit.textChanged.connect(refresh_preview)
        refresh_preview()

        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        v.addWidget(btns)

        def do_save():
            new_artist = artist_edit.text().strip()
            new_title = title_edit.text().strip()
            new_disc = disc_edit.text().strip()
            if not new_title:
                QMessageBox.warning(dlg, "Missing Title", "Please enter a title.")
                return
            try:
                rename_map, new_main_path = self._rename_track_files(path, new_artist, new_title, new_disc)
                if not rename_map:
                    rename_map = {path: path}
                self._apply_track_rename_map(rename_map, new_artist, new_title, new_disc)
                self._update_song_index_for_rename(rename_map, new_artist, new_title, new_disc)
                self._persist_tracks_json(trigger_reindex=False)
                self.update_queue_display()
                self.search_tracks()
                self.update_bg_track_display()
                try:
                    self._schedule_next_up_prescan()
                except Exception:
                    pass
                QMessageBox.information(dlg, "Saved", f"Updated:\n{new_main_path}")
                dlg.accept()
            except FileExistsError as e:
                QMessageBox.warning(dlg, "Name Exists", str(e))
            except Exception as e:
                QMessageBox.critical(dlg, "Rename Failed", str(e))

        btns.accepted.connect(do_save)
        btns.rejected.connect(dlg.reject)
        dlg.exec()



    def _compute_queue_eta_seconds(self) -> tuple[int, int]:
        """Return (active_singer_count, total_eta_seconds) for queue header."""
        karaoke_active = bool(getattr(self, "karaoke_playing", False))
        current_singer_name = str(getattr(self, "_current_karaoke_singer_name", "") or "").strip().lower()
        queued_active_singers = [s for s in self.queue if self.is_singer_active(s)]
        active_singers = [
            s for s in self.queue
            if self.is_singer_active(s)
            or (karaoke_active and str(s.get("name", "") or "").strip().lower() == current_singer_name)
        ]
        singer_count = len(active_singers)
        padding_singer_count = len(queued_active_singers)

        include_all_songs = bool(self.settings.get("rotation_estimate_include_all_songs", False))
        try:
            pad_per_singer = max(0, int(self.settings.get("rotation_padding_sec", 90)))
        except Exception:
            pad_per_singer = 90

        total_secs = 0
        for s in active_singers:
            non_skipped_songs = []
            for song in s.get("songs", []):
                if isinstance(song, dict):
                    if song.get("skipped", False):
                        continue
                    non_skipped_songs.append(song)
                else:
                    # Old format tuple/list entries are considered active.
                    non_skipped_songs.append(song)

            if not non_skipped_songs:
                continue

            songs_to_count = non_skipped_songs if include_all_songs else [non_skipped_songs[0]]

            for entry in songs_to_count:
                if isinstance(entry, dict):
                    song_info = entry.get("song_info")
                else:
                    try:
                        song_info = entry[0]
                    except Exception:
                        song_info = entry

                if isinstance(entry, dict) and "duration" in entry:
                    dur = entry.get("duration") or 0
                else:
                    song_path = song_info[0] if isinstance(song_info, (tuple, list)) else song_info
                    dur = self._get_duration_secs(song_path) or 0
                    try:
                        if isinstance(entry, dict):
                            entry["duration"] = dur
                    except Exception:
                        pass
                total_secs += dur

        total_secs += padding_singer_count * pad_per_singer
        if bool(getattr(self, "karaoke_playing", False)):
            try:
                total_secs += max(0, int(getattr(self, "_eta_hold_current_secs", 0) or 0))
            except Exception:
                pass
        return singer_count, total_secs

    def _update_queue_eta_label(self):
        try:
            self._rotation_recompute_round_state(force_reset=False)
        except Exception:
            pass
        _active_singer_count, total_secs = self._compute_queue_eta_seconds()
        try:
            singer_count = sum(
                1 for singer in (self.queue or [])
                if isinstance(singer, dict) and str(singer.get("name", "") or "").strip()
            )
        except Exception:
            singer_count = int(_active_singer_count or 0)
        eta_mss = self._fmt_m_ss(total_secs) if total_secs > 0 else "0:00"

        SHOW_END_TIME = True
        end_html = ""
        if SHOW_END_TIME and total_secs > 0:
            end_time = datetime.now() + timedelta(seconds=total_secs)
            time_str = end_time.strftime("%I:%M %p").lstrip("0")
            end_html = (
                '<span style="color:#5C6170;"> • </span>'
                '<span style="color:#FF5C5C; font-weight:700;">ENDS</span> '
                f'<span style="color:#FF3B3B; font-weight:900;">{time_str}</span>'
            )

        mode_label = "ROTATION" if self._is_rotation_mode() else "CLASSIC"
        locked_html = ""
        if self._is_rotation_locked():
            locked_html = (
                '<span style="color:#5C6170;"> • </span>'
                '<span style="color:#F3CB00; font-weight:900;">LOCKED</span>'
            )
        loop_html = ""
        if getattr(self, "_intro_loop_active", False):
            loop_html = (
                '<span style="color:#5C6170;"> • </span>'
                '<span style="color:#5AC8FA; font-weight:900;">LOOPING</span>'
            )

        start_html = ""
        if self._is_rotation_mode():
            try:
                marker_idx = int(self._rotation_marker_index())
                marker_name = str(self.queue[marker_idx].get("name", "") or "").strip() if 0 <= marker_idx < len(self.queue) else ""
            except Exception:
                marker_name = ""
            if marker_name:
                from html import escape as _html_escape
                start_html = (
                    '<span style="color:#5C6170;"> • </span>'
                    '<span style="color:#F3CB00; font-weight:900;">START</span> '
                    f'<span style="color:#FFF0A6; font-weight:850;">{_html_escape(marker_name)}</span>'
                )

        self.queue_label.setText(
            f'<span style="color:#9CA3B5; font-weight:700;">SINGERS</span> '
            f'<span style="color:#FFFFFF; font-weight:800;">{singer_count}</span>'
            f'<span style="color:#5C6170;"> • </span>'
            f'<span style="color:#9CA3B5; font-weight:700;">ETA</span> '
            f'<span style="color:#FFFFFF; font-weight:800;">{eta_mss}</span>'
            f'{end_html}'
            f'<span style="color:#5C6170;"> • </span>'
            f'<span style="color:#B994FF; font-weight:800;">{mode_label}</span>'
            f'{start_html}{locked_html}{loop_html}'
        )

    def update_queue_display(self):
        _perf_t0 = time.perf_counter()
        # ---- Thread safety guard ----
        # Background workers (network sends, decoder callbacks, etc.) can
        # indirectly reach this through state changes that trigger UI
        # refreshes.  Resetting the queue model from any thread other than the
        # main UI thread can crash Qt (SIGSEGV in endResetModel).
        # Defer to the main thread via QTimer.singleShot's 3-arg form
        # (Qt 5.15+) which fires the callback on the context object's
        # thread — i.e. always on the GUI thread.
        try:
            from PyQt6.QtCore import QThread as _QThread
            _qapp = QApplication.instance()
            _owner_thread = self.thread() if _qapp is not None else None
            if _qapp is not None and _owner_thread is not None and _QThread.currentThread() != _owner_thread:
                self._run_on_ui_thread(self.update_queue_display)
                return
        except Exception:
            pass

        # ---- Coalesce rapid back-to-back invalidations ----
        # During fast play/stop / mass remote requests, this method can
        # be called dozens of times in a single tick.  Each call clears
        # and rebuilds the queue widget.  We rebuild once per UI tick at
        # most by debouncing via a one-shot timer; the immediate first
        # call still runs synchronously so the user sees no perceptible
        # lag, but a burst of follow-up calls collapses into a single
        # additional refresh.
        try:
            if getattr(self, "_queue_display_busy", False):
                # Already inside a rebuild; coalesce by remembering we
                # want one more pass when this one finishes.
                self._queue_display_dirty = True
                return
            self._queue_display_busy = True
        except Exception:
            pass

        try:
            self._prune_expired_empty_rotation_slots()
            self._rotation_recompute_round_state(force_reset=False)
            self._rotation_repair_marker()
        except Exception:
            pass
        try:
            self._update_rotation_lock_button()
        except Exception:
            pass
        queue_updates_suspended = False
        try:
            self.queue_display.setUpdatesEnabled(False)
            queue_updates_suspended = True
        except Exception:
            queue_updates_suspended = False
        selected_identity = None
        try:
            selected_item = self.queue_display.currentItem()
            if selected_item is not None:
                kind = self._queue_item_kind(selected_item)
                if kind == "singer":
                    selected_identity = ("singer", self._queue_item_singer_index(selected_item, self.get_selected_index()), -1)
                elif kind == "song":
                    singer_idx, song_idx = self._queue_item_song_indices(selected_item, self.get_selected_index())
                    stable_entry_id = ""
                    try:
                        model = getattr(self, "queue_display_model", None)
                        row_data = model.rowDict(selected_item.row()) if isinstance(model, QueueListModel) else {}
                        entry = row_data.get("entry")
                        if isinstance(entry, dict):
                            stable_entry_id = self._ensure_queue_entry_id(entry)
                    except Exception:
                        stable_entry_id = ""
                    selected_identity = ("song", singer_idx, song_idx, stable_entry_id)
        except Exception:
            selected_identity = None
        model_rows = []
        self._update_queue_eta_label()
        self._update_rotation_summary_card()
        try:
            self._update_last_sung_card()
        except Exception:
            pass
        karaoke_active = bool(getattr(self, "karaoke_playing", False))
        current_song_path = str(getattr(self, "_current_karaoke_song_path", "") or "").strip().lower()
        current_singer_idx, next_active_singer_idx, current_mapping_warning = self._authoritative_rotation_indices()

        boundary_idx = -1
        try:
            if self._is_rotation_mode():
                boundary_idx = int(self._rotation_marker_index())
        except Exception:
            boundary_idx = -1

        presentation_next_singer_idx = next_active_singer_idx
        if presentation_next_singer_idx < 0:
            try:
                for i, s in enumerate(self.queue):
                    if s.get("skipped", False):
                        continue
                    if any((not song.get("skipped", False)) if isinstance(song, dict) else True for song in s.get("songs", [])):
                        presentation_next_singer_idx = i
                        break
            except Exception:
                presentation_next_singer_idx = -1

        try:
            pad_per_singer = max(0, int(self.settings.get("rotation_padding_sec", 90)))
        except Exception:
            pad_per_singer = 90
        queue_wait_secs = 0
        if karaoke_active:
            try:
                queue_wait_secs += max(0, int(getattr(self, "_eta_hold_current_secs", 0) or 0))
            except Exception:
                pass

        number = 1
        for singer_idx, singer in enumerate(self.queue):
            is_singer_skipped = singer.get("skipped", False)
            has_sung = singer.get("has_sung", False)  # New singers haven't sung yet
            self._ensure_singer_id(singer)
            is_current_singer = karaoke_active and singer_idx == current_singer_idx
            has_songs = singer.get("songs") and any(
                not song.get("skipped", False) if isinstance(song, dict) else True 
                for song in singer.get("songs", [])
            )
            
            # Only singers who actually have a song queued take a number, so the
            # numbers answer "how many until I'm up" directly and the host does
            # not have to subtract the placeholders. A singer with nothing in
            # still holds their row and their place -- add a song and they take
            # the next number at that same spot.
            if is_singer_skipped or not has_songs:
                singer_left = f"— {singer['name']}"
            else:
                singer_left = f"{number}. {singer['name']}"
                number += 1
            singer_right = self._queue_singer_status_label(
                singer,
                is_rotation_start=bool(self._is_rotation_mode() and singer_idx == boundary_idx),
                is_current=bool(is_current_singer),
                is_next=bool(karaoke_active and singer_idx == next_active_singer_idx),
            )

            if not is_singer_skipped:
                item = QListWidgetItem(singer_left)
                self._set_queue_row_identity(item, "singer", singer_idx, -1)
            else:
                item = QListWidgetItem(singer_left)
                self._set_queue_row_identity(item, "singer", singer_idx, -1)
            self._set_aligned_row_meta(item, singer_left, singer_right)
            # Duet: show "& Partner" in italics after the name for easy announcing.
            try:
                item.setData(self._row_duet_role, self._singer_duet_suffix(singer))
            except Exception:
                pass
            
            # Set colors based on status:
            # - RED text for skipped singers
            # - green accent text for new singers (hasn't sung yet)
            if is_singer_skipped:
                item.setForeground(QColor(_v("danger")))
            elif not has_sung:
                # New singer - green accent
                item.setForeground(QColor(_v("now_singing")))
            try:
                singer_font = item.font()
                singer_font.setBold(True)
                singer_font.setPointSize(max(singer_font.pointSize(), int(self._queue_base_point_size)))
                item.setFont(singer_font)
                item.setSizeHint(QSize(0, 34))
            except Exception:
                pass
            # Rotation boundary marker: yellow singer line (overrides green/new color).
            if self._is_rotation_mode() and singer_idx == boundary_idx and not is_singer_skipped:
                item.setForeground(QColor(_v("warning")))
            if is_current_singer:
                self._set_aligned_row_meta(item, singer_left, singer_right)
                item.setData(getattr(self, "_queue_presentation_role", int(Qt.ItemDataRole.UserRole) + 33), "current")
                item.setBackground(QColor(17, 94, 58, 220))
                item.setForeground(QColor("#FFFFFF"))
                try:
                    f = item.font()
                    f.setBold(True)
                    item.setFont(f)
                except Exception:
                    pass
            elif not has_songs and not is_singer_skipped:
                item.setForeground(QColor(_v("text_soft")))
                try:
                    f = item.font()
                    f.setItalic(True)
                    item.setFont(f)
                except Exception:
                    pass
            elif karaoke_active and singer_idx == next_active_singer_idx and not is_singer_skipped:
                self._set_aligned_row_meta(item, singer_left, singer_right)
                item.setData(getattr(self, "_queue_presentation_role", int(Qt.ItemDataRole.UserRole) + 33), "next")
                item.setBackground(QColor(70, 54, 16, 130))
                item.setForeground(QColor("#FFE49A"))
            
            model_rows.append(self._queue_model_row_from_item(item))

            first_active_song_seen = False
            first_active_entry = self._first_active_entry_for_singer(singer)
            for song_idx, entry in enumerate(singer.get("songs", [])):
                # Handle both dict and tuple format
                if isinstance(entry, dict):
                    song_info = entry.get("song_info")
                    key = entry.get("key", 0)
                    duet_display = entry.get("duet_display")
                    is_song_skipped = entry.get("skipped", False)
                else:
                    song_info = entry[0] if isinstance(entry, (tuple, list)) and len(entry) >= 1 else entry
                    key = entry[1] if isinstance(entry, (tuple, list)) and len(entry) >= 2 else 0
                    duet_display = entry[2] if isinstance(entry, (tuple, list)) and len(entry) >= 3 else None
                    is_song_skipped = False

                # NEW: Use pre-stored values (no lookups!)
                if isinstance(entry, dict) and "display_name" in entry:
                    display_name = entry["display_name"]
                    dur = entry.get("duration")
                else:
                    # Fallback for old format (will be slow first time, cached after)
                    song_path = song_info[0] if isinstance(song_info, (tuple, list)) else song_info
                    if karaoke_active:
                        display_name = os.path.basename(str(song_path or "")) or "Unknown"
                        dur = 0
                    else:
                        display_name = self.lookup_display_name(song_path)
                        dur = self._get_duration_secs(song_path)
                    # Convert to new format in place for next time
                    try:
                        entry["display_name"] = display_name
                        entry["duration"] = dur
                    except:
                        pass  # Can't upgrade tuple format
                # Build clean Mode-A two-column row:
                # Left = Artist • Title
                # Right = (Duet names if any)  DISCID  TIME  (Key if non-0)
                try:
                    visible, tooltip, left, right = self._build_queue_song_row_text(entry if isinstance(entry, dict) else {
                        "display_name": display_name,
                        "duration": dur,
                        "key": key,
                        "duet_display": duet_display
                    })
                except Exception:
                    visible = f"   • {display_name}"
                    tooltip = visible

                item = QListWidgetItem(visible)
                self._set_queue_row_identity(item, "song", singer_idx, song_idx)
                try:
                    song_font = item.font()
                    song_font.setPointSize(max(9, int(self._queue_base_point_size) - 1))
                    item.setFont(song_font)
                    item.setSizeHint(QSize(0, 31))
                except Exception:
                    pass
                # Keep underlying entry available for resize reformat (UserRole+1)
                try:
                    role_data = int(Qt.ItemDataRole.UserRole) + 1
                    if isinstance(entry, dict):
                        item.setData(role_data, entry)
                except Exception:
                    pass
                try:
                    item.setToolTip(tooltip)
                except Exception:
                    pass
                row_song_path = str(self._song_info_primary_path(song_info) or "").strip().lower()
                if isinstance(entry, dict) and self._is_external_karafun_entry(entry):
                    status = str(entry.get("karafun_status") or "").strip().lower()
                    status_label = {
                        "searching": "SEARCHING KARAFUN",
                        "ready": "KARAFUN READY",
                        "manual": "MANUAL KARAFUN",
                        "launching": "LAUNCHING KARAFUN",
                        "playing": "PLAYING KARAFUN",
                        "permission": "KARAFUN PERMISSION",
                        "failed": "KARAFUN FAILED",
                        "completed": "KARAFUN DONE",
                    }.get(status, "KARAFUN")
                    right = f"{status_label}  {right}" if right else status_label
                if is_song_skipped:
                    right = "SKIP  " + right if right else "SKIP"
                    item.setForeground(QColor(_v("danger")))
                elif karaoke_active and current_song_path and row_song_path == current_song_path:
                    right = "NOW  " + right if right else "NOW"
                    item.setBackground(QColor(109, 40, 255, 118))
                    item.setForeground(QColor("#FFFFFF"))
                    try:
                        f = item.font()
                        f.setBold(True)
                        item.setFont(f)
                    except Exception:
                        pass
                elif singer_idx == presentation_next_singer_idx and not first_active_song_seen and not is_song_skipped:
                    right = "CUE  " + right if right else "CUE"
                    item.setBackground(QColor(92, 74, 18, 90))
                    item.setForeground(QColor("#FFE9A6"))
                self._set_aligned_row_meta(item, left, right)
                # Duet songs show the partner ("& Jane") in italics right after the
                # song so the operator can see who's singing it with them.
                try:
                    item.setData(self._row_duet_role, self._duet_partner_suffix(duet_display))
                except Exception:
                    pass
                if not is_song_skipped and not first_active_song_seen:
                    first_active_song_seen = True
                model_rows.append(self._queue_model_row_from_item(item))

            if has_songs and not is_singer_skipped and not is_current_singer:
                queue_wait_secs += self._queue_entry_duration_for_display(first_active_entry) + pad_per_singer

        try:
            model = getattr(self, "queue_display_model", None)
            if isinstance(model, QueueListModel):
                model.syncRows(model_rows)
        except Exception:
            pass
        try:
            self._restore_queue_selection_after_rebuild(selected_identity)
        except Exception:
            pass
        if queue_updates_suspended:
            try:
                self.queue_display.setUpdatesEnabled(True)
            except Exception:
                pass
        self._finish_queue_display_refresh_side_effects()

        # Release the coalesce lock and replay if more refreshes piled up
        # while we were inside this call.
        try:
            self._queue_display_busy = False
            if getattr(self, "_queue_display_dirty", False):
                self._queue_display_dirty = False
                self._run_on_ui_thread(self.update_queue_display)
        except Exception:
            self._queue_display_busy = False
        _perf_log_if_slow("ui_update_queue_display", (time.perf_counter() - _perf_t0) * 1000.0)

    def _finish_queue_display_refresh_side_effects(self):
        try:
            app = QApplication.instance()
            owner_thread = self.thread() if app is not None else None
            if app is not None and owner_thread is not None and QThread.currentThread() != owner_thread:
                self._run_on_ui_thread(self._finish_queue_display_refresh_side_effects)
                return
        except Exception:
            pass
        self.update_rotation_view()
        try:
            timer = getattr(self, "rotation_post_timer", None)
            if timer is not None and QThread.currentThread() == timer.thread():
                timer.start(10000)  # 10,000 ms = 10 seconds debounce
        except Exception:
            pass
        self.schedule_ticker_update()  # Debounce ticker
        try:
            self._schedule_host_control_state_sync()
        except Exception:
            pass
        self._schedule_next_up_prescan()

    def eventFilter(self, obj, event):
        """Event filter:
        - Allow deselecting list items by clicking empty space (queue + search)
        - Debounced reformat on resize for Mode A two-column layout
        """
        try:
            et = event.type()
        except Exception:
            et = None
        try:
            queue_list = getattr(self, "queue_display", None)
            queue_viewport = queue_list.viewport() if queue_list is not None else None
        except RuntimeError:
            queue_list = None
            queue_viewport = None
        except Exception:
            queue_list = None
            queue_viewport = None
        try:
            results_list = getattr(self, "results_list", None)
            results_viewport = results_list.viewport() if results_list is not None else None
        except RuntimeError:
            results_list = None
            results_viewport = None
        except Exception:
            results_list = None
            results_viewport = None

        # Reformat lists when their viewport resizes (window drag / layout changes)
        try:
            if et == event.Type.Resize and (obj == queue_viewport or obj == results_viewport):
                self._schedule_reformat_lists()
        except Exception:
            pass

        # Queue deselect
        if queue_list is not None and obj == queue_viewport:
            try:
                if et == event.Type.MouseButtonPress:
                    index = queue_list.indexAt(event.pos())
                    if not index.isValid():
                        queue_list.clearSelection()
                        return True
            except RuntimeError:
                return False
            except Exception:
                pass

        # Search results deselect (matches queue behavior)
        if results_list is not None and obj == results_viewport:
            try:
                if et == event.Type.MouseButtonPress:
                    index = results_list.indexAt(event.pos())
                    if not index.isValid():
                        results_list.clearSelection()
                        return True
            except RuntimeError:
                return False
            except Exception:
                pass

        return super().eventFilter(obj, event)

    
    def get_selected_index(self):
        return self.queue_display.currentRow()

    def _row_for_singer_index(self, singer_idx: int) -> int:
        """Return queue_display row for a singer header by singer index."""
        if singer_idx < 0 or singer_idx >= len(self.queue):
            return -1
        try:
            model = getattr(self, "queue_display_model", None)
            if isinstance(model, QueueListModel):
                idx = model.indexForSinger(int(singer_idx))
                return int(idx.row()) if idx.isValid() else -1
        except Exception:
            pass
        row = 0
        for i, singer in enumerate(self.queue):
            if i == singer_idx:
                return row
            row += 1 + len(singer.get("songs", []))
        return -1

    def move_up(self):
        index = self.get_selected_index()
        if index <= 0 or index >= self.queue_display.count():
            return

        shift_held = bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ShiftModifier)
        current_item = self.queue_display.item(index)
        current_kind = self._queue_item_kind(current_item) if current_item is not None else ""
        undo = KaraokeApp._begin_undoable_action(self, "Reorder")

        # Move singer up
        if current_kind == "singer":
            i = self._queue_item_singer_index(current_item, index)
            if i > 0 and i < len(self.queue):
                if shift_held:
                    singer = self.queue.pop(i)
                    self.queue.insert(0, singer)
                    new_singer_idx = 0
                else:
                    self.queue[i - 1], self.queue[i] = self.queue[i], self.queue[i - 1]
                    new_singer_idx = i - 1
                self.update_queue_display()
                new_row = self._row_for_singer_index(new_singer_idx)
                self.queue_display.setCurrentRow(new_row)
        # Move song up within same singer only
        elif current_kind == "song":
            singer_idx, song_idx = self._queue_item_song_indices(current_item, index)
            if singer_idx != -1 and song_idx > 0:
                if shift_held:
                    songs = self.queue[singer_idx]["songs"]
                    song = songs.pop(song_idx)
                    songs.insert(0, song)
                    self.update_queue_display()
                    base_row = self._row_for_singer_index(singer_idx)
                    self.queue_display.setCurrentRow(base_row + 1)
                    self._sync_remote_singer_order(singer_idx)
                else:
                    # Swap songs in data
                    self.queue[singer_idx]["songs"][song_idx - 1], self.queue[singer_idx]["songs"][song_idx] = \
                        self.queue[singer_idx]["songs"][song_idx], self.queue[singer_idx]["songs"][song_idx - 1]
                    self.update_queue_display()
                    self.queue_display.setCurrentRow(index - 1)
                    self._refresh_queue_song_row_identities(singer_idx)
                    self._update_queue_eta_label()
                    self._sync_remote_singer_order(singer_idx)
                # Debounced ticker
                self.schedule_ticker_update()
        KaraokeApp._commit_undoable_action(self, undo, "Queue reordered")

    def move_down(self):
        index = self.get_selected_index()
        if index < 0 or index >= self.queue_display.count() - 1:
            return

        shift_held = bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ShiftModifier)
        current_item = self.queue_display.item(index)
        current_kind = self._queue_item_kind(current_item) if current_item is not None else ""
        undo = KaraokeApp._begin_undoable_action(self, "Reorder")

        # Move singer down
        if current_kind == "singer":
            i = self._queue_item_singer_index(current_item, index)
            if i < len(self.queue) - 1:
                if shift_held:
                    singer = self.queue.pop(i)
                    self.queue.append(singer)
                    new_singer_idx = len(self.queue) - 1
                else:
                    self.queue[i], self.queue[i + 1] = self.queue[i + 1], self.queue[i]
                    new_singer_idx = i + 1
                self.update_queue_display()
                new_row = self._row_for_singer_index(new_singer_idx)
                self.queue_display.setCurrentRow(new_row)
        # Move song down within same singer only
        elif current_kind == "song":
            singer_idx, song_idx = self._queue_item_song_indices(current_item, index)
            if singer_idx != -1 and song_idx < len(self.queue[singer_idx]["songs"]) - 1:
                if shift_held:
                    songs = self.queue[singer_idx]["songs"]
                    song = songs.pop(song_idx)
                    songs.append(song)
                    self.update_queue_display()
                    base_row = self._row_for_singer_index(singer_idx)
                    self.queue_display.setCurrentRow(base_row + len(songs))
                    self._sync_remote_singer_order(singer_idx)
                else:
                    # Swap songs in data
                    self.queue[singer_idx]["songs"][song_idx], self.queue[singer_idx]["songs"][song_idx + 1] = \
                        self.queue[singer_idx]["songs"][song_idx + 1], self.queue[singer_idx]["songs"][song_idx]
                    self.update_queue_display()
                    self.queue_display.setCurrentRow(index + 1)
                    self._refresh_queue_song_row_identities(singer_idx)
                    self._update_queue_eta_label()
                    self._sync_remote_singer_order(singer_idx)
                # Debounced ticker
                self.schedule_ticker_update()
        KaraokeApp._commit_undoable_action(self, undo, "Queue reordered")

    def clear_queue_with_confirmation(self):
        if not self.queue:
            return
        remote_ids = self._queue_remote_request_ids()
        message = "This will remove all songs from the local queue while keeping singers in the rotation."
        if self.is_network_configured():
            message += "\n\nIt will also clear the server queue/public rotation so stale requests do not reappear."
        message += "\nAre you sure you want to continue?"
        dlg = ConfirmInterruptDialog(
            self,
            title="Clear Entire Queue?",
            message=message,
            confirm_text="Clear Queue",
            cancel_text="Cancel",
        )
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        undo = KaraokeApp._begin_undoable_action(self, "Clear Rotation")
        if self.is_network_configured():
            try:
                self.stop_request_polling()
            except Exception:
                pass
        try:
            self._remote_clear_in_progress_until = time.time() + 20.0
        except Exception:
            pass
        try:
            for singer in list(self.queue or []):
                for entry in list((singer or {}).get("songs", []) or []):
                    remote_request_id = self._queue_entry_remote_request_id(entry)
                    if remote_request_id is not None:
                        self._record_remote_request_tombstone(
                            remote_request_id,
                            entry=entry,
                            singer_name=str((singer or {}).get("name", "") or ""),
                            reason="host_clear_queue",
                        )
        except Exception as e:
            _diag(f"[REMOTE-TOMBSTONE] clear queue tombstone pass failed: {e}")
        self._clear_queue_songs_preserving_singers(reason="host_clear_queue")
        self._pending_remote_order_syncs = {}
        # Monotonic revision bumped on every host reorder. The app is the source
        # of truth for show order; the revision is sent with order pushes so the
        # server/public display can adopt the host's ordering and never apply a
        # stale order on top of a newer host arrangement.
        self._queue_revision = 0
        self._unmatched_remote_request_ids = set()
        self._unmatched_request_sigs = set()
        self._relay_last_snapshot_signature = ""
        self.update_queue_display()
        try:
            self.save_data()
        except Exception:
            pass
        try:
            self.post_rotation()
        except Exception:
            pass
        try:
            self._clear_remote_queue_async(remote_ids, reason="host_clear_queue")
        except Exception as e:
            print(f"[REMOTE-CLEAR] local queue cleared; remote clear scheduling failed: {e}")
        print("[REMOTE-CLEAR] local queue cleared")
        KaraokeApp._commit_undoable_action(self, undo, "Rotation cleared")

    def remove_selected(self):
        shift_held = bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ShiftModifier)
        if shift_held and self.queue:
            self.clear_queue_with_confirmation()
            return

        index = self.get_selected_index()
        if index < 0 or index >= self.queue_display.count():
            return

        item = self.queue_display.item(index)
        item_kind = self._queue_item_kind(item) if item is not None else ""
        undo_name = "Remove Singer" if item_kind == "singer" else "Remove Song"
        undo = KaraokeApp._begin_undoable_action(self, undo_name)

        # Remove singer if it's a singer line
        if item_kind == "singer":
            singer_idx = self._queue_item_singer_index(item, index)
            if singer_idx != -1:
                try:
                    singer = self.queue[singer_idx]
                    for entry in list(singer.get("songs", []) or []):
                        remote_request_id = self._queue_entry_remote_request_id(entry)
                        if remote_request_id is not None:
                            self._delete_remote_request(
                                remote_request_id,
                                entry=entry,
                                singer_name=str(singer.get("name", "") or ""),
                                reason="host_remove_singer",
                            )
                except Exception:
                    pass
                self._delete_rotation_singer_row(singer_idx, reason="host_remove_singer")
        # Remove song if it's a song line
        elif item_kind == "song":
            singer_idx, song_idx = self._queue_item_song_indices(item, index)
            if singer_idx != -1 and song_idx != -1:
                try:
                    entry = self.queue[singer_idx]["songs"][song_idx]
                    remote_request_id = self._queue_entry_remote_request_id(entry)
                    if remote_request_id is not None:
                        self._delete_remote_request(
                            remote_request_id,
                            entry=entry,
                            singer_name=str(self.queue[singer_idx].get("name", "") or ""),
                            reason="host_remove_song",
                        )
                except Exception:
                    pass
                del self.queue[singer_idx]["songs"][song_idx]
                try:
                    if singer_idx < len(self.queue) and not self.queue[singer_idx].get("songs"):
                        self._mark_rotation_slot_temporarily_empty(self.queue[singer_idx], reason="host_remove_song")
                except Exception:
                    pass
                try:
                    if singer_idx < len(self.queue):
                        self._sync_remote_singer_order(singer_idx, reason="host_remove_song")
                except Exception:
                    pass

        self._request_queue_display_refresh()
        try:
            self._schedule_save_data(1000 if bool(getattr(self, "karaoke_playing", False)) else 0)
        except Exception:
            pass
        KaraokeApp._commit_undoable_action(
            self, undo,
            "Singer removed" if item_kind == "singer" else "Song removed",
        )

    def _resolve_karaoke_audio_path(self, song_info) -> str:
        """Return the best audio path for a queued karaoke entry (empty if not scannable)."""
        try:
            value = song_info
            if isinstance(value, dict):
                value = value.get("song_info")

            if isinstance(value, (tuple, list)):
                if not value:
                    return ""
                first = str(value[0])
                if first.lower().endswith(".cdg"):
                    if len(value) >= 2:
                        return str(value[1])
                    base, _ = os.path.splitext(first)
                    return base + ".mp3"
                if first.lower().endswith(".zip"):
                    return first
                return first

            path = str(value or "")
            if not path:
                return ""
            low = path.lower()
            if low.endswith(".cdg"):
                base, _ = os.path.splitext(path)
                return base + ".mp3"
            if low.endswith(".zip"):
                return path
            return path
        except Exception:
            return ""

    def _get_next_up_audio_path(self) -> str:
        """Find the next active queued song's audio path for prescan."""
        for singer in self.queue:
            if singer.get("skipped", False):
                continue
            for entry in singer.get("songs", []):
                if isinstance(entry, dict):
                    if entry.get("skipped", False):
                        continue
                    song_info = entry.get("song_info")
                else:
                    song_info = entry[0] if isinstance(entry, (tuple, list)) and len(entry) >= 1 else entry

                return self._resolve_karaoke_audio_path(song_info)
        return ""

    def _get_next_up_cdg_path(self) -> str:
        """Return an unzipped CDG path for the first playable queue entry."""
        for singer in self.queue:
            if singer.get("skipped", False):
                continue
            for entry in singer.get("songs", []):
                if isinstance(entry, dict):
                    if entry.get("skipped", False):
                        continue
                    song_info = entry.get("song_info")
                else:
                    song_info = entry[0] if isinstance(entry, (tuple, list)) and entry else entry
                path = self._song_info_primary_path(song_info)
                return path if str(path or "").lower().endswith(".cdg") else ""
        return ""

    def _preload_next_up_cdg(self, path: str):
        """Native mpv opens CDG media directly; no Python packet cache needed."""
        self._next_cdg_preload_path = ""

    def _apply_prescan_result(self, scan_key: str, token: int, offset: float, resolved_path: str | None = None):
        """Apply async scan result only if still current (stale-safe)."""
        if token != self._next_scan_token or scan_key != self._next_scan_path:
            return

        clamped = max(0.0, min(10.0, float(offset or 0.0)))
        resolved = str(resolved_path or scan_key)

        # Cache by both queue key (zip/mp3 path) and resolved audio path (usually mp3).
        self._silence_cache[scan_key] = clamped
        if resolved and resolved != scan_key:
            self._silence_cache[resolved] = clamped

        self._next_silence_path = resolved
        self._next_silence_offset = clamped
        print(f"[SILENCE] next-up prescan ready: {Path(resolved).name} offset={clamped:.2f}s")

    def _lead_silence_prescan_enabled(self) -> bool:
        try:
            return bool(self.settings.get("end_silence_trim_enabled", True))
        except Exception:
            return False

    def _prescan_next_track(self, path: str):
        """Scan only the current next-up song in a daemon thread."""
        if not path:
            self._next_silence_path = ""
            self._next_silence_offset = 0.0
            return
        if not self._lead_silence_prescan_enabled():
            self._next_scan_token += 1
            self._next_scan_path = ""
            self._next_silence_path = ""
            self._next_silence_offset = 0.0
            _diag(f"[SILENCE] next-up prescan skipped reason=disabled file={Path(path).name}")
            return

        self._next_scan_token += 1
        token = self._next_scan_token
        self._next_scan_path = path

        # Fast cache hit by queue key.
        if path in self._silence_cache:
            self._next_silence_path = path
            self._next_silence_offset = float(self._silence_cache.get(path, 0.0))
            try:
                if self._karaoke_normalize_active():
                    if loudness_gain_db_cached(path) is None:
                        analyze_loudness_async(path)
                else:
                    _diag(f"[LOUDNESS] next-up analysis skipped reason={self._karaoke_normalize_bypass_reason()} file={Path(path).name}")
            except Exception:
                pass
            return

        print(f"[SILENCE] prescan start: {Path(path).name}")

        def worker(scan_path: str, scan_token: int):
            try:
                inflight = getattr(self, "_next_prescan_inflight", None)
                if not isinstance(inflight, set):
                    inflight = set()
                    self._next_prescan_inflight = inflight
                inflight.add(scan_token)
            except Exception:
                pass
            resolved = scan_path
            try:
                if not self._lead_silence_prescan_enabled():
                    return
                low = scan_path.lower()
                if low.endswith('.zip'):
                    # Pre-extract next-up ZIP in background so silence scan can run on MP3.
                    cdg_p, mp3_p = self.zip_cache.get_extracted_paths(scan_path)
                    if mp3_p:
                        resolved = str(mp3_p)
                        print(f"[SILENCE] zip next-up extracted for prescan: {Path(resolved).name}")
                    else:
                        resolved = scan_path

                # Cache hit on resolved path (e.g., previously extracted mp3)
                if resolved in self._silence_cache:
                    offset = float(self._silence_cache.get(resolved, 0.0))
                else:
                    offset = detect_lead_silence(resolved)
                try:
                    if self._karaoke_normalize_active():
                        if loudness_gain_db_cached(resolved) is None:
                            analyze_loudness_async(resolved)
                            _diag(f"[LOUDNESS] queued next-up analysis for {Path(resolved).name}")
                    else:
                        _diag(f"[LOUDNESS] next-up analysis skipped reason={self._karaoke_normalize_bypass_reason()} file={Path(resolved).name}")
                except Exception:
                    pass
            except Exception:
                offset = 0.0
                resolved = scan_path

            finally:
                try:
                    inflight = getattr(self, "_next_prescan_inflight", None)
                    if isinstance(inflight, set):
                        inflight.discard(scan_token)
                except Exception:
                    pass

            # Safe to update state (no direct Qt UI here)
            if self._lead_silence_prescan_enabled():
                self._apply_prescan_result(scan_path, scan_token, offset, resolved_path=resolved)

        threading.Thread(target=worker, args=(path, token), daemon=True).start()

    def _schedule_next_up_prescan(self):
        """Re-evaluate next-up and scan only when it changes."""
        self._preload_next_up_cdg(self._get_next_up_cdg_path())
        if not self._lead_silence_prescan_enabled():
            self._next_scan_token += 1
            self._next_scan_path = ""
            self._next_silence_path = ""
            self._next_silence_offset = 0.0
            return
        next_path = self._get_next_up_audio_path()

        if not next_path:
            self._next_scan_token += 1
            self._next_scan_path = ""
            self._next_silence_path = ""
            self._next_silence_offset = 0.0
            return

        if next_path == self._next_scan_path:
            return

        self._prescan_next_track(next_path)

    def _consume_next_silence_offset(self, current_song_info) -> float:
        """Read and clear one-shot next-up offset for the currently starting song."""
        current_audio = self._resolve_karaoke_audio_path(current_song_info)
        offset = 0.0

        if current_audio:
            if current_audio == self._next_silence_path:
                offset = float(self._next_silence_offset or 0.0)
            else:
                offset = float(self._silence_cache.get(current_audio, 0.0))

        self._next_silence_path = ""
        self._next_silence_offset = 0.0

        # Immediately move prescan to the new next-up after consume.
        QTimer.singleShot(0, self._schedule_next_up_prescan)
        return max(0.0, min(10.0, offset))

    def _clear_bg_transition_timers(self):
        try:
            self._bg_transition_fade_timer.stop()
        except Exception:
            pass
        try:
            self._bg_transition_advance_timer.stop()
        except Exception:
            pass

    def _cancel_pending_karaoke_start_transition(self):
        """Invalidate and stop any delayed BG fade/advance scheduled for karaoke-start."""
        try:
            self._bg_transition_gen = int(getattr(self, "_bg_transition_gen", 0)) + 1
        except Exception:
            self._bg_transition_gen = 1
        self._clear_bg_transition_timers()
        try:
            self._bg_resume_timer.stop()
        except Exception:
            pass
        self._bg_resume_reason = "default"

    def _run_bg_transition_fade(self):
        if int(getattr(self, "_bg_transition_fade_gen", -1)) != int(getattr(self, "_bg_transition_gen", 0)):
            _diag("[TRANSITION] stale fade callback ignored")
            return
        try:
            fade_ms = max(200, int(getattr(self, "_bg_transition_fade_ms", self._bg_fade_duration_ms)))
            self.bg_music.fade_out(fade_ms)
        except Exception:
            pass

    def _run_bg_transition_advance(self):
        if int(getattr(self, "_bg_transition_advance_gen", -1)) != int(getattr(self, "_bg_transition_gen", 0)):
            _diag("[TRANSITION] stale advance callback ignored")
            return
        try:
            self._advance_bg_to_next_paused()
        finally:
            try:
                self.update_bg_button_state()
            except Exception:
                pass

    def _schedule_bg_resume(self, delay_ms: int, reason: str = "default"):
        try:
            self._bg_resume_timer.stop()
        except Exception:
            pass
        try:
            self._bg_resume_reason = str(reason or "default")
        except Exception:
            self._bg_resume_reason = "default"
        self._bg_resume_timer.start(max(0, int(delay_ms)))

    def _on_bg_resume_timer(self):
        self._start_bg_with_fade_safe("resume_timer")

    def _verify_bg_resume_started(self, generation: int):
        """Verify a requested idle resume produced real BASS playback; retry once."""
        if int(generation) != int(getattr(self, "_bg_resume_verify_gen", 0)):
            return
        if bool(getattr(self, "karaoke_playing", False)):
            return
        bg = getattr(self, "bg_music", None)
        if bg is None or not bool(getattr(bg, "playlist", None)):
            return
        if not bool(self.settings.get("bg_enabled", True)):
            return
        if not bool(self.settings.get("bg_autoplay_on_idle", True)):
            return
        try:
            effective = bool(bg.is_effectively_playing())
        except Exception:
            effective = False
        if effective:
            _diag(f"[BG-HANDOFF] playback verified generation={generation}")
            return
        if bool(getattr(self, "_bg_resume_verify_retried", False)):
            _diag(f"[BG-HANDOFF] playback still inactive after verified retry generation={generation}")
            return
        self._bg_resume_verify_retried = True
        _diag(f"[BG-HANDOFF] playback verification failed; resetting deck and retrying generation={generation}")
        try:
            bg.stop()
        except Exception:
            pass
        try:
            bg.preload_current_track_paused()
        except Exception:
            pass
        self._bg_resume_reason = "verified_retry"
        self._start_bg_with_fade_safe("verified_retry")

    def _clear_media_end_handoff_guard(self):
        self._media_end_handoff_active = False

    def _schedule_preview_overlay_refresh(self, delay_ms: int = 0, recreate_surface: bool = False):
        """Rebind the live preview sink after layout changes move the preview widget."""
        try:
            if not bool(getattr(self, "karaoke_playing", False)):
                return
            if not bool(getattr(self, "gst_preview_video_sink", None)):
                return
            if bool(recreate_surface):
                self._preview_overlay_refresh_recreate = True
            self._preview_overlay_refresh_timer.start(max(0, int(delay_ms)))
        except Exception:
            pass

    def _refresh_preview_overlay_binding(self):
        """Refresh preview sink binding/rectangle so it tracks the current widget position."""
        sink = getattr(self, "gst_preview_video_sink", None)
        preview = getattr(self, "preview_window", None)
        if sink is None or preview is None:
            return
        try:
            recreate_surface = bool(getattr(self, "_preview_overlay_refresh_recreate", False))
            self._preview_overlay_refresh_recreate = False
            if recreate_surface and sys.platform == "darwin":
                try:
                    preview.force_black = False
                    preview.update()
                except Exception:
                    pass
            try:
                preview.layout().activate()
            except Exception:
                pass
            area = getattr(preview, "video_area", None)
            if area is None:
                return
            try:
                area.updateGeometry()
                area.update()
            except Exception:
                pass
            self._prepare_overlay(sink, area.winId())
            try:
                sink.set_render_rectangle(0, 0, int(area.width()), int(area.height()))
            except Exception:
                pass
            try:
                GstVideo.VideoOverlay.expose(sink)
            except Exception:
                try:
                    sink.expose()
                except Exception:
                    pass
            try:
                top_left = area.mapToGlobal(QPoint(0, 0))
                gx = int(top_left.x())
                gy = int(top_left.y())
            except Exception:
                gx = -1
                gy = -1
            _diag(
                f"[PREVIEW] overlay refresh win={int(area.winId())} "
                f"w={int(area.width())} h={int(area.height())} gx={gx} gy={gy} recreate={recreate_surface}"
            )
        except Exception:
            pass

    def _cancel_pending_media_end_cleanup(self, reason: str = "unknown", clear_handoff: bool = True):
        """Invalidate delayed media-end cleanup so stale callbacks cannot fire later."""
        try:
            self._media_end_cleanup_gen = int(getattr(self, "_media_end_cleanup_gen", 0)) + 1
        except Exception:
            self._media_end_cleanup_gen = 1
        try:
            self._media_end_cleanup_timer.stop()
        except Exception:
            pass
        self._media_end_cleanup_end_silence_triggered = False
        self._media_end_cleanup_schedule_bg_resume = False
        if clear_handoff:
            try:
                self._media_end_handoff_timer.stop()
            except Exception:
                pass
            self._media_end_handoff_active = False
        try:
            _diag(f"[END] pending media-end cleanup cancelled reason={reason}")
        except Exception:
            pass

    def _schedule_media_end_cleanup(self, delay_ms: int, end_silence_triggered: bool, schedule_bg_resume: bool):
        """Schedule cancellable media-end cleanup owned by a generation token."""
        try:
            self._media_end_cleanup_gen = int(getattr(self, "_media_end_cleanup_gen", 0)) + 1
        except Exception:
            self._media_end_cleanup_gen = 1
        self._scheduled_media_end_cleanup_gen = int(self._media_end_cleanup_gen)
        self._media_end_cleanup_end_silence_triggered = bool(end_silence_triggered)
        self._media_end_cleanup_schedule_bg_resume = bool(schedule_bg_resume)
        try:
            self._media_end_cleanup_timer.stop()
        except Exception:
            pass
        self._media_end_cleanup_timer.start(max(0, int(delay_ms)))

    def _run_media_end_cleanup(self):
        current_gen = int(getattr(self, "_media_end_cleanup_gen", 0))
        scheduled_gen = int(getattr(self, "_scheduled_media_end_cleanup_gen", -1))
        if scheduled_gen != current_gen:
            _diag("[END] stale media-end cleanup ignored")
            return
        if bool(getattr(self, "_stop_in_progress", False)):
            _diag("[END] media-end cleanup skipped: teardown already in progress")
            return
        self._finish_media_end_cleanup(
            bool(getattr(self, "_media_end_cleanup_end_silence_triggered", False)),
            bool(getattr(self, "_media_end_cleanup_schedule_bg_resume", False)),
        )

    def _prepare_bg_for_karaoke_start(self, current_song_info):
        """Fade/advance BG with lead-silence offset + fixed transition gap."""
        if not self.bg_music.playlist:
            return

        # Cancel any stale transition actions before scheduling a new one.
        self._bg_transition_gen = int(getattr(self, "_bg_transition_gen", 0)) + 1
        self._clear_bg_transition_timers()
        current_gen = int(self._bg_transition_gen)

        lead_offset = self._consume_next_silence_offset(current_song_info)
        gap_sec = max(-3.0, min(3.0, float(self._transition_gap_sec)))
        fade_ms = max(200, int(self._bg_fade_duration_ms))
        fade_sec = float(fade_ms) / 1000.0

        # Start fade so fade END lands near (lead_offset - gap_sec).
        # +gap => more silence before karaoke content, -gap => more overlap.
        delay_ms = max(0, int(round((lead_offset - gap_sec - fade_sec) * 1000.0)))

        if self.bg_music.is_playing:
            self._bg_transition_fade_ms = fade_ms
            if delay_ms > 0:
                _diag(f"[TRANSITION] delaying BG fade by {delay_ms}ms (lead_offset={lead_offset:.2f}s gap={gap_sec:+.1f}s fade={fade_sec:.2f}s)")
                self._bg_transition_fade_gen = current_gen
                self._bg_transition_fade_timer.start(delay_ms)
            else:
                self._bg_transition_fade_gen = current_gen
                self._run_bg_transition_fade()
            advance_after_ms = delay_ms + fade_ms + 100
        else:
            advance_after_ms = max(100, delay_ms)

        self._bg_transition_advance_gen = current_gen
        self._bg_transition_advance_timer.start(max(0, int(advance_after_ms)))

    def _is_external_karafun_entry(self, entry) -> bool:
        if not isinstance(entry, dict):
            return False
        provider = str(entry.get("provider") or "").strip().lower()
        if provider in {"karafun_local", "karafun_streaming", "external_karafun"}:
            return True
        path = self._song_info_primary_path(entry.get("song_info"))
        return str(path or "").lower().startswith(("karafun_streaming:", "karafun_local:", "external_karafun:"))

    def _karafun_entry_artist_title(self, entry: dict) -> tuple[str, str]:
        artist = str((entry or {}).get("artist") or "").strip()
        title = str((entry or {}).get("title") or "").strip()
        if title:
            return artist, title
        display = str((entry or {}).get("display_name") or (entry or {}).get("display") or "").strip()
        if " - " in display:
            parts = [p.strip() for p in display.split(" - ") if p.strip()]
            if len(parts) >= 2:
                return artist or parts[0], title or parts[1]
        return artist, title or display or "KaraFun Song"

    def _karafun_lookup_text(self, entry: dict) -> str:
        artist, title = self._karafun_entry_artist_title(entry)
        bits = []
        if artist or title:
            bits.append(" - ".join([p for p in (artist, title) if p]))
        provider_track_id = str((entry or {}).get("provider_track_id") or "").strip()
        provider_url = str((entry or {}).get("provider_url") or "").strip()
        local_ref = str((entry or {}).get("local_reference_path") or "").strip()
        if provider_track_id:
            bits.append(f"KaraFun ID/search: {provider_track_id}")
        if provider_url:
            bits.append(provider_url)
        elif local_ref:
            bits.append(local_ref)
        return "\n".join([b for b in bits if b]).strip()

    def _open_karafun_for_entry(self, entry: dict) -> bool:
        provider_url = str((entry or {}).get("provider_url") or "").strip()
        local_ref = str((entry or {}).get("local_reference_path") or "").strip()
        target = provider_url or local_ref
        self._last_karafun_launch_error = ""
        try:
            if sys.platform == "darwin":
                app_path = self._karafun_application_path()
                if not app_path:
                    raise FileNotFoundError(
                        "KaraFun.app was not found in /Applications or ~/Applications. "
                        "Install KaraFun, open it once, then retry."
                    )
                args = ["/usr/bin/open", str(app_path)]
                # Local KaraFun documents should be handed directly to KaraFun.
                # Catalog URLs are deliberately not opened in the default
                # browser while automatic queueing is enabled; the Accessibility
                # workflow searches the native app for the exact song instead.
                if local_ref:
                    args = ["/usr/bin/open", "-a", str(app_path), local_ref]
                completed = subprocess.run(args, capture_output=True, text=True, timeout=10)
                if completed.returncode != 0:
                    raise RuntimeError(
                        str(completed.stderr or completed.stdout or "macOS could not launch KaraFun").strip()
                    )
                if target and not local_ref and not bool(self.settings.get("karafun_auto_queue_enabled", False)):
                    QDesktopServices.openUrl(QUrl(target))
                _diag(
                    f"[KARAFUN] launched app={str(app_path)!r} arch={platform.machine()} "
                    f"automatic={int(bool(self.settings.get('karafun_auto_queue_enabled', False)))}"
                )
                return True
        except Exception as e:
            self._last_karafun_launch_error = str(e)
            _diag(f"[KARAFUN] open failed: {e}")
        return False

    @staticmethod
    def _karafun_application_candidates() -> list[Path]:
        candidates = []
        for folder in (Path("/Applications"), Path.home() / "Applications"):
            candidates.append(folder / "KaraFun.app")
            try:
                candidates.extend(sorted(folder.glob("KaraFun*.app")))
            except Exception:
                pass
        unique = []
        seen = set()
        for candidate in candidates:
            key = os.path.normcase(os.path.realpath(str(candidate)))
            if key not in seen:
                unique.append(candidate)
                seen.add(key)
        return unique

    @classmethod
    def _karafun_application_path(cls) -> Path | None:
        if sys.platform != "darwin":
            return None
        # LaunchServices is preferable when KaraFun has already been opened,
        # but clean Intel installations may not have registered it yet.
        try:
            from AppKit import NSWorkspace
            url = NSWorkspace.sharedWorkspace().URLForApplicationWithBundleIdentifier_("com.recisio.kfiphone")
            if url is not None:
                path = Path(str(url.path()))
                if path.is_dir():
                    return path
        except Exception as e:
            _diag(f"[KARAFUN] LaunchServices lookup unavailable: {e}")
        for candidate in cls._karafun_application_candidates():
            if candidate.is_dir() and (candidate / "Contents" / "MacOS" / "KaraFun").exists():
                return candidate
        return None

    @staticmethod
    def _karafun_script_source(lines) -> str:
        return "\n".join(str(line) for line in (lines or []))

    @staticmethod
    def _karafun_applescript_literal(value: str) -> str:
        text = str(value or "").replace("\\", "\\\\").replace('"', '\\"').replace("\r", " ").replace("\n", " ")
        return f'"{text}"'

    def _run_karafun_applescript_sync(self, lines, *, timeout: float | None = None) -> tuple[bool, str, str]:
        """Run AppleScript inside SingWS so Accessibility permission belongs to SingWS, not /usr/bin/osascript."""
        source = self._karafun_script_source(lines)
        if not source.strip():
            return False, "", "empty_script"
        if sys.platform == "darwin":
            try:
                from AppKit import NSAppleScript
                script = NSAppleScript.alloc().initWithSource_(source)
                result, error = script.executeAndReturnError_(None)
                if error:
                    error_text = str(error)
                    _diag(
                        f"[KARAFUN-SCRIPT] failed arch={platform.machine()} frozen={int(bool(getattr(sys, 'frozen', False)))} "
                        f"executable={str(sys.executable)!r} error={error_text!r}"
                    )
                    return False, "", error_text
                try:
                    return True, str(result.stringValue() if result is not None else "").strip(), ""
                except Exception:
                    return True, "", ""
            except Exception as e:
                _diag(f"[KARAFUN] NSAppleScript fallback to osascript: {e}")
        try:
            args = ["osascript"]
            for line in lines:
                args.extend(["-e", str(line)])
            completed = subprocess.run(
                args,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
            if completed.returncode != 0:
                stderr = str(completed.stderr or "").strip()
                _diag(
                    f"[KARAFUN-SCRIPT] osascript failed arch={platform.machine()} "
                    f"returncode={completed.returncode} error={stderr!r}"
                )
                return False, str(completed.stdout or "").strip(), stderr
            return True, str(completed.stdout or "").strip(), str(completed.stderr or "").strip()
        except Exception as e:
            return False, "", str(e)

    @staticmethod
    def _is_karafun_accessibility_error(message: str) -> bool:
        text = str(message or "").lower()
        return (
            "not allowed assistive access" in text
            or "accessibility" in text and "not allowed" in text
            or "-25211" in text
        )

    @staticmethod
    def _is_karafun_ui_not_ready_error(message: str) -> bool:
        """True for "KaraFun's window is not built yet", not "no such song".

        KaraFun is launched and driven in the same breath, so the first search
        can arrive before its window exists and System Events answers with
        AXError -1719 / "Invalid index". That is transient and says nothing
        about the catalog: it must be retried with the SAME query rather than
        falling through to a looser one.
        """
        text = str(message or "").lower()
        if not text:
            return False
        if "-1743" in text or "-25211" in text:
            return False
        return (
            "-1719" in text
            or "invalid index" in text
            or "can\u2019t get" in text
            or "can't get" in text
            or "is not defined" in text
        )

    @staticmethod
    def _is_karafun_apple_events_error(message: str) -> bool:
        text = str(message or "").lower()
        return (
            "-1743" in text
            or "not authorized to send apple events" in text
            or ("apple events" in text and "not permitted" in text)
        )

    def _show_karafun_apple_events_setup(self, *, notify: bool = True):
        message = (
            "macOS blocked SingWS from controlling System Events (Apple Event error -1743). "
            "Open System Settings > Privacy & Security > Automation, enable System Events under SingWS, "
            "then quit and reopen both SingWS and KaraFun. If SingWS is not listed, retry one KaraFun song "
            "with this updated build so macOS can show the authorization prompt."
        )
        _diag(f"[KARAFUN] Apple Events authorization required arch={platform.machine()}")
        if notify:
            try:
                self._show_processing_notification(message, level="warning", persistent=True)
            except Exception:
                pass
            try:
                QMessageBox.warning(self, "KaraFun Automation Permission Needed", message)
            except Exception:
                pass
        try:
            if sys.platform == "darwin":
                QDesktopServices.openUrl(QUrl("x-apple.systempreferences:com.apple.preference.security?Privacy_Automation"))
        except Exception:
            pass
        return message

    def _karafun_apple_events_preflight(self) -> tuple[bool, str]:
        ok, stdout, stderr = self._run_karafun_applescript_sync(
            [
                'tell application "System Events"',
                'set matches to every application process whose name contains "KaraFun"',
                'if (count of matches) is 0 then return "AUTHORIZED|0"',
                'return "AUTHORIZED|" & (unix id of item 1 of matches as text)',
                'end tell',
            ],
            timeout=8,
        )
        if ok:
            try:
                self._karafun_process_id = int(str(stdout or "").split("|")[-1])
            except Exception:
                self._karafun_process_id = 0
            return True, str(stdout or "AUTHORIZED")
        return False, str(stderr or stdout or "Apple Events authorization failed")

    def _karafun_target_audio_output_name(self) -> str:
        explicit = str(self.settings.get("karafun_audio_output_name", "") or "").strip()
        if explicit:
            return explicit
        if bool(self.settings.get("karafun_audio_output_follow_singws", True)):
            # A saved headphone name can disappear when it is unplugged; use
            # the same live local fallback as native karaoke and BGM.
            return self._safe_local_audio_output_name() or ""
        return ""

    def _ensure_karafun_audio_output(self) -> tuple[bool, str]:
        """Validate the intended route without opening KaraFun's settings UI.

        KaraFun persists its own output choice. Trying to re-select that choice
        before every song opened Audio Settings, walked the entire Accessibility
        tree for as long as 25 seconds, and could leave popovers over the app.
        The 2026-08-13 show then aborted a valid song merely because KaraFun's
        label did not exactly match SingWS's ``External Headphones`` label.
        Keep the AirPlay/display guard, but trust the already-configured KaraFun
        route and let the normal playback monitor detect a genuine failure.
        """
        target = self._karafun_target_audio_output_name()
        if not target:
            _diag(
                "[KARAFUN-AUDIO] using KaraFun's saved output; "
                "SingWS has no named local route to compare"
            )
            return True, "KaraFun saved output"
        target_key = self._normalized_audio_output_name(target)
        if any(word in target_key for word in ("airplay", "apple tv", "bravia", "television", "display")):
            return False, f"KaraFun audio output {target!r} looks like a display/AirPlay route. Choose headphones or a USB interface."
        _diag(
            f"[KARAFUN-AUDIO] trusting saved KaraFun route; expected local output={target!r} "
            "settings_ui_opened=0"
        )
        return True, target

    def _show_karafun_accessibility_setup(self, *, notify: bool = True):
        message = (
            "KaraFun automation needs macOS Accessibility permission for SingWS. "
            "Open System Settings > Privacy & Security > Accessibility, enable SingWS, "
            "then quit and reopen SingWS."
        )
        try:
            _diag("[KARAFUN] accessibility permission required for automation")
        except Exception:
            pass
        if notify:
            try:
                self._show_processing_notification(message, level="warning", persistent=True)
            except Exception:
                pass
            try:
                QMessageBox.warning(self, "KaraFun Automation Permission Needed", message)
            except Exception:
                pass
        try:
            if sys.platform == "darwin":
                QDesktopServices.openUrl(QUrl("x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility"))
        except Exception:
            pass
        return message

    def _request_karafun_accessibility_on_first_launch(self):
        """Ask macOS for Accessibility trust once, after the main UI appears."""
        if sys.platform != "darwin":
            return
        if not bool(self.settings.get("karafun_auto_queue_enabled", False)):
            return
        if bool(self.settings.get("karafun_accessibility_prompt_requested", False)):
            return
        # Persist before invoking macOS: dismissing the system prompt must not
        # turn every subsequent launch into another unsolicited prompt.
        self.settings["karafun_accessibility_prompt_requested"] = True
        try:
            self.save_settings()
        except Exception:
            pass
        try:
            import objc
            from Foundation import NSDictionary

            options = NSDictionary.dictionaryWithObject_forKey_(
                True, "AXTrustedCheckOptionPrompt"
            )
            app_services = ctypes.CDLL(
                "/System/Library/Frameworks/ApplicationServices.framework/ApplicationServices"
            )
            app_services.AXIsProcessTrustedWithOptions.argtypes = [ctypes.c_void_p]
            app_services.AXIsProcessTrustedWithOptions.restype = ctypes.c_bool
            trusted = bool(app_services.AXIsProcessTrustedWithOptions(objc.pyobjc_id(options)))
            _diag(f"[KARAFUN] accessibility launch preflight trusted={int(trusted)} prompt_requested=1")
        except Exception as exc:
            _diag(f"[KARAFUN] accessibility launch prompt unavailable: {exc}")

    def _karafun_run_window_script(self, lines, on_complete=None, *, timeout: float = 18) -> bool:
        """Run non-blocking macOS Accessibility automation for KaraFun."""
        if sys.platform != "darwin":
            return False
        try:
            if callable(on_complete):
                def _wait_then_complete():
                    ok, stdout, stderr = self._run_karafun_applescript_sync(lines, timeout=timeout)
                    result = str(stdout or "").strip()
                    if not ok:
                        _diag(f"[KARAFUN] window script failed error={str(stderr or '').strip()[:240]!r}")

                    def _deliver_completion():
                        try:
                            on_complete(result)
                        except TypeError:
                            on_complete()
                        except Exception as e:
                            _diag(f"[KARAFUN] window automation completion failed: {e}")

                    # Completion handlers schedule Qt timers and inspect Qt
                    # windows. Always deliver them on the UI thread; a
                    # QTimer.singleShot created from this worker thread can be
                    # silently lost because the worker has no Qt event loop.
                    self._run_on_ui_thread(_deliver_completion)
                threading.Thread(target=_wait_then_complete, daemon=True).start()
            else:
                def _fire_and_forget():
                    ok, _stdout, stderr = self._run_karafun_applescript_sync(lines, timeout=timeout)
                    if not ok:
                        _diag(f"[KARAFUN] window script failed error={str(stderr or '').strip()[:240]!r}")
                threading.Thread(target=_fire_and_forget, daemon=True).start()
            return True
        except Exception as e:
            _diag(f"[KARAFUN] window automation failed: {e}")
            return False

    @staticmethod
    def _macos_native_mouse_click(x: int, y: int, *, clicks: int = 1) -> bool:
        """Post one or more genuine mouse clicks at a macOS screen point."""
        if sys.platform != "darwin":
            return False
        try:
            class CGPoint(ctypes.Structure):
                _fields_ = [("x", ctypes.c_double), ("y", ctypes.c_double)]

            cg = ctypes.CDLL("/System/Library/Frameworks/ApplicationServices.framework/ApplicationServices")
            cf = ctypes.CDLL("/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation")
            cg.CGEventCreateMouseEvent.restype = ctypes.c_void_p
            cg.CGEventCreateMouseEvent.argtypes = [ctypes.c_void_p, ctypes.c_uint32, CGPoint, ctypes.c_uint32]
            cg.CGEventSetIntegerValueField.argtypes = [ctypes.c_void_p, ctypes.c_uint32, ctypes.c_int64]
            cg.CGEventPost.argtypes = [ctypes.c_uint32, ctypes.c_void_p]
            cf.CFRelease.argtypes = [ctypes.c_void_p]
            point = CGPoint(float(x), float(y))
            for click_count in range(1, max(1, int(clicks or 1)) + 1):
                down = cg.CGEventCreateMouseEvent(None, 1, point, 0)  # leftMouseDown
                up = cg.CGEventCreateMouseEvent(None, 2, point, 0)    # leftMouseUp
                if not down or not up:
                    return False
                cg.CGEventSetIntegerValueField(down, 1, click_count)  # mouseEventClickState
                cg.CGEventSetIntegerValueField(up, 1, click_count)
                cg.CGEventPost(0, down)  # cghidEventTap
                cg.CGEventPost(0, up)
                cf.CFRelease(down)
                cf.CFRelease(up)
                time.sleep(0.08)
            return True
        except Exception as e:
            _diag(f"[KARAFUN] native mouse click failed: {e}")
            return False

    @staticmethod
    def _macos_native_double_click(x: int, y: int) -> bool:
        """Post a genuine two-click mouse sequence at a macOS screen point."""
        return KaraokeApp._macos_native_mouse_click(x, y, clicks=2)

    def _handoff_show_screen_to_karafun(self):
        """Reveal KaraFun on the show display, preferring an instant transparent overlay."""
        if sys.platform != "darwin" or not bool(self.settings.get("karafun_manage_show_screen", True)):
            return
        if bool(getattr(self, "_karafun_handoff_in_progress", False)):
            _diag("[KARAFUN] show-screen handoff already in progress; duplicate ignored")
            return
        if bool(getattr(self, "_karafun_handoff_complete", False)):
            _diag("[KARAFUN] show-screen handoff already complete; duplicate ignored")
            return
        vw = getattr(self, "video_window", None)
        if vw is None:
            return
        handoff_token = uuid.uuid4().hex
        self._karafun_handoff_token = handoff_token
        self._karafun_handoff_in_progress = True
        self._karafun_handoff_complete = False

        def _handoff_is_current() -> bool:
            return (
                getattr(self, "_karafun_handoff_token", None) == handoff_token
                and isinstance(getattr(self, "_active_external_karafun", None), dict)
            )

        def _finish_handoff_state(*, complete: bool):
            if getattr(self, "_karafun_handoff_token", None) != handoff_token:
                return
            self._karafun_handoff_in_progress = False
            self._karafun_handoff_complete = bool(complete)

        if (
            bool(self.settings.get("karafun_transparent_handoff", True))
            and bool(getattr(self, "_karafun_transparent_renderer_ready", False))
        ):
            try:
                frame = vw.frameGeometry()
                screen = QApplication.screenAt(frame.center()) or vw.screen() or QApplication.primaryScreen()
                screen_rect = screen.geometry() if screen is not None else frame
                self._karafun_show_screen_restore = {
                    "mode": "transparent",
                    "geometry": vw.geometry(),
                    "fullscreen": bool(vw.isFullScreen()),
                    "maximized": bool(vw.isMaximized()),
                    "visible": bool(vw.isVisible()),
                    "window_opacity": float(vw.windowOpacity()),
                    "screen_geometry": screen_rect,
                }
                state = self._karafun_show_screen_restore
                x, y = int(screen_rect.x()), int(screen_rect.y())
                width, height = int(screen_rect.width()), int(screen_rect.height())
            except Exception as e:
                _finish_handoff_state(complete=False)
                _diag(f"[KARAFUN] transparent show-screen handoff failed: {e}")
                return

            def _reveal_true_fullscreen(result=""):
                if not _handoff_is_current():
                    _diag("[KARAFUN] skipped stale true-fullscreen reveal")
                    return
                verified = str(result or "").strip() == "FULLSCREEN"
                if not verified:
                    _finish_handoff_state(complete=False)
                    _diag(f"[KARAFUN] renderer not verified; retaining show screen result={result!r}")
                    return
                try:
                    vw.setWindowOpacity(0.0)
                    _finish_handoff_state(complete=True)
                    _diag(
                        f"[KARAFUN] SingWS show screen opacity=0; "
                        f"revealed KaraFun true_fullscreen={int(verified)}"
                    )
                except Exception as e:
                    _finish_handoff_state(complete=False)
                    _diag(f"[KARAFUN] true-fullscreen reveal failed: {e}")

            def _check_or_enter_true_fullscreen():
                ensure_renderer_fullscreen(self, _reveal_true_fullscreen, _handoff_is_current)

            def _configure_auxiliary_window():
                if not _handoff_is_current():
                    return
                try:
                    import objc
                    from AppKit import (
                        NSFloatingWindowLevel,
                        NSWindowCollectionBehaviorCanJoinAllSpaces,
                        NSWindowCollectionBehaviorFullScreenAuxiliary,
                        NSWindowCollectionBehaviorFullScreenPrimary,
                        NSWindowStyleMaskBorderless,
                    )

                    vw.setWindowState(Qt.WindowState.WindowNoState)
                    vw.setGeometry(screen_rect)
                    vw.show()
                    QApplication.processEvents()
                    native_view = objc.objc_object(c_void_p=int(QWidget.winId(vw)))
                    native_window = native_view.window()
                    if native_window is None:
                        raise RuntimeError("SingWS native audience window unavailable")
                    if "native_style_mask" not in state:
                        state["native_style_mask"] = int(native_window.styleMask())
                        state["native_collection_behavior"] = int(native_window.collectionBehavior())
                        state["native_level"] = int(native_window.level())
                        state["native_ignores_mouse"] = bool(native_window.ignoresMouseEvents())
                    behavior = int(native_window.collectionBehavior())
                    behavior &= ~int(NSWindowCollectionBehaviorFullScreenPrimary)
                    behavior |= int(NSWindowCollectionBehaviorCanJoinAllSpaces)
                    behavior |= int(NSWindowCollectionBehaviorFullScreenAuxiliary)
                    native_window.setStyleMask_(NSWindowStyleMaskBorderless)
                    native_window.setCollectionBehavior_(behavior)
                    native_window.setLevel_(NSFloatingWindowLevel)
                    native_window.setIgnoresMouseEvents_(True)
                    vw.setGeometry(screen_rect)
                    native_window.orderFrontRegardless()
                    state["native_window"] = native_window
                    self._karafun_auxiliary_show_screen = True
                    _diag(
                        f"[KARAFUN] SingWS show screen configured fullscreen auxiliary "
                        f"bounds={x},{y},{width},{height}"
                    )
                    QTimer.singleShot(250, _check_or_enter_true_fullscreen)
                except Exception as e:
                    _diag(f"[KARAFUN] fullscreen auxiliary setup failed: {e}; using windowed reveal")
                    _reveal_true_fullscreen("AUXILIARY_SETUP_FAILED")

            # A Qt native-fullscreen window is a primary Space and cannot join
            # KaraFun's fullscreen Space in place. Leave that Space first, then
            # convert the same native audience window to a borderless auxiliary.
            if bool(getattr(self, "_karafun_auxiliary_show_screen", False)):
                QTimer.singleShot(0, _configure_auxiliary_window)
            else:
                vw.showNormal()
                QTimer.singleShot(700, _configure_auxiliary_window)
            return

        try:
            frame = vw.frameGeometry()
            screen = QApplication.screenAt(frame.center()) or vw.screen() or QApplication.primaryScreen()
            rect = screen.geometry() if screen is not None else frame
            self._karafun_show_screen_restore = {
                "geometry": vw.geometry(),
                "fullscreen": bool(vw.isFullScreen()),
                "maximized": bool(vw.isMaximized()),
                "visible": bool(vw.isVisible()),
                "screen_geometry": rect,
            }
            # A minimized Qt fullscreen window can leave its macOS fullscreen
            # Space active.  KaraFun then becomes the frontmost application,
            # but its Dual Renderer remains in another Space until the host
            # switches to it manually.  Leave the SingWS fullscreen Space and
            # hide the audience window before raising KaraFun so the handoff is
            # visible immediately.  The snapshot above is used to restore the
            # original fullscreen state after KaraFun completes.
            vw.setWindowState(Qt.WindowState.WindowNoState)
            vw.showNormal()
            vw.hide()
            x, y, width, height = int(rect.x()), int(rect.y()), int(rect.width()), int(rect.height())
        except Exception as e:
            _finish_handoff_state(complete=False)
            _diag(f"[KARAFUN] show-screen snapshot failed: {e}")
            return

        def _fullscreen_karafun(attempt=0):
            if not _handoff_is_current():
                _diag("[KARAFUN] skipped stale show-screen handoff attempt")
                return
            lines = [
                'tell application "System Events"',
                'set kf to missing value',
                'repeat 12 times',
                'set matches to every application process whose name contains "KaraFun"',
                'if (count of matches) > 0 then',
                'set kf to item 1 of matches',
                'exit repeat',
                'end if',
                'delay 0.05',
                'end repeat',
                'if kf is not missing value then',
                'set frontmost of kf to true',
                'tell kf',
                '-- KaraFun lyrics use a separate Dual-Screen Display window.',
                '-- Reuse an existing renderer after explicitly leaving its old',
                '-- fullscreen Space. Recreating it costs 6-10 seconds after audio starts.',
                'set mainWindow to missing value',
                'set outputWindow to missing value',
                'repeat with candidateWindow in windows',
                'try',
                'if name of candidateWindow is "Dual Renderer" then',
                'set outputWindow to candidateWindow',
                'else if mainWindow is missing value then',
                'set mainWindow to candidateWindow',
                'end if',
                'end try',
                'end repeat',
                'if mainWindow is missing value then return "NOT_READY"',
                '-- Fast start commonly finds the renderer already open. Move and',
                '-- raise that window directly instead of toggling it closed and',
                '-- waiting 6-10 seconds for KaraFun to create it again.',
                'if outputWindow is not missing value then',
                'try',
                'if value of attribute "AXFullScreen" of outputWindow then',
                f'if (position of outputWindow) is {{{x}, {y}}} then',
                'perform action "AXRaise" of outputWindow',
                'return "READY"',
                'end if',
                'end if',
                'set value of attribute "AXFullScreen" of outputWindow to false',
                'end try',
                'repeat 30 times',
                'try',
                'if value of attribute "AXFullScreen" of outputWindow is false then exit repeat',
                'end try',
                'delay 0.1',
                'end repeat',
                'try',
                'set value of attribute "AXMinimized" of outputWindow to false',
                'end try',
                f'set position of outputWindow to {{{x}, {y}}}',
                f'set size of outputWindow to {{{width}, {height}}}',
                'perform action "AXRaise" of outputWindow',
                'delay 0.1',
                'perform action "AXRaise" of outputWindow',
                'return "READY"',
                'end if',
                'try',
                'set elems to entire contents of mainWindow',
                'set wp to position of mainWindow',
                'set ws to size of mainWindow',
                'set bestButton to missing value',
                'set bestButtonX to 0',
                'set bestButtonY to 0',
                'repeat with elem in elems',
                'try',
                'if role of elem is "AXButton" then',
                'set labelText to ""',
                'try',
                'set labelText to (name of elem as text) & " " & (description of elem as text) & " " & (help of elem as text)',
                'end try',
                'set ep to position of elem',
                'set es to size of elem',
                'set centerX to (item 1 of ep) + ((item 1 of es) div 2)',
                'set centerY to (item 2 of ep) + ((item 2 of es) div 2)',
                'ignoring case',
                'if labelText contains "dual" or labelText contains "screen" or labelText contains "display" or labelText contains "renderer" then',
                'set bestButton to elem',
                'set bestButtonX to centerX',
                'set bestButtonY to centerY',
                'exit repeat',
                'end if',
                'end ignoring',
                '-- Fallback for KaraFun builds whose Dual-Screen button has no useful AX label.',
                'if centerX > ((item 1 of wp) + ((item 1 of ws) * 0.66)) and centerY < ((item 2 of wp) + 115) then',
                'if bestButton is missing value or centerX > bestButtonX then',
                'set bestButton to elem',
                'set bestButtonX to centerX',
                'set bestButtonY to centerY',
                'end if',
                'end if',
                'end if',
                'end try',
                'end repeat',
                'if bestButton is missing value then return "NO_DUAL_BUTTON"',
                '-- No renderer exists, so click the toggle once to create it.',
                'try',
                'click at {bestButtonX, bestButtonY}',
                'end try',
                'end try',
                '-- Renderer creation can still take 6-10 seconds on the show Mac.',
                'repeat 100 times',
                'set outputWindow to missing value',
                'repeat with candidateWindow in windows',
                'try',
                'if name of candidateWindow is "Dual Renderer" then',
                'set outputWindow to candidateWindow',
                'exit repeat',
                'end if',
                'end try',
                'end repeat',
                'if outputWindow is not missing value then exit repeat',
                'delay 0.1',
                'end repeat',
                'if outputWindow is not missing value then',
                'try',
                'set value of attribute "AXFullScreen" of outputWindow to false',
                'end try',
                f'set position of outputWindow to {{{x}, {y}}}',
                f'set size of outputWindow to {{{width}, {height}}}',
                'perform action "AXRaise" of outputWindow',
                'delay 0.2',
                'perform action "AXRaise" of outputWindow',
                'return "READY"',
                'else',
                '-- Never fullscreen KaraFun window 1 here; that is the host/control window.',
                '-- If the Dual Renderer is unavailable, leave the host window usable.',
                'return "NO_DUAL_RENDERER"',
                'end if',
                'end tell',
                'else',
                'return "NOT_READY"',
                'end if',
                'end tell',
            ]
            center_x = x + (width // 2)
            center_y = y + (height // 2)
            def _finish_handoff(result=""):
                if not _handoff_is_current():
                    _diag("[KARAFUN] skipped stale show-screen handoff result")
                    return
                outcome = str(result or "").strip()
                if outcome == "READY":
                    def _after_fullscreen_check(check_result=""):
                        if not _handoff_is_current():
                            return
                        verified = str(check_result or "").strip() == "FULLSCREEN"
                        _finish_handoff_state(complete=verified)
                        if verified:
                            _diag("[KARAFUN] Dual Renderer fullscreen verified")
                        else:
                            _diag(f"[KARAFUN] Dual Renderer fullscreen verification failed state={check_result!r}")

                    ensure_renderer_fullscreen(self, _after_fullscreen_check, _handoff_is_current)
                    return
                if outcome == "NO_DUAL_RENDERER":
                    if attempt < 1:
                        _diag(f"[KARAFUN] Dual Renderer unavailable; retrying recreation attempt={attempt + 1}")
                        QTimer.singleShot(250, lambda: _fullscreen_karafun(attempt + 1))
                    else:
                        _finish_handoff_state(complete=False)
                        _diag(f"[KARAFUN] Dual Renderer unavailable; leaving KaraFun control window unchanged attempt={attempt + 1}")
                    return
                if attempt < 1:
                    QTimer.singleShot(350, lambda: _fullscreen_karafun(attempt + 1))
                else:
                    _finish_handoff_state(complete=False)
                    _diag("[KARAFUN] Dual Renderer unavailable after 2 attempts")
            if self._karafun_run_window_script(
                lines,
                on_complete=_finish_handoff,
            ):
                _diag(f"[KARAFUN] show-screen handoff attempt={attempt + 1} bounds={x},{y},{width},{height}")

        QTimer.singleShot(0, _fullscreen_karafun)

    def _activate_host_if_foreground(self):
        """Return focus after window placement only if SingWS is still active."""
        if QApplication.applicationState() == Qt.ApplicationState.ApplicationActive:
            self.activateWindow()

    def _can_restore_host_focus_after_karafun(self) -> bool:
        if QApplication.applicationState() == Qt.ApplicationState.ApplicationActive:
            return True
        if sys.platform == "darwin":
            try:
                from AppKit import NSWorkspace
                frontmost = NSWorkspace.sharedWorkspace().frontmostApplication()
                # Returning from KaraFun is expected. Pulling focus away from
                # a browser/editor is not, including during the delayed retry.
                return str(frontmost.localizedName() or "").casefold() == "karafun"
            except Exception:
                pass
        return False

    def _activate_host_window_after_karafun(self, attempt: int = 0):
        """Return keyboard focus to the main host window after KaraFun exits.

        The audience window is restored separately. On macOS, closing KaraFun's
        fullscreen Space can finish after Qt's first activation request, so make
        one short bounded retry once that animation has had time to settle.
        """
        if isinstance(getattr(self, "_active_external_karafun", None), dict):
            return
        if not self._can_restore_host_focus_after_karafun():
            return
        try:
            state = self.windowState()
            if state & Qt.WindowState.WindowMinimized:
                self.setWindowState(state & ~Qt.WindowState.WindowMinimized)
            self.show()
            try:
                from AppKit import NSApplication
                NSApplication.sharedApplication().activateIgnoringOtherApps_(True)
            except Exception:
                pass
            self.raise_()
            self.activateWindow()
            _diag(f"[KARAFUN] activated SingWS host window attempt={attempt + 1}")
        except Exception as e:
            _diag(f"[KARAFUN] host window activation failed attempt={attempt + 1}: {e}")
        if attempt < 1:
            QTimer.singleShot(350, lambda: self._activate_host_window_after_karafun(attempt + 1))

    def _restore_show_screen_from_karafun(self):
        """Restore the SingWS audience output after external KaraFun playback."""
        state = getattr(self, "_karafun_show_screen_restore", None)
        transparent_handoff = isinstance(state, dict) and state.get("mode") == "transparent"
        if transparent_handoff:
            self._karafun_show_screen_restore = None
            self._karafun_handoff_token = None
            self._karafun_handoff_in_progress = False
            self._karafun_handoff_complete = False
            restore_token = uuid.uuid4().hex
            self._karafun_restore_token = restore_token
            vw = getattr(self, "video_window", None)
            if vw is None:
                return

            restore_started = False

            def _restore_transparent_singws(reason=""):
                nonlocal restore_started
                if getattr(self, "_karafun_restore_token", None) != restore_token:
                    _diag("[KARAFUN] skipped stale transparent show-screen restore")
                    return
                if isinstance(getattr(self, "_active_external_karafun", None), dict):
                    _diag("[KARAFUN] skipped transparent show-screen restore during active KaraFun playback")
                    return
                if restore_started:
                    return
                restore_started = True
                try:
                    opacity = float(state.get("window_opacity", 1.0))
                    opacity = max(0.0, min(1.0, opacity))
                    native_window = state.get("native_window")
                    if native_window is not None:
                        native_window.setIgnoresMouseEvents_(False)
                        if "native_style_mask" in state:
                            native_window.setStyleMask_(int(state["native_style_mask"]))
                        if "native_collection_behavior" in state:
                            native_window.setCollectionBehavior_(int(state["native_collection_behavior"]))
                        if "native_level" in state:
                            native_window.setLevel_(int(state["native_level"]))
                    was_visible = bool(state.get("visible", True))
                    if not was_visible:
                        vw.hide()
                    else:
                        screen_rect = state.get("screen_geometry")
                        saved_geometry = state.get("geometry")
                        was_fullscreen = bool(state.get("fullscreen", False))
                        was_maximized = bool(state.get("maximized", False))
                        vw.hide()
                        vw.setWindowState(Qt.WindowState.WindowNoState)
                        if screen_rect is not None:
                            vw.setGeometry(screen_rect)
                        elif saved_geometry is not None:
                            vw.setGeometry(saved_geometry)
                        vw.setWindowOpacity(opacity)
                        if was_fullscreen or was_maximized:
                            vw.showFullScreen()
                        else:
                            vw.showNormal()
                        vw.raise_()
                        # Audience restoration must not activate the entire
                        # application; host focus is handled separately below.
                        if native_window is not None:
                            native_window.orderFrontRegardless()
                    _diag(
                        f"[KARAFUN] restored SingWS show screen opacity={opacity:.2f} "
                        f"fullscreen={int(vw.isFullScreen())} reason={reason}"
                    )
                    self._activate_host_window_after_karafun()
                except Exception as e:
                    _diag(f"[KARAFUN] transparent show-screen restore failed: {e}")
                    self._activate_host_window_after_karafun()

            def _after_transparent_karafun_hidden(result=""):
                if getattr(self, "_karafun_restore_token", None) != restore_token:
                    _diag("[KARAFUN] skipped stale transparent KaraFun hide completion")
                    return
                _diag(f"[KARAFUN] transparent KaraFun hide result={str(result or '').strip() or 'OK'}")
                # AXMinimized is verified by the script. A short delay lets the
                # final Space animation settle before recreating SingWS native
                # fullscreen on the same physical display.
                QTimer.singleShot(250, lambda: _restore_transparent_singws("karafun_hidden"))

            hide_script = [
                'tell application "System Events"',
                'set matches to every application process whose name contains "KaraFun"',
                'if (count of matches) is 0 then return "NO_APP"',
                'tell item 1 of matches',
                'set outputWindow to missing value',
                'repeat with w in windows',
                'try',
                'if name of w is "Dual Renderer" then set outputWindow to w',
                'end try',
                'end repeat',
                'if outputWindow is missing value then return "NO_DUAL_RENDERER"',
                'try',
                'set value of attribute "AXFullScreen" of outputWindow to false',
                'end try',
                'repeat 20 times',
                'try',
                'if not (value of attribute "AXFullScreen" of outputWindow) then exit repeat',
                'end try',
                'delay 0.1',
                'end repeat',
                'try',
                'set value of attribute "AXMinimized" of outputWindow to true',
                'end try',
                'repeat 20 times',
                'try',
                'if value of attribute "AXMinimized" of outputWindow then return "MINIMIZED"',
                'end try',
                'delay 0.1',
                'end repeat',
                'return "MINIMIZE_FAILED"',
                'end tell',
                'end tell',
            ]
            started = self._karafun_run_window_script(
                hide_script,
                on_complete=_after_transparent_karafun_hidden,
                timeout=6,
            )
            if not started:
                QTimer.singleShot(350, lambda: _restore_transparent_singws("script_start_failed"))
            QTimer.singleShot(6500, lambda: _restore_transparent_singws("fallback_timeout"))
            return
        if not isinstance(state, dict):
            vw = getattr(self, "video_window", None)
            if vw is None:
                return
            try:
                frame = vw.frameGeometry()
                screen = QApplication.screenAt(frame.center()) or vw.screen() or QApplication.primaryScreen()
                state = {
                    "geometry": vw.geometry(),
                    "fullscreen": bool(vw.isFullScreen()),
                    "maximized": bool(vw.isMaximized()),
                    "visible": bool(vw.isVisible()),
                    "screen_geometry": screen.geometry() if screen is not None else frame,
                }
                _diag("[KARAFUN] restore snapshot missing; using current show-screen display")
            except Exception:
                state = {"screen_geometry": None}
        self._karafun_show_screen_restore = None
        # Invalidate every pending open/fullscreen callback before beginning the
        # reverse transition. A late handoff result must never reopen or toggle
        # KaraFun after playback has ended.
        self._karafun_handoff_token = None
        self._karafun_handoff_in_progress = False
        self._karafun_handoff_complete = False
        restore_token = uuid.uuid4().hex
        self._karafun_restore_token = restore_token

        restore_started = False

        def _restore_singws(reason=""):
            nonlocal restore_started
            if getattr(self, "_karafun_restore_token", None) != restore_token:
                _diag("[KARAFUN] skipped stale SingWS show-screen restore")
                return
            if isinstance(getattr(self, "_active_external_karafun", None), dict):
                _diag("[KARAFUN] skipped SingWS show-screen restore during active KaraFun playback")
                return
            if restore_started:
                _diag(f"[KARAFUN] skipped duplicate SingWS show-screen restore reason={reason}")
                return
            restore_started = True
            vw = getattr(self, "video_window", None)
            if vw is None:
                return
            try:
                screen_rect = state.get("screen_geometry")
                saved_geometry = state.get("geometry")
                was_fullscreen = bool(state.get("fullscreen", False))
                was_maximized = bool(state.get("maximized", False))
                was_visible = bool(state.get("visible", True))
                restore_fullscreen = was_fullscreen or was_maximized

                vw.setWindowState(Qt.WindowState.WindowNoState)
                if restore_fullscreen and screen_rect is not None:
                    vw.setGeometry(screen_rect)
                elif saved_geometry is not None:
                    vw.setGeometry(saved_geometry)

                if not was_visible:
                    vw.hide()
                    _diag("[KARAFUN] restored SingWS show screen hidden")
                    self._activate_host_window_after_karafun()
                    return
                if not restore_fullscreen:
                    vw.showNormal()
                    vw.raise_()
                    # Raising the show window can bury the ticker underneath the
                    # mpv host surfaces; closing and reopening the show screen
                    # used to be the only repair.
                    self._schedule_show_ticker_reassert("karafun_restore")
                    _diag("[KARAFUN] restored SingWS show screen fullscreen=0")
                    self._activate_host_window_after_karafun()
                    return

                def _enter_singws_fullscreen(attempt=0):
                    if getattr(self, "_karafun_restore_token", None) != restore_token:
                        _diag("[KARAFUN] skipped stale SingWS fullscreen request")
                        return
                    if isinstance(getattr(self, "_active_external_karafun", None), dict):
                        _diag("[KARAFUN] skipped SingWS fullscreen request during active KaraFun playback")
                        return
                    try:
                        if vw.isFullScreen():
                            self._schedule_show_ticker_reassert("karafun_restore_fullscreen")
                            _diag("[KARAFUN] restored SingWS show screen fullscreen=1")
                            return
                        if screen_rect is not None:
                            vw.setGeometry(screen_rect)
                        vw.showFullScreen()
                        vw.raise_()
                        if not vw.isFullScreen() and attempt < 1:
                            QTimer.singleShot(700, lambda: _enter_singws_fullscreen(attempt + 1))
                        else:
                            # The fullscreen Space transition settles later than
                            # a plain reveal, so this ladder runs longer.
                            self._schedule_show_ticker_reassert(
                                "karafun_restore_fullscreen", delays=(0, 120, 400, 900)
                            )
                            _diag(f"[KARAFUN] restored SingWS show screen fullscreen={int(vw.isFullScreen())}")
                    except Exception as e:
                        _diag(f"[KARAFUN] fullscreen retry failed: {e}")

                _enter_singws_fullscreen()
                self._activate_host_window_after_karafun()
            except Exception as e:
                _diag(f"[KARAFUN] show-screen restore failed: {e}")
                self._activate_host_window_after_karafun()

        def _after_karafun_hidden(_result=""):
            if getattr(self, "_karafun_restore_token", None) != restore_token:
                _diag("[KARAFUN] skipped stale KaraFun Dual Renderer minimize completion")
                return
            if isinstance(getattr(self, "_active_external_karafun", None), dict):
                _diag("[KARAFUN] skipped KaraFun Dual Renderer minimize completion during active playback")
                return
            # Let the native fullscreen Space finish closing before SingWS
            # claims the same physical display.
            QTimer.singleShot(250, lambda: _restore_singws("karafun_hidden"))

        restore_script = [
            'tell application "System Events"',
            'set matches to every application process whose name contains "KaraFun"',
            'if (count of matches) > 0 then',
            'tell item 1 of matches',
            'set outputWindow to missing value',
            'repeat with w in windows',
            'try',
            'if name of w is "Dual Renderer" then set outputWindow to w',
            'end try',
            'end repeat',
            'if outputWindow is not missing value then',
            'try',
            'set value of attribute "AXFullScreen" of outputWindow to false',
            'end try',
            'delay 0.6',
            'try',
            'set value of attribute "AXMinimized" of outputWindow to true',
            'end try',
            'end if',
            'end tell',
            'end if',
            'end tell',
        ]
        started = self._karafun_run_window_script(
            restore_script,
            on_complete=_after_karafun_hidden,
            timeout=3,
        )
        if not started:
            QTimer.singleShot(250, lambda: _restore_singws("script_start_failed"))
        # Bounded fallback: restoration still happens if Accessibility is
        # denied or KaraFun stops responding. The local guard makes this a
        # no-op if the normal completion path has already restored the window.
        QTimer.singleShot(3500, lambda: _restore_singws("fallback_timeout"))

    def _copy_karafun_lookup_text(self, entry: dict) -> bool:
        text = self._karafun_lookup_text(entry)
        if not text:
            return False
        try:
            QApplication.clipboard().setText(text)
            _diag("[KARAFUN] copied lookup text")
            return True
        except Exception as e:
            _diag(f"[KARAFUN] copy failed: {e}")
            return False

    def _find_queue_entry_by_song_path(self, song_path: str):
        target = str(song_path or "").strip()
        if not target:
            return None
        try:
            for singer in reversed(self.queue or []):
                for entry in reversed(singer.get("songs") or []):
                    if isinstance(entry, dict) and str(self._song_info_primary_path(entry.get("song_info")) or "").strip() == target:
                        return entry
        except Exception:
            return None
        return None

    @staticmethod
    def _karafun_clean_search_part(value: str) -> str:
        text = str(value or "")
        text = re.sub(r"\([^)]*(karaoke|version|explicit|clean|remaster|live|feat\\.?|ft\\.?)[^)]*\)", " ", text, flags=re.I)
        text = re.sub(r"\[[^]]*(karaoke|version|explicit|clean|remaster|live|feat\\.?|ft\\.?)[^]]*\]", " ", text, flags=re.I)
        text = re.sub(r"\b(feat\\.?|ft\\.?|featuring)\b.*$", " ", text, flags=re.I)
        text = re.sub(r"\b(karaoke|instrumental|official|version|lyrics?|lyric video|hd|remaster(?:ed)?|clean|explicit)\b", " ", text, flags=re.I)
        text = text.replace("&", " and ")
        text = re.sub(r"[’'`]", "", text)
        text = re.sub(r"[^0-9A-Za-zÀ-ÖØ-öø-ÿ]+", " ", text)
        return re.sub(r"\s+", " ", text).strip()

    def _karafun_search_query_for_entry(self, entry: dict) -> str:
        artist, title = self._karafun_entry_artist_title(entry)
        artist = self._karafun_clean_search_part(artist)
        title = self._karafun_clean_search_part(title)
        return " ".join(p for p in (artist, title) if p).strip()

    def _karafun_search_queries_for_entry(self, entry: dict) -> list[str]:
        artist, title = self._karafun_entry_artist_title(entry)
        artist = self._karafun_clean_search_part(artist)
        title = self._karafun_clean_search_part(title)
        candidates = [
            " ".join(p for p in (artist, title) if p).strip(),
            " ".join(p for p in (title, artist) if p).strip(),
            title,
            artist,
        ]
        out = []
        seen = set()
        for query in candidates:
            key = str(query or "").strip().lower()
            if key and key not in seen:
                out.append(str(query).strip())
                seen.add(key)
        return out

    def _set_karafun_entry_status(self, entry: dict, status: str, *, message: str = "", notify: bool = False, level: str = "info"):
        if not isinstance(entry, dict):
            return
        status = str(status or "").strip()
        entry["karafun_status"] = status
        entry["karafun_status_at"] = int(time.time())
        if message:
            entry["karafun_status_message"] = str(message)[:240]
        try:
            _diag(f"[KARAFUN] status={status} title={entry.get('title', '')!r} message={str(message or '')[:180]!r}")
        except Exception:
            pass
        try:
            self._schedule_save_data(0)
        except Exception:
            pass
        try:
            self._run_on_ui_thread(self.update_queue_display)
        except Exception:
            pass
        if notify and message:
            try:
                self._show_processing_notification(message, level=level)
            except Exception:
                pass

    def _karafun_press_play_control(self) -> tuple[bool, str]:
        """Click KaraFun's main transport Play control. Returns (ok, error)."""
        play_script = [
            'tell application "System Events"',
            'tell application process "KaraFun"',
            'set frontmost to true',
            'set mainWindow to missing value',
            'repeat with candidateWindow in windows',
            'try',
            'if name of candidateWindow is not "Dual Renderer" then set mainWindow to candidateWindow',
            'end try',
            'end repeat',
            'if mainWindow is missing value then return "ERROR|KaraFun control window not found"',
            'set wp to position of mainWindow',
            'set ws to size of mainWindow',
            '-- Main player Play/Pause button: left transport control in the right-side player panel.',
            '-- Avoid AXPress/button scans here; KaraFun can hang while enumerating player controls.',
            'set playX to (item 1 of wp) + ((item 1 of ws) * 0.768)',
            'set playY to (item 2 of wp) + ((item 2 of ws) * 0.222)',
            'return "PLAY|" & playX & "|" & playY',
            'end tell',
            'end tell',
        ]
        ok, played, script_error = self._run_karafun_applescript_sync(play_script, timeout=10)
        if not ok:
            return False, str(script_error or "KaraFun play automation failed")
        play_parts = str(played or "").split("|")
        if len(play_parts) != 3 or play_parts[0] not in {"PLAY_NEXT", "PLAY"}:
            return False, str(played or "").split("|", 1)[-1] or "KaraFun did not expose a play control"
        _diag(f"[KARAFUN-AUTO] pressing KaraFun control mode={play_parts[0]} x={play_parts[1]} y={play_parts[2]}")
        if not self._macos_native_mouse_click(int(float(play_parts[1])), int(float(play_parts[2])), clicks=1):
            return False, "Could not click the KaraFun play control"
        return True, ""

    def _karafun_activate_result_for_playback(self, activation_point) -> tuple[bool, str]:
        """Raise the search-results window and double-click its matched row."""
        try:
            if not isinstance(activation_point, (tuple, list)) or len(activation_point) != 2:
                return False, "KaraFun result position is unavailable"
            x, y = int(activation_point[0]), int(activation_point[1])
        except Exception:
            return False, "KaraFun result position is invalid"
        ok, result, script_error = self._run_karafun_applescript_sync(
            [
                'tell application "System Events"',
                'set matches to every application process whose name contains "KaraFun"',
                'if (count of matches) is 0 then return "ERROR|KaraFun is not running"',
                'tell item 1 of matches',
                'set frontmost to true',
                'set mainWindow to missing value',
                'repeat with candidateWindow in windows',
                'try',
                'if name of candidateWindow starts with "Results for " then',
                'set mainWindow to candidateWindow',
                'exit repeat',
                'end if',
                'end try',
                'end repeat',
                'if mainWindow is missing value then return "ERROR|KaraFun results window not found"',
                'perform action "AXRaise" of mainWindow',
                'return "READY"',
                'end tell',
                'end tell',
            ],
            timeout=8,
        )
        if not ok or str(result or "").strip() != "READY":
            return False, str(script_error or result or "KaraFun results window is unavailable")
        if not self._macos_native_double_click(x, y):
            return False, "Could not double-click the KaraFun result"
        return True, ""

    def _karafun_search_script(self, *, query: str, safe_title: str = "", safe_artist: str = "",
                               require_exact_title: bool = False):
        query_literal = self._karafun_applescript_literal(query)
        safe_title_literal = self._karafun_applescript_literal(safe_title)
        safe_artist_literal = self._karafun_applescript_literal(safe_artist)
        lines = [
            'tell application "System Events"',
            'set matches to every application process whose name contains "KaraFun"',
            'if (count of matches) is 0 then return "ERROR|KaraFun is not running"',
            'tell item 1 of matches',
            'set frontmost to true',
            'set mainWindow to missing value',
            'set searchField to missing value',
            'repeat 80 times',
            'repeat with candidateWindow in windows',
            'try',
            'if name of candidateWindow is not "Dual Renderer" then',
            'try',
            'set candidateElems to entire contents of candidateWindow',
            'on error',
            'set candidateElems to UI elements of candidateWindow',
            'end try',
            'set wp to position of candidateWindow',
            'set ws to size of candidateWindow',
            'set fallbackField to missing value',
            'set fallbackX to 999999',
            'repeat with elem in candidateElems',
            'try',
            'if role of elem is "AXTextField" then',
            'set labelText to ""',
            'try',
            'set labelText to (name of elem as text) & " " & (description of elem as text) & " " & (help of elem as text) & " " & (value of elem as text)',
            'end try',
            'set ep to position of elem',
            'set es to size of elem',
            'set centerX to (item 1 of ep) + ((item 1 of es) div 2)',
            'set centerY to (item 2 of ep) + ((item 2 of es) div 2)',
            'ignoring case',
            'if labelText contains "catalog" or labelText contains "search" then',
            'set mainWindow to candidateWindow',
            'set searchField to elem',
            'exit repeat',
            'end if',
            'end ignoring',
            'if centerX < ((item 1 of wp) + ((item 1 of ws) * 0.35)) and centerY < ((item 2 of wp) + 170) then',
            'if centerX < fallbackX then',
            'set fallbackField to elem',
            'set fallbackX to centerX',
            'end if',
            'end if',
            'end if',
            'end try',
            'end repeat',
            'if searchField is missing value and fallbackField is not missing value then',
            'set mainWindow to candidateWindow',
            'set searchField to fallbackField',
            'end if',
            'end if',
            'end try',
            'if searchField is not missing value then exit repeat',
            'end repeat',
            'if searchField is not missing value then exit repeat',
            'delay 0.15',
            'end repeat',
            'if searchField is missing value then return "ERROR|KaraFun search field not found"',
            'perform action "AXRaise" of mainWindow',
            'set frontmost to true',
            'set focused of searchField to true',
            'click searchField',
            'delay 0.1',
            'key code 0 using command down',
            'delay 0.05',
            f'keystroke {query_literal}',
            'key code 36',
            'delay 3',
        ]
        if require_exact_title and safe_title:
            lines.extend([
                'try',
                'set elems to entire contents of mainWindow',
                'on error',
                'set elems to UI elements of mainWindow',
                'end try',
                'set wp to position of mainWindow',
                'set ws to size of mainWindow',
                'set cutoff to (item 1 of wp) + ((item 1 of ws) * 0.7)',
                'set fallbackX to 0',
                'set fallbackY to 0',
            ])
            if safe_artist:
                # Titles are not unique. "Memory" is Sugarcult's song and also
                # Cats', and a title-only match once put the wrong one on the
                # audience screen. When the artist is known, prefer the result
                # row that carries it: same row (aligned Y), inside the results
                # area. Falls through to the title-only pass below, which the
                # caller may then refuse for an artist-less query.
                lines.extend([
                    'repeat with elem in elems',
                    'try',
                    f'if (role of elem is "AXStaticText") and ((name of elem as text) contains {safe_title_literal}) then',
                    'set ep to position of elem',
                    'if (item 1 of ep) < cutoff then',
                    'set es to size of elem',
                    'set rowX to ((item 1 of ep) + ((item 1 of es) div 2))',
                    'set rowY to ((item 2 of ep) + ((item 2 of es) div 2))',
                    'set artistMatched to false',
                    'repeat with artistElem in elems',
                    'try',
                    'if role of artistElem is "AXStaticText" then',
                    'set aName to name of artistElem as text',
                    'set ap to position of artistElem',
                    # AppleScript identifiers are case-insensitive, so `aS`
                    # is parsed as the reserved coercion keyword `as`.
                    'set artistSize to size of artistElem',
                    'set aX to (item 1 of ap) + ((item 1 of artistSize) div 2)',
                    'set aY to (item 2 of ap) + ((item 2 of artistSize) div 2)',
                    'set aDelta to aY - rowY',
                    'if aDelta < 0 then set aDelta to -aDelta',
                    'ignoring case',
                    f'if aDelta < 30 and aX < cutoff and (aName contains {safe_artist_literal}) then',
                    'set artistMatched to true',
                    'end if',
                    'end ignoring',
                    'if artistMatched then exit repeat',
                    'end if',
                    'end try',
                    'end repeat',
                    'if artistMatched then',
                    'set durationText to ""',
                    'repeat with durationElem in elems',
                    'try',
                    'if role of durationElem is "AXStaticText" then',
                    'set dName to name of durationElem as text',
                    'set dp to position of durationElem',
                    'set ds to size of durationElem',
                    'set dX to (item 1 of dp) + ((item 1 of ds) div 2)',
                    'set dY to (item 2 of dp) + ((item 2 of ds) div 2)',
                    'set rowDelta to dY - rowY',
                    'if rowDelta < 0 then set rowDelta to -rowDelta',
                    'if dName contains ":" and (length of dName) < 9 and dX > rowX and rowDelta < 30 then',
                    'set durationText to dName',
                    'exit repeat',
                    'end if',
                    'end if',
                    'end try',
                    'end repeat',
                    'return "FOUND|" & rowX & "|" & rowY & "|" & durationText',
                    'end if',
                    'end if',
                    'end if',
                    'end try',
                    'end repeat',
                ])
            lines.extend([
                'repeat with elem in elems',
                'try',
                # KaraFun appends a small attachment/icon character to some
                # result titles, so equality rejects the correct visible row.
                f'if (role of elem is "AXStaticText") and ((name of elem as text) contains {safe_title_literal}) then',
                'set ep to position of elem',
                'if (item 1 of ep) < cutoff then',
                'set es to size of elem',
                'set rowX to ((item 1 of ep) + ((item 1 of es) div 2))',
                'set rowY to ((item 2 of ep) + ((item 2 of es) div 2))',
                'set durationText to ""',
                'repeat with durationElem in elems',
                'try',
                'if role of durationElem is "AXStaticText" then',
                'set dName to name of durationElem as text',
                'set dp to position of durationElem',
                'set ds to size of durationElem',
                'set dX to (item 1 of dp) + ((item 1 of ds) div 2)',
                'set dY to (item 2 of dp) + ((item 2 of ds) div 2)',
                'set rowDelta to dY - rowY',
                'if rowDelta < 0 then set rowDelta to -rowDelta',
                'if dName contains ":" and (length of dName) < 9 and dX > rowX and rowDelta < 30 then',
                'set durationText to dName',
                'exit repeat',
                'end if',
                'end if',
                'end try',
                'end repeat',
                # Weaker verdict when the artist was known but not confirmed
                # on the row: the caller decides whether to accept it.
                f'return "{"TITLE_ONLY" if safe_artist else "FOUND"}|" & rowX & "|" & rowY & "|" & durationText',
                'end if',
                'end if',
                'end try',
                'end repeat',
                '-- Fallback: use the first visible result in the left results area for the already-specific artist+title query.',
                'repeat with elem in elems',
                'try',
                'if role of elem is "AXStaticText" then',
                'set n to name of elem as text',
                'set ep to position of elem',
                'set es to size of elem',
                'set centerX to (item 1 of ep) + ((item 1 of es) div 2)',
                'set centerY to (item 2 of ep) + ((item 2 of es) div 2)',
                'if (n is not "") and (centerX < cutoff) and (centerY > ((item 2 of wp) + 110)) then',
                'set durationText to ""',
                'repeat with durationElem in elems',
                'try',
                'if role of durationElem is "AXStaticText" then',
                'set dName to name of durationElem as text',
                'set dp to position of durationElem',
                'set ds to size of durationElem',
                'set dX to (item 1 of dp) + ((item 1 of ds) div 2)',
                'set dY to (item 2 of dp) + ((item 2 of ds) div 2)',
                'set rowDelta to dY - centerY',
                'if rowDelta < 0 then set rowDelta to -rowDelta',
                'if dName contains ":" and (length of dName) < 9 and dX > centerX and rowDelta < 30 then',
                'set durationText to dName',
                'exit repeat',
                'end if',
                'end if',
                'end try',
                'end repeat',
                '-- A real result row exposes an aligned duration. Requiring it',
                '-- prevents labels such as Discover, Display, and My Playlists',
                '-- from becoming the fallback double-click target.',
                'if durationText is not "" then return "FIRST|" & centerX & "|" & centerY & "|" & durationText',
                'end if',
                'end if',
                'end try',
                'end repeat',
                'return "ERROR|No usable KaraFun search result"',
            ])
        else:
            lines.append('return "SEARCHED"')
        lines.extend([
            'end tell',
            'end tell',
        ])
        return lines

    def _automate_karafun_search_only(self, entry: dict) -> bool:
        """Search KaraFun from Add KaraFun without starting playback."""
        if sys.platform != "darwin" or not bool(self.settings.get("karafun_auto_queue_enabled", False)):
            self._set_karafun_entry_status(entry, "manual", message="KaraFun automation is disabled; select this track manually.", notify=True, level="warning")
            return False
        if not isinstance(entry, dict):
            return False
        query = self._karafun_search_query_for_entry(entry)
        if not query:
            self._set_karafun_entry_status(entry, "manual", message="Could not build a KaraFun search query. Please select it manually.", notify=True, level="warning")
            return False
        self._set_karafun_entry_status(entry, "searching", message=f"Searching KaraFun: {query}")
        _diag(f"[KARAFUN-SEARCH] query={query!r}")

        def _worker():
            result = {"ok": False, "message": "KaraFun search did not complete."}
            try:
                if not self._open_karafun_for_entry(entry):
                    raise RuntimeError(
                        str(getattr(self, "_last_karafun_launch_error", "") or "KaraFun could not be opened")
                    )
                permission_ok, permission_error = self._karafun_apple_events_preflight()
                if not permission_ok:
                    raise RuntimeError(permission_error)
                ok, out, err = self._run_karafun_applescript_sync(
                    self._karafun_search_script(query=query, require_exact_title=False),
                    timeout=18,
                )
                if not ok:
                    raise RuntimeError(err or out or "KaraFun search failed")
                result = {"ok": True, "message": out or "SEARCHED"}
            except Exception as e:
                result = {"ok": False, "message": str(e)}

            def _finish():
                if result["ok"]:
                    self._set_karafun_entry_status(entry, "ready", message="KaraFun search complete. Confirm the result before Play if needed.", notify=False)
                    try:
                        self._show_processing_notification("KaraFun search complete.", level="success")
                    except Exception:
                        pass
                else:
                    if self._is_karafun_apple_events_error(result["message"]):
                        setup_message = self._show_karafun_apple_events_setup(notify=True)
                        self._set_karafun_entry_status(
                            entry,
                            "permission",
                            message=setup_message,
                            notify=False,
                        )
                    elif self._is_karafun_accessibility_error(result["message"]):
                        setup_message = self._show_karafun_accessibility_setup(notify=True)
                        self._set_karafun_entry_status(
                            entry,
                            "permission",
                            message=setup_message,
                            notify=False,
                        )
                    else:
                        self._set_karafun_entry_status(
                            entry,
                            "manual",
                            message="Could not automatically find this track in KaraFun. Please select it manually.",
                            notify=True,
                            level="warning",
                        )
                    entry["karafun_submission_error"] = result["message"][:240]
                    _diag(f"[KARAFUN-SEARCH] failed error={result['message'][:240]!r}")

            self._run_on_ui_thread(_finish)

        threading.Thread(target=_worker, daemon=True, name="karafun-search-only").start()
        return True

    def _automate_karafun_search_and_play(self, entry: dict, *, key=0, tempo_percent=None):
        """Search, queue, start, and adjust an exact track in the official KaraFun app."""
        if sys.platform != "darwin" or not bool(self.settings.get("karafun_auto_queue_enabled", False)):
            return False
        if not isinstance(entry, dict):
            return False
        active_session = getattr(self, "_active_external_karafun", None)
        if not isinstance(active_session, dict) or active_session.get("entry") is not entry:
            return False

        def _session_is_current():
            return getattr(self, "_active_external_karafun", None) is active_session

        def _require_current_session():
            if not _session_is_current():
                raise RuntimeError("KaraFun launch cancelled: playback session ended")

        def _run_session_script(lines, **kwargs):
            _require_current_session()
            result = self._run_karafun_applescript_sync(lines, **kwargs)
            _require_current_session()
            return result

        state = str(entry.get("karafun_submission_state") or "").strip().lower()
        pending_at = float(entry.get("karafun_pending_at") or 0)
        if state in {"karafun_queued", "karafun_completed"} or (
            state == "karafun_pending" and (time.time() - pending_at) < 30
        ):
            _diag(f"[KARAFUN-AUTO] duplicate prevented state={state}")
            return False
        artist, title = self._karafun_entry_artist_title(entry)
        if not title:
            entry["karafun_submission_state"] = "karafun_manual_action_required"
            return False
        try:
            requested_key = max(-12, min(12, int(key or 0)))
        except Exception:
            requested_key = 0
        try:
            requested_tempo = max(50, min(200, int(tempo_percent if tempo_percent is not None else 100)))
        except Exception:
            requested_tempo = 100
        adjustment_signature = f"key={requested_key};tempo={requested_tempo}"
        entry["karafun_submission_state"] = "karafun_pending"
        entry["karafun_pending_at"] = time.time()
        self._set_karafun_entry_status(entry, "launching", message="Launching KaraFun playback")
        request_uid = self._ensure_queue_entry_id(entry)

        safe_title = str(title or "").strip()
        search_queries = self._karafun_search_queries_for_entry(entry)
        if not search_queries:
            search_queries = [" ".join(p for p in (artist, title) if p).strip()]
        _diag(f"[KARAFUN-AUTO] playback search queries={search_queries!r} title={title!r}")

        transparent_renderer_bounds = None
        if bool(self.settings.get("karafun_transparent_handoff", True)):
            try:
                vw = getattr(self, "video_window", None)
                if vw is not None:
                    frame = vw.frameGeometry()
                    screen = QApplication.screenAt(frame.center()) or vw.screen() or QApplication.primaryScreen()
                    rect = screen.availableGeometry() if screen is not None else frame
                    transparent_renderer_bounds = (
                        int(rect.x()), int(rect.y()), int(rect.width()), int(rect.height())
                    )
            except Exception as e:
                _diag(f"[KARAFUN] transparent renderer target unavailable: {e}")

        def _worker():
            result = {"ok": False, "message": "KaraFun automation did not complete."}
            handoff_scheduled = False
            bgm_fade_scheduled = False

            def _schedule_bgm_fade(reason: str):
                nonlocal bgm_fade_scheduled
                if bgm_fade_scheduled:
                    return
                bgm_fade_scheduled = True
                _diag(f"[KARAFUN] delayed BGM fade scheduled reason={reason}")
                self._run_on_ui_thread(lambda: self._fade_bg_for_external_karafun() if _session_is_current() else None)

            def _schedule_early_handoff(reason: str):
                nonlocal handoff_scheduled
                if handoff_scheduled:
                    return
                handoff_scheduled = True
                _diag(f"[KARAFUN] early show-screen handoff scheduled reason={reason}")
                self._run_on_ui_thread(lambda: self._handoff_show_screen_to_karafun() if _session_is_current() else None)

            try:
                _require_current_session()
                if not self._open_karafun_for_entry(entry):
                    raise RuntimeError(
                        str(getattr(self, "_last_karafun_launch_error", "") or "KaraFun could not be opened")
                    )
                _require_current_session()
                permission_ok, permission_error = self._karafun_apple_events_preflight()
                if not permission_ok:
                    raise RuntimeError(permission_error)
                audio_ok, audio_result = self._ensure_karafun_audio_output()
                if not audio_ok:
                    raise RuntimeError(f"KaraFun audio safety check failed: {audio_result}")
                self._karafun_transparent_renderer_ready = False
                if (
                    transparent_renderer_bounds is not None
                    and not bool(self.settings.get("karafun_fast_start_enabled", True))
                ):
                    rx, ry, rw, rh = transparent_renderer_bounds
                    prepare_renderer_script = [
                        'tell application "System Events"',
                        'set matches to every application process whose name contains "KaraFun"',
                        'if (count of matches) is 0 then return "NOT_READY|no_app"',
                        'set kf to item 1 of matches',
                        '-- The renderer toggle is clicked by screen coordinates after',
                        '-- this script returns. Make KaraFun frontmost first so that',
                        '-- click cannot land on the SingWS control window instead.',
                        'set frontmost of kf to true',
                        'tell kf',
                        'set mainWindow to missing value',
                        'set outputWindow to missing value',
                        'repeat with candidateWindow in windows',
                        'try',
                        'if name of candidateWindow is "Dual Renderer" then',
                        'set outputWindow to candidateWindow',
                        'else if mainWindow is missing value then',
                        'set mainWindow to candidateWindow',
                        'end if',
                        'end try',
                        'end repeat',
                        'if outputWindow is not missing value then',
                        'try',
                        '-- Preserve true fullscreen across songs. Reposition only',
                        '-- a normal renderer; fullscreen owns its display Space.',
                        'if value of attribute "AXFullScreen" of outputWindow then return "READY"',
                        'end try',
                        'try',
                        'set value of attribute "AXMinimized" of outputWindow to false',
                        'end try',
                        f'set position of outputWindow to {{{rx}, {ry}}}',
                        f'set size of outputWindow to {{{rw}, {rh}}}',
                        'return "READY"',
                        'end if',
                        'if mainWindow is missing value then return "NOT_READY|no_main_window"',
                        'set elems to entire contents of mainWindow',
                        'repeat with elem in elems',
                        'try',
                        'if role of elem is "AXButton" then',
                        'set descriptionText to ""',
                        'set helpText to ""',
                        'try',
                        'set descriptionText to description of elem as text',
                        'end try',
                        'try',
                        'set helpText to help of elem as text',
                        'end try',
                        'ignoring case',
                        'if descriptionText contains "Dual Renderer" or helpText contains "Dual-Screen Display" then',
                        'set ep to position of elem',
                        'set es to size of elem',
                        'set centerX to (item 1 of ep) + ((item 1 of es) div 2)',
                        'set centerY to (item 2 of ep) + ((item 2 of es) div 2)',
                        'return "OPEN|" & centerX & "|" & centerY',
                        'end if',
                        'end ignoring',
                        'end if',
                        'end try',
                        'end repeat',
                        'return "NOT_READY|no_renderer_button"',
                        'end tell',
                        'end tell',
                    ]
                    renderer_result = ""
                    # The open button is a TOGGLE. Clicking it on every failed
                    # attempt is what made this take three rounds and ~10s of
                    # dead air: the first click opened the renderer, 0.8s was
                    # not long enough for the window to appear, so the next
                    # attempt clicked again and closed it. Click once, then
                    # poll for the window with a wait that actually covers how
                    # long KaraFun takes to show it.
                    renderer_open_clicked = False
                    for renderer_attempt in range(4):
                        ok, renderer_result, renderer_error = _run_session_script(
                            prepare_renderer_script, timeout=8
                        )
                        renderer_result = str(renderer_result or renderer_error or "").strip()
                        if ok and renderer_result == "READY":
                            self._karafun_transparent_renderer_ready = True
                            _diag(
                                f"[KARAFUN] transparent renderer ready bounds={rx},{ry},{rw},{rh} "
                                f"attempt={renderer_attempt + 1}"
                                f"{' (after open click)' if renderer_open_clicked else ''}"
                            )
                            break
                        renderer_parts = renderer_result.split("|")
                        if ok and len(renderer_parts) == 3 and renderer_parts[0] == "OPEN":
                            if not renderer_open_clicked:
                                _diag(f"[KARAFUN] opening missing Dual Renderer attempt={renderer_attempt + 1}")
                                self._macos_native_mouse_click(
                                    int(float(renderer_parts[1])), int(float(renderer_parts[2])), clicks=1
                                )
                                renderer_open_clicked = True
                                time.sleep(1.5)
                            else:
                                # Already asked for it; just give it more time.
                                time.sleep(1.0)
                            continue
                        break
                    if not self._karafun_transparent_renderer_ready:
                        _diag(
                            f"[KARAFUN] transparent renderer preflight unavailable result={renderer_result!r}; "
                            "using legacy show-screen handoff"
                        )
                elif transparent_renderer_bounds is not None:
                    _diag("[KARAFUN-AUTO] fast start skipped unreliable transparent renderer preflight")

                found = ""
                selected_query = ""
                last_error = ""
                # The query list runs from most specific to least, ending in
                # title-only. Two things must hold or the wrong song plays:
                # a transient "KaraFun's window is not ready" error must not
                # consume a rung of that ladder, and a query that carries no
                # artist may only accept an artist-verified row.
                safe_artist_match = str(artist or "").strip()
                for attempt, query in enumerate(search_queries, start=1):
                    if not query:
                        continue
                    query_key = query.casefold()
                    query_has_artist = bool(safe_artist_match) and safe_artist_match.casefold() in query_key
                    if safe_artist_match and not query_has_artist:
                        accepted = {"FOUND"}
                    else:
                        accepted = {"FOUND", "TITLE_ONLY", "FIRST"}
                    ok = False
                    candidate = ""
                    for ui_retry in range(3):
                        _diag(
                            f"[KARAFUN-AUTO] search attempt={attempt} query={query!r}"
                            + (f" ui_retry={ui_retry + 1}" if ui_retry else "")
                        )
                        search_script = self._karafun_search_script(
                            query=query,
                            safe_title=safe_title,
                            safe_artist=safe_artist_match,
                            require_exact_title=True,
                        )
                        ok, candidate, script_error = _run_session_script(search_script, timeout=18)
                        if ok:
                            break
                        last_error = script_error or candidate or "KaraFun search automation failed"
                        _diag(f"[KARAFUN-AUTO] search attempt={attempt} failed error={str(last_error)[:180]!r}")
                        if (
                            self._is_karafun_apple_events_error(last_error)
                            or self._is_karafun_accessibility_error(last_error)
                        ):
                            raise RuntimeError(last_error)
                        if self._is_karafun_ui_not_ready_error(last_error) and ui_retry < 2:
                            # KaraFun is still building its window. Retry THIS
                            # query: falling through to the next one drops the
                            # artist, and a title-only search can land on a
                            # different song entirely.
                            _diag(f"[KARAFUN-AUTO] search attempt={attempt} KaraFun UI not ready; retrying same query")
                            time.sleep(1.5)
                            continue
                        break
                    if not ok:
                        continue
                    parts = str(candidate or "").split("|")
                    kind = parts[0] if parts else ""
                    if len(parts) >= 3 and kind in accepted:
                        found = str(candidate or "")
                        selected_query = query
                        _diag(f"[KARAFUN-AUTO] search attempt={attempt} result={found!r}")
                        break
                    if len(parts) >= 3 and kind in {"FOUND", "TITLE_ONLY", "FIRST"}:
                        last_error = (
                            f"KaraFun matched a {kind} row for {query!r} without confirming artist "
                            f"{safe_artist_match!r}"
                        )
                        _diag(f"[KARAFUN-AUTO] search attempt={attempt} rejected kind={kind} artist_unconfirmed=1")
                        continue
                    last_error = parts[-1] if parts else "KaraFun search failed"
                    _diag(f"[KARAFUN-AUTO] search attempt={attempt} no_match result={str(candidate or '')[:180]!r}")
                parts = found.split("|")
                if len(parts) < 3 or parts[0] not in {"FOUND", "TITLE_ONLY", "FIRST"}:
                    raise RuntimeError(last_error or "No acceptable KaraFun match")
                selected_duration = self._karafun_clock_seconds(parts[3] if len(parts) > 3 else "")
                if selected_duration and selected_duration > 0:
                    if self._apply_verified_duration(entry, selected_duration, source="karafun_result"):
                        _diag(
                            f"[KARAFUN-AUTO] selected duration seconds={int(selected_duration)} "
                            f"raw={parts[3]!r} replaced_estimate=1"
                        )
                if parts[0] == "FIRST":
                    _diag(f"[KARAFUN-AUTO] selected first visible KaraFun result query={selected_query!r}")
                elif parts[0] == "TITLE_ONLY":
                    _diag(f"[KARAFUN-AUTO] selected KaraFun title without artist confirmation query={selected_query!r}")
                else:
                    _diag(f"[KARAFUN-AUTO] selected exact KaraFun title+artist query={selected_query!r}")

                # When SingWS owns the show display, select the result without
                # starting it, finish the renderer handoff, then reactivate the
                # matched result row. Starting from a double-click let audio/lyrics run for
                # 6-10 seconds behind the fullscreen Space transition.
                _require_current_session()
                _diag(f"[KARAFUN-AUTO] activating KaraFun result mode={parts[0]} x={parts[1]} y={parts[2]}")
                activation_point = (int(float(parts[1])), int(float(parts[2])))
                entry["karafun_result_activation_point"] = activation_point
                _require_current_session()
                managed_handoff = bool(self.settings.get("karafun_manage_show_screen", True))
                if managed_handoff:
                    if not self._macos_native_mouse_click(*activation_point, clicks=1):
                        raise RuntimeError("Could not select the KaraFun result")
                    _schedule_early_handoff("after_result_activation")
                    handoff_wait_deadline = time.monotonic() + 15.0
                    while (bool(getattr(self, "_karafun_handoff_in_progress", False))
                           and time.monotonic() < handoff_wait_deadline):
                        _require_current_session()
                        time.sleep(0.1)
                    handoff_ready = bool(getattr(self, "_karafun_handoff_complete", False))
                    entry["karafun_handoff_timed_out_before_play"] = not handoff_ready
                    if handoff_ready:
                        _diag("[KARAFUN-AUTO] fullscreen audience handoff ready before play")
                    else:
                        _diag(
                            "[KARAFUN-AUTO] fullscreen audience handoff not verified before play; "
                            "continuing with guarded playback"
                        )
                    _schedule_bgm_fade("fullscreen_handoff_ready")
                    activated, activation_error = self._karafun_activate_result_for_playback(
                        activation_point
                    )
                    if not activated:
                        raise RuntimeError(
                            f"Could not start selected KaraFun result: {activation_error}"
                        )
                    result_activated_at = time.monotonic()
                    entry["karafun_result_activated_at"] = result_activated_at
                    entry["karafun_playback_clock_started_at"] = result_activated_at
                    entry["karafun_playback_assumed"] = True
                    time.sleep(0.3)
                else:
                    _schedule_bgm_fade("before_result_activation")
                    if not self._macos_native_double_click(*activation_point):
                        raise RuntimeError("Could not double-click the KaraFun result")
                    result_activated_at = time.monotonic()
                    entry["karafun_result_activated_at"] = result_activated_at
                    time.sleep(0.8)
                _require_current_session()


                playback_probe_script = [
                    'tell application "System Events"',
                    'tell application process "KaraFun"',
                    'set mainWindow to missing value',
                    'repeat with candidateWindow in windows',
                    'try',
                    'if name of candidateWindow is not "Dual Renderer" then',
                    'set mainWindow to candidateWindow',
                    'exit repeat',
                    'end if',
                    'end try',
                    'end repeat',
                    'if mainWindow is missing value then return "ERROR|KaraFun control window not found"',
                    'set out to ""',
                    'set playingHintFound to false',
                    'set idleTextFound to false',
                    'try',
                    'set elems to entire contents of mainWindow',
                    'on error',
                    'set elems to UI elements of mainWindow',
                    'end try',
                    'repeat with elem in elems',
                    'try',
                    'set labelText to ""',
                    'set controlDescription to ""',
                    'try',
                    'set labelText to (name of elem as text) & " " & (description of elem as text) & " " & (help of elem as text) & " " & (value of elem as text)',
                    'end try',
                    'try',
                    'set controlDescription to description of elem as text',
                    'end try',
                    'ignoring case',
                    '-- The idle button help is always "Play/Pause". Its actual',
                    '-- description changes from play to pause during playback.',
                    'if controlDescription is "pause" or controlDescription is "stop" then set playingHintFound to true',
                    'if labelText contains "no item is being played" then set idleTextFound to true',
                    'end ignoring',
                    'end try',
                    'end repeat',
                    'if playingHintFound then return "PLAYING"',
                    '-- Direct result playback does not populate the queue, so',
                    '-- "Your queue is empty" remains visible while playing.',
                    'if idleTextFound then return "IDLE"',
                    'return "UNKNOWN"',
                    'end tell',
                    'end tell',
                ]
                fast_start = bool(self.settings.get("karafun_fast_start_enabled", True))
                if fast_start:
                    # A native double-click on a resolved KaraFun result starts
                    # playback directly. The old full accessibility-tree scan
                    # blocked 11-18 seconds after audio had already begun. Let
                    # the completion monitor verify state in the background.
                    # NOTE: nothing is probed here. Double-clicking a resolved
                    # result usually starts playback, and the old full AX scan
                    # blocked 11-18s after audio had begun. But this is an
                    # ASSUMPTION, not an observation, and when the double-click
                    # does not take (KaraFun rebuilding its renderer, say) the
                    # play click was skipped and nothing ever recovered: on
                    # 2026-08-16 at 01:07 the song sat silent until the operator
                    # pressed play by hand. The completion monitor now actually
                    # performs the verification promised here.
                    ok, initial_probe_state = True, "PLAYING"
                    entry["karafun_playback_assumed"] = True
                    _diag("[KARAFUN-AUTO] fast start assumed playback from activated result; monitor will verify")
                else:
                    ok, initial_probe, initial_probe_error = _run_session_script(playback_probe_script, timeout=5)
                    initial_probe_state = str(initial_probe or initial_probe_error or "").strip()
                _diag(f"[KARAFUN-AUTO] playback pre-click state={initial_probe_state!r}")
                if ok and initial_probe_state == "PLAYING":
                    _schedule_early_handoff("pre_click_playing")
                if not (ok and initial_probe_state == "PLAYING"):
                    pressed, press_error = self._karafun_press_play_control()
                    if not pressed:
                        raise RuntimeError(press_error or "KaraFun play automation failed")
                    entry["karafun_playback_clock_started_at"] = time.monotonic()
                else:
                    entry["karafun_playback_clock_started_at"] = result_activated_at
                    _diag("[KARAFUN-AUTO] play click skipped already playing")
                # The pre-click probe is already a positive playback
                # verification. Do not immediately run the same expensive AX
                # scan again while the fullscreen handoff is starting.
                # Fast start deliberately skips the probe, so its synthetic
                # PLAYING value is permission to continue asynchronously, not
                # evidence that KaraFun actually started. The completion
                # monitor performs that verification without holding up audio.
                verified_playing = bool(
                    ok and initial_probe_state == "PLAYING" and not fast_start
                )
                last_playback_probe = ""
                if not verified_playing and not fast_start:
                    for probe_attempt in range(12):
                        time.sleep(1.0)
                        ok, probe_result, probe_error = _run_session_script(playback_probe_script, timeout=5)
                        last_playback_probe = str(probe_result or probe_error or "").strip()
                        _diag(f"[KARAFUN-AUTO] playback verify attempt={probe_attempt + 1} state={last_playback_probe!r}")
                        if ok and last_playback_probe == "PLAYING":
                            _schedule_early_handoff("playback_verified")
                            verified_playing = True
                            break
                if not verified_playing and not fast_start:
                    raise RuntimeError(f"KaraFun did not report active playback after Play ({last_playback_probe or 'unknown state'})")
                if not entry.get("karafun_playback_clock_started_at"):
                    entry["karafun_playback_clock_started_at"] = time.monotonic()
                entry["karafun_play_started_at"] = time.time()
                _diag(f"[KARAFUN-AUTO] playback start event title={title!r} query={selected_query!r}")

                _require_current_session()
                self._start_karafun_completion_monitor(entry)

                # Discover named controls at runtime. Never set an unidentified slider.
                adjusted = "ADJUSTED|false|false"
                needs_adjustment = requested_key != 0 or requested_tempo != 100
                adjustment_already_applied = str(entry.get("karafun_adjustment_applied") or "") == adjustment_signature
                if needs_adjustment and not adjustment_already_applied:
                    handoff_wait_deadline = time.monotonic() + 15.0
                    while bool(getattr(self, "_karafun_handoff_in_progress", False)) and time.monotonic() < handoff_wait_deadline:
                        time.sleep(0.25)
                    time.sleep(1.5)
                    adjust_script = [
                        'tell application "System Events"',
                        'tell application process "KaraFun"',
                        'set mainWindow to missing value',
                        'repeat with candidateWindow in windows',
                        'try',
                        'if name of candidateWindow is not "Dual Renderer" then set mainWindow to candidateWindow',
                        'end try',
                        'end repeat',
                        'if mainWindow is missing value then return "ERROR|KaraFun control window not found"',
                        'try',
                        'set elems to entire contents of mainWindow',
                        'on error',
                        'set elems to UI elements of mainWindow',
                        'end try',
                        # Never open KaraFun's Audio Settings popover. It is
                        # already configured by the host and opening it here
                        # was the slow/freeze-prone part of every launch. Only
                        # adjust named controls already exposed by the player.
                        'set keySet to false',
                        'set tempoSet to false',
                        'repeat with elem in elems',
                        'try',
                        'if role of elem is "AXSlider" then',
                        'set labelText to ""',
                        'try',
                        'set labelText to (description of elem as text) & " " & (help of elem as text) & " " & (name of elem as text)',
                        'end try',
                        'ignoring case',
                        f'if labelText contains "key" or labelText contains "pitch" then set value of elem to {requested_key}',
                        f'if labelText contains "tempo" or labelText contains "speed" then set value of elem to {requested_tempo}',
                        'if labelText contains "key" or labelText contains "pitch" then set keySet to true',
                        'if labelText contains "tempo" or labelText contains "speed" then set tempoSet to true',
                        'end ignoring',
                        'end if',
                        'end try',
                        'end repeat',
                        'return "ADJUSTED|" & keySet & "|" & tempoSet',
                        'end tell',
                        'end tell',
                    ]
                    ok, adjusted, script_error = _run_session_script(adjust_script, timeout=8)
                    if not ok:
                        _diag(f"[KARAFUN-AUTO] adjustment skipped error={str(script_error or '')[:180]!r}")
                        adjusted = ""
                    else:
                        lowered_adjusted = str(adjusted or "").lower()
                        key_ok = requested_key == 0 or "|true|" in lowered_adjusted
                        tempo_ok = requested_tempo == 100 or lowered_adjusted.endswith("|true")
                        if key_ok and tempo_ok:
                            entry["karafun_adjustment_applied"] = adjustment_signature
                            _diag(f"[KARAFUN-AUTO] adjustment applied {adjustment_signature}")
                else:
                    if adjustment_already_applied:
                        _diag(f"[KARAFUN-AUTO] adjustment skipped already applied {adjustment_signature}")
                    else:
                        _diag("[KARAFUN-AUTO] adjustment skipped default key/tempo")
                result = {"ok": True, "message": adjusted or "ADJUSTED|false|false"}
            except Exception as e:
                result = {"ok": False, "message": str(e)}

            def _finish():
                if not _session_is_current():
                    _diag("[KARAFUN-AUTO] discarded result from ended playback session")
                    return
                if result["ok"]:
                    entry["karafun_submission_state"] = "karafun_queued"
                    entry["karafun_submitted_at"] = int(time.time())
                    entry["karafun_idempotency_key"] = request_uid
                    entry.pop("karafun_pending_at", None)
                    self._set_karafun_entry_status(entry, "playing", message="Playing in KaraFun")
                    _diag(f"[KARAFUN-AUTO] search, queue, and play succeeded title={title!r}")
                    try:
                        self._handoff_show_screen_to_karafun()
                    except Exception as e:
                        _diag(f"[KARAFUN] post-play show-screen handoff failed: {e}")
                    adjustment = result["message"].lower()
                    if (requested_key != 0 and "|true|" not in adjustment) or (requested_tempo != 100 and not adjustment.endswith("|true")):
                        self._show_processing_notification("KaraFun started, but key/tempo controls need manual adjustment.", level="warning")
                    else:
                        self._show_processing_notification(f"KaraFun queued and started: {title}", level="success")
                else:
                    entry["karafun_submission_state"] = "karafun_failed"
                    entry.pop("karafun_pending_at", None)
                    entry["karafun_submission_error"] = result["message"][:240]
                    if self._is_karafun_apple_events_error(result["message"]):
                        setup_message = self._show_karafun_apple_events_setup(notify=True)
                        self._set_karafun_entry_status(entry, "permission", message=setup_message, notify=False)
                    elif self._is_karafun_accessibility_error(result["message"]):
                        setup_message = self._show_karafun_accessibility_setup(notify=True)
                        self._set_karafun_entry_status(entry, "permission", message=setup_message, notify=False)
                    else:
                        self._set_karafun_entry_status(entry, "failed", message=f"KaraFun automation failed: {result['message']}", notify=False)
                    _diag(f"[KARAFUN-AUTO] failed title={title!r} error={result['message'][:240]!r}")
                    if not (
                        self._is_karafun_apple_events_error(result["message"])
                        or self._is_karafun_accessibility_error(result["message"])
                    ):
                        self._show_processing_notification(f"KaraFun automation failed: {result['message']}", level="error")
                self._schedule_save_data(0)
                self.update_queue_display()

            self._run_on_ui_thread(_finish)

        threading.Thread(target=_worker, daemon=True, name="karafun-search-play").start()
        return True

    @staticmethod
    def _karafun_clock_seconds(value: str):
        return normalize_karafun_duration_seconds(value)

    # Fast start assumes playback; these bound how long that assumption may go
    # unverified before the monitor presses play, and then warns the operator.
    KARAFUN_PLAYBACK_RECOVERY_DELAY_S = 12.0
    KARAFUN_HANDOFF_TIMEOUT_RECOVERY_DELAY_S = 6.0
    KARAFUN_PLAYBACK_ALERT_DELAY_S = 40.0

    def _start_karafun_completion_monitor(self, entry: dict):
        """Complete the active external track once KaraFun reports end/idle state."""
        if not isinstance(entry, dict):
            return
        active_session = getattr(self, "_active_external_karafun", None)
        if not isinstance(active_session, dict) or active_session.get("entry") is not entry:
            return
        monitor_token = uuid.uuid4().hex
        entry["karafun_completion_monitor"] = monitor_token
        now_mono = time.monotonic()
        try:
            started = float(entry.get("karafun_playback_clock_started_at") or entry.get("karafun_result_activated_at") or now_mono)
        except Exception:
            started = now_mono
        if started <= 0 or started > now_mono + 5.0:
            started = now_mono
        seen_playback = False
        # The fallback clock must not start until KaraFun is audibly playing.
        # Launching the app, the renderer handoff and the fullscreen Space
        # transition took ~45s on 2026-08-16, all of it charged against the
        # song's own duration, so the fallback hit zero with ~30s still to
        # sing: the rotation advanced and background music came up over the
        # ending. Rebased at the first confirmed playback signal instead.
        playback_confirmed_at = None
        playback_clock_origin = None
        # Fast start assumes the result double-click began playback and skips
        # the play click. When that assumption is wrong nothing recovered and
        # the song sat silent (2026-08-16 01:07, Los Enanitos Verdes: the KJ
        # pressed play by hand 32s in). These drive one recovery press.
        playback_assumed = bool(entry.get("karafun_playback_assumed", False))
        recovery_pressed = False
        playback_hint_seen = False
        playing_hint_count = 0
        last_state = ""
        last_clock_candidates = {}
        last_clock_remaining = None
        last_clock_at = None
        idle_stop_count = 0
        try:
            # Rotation estimates are presentation metadata, not a playback end
            # signal. Only a verified/manual duration may arm the completion
            # watchdog; otherwise a song longer than the catalog estimate could
            # be completed early merely because its ETA used that fallback.
            fallback_duration = (
                0 if bool(entry.get("duration_estimated", False))
                else max(0, int(entry.get("duration") or 0))
            )
        except Exception:
            fallback_duration = 0
        try:
            _diag(
                f"[KARAFUN] completion monitor started title={entry.get('title', '')!r} "
                f"fallback_duration={fallback_duration} clock_age={max(0.0, now_mono - started):.1f}s"
            )
        except Exception:
            pass

        # A stuck accessibility query is not evidence the song has ended.
        # Keep a separate reminder so the host can still use Complete, but
        # never let a wall-clock timeout advance the rotation by itself.
        if fallback_duration > 0:
            fallback_delay = max(1.0, float(fallback_duration) - max(0.0, now_mono - started) + 2.0)

            def _duration_watchdog_fired():
                def _check_duration_watchdog():
                    active = getattr(self, "_active_external_karafun", None)
                    if active is not active_session:
                        return
                    if entry.get("karafun_completion_monitor") != monitor_token:
                        return
                    last_playing = float(entry.get("karafun_last_playing_ts") or 0.0)
                    playing_age = (time.monotonic() - last_playing) if last_playing > 0 else None
                    confirmed_remaining = (
                        fallback_duration - (time.monotonic() - playback_confirmed_at)
                        if playback_confirmed_at is not None else None
                    )
                    if confirmed_remaining is not None and confirmed_remaining > 0:
                        extend = confirmed_remaining + 2.0
                    elif playing_age is not None and playing_age <= 20.0:
                        extend = 15.0
                    else:
                        extend = None
                    if extend is not None:
                        again = threading.Timer(extend, _duration_watchdog_fired)
                        again.daemon = True
                        again.start()
                        return
                    _diag(
                        "[KARAFUN] end unverified reason=duration_watchdog "
                        f"last_playing={'never' if playing_age is None else f'{playing_age:.1f}s ago'}"
                    )
                    self._set_karafun_entry_status(
                        entry, "manual",
                        message="Cannot verify that KaraFun has finished. Use Complete when the song ends.",
                        notify=True, level="warning",
                    )

                self._run_on_ui_thread(_check_duration_watchdog)

            duration_watchdog = threading.Timer(fallback_delay, _duration_watchdog_fired)
            duration_watchdog.daemon = True
            duration_watchdog.start()

        def _monitor():
            nonlocal seen_playback, last_state, last_clock_candidates, idle_stop_count
            nonlocal playback_confirmed_at, playback_clock_origin, recovery_pressed, playing_hint_count, playback_hint_seen
            nonlocal last_clock_remaining, last_clock_at

            def _confirm_playback():
                nonlocal playback_confirmed_at, seen_playback
                seen_playback = True
                if playback_confirmed_at is None:
                    playback_confirmed_at = time.monotonic()
                    confirmation_delay = max(0.0, playback_confirmed_at - started)
                    # A selected result that SingWS explicitly started after a
                    # completed fullscreen handoff has an authoritative start
                    # timestamp. Do not move its end 10-15 seconds late merely
                    # because the first Accessibility probe was slow. Preserve
                    # the old rebase for launches whose start was not controlled.
                    playback_clock_origin = (
                        started
                        if bool(entry.get("karafun_playback_clock_started_at"))
                        else playback_confirmed_at
                    )
                    _diag(
                        "[KARAFUN] playback confirmed; duration fallback rebased "
                        f"(launch overhead {confirmation_delay:.1f}s "
                        f"{'retained' if playback_clock_origin == started else 'excluded'})"
                    )
            while True:
                active = getattr(self, "_active_external_karafun", None)
                if active is not active_session:
                    return
                if entry.get("karafun_completion_monitor") != monitor_token:
                    return
                # NSAppleScript calls into KaraFun are not safely concurrent.
                # Let the latency-sensitive fullscreen handoff finish before
                # starting the recurring completion-state scrape. The duration
                # watchdog above remains active throughout this pause.
                if bool(getattr(self, "_karafun_handoff_in_progress", False)):
                    time.sleep(0.25)
                    continue
                remaining = None
                idle_reported = False
                playing_reported = False
                clocks = []
                try:
                    script = [
                        'tell application "System Events"',
                        'set matches to every application process whose name contains "KaraFun"',
                        'if (count of matches) is 0 then return ""',
                        'tell item 1 of matches',
                        # The control window is hidden while Dual Renderer owns
                        # a fullscreen Space, but KaraFun keeps its Playback
                        # menu available. Its first item toggles between Play
                        # and Pause and remains cheap to read in that state.
                        'try',
                        'set playbackToggleName to name of menu item 1 of menu 1 of menu bar item "Playback" of menu bar 1 as text',
                        'ignoring case',
                        'if playbackToggleName is "pause" then return "STATE|PLAYING"',
                        'if playbackToggleName is "play" then return "STATE|IDLE"',
                        'end ignoring',
                        'end try',
                        'if (count of windows) is 0 then return ""',
                        'set mainWindow to missing value',
                        'repeat with candidateWindow in windows',
                        'try',
                        'if name of candidateWindow is not "Dual Renderer" then',
                        'set mainWindow to candidateWindow',
                        'exit repeat',
                        'end if',
                        'end try',
                        'end repeat',
                        'if mainWindow is missing value then return ""',
                        'set out to ""',
                        'set idleTextFound to false',
                        'set playingHintFound to false',
                        'try',
                        'set elems to entire contents of mainWindow',
                        'on error',
                        'set elems to UI elements of mainWindow',
                        'end try',
                        'repeat with elem in elems',
                        'try',
                        # Query only attributes used by the monitor. Fetching
                        # name/description/help/value on every tree node made
                        # each show-machine poll take 16-18 seconds.
                        'set elementRole to role of elem',
                        'if elementRole is "AXButton" then',
                        'set controlDescription to description of elem as text',
                        'ignoring case',
                        'if controlDescription is "pause" or controlDescription is "stop" then set playingHintFound to true',
                        'end ignoring',
                        'else if elementRole is "AXStaticText" then',
                        'set n to name of elem as text',
                        'ignoring case',
                        # Direct result playback can leave the queue empty.
                        # That label cannot distinguish playing from idle.
                        'if n contains "no item is being played" then set idleTextFound to true',
                        'end ignoring',
                        'if n contains ":" and (length of n) is less than 9 then set out to out & n & linefeed',
                        'end if',
                        'end try',
                        'end repeat',
                        'if idleTextFound and not playingHintFound then set out to out & "STATE|IDLE" & linefeed',
                        'if playingHintFound then set out to out & "STATE|PLAYING" & linefeed',
                        'return out',
                        'end tell',
                        'end tell',
                    ]
                    probe_started = time.monotonic()
                    ok, raw, _script_error = self._run_karafun_applescript_sync(script, timeout=4)
                    if (getattr(self, "_active_external_karafun", None) is not active_session
                            or entry.get("karafun_completion_monitor") != monitor_token):
                        return
                    probe_elapsed = time.monotonic() - probe_started
                    if probe_elapsed >= 4.0:
                        _diag(f"[KARAFUN] slow playback probe seconds={probe_elapsed:.1f} ok={int(ok)}")
                    if not ok:
                        raw = ""
                    lines = [str(v or "").strip() for v in raw.splitlines() if str(v or "").strip()]
                    idle_reported = any(v == "STATE|IDLE" for v in lines)
                    playing_reported = any(v == "STATE|PLAYING" for v in lines)
                    clocks = [self._karafun_clock_seconds(v) for v in lines if not v.startswith("STATE|")]
                    clocks = [v for v in clocks if v is not None]
                    # KaraFun may expose search durations or display counters
                    # after the actual player clock. Static duration labels can
                    # look like current == total, so only trust a clock pair
                    # once its current value progresses between polls.
                    next_clock_candidates = {}
                    for i in range(0, max(0, len(clocks) - 1)):
                        current, total = clocks[i], clocks[i + 1]
                        if total > 0 and 0 <= current <= total:
                            previous = last_clock_candidates.get(total)
                            next_clock_candidates[total] = max(current, int(next_clock_candidates.get(total, -1)))
                            if previous is None or current <= previous:
                                continue
                            remaining = total - current
                            last_clock_remaining = remaining
                            last_clock_at = time.monotonic()
                            # A clock that advanced between polls is the
                            # strongest proof KaraFun is still playing, so it
                            # also holds the duration watchdog off.
                            entry["karafun_last_playing_ts"] = time.monotonic()
                            if current > 2:
                                _confirm_playback()
                    last_clock_candidates = next_clock_candidates
                    if playing_reported:
                        playback_hint_seen = True
                        playing_hint_count += 1
                        idle_stop_count = 0
                        # A single stale Pause/Stop accessibility label is not
                        # proof that playback began. Require it on consecutive
                        # polls; an advancing player clock above confirms
                        # immediately and is handled earlier in this block.
                        if playing_hint_count >= 2:
                            _confirm_playback()
                            # Timestamp of the newest confirmed "still playing"
                            # reading. The duration watchdog reads this to avoid
                            # cutting a song KaraFun has not finished.
                            entry["karafun_last_playing_ts"] = time.monotonic()
                    elif idle_reported and seen_playback:
                        playing_hint_count = 0
                        idle_stop_count += 1
                    else:
                        playing_hint_count = 0
                        idle_stop_count = 0
                    state_label = (
                        f"idle={int(idle_reported)} playing={int(playing_reported)} "
                        f"remaining={remaining}"
                    )
                    if state_label != last_state:
                        _diag(f"[KARAFUN] monitor state {state_label} idle_stop_count={idle_stop_count}")
                        last_state = state_label
                except Exception:
                    remaining = None

                fallback_remaining = None
                remaining_from_fallback = False
                if fallback_duration > 0:
                    # Count from the first confirmed playback, not from the
                    # handoff: everything before that is KaraFun starting up.
                    fallback_origin = playback_clock_origin if playback_clock_origin is not None else started
                    fallback_remaining = fallback_duration - int(time.monotonic() - fallback_origin)
                if remaining is None and fallback_remaining is not None:
                    remaining = fallback_remaining
                    remaining_from_fallback = True
                age = time.monotonic() - started
                recovery_delay = (
                    self.KARAFUN_HANDOFF_TIMEOUT_RECOVERY_DELAY_S
                    if bool(entry.get("karafun_handoff_timed_out_before_play", False))
                    else self.KARAFUN_PLAYBACK_RECOVERY_DELAY_S
                )
                if remaining is not None and remaining > 5:
                    if not remaining_from_fallback:
                        _confirm_playback()
                # Recovery: if result activation did not take, pressing Play
                # while KaraFun is still idle has no loaded song to start. Retry
                # the already-matched result once; only use Play as a fallback
                # when that saved activation point is unavailable.
                if (
                    playback_assumed
                    and not recovery_pressed
                    and playback_confirmed_at is None
                    and not playback_hint_seen
                    and idle_reported
                    and not playing_reported
                    and age > recovery_delay
                ):
                    recovery_pressed = True
                    _diag(
                        f"[KARAFUN] playback never started after {age:.0f}s; "
                        "retrying the matched result once (fast start assumed it had)"
                    )
                    activation_point = entry.get("karafun_result_activation_point")
                    try:
                        reactivated, press_error = (
                            self._karafun_activate_result_for_playback(activation_point)
                        )
                    except Exception as exc:
                        reactivated = False
                        press_error = str(exc)
                    if reactivated:
                        entry["karafun_result_activated_at"] = time.monotonic()
                        _diag("[KARAFUN] recovery result activation sent")
                    else:
                        try:
                            pressed, press_error = self._karafun_press_play_control()
                        except Exception as exc:
                            pressed, press_error = False, str(exc)
                        if pressed:
                            _diag("[KARAFUN] recovery play press sent")
                        else:
                            _diag(f"[KARAFUN] recovery play press failed: {press_error}")
                            self._set_karafun_entry_status(
                                entry, "manual",
                                message="KaraFun did not start this song. Press play in KaraFun.",
                                notify=True, level="warning",
                            )
                    time.sleep(1.0)
                    continue

                # Report unverified playback without treating an unreadable
                # state as permission to press Play or activate the result.
                if (
                    playback_assumed
                    and not playing_reported
                    and not playback_hint_seen
                    and playback_confirmed_at is None
                    and age > self.KARAFUN_PLAYBACK_ALERT_DELAY_S
                    and str(entry.get("karafun_status") or "") != "manual"
                ):
                    _diag(f"[KARAFUN] playback unverified after {age:.0f}s; alerting operator idle={int(idle_reported)}")
                    self._set_karafun_entry_status(
                        entry, "manual",
                        message=("KaraFun is not playing this song. Press play in KaraFun."
                                 if idle_reported else
                                 "Cannot read KaraFun playback status. Check KaraFun; use Complete when the song ends."),
                        notify=True, level="warning",
                    )

                clock_near_end = (
                    last_clock_remaining is not None and last_clock_remaining <= 5
                    and last_clock_at is not None and time.monotonic() - last_clock_at <= 20.0
                )
                expected_end_reached = (
                    playback_confirmed_at is not None
                    and fallback_remaining is not None and fallback_remaining <= 5
                )
                # An idle label alone cut a 263-second song after 34 seconds.
                # Require end timing as corroboration, and never complete while
                # playing or unknown. At a corroborated end, one idle reading
                # suffices: waiting for a second full scrape adds dead air.
                should_complete = (
                    idle_reported and not playing_reported and seen_playback
                    and idle_stop_count >= 1 and age > 8.0
                    and (clock_near_end or expected_end_reached)
                )
                if should_complete:
                    def _complete_near_end():
                        current_active = getattr(self, "_active_external_karafun", None)
                        if (current_active is active_session
                                and entry.get("karafun_completion_monitor") == monitor_token):
                            reason = "karaFun_idle_clock_end" if clock_near_end else "karaFun_idle_expected_end"
                            _diag(f"[KARAFUN] completion event received reason={reason} remaining={remaining} idle={int(idle_reported)}")
                            self._finish_external_karafun_playback("complete", expected_active=active_session)
                    self._run_on_ui_thread(_complete_near_end)
                    return
                time.sleep(1.0)

        threading.Thread(target=_monitor, daemon=True, name="karafun-completion-monitor").start()

    def _fade_bg_for_external_karafun(self):
        try:
            self._bg_transition_gen = int(getattr(self, "_bg_transition_gen", 0)) + 1
            self._clear_bg_transition_timers()
        except Exception:
            pass
        bg = getattr(self, "bg_music", None)
        if bg is None:
            return
        try:
            if bool(getattr(bg, "is_playing", False)):
                fade_ms = max(200, int(getattr(self, "_bg_fade_duration_ms", 1000) or 1000))
                bg.fade_out(fade_ms)
                _diag(f"[KARAFUN] BGM fade_out duration_ms={fade_ms}")
        except Exception as e:
            _diag(f"[KARAFUN] BGM fade failed: {e}")

    def _start_external_karafun_playback(self, *, singer: dict, entry: dict, song_info, key=0, tempo_percent=None, duet_display=None, marker_was_top: bool = False):
        artist, title = self._karafun_entry_artist_title(entry)
        singer_display = duet_display or str((singer or {}).get("name", "") or "").strip()
        self._karafun_restore_token = None
        self._karafun_handoff_token = None
        self._karafun_handoff_in_progress = False
        self._karafun_handoff_complete = False
        self._karafun_transparent_renderer_ready = False
        self._active_external_karafun = {
            "singer": singer,
            "entry": entry,
            "song_info": song_info,
            "key": key,
            "tempo_percent": tempo_percent,
            "duet_display": duet_display,
            "marker_was_top": bool(marker_was_top),
            "started_at": time.time(),
        }
        # play_next_file popped this singer, and a KaraFun song plays for minutes
        # in an external app. Leaving them out of the queue that whole time made
        # relay reconciliation treat them as brand new -- observed live as
        # "[QUEUE-INSERT] singer='Hanady' reason=new_singer insertion_index=0" --
        # and _merge_duplicate_rotation_singers then collapsed that copy with the
        # one appended at completion, keeping the *earliest* slot. Net effect: the
        # singer never reached the bottom of the rotation.
        #
        # Put them back on the queue now, exactly as the normal playback path
        # does, so sync recognises them and appends to the existing record.
        try:
            self.queue.append(singer)
            if self._is_rotation_locked():
                self._rotation_reweave_locked_tail()
            self.queue = self.queue.copy()
        except Exception as exc:
            _diag(f"[KARAFUN] queue re-add at start failed: {exc}")
        self.karaoke_playing = True
        self._eta_hold_current_secs = max(0, int((entry or {}).get("duration") or 0))
        self._current_karaoke_singer_name = str((singer or {}).get("name", "") or "")
        self._current_karaoke_singer_display = str(singer_display or "")
        self._current_karaoke_singer_id = self._ensure_singer_id(singer)
        self._current_karaoke_request_id = self._ensure_queue_entry_id(entry)
        self._current_karaoke_song_path = str(self._song_info_primary_path(song_info) or "")
        self._current_karaoke_artist = str(artist or "")
        self._current_karaoke_title = str(title or "")
        _diag(f"[KARAFUN] song started singer={singer_display!r} artist={artist!r} title={title!r}")
        QTimer.singleShot(0, lambda: self._reapply_rotation_presentation(scroll_current=True))
        try:
            self._clear_next_up_overlay_pending("external_karafun_start")
        except Exception:
            pass
        try:
            self._set_now_singing_3line(singer_display, artist, title)
            self._trigger_show_screen_singer_start_vfx(singer_display, artist, title)
        except Exception:
            pass
        open_automatically = bool(self.settings.get("karafun_open_automatically", True))
        automatic_playback = open_automatically and bool(
            self.settings.get("karafun_auto_queue_enabled", False)
        )
        try:
            if not automatic_playback:
                self._fade_bg_for_external_karafun()
        except Exception:
            pass
        try:
            self._show_idle_background_after_karaoke(reason="external_karafun_active", advance_slideshow=False)
        except Exception:
            pass
        # The automation worker performs the launch and authorization preflight
        # itself so it can recover after KaraFun is restarted. Only the manual
        # companion path needs to launch KaraFun here.
        if open_automatically and not automatic_playback:
            opened = self._open_karafun_for_entry(entry)
            if not opened:
                self._copy_karafun_lookup_text(entry)
        elif not open_automatically:
            self._copy_karafun_lookup_text(entry)
        try:
            _diag(f"[KARAFUN] companion active singer={singer_display!r} artist={artist!r} title={title!r}")
        except Exception:
            pass
        self._show_external_karafun_dialog(activate=not automatic_playback)
        if automatic_playback:
            self._automate_karafun_search_and_play(entry, key=key, tempo_percent=tempo_percent)
        self.queue = self.queue.copy()
        QTimer.singleShot(0, self.update_queue_display)

    def _show_external_karafun_dialog(self, *, activate: bool = True):
        active = self._active_external_karafun
        if not isinstance(active, dict):
            return
        old = getattr(self, "_active_external_karafun_dialog", None)
        try:
            if old is not None:
                old.close()
        except Exception:
            pass
        entry = active.get("entry") or {}
        singer = active.get("singer") or {}
        artist, title = self._karafun_entry_artist_title(entry)
        dlg = QDialog(self)
        dlg.setWindowTitle("KaraFun Active")
        dlg.setModal(False)
        # KaraFun is brought to the foreground after this companion appears.
        # Keep the explicit Complete/Return controls reachable on the host
        # display throughout the song, without activating them or allowing the
        # automation worker's Return key to trigger a button.
        dlg.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint, True)
        dlg.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, not activate)
        dlg.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, False)
        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(18, 16, 18, 14)
        layout.setSpacing(10)
        heading = QLabel(f"{str(singer.get('name', '') or '').strip()}")
        heading.setStyleSheet(f"color:{_v('text_bright')}; font-size:18px; font-weight:800;")
        layout.addWidget(heading)
        song_label = QLabel(" - ".join([p for p in (artist, title) if p]) or "KaraFun Song")
        song_label.setWordWrap(True)
        song_label.setStyleSheet(f"color:{_v('text')}; font-size:14px; font-weight:700;")
        layout.addWidget(song_label)
        note = QLabel("SingWS is controlling KaraFun and will advance automatically when playback ends.")
        note.setWordWrap(True)
        note.setStyleSheet(section_meta_css())
        layout.addWidget(note)
        actions = QHBoxLayout()
        complete_btn = QPushButton("Complete")
        open_btn = QPushButton("Open KaraFun")
        copy_btn = QPushButton("Copy Info")
        return_btn = QPushButton("Return to Queue")
        for btn in (complete_btn, open_btn, copy_btn, return_btn):
            btn.setMinimumHeight(34)
            # Search automation sends Return. It must never activate Complete
            # or Return to Queue if focus briefly lands on this dialog.
            btn.setAutoDefault(False)
            btn.setDefault(False)
        complete_btn.setStyleSheet(button_css(padding="7px 10px", radius=8))
        open_btn.setStyleSheet(subtle_button_css(padding="7px 10px", radius=8))
        copy_btn.setStyleSheet(subtle_button_css(padding="7px 10px", radius=8))
        return_btn.setStyleSheet(warning_button_css(padding="7px 10px", radius=8))
        actions.addWidget(complete_btn)
        actions.addWidget(open_btn)
        actions.addWidget(copy_btn)
        actions.addWidget(return_btn)
        layout.addLayout(actions)
        complete_btn.clicked.connect(lambda: self._finish_external_karafun_playback("complete", expected_active=active))
        open_btn.clicked.connect(lambda: self._open_karafun_for_entry(entry))
        copy_btn.clicked.connect(lambda: self._copy_karafun_lookup_text(entry))
        return_btn.clicked.connect(lambda: self._finish_external_karafun_playback("return_to_queue", expected_active=active))
        self._active_external_karafun_dialog = dlg
        try:
            dlg.resize(520, dlg.sizeHint().height())
        except Exception:
            pass
        dlg.show()
        if activate:
            dlg.raise_()
            dlg.activateWindow()

    def _finish_external_karafun_playback(self, action: str, *, expected_active=None):
        active = self._active_external_karafun
        if expected_active is not None and active is not expected_active:
            _diag("[KARAFUN] ignored completion from an older playback session")
            return
        if not isinstance(active, dict):
            return
        action = str(action or "").strip().lower()
        _diag(f"[KARAFUN] finish requested action={action!r} submission_state={str((active.get('entry') or {}).get('karafun_submission_state') or '')!r}")
        singer = active.get("singer") if isinstance(active.get("singer"), dict) else {}
        entry = active.get("entry") if isinstance(active.get("entry"), dict) else {}
        song_info = active.get("song_info")
        key = active.get("key", 0)
        tempo_percent = active.get("tempo_percent")
        marker_was_top = bool(active.get("marker_was_top", False))
        singer_name = str(singer.get("name", "") or "").strip()
        try:
            dlg = getattr(self, "_active_external_karafun_dialog", None)
            if dlg is not None:
                dlg.close()
        except Exception:
            pass
        self._active_external_karafun_dialog = None
        self._active_external_karafun = None
        try:
            entry.pop("karafun_completion_monitor", None)
            entry.pop("karafun_play_started_at", None)
        except Exception:
            pass
        self.karaoke_playing = False
        self._eta_hold_current_secs = 0
        self._restore_show_screen_from_karafun()

        if action == "return_to_queue":
            try:
                self._set_karafun_entry_status(entry, "ready", message="Returned to queue")
                singer.setdefault("songs", []).insert(0, entry)
                # Remove the reference added when playback started, otherwise
                # returning to the queue leaves this singer listed twice.
                self.queue = [s for s in self.queue if s is not singer]
                self.queue.insert(0, singer)
                self.queue = self.queue.copy()
                self._show_processing_notification("KaraFun song returned to queue.", level="info")
                _diag(f"[KARAFUN] returned to queue singer={singer_name!r}")
            except Exception as e:
                _diag(f"[KARAFUN] return_to_queue failed: {e}")
            try:
                self.clear_now_singing()
            except Exception:
                pass
            try:
                self._schedule_bg_resume(120, reason="external_karafun_return")
            except Exception:
                pass
            self.update_queue_display()
            self.save_data()
            return

        try:
            rid = self._queue_entry_remote_request_id(entry)
            if rid is not None:
                self._complete_remote_request(rid, entry=entry, singer_name=singer_name, reason="external_karafun_completed")
        except Exception:
            pass
        try:
            self._set_karafun_entry_status(entry, "completed", message="Completed in KaraFun")
            entry["karafun_submission_state"] = "karafun_completed"
        except Exception:
            pass
        try:
            self._record_singer_history_play(singer_name, entry, str(self._song_info_primary_path(song_info) or ""), key=key, tempo_percent=tempo_percent)
            self._sync_singer_history_async("external_karafun_complete")
        except Exception:
            pass
        singer["has_sung"] = True
        singer["last_sung_at"] = time.time()
        if self._is_rotation_mode():
            singer["round_sung"] = True
        # They are already on the queue (added when playback started), so drop
        # that reference before re-adding, or completion leaves the same singer
        # in twice. Identity comparison, not name: it is the very same dict, so
        # nothing can be lost, and a separate record for the same person is left
        # alone for the normal merge path to handle.
        try:
            self.queue = [s for s in self.queue if s is not singer]
        except Exception as exc:
            _diag(f"[KARAFUN] queue dedupe before rotation failed: {exc}")
        self.queue.append(singer)
        if self._is_rotation_locked():
            self._rotation_reweave_locked_tail()
        if self._is_rotation_mode():
            if marker_was_top:
                for s in self.queue:
                    if isinstance(s, dict):
                        s["rotation_marker"] = False
                singer["rotation_marker"] = True
            self._rotation_repair_marker()
            self._rotation_recompute_round_state(force_reset=False)
        self.queue = self.queue.copy()
        try:
            self._mark_next_up_overlay_pending_after_completion(reason="external_karafun_complete")
        except Exception:
            pass
        try:
            self.clear_now_singing()
        except Exception:
            pass
        try:
            self._schedule_waiting_for_add_view_refresh(reason="external_karafun_completed")
        except Exception:
            pass
        try:
            self._schedule_bg_resume(120, reason="external_karafun_complete")
        except Exception:
            pass
        self.update_queue_display()
        self._schedule_save_data(500)
        try:
            self.post_rotation()
        except Exception:
            pass
        _diag(f"[KARAFUN] song ended singer={singer_name!r} action={action!r}")
        _diag(f"[KARAFUN] rotation advanced after completion singer={singer_name!r} queue_len={len(self.queue) if isinstance(self.queue, list) else -1}")

    def _set_play_control_starting(self, starting: bool):
        """Mark Play locked while still allowing a repeat press to ask first."""
        self._play_control_starting = bool(starting)
        button = getattr(self, "play_next", None)
        if button is None:
            return
        try:
            # Keep the widget enabled so a deliberate repeated press can open
            # the required confirmation. The command/token gate below is the
            # lock that prevents that signal from mutating the queue directly.
            button.setEnabled(True)
            button.setToolTip(
                "Starting queued song…" if starting else "Play Next Singer"
            )
        except Exception:
            pass

    @staticmethod
    def _play_confirmation_line(payload: dict, fallback: str) -> str:
        payload = payload if isinstance(payload, dict) else {}
        singer = str(payload.get("singer") or fallback or "Unknown singer").strip()
        artist = str(payload.get("artist") or "").strip()
        title = str(payload.get("title") or "").strip()
        song = " — ".join(part for part in (artist, title) if part) or "Unknown song"
        return f"{singer}: {song}"

    def _repeated_play_payloads(self) -> tuple[dict, dict, str]:
        pending = getattr(self, "_pending_play_start_context", None)
        if isinstance(pending, dict):
            current = dict(pending.get("payload") or {})
            state = "starting"
        else:
            current = self._song_outro_payload_from_current()
            state = "paused" if self._is_karaoke_paused() else "playing"
        try:
            next_payload = self._next_up_transition_payload_from_queue()
        except Exception:
            next_payload = {}
        return current, next_payload, state

    def _confirm_repeated_play_advance(self) -> bool:
        """Describe the exact interrupt/queue effects before advancing."""
        if bool(getattr(self, "_play_confirmation_open", False)):
            _diag("[PLAY-COMMAND] duplicate confirmation request ignored")
            return False
        current, next_payload, state = self._repeated_play_payloads()
        if not next_payload:
            try:
                QMessageBox.information(
                    self,
                    "No Next Song",
                    "There is no playable queued song to advance to.\n\n"
                    "Current audio and every queue entry will remain unchanged.",
                )
            except Exception:
                pass
            return False
        current_line = self._play_confirmation_line(current, "Current singer")
        next_line = self._play_confirmation_line(next_payload, "Next singer")
        if state == "starting":
            current_effect = (
                "The pending start will be canceled. Its song will be retained and its singer "
                "will move to the end of the rotation."
            )
        elif state == "paused":
            current_effect = "The paused current song will stop and remain in performance history."
        else:
            current_effect = "The currently playing song will stop and remain in performance history."
        message = (
            f"Current ({state}):\n{current_line}\n\n"
            f"Next to play:\n{next_line}\n\n"
            f"{current_effect}\n"
            "The next song will leave the pending queue only after playback successfully starts.\n"
            "No other singer or song will be skipped, completed, deleted, or removed.\n\n"
            "Stop the current action and play the identified next song?"
        )
        self._play_confirmation_open = True
        try:
            dlg = ConfirmInterruptDialog(
                self,
                title="Stop Current and Play Next?",
                message=message,
                confirm_text="Stop & Play Next",
                cancel_text="Keep Current",
            )
            accepted = dlg.exec() == QDialog.DialogCode.Accepted
            _diag(f"[PLAY-COMMAND] repeated play confirmation accepted={int(accepted)} state={state}")
            return accepted
        except Exception as exc:
            # A broken dialog must never turn into an unconfirmed advance.
            _diag(f"[PLAY-COMMAND] confirmation failed closed: {exc}")
            return False
        finally:
            self._play_confirmation_open = False

    def _advance_from_pending_start_after_confirmation(self) -> bool:
        context = getattr(self, "_pending_play_start_context", None)
        if not isinstance(context, dict):
            return False
        pending_singer_id = str(context.get("singer_id") or "")
        if not self._cancel_pending_singer_start_for_queue_change("confirmed_play_advance"):
            return False
        # Rollback restored the selected request. Advancing rotates that singer
        # without setting skip, completing the request, or deleting the song.
        for idx, candidate in enumerate(list(getattr(self, "queue", []) or [])):
            if not isinstance(candidate, dict):
                continue
            if str(self._ensure_singer_id(candidate) or "") != pending_singer_id:
                continue
            retained = self.queue.pop(idx)
            self.queue.append(retained)
            self.queue = self.queue.copy()
            _diag(
                f"[PLAY-COMMAND] retained pending song and rotated singer "
                f"singer_id={pending_singer_id} from_index={idx}"
            )
            try:
                self._request_queue_display_refresh()
                self._schedule_save_data(0)
            except Exception:
                pass
            break
        self._next_in_progress = False
        return True

    def _flash_play_control_kept_current(self):
        """Briefly say why Play did nothing, so the press is not silent.

        The old behaviour answered a press with a modal; the new one keeps the
        current song. Without some acknowledgement that reads as a dead button,
        which is the complaint that started this.
        """
        button = getattr(self, "play_next", None)
        if button is None:
            return
        try:
            restore = "Starting queued song…" if bool(
                getattr(self, "_play_control_starting", False)
            ) else "Play Next Singer"
            button.setToolTip("Current song kept — use Skip or Stop to end it")
            try:
                from PyQt6.QtWidgets import QToolTip
                from PyQt6.QtGui import QCursor

                QToolTip.showText(QCursor.pos(), button.toolTip(), button)
            except Exception:
                pass
            timer = getattr(self, "_play_kept_current_timer", None)
            if timer is None:
                timer = QTimer(self)
                timer.setSingleShot(True)
                self._play_kept_current_timer = timer
            try:
                timer.timeout.disconnect()
            except Exception:
                pass
            timer.timeout.connect(lambda: self._restore_play_control_tooltip(restore))
            timer.start(2500)
        except Exception:
            pass

    def _restore_play_control_tooltip(self, text: str):
        button = getattr(self, "play_next", None)
        if button is None:
            return
        try:
            button.setToolTip(str(text or "Play Next Singer"))
        except Exception:
            pass

    def _on_play_control_clicked(self, _checked=False):
        """Single UI entry point for mouse, touch, keyboard, and accessibility."""
        starting = bool(
            getattr(self, "_pending_play_start_token", None) is not None
            or getattr(self, "_next_in_progress", False)
            or getattr(self, "_play_control_starting", False)
            or getattr(self, "_mp3g_prepare_then_play_next", "")
        )
        active = bool(
            starting
            or getattr(self, "karaoke_transport", None) is not None
            or getattr(self, "karaoke_playing", False)
        )
        if not active:
            self.play_next_file(skip_confirmation=True, command_source="manual_idle")
            return
        # Pressing Play while something is already going keeps the current
        # song. It used to raise a "Stop Current and Play Next?" dialog, but
        # confirming it could still end in a silent no-op: when the advance
        # came from a pending start, a failed rollback just returned without
        # a word, so the press looked broken. Interrupting a singer mid-song
        # is not a decision worth a modal on a live console either -- the
        # explicit Skip and Stop controls already do that deliberately.
        _diag(
            "[PLAY-COMMAND] play pressed while active; keeping current song "
            f"(starting={int(starting)})"
        )
        self._flash_play_control_kept_current()

    def play_next_file(self, skip_confirmation=False, *, command_source="internal"):
        # Intro Loop release: if the next song is held in a looping intro, a
        # Play/Next press just lets it continue past the loop — no teardown, no
        # advance. (Not during the media-end auto-advance, which sets _pending.)
        if getattr(self, "_intro_loop_active", False) and not getattr(self, "_pending_intro_loop", False):
            self._release_intro_loop()
            return
        try:
            self._flush_deferred_remote_adds("before_play_next")
        except Exception:
            pass
        self._cancel_pending_media_end_cleanup("play_next")
        try:
            q_len = len(self.queue) if hasattr(self, "queue") and self.queue is not None else -1
            has_pipe = bool(getattr(self, "karaoke_transport", None))
            _diag(
                f"[PLAYNEXT] requested source={command_source} queue_len={q_len} "
                f"next_in_progress={bool(getattr(self, '_next_in_progress', False))} "
                f"stop_in_progress={bool(getattr(self, '_stop_in_progress', False))} has_pipeline={has_pipe}"
            )
        except Exception:
            pass
        # Prevent overlapping "next" actions when the button is spammed.
        # Without this, multiple pipelines can start and you can end up with multiple tracks playing.
        if getattr(self, "_stop_in_progress", False):
            has_pipe = False  # legacy pipelines removed
            stop_age = max(0.0, time.monotonic() - float(getattr(self, "_stop_started_ts", 0.0) or 0.0))
            teardown_active = bool(getattr(self, "_teardown_active", False))
            # While async teardown is active, never clear the gate based only on refs.
            if teardown_active or stop_age < 5.0:
                self._playnext_pending = True
                _diag(f"[PLAYNEXT] deferred: teardown in progress (age={stop_age:.2f}s active={teardown_active})")
                return
            if not has_pipe:
                _diag("[PLAYNEXT] self-heal: clearing stale stop gate after timeout")
                self._stop_in_progress = False
                self._teardown_active = False
                self._recover_idle_output("playnext_self_heal", ensure_bg=False)
            else:
                self._playnext_pending = True
                _diag("[PLAYNEXT] deferred: teardown in progress")
                return

        # Serialize transition: if karaoke pipelines are active, request teardown and
        # start the next track only from teardown-complete callback.
        has_pipe_now = False  # legacy pipelines removed
        if has_pipe_now:
            self._playnext_pending = True
            _diag("[PLAYNEXT] queued: active pipeline detected, waiting for teardown complete")
            try:
                self._gst_teardown_async()
            except Exception:
                pass
            return

        if getattr(self, "_next_in_progress", False):
            _diag("[PLAYNEXT] ignored: action already in progress")
            return
        if getattr(self, "_pending_play_start_token", None) is not None:
            _diag("[PLAYNEXT] ignored: playback preroll/countdown not committed")
            return
        self._next_in_progress = True
        self._set_play_control_starting(True)
        # Covers countdown + asynchronous GStreamer preroll. A 450ms gate let
        # a normal double-click consume the following singer before audio had
        # started on slower Macs.
        QTimer.singleShot(3500, lambda: setattr(self, "_next_in_progress", False))

        # Optional confirmation if currently playing
        is_playing = False
        if getattr(self, "karaoke_transport", None) is not None:
            is_playing = True
        if is_playing and not skip_confirmation:
            dlg = ConfirmInterruptDialog(self)
            if dlg.exec() != QDialog.DialogCode.Accepted:
                _diag("[PLAYNEXT] cancelled by interrupt dialog")
                self._next_in_progress = False
                self._set_play_control_starting(False)
                return

        if not self.queue:
            _diag("[PLAYNEXT] ignored: queue empty")
            self._next_in_progress = False
            self._set_play_control_starting(False)
            return

        # Playback selection is transactional. Several legacy return paths
        # popped a singer/song before validating or starting media, which is
        # how a failed Play could make later rotation positions disappear.
        queue_snapshot = list(self.queue)
        singer_snapshots = []
        for snapshot_singer in queue_snapshot:
            if not isinstance(snapshot_singer, dict):
                continue
            snapshot_state = dict(snapshot_singer)
            snapshot_state["songs"] = list(snapshot_singer.get("songs", []) or [])
            singer_snapshots.append((snapshot_singer, snapshot_state))

        def _restore_play_transaction(reason: str, *, clear_gate: bool = True):
            for snapshot_singer, snapshot_state in singer_snapshots:
                snapshot_singer.clear()
                snapshot_singer.update(snapshot_state)
                snapshot_singer["songs"] = list(snapshot_state.get("songs", []) or [])
            self.queue = list(queue_snapshot)
            self.karaoke_playing = False
            self._playback_start_countdown_ms = 0
            self._pending_playback_countdown_payload = None
            if clear_gate:
                self._next_in_progress = False
                self._set_play_control_starting(False)
            _diag(f"[QUEUE-AUDIT] action=play_start_rollback reason={reason} singers={len(self.queue)}")
            try:
                self._request_queue_display_refresh()
                self._schedule_save_data(0)
            except Exception:
                pass

        marker_was_top = False
        if self._is_rotation_mode():
            try:
                marker_was_top = (self._rotation_marker_index() == 0)
            except Exception:
                marker_was_top = False
            # The next rotation is starting: a locked newcomer (or the marked
            # singer) is reaching the top, so the lock has done its job — clear it.
            try:
                if self._is_rotation_locked() and self.queue:
                    top = self.queue[0]
                    if bool(top.get("rotation_lock_new", False)) or marker_was_top:
                        self._rotation_clear_lock(save=True)
            except Exception:
                pass

        singer = None
        attempts_remaining = max(0, len(self.queue))
        while attempts_remaining > 0:
            attempts_remaining -= 1
            singer = self.queue.pop(0)
            if singer.get("skipped", False):
                try:
                    _diag(f"[PLAYNEXT] skipped singer moved to bottom: {singer.get('name', 'Unknown')}")
                except Exception:
                    pass
                self.queue.append(singer)
                if self._is_rotation_locked():
                    self._rotation_reweave_locked_tail()
                continue
            active_songs = singer.get("songs") and any(
                (not song.get("skipped", False)) if isinstance(song, dict) else True
                for song in singer.get("songs", [])
            )
            if active_songs:
                break
            try:
                _diag(f"[PLAYNEXT] placeholder singer kept in rotation and skipped: {singer.get('name', 'Unknown')}")
            except Exception:
                pass
            self.queue.append(singer)
            if self._is_rotation_locked():
                self._rotation_reweave_locked_tail()
            singer = None
        if singer is None:
            QTimer.singleShot(0, self.update_queue_display)
            self._next_in_progress = False
            self._set_play_control_starting(False)
            return

        # Find first NON-SKIPPED valid song (keep skipped songs in the list!).
        entry = None
        song_info = None
        key = 0
        remote_request_id = None
        duet_display = None
        while True:
            first_non_skipped_idx = -1
            for i, song in enumerate(singer.get("songs", [])):
                if isinstance(song, dict):
                    if not song.get("skipped", False):
                        first_non_skipped_idx = i
                        break
                else:
                    # Old tuple format, not skipped
                    first_non_skipped_idx = i
                    break

            # If no non-skipped songs (empty or all skipped), move to bottom and STOP
            if first_non_skipped_idx == -1:
                try:
                    _diag(f"[PLAYNEXT] no playable songs for singer (all skipped/empty): {singer.get('name', 'Unknown')}")
                except Exception:
                    pass
                self.queue.append(singer)
                if self._is_rotation_locked():
                    self._rotation_reweave_locked_tail()
                self.queue = self.queue.copy()
                QTimer.singleShot(0, self.update_queue_display)
                self._next_in_progress = False
                self._set_play_control_starting(False)
                return

            # Pop the first non-skipped song (might be index 0 or later if skipped songs before it)
            entry = singer['songs'].pop(first_non_skipped_idx)
            try:
                remote_request_id = self._queue_entry_remote_request_id(entry)
            except Exception:
                remote_request_id = None

            # Handle both dict and tuple format
            if isinstance(entry, dict):
                self._refresh_queue_entry_metadata(entry)
                song_info = entry.get("song_info")
                key = entry.get("key", 0)
                tempo_percent = entry.get("tempo_percent")
                duet_display = entry.get("duet_display")
            else:
                # Old tuple format
                try:
                    song_info = entry[0]
                    key = entry[1] if len(entry) >= 2 else 0
                    tempo_percent = entry[2] if len(entry) >= 3 and isinstance(entry[2], (int, float)) else None
                    duet_display = entry[3] if len(entry) >= 4 else (entry[2] if len(entry) >= 3 and not isinstance(entry[2], (int, float)) else None)
                except Exception:
                    song_info, key, tempo_percent, duet_display = entry, 0, None, None

            primary_path = self._song_info_primary_path(song_info)
            if self._is_external_karafun_entry(entry):
                self._start_external_karafun_playback(
                    singer=singer,
                    entry=entry,
                    song_info=song_info,
                    key=key,
                    tempo_percent=tempo_percent,
                    duet_display=duet_display,
                    marker_was_top=marker_was_top,
                )
                self._next_in_progress = False
                self._set_play_control_starting(False)
                return
            if primary_path and (not os.path.exists(primary_path)):
                _diag(f"[PLAYNEXT] start rejected: missing file kept in queue: {primary_path}")
                _restore_play_transaction("missing_file")
                try:
                    QMessageBox.warning(self, "Playback Failed", f"The selected track file is missing:\n\n{primary_path}")
                except Exception:
                    pass
                return
            break

        # Keep this song in ETA while it is actively playing.
        current_song_dur = 0
        try:
            if isinstance(entry, dict):
                current_song_dur = int(entry.get("duration") or 0)
            if current_song_dur <= 0:
                dur_path = primary_path or (song_info[0] if isinstance(song_info, (tuple, list)) else song_info)
                current_song_dur = int(self._get_duration_secs(dur_path) or 0)
                # A queue dict may legitimately have no cached duration yet.
                # MP3+G ZIPs are cheap to probe from the MP3 header and need a
                # duration before transport start for the timer/end trim.
                if current_song_dur <= 0 and str(dur_path).lower().endswith(".zip"):
                    current_song_dur = int(self.probe_mp3g_duration(dur_path) or 0)
            if isinstance(entry, dict) and current_song_dur > 0:
                entry["duration"] = current_song_dur
        except Exception:
            current_song_dur = 0

        # Phrase-start has been retired; songs always begin at the file start.
        phrase_start = self._resolve_phrase_start(primary_path, entry, current_song_dur)

        # Retired phrase/intro-loop path.
        intro_loop_seconds = None
        if getattr(self, "_pending_intro_loop", False):
            self._pending_intro_loop = False

        self.video_window.force_black = False
        self.video_window.idle = False
        self.video_window.update()
        self.preview_window.force_black = False
        self.preview_window.update()

        # Apply any per-song remote tempo preset before playback starts.
        if tempo_percent is not None:
            try:
                self._set_karaoke_tempo(int(tempo_percent), apply_live=False)
            except Exception:
                pass

        # Uncached MP3+G ZIPs are preparation, not a successful playback
        # start. Restore the queue before starting the worker, keep Play gated,
        # and re-enter this method from the extraction callback. This prevents
        # extraction errors or repeated clicks from consuming a request.
        if isinstance(song_info, str) and song_info.lower().endswith(".zip"):
            cached_cdg, cached_mp3 = self.zip_cache.cached_paths_if_ready(song_info)
            if not cached_cdg or not cached_mp3:
                _restore_play_transaction("zip_prepare_pending", clear_gate=False)
                self._mp3g_prepare_then_play_next = str(song_info)
                if not self.play_mp3g_zip(
                    song_info,
                    semitones=key,
                    start_seconds=phrase_start,
                    loop_seconds=intro_loop_seconds,
                    duration_seconds=current_song_dur,
                ):
                    self._mp3g_prepare_then_play_next = ""
                    self._next_in_progress = False
                    self._set_play_control_starting(False)
                return

        # Do not add an unseen start gate: the singer animation itself begins
        # only after started is confirmed below. Delaying the transport here
        # would create dead air before that confirmed animation.
        countdown_artist = str(entry.get("artist") or "").strip() if isinstance(entry, dict) else ""
        countdown_title = str(entry.get("title") or "").strip() if isinstance(entry, dict) else ""
        singer_display = duet_display if duet_display else singer.get("name", "")
        start_generation = int(getattr(self, "_singer_start_generation", 0) or 0) + 1
        self._singer_start_generation = start_generation
        self._playback_start_countdown_ms = 0
        self._pending_playback_countdown_payload = {
            "generation": start_generation,
            "singer": str(singer_display or ""),
            "artist": countdown_artist,
            "title": countdown_title,
        }

        # Normalize shapes we might see in the queue
        start_ok = False
        if isinstance(song_info, (tuple, list)):
            # Could be ((cdg, mp3), key) OR (orig_mp4, processed_mp4) from older entries
            if isinstance(song_info[0], str) and song_info[0].endswith(".cdg"):
                cdg_path, mp3_path = song_info
                song_path_display = cdg_path
                start_ok = bool(self.play_cdg_mp3_dual(cdg_path, mp3_path, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds, duration_seconds=current_song_dur))
            elif isinstance(song_info[0], str) and song_info[0].endswith(".mp4"):
                # Old tuple (original, processed) — play original with realtime key change
                orig_mp4 = song_info[0]
                song_path_display = orig_mp4
                start_ok = bool(self.play_mp4(orig_mp4, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds))
            else:
                # Fallback to first element
                song_path_display = str(song_info[0])
                if song_path_display.endswith(".mp4"):
                    start_ok = bool(self.play_mp4(song_path_display, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds))
                elif song_path_display.endswith(".mp3"):
                    start_ok = bool(self.play_mp3(song_path_display, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds))
                else:
                    print("Unsupported tuple format:", song_info)
                    _restore_play_transaction("unsupported_tuple")
                    return
        else:
            # Plain string path
            song_path_display = song_info
            if song_info.endswith(".mp4"):
                start_ok = bool(self.play_mp4(song_info, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds))
            elif song_info.endswith(".mp3"):
                start_ok = bool(self.play_mp3(song_info, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds))
            elif song_info.endswith(".zip"):
                # NEW: Handle MP3G zip files
                if self.is_mp3g_zip(song_info):
                    start_ok = bool(self.play_mp3g_zip(song_info, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds, duration_seconds=current_song_dur))
                else:
                    print("Invalid zip format:", song_info)
                    _restore_play_transaction("invalid_zip")
                    return
            elif song_info.endswith(".cdg"):
                base, _ = os.path.splitext(song_info)
                mp3_path = base + ".mp3"
                if os.path.exists(mp3_path):
                    start_ok = bool(self.play_cdg_mp3_dual(song_info, mp3_path, semitones=key, start_seconds=phrase_start, loop_seconds=intro_loop_seconds, duration_seconds=current_song_dur))
                else:
                    _diag(f"[PLAYNEXT] failed: missing MP3 pair for CDG {song_info}")
                    print("Missing MP3 for CDG:", song_info)
                    _restore_play_transaction("missing_cdg_audio_pair")
                    return
            else:
                _diag(f"[PLAYNEXT] failed: unsupported format {song_info}")
                print("Unsupported format:", song_info)
                _restore_play_transaction("unsupported_format")
                return

        # The transport copied this value before returning acceptance. Do not
        # leak the queue countdown into previews, restarts, or later direct
        # playback calls.
        self._playback_start_countdown_ms = 0
        if not start_ok:
            _restore_play_transaction("transport_rejected_start")
            return

        # Resolve the immutable display payload for the selected entry. Never
        # read the later queue selection when publishing the animation.
        entry_artist = ""
        entry_title = ""
        if isinstance(entry, dict):
            entry_artist = str(entry.get("artist") or "").strip()
            entry_title = str(entry.get("title") or "").strip()
        if entry_artist and entry_title:
            display_name = f"{entry_artist} • {entry_title}"
        else:
            display_name = self.lookup_display_name(song_path_display, artist_title_only=True)
        artist = ""
        title = ""
        if " • " in display_name:
            artist, title = display_name.split(" • ", 1)
            artist = artist.strip()
            title = title.strip()
        else:
            artist = (display_name or "").strip()
        singer_display = duet_display if duet_display else singer.get("name", "")
        singer_id = self._ensure_singer_id(singer)
        request_id = self._ensure_queue_entry_id(entry)

        # start_ok means asynchronous preroll was accepted, not that sound has
        # started. Commit every visible/active identity and rotation mutation
        # only from the transport's real started signal. A preroll failure or
        # Stop during the gate restores the complete queue snapshot and never
        # announces this singer.
        transport_for_start = getattr(self, "karaoke_transport", None)
        play_start_token = object()
        self._pending_play_start_token = play_start_token
        self._pending_play_start_context = {
            "generation": start_generation,
            "singer_id": singer_id,
            "request_id": request_id,
            "payload": {
                "singer": str(singer_display or ""),
                "artist": str(artist or ""),
                "title": str(title or ""),
            },
            "command_source": str(command_source or "internal"),
        }

        def _rollback_pending_start(reason: str):
            if getattr(self, "_pending_play_start_token", None) is not play_start_token:
                return False
            self._pending_play_start_token = None
            self._pending_play_start_rollback = None
            self._pending_play_start_context = None
            if isinstance(getattr(self, "_pending_playback_countdown_payload", None), dict):
                pending_generation = self._pending_playback_countdown_payload.get("generation")
                if pending_generation == start_generation:
                    self._pending_playback_countdown_payload = None
            _restore_play_transaction(reason)
            return True

        def _commit_pending_start():
            if getattr(self, "_pending_play_start_token", None) is not play_start_token:
                _diag(
                    f"[PLAYNEXT] ignored stale started signal generation={start_generation} "
                    f"singer={str(singer_display or '')!r}"
                )
                return
            if getattr(self, "karaoke_transport", None) is not transport_for_start:
                _diag(
                    f"[PLAYNEXT] ignored replaced transport start generation={start_generation} "
                    f"singer={str(singer_display or '')!r}"
                )
                return
            self._pending_play_start_token = None
            self._pending_play_start_rollback = None
            self._pending_playback_countdown_payload = None
            self._pending_play_start_context = None
            self._confirmed_singer_start_generation = start_generation
            self._next_in_progress = False
            self._set_play_control_starting(False)

            # The confirmed item is the single source of truth for all singer
            # presentation and active-playback identity.
            self._eta_hold_current_secs = max(0, int(current_song_dur or 0))
            self._current_karaoke_singer_name = str(singer.get("name", "") or "")
            self._current_karaoke_singer_display = str(singer_display or "")
            self._current_karaoke_singer_id = singer_id
            self._current_karaoke_request_id = request_id
            self._current_karaoke_song_path = str(song_path_display or "")
            self._current_karaoke_artist = str(artist or "")
            self._current_karaoke_title = str(title or "")
            try:
                self._update_last_sung_card()
            except Exception:
                pass
            try:
                self._clear_next_up_overlay_pending("confirmed_playback_start")
                self._hide_next_up_transition_overlay(reason="confirmed_singer_start")
            except Exception:
                pass
            self._set_now_singing_3line(singer_display, artist, title)
            self._trigger_show_screen_singer_start_vfx(
                singer_display,
                artist,
                title,
                generation=start_generation,
            )

            singer["has_sung"] = True
            singer["last_sung_at"] = time.time()
            try:
                self._schedule_waiting_for_add_view_refresh(reason="singer_started")
            except Exception:
                pass
            if self._is_rotation_mode():
                singer["round_sung"] = True
            self.queue.append(singer)
            if self._is_rotation_locked():
                self._rotation_reweave_locked_tail()
            if self._is_rotation_mode():
                if marker_was_top:
                    for queued_singer in self.queue:
                        queued_singer["rotation_marker"] = False
                    singer["rotation_marker"] = True
                self._rotation_repair_marker()
                self._rotation_recompute_round_state(force_reset=False)
            self.queue = self.queue.copy()

            # Do NOT mark the song sung here. Starting a song used to complete
            # the remote request and record the performance immediately, which
            # meant a song changed or removed mid-play still counted as sung --
            # the server then answered re-adds with "You already sang this song
            # tonight" -- and it freed the singer's slot early, letting them
            # queue another before theirs had finished.
            #
            # Stash it instead. _finish_media_end_cleanup commits this on a real
            # media end; stop_playback discards it on a host stop, skip or
            # removal. Duplicate protection is unaffected: the request stays
            # 'active', which already blocks re-adding while it is queued.
            try:
                self._pending_performance = {
                    "remote_request_id": remote_request_id,
                    "singer_name": str(singer.get("name", "") or "") or singer_display,
                    "entry": entry,
                    "song_path": song_path_display,
                    "key": key,
                    "tempo_percent": tempo_percent,
                }
            except Exception:
                self._pending_performance = None
            try:
                self._send_stage_notifications_for_transition(singer_display or singer.get("name", ""))
            except Exception:
                pass
            try:
                _diag(
                    f"[PLAYNEXT] confirmed generation={start_generation} "
                    f"singer={singer.get('name', 'Unknown')!r} song={song_path_display!r}"
                )
            except Exception:
                pass
            self._clear_routine_processing_text_for_playback()
            QTimer.singleShot(0, lambda sid=singer_id: self._select_next_rotation_after_start(sid))

            def _refresh_confirmed_presentation():
                if int(getattr(self, "_confirmed_singer_start_generation", 0) or 0) != start_generation:
                    return
                self._reapply_rotation_presentation(scroll_current=False)

            QTimer.singleShot(50, _refresh_confirmed_presentation)

        self._pending_play_start_rollback = _rollback_pending_start
        if transport_for_start is not None and hasattr(transport_for_start, "started"):
            transport_for_start.started.connect(_commit_pending_start)
        else:
            QTimer.singleShot(0, _commit_pending_start)

    def stop_playback(self, skip_confirmation=False):
        _ia_record(self, "manual_stop", karaoke_playing=bool(getattr(self, "karaoke_playing", False)))
        _ia_observe(self, "end", trigger="manual_stop")
        # A song stopped before it ended was never performed, so it must not be
        # recorded as sung -- otherwise the singer cannot re-add it. On a real
        # media end _finish_media_end_cleanup has already committed it, so this
        # is a no-op there.
        try:
            self._discard_pending_performance(reason="stop_playback")
        except Exception:
            pass
        pending_rollback = getattr(self, "_pending_play_start_rollback", None)
        if callable(pending_rollback):
            try:
                pending_rollback("stopped_before_audible_start")
            except Exception:
                pass
        if isinstance(getattr(self, "_active_external_karafun", None), dict):
            self._finish_external_karafun_playback("return_to_queue")
            return
        self._cancel_pending_karaoke_start_transition()
        self._cancel_pending_media_end_cleanup("stop_playback")
        try:
            self._remember_last_sung_from_current()
        except Exception:
            pass
        # Karaoke stopping — clear flag and refresh BG UI
        self.karaoke_playing = False
        try:
            self._mark_daw_preview_playback_stopped("stop_playback")
        except Exception:
            pass
        try:
            self._update_deferred_remote_add_status()
        except Exception:
            pass
        self._reset_karaoke_tempo_for_track_end()
        self._reset_end_silence_state()
        self._eta_hold_current_secs = 0
        try:
            self.update_queue_display()
        except Exception:
            pass
        try:
            self.clear_now_singing()
        except Exception:
            pass
        try:
            self.update_bg_button_state()
        except Exception:
            pass
        _diag("[STOP] Using async teardown to avoid blocking UI")
        self._reset_karaoke_key_for_track_end()
        self._gst_teardown_async()  # ← CRITICAL FIX: Use async version
        if bool(getattr(self, "_app_closing", False)):
            return
        self._recreate_video_surfaces("stop_playback")
        self._show_idle_background_after_karaoke(reason="stop_playback", advance_slideshow=True)
    def restart_track(self, skip_confirmation=False):
        """Restart the Python karaoke transport from the beginning."""
        if getattr(self, "_stop_in_progress", False):
            _diag("[RESTART] ignored: teardown in progress")
            return
        if getattr(self, "_restart_in_progress", False):
            _diag("[RESTART] ignored: restart already in progress")
            return
        self._restart_in_progress = True
        QTimer.singleShot(800, lambda: setattr(self, "_restart_in_progress", False))

        transport = getattr(self, "karaoke_transport", None)
        if transport is None:
            return

        if not skip_confirmation:
            dlg = ConfirmInterruptDialog(
                self,
                title="Restart Current Song?",
                message=(
                    "A track is currently playing.\n"
                    "Are you sure you want to restart the current song from the beginning?"
                ),
                confirm_text="Restart",
                cancel_text="Cancel",
            )
            if dlg.exec() != QDialog.DialogCode.Accepted:
                return
        try:
            transport.seek(0.0)
            self._apply_karaoke_tempo_live()
        except Exception as e:
            _diag(f"[PY-KARAOKE] restart failed: {e}")

    def _safe_get_volume(self, vol):
        """Return current volume as float, robust to PyGObject differences."""
        try:
            return float(vol.get_property("volume"))
        except Exception:
            try:
                return float(getattr(vol.props, "volume"))
            except Exception:
                return 1.0  # sensible fallback

    def _safe_set_volume(self, vol, value: float):
        """Set volume safely across PyGObject builds."""
        try:
            vol.set_property("volume", float(value))
        except Exception:
            try:
                setattr(vol.props, "volume", float(value))
            except Exception:
                pass

    def _confirm_audio_interrupt(self, *, title: str, message: str) -> bool:
        """Ask before an action that would halt audible karaoke playback.

        Returns True (proceed) immediately when nothing is playing, so the
        prompt only appears when there's actually audio to interrupt. Key/tempo
        changes and seeking deliberately never call this.
        """
        try:
            if not bool(getattr(self, "karaoke_playing", False)):
                return True
        except Exception:
            return True
        try:
            dlg = ConfirmInterruptDialog(
                self, title=title, message=message, confirm_text="Yes", cancel_text="No"
            )
            return dlg.exec() == QDialog.DialogCode.Accepted
        except Exception:
            # Never let a dialog failure block the operator.
            return True

    def stop_and_clear_now_singing(self, skip_confirmation=False):
        """
        Manual Stop (Stop button):
        - Fade karaoke audio out over ~2.0s if it's playing (using the hidden 'karaoke_volume' element)
        - Then teardown pipelines and restore BG music with your normal fade-in
        - NON-BLOCKING on macOS (fire-and-forget pipeline teardown)
        """
        if getattr(self, "_manual_stop_in_progress", False):
            _diag("Manual stop ignored (already in progress)")
            return
        if getattr(self, "_manual_stop_deferred", False):
            _diag("Manual stop ignored (confirmation handoff pending)")
            return
        if not skip_confirmation:
            if not self._confirm_audio_interrupt(
                title="Stop Playback?",
                message=("A track is currently playing.\n"
                         "Stop the current singer and return to background music?"),
            ):
                return
            # A QDialog opened from a menu action runs inside two nested native
            # event loops on macOS. Changing the show/preview paint targets
            # before both loops unwind left Cocoa flushing a dead paint device
            # (the three 07-31 crashes all died in devicePixelRatio()).
            self._manual_stop_deferred = True

            def finish_confirmed_stop():
                self._manual_stop_deferred = False
                self.stop_and_clear_now_singing(skip_confirmation=True)

            QTimer.singleShot(75, finish_confirmed_stop)
            return
        self._manual_stop_in_progress = True
        self._cancel_pending_karaoke_start_transition()
        self._cancel_pending_media_end_cleanup("manual_stop")
        try:
            if hasattr(self, "bg_music") and self.bg_music is not None:
                # Critical for rapid-stop mid fade: kill stale fade-out ticks immediately.
                self.bg_music.cancel_pending_fades(restore_to_target=True)
        except Exception:
            pass
        _diag("Manual stop requested")
        self._log_manual_stop_timeline("press")
        # Immediate visual handoff on manual stop; keep audio fade independent.
        try:
            self._recreate_video_surfaces("manual_stop_press")
            self._show_idle_background_after_karaoke(reason="manual_stop_press", advance_slideshow=True)
            self._detach_video_sinks_now("manual_stop_press")
            self._log_manual_stop_timeline("visual_handoff_done")
        except Exception:
            pass
        QTimer.singleShot(3000, lambda: setattr(self, "_manual_stop_in_progress", False))

        # Start BG crossfade immediately so it rises underneath the karaoke fade-out (3s overlap).
        # allow_during_karaoke=True because karaoke pipeline is still active while this ramps up.
        if (hasattr(self, "bg_music") and self.bg_music.playlist
                and not self.bg_music.is_playing
                and self.settings.get("bg_enabled", True)
                and self.settings.get("bg_autoplay_on_idle", True)):
            try:
                self._bg_resume_reason = "manual_stop"
                self.bg_music.fade_in(None, 3000, allow_during_karaoke=True)
                _diag("Manual stop: started BG crossfade (3s overlap)")
            except Exception as e:
                _diag(f"Manual stop: BG crossfade start failed: {e}")

        # Fade the karaoke audio out before tearing it down, so Stop sounds like
        # the end of a song rather than a cut cable. The visual handoff above
        # has already happened, and the background music is crossfading in
        # underneath, so the fade only governs when the karaoke audio stops.
        transport = getattr(self, "karaoke_transport", None)
        fade_ms = self._manual_stop_fade_ms()
        if transport is not None and hasattr(transport, "fade_out"):
            try:
                if transport.fade_out(fade_ms, on_finished=self._finish_manual_stop_teardown):
                    self._log_manual_stop_timeline("fade_started")
                    return
            except Exception as e:
                _diag(f"[MANUAL-STOP] fade unavailable ({e}); stopping immediately")
        # Nothing to fade (no transport, or it declined): stop immediately.
        self._log_manual_stop_timeline("no_fade_path")
        self._finish_manual_stop_teardown()

    def _manual_stop_fade_ms(self) -> int:
        """How long Stop takes to fade the karaoke audio out."""
        try:
            value = int(self.settings.get("manual_stop_fade_ms", 2000) or 2000)
        except Exception:
            value = 2000
        # 0 restores the old instant cut; the cap keeps Stop responsive and
        # stays inside the 3s _manual_stop_in_progress guard.
        return max(0, min(2800, value))

    def _finish_manual_stop_teardown(self):
        self._log_manual_stop_timeline("teardown")
        pending_rollback = getattr(self, "_pending_play_start_rollback", None)
        if callable(pending_rollback):
            try:
                pending_rollback("manual_stop_before_start_commit")
            except Exception:
                pass
        self._next_in_progress = False
        self._set_play_control_starting(False)
        self._gst_teardown_async()  # ← Use the non-blocking version
        self.clear_now_singing()
        
        # Update UI immediately
        self._show_idle_background_after_karaoke(reason="manual_stop_immediate", advance_slideshow=False)
        
        # Mark as not playing
        self.karaoke_playing = False
        try:
            self._mark_daw_preview_playback_stopped("manual_stop_immediate")
        except Exception:
            pass
        self._reset_karaoke_tempo_for_track_end()
        self._reset_end_silence_state()
        self._eta_hold_current_secs = 0
        try:
            self.update_queue_display()
        except Exception:
            pass
        try:
            self.update_bg_button_state()
        except Exception:
            pass
        
        if hasattr(self, 'bg_music') and self.bg_music.playlist:
            if self.bg_music.is_playing:
                _diag("BG already playing after manual stop; verifying audibility")
                try:
                    self.bg_music.ensure_audible("manual_stop")
                except Exception:
                    pass
            else:
                _diag("Restarting background music after manual stop.")
                self._schedule_bg_resume(100, reason="manual_stop")
        else:
            _diag("Cannot restart background music after manual stop (no playlist/bg)")
            self._force_bg_resume_recovery()
        self._manual_stop_in_progress = False

    def _log_manual_stop_timeline(self, stage: str):
        """One-shot timing trace for manual stop path: press -> visual handoff -> fade -> teardown."""
        try:
            now = time.monotonic()
            if stage == "press":
                self._manual_stop_t0 = now

            t0 = float(getattr(self, "_manual_stop_t0", now))
            # Stale anchor guard: prevents unrelated later teardowns from reporting huge ms values.
            if stage != "press" and (now - t0) > 15.0:
                t0 = now
                self._manual_stop_t0 = now

            ms = int((now - t0) * 1000.0)
            _diag(f"[MANUAL-STOP] stage={stage} t+{ms}ms")

            # Expire timeline anchor after terminal stages.
            if stage in ("teardown_complete", "no_fade_path") and hasattr(self, "_manual_stop_t0"):
                delattr(self, "_manual_stop_t0")
        except Exception:
            pass

    def _force_bg_resume_recovery(self):
        """Fallback recovery for manual-stop race where BG state becomes inconsistent."""
        try:
            if not hasattr(self, "bg_music") or not self.bg_music.playlist:
                return
            try:
                self.bg_music.stop()
            except Exception:
                pass
            try:
                self.bg_music.preload_current_track_paused()
            except Exception:
                pass
            _diag("[BG] Manual-stop recovery forcing BG resume")
            self._schedule_bg_resume(120, reason="manual_stop")
        except Exception as e:
            _diag(f"[BG] Manual-stop recovery failed: {e}")
    
    def play_mp4(self, song_path, semitones=0, start_seconds=0.0, loop_seconds=None):
        return self._play_mp4(song_path, semitones, start_seconds=start_seconds, loop_seconds=loop_seconds)


    def play_cdg_mp3_dual(self, cdg_path, mp3_path, semitones=0, start_seconds=0.0, fast_restart=False, loop_seconds=None, duration_seconds=None):
        return self._play_cdg(
            cdg_path,
            mp3_path,
            semitones,
            start_seconds=start_seconds,
            loop_seconds=loop_seconds,
            duration_seconds=duration_seconds,
        )


    def on_media_ended(self, event=None):
            from PyQt6.QtCore import QTimer
            QTimer.singleShot(0, self._handle_media_end_safe)
                
    def play_mp3(self, song_path, semitones=0, start_seconds=0.0, loop_seconds=None):
        return self._play_mp3(song_path, semitones, start_seconds=start_seconds, loop_seconds=loop_seconds)


    def get_singer_index_by_row(self, row):
        counter = 0
        for i, singer in enumerate(self.queue):
            if counter == row:
                return i
            counter += 1 + len(singer["songs"])
        return -1

    def get_song_index_by_row(self, row):
        counter = 0
        for i, singer in enumerate(self.queue):
            if counter == row:
                return i, -1
            counter += 1
            for j, _ in enumerate(singer["songs"]):
                if counter == row:
                    return i, j
                counter += 1
        return -1, -1

    def get_block_size(self, singer):
        return 1 + len(singer["songs"])

    def _queue_entry_remote_request_id(self, entry):
        try:
            if isinstance(entry, dict) and entry.get("remote_request_id") is not None:
                return int(entry.get("remote_request_id"))
        except Exception:
            pass
        return None

    def _coerce_order_timestamp(self, value) -> int:
        try:
            if value is None or value == "":
                return 0
            raw = float(value)
            if raw <= 0:
                return 0
            # Server fields are milliseconds. Accept seconds from older callers.
            if raw < 100000000000:
                raw *= 1000.0
            return int(raw)
        except Exception:
            return 0

    def _remote_order_now_ms(self, singer: dict | None = None) -> int:
        now = int(time.time() * 1000)
        try:
            if isinstance(singer, dict):
                prev = max(
                    self._coerce_order_timestamp(singer.get("host_order_updated_at")),
                    self._coerce_order_timestamp(singer.get("singer_order_updated_at")),
                )
                if now <= prev:
                    now = prev + 1
        except Exception:
            pass
        return now

    def _singer_remote_order_ids(self, singer: dict | None) -> list[int]:
        request_ids = []
        try:
            for entry in (singer or {}).get("songs", []) or []:
                remote_id = self._queue_entry_remote_request_id(entry)
                if remote_id is not None:
                    request_ids.append(int(remote_id))
        except Exception:
            pass
        return request_ids

    def _record_host_singer_order_change(self, singer_idx: int, *, reason: str = "host_order_change", request_ids: list[int] | None = None) -> tuple[list[int], int, int]:
        try:
            singer = self.queue[int(singer_idx)]
        except Exception:
            return [], 0, 0
        if not isinstance(singer, dict):
            return [], 0, 0
        if request_ids is None:
            request_ids = self._singer_remote_order_ids(singer)
        try:
            self._queue_revision = int(getattr(self, "_queue_revision", 0) or 0) + 1
        except Exception:
            self._queue_revision = 1
        revision = int(getattr(self, "_queue_revision", 0) or 0)
        stamp = self._remote_order_now_ms(singer)
        singer["host_order_updated_at"] = stamp
        singer["order_revision"] = revision
        singer["last_order_source"] = "host"
        singer.setdefault("singer_order_updated_at", 0)
        singer_key = str(singer.get("name", "") or "").strip().lower()
        if singer_key and request_ids:
            try:
                if not hasattr(self, "_pending_remote_order_syncs") or not isinstance(self._pending_remote_order_syncs, dict):
                    self._pending_remote_order_syncs = {}
                self._pending_remote_order_syncs[singer_key] = {
                    "request_ids": list(request_ids),
                    "host_order_updated_at": stamp,
                    "order_revision": revision,
                    "last_order_source": "host",
                    "reason": reason,
                }
            except Exception:
                pass
        _diag(
            "[ORDER-CONFLICT] singer="
            f"{singer.get('name','')!r} old_order={request_ids} incoming_order=[] local_order={request_ids} "
            f"source=host local_revision={revision} incoming_revision=0 "
            f"local_ts={stamp} incoming_ts=0 decision=recorded reason={reason}"
        )
        return list(request_ids), stamp, revision

    def _remote_order_meta_from_req(self, req: dict) -> dict:
        if not isinstance(req, dict):
            return {"host_order_updated_at": 0, "singer_order_updated_at": 0, "order_revision": 0, "last_order_source": "server"}
        # Do not use the generic request "source" field here: values such as
        # "phone", "kiosk", or "singer" describe who submitted the request, not
        # who explicitly reordered an existing singer queue.
        source = str(req.get("last_order_source") or req.get("order_source") or "server").strip().lower()
        if source not in {"host", "singer", "server"}:
            source = "server"
        try:
            revision = int(req.get("order_revision") or req.get("revision") or 0)
        except Exception:
            revision = 0
        return {
            "host_order_updated_at": self._coerce_order_timestamp(req.get("host_order_updated_at")),
            "singer_order_updated_at": self._coerce_order_timestamp(req.get("singer_order_updated_at")),
            "order_revision": revision,
            "last_order_source": source,
        }

    def _merge_remote_order_meta(self, current: dict | None, incoming: dict) -> dict:
        merged = dict(current or {})
        incoming = incoming or {}
        host_ts = max(int(merged.get("host_order_updated_at") or 0), int(incoming.get("host_order_updated_at") or 0))
        singer_ts = max(int(merged.get("singer_order_updated_at") or 0), int(incoming.get("singer_order_updated_at") or 0))
        revision = max(int(merged.get("order_revision") or 0), int(incoming.get("order_revision") or 0))
        source = str(incoming.get("last_order_source") or merged.get("last_order_source") or "server").strip().lower()
        if source not in {"host", "singer", "server"}:
            source = "server"
        merged.update({
            "host_order_updated_at": host_ts,
            "singer_order_updated_at": singer_ts,
            "order_revision": revision,
            "last_order_source": source,
        })
        return merged

    def _incoming_order_timestamp(self, meta: dict | None) -> int:
        meta = meta or {}
        source = str(meta.get("last_order_source") or "server").strip().lower()
        host_ts = int(meta.get("host_order_updated_at") or 0)
        singer_ts = int(meta.get("singer_order_updated_at") or 0)
        if source == "singer":
            return singer_ts
        if source == "host":
            return host_ts
        return max(host_ts, singer_ts)

    def _apply_order_meta_to_singer(self, singer: dict, meta: dict | None) -> None:
        if not isinstance(singer, dict) or not isinstance(meta, dict):
            return
        host_ts = int(meta.get("host_order_updated_at") or 0)
        singer_ts = int(meta.get("singer_order_updated_at") or 0)
        revision = int(meta.get("order_revision") or 0)
        if host_ts:
            singer["host_order_updated_at"] = max(self._coerce_order_timestamp(singer.get("host_order_updated_at")), host_ts)
        if singer_ts:
            singer["singer_order_updated_at"] = max(self._coerce_order_timestamp(singer.get("singer_order_updated_at")), singer_ts)
        if revision:
            singer["order_revision"] = max(int(singer.get("order_revision") or 0), revision)
        source = str(meta.get("last_order_source") or "").strip().lower()
        if source in {"host", "singer", "server"} and (host_ts or singer_ts or revision):
            singer["last_order_source"] = source

    def _load_remote_request_tombstones(self) -> dict:
        try:
            if not REMOTE_REQUEST_TOMBSTONES_PATH.exists():
                return {"requests": {}, "generated_at": int(time.time()), "version": 1}
            with open(REMOTE_REQUEST_TOMBSTONES_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                return {"requests": {}, "generated_at": int(time.time()), "version": 1}
            requests_map = data.get("requests")
            if not isinstance(requests_map, dict):
                requests_map = {}
            data["requests"] = requests_map
            data.setdefault("version", 1)
            return data
        except Exception as e:
            _diag(f"[REMOTE-TOMBSTONE] load failed: {e}")
            return {"requests": {}, "generated_at": int(time.time()), "version": 1}

    def _save_remote_request_tombstones(self, payload: dict | None = None) -> None:
        try:
            data = payload if isinstance(payload, dict) else getattr(self, "_remote_request_tombstones", None)
            if not isinstance(data, dict):
                data = {"requests": {}, "generated_at": int(time.time()), "version": 1}
            data["generated_at"] = int(time.time())
            with open(REMOTE_REQUEST_TOMBSTONES_PATH, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, sort_keys=True)
        except Exception as e:
            _diag(f"[REMOTE-TOMBSTONE] save failed: {e}")

    def _ensure_remote_request_tombstones(self) -> dict:
        try:
            data = self.__dict__.get("_remote_request_tombstones")
        except Exception:
            data = None
        if not isinstance(data, dict):
            data = self._load_remote_request_tombstones()
            self._remote_request_tombstones = data
        data.setdefault("requests", {})
        self._prune_remote_request_tombstones(data)
        return data

    def _prune_remote_request_tombstones(self, data: dict | None = None) -> None:
        if not isinstance(data, dict):
            try:
                data = self.__dict__.get("_remote_request_tombstones")
            except Exception:
                data = None
        if not isinstance(data, dict):
            return
        items = data.setdefault("requests", {})
        if not isinstance(items, dict):
            data["requests"] = {}
            return
        now = time.time()
        ttl = 48 * 3600
        changed = False
        for key, tombstone in list(items.items()):
            try:
                removed_at = float((tombstone or {}).get("removed_at") or 0)
            except Exception:
                removed_at = 0
            # Never discard an unconfirmed terminal transition. It is the
            # durable retry record used after a disconnect or app restart.
            if removed_at and (tombstone or {}).get("server_synced_at") and now - removed_at > ttl:
                items.pop(key, None)
                changed = True
        if changed:
            self._save_remote_request_tombstones(data)

    def _queue_entry_artist_title_for_tombstone(self, entry) -> tuple[str, str]:
        if isinstance(entry, dict):
            artist = str(entry.get("artist") or "").strip()
            title = str(entry.get("title") or "").strip()
            if artist or title:
                return artist, title
            display = str(entry.get("display_name") or "").strip()
            if "•" in display:
                left, right = display.split("•", 1)
                return left.strip(), right.strip()
            if "-" in display:
                left, right = display.split("-", 1)
                return left.strip(), right.strip()
        return "", ""

    def _record_remote_request_tombstone(self, request_id: int, *, entry=None, singer_name: str = "", reason: str = "host_remove", status: str = "removed") -> dict | None:
        try:
            request_id = int(request_id or 0)
        except Exception:
            request_id = 0
        if request_id <= 0:
            return None
        data = self._ensure_remote_request_tombstones()
        existing = (data.get("requests") or {}).get(str(request_id)) if isinstance(data, dict) else None
        if isinstance(existing, dict):
            try:
                removed = getattr(self, "_remote_removed_request_ids", None)
                if not isinstance(removed, set):
                    removed = set()
                    self._remote_removed_request_ids = removed
                removed.add(request_id)
            except Exception:
                pass
            try:
                last_log = getattr(self, "_remote_tombstone_duplicate_log_ts", {})
                if not isinstance(last_log, dict):
                    last_log = {}
                    self._remote_tombstone_duplicate_log_ts = last_log
                now_log = time.time()
                prev = float(last_log.get(request_id, 0.0) or 0.0)
                if now_log - prev > 30.0:
                    _diag(f"[REMOTE-TOMBSTONE] duplicate create ignored request_id={request_id} reason={reason}")
                    last_log[request_id] = now_log
            except Exception:
                pass
            return existing
        artist, title = self._queue_entry_artist_title_for_tombstone(entry)
        singer_name = str(singer_name or "").strip()
        try:
            self._queue_revision = int(getattr(self, "_queue_revision", 0)) + 1
        except Exception:
            self._queue_revision = 1
        now = time.time()
        status = str(status or "removed").strip().lower()
        if status not in {"removed", "completed", "sung"}:
            status = "removed"
        tombstone = {
            "request_id": request_id,
            "singer_name": singer_name,
            "artist": artist,
            "title": title,
            "song_key": remote_request_song_key(singer_name, artist, title),
            "removed_at": now,
            "removed_by": "host",
            "removal_reason": str(reason or "host_remove"),
            "local_revision": int(getattr(self, "_queue_revision", 0) or 0),
            "server_synced_at": None,
            "sync_attempts": 0,
            "last_sync_attempt_at": None,
            "last_sync_error": "",
            "status": status,
        }
        data.setdefault("requests", {})[str(request_id)] = tombstone
        self._save_remote_request_tombstones(data)
        try:
            removed = getattr(self, "_remote_removed_request_ids", None)
            if not isinstance(removed, set):
                removed = set()
                self._remote_removed_request_ids = removed
            removed.add(request_id)
        except Exception:
            pass
        _diag(
            "[REMOTE-TOMBSTONE] created "
            f"request_id={request_id} singer={singer_name!r} title={title!r} "
            f"artist={artist!r} reason={reason} revision={tombstone['local_revision']} "
            f"status={status} accepting_requests={int(self._is_requests_accepting_cached())}"
        )
        return tombstone

    def _remote_request_matches_tombstone(self, req: dict) -> dict | None:
        if not isinstance(req, dict):
            return None
        data = self._ensure_remote_request_tombstones()
        items = data.get("requests") if isinstance(data, dict) else {}
        if not isinstance(items, dict):
            return None
        try:
            rid = int(req.get("request_id", 0) or 0)
        except Exception:
            rid = 0
        song_key = remote_request_song_key(req.get("singer", ""), req.get("artist", ""), req.get("title", ""))
        if rid > 0:
            # Pure lookup by id: whether a signature mismatch means the id was
            # truly reused (vs normal metadata drift) is the CALLER's decision
            # via _tombstone_signature_conflicts(). This used to pop the
            # tombstone on any song_key difference, but the tombstone key is
            # built from library-canonical queue metadata and the primary
            # singer, while server rows carry the singer's typed artist/title
            # and duet display ("Dan & Amy") — routine drift was destroying
            # tombstones and letting stale rows resurrect host-removed songs.
            tombstone = items.get(str(rid))
            return tombstone if isinstance(tombstone, dict) else None
        if not song_key or song_key == "||":
            return None
        for tombstone in items.values():
            if isinstance(tombstone, dict) and tombstone.get("song_key") == song_key:
                return tombstone
        return None

    @staticmethod
    def _tombstone_signature_conflicts(tombstone, req) -> bool:
        """True only when the server row is clearly a DIFFERENT song than the
        one the host removed — the only legitimate way a request id can come
        back to life (a server-side wipe reset the id counter and the id was
        handed to a brand-new request).

        Anything less than a clear title conflict keeps the tombstone: request
        rows carry the singer's typed artist/title and duet display while the
        queue stores library metadata and the primary singer, so formatting
        drift is normal and must never resurrect a host-removed song. The
        newest authoritative host action wins over incomplete/older data."""

        def norm(value) -> str:
            # squash everything to lowercase alphanumerics so spacing and
            # punctuation drift ("Rocket Man" vs "Rocketman") can't conflict
            return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())

        t_title = norm((tombstone or {}).get("title"))
        r_title = norm((req or {}).get("title"))
        if not t_title or not r_title:
            return False  # incomplete data — host removal stands
        if t_title == r_title or t_title in r_title or r_title in t_title:
            return False  # same song modulo formatting drift
        return True

    def _drop_remote_request_tombstone(self, request_id: int, *, reason: str = "") -> None:
        """Retire a tombstone (confirmed id reuse after a server reset)."""
        try:
            data = self._ensure_remote_request_tombstones()
            if (data.get("requests") or {}).pop(str(int(request_id)), None) is not None:
                self._save_remote_request_tombstones(data)
                _diag(f"[REMOTE-TOMBSTONE] retired request_id={request_id} reason={reason}")
        except Exception:
            pass

    def _queue_entry_dup_signature(self, entry):
        """Signature for accidental-duplicate detection within ONE singer:
        normalized artist + title + karaoke version (disc id, else the actual
        library file). None when there isn't enough data to compare safely.
        Never used across singers — other singers' copies are unrelated."""
        if not isinstance(entry, dict):
            return None
        artist, title = self._queue_entry_artist_title_for_tombstone(entry)
        if not str(title or "").strip():
            return None

        def norm(value) -> str:
            return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()

        version = str(
            entry.get("provider_track_id")
            or entry.get("selected_disc_id")
            or entry.get("disc_id")
            or entry.get("selected_version")
            or ""
        ).strip()
        provider = str(entry.get("provider") or "local").strip().lower()
        if provider and provider != "local" and version:
            version = f"{provider}:{version}"
        if not version:
            try:
                version = str(self._song_info_primary_path(entry.get("song_info")) or "")
            except Exception:
                version = ""
        return (norm(artist), norm(title), norm(version))

    def _cleanup_duplicate_singer_songs(self, *, reason: str = "") -> int:
        """Collapse only entries that share the same immutable request ID.

        Artist/title/version are never identities: a singer may intentionally
        request the same song/version more than once. Legacy entries without a
        permanent ID are preserved rather than guessed away.
        """
        removed = 0
        for singer in self.queue or []:
            if not isinstance(singer, dict):
                continue
            songs = singer.get("songs") or []
            if len(songs) < 2:
                continue
            survivors_by_identity = {}
            drop_indices = []
            for idx, entry in enumerate(songs):
                if not isinstance(entry, dict) or entry.get("skipped", False):
                    continue
                identity = self._queue_entry_identity_key(entry)
                if identity is None:
                    continue
                survivor = survivors_by_identity.get(identity)
                if survivor is None:
                    survivors_by_identity[identity] = entry
                    continue
                rid_survivor = self._queue_entry_remote_request_id(survivor)
                rid_dup = self._queue_entry_remote_request_id(entry)
                drop_indices.append(idx)
                removed += 1
                _diag(
                    "[QUEUE-AUDIT] action=dedup_same_request_id "
                    f"singer={singer.get('name', '')!r} title={entry.get('title', '')!r} "
                    f"identity={identity!r} request_id={rid_dup} kept_request_id={rid_survivor} "
                    f"reason={reason}"
                )
            for idx in reversed(drop_indices):
                songs.pop(idx)
        if removed:
            try:
                self._request_queue_display_refresh()
            except Exception:
                pass
            try:
                self._schedule_save_data(500)
            except Exception:
                pass
        return removed

    def _queue_entry_identity_key(self, entry) -> tuple | None:
        """Permanent queue-entry identity; never derived from display metadata."""
        if not isinstance(entry, dict):
            return None
        remote_id = self._queue_entry_remote_request_id(entry)
        if remote_id is not None:
            return ("remote", int(remote_id))
        request_uid = str(entry.get("request_uid") or "").strip()
        if request_uid:
            return ("local", request_uid)
        return None

    def _find_existing_duplicate_song_entry(self, singer_name: str, entry: dict) -> tuple[int, int, dict] | None:
        if not isinstance(entry, dict):
            return None
        identity = self._queue_entry_identity_key(entry)
        if identity is None:
            return None
        for singer_idx, singer in enumerate(self.queue or []):
            if not isinstance(singer, dict):
                continue
            for song_idx, existing in enumerate(singer.get("songs", []) or []):
                if not isinstance(existing, dict) or bool(existing.get("skipped", False)):
                    continue
                if self._queue_entry_identity_key(existing) == identity:
                    return singer_idx, song_idx, existing
        return None

    def _remote_request_mark_already_absent(self, resp) -> bool:
        try:
            status_code = int(getattr(resp, "status_code", 0) or 0)
        except Exception:
            status_code = 0
        if status_code not in {404, 410}:
            return False
        text = str(getattr(resp, "text", "") or "").lower()
        if "request_not_found" in text or "not found" in text:
            return True
        try:
            payload = resp.json()
        except Exception:
            payload = None
        if isinstance(payload, dict):
            error = str(payload.get("error") or payload.get("message") or "").lower()
            return "request_not_found" in error or "not found" in error
        return False

    def _remote_tombstone_retry_due(self, tombstone: dict, *, now: float | None = None) -> bool:
        """Bound terminal retries while still guaranteeing eventual recovery.

        The network watchdog runs every two seconds. Without a per-record due
        time, every offline tombstone was posted on every tick; six records
        generated almost two thousand failed requests during one short outage.
        New terminal actions still send immediately via ``force=True``.
        """
        if not isinstance(tombstone, dict) or tombstone.get("server_synced_at"):
            return False
        try:
            attempts = max(0, int(tombstone.get("sync_attempts") or 0))
            last_attempt = float(tombstone.get("last_sync_attempt_at") or 0.0)
        except Exception:
            return True
        if attempts <= 0 or last_attempt <= 0:
            return True
        delays = tuple(float(value) for value in self.TERMINAL_RETRY_DELAYS_SEC)
        delay = delays[min(attempts - 1, len(delays) - 1)]
        return float(time.time() if now is None else now) >= last_attempt + delay

    def _sync_remote_removal_tombstones_async(self, reason: str = "manual", *, force: bool = False) -> None:
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        if not base_url or not tenant or not api_key:
            return
        import threading
        state = object.__getattribute__(self, "__dict__")
        try:
            lock = state.get("_remote_tombstone_sync_lock")
            if lock is None:
                lock = threading.Lock()
                state["_remote_tombstone_sync_lock"] = lock
            with lock:
                now = time.time()
                if not force and now - float(state.get("_remote_tombstone_sync_last_ts", 0.0) or 0.0) < 2.0:
                    return
                if bool(state.get("_remote_tombstone_sync_active", False)):
                    return
                state["_remote_tombstone_sync_active"] = True
        except Exception:
            if bool(state.get("_remote_tombstone_sync_active", False)):
                return
            state["_remote_tombstone_sync_active"] = True
        data = self._ensure_remote_request_tombstones()
        now = time.time()
        pending = [
            dict(item)
            for item in (data.get("requests") or {}).values()
            if isinstance(item, dict)
            and item.get("request_id")
            and not item.get("server_synced_at")
            and (force or self._remote_tombstone_retry_due(item, now=now))
        ]
        if not pending:
            try:
                self._remote_tombstone_sync_active = False
            except Exception:
                pass
            return
        state["_remote_tombstone_sync_last_ts"] = now


        def send():
            headers = {"X-API-Key": api_key, "Accept": "application/json", "User-Agent": "SingWS/removal-sync"}
            synced = []
            failures = {}
            try:
                for tombstone in pending:
                    rid = int(tombstone.get("request_id") or 0)
                    attempt = int(tombstone.get("sync_attempts") or 0) + 1
                    state_name = str(tombstone.get("status") or "removed").strip().lower()
                    if state_name not in {"removed", "completed", "sung"}:
                        state_name = "removed"
                    payload = {
                        "user": tenant,
                        "request_id": rid,
                        "state": state_name,
                        "status": state_name,
                        "singer_name": tombstone.get("singer_name", ""),
                        "artist": tombstone.get("artist", ""),
                        "title": tombstone.get("title", ""),
                        "removed_at": int(float(tombstone.get("removed_at") or time.time())),
                        "completed_at": int(float(tombstone.get("removed_at") or time.time())),
                        "removed_by": tombstone.get("removed_by", "host"),
                        "removal_reason": tombstone.get("removal_reason", reason),
                        "local_revision": tombstone.get("local_revision", ""),
                    }
                    _diag(
                        "[REMOTE-TOMBSTONE] push "
                        f"request_id={rid} state={state_name} attempt={attempt} reason={reason} "
                        f"accepting_requests={int(self._is_requests_accepting_cached())} "
                        f"sync_connected=1 url={base_url}/api/v1/complete_remote_request.php"
                    )
                    try:
                        resp = requests.post(
                            f"{base_url}/api/v1/complete_remote_request.php",
                            data=payload,
                            headers=headers,
                            timeout=6,
                        )
                    except Exception as exc:
                        failures[rid] = str(exc)
                        _diag(
                            f"[REQUEST-LIFECYCLE] terminal push failed request_id={rid} "
                            f"state={state_name} attempt={attempt} error={exc!r}"
                        )
                        continue
                    try:
                        body = resp.json()
                    except Exception:
                        body = None
                    identity_matches = (
                        isinstance(body, dict)
                        and int(body.get("request_id") or 0) == rid
                        and str(body.get("state") or "").strip().lower() == state_name
                    )
                    acknowledged = (
                        200 <= resp.status_code < 300
                        and identity_matches
                        and bool(body.get("ok"))
                    )
                    # The server may answer idempotent=true for a row that is
                    # ALREADY in the requested terminal state even when its
                    # okjweb twin could not be cross-confirmed (pre-alignment
                    # rows have unlinkable ids). There is nothing left to sync;
                    # retrying forever just spams the log (370+ attempts seen
                    # live 2026-07-20).
                    if not acknowledged and identity_matches and bool(body.get("idempotent")):
                        acknowledged = True
                        _diag(
                            f"[REMOTE-TOMBSTONE] idempotent terminal state accepted "
                            f"request_id={rid} state={state_name} status={resp.status_code} "
                            f"okj_confirmed={int(bool(body.get('okj_confirmed')))}"
                        )
                    if acknowledged:
                        synced.append(rid)
                        _diag(
                            f"[REQUEST-LIFECYCLE] server confirmed terminal state "
                            f"request_id={rid} state={state_name} attempt={attempt} status={resp.status_code}"
                        )
                    elif self._remote_request_mark_already_absent(resp):
                        synced.append(rid)
                        _diag(f"[REMOTE-TOMBSTONE] server already absent request_id={rid} status={resp.status_code}; marking synced")
                    else:
                        error = (
                            str((body or {}).get("error") or (body or {}).get("message") or "")
                            if isinstance(body, dict) else ""
                        ) or f"unconfirmed HTTP {resp.status_code}"
                        failures[rid] = error
                        _diag(
                            f"[REQUEST-LIFECYCLE] terminal acknowledgement rejected request_id={rid} "
                            f"state={state_name} attempt={attempt} status={resp.status_code} "
                            f"error={error!r} body={(resp.text or '')[:180]!r}"
                        )
            except Exception as e:
                _diag(f"[REMOTE-TOMBSTONE] sync failed reason={reason}: {e}")
            finally:
                try:
                    if synced or failures:
                        latest = self._ensure_remote_request_tombstones()
                        changed = False
                        now_done = time.time()
                        for rid in set(synced) | set(failures):
                            item = latest.get("requests", {}).get(str(rid))
                            if not isinstance(item, dict):
                                continue
                            item["sync_attempts"] = int(item.get("sync_attempts") or 0) + 1
                            item["last_sync_attempt_at"] = now_done
                            if rid in synced:
                                item["server_synced_at"] = now_done
                                item["last_sync_error"] = ""
                            else:
                                item["last_sync_error"] = str(failures.get(rid) or "sync_failed")[:240]
                            changed = True
                        if changed:
                            self._save_remote_request_tombstones(latest)
                finally:
                    try:
                        self._remote_tombstone_sync_active = False
                    except Exception:
                        pass

        threading.Thread(target=send, daemon=True).start()

    def _complete_remote_request(self, request_id: int, *, entry=None, singer_name: str = "", reason: str = "song_completed"):
        try:
            request_id = int(request_id or 0)
        except Exception:
            return
        if request_id <= 0:
            return
        tombstone = self._record_remote_request_tombstone(
            request_id,
            entry=entry,
            singer_name=singer_name,
            reason=reason,
            status="completed",
        )
        try:
            removed = getattr(self, "_remote_removed_request_ids", None)
            if not isinstance(removed, set):
                removed = set()
                self._remote_removed_request_ids = removed
            removed.add(request_id)
        except Exception:
            pass

        if not self.is_network_configured() or not str(self.settings.get("api_key", "") or "").strip():
            _diag(f"[REMOTE-COMPLETE] queued unsynced request_id={request_id} reason=network_not_configured")
            return
        _diag(
            f"[REQUEST-LIFECYCLE] completion queued request_id={request_id} "
            f"reason={reason} durable=1"
        )
        self._sync_remote_removal_tombstones_async("song_completion", force=True)

    def _delete_remote_request(self, request_id: int, *, entry=None, singer_name: str = "", reason: str = "host_remove"):
        try:
            request_id = int(request_id or 0)
        except Exception:
            return
        if request_id <= 0:
            return
        tombstone = self._record_remote_request_tombstone(request_id, entry=entry, singer_name=singer_name, reason=reason)
        try:
            removed = getattr(self, "_remote_removed_request_ids", None)
            if not isinstance(removed, set):
                removed = set()
                self._remote_removed_request_ids = removed
            removed.add(request_id)
        except Exception:
            pass
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        if not base_url or not tenant or not api_key:
            _diag(f"[REMOTE-TOMBSTONE] queued unsynced request_id={request_id} reason=network_not_configured")
            return

        import threading

        def send():
            headers = {"X-API-Key": api_key, "Accept": "application/json", "User-Agent": "SingWS/remove-request"}
            try:
                # First mark the request non-pending. This prevents the next
                # sync poll from resurrecting a remotely-added song while the
                # cleanup/delete request is still in flight.
                mark = requests.post(
                    f"{base_url}/api/v1/complete_remote_request.php",
                    data={
                        "user": tenant,
                        "request_id": request_id,
                        "state": "removed",
                        "status": "removed",
                        "singer_name": singer_name,
                        "artist": (tombstone or {}).get("artist", ""),
                        "title": (tombstone or {}).get("title", ""),
                        "removed_at": int(float((tombstone or {}).get("removed_at") or time.time())),
                        "removed_by": "host",
                        "removal_reason": reason,
                        "local_revision": (tombstone or {}).get("local_revision", ""),
                    },
                    headers=headers,
                    timeout=5,
                )
                if 200 <= mark.status_code < 300 or self._remote_request_mark_already_absent(mark):
                    latest = self._ensure_remote_request_tombstones()
                    item = latest.get("requests", {}).get(str(request_id))
                    if isinstance(item, dict):
                        item["server_synced_at"] = time.time()
                        self._save_remote_request_tombstones(latest)
                    _diag(f"[REMOTE-TOMBSTONE] server acknowledged removal request_id={request_id} status={mark.status_code}")
                else:
                    print(f"[REMOTE-DELETE] mark removed HTTP {mark.status_code}: {mark.text[:160]}")
            except Exception as e:
                print(f"[REMOTE-DELETE] Failed to mark request {request_id} removed: {e}")
            try:
                requests.post(
                    f"{base_url}/api/v1/delete_remote_request.php",
                    data={
                        "user": tenant,
                        "request_id": request_id,
                        "removed_by": "host",
                        "removal_reason": reason,
                        "local_revision": (tombstone or {}).get("local_revision", ""),
                    },
                    headers=headers,
                    timeout=5,
                )
            except Exception as e:
                print(f"[REMOTE-DELETE] Failed to delete request {request_id}: {e}")

        threading.Thread(target=send, daemon=True).start()

    def _push_remote_request_modifiers(self, entry):
        """Host-wins: when the operator changes a song's key/tempo, push it to the
        server so the website reflects the host value instead of overwriting it.
        No-op for locally-added songs (no remote_request_id)."""
        request_id = self._queue_entry_remote_request_id(entry)
        if request_id is None:
            return
        try:
            song_key = int(entry.get("key") or 0)
        except Exception:
            song_key = 0
        try:
            tempo_offset = int((entry.get("tempo_percent") or 100)) - 100
        except Exception:
            tempo_offset = 0

        # Remember the host's value so an in-flight sync poll doesn't momentarily
        # revert the row before the server reflects the change (see reconcile).
        try:
            pending = getattr(self, "_pending_remote_modifier_pushes", None)
            if not isinstance(pending, dict):
                pending = {}
                self._pending_remote_modifier_pushes = pending
            pending[int(request_id)] = {
                "key": song_key,
                "tempo": tempo_offset,
                "expires_at": time.time() + 20.0,
            }
        except Exception:
            pass

        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        if not base_url or not tenant or not api_key:
            _diag(f"[REMOTE-MODIFIER] queued unsynced request_id={request_id} reason=network_not_configured")
            return

        import threading

        def send():
            headers = {"X-API-Key": api_key, "Accept": "application/json", "User-Agent": "SingWS/set-modifiers"}
            try:
                resp = requests.post(
                    f"{base_url}/api/v1/set_remote_request_modifiers.php",
                    data={
                        "user": tenant,
                        "request_id": int(request_id),
                        "song_key": int(song_key),
                        "tempo": int(tempo_offset),
                    },
                    headers=headers,
                    timeout=5,
                )
                if 200 <= resp.status_code < 300:
                    _diag(f"[REMOTE-MODIFIER] server accepted request_id={request_id} key={song_key:+d} tempo={tempo_offset:+d}")
                else:
                    print(f"[REMOTE-MODIFIER] HTTP {resp.status_code}: {resp.text[:160]}")
            except Exception as e:
                print(f"[REMOTE-MODIFIER] Failed to push modifiers for request {request_id}: {e}")

        threading.Thread(target=send, daemon=True).start()

    def _host_owned_remote_request_ids(self) -> list[int]:
        ids = self._queue_remote_request_ids()
        # Playback removes the current entry from the singer's pending songs.
        # Its permanent id still belongs to this host until completion/stop.
        state = object.__getattribute__(self, "__dict__")
        if bool(state.get("karaoke_playing", False)):
            current = str(state.get("_current_karaoke_request_id", "") or "")
            if current.startswith("remote:"):
                try:
                    rid = int(current.partition(":")[2])
                    if rid > 0:
                        ids.append(rid)
                except ValueError:
                    pass
        return sorted(set(ids))

    def _queue_remote_request_ids(self) -> list[int]:
        ids = []
        for singer in getattr(self, "queue", []) or []:
            if not isinstance(singer, dict):
                continue
            for entry in singer.get("songs", []) or []:
                remote_id = self._queue_entry_remote_request_id(entry)
                if remote_id is None:
                    continue
                try:
                    rid = int(remote_id)
                    if rid > 0:
                        ids.append(rid)
                except Exception:
                    pass
        return sorted(set(ids))

    def _server_terminal_conflicts_with_live_host_request(self, request_id: int, req: dict) -> bool:
        """Return True when a terminal history row reused a live host request id.

        Some server resets can recycle numeric request ids while older terminal
        rows are still present in the history payload. A newly synced host add
        has a permanent host_request_key, so an unrelated historical row must
        never complete/remove it merely because the numeric ids collide.
        """
        try:
            request_id = int(request_id or 0)
        except Exception:
            return False
        if request_id <= 0 or not isinstance(req, dict):
            return False

        def norm(value) -> str:
            return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())

        server_key = str(req.get("idempotency_key") or req.get("host_request_key") or "").strip()
        server_source = str(req.get("request_source") or req.get("source") or "").strip().lower()
        for singer in getattr(self, "queue", []) or []:
            if not isinstance(singer, dict):
                continue
            for entry in singer.get("songs", []) or []:
                try:
                    local_id = int(self._queue_entry_remote_request_id(entry) or 0)
                except Exception:
                    local_id = 0
                if local_id != request_id or not isinstance(entry, dict):
                    continue

                local_key = str(entry.get("host_request_key") or "").strip()
                if not local_key:
                    return False
                if server_key:
                    return server_key != local_key
                if server_source and server_source != "host_manual":
                    return True

                _artist, local_title = self._queue_entry_artist_title_for_tombstone(entry)
                server_title = str(req.get("title") or "").strip()
                if local_title and server_title and self._tombstone_signature_conflicts(
                    {"title": local_title}, {"title": server_title}
                ):
                    return True

                local_singer = str(entry.get("duet_display") or singer.get("name") or "").strip()
                server_singer = str(req.get("singer") or "").strip()
                if local_singer and server_singer and norm(local_singer) != norm(server_singer):
                    return True
                return False
        return False

    def _remove_local_remote_request_by_id(self, request_id: int, reason: str = "server_removed") -> int:
        try:
            request_id = int(request_id or 0)
        except Exception:
            request_id = 0
        if request_id <= 0:
            return 0
        removed = 0
        for singer_idx in range(len(self.queue) - 1, -1, -1):
            singer = self.queue[singer_idx]
            if not isinstance(singer, dict):
                continue
            songs = singer.get("songs", [])
            if not isinstance(songs, list):
                continue
            for song_idx in range(len(songs) - 1, -1, -1):
                entry = songs[song_idx]
                remote_id = self._queue_entry_remote_request_id(entry)
                try:
                    remote_id = int(remote_id or 0)
                except Exception:
                    remote_id = 0
                if remote_id != request_id:
                    continue
                songs.pop(song_idx)
                removed += 1
                _diag(
                    "[REMOTE-SYNC] removed local queued request from server tombstone "
                    f"request_id={request_id} singer={singer.get('name', '')!r} reason={reason}"
                )
            if songs:
                continue
            if self._is_rotation_mode():
                singer["songs"] = []
                self._mark_rotation_slot_temporarily_empty(singer, reason=reason)
            elif self._should_preserve_empty_singer_row(singer):
                singer["songs"] = []
            else:
                del self.queue[singer_idx]
        if removed:
            try:
                self._queue_revision = int(getattr(self, "_queue_revision", 0)) + 1
            except Exception:
                self._queue_revision = 1
            try:
                self._request_queue_display_refresh()
            except Exception:
                pass
        return removed

    def _log_remote_request_diag(self, req: dict | None, *, status: str, match_result: str = "",
                                 queue_insert_result: str = "", failure_reason: str = "") -> None:
        req = req if isinstance(req, dict) else {}
        try:
            request_id = int(req.get("request_id") or req.get("id") or 0)
        except Exception:
            request_id = 0
        try:
            rev = int(getattr(self, "_queue_revision", 0) or 0)
        except Exception:
            rev = 0
        try:
            accepting = int(self._is_requests_accepting_cached())
        except Exception:
            accepting = 1
        summary = (
            f"#{request_id} {str(req.get('singer', '') or '').strip()} - "
            f"{str(req.get('artist', '') or '').strip()} / {str(req.get('title', '') or '').strip()}"
        ).strip()
        diag_signature = (
            str(status or ""),
            str(match_result or ""),
            str(queue_insert_result or ""),
            str(failure_reason or ""),
            str(req.get("singer") or ""),
            str(req.get("artist") or ""),
            str(req.get("title") or ""),
            str(req.get("selected_version") or req.get("selected_brand") or req.get("selected_disc_id") or ""),
        )
        try:
            cache = getattr(self, "_remote_request_diag_signatures", None)
            if not isinstance(cache, dict):
                cache = {}
                self._remote_request_diag_signatures = cache
            if request_id > 0 and cache.get(request_id) == diag_signature:
                return
            if request_id > 0:
                cache[request_id] = diag_signature
                if len(cache) > 2048:
                    for stale_id in list(cache)[:len(cache) - 2048]:
                        cache.pop(stale_id, None)
        except Exception:
            pass
        try:
            if status in {"received", "processing", "pending"}:
                self._last_request_received_summary = summary
            if status == "accepted":
                self._last_request_accepted_summary = summary
            if failure_reason:
                self._last_server_error = str(failure_reason)
            self._last_sync_time_label = datetime.now().strftime("%H:%M:%S")
        except Exception:
            pass
        _diag(
            "[REQUEST-DIAG] "
            f"request_id={request_id} singer={str(req.get('singer', '') or '')!r} "
            f"artist={str(req.get('artist', '') or '')!r} title={str(req.get('title', '') or '')!r} "
            f"source={str(req.get('request_source') or req.get('source') or '')!r} "
            f"session_id={str(req.get('singer_session_id') or req.get('session_id') or '')!r} "
            f"selected_version={str(req.get('selected_version') or req.get('selected_brand') or req.get('selected_disc_id') or '')!r} "
            f"received_ts={int(time.time())} status={status} match_result={match_result!r} "
            f"queue_insert_result={queue_insert_result!r} sync_revision={rev} "
            f"server_enabled={accepting} failure_reason={failure_reason!r}"
        )
        try:
            self._refresh_header_status()
        except Exception:
            pass

    def _record_remote_attention_request(self, req: dict | None, reason: str) -> None:
        """Keep failed automatic requests visible to diagnostics instead of losing them."""
        req = dict(req or {}) if isinstance(req, dict) else {}
        try:
            rid = int(req.get("request_id") or req.get("id") or 0)
        except Exception:
            rid = 0
        key = rid or hash((
            str(req.get("singer", "") or "").lower(),
            str(req.get("artist", "") or "").lower(),
            str(req.get("title", "") or "").lower(),
        ))
        pending = getattr(self, "_remote_attention_requests", None)
        if not isinstance(pending, dict):
            pending = {}
            self._remote_attention_requests = pending
        item = dict(req)
        item["attention_reason"] = str(reason or "unknown")
        item["attention_at"] = int(time.time())
        pending[key] = item
        _diag(
            "[REQUEST-ATTENTION] pending "
            f"request_id={rid} singer={str(req.get('singer', '') or '')!r} "
            f"artist={str(req.get('artist', '') or '')!r} title={str(req.get('title', '') or '')!r} "
            f"reason={reason!r} pending_count={len(pending)}"
        )
        try:
            # Failed automatic requests must stay host-visible even in
            # auto-accept mode (waitlist off): a silent drop looks like "no
            # requests tonight" while singers watch their submissions say
            # "sent" (2026-07-19 show outage).
            self._upsert_waiting_for_add_request(item, str(reason or "unknown"), force_visible=True)
        except Exception:
            pass
        try:
            self._set_processing_text(
                f"⚠ Request NOT added: {str(req.get('singer', '') or '?')} — "
                f"{str(req.get('artist', '') or '?')} - {str(req.get('title', '') or '?')} ({reason})",
            )
        except Exception:
            pass
        # Always tell the server: the web side must show "needs host review",
        # never a silent "sent" while the host saw nothing.
        self._report_remote_attention_request_async(req, str(reason or "unknown"))

    def _record_remote_limit_blocked_request(self, req: dict | None, message: str, *, report: bool = True) -> None:
        """Reject a public request at the singer cap without placing it in the host waitlist."""
        req = dict(req or {}) if isinstance(req, dict) else {}
        reason = "singer_song_limit"
        if message:
            req["attention_error"] = str(message)
        try:
            self._show_queue_limit_rejected(str(message or "Singer song limit reached."), remote=True)
        except Exception:
            pass
        try:
            self._log_remote_request_diag(
                req,
                status="pending",
                match_result="not_attempted",
                queue_insert_result="blocked",
                failure_reason=reason,
            )
        except Exception:
            pass
        _diag(
            "[REQUEST-LIMIT] blocked "
            f"request_id={self._request_limit_request_id(req)} singer={str(req.get('singer', '') or '')!r} "
            f"reason={reason!r} message={str(message or '')!r}"
        )
        if report:
            # Reported regardless of waitlist mode so the singer-facing page
            # reflects the block instead of a silent "sent".
            self._report_remote_attention_request_async(req, reason)

    def _report_remote_attention_request_async(self, req: dict, reason: str) -> None:
        try:
            rid = int(req.get("request_id") or req.get("id") or 0)
        except Exception:
            rid = 0
        if rid <= 0:
            return
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        if not base_url or not tenant or not api_key:
            return

        def worker():
            try:
                resp = requests.post(
                    f"{base_url}/api/v1/report_pending_request.php",
                    data={
                        "user": tenant,
                        "request_id": rid,
                        "state": "failed_needs_review",
                        "reason": str(reason or "sync_failed"),
                        "error": str(req.get("attention_error") or reason or ""),
                        "source": str(req.get("request_source") or req.get("source") or ""),
                        "singer": str(req.get("singer") or ""),
                        "artist": str(req.get("artist") or ""),
                        "title": str(req.get("title") or ""),
                    },
                    headers={"X-API-Key": api_key},
                    timeout=4,
                )
                ok = 200 <= int(getattr(resp, "status_code", 0)) < 300
                _diag(
                    "[REQUEST-ATTENTION] report "
                    f"request_id={rid} reason={reason!r} ok={int(ok)} status={getattr(resp, 'status_code', '')}"
                )
            except Exception as e:
                _diag(f"[REQUEST-ATTENTION] report failed request_id={rid} reason={reason!r}: {e}")

        try:
            threading.Thread(target=worker, daemon=True, name="request-attention-report").start()
        except Exception:
            pass

    def _clear_remote_attention_request(self, req: dict | None) -> None:
        pending = getattr(self, "_remote_attention_requests", None)
        if not isinstance(pending, dict):
            return
        req = req if isinstance(req, dict) else {}
        try:
            rid = int(req.get("request_id") or req.get("id") or 0)
        except Exception:
            rid = 0
        keys = []
        if rid:
            keys.append(rid)
        keys.append(hash((
            str(req.get("singer", "") or "").lower(),
            str(req.get("artist", "") or "").lower(),
            str(req.get("title", "") or "").lower(),
        )))
        for key in keys:
            pending.pop(key, None)
        try:
            wait = getattr(self, "_waiting_for_add_requests", None)
            if isinstance(wait, dict):
                for key in keys:
                    wait.pop(key, None)
                self._schedule_waiting_for_add_view_refresh(reason="remote_remove")
        except Exception:
            pass

    def _clear_remote_queue_async(self, request_ids: list[int] | None = None, reason: str = "clear_queue"):
        """Clear server-side requests/rotation, then force a poll refresh.

        The preferred server endpoint is clear_remote_queue.php. For older
        servers, fall back to deleting known remote request ids one by one and
        posting an empty public rotation so stale display data disappears.
        """
        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        ids = []
        for value in request_ids or []:
            try:
                rid = int(value)
                if rid > 0:
                    ids.append(rid)
            except Exception:
                pass
        ids = sorted(set(ids))
        if not base_url or not tenant or not api_key:
            _diag(f"[REMOTE-CLEAR] skipped: network not configured reason={reason}")
            return

        import threading, json as _json

        def send():
            headers = {
                "X-API-Key": api_key,
                "Accept": "application/json",
                "User-Agent": "SingWS/clear-queue",
            }
            cleared = False
            try:
                resp = requests.post(
                    f"{base_url}/api/v1/clear_remote_queue.php",
                    data={"user": tenant, "clear_rotation": "1", "clear_requests": "1"},
                    headers=headers,
                    timeout=8,
                )
                if 200 <= resp.status_code < 300:
                    cleared = True
                    print(f"[REMOTE-CLEAR] server queue cleared ({reason})")
                else:
                    print(f"[REMOTE-CLEAR] clear endpoint HTTP {resp.status_code}: {resp.text[:160]}")
            except Exception as e:
                print(f"[REMOTE-CLEAR] clear endpoint unavailable: {e}")

            if not cleared and ids:
                deleted = 0
                for rid in ids:
                    try:
                        resp = requests.post(
                            f"{base_url}/api/v1/delete_remote_request.php",
                            data={"user": tenant, "request_id": rid},
                            headers=headers,
                            timeout=5,
                        )
                        if 200 <= resp.status_code < 300:
                            deleted += 1
                    except Exception as e:
                        print(f"[REMOTE-CLEAR] delete fallback failed for {rid}: {e}")
                print(f"[REMOTE-CLEAR] delete fallback removed {deleted}/{len(ids)} known request(s)")

            if not cleared:
                try:
                    resp = requests.post(
                        f"{base_url}/api.php",
                        params={"tenant": tenant},
                        json={"command": "clearRequests"},
                        headers=headers,
                        timeout=5,
                    )
                    if 200 <= resp.status_code < 300:
                        print("[REMOTE-CLEAR] legacy api.php clearRequests sent")
                    else:
                        print(f"[REMOTE-CLEAR] legacy clear HTTP {resp.status_code}: {resp.text[:160]}")
                except Exception as e:
                    print(f"[REMOTE-CLEAR] legacy clear failed: {e}")

            try:
                resp = requests.post(
                    f"{base_url}/post_rotation.php",
                    params={"user": tenant},
                    data={
                        "user": tenant,
                        "tenant": tenant,
                        "request_type": "rotation",
                        "rotation": _json.dumps([]),
                    },
                    headers=headers,
                    timeout=5,
                )
                if 200 <= resp.status_code < 300:
                    print("[REMOTE-CLEAR] public rotation cleared")
                else:
                    print(f"[REMOTE-CLEAR] public rotation clear HTTP {resp.status_code}: {resp.text[:160]}")
            except Exception as e:
                print(f"[REMOTE-CLEAR] public rotation clear failed: {e}")

            try:
                self._run_on_ui_thread(lambda: self.handle_requests_from_thread([]))
                self._run_on_ui_thread(lambda: QTimer.singleShot(1200, self.restart_request_polling))
                print("[REMOTE-CLEAR] sync refresh scheduled")
            except Exception:
                pass

        threading.Thread(target=send, daemon=True).start()

    def _sync_remote_singer_order(self, singer_idx: int, *, reason: str = "host_reorder"):
        try:
            singer = self.queue[singer_idx]
        except Exception:
            return
        songs = singer.get("songs", []) if isinstance(singer, dict) else []
        request_ids = self._singer_remote_order_ids(singer)
        request_ids, host_order_updated_at, rev = self._record_host_singer_order_change(
            singer_idx,
            reason=reason,
            request_ids=request_ids,
        )
        if not request_ids:
            return
        _diag(
            f"[REORDER] singer={singer.get('name','')!r} order={request_ids} "
            f"queue_revision={rev} host_order_updated_at={host_order_updated_at} (host is authoritative)"
        )

        base_url = _network_normalize_base_url(self.settings.get("base_url", ""))
        tenant = str(self.settings.get("user", self.settings.get("tenant", "")) or "").strip()
        api_key = str(self.settings.get("api_key", "") or "").strip()
        if not base_url or not tenant or not api_key:
            return

        import threading

        def send():
            try:
                resp = requests.post(
                    f"{base_url}/api/v1/set_remote_request_order.php",
                    data=[("user", tenant), ("revision", str(rev)),
                          ("order_revision", str(rev)),
                          ("host_order_updated_at", str(host_order_updated_at)),
                          ("last_order_source", "host"),
                          *[("request_ids[]", rid) for rid in request_ids]],
                    headers={"X-API-Key": api_key},
                    timeout=5,
                )
                _diag(f"[REORDER] server accepted={resp.status_code == 200} "
                      f"(HTTP {resp.status_code}) revision={rev} host_order_updated_at={host_order_updated_at}")
            except Exception as e:
                print(f"[REMOTE-ORDER] Failed to sync order for singer {singer.get('name', '')}: {e}")

        threading.Thread(target=send, daemon=True).start()

    def _reconcile_remote_requests(self, reqs, *, update_waitlist: bool = True):
        _perf_t0 = time.perf_counter()
        # A successful poll is also our reconnect signal. Retry durable host
        # additions without blocking the UI; idempotency prevents duplicates.
        try:
            self._flush_host_request_sync_ops()
        except Exception:
            pass
        try:
            self._prune_expired_empty_rotation_slots()
        except Exception:
            pass
        try:
            self._merge_duplicate_rotation_singers(reason="remote_reconcile_start")
        except Exception:
            pass
        try:
            if time.time() < float(getattr(self, "_remote_clear_in_progress_until", 0.0) or 0.0):
                _diag(f"[REMOTE-CLEAR] ignoring stale poll during clear window ({len(reqs or [])} request(s))")
                return
        except Exception:
            pass
        normalized = []
        try:
            removed_ids = getattr(self, "_remote_removed_request_ids", set())
            if not isinstance(removed_ids, set):
                removed_ids = set()
        except Exception:
            removed_ids = set()
        accepting_requests = self._is_requests_accepting_cached()
        try:
            local_remote_ids = set(int(v) for v in self._queue_remote_request_ids())
        except Exception:
            local_remote_ids = set()
        try:
            local_remote_ids |= self._deferred_remote_request_ids()
            local_remote_ids |= self._remote_request_inflight_ids()
        except Exception:
            pass
        try:
            self._last_sync_time_label = datetime.now().strftime("%H:%M:%S")
            self._refresh_header_status()
        except Exception:
            pass
        if update_waitlist:
            try:
                self._set_waiting_for_add_requests(reqs, local_remote_ids=local_remote_ids)
            except Exception as e:
                _diag(f"[WAITING-FOR-ADD] refresh failed: {e}")
        else:
            _diag(
                "[WAITING-FOR-ADD] preserved legacy waitlist snapshot "
                f"source=relay_v2 relay_rows={len(reqs or [])}"
            )
        _diag(
            "[REMOTE-SYNC] reconcile "
            f"count={len(reqs or [])} accepting_requests={int(accepting_requests)} "
            f"sync_connected={int(self.is_network_configured())}"
        )
        try:
            self._ensure_server_accepting_matches_host_intent_async(reason="remote_reconcile")
        except Exception as e:
            _diag(f"[SERVER-STATE] accepting watchdog schedule failed reason=remote_reconcile: {e}")
        try:
            # Pull in both modes. The old enabled-only gate meant a stale
            # client/server toggle could never self-heal once local mode was
            # off, which is why iPads appeared stuck until restart.
            self._sync_waitlist_state_from_server_async(reason="remote_reconcile")
        except Exception as e:
            _diag(f"[WAITLIST-STATE] pull schedule failed reason=remote_reconcile: {e}")

        # Session-scoped dedupe for per-request reconcile logging: the server
        # resends the night's full request history on every sync pass, and
        # re-logging every historical/terminal row on every pass used to
        # dominate the log (tens of thousands of lines per night).
        def _logged_set(attr: str) -> set:
            try:
                value = getattr(self, attr, None)
            except Exception:
                value = None
            if not isinstance(value, set):
                value = set()
                try:
                    setattr(self, attr, value)
                except Exception:
                    pass
            return value

        logged_terminal = _logged_set("_remote_sync_logged_terminal")
        logged_historical = _logged_set("_remote_sync_logged_historical")
        logged_holding = _logged_set("_remote_sync_logged_holding")
        logged_tombstone_repush = _logged_set("_remote_sync_logged_tombstone_repush")
        ignored_historical = 0
        terminal_not_present = 0
        for req in reqs or []:
            if not isinstance(req, dict):
                continue
            try:
                request_id = int(req.get("request_id", 0) or 0)
            except Exception:
                request_id = 0
            if request_id <= 0:
                continue
            state = str(req.get("state", "") or "").strip().lower()
            try:
                removed_at = int(float(req.get("removed_at") or 0))
            except Exception:
                removed_at = 0
            try:
                completed_at = int(float(req.get("completed_at") or 0))
            except Exception:
                completed_at = 0
            server_terminal = state in {"removed", "completed", "sung"} or removed_at > 0 or completed_at > 0
            if server_terminal:
                if self._server_terminal_conflicts_with_live_host_request(request_id, req):
                    # A stale terminal history row collided with the numeric id
                    # just assigned to a different live host/manual request.
                    # The host queue is authoritative; do not auto-complete it.
                    if request_id not in logged_historical:
                        logged_historical.add(request_id)
                        _diag(
                            "[REMOTE-SYNC] stale terminal id collision ignored "
                            f"request_id={request_id} singer={req.get('singer', '')!r} "
                            f"title={req.get('title', '')!r}"
                        )
                    continue
                # The server already knows this request is done. Handle it
                # before the local-tombstone branch: re-pushing removals for
                # rows the server itself reports as terminal churned the
                # network and flip-flopped removed_ids on every pass.
                removed_count = self._remove_local_remote_request_by_id(
                    request_id,
                    reason=f"server_{state or ('removed' if removed_at else 'completed')}",
                )
                if self._remove_deferred_remote_add_by_id(request_id):
                    removed_count += 1
                try:
                    removed_ids.add(request_id)
                    self._remote_removed_request_ids = removed_ids
                    # Remember what song this terminal id was for, so a later
                    # row with the same id can be told apart: same title =
                    # stale restore (ignore), different title = id reused by
                    # a new request after a server-side reset (accept).
                    terminal_titles = object.__getattribute__(self, "__dict__").setdefault(
                        "_remote_terminal_titles", {}
                    )
                    terminal_titles[request_id] = str(req.get("title") or "")
                except Exception:
                    pass
                if removed_count:
                    logged_terminal.add((request_id, state))
                    self._log_remote_request_diag(
                        req,
                        status="removed" if state == "removed" or removed_at else "completed",
                        match_result="server_tombstone",
                        queue_insert_result="removed" if removed_count else "not_present",
                        failure_reason="",
                    )
                elif (request_id, state) not in logged_terminal:
                    logged_terminal.add((request_id, state))
                    terminal_not_present += 1
                continue
            tombstone = self._remote_request_matches_tombstone(req)
            if tombstone is not None and self._tombstone_signature_conflicts(tombstone, req):
                # Confirmed id reuse (clearly a different song): retire the
                # old tombstone and treat this row as a brand-new request.
                self._drop_remote_request_tombstone(request_id, reason="id_reuse_confirmed")
                try:
                    removed_ids.discard(request_id)
                    self._remote_removed_request_ids = removed_ids
                except Exception:
                    pass
                _diag(
                    "[REMOTE-TOMBSTONE] reused request id accepted "
                    f"request_id={request_id} tombstone_title={tombstone.get('title', '')!r} "
                    f"request_title={req.get('title', '')!r}"
                )
                tombstone = None
            elif tombstone is not None:
                # The server still reports a request the host removed locally:
                # the host removal is authoritative — keep re-pushing the
                # removal (the push helper is throttled and skips
                # already-acknowledged tombstones), but log once per id.
                if request_id not in logged_tombstone_repush:
                    logged_tombstone_repush.add(request_id)
                    _diag(
                        "[REMOTE-TOMBSTONE] poll old request ignored "
                        f"request_id={request_id} singer={req.get('singer', '')!r} "
                        f"title={req.get('title', '')!r} reason=tombstone; re-push removed status"
                    )
                try:
                    removed_ids.add(request_id)
                    self._remote_removed_request_ids = removed_ids
                    self._sync_remote_removal_tombstones_async("stale_poll_repush")
                except Exception:
                    pass
                continue
            if request_id in removed_ids:
                # Known-terminal id with no live tombstone (the server itself
                # reported it removed/completed earlier this session). A stale
                # row flipping back to 'pending' — e.g. another client posting
                # old data — must not resurrect the host-deleted item. Only a
                # clear title conflict (id genuinely reused by a NEW request
                # after a server-side reset) is allowed through.
                terminal_title = ""
                try:
                    terminal_title = str(
                        object.__getattribute__(self, "__dict__").get("_remote_terminal_titles", {}).get(request_id) or ""
                    )
                except Exception:
                    terminal_title = ""
                if terminal_title and self._tombstone_signature_conflicts({"title": terminal_title}, req):
                    try:
                        removed_ids.discard(request_id)
                        self._remote_removed_request_ids = removed_ids
                    except Exception:
                        pass
                    _diag(
                        "[REMOTE-TOMBSTONE] terminal id reused by new request; accepting "
                        f"request_id={request_id} old_title={terminal_title!r} new_title={req.get('title', '')!r}"
                    )
                else:
                    if request_id not in logged_tombstone_repush:
                        logged_tombstone_repush.add(request_id)
                        _diag(
                            "[REMOTE-TOMBSTONE] stale non-terminal row for terminal id ignored "
                            f"request_id={request_id} singer={req.get('singer', '')!r} "
                            f"title={req.get('title', '')!r}"
                        )
                    continue
            # Lifecycle state outranks legacy transport acknowledgement flags.
            # A waiting/failed row with a stale ``sent`` bit still needs a host
            # decision and must not be filed as historical.
            delivered = self._remote_request_is_non_actionable(req)
            if delivered and request_id not in local_remote_ids:
                ignored_historical += 1
                if (request_id, state) not in logged_historical:
                    logged_historical.add((request_id, state))
                continue
            if self._is_waiting_for_add_request(req):
                hold_reason = str(req.get("pending_reason") or req.get("attention_reason") or "")
                if (request_id, state, hold_reason) not in logged_holding:
                    logged_holding.add((request_id, state, hold_reason))
                    _diag(
                        "[WAITING-FOR-ADD] holding request for host "
                        f"request_id={request_id} state={state!r} reason={hold_reason!r}"
                    )
                continue
            singer = str(req.get("singer", "") or "").strip()
            if not singer:
                continue
            try:
                key = int(req.get("key", 0) or 0)
            except Exception:
                key = 0
            try:
                tempo = int(req.get("tempo", 0) or 0)
            except Exception:
                tempo = 0
            tempo = max(-30, min(30, tempo))
            queue_singer, _duet_display = self._parse_duet_singer(singer)
            if not queue_singer:
                queue_singer = singer
            order_meta = self._remote_order_meta_from_req(req)
            normalized.append({
                "request_id": request_id,
                "singer": singer,
                "queue_singer": queue_singer,
                "artist": str(req.get("artist", "") or "").strip(),
                "title": str(req.get("title", "") or "").strip(),
                "key": key,
                "tempo": tempo,
                "host_order_updated_at": order_meta.get("host_order_updated_at", 0),
                "singer_order_updated_at": order_meta.get("singer_order_updated_at", 0),
                "order_revision": order_meta.get("order_revision", 0),
                "last_order_source": order_meta.get("last_order_source", "server"),
                # Raw wire value on purpose: absence (None/"") means the server
                # conveyed order via row order only; see sort_lookup below.
                "sort_order": req.get("sort_order"),
                "request_source": str(req.get("request_source") or req.get("source") or ""),
                "source": str(req.get("request_source") or req.get("source") or ""),
                "singer_session_id": req.get("singer_session_id") or req.get("session_id") or "",
                "selected_version": req.get("selected_version") or "",
                "selected_brand": req.get("selected_brand") or "",
                "selected_disc_id": req.get("selected_disc_id") or "",
                "selected_source": req.get("selected_source") or "",
                "provider": req.get("provider") or "",
                "provider_track_id": req.get("provider_track_id") or req.get("selected_disc_id") or "",
                "provider_url": req.get("provider_url") or req.get("selected_url") or "",
                "duration": next(
                    (req.get(field) for field in ("duration", "duration_secs", "duration_seconds", "length_secs", "length")
                     if req.get(field) not in (None, "")),
                    None,
                ),
                "duration_estimated": bool(req.get("duration_estimated", False)),
                "duration_source": str(req.get("duration_source") or "server_metadata"),
                "received_at_server": req.get("received_at_server") or "",
                "pending_reason": req.get("pending_reason") or "",
                "pending_status": req.get("pending_status") or "",
                "last_error": req.get("last_error") or "",
            })
            try:
                self._log_remote_request_diag(normalized[-1], status="received", match_result="pending", queue_insert_result="pending")
            except Exception:
                pass

        if ignored_historical:
            _diag(
                "[REMOTE-SYNC] historical requests ignored "
                f"count={ignored_historical}"
            )
        if terminal_not_present:
            _diag(
                "[REMOTE-SYNC] terminal requests already absent locally "
                f"count={terminal_not_present}"
            )

        desired_ids = {item["request_id"] for item in normalized}
        existing_ids = set(self._host_owned_remote_request_ids())
        unmatched_by_signature = {}
        for req in normalized:
            sig = (req["queue_singer"].lower(), req["artist"].lower(), req["title"].lower())
            unmatched_by_signature.setdefault(sig, []).append(req)

        for singer in self.queue:
            singer_name_l = str(singer.get("name", "") or "").strip().lower()
            for entry in singer.get("songs", []):
                remote_id = self._queue_entry_remote_request_id(entry)
                if remote_id is not None:
                    continue
                artist, title = self._queue_entry_artist_title(entry)
                artist_l = str(artist or "").strip().lower()
                title_l = str(title or "").strip().lower()
                if not artist_l or not title_l:
                    continue
                sig = (singer_name_l, artist_l, title_l)
                candidates = unmatched_by_signature.get(sig) or []
                if not candidates:
                    continue
                match = candidates.pop(0)
                if isinstance(entry, dict):
                    entry["remote_request_id"] = match["request_id"]
                    entry["key"] = match["key"]
                    entry["tempo_percent"] = 100 + match["tempo"]
                existing_ids.add(match["request_id"])

        for singer_idx in range(len(self.queue) - 1, -1, -1):
            singer = self.queue[singer_idx]
            songs = singer.get("songs", [])
            for song_idx in range(len(songs) - 1, -1, -1):
                entry = songs[song_idx]
                remote_id = self._queue_entry_remote_request_id(entry)
                if remote_id is None:
                    continue
                if remote_id not in desired_ids:
                    # Do not delete an already-accepted local queue entry just
                    # because the latest server sync no longer lists it. Newer
                    # relay/v2 servers may stop returning delivered/acked rows;
                    # the host queue remains authoritative until explicit host
                    # removal or song completion records a tombstone.
                    existing_ids.add(remote_id)
                    _diag_rate_limited(
                        f"remote_preserve:{remote_id}",
                        "[REMOTE-SYNC] preserving local queued request missing from server payload "
                        f"request_id={remote_id} singer={singer.get('name', '')!r}",
                        300.0,
                    )
                else:
                    existing_ids.add(remote_id)
            if not songs:
                if self._should_preserve_empty_singer_row(singer):
                    singer["songs"] = []
                else:
                    del self.queue[singer_idx]

        # Requests whose song can't be found in the library would otherwise be
        # re-processed (and re-logged) on every poll, because a failed lookup
        # never lands in the queue and so never enters existing_ids. Remember the
        # ones we've already tried-and-failed and skip them until the server
        # drops them (or the library is re-indexed, which clears this set).
        failed = getattr(self, "_unmatched_remote_request_ids", None)
        if not isinstance(failed, set):
            failed = set()
            self._unmatched_remote_request_ids = failed
        # Forget ids the server no longer lists so a re-submission gets a fresh try.
        failed &= desired_ids

        accepted_remote_add = False
        try:
            self._cleanup_duplicate_singer_songs(reason="remote_reconcile_precheck")
        except Exception:
            pass
        intake_counts = self._live_song_counts_by_singer()
        try:
            waiting_ids = {int(v) for v in getattr(self, "_waiting_for_add_requests", {}).keys()}
        except Exception:
            waiting_ids = set()
        self._begin_queue_update_batch()
        try:
            for req in normalized:
                rid = req["request_id"]
                if rid in existing_ids or rid in failed or rid in waiting_ids:
                    continue
                ok_limit, limit_message = self._check_remote_request_song_limit(req, counts=intake_counts)
                if not ok_limit:
                    self._record_remote_limit_blocked_request(req, limit_message)
                    continue
                if not accepting_requests:
                    _diag(
                        "[REMOTE-SYNC] stale pending request ignored because accepting_requests=0 "
                        f"request_id={rid} singer={req.get('singer', '')!r} title={req.get('title', '')!r} "
                        f"state={req.get('state', '')!r} received_at_server={req.get('received_at_server', '')!r}"
                    )
                    self._log_remote_request_diag(
                        req,
                        status="ignored",
                        match_result="not_attempted",
                        queue_insert_result="ignored",
                        failure_reason="accepting_closed_stale_pending",
                    )
                    continue
                if self._should_async_remote_request_intake():
                    if self._start_remote_request_intake_worker(req):
                        accepted_remote_add = True
                        self._add_participants_to_song_counts(intake_counts, self._remote_request_participants(req))
                    else:
                        failed.add(rid)
                        self._record_remote_attention_request(req, "auto_accept_failed")
                elif self.process_external_request(req):
                    accepted_remote_add = True
                    self._add_participants_to_song_counts(intake_counts, self._remote_request_participants(req))
                else:
                    failed.add(rid)
                    self._record_remote_attention_request(req, "auto_accept_failed")
        finally:
            self._end_queue_update_batch(flush=False)

        tempo_by_id = {item["request_id"]: item["tempo"] for item in normalized}
        key_by_id = {item["request_id"]: item["key"] for item in normalized}
        duration_by_id = {item["request_id"]: item.get("duration") for item in normalized}
        duration_source_by_id = {item["request_id"]: item.get("duration_source") for item in normalized}
        sort_by_id = {}
        for item in normalized:
            try:
                sort_by_id[item["request_id"]] = float(item.get("sort_order"))
            except (TypeError, ValueError):
                sort_by_id[item["request_id"]] = float(item["request_id"])
        desired_by_singer = {}
        desired_meta_by_singer = {}
        for req in normalized:
            singer_key = req["queue_singer"].lower()
            desired_by_singer.setdefault(singer_key, []).append(req["request_id"])
            desired_meta_by_singer[singer_key] = self._merge_remote_order_meta(desired_meta_by_singer.get(singer_key), req)
        for singer_key, request_ids in list(desired_by_singer.items()):
            # Re-sort by sort_order ONLY when the server actually sent one.
            # get_requests.php conveys order via ROW ORDER (it already does
            # ORDER BY sort_order server-side) and does not emit the column,
            # so falling back to request_id here would destroy the server's
            # intended order for every payload (host/singer reorders never
            # reached the desktop).
            sort_lookup = {}
            for req in normalized:
                if req["queue_singer"].lower() != singer_key:
                    continue
                raw = req.get("sort_order")
                if raw in (None, ""):
                    continue
                try:
                    sort_lookup[int(req["request_id"])] = (float(raw), int(req["request_id"]))
                except Exception:
                    pass
            if not sort_lookup:
                continue  # wire order is authoritative
            payload_rank = {int(rid): i for i, rid in enumerate(request_ids)}
            desired_by_singer[singer_key] = sorted(
                [int(rid) for rid in request_ids],
                key=lambda rid: sort_lookup.get(
                    int(rid), (float("inf"), payload_rank.get(int(rid), 0))
                ),
            )

        try:
            pending = getattr(self, "_pending_remote_order_syncs", {})
            if isinstance(pending, dict):
                for singer_key in list(pending.keys()):
                    item = pending.get(singer_key) or {}
                    pending_ids = [int(v) for v in (item.get("request_ids") or []) if int(v) in desired_ids]
                    server_ids = desired_by_singer.get(singer_key, [])
                    if pending_ids and set(pending_ids) == set(server_ids):
                        if server_ids == pending_ids:
                            incoming_meta = desired_meta_by_singer.get(singer_key, {})
                            incoming_host_ts = int(incoming_meta.get("host_order_updated_at") or 0)
                            pending_host_ts = int(item.get("host_order_updated_at") or 0)
                            if incoming_host_ts and pending_host_ts and incoming_host_ts < pending_host_ts:
                                desired_by_singer[singer_key] = pending_ids
                                continue
                            pending.pop(singer_key, None)
                        else:
                            incoming_meta = desired_meta_by_singer.get(singer_key, {})
                            incoming_source = str(incoming_meta.get("last_order_source") or "server").strip().lower()
                            incoming_ts = self._incoming_order_timestamp(incoming_meta)
                            pending_host_ts = int(item.get("host_order_updated_at") or 0)
                            if not (incoming_source == "singer" and incoming_ts > pending_host_ts):
                                desired_by_singer[singer_key] = pending_ids
        except Exception:
            pass

        # Sync per-song metadata (key / tempo edits made on the website) onto the
        # matching local entries. Singer-side ordering is allowed only within
        # that singer's own song list; the overall singer rotation never moves.
        # Host-wins: a key/tempo edit the operator just pushed must not be
        # reverted by a poll that raced ahead of the server commit. We keep the
        # pending host value until the server reports the same thing (or the
        # short window expires).
        try:
            pending_mods = getattr(self, "_pending_remote_modifier_pushes", None)
        except Exception:
            pending_mods = None
        if not isinstance(pending_mods, dict):
            pending_mods = {}
        now_ts = time.time()
        for rid in list(pending_mods.keys()):
            item = pending_mods.get(rid) or {}
            if float(item.get("expires_at") or 0.0) < now_ts:
                pending_mods.pop(rid, None)

        entry_by_id = {}
        for singer in self.queue:
            for entry in singer.get("songs", []):
                remote_id = self._queue_entry_remote_request_id(entry)
                if remote_id is None:
                    continue
                entry_by_id[remote_id] = entry
                if isinstance(entry, dict):
                    server_key = key_by_id.get(remote_id, entry.get("key", 0))
                    server_tempo = tempo_by_id.get(remote_id, int((entry.get("tempo_percent") or 100) - 100))
                    pending = pending_mods.get(remote_id)
                    if pending is not None:
                        want_key = int(pending.get("key", server_key))
                        want_tempo = int(pending.get("tempo", server_tempo))
                        # Once the server echoes the host value, the override is
                        # confirmed and can be dropped.
                        if int(server_key) == want_key and int(server_tempo) == want_tempo:
                            pending_mods.pop(remote_id, None)
                        server_key = want_key
                        server_tempo = want_tempo
                    entry["key"] = server_key
                    server_tempo = max(-30, min(30, int(server_tempo or 0)))
                    entry["tempo_percent"] = 100 + server_tempo
                    server_duration = duration_by_id.get(remote_id)
                    if normalize_karafun_duration_seconds(server_duration) is not None:
                        self._apply_verified_duration(
                            entry,
                            server_duration,
                            source=str(duration_source_by_id.get(remote_id) or "server_metadata"),
                        )
                    try:
                        entry["request_order"] = float(sort_by_id.get(remote_id, entry.get("request_order", remote_id)))
                    except Exception:
                        pass
        for singer in self.queue:
            singer_key = str(singer.get("name", "") or "").strip().lower()
            order = desired_by_singer.get(singer_key, [])
            if not order:
                continue
            incoming_meta = desired_meta_by_singer.get(singer_key, {})
            rank = {int(rid): idx for idx, rid in enumerate(order)}
            songs = singer.get("songs", [])
            if not isinstance(songs, list) or len(songs) < 2:
                continue
            before = [self._queue_entry_remote_request_id(entry) for entry in songs]
            local_host_ts = self._coerce_order_timestamp(singer.get("host_order_updated_at"))
            local_singer_ts = self._coerce_order_timestamp(singer.get("singer_order_updated_at"))
            local_revision = int(singer.get("order_revision") or 0)
            incoming_ts = self._incoming_order_timestamp(incoming_meta)
            incoming_revision = int((incoming_meta or {}).get("order_revision") or 0)
            incoming_source = str((incoming_meta or {}).get("last_order_source") or "server").strip().lower()
            local_remote_ids = [rid for rid in before if rid is not None]
            pending_item = getattr(self, "_pending_remote_order_syncs", {}).get(singer_key, {}) if isinstance(getattr(self, "_pending_remote_order_syncs", {}), dict) else {}
            pending_ids = [int(v) for v in (pending_item.get("request_ids") or []) if int(v) in desired_ids]
            force_pending = bool(pending_ids and set(pending_ids) == set(order) and order == pending_ids)
            allow_remote_order = True
            decision_reason = "applied"
            if force_pending:
                allow_remote_order = True
                decision_reason = "pending_host_order"
            elif local_host_ts > 0:
                if incoming_source == "singer" and incoming_ts > local_host_ts:
                    allow_remote_order = True
                    decision_reason = "newer_singer_order"
                elif incoming_source == "host" and incoming_ts >= local_host_ts:
                    allow_remote_order = True
                    decision_reason = "host_echo"
                elif incoming_revision > local_revision and incoming_ts >= max(local_host_ts, local_singer_ts):
                    allow_remote_order = True
                    decision_reason = "newer_revision"
                else:
                    allow_remote_order = False
                    decision_reason = "ignored_stale_remote_order"
            elif local_singer_ts > 0 and incoming_ts and incoming_ts < local_singer_ts:
                allow_remote_order = False
                decision_reason = "ignored_older_singer_order"
            if not allow_remote_order:
                _diag(
                    "[ORDER-CONFLICT] singer="
                    f"{singer.get('name','')!r} old_order={before} incoming_order={order} local_order={local_remote_ids} "
                    f"source={incoming_source} local_revision={local_revision} incoming_revision={incoming_revision} "
                    f"local_ts={max(local_host_ts, local_singer_ts)} incoming_ts={incoming_ts} decision=ignored"
                )
                continue
            # The server only knows about its own request rows, so an incoming
            # order may only permute those entries relative to each other.
            # Host-added local songs (no remote_request_id) and queued requests
            # the payload no longer lists keep their exact positions. A global
            # sort here would force every server-known song ahead of them and
            # snap back host reorders of mixed local/remote queues on every poll.
            ranked_positions = [
                pos for pos, entry in enumerate(songs)
                if rank.get(self._queue_entry_remote_request_id(entry)) is not None
            ]
            ranked_entries = sorted(
                (songs[pos] for pos in ranked_positions),
                key=lambda entry: rank[self._queue_entry_remote_request_id(entry)],
            )
            new_songs = list(songs)
            for pos, entry in zip(ranked_positions, ranked_entries):
                new_songs[pos] = entry
            singer["songs"] = new_songs
            after = [self._queue_entry_remote_request_id(entry) for entry in singer["songs"]]
            pinned_count = len(songs) - len(ranked_positions)
            if pinned_count:
                _diag(
                    "[QUEUE_SYNC_AUTHORITY] partial remote reorder singer="
                    f"{singer.get('name','')!r} ranked={len(ranked_positions)} pinned_local={pinned_count} "
                    f"incoming_order={order} before={before} after={after} decision={decision_reason}"
                )
            self._apply_order_meta_to_singer(singer, incoming_meta)
            # Only an order that actually moved is a conflict worth a line; the
            # no_change case fires for every singer on every reconcile.
            if before != after:
                _diag(
                    "[ORDER-CONFLICT] singer="
                    f"{singer.get('name','')!r} old_order={before} incoming_order={order} local_order={after} "
                    f"source={incoming_source} local_revision={local_revision} incoming_revision={incoming_revision} "
                    f"local_ts={max(local_host_ts, local_singer_ts)} incoming_ts={incoming_ts} decision={decision_reason}"
                )

        try:
            self._merge_duplicate_rotation_singers(reason="remote_reconcile_finish")
            self._cleanup_duplicate_singer_songs(reason="reconcile")
        except Exception as e:
            _diag(f"[QUEUE-DEDUP] reconcile pass failed: {e}")

        self._queue_display_batch_dirty = False
        if accepted_remote_add:
            # A server sync inserted requests (e.g. after a reconnect): the
            # rebuild must re-select the top rotation row, not the new rows.
            self._mark_server_queue_mutation(reason="reconcile_remote_requests")
        self._request_queue_display_refresh()
        try:
            self._refresh_header_status()
        except Exception:
            pass
        try:
            # Always debounce. The old else-branch wrote queue + singer history
            # + singer prefs synchronously on the GUI thread at the end of every
            # reconcile pass that accepted nothing -- which is most of them,
            # including the big one right after the relay connects at launch.
            # The debounced path snapshots on the UI thread and encodes/writes
            # on a worker, and shutdown still forces a final synchronous save.
            self._schedule_save_data(1500)
        except Exception:
            pass
        _perf_log_if_slow("remote_request_reconcile_total", (time.perf_counter() - _perf_t0) * 1000.0)

    def _find_song_for_request(self, artist: str, title: str) -> list:
        """Resolve a web request to library track(s) using the SAME index search
        the in-app library search uses (song_index.search_songs), instead of a
        separate strict exact-match path.

        The strict path (find_by_artist_title) misses anything whose library
        artist/title isn't an exact string match — e.g. a library title of
        "My Way (Remastered)" vs a request for "My Way". The in-app search finds
        those because it matches each query word as a substring of the song's
        search blob, so we route web requests through that same function and then
        pick the best-matching song (possibly several disc versions) for
        pick_by_disc_priority. Returns [] when nothing confidently matches.
        """
        artist = (artist or "").strip()
        title = (title or "").strip()

        # Fast precise path first (indexed exact / normalized artist+title).
        try:
            exact = song_index.find_by_artist_title(artist, title)
        except Exception:
            exact = []
        if exact:
            return exact

        query = (artist + " " + title).strip()
        if not query:
            return []
        # Same search the library box uses. fuzzy=False keeps a burst of remote
        # requests fast (the per-word substring match already absorbs the
        # formatting differences that the strict path chokes on).
        try:
            candidates = song_index.search_songs(query, limit=60, fuzzy=False)
        except Exception:
            candidates = []
        if not candidates:
            return []

        def _tokens(s: str) -> set:
            return set(re.findall(r"[a-z0-9]+", song_index.normalize_text(s or "")))

        req_tt = _tokens(title)
        req_at = _tokens(artist)

        def _score(c) -> int:
            ct = _tokens(str(c.get("title") or ""))
            ca = _tokens(str(c.get("artist") or ""))
            s = 0
            # Title is the strong signal: reward how many of the requested title
            # words appear in the candidate title (all present == best).
            if req_tt:
                if req_tt <= ct:
                    s += 100
                else:
                    s += int(80 * len(req_tt & ct) / len(req_tt))
            # Artist confirms it's the right performer.
            if req_at:
                if req_at <= ca:
                    s += 50
                else:
                    s += int(40 * len(req_at & ca) / len(req_at))
            return s

        best = max(candidates, key=_score)
        if _score(best) < 70:
            # Too little of the requested title/artist is actually present — don't
            # auto-queue a wrong song just because a stray word overlapped.
            return []

        # Return every candidate that is the SAME song as the best pick so
        # pick_by_disc_priority can still choose the preferred disc version.
        best_tk = song_index.fuzzy_match_key(str(best.get("title") or ""))
        same = [
            c for c in candidates
            if song_index.fuzzy_match_key(str(c.get("title") or "")) == best_tk
            and song_index.artist_names_match(
                str(c.get("artist") or ""), str(best.get("artist") or "")
            )
        ]
        return same or [best]

    def _remote_request_failure_payload(self, req: dict, reason: str, *, match_result: str = "pending") -> dict:
        payload = dict(req or {})
        payload["_ok"] = False
        payload["_failure_reason"] = str(reason or "unknown")
        payload["_match_result"] = str(match_result or "pending")
        return payload

    @staticmethod
    def _remote_request_is_karafun(req: dict | None) -> bool:
        """Recognize KaraFun requests across current and legacy server shapes."""
        req = req if isinstance(req, dict) else {}
        metadata = " ".join(
            str(req.get(key) or "").strip().casefold()
            for key in (
                "selected_source",
                "provider",
                "source_provider",
                "selected_version",
                "selected_brand",
                "brand",
                "version",
            )
        )
        path = str(req.get("path") or req.get("song_path") or "").strip().casefold()
        provider_track_id = str(
            req.get("provider_track_id") or req.get("selected_disc_id") or ""
        ).strip()
        return (
            "karafun" in metadata
            or path.startswith(("karafun_streaming:", "external_karafun:"))
            or provider_track_id.casefold().startswith("kf_")
        )

    def _prepare_remote_request_add_payload(self, req: dict) -> dict:
        """Resolve a remote request into a ready-to-insert queue payload.

        This is intentionally free of Qt widget work and queue mutation so it
        can run in a background thread while karaoke playback continues.
        """
        _perf_t0 = time.perf_counter()
        req = dict(req or {})
        singer = (req.get("singer", "") or "").strip()
        artist = (req.get("artist", "") or "").strip()
        title = (req.get("title", "") or "").strip()

        try:
            key = int(req.get("key", 0) or 0)
        except Exception:
            key = 0
        try:
            tempo_offset = int(req.get("tempo", 0) or 0)
        except Exception:
            tempo_offset = 0
        tempo_offset = max(-30, min(30, tempo_offset))
        tempo_percent = 100 + tempo_offset

        provider_track_id = str(req.get("provider_track_id") or req.get("selected_disc_id") or "").strip()
        provider_url = str(req.get("provider_url") or req.get("selected_url") or "").strip()
        is_karafun = self._remote_request_is_karafun(req)
        def _external_karafun_payload():
            raw_duration = next(
                (req.get(field) for field in ("duration", "duration_secs", "duration_seconds", "length_secs", "length")
                 if req.get(field) not in (None, "")),
                None,
            )
            track = self._build_karafun_streaming_track(
                artist=artist,
                title=title,
                provider_track_id=provider_track_id,
                provider_url=provider_url,
                duration=raw_duration,
                duration_estimated=req.get("duration_estimated"),
                duration_source=str(req.get("duration_source") or "server_metadata"),
            )
            try:
                request_id = int(req.get("request_id", req.get("id", 0)) or 0)
            except Exception:
                request_id = 0
            try:
                request_time = float(req.get("created_at") or req.get("requested_at") or req.get("request_time") or time.time())
            except Exception:
                request_time = time.time()
            return {
                "_ok": True,
                "request_id": request_id,
                "request_time": request_time,
                "singer": singer,
                "artist": artist,
                "title": title,
                "song_data": (track["path"], key, tempo_percent),
                "track": track,
                "remote_meta": req,
                "brand_info": {"effective": ["KARAFUN"], "source": "server_catalog"},
            }

        _sig = (singer.lower(), artist.lower(), title.lower())
        _failed_sigs = getattr(self, "_unmatched_request_sigs", None)
        if not is_karafun and isinstance(_failed_sigs, set) and _sig in _failed_sigs:
            return self._remote_request_failure_payload(req, "previous_auto_match_failure", match_result="previous_failure")

        _match_t0 = time.perf_counter()
        try:
            matches = self._find_song_for_request(artist, title)
        except Exception as e:
            logging.error(f"External request lookup failed for '{artist} - {title}': {e}")
            matches = [
                t for t in getattr(self, "tracks", [])
                if t.get("artist", "").lower() == artist.lower()
                and t.get("title", "").lower() == title.lower()
            ]
        _perf_log_if_slow("remote_request_match_lookup", (time.perf_counter() - _match_t0) * 1000.0)
        if is_karafun:
            # A KaraFun catalog badge describes where the singer found the
            # title, not how it must be played. Only physical, supported local
            # media counts as an alternative; stored external references do not.
            local_matches = []
            for candidate in matches:
                candidate_path = str(candidate.get("path") or "").strip()
                _base, candidate_ext = os.path.splitext(candidate_path)
                if candidate_ext.lower() in {".mp4", ".mp3", ".cdg", ".zip"} and os.path.isfile(candidate_path):
                    local_matches.append(candidate)
            if not local_matches and artist and title:
                return _external_karafun_payload()
            matches = local_matches
            # Prefer the host's local video when several physical versions
            # exist, while still using any other playable local version before
            # falling back to the KaraFun app.
            local_mp4_matches = [
                candidate for candidate in matches
                if str(candidate.get("path") or "").lower().endswith(".mp4")
            ]
            if local_mp4_matches:
                matches = local_mp4_matches
        if not matches:
            return self._remote_request_failure_payload(req, "no_local_library_match", match_result="no_match")

        host_priority = normalize_disc_priority(self.settings.get("disc_id_priority", ""), max_items=10)
        singer_brand_raw = request_preferred_disc_brand(req)
        singer_override = req.get("_singer_override")
        if not isinstance(singer_override, list):
            singer_override = self._singer_disc_priority_override(singer)
        runtime_info = effective_disc_priority(
            host_priority,
            singer_brand_raw=singer_brand_raw,
            singer_override=singer_override,
            max_items=10,
        )
        runtime_priority = runtime_info.get("effective", [])
        chosen = pick_by_disc_priority(matches, runtime_priority)
        chosen_path = str(chosen.get("path") or "")
        base, ext = os.path.splitext(chosen_path)
        ext = ext.lower()

        if ext in (".mp4", ".mp3"):
            song_data = (chosen_path, key, tempo_percent)
        elif ext == ".cdg":
            mp3_path = base + ".mp3"
            if not os.path.exists(mp3_path):
                mp3_path_upper = base + ".MP3"
                if os.path.exists(mp3_path_upper):
                    mp3_path = mp3_path_upper
                else:
                    return self._remote_request_failure_payload(req, "cdg_missing_mp3", match_result="matched")
            song_data = ((chosen_path, mp3_path), key, tempo_percent)
        elif ext == ".zip":
            if not self.is_mp3g_zip(chosen_path):
                return self._remote_request_failure_payload(req, "invalid_zip_format", match_result="matched")
            song_data = (chosen_path, key, tempo_percent)
        else:
            return self._remote_request_failure_payload(req, f"unsupported_format:{ext}", match_result="matched")

        try:
            request_id = int(req.get("request_id", req.get("id", 0)) or 0)
        except Exception:
            request_id = 0
        try:
            request_time = float(req.get("created_at") or req.get("requested_at") or req.get("request_time") or time.time())
        except Exception:
            request_time = time.time()

        payload = {
            "_ok": True,
            "request_id": request_id,
            "request_time": request_time,
            "singer": singer,
            "artist": artist,
            "title": title,
            "song_data": song_data,
            "track": chosen,
            "remote_meta": req,
            "brand_info": runtime_info,
        }
        _perf_log_if_slow("remote_request_prepare_payload", (time.perf_counter() - _perf_t0) * 1000.0)
        return payload

    def _apply_resolved_remote_add(self, payload: dict, *, allow_defer: bool = True) -> bool:
        if not isinstance(payload, dict):
            return False
        if not payload.get("_ok", False):
            req = payload
            reason = str(payload.get("_failure_reason") or "unknown")
            self._log_remote_request_diag(
                req,
                status="pending",
                match_result=str(payload.get("_match_result") or "pending"),
                queue_insert_result="not_attempted",
                failure_reason=reason,
            )
            if reason == "no_local_library_match":
                try:
                    _failed_sigs = getattr(self, "_unmatched_request_sigs", None)
                    if not isinstance(_failed_sigs, set):
                        _failed_sigs = set()
                        self._unmatched_request_sigs = _failed_sigs
                    _failed_sigs.add((
                        str(req.get("singer", "") or "").strip().lower(),
                        str(req.get("artist", "") or "").strip().lower(),
                        str(req.get("title", "") or "").strip().lower(),
                    ))
                except Exception:
                    pass
            self._record_remote_attention_request(req, reason)
            return False

        req = payload.get("remote_meta") or payload
        check_req = dict(req or {})
        track = payload.get("track")
        if isinstance(track, dict):
            check_req.setdefault("artist", track.get("artist"))
            check_req.setdefault("title", track.get("title"))
            for key in (
                "song_key",
                "stable_request_key",
                "selected_version",
                "selected_brand",
                "selected_disc_id",
                "selected_source",
                "disc_id",
                "discid",
                "songid",
                "song_id",
                "brand",
                "version",
                "source",
            ):
                if not check_req.get(key) and track.get(key):
                    check_req[key] = track.get(key)
        identity_sets = self._accepted_request_identity_sets()
        try:
            current_rid = int(check_req.get("request_id") or check_req.get("id") or payload.get("request_id") or 0)
            if current_rid > 0 and current_rid in identity_sets[0]:
                identity_sets = (set(identity_sets[0]) - {current_rid}, identity_sets[1], identity_sets[2])
        except Exception:
            pass
        if self._request_matches_accepted_queue_item(check_req, identity_sets=identity_sets):
            self._mark_waiting_for_add_duplicate_accepted(req, reason="remote_add")
            self._log_remote_request_diag(
                req,
                status="accepted",
                match_result="already_queued",
                queue_insert_result="duplicate_suppressed",
                failure_reason="",
            )
            return True
        ok_limit, limit_message = self._check_remote_request_song_limit(req)
        if not ok_limit:
            self._record_remote_limit_blocked_request(req, limit_message)
            return False

        if allow_defer and self._should_defer_remote_adds_now():
            ok = self._queue_deferred_remote_add(payload)
            if ok:
                self._log_remote_request_diag(
                    payload.get("remote_meta") or payload,
                    status="accepted",
                    match_result="matched",
                    queue_insert_result="deferred",
                    failure_reason="",
            )
            return ok

        req = payload.get("remote_meta") or {}
        ok = bool(self._add_song_to_queue(
            payload.get("singer", ""),
            payload.get("song_data"),
            track=payload.get("track"),
            remote_meta=req,
        ))
        self._log_remote_request_diag(
            req,
            status="accepted" if ok else "pending",
            match_result="matched",
            queue_insert_result="created" if ok else "failed",
            failure_reason="" if ok else "queue_insert_failed",
        )
        if ok:
            self._clear_remote_attention_request(req)
        else:
            self._record_remote_attention_request(req, "queue_insert_failed")
        return ok

    def _should_async_remote_request_intake(self) -> bool:
        try:
            app = QApplication.instance()
            if app is None:
                return False
            if not self._qt_object_is_initialized():
                return False
            return QThread.currentThread() == app.thread()
        except Exception:
            return False

    def _start_remote_request_intake_worker(self, req: dict) -> bool:
        try:
            rid = int((req or {}).get("request_id", (req or {}).get("id", 0)) or 0)
        except Exception:
            rid = 0
        if rid <= 0:
            return False
        inflight = getattr(self, "_remote_request_intake_inflight", None)
        if not isinstance(inflight, set):
            inflight = set()
            self._remote_request_intake_inflight = inflight
        if rid in inflight or rid in self._deferred_remote_request_ids():
            return True
        inflight.add(rid)
        snapshot = dict(req or {})
        try:
            snapshot["_singer_override"] = self._singer_disc_priority_override(str(snapshot.get("singer", "") or ""))
        except Exception:
            snapshot["_singer_override"] = []

        def worker():
            started = time.perf_counter()
            try:
                payload = self._prepare_remote_request_add_payload(snapshot)
            except Exception as e:
                logging.error(f"Remote request worker failed request_id={rid}: {e}")
                payload = self._remote_request_failure_payload(snapshot, f"worker_error:{e}")
            elapsed_ms = (time.perf_counter() - started) * 1000.0
            _perf_log_if_slow("remote_request_worker_total", elapsed_ms)
            self._run_on_ui_thread(lambda: self._finish_remote_request_intake_worker(rid, payload))

        threading.Thread(target=worker, daemon=True, name=f"remote-request-intake-{rid}").start()
        _diag(f"[REMOTE-INTAKE] scheduled background resolve request_id={rid}")
        return True

    def _finish_remote_request_intake_worker(self, request_id: int, payload: dict):
        try:
            inflight = getattr(self, "_remote_request_intake_inflight", set())
            if isinstance(inflight, set):
                inflight.discard(int(request_id))
        except Exception:
            pass
        ok = self._apply_resolved_remote_add(payload, allow_defer=True)
        if ok:
            try:
                self.ack_remote_requests([int(request_id)])
            except Exception:
                pass
            try:
                self._schedule_save_data(1500)
            except Exception:
                pass
        else:
            try:
                failed = getattr(self, "_unmatched_remote_request_ids", None)
                if isinstance(failed, set) and int(request_id) > 0:
                    failed.add(int(request_id))
            except Exception:
                pass
        self._update_deferred_remote_add_status()

    def process_external_request(self, req):
        import time as time_module
        start = time_module.time()
        _perf_t0 = time.perf_counter()

        def _finish(ok: bool):
            _perf_log_if_slow("remote_request_process_total", (time.perf_counter() - _perf_t0) * 1000.0)
            return ok

        req = req if isinstance(req, dict) else {}
        
        singer = (req.get("singer", "") or "").strip()
        artist = (req.get("artist", "") or "").strip()
        title  = (req.get("title", "") or "").strip()
        try:
            self._log_remote_request_diag(req, status="processing", match_result="pending", queue_insert_result="pending")
        except Exception:
            pass

        # Safe int parse for key (semitones)
        try:
            key = int(req.get("key", 0) or 0)
        except Exception:
            key = 0

        # Remote tempo arrives as a signed offset from normal speed.
        try:
            tempo_offset = int(req.get("tempo", 0) or 0)
        except Exception:
            tempo_offset = 0
        tempo_offset = max(-30, min(30, tempo_offset))
        tempo_percent = 100 + tempo_offset

        # Skip requests we've already tried and couldn't match in the library.
        # This dedups by content (singer/artist/title) so it stops the
        # log spam on EVERY poll regardless of which code path delivered the
        # request (the legacy delivery loop has no request_id to dedup on). The
        # set is cleared whenever the library is re-indexed, giving newly-added
        # songs a fresh attempt.
        # Catastrophic-config tripwire: a remote request arriving while the
        # library index is EMPTY means no request can ever match (unmounted
        # drive, failed scan, missing library locations). Shout once, loudly.
        # (State reads via __dict__: Qt raises RuntimeError, not
        # AttributeError, for unset attributes on partially built objects.)
        try:
            _state = object.__getattribute__(self, "__dict__")
            # ``tracks`` is a property backed by _tracks_state_data, so it no
            # longer appears in __dict__. "ready" is the equivalent of the old
            # "has the attribute been assigned at all" test: it is False while
            # the startup parse is still in flight, which is correctly not the
            # same as a confirmed-empty library.
            _tracks_state = _state.get("_tracks_state_data")
            _tracks_known = isinstance(_tracks_state, dict) and bool(_tracks_state.get("ready"))
            if _tracks_known and not _tracks_state.get("value"):
                if not bool(_state.get("_empty_library_request_warned", False)):
                    self._empty_library_request_warned = True
                    _diag(
                        "[REQUEST-ATTENTION] CRITICAL: remote request received but the karaoke "
                        "library index is EMPTY — no request can be matched. Check library "
                        "locations and that every library drive is mounted."
                    )
                    try:
                        self._set_processing_text(
                            "⚠ LIBRARY EMPTY — remote requests cannot be matched! "
                            "Check library locations / drives.",
                            auto_dismiss_ms=None,
                        )
                    except Exception:
                        pass
        except Exception:
            pass

        _sig = (singer.lower(), artist.lower(), title.lower())
        _failed_sigs = getattr(self, "_unmatched_request_sigs", None)
        if not isinstance(_failed_sigs, set):
            _failed_sigs = set()
            self._unmatched_request_sigs = _failed_sigs
        if _sig in _failed_sigs and not self._remote_request_is_karafun(req):
            self._log_remote_request_diag(
                req,
                status="pending",
                match_result="previous_failure",
                queue_insert_result="not_attempted",
                failure_reason="previous_auto_match_failure",
            )
            self._record_remote_attention_request(req, "previous_auto_match_failure")
            return _finish(False)

        ok_limit, limit_message = self._check_remote_request_song_limit(req)
        if not ok_limit:
            self._record_remote_limit_blocked_request(req, limit_message)
            return _finish(False)

        payload = self._prepare_remote_request_add_payload(req)
        if payload.get("_ok"):
            SingWSLogger.log_external_request(artist, title, singer, key)
            chosen = payload.get("track") or {}
            print(f"Matched: {chosen.get('display', chosen.get('path', ''))} for {singer}")
        ok = self._apply_resolved_remote_add(payload, allow_defer=True)
        return _finish(ok)
            
    def get_rotation_data(self):
        rotation = []
        number = 1
        for singer in self.queue:
            if not isinstance(singer, dict) or bool(singer.get("skipped", False)):
                continue

            songs = []
            for entry in singer.get("songs", []):
                # Handle both dict and tuple format
                if isinstance(entry, dict):
                    # Skip if song is skipped
                    if entry.get("skipped", False):
                        continue
                    song_info = entry.get("song_info")
                else:
                    # Old format
                    try:
                        song_info = entry[0]
                    except Exception:
                        song_info = entry
                
                if isinstance(song_info, (tuple, list)) and song_info:
                    song_path = song_info[0]
                else:
                    song_path = song_info
                if song_path:
                    artist, title = self._queue_entry_artist_title(entry)
                    if artist and title:
                        songs.append(f"{artist} • {title}")
                    elif title:
                        songs.append(title)
                    else:
                        songs.append(self.lookup_display_name(song_path, artist_title_only=True))

            if songs:
                display_name = self._queue_singer_display_for_entry(singer, self._first_active_entry_for_singer(singer))
                rotation.append({
                    "number": number,
                    "rotation_position": number,
                    "name": display_name or singer.get("name", ""),
                    "songs": songs,
                    "active": True,
                    "status": "active",
                })
                number += 1
        return {"rotation": rotation}

    def clear_all_selections(self):
        """Clear selections from both track list and queue display (and drop focus from inputs)."""
        try:
            self.results_list.clearSelection()
        except Exception:
            pass
        try:
            self.queue_display.clearSelection()
        except Exception:
            pass
        # Drop focus so the search box doesn't look "stuck" selected
        try:
            self.search_input.clearFocus()
        except Exception:
            pass

    def mousePressEvent(self, event):
        """Clear selections when clicking empty space in main window"""
        # Get the widget that was clicked
        widget_under_mouse = self.childAt(event.pos())
        
        # If clicking on empty space (not on a widget) or on the main window background
        if widget_under_mouse is None or widget_under_mouse == self:
            self.clear_all_selections()
            # Don't set focus to main window - just clear selections
            return
        
        # Call parent implementation
        super().mousePressEvent(event)

    def setup_clean_focus_behavior(self):
        """Unify selection visuals and remove macOS blue focus rings."""

        # Let views take focus normally (fixes the 'need to click twice' feeling),
        # but suppress macOS focus rectangles so nothing turns blue.
        try:
            self.results_list.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        except Exception:
            pass
        try:
            self.queue_display.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        except Exception:
            pass

        import sys
        if sys.platform == "darwin":
            try:
                self.results_list.setAttribute(Qt.WidgetAttribute.WA_MacShowFocusRect, False)
                self.queue_display.setAttribute(Qt.WidgetAttribute.WA_MacShowFocusRect, False)
            except Exception:
                pass
            # Allow first click to interact even when the window is inactive (no "activate then click again")
            try:
                self.results_list.setAttribute(Qt.WidgetAttribute.WA_MacAcceptsFirstMouse, True)
                self.queue_display.setAttribute(Qt.WidgetAttribute.WA_MacAcceptsFirstMouse, True)
            except Exception:
                pass
            # Also apply to the search box itself
            try:
                self.search_input.setAttribute(Qt.WidgetAttribute.WA_MacShowFocusRect, False)
                self.search_input.setAttribute(Qt.WidgetAttribute.WA_MacAcceptsFirstMouse, True)
            except Exception:
                pass

        # Custom gray "glow" focus for the search box (instead of macOS blue).
        try:
            self.search_input.setFocusPolicy(Qt.FocusPolicy.ClickFocus)
            self.search_input.setStyleSheet(line_edit_css())
        except Exception:
            pass

    def setup_selection_behavior(self):
        """Selection + focus behavior:
        - Selecting in one view clears selection in the other
        - Clicking either view drops focus from the search box so it doesn't look 'stuck'
        """

        # Any click in results/queue should drop focus from the search box
        try:
            self.results_list.itemClicked.connect(lambda *_: self.search_input.clearFocus())
        except Exception:
            pass
        try:
            self.queue_display.itemClicked.connect(lambda *_: self.search_input.clearFocus())
        except Exception:
            pass

    def post_rotation(self):
        # Only post rotation if network is configured
        if not self.is_network_configured():
            return  # Silently skip if network not configured

        # Off-thread for the same reason as the Network dialog: this is called
        # from queue changes on the GUI thread, and a CoreLocation fix can take
        # ten seconds.
        self.sync_session_location_async("post_rotation")

        import threading, json as _json

        def send():
            base_url = _network_normalize_base_url(self.settings.get("base_url", "https://beta.wskar.com"))
            tenant   = str(self.settings.get("user", self.settings.get("tenant", ""))).strip()

            # Upload via get_requests.php
            url = f"{base_url}/post_rotation.php"

            # Send rotation as JSON string in a form body (common PHP pattern)
            rot = (self.get_rotation_data() or {}).get("rotation", [])
            form = {
                "user":         tenant,
                "tenant":       tenant,  # back-compat if server still expects it
                "request_type": "rotation",
                "rotation":     _json.dumps(rot),
            }

            try:
                # First try request_type=rotation
                resp = requests.post(
                    url,
                    params={"user": tenant},
                    data=form,  # application/x-www-form-urlencoded
                    timeout=5,
                    headers={
                        "User-Agent": "SingWS/rotation-uploader",
                        "Accept": "application/json",
                        **({"X-API-Key": self.settings.get("api_key", "")} if self.settings.get("api_key") else {}),
                    },
                )

                # If server doesn’t like that key, try request_type=post_rotation
                if resp.status_code == 400 and "bad request_type" in (resp.text or "").lower():
                    form["request_type"] = "post_rotation"
                    resp = requests.post(
                        url,
                        data=form,
                        timeout=5,
                        headers={
                        "User-Agent": "SingWS/rotation-uploader",
                        "Accept": "application/json",
                        **({"X-API-Key": self.settings.get("api_key", "")} if self.settings.get("api_key") else {}),
                    },
                    )

                if resp.status_code != 200:
                    print(f"[rotation] HTTP {resp.status_code} posting to {url}: {resp.text[:200]}")
                else:
                    print(f"[rotation] public display updated ({len(rot)} singer(s))")

            except requests.Timeout:
                print(f"[rotation] timeout posting to {url}")
            except Exception as e:
                print("Rotation post failed:", e)

        threading.Thread(target=send, daemon=True).start()

